                    search: for (al.code_path) |dir| {
                        var pbuf: [512]u8 = undefined;
                        const path = std.fmt.bufPrint(&pbuf, "{s}/{s}.beam", .{ dir, name }) catch break :search;
                        const bytes = prim_file.readFile(al.io, al.root, self.gpa, path, autoload_read_max) catch |e| switch (e) {
                            error.OutOfMemory => return error.OutOfMemory,
                            else => continue :search, // Enoent/short/… → next code_path dir
                        };
