    /// E7.5 (Task 5): `erlang:hibernate/3` — DISCARD the calling process's call
    /// stack and RE-ENTER at `M:F/A` on the next message. The MFA-reentry
    /// homomorphism: after hibernate the process is observationally a FRESH entry
    /// at `M:F/A` (args in x0..x[A-1]) with its MAILBOX intact — never a resumed
    /// old frame. Bounded (the arg count is bounded by `resolveExport`). Sends NO
    /// signal (the SACRED M7 order is untouched — a local control-flow reset, the
    /// `run_on_load` precedent). An unresolvable MFA exits `undef` (BEAM-faithful).
    fn doHibernate(self: *Vm, pid: Pid, m: *ia.Machine, module: FinalTerms.Term, func: FinalTerms.Term, args: FinalTerms.Term) !void {
        const p = self.proc(pid) orelse return;
        // Resolve M:F/A against THIS process's own export index (hibernate re-enters
        // in-process, unlike spawn's child) and unpack the arg list into x0..x[A-1].
        // `resolveSpawnMFA` counts+validates the list and cross-heap-copies args;
        // here source and dest are the SAME machine, so the copy is an identity
        // within `m.ctx` (still a valid gcCopy — no aliasing hazard).
        const entry = self.resolveSpawnMFA(p, m, module, func, args);
        if (entry == null) {
            // BEAM-faithful: a hibernate to an unresolvable MFA kills the process.
            // e32-t1 fix: the EXIT reason for an unresolvable hibernate MFA is
            // the STRUCTURED `{undef, [{M,F,Args,[]}]}` (the BEAM undef contract
            // — the same head frame `raiseUndef` builds), not the bare atom
            // (fleet finding: `{'EXIT', P, {undef,_}}` never matched).
            const undef = FinalTerms.atom(&m.ctx, try self.atoms.intern("undef"));
            const frame = try FinalTerms.tuple(&m.ctx, &.{
                module, // already atom TERMS (the hibernate operands)
                func,
                args,
                FinalTerms.nil(&m.ctx),
            });
            const stack = try FinalTerms.cons(&m.ctx, frame, FinalTerms.nil(&m.ctx));
            const reason = try FinalTerms.tuple(&m.ctx, &.{ undef, stack });
            try self.terminate(pid, reason);
            return;
        }
        // DISCARD the call stack — the observable heart of hibernate. The mailbox
        // (`m.mbox`) is deliberately untouched: queued messages survive and the
        // re-entered `receive` re-scans them from the top (`recv_cursor = 0`).
        m.stack.clearRetainingCapacity();
        m.ystack.clearRetainingCapacity();
        m.catch_stack.clearRetainingCapacity();
        m.recv_cursor = 0;
        m.pc = entry.?;
        m.status = .running;
    }

    /// E7.5 (Task 5): one PARKED async system-task reply — the `{RequestId,
    /// Result}` message owed to a requester. Mirrors `ParkedSpawn`: the reply term
    /// lives in the requester's (`to`) heap, delivered on the next scheduler tick
    /// by `deliverParkedSysTask` over the stamped `signal` path.
    // sender-narrowing N1: vhash precomputed at park time (see `ParkedSpawn`).
    const ParkedSysTask = struct { to: Pid, reply: FinalTerms.Term, vhash: u64 };

    /// E7.5 (Task 5): `erts_internal:request_system_task/3,4` — enqueue an async
    /// system task and PARK its `{RequestId, Result}` reply to the requester (the
    /// E5.6 parked-reply protocol). The synchronous return is `true`. `op` folds to
    /// the Result: `garbage_collect` → `true` (zigvm's copying GC is denote-
    /// preserving), any other → `true` (the request was enqueued). The reply is
    /// built in the requester's heap; a dead requester drops it at delivery.
    fn doRequestSystemTask(self: *Vm, m: *ia.Machine, requester: FinalTerms.Term, reqid: FinalTerms.Term, op: ia.SysTaskOp) !FinalTerms.Term {
        const to = pidOfTerm(&m.ctx, requester) orelse return FinalTerms.atom(&m.ctx, m.bool_true);
        const rp = self.proc(to) orelse return FinalTerms.atom(&m.ctx, m.bool_true);
        // Result folds from the op. Every modeled op replies `true` (the task ran /
        // was enqueued); the op is retained so a future op with an observable
        // non-`true` Result slots in without changing the protocol.
        const result_true = op == .garbage_collect or op == .other;
        const reqid_copy = try FinalTerms.gcCopy(&rp.machine.ctx, &m.ctx, reqid);
        const res = FinalTerms.atom(&rp.machine.ctx, if (result_true) rp.machine.bool_true else rp.machine.bool_false);
        const reply = try FinalTerms.tuple(&rp.machine.ctx, &.{ reqid_copy, res });
        // gap-b-3: STAGE the park (was an inline write to the global `parked_systask`
        // from inside the `L_v`-held `interpret`) — applied to the global list at the
        // grant epilogue by `applyStagedParks` (the future `L_c` site).
        try self.staged_systask.append(self.gpa, .{ .to = to, .reply = reply, .vhash = FinalTerms.hashTerm(&rp.machine.ctx, reply) });
        self.staged_nonempty.store(true, .release); // N3: arm the epilogue's lock-free peek
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// E7.5 (Task 5): flush every parked system-task reply to its requester through
    /// the stamped `signal` path (the `deliverParkedSpawn` sibling; run at `grant`
    /// start so the reply lands one tick after the request — the async window).
    /// `from = to` (a self-directed system reply, a distinct pair from any user
    /// pair, so the SACRED M7 per-pair order is untouched). A requester that has
    /// since died drops the reply. Bounded (parked count). EXACTLY-ONCE: each entry
    /// signals once, then the queue is cleared.
    fn deliverParkedSysTask(self: *Vm) !void {
        // gap-b-5a: SNAPSHOT-then-signal. `L_c` guards ONLY the parked-list READ+DRAIN
        // (snapshot into scratch, clear the global list); it is RELEASED before the
        // `signal` loop, because `signal` now takes `L_c` itself for its wake decision
        // (push-based discovery) and the spinlock is non-reentrant. Snapshot-under-L_c
        // makes the drain exactly-once/exclusive (no peer re-drains the cleared list);
        // the subsequent `signal`s run `L_v→L_c→L_timer` per-entry, the sanctioned
        // order, no nesting.
        // sender-narrowing N1: the snapshot goes into a WORKER-LOCAL buffer —
        // the old Vm-shared `drain_scratch_systask` was serialized only by the
        // callers' `L_v`, an implicit coupling the top-of-loop narrowing removes.
        var scratch: std.ArrayList(ParkedSysTask) = .empty;
        defer scratch.deinit(self.gpa);
        self.l_c.lock();
        if (self.parked_systask.items.len == 0) {
            self.l_c.unlock();
            return;
        }
        scratch.appendSlice(self.gpa, self.parked_systask.items) catch |e| {
            self.l_c.unlock(); // parked list UNTOUCHED on OOM (cleared only after a successful snapshot)
            return e;
        };
        self.parked_systask.clearRetainingCapacity();
        self.l_c.unlock();
        for (scratch.items) |e| {
            if (self.proc(e.to) == null) continue; // requester gone: drop
            // N1: park-time vhash — delivery never hashes the requester's heap.
            try self.signalInner(e.to, e.to, .{ .message = e.reply }, e.vhash);
        }
    }

    // ---- E6.2 (Task 2): the LIVE timer engine (Stratum B over the timer_wheel
    // algebra). The wheel supplies ordering/at-most-once/cancel-then-fire; these
    // helpers carry the semantics and read the deterministic virtual clock.

    /// Find the LIVE timer with user TRef `key`, or null (fired/cancelled/unknown).
    /// e47-timer-meta-quadratic: O(1) via `timer_tref_idx`, DEFENSIVELY re-verified
    /// (`live` + `tref==key`) so even a stale map entry can only yield `null`, never
    /// a wrong timer — the map is a fast path, correctness never depends on it alone.
    fn timerByTref(self: *Vm, key: u64) ?usize {
        const idx = self.timer_tref_idx.get(key) orelse return null;
        if (idx < self.timer_meta.items.len) {
            const t = &self.timer_meta.items[idx];
            if (t.live and t.tref == key) return idx;
        }
        return null;
    }

    /// Remaining ms of a timer at `deadline` against the virtual clock (never < 0).
    fn timerRemaining(self: *Vm, deadline: u64) u64 {
        return if (deadline > self.vclock) deadline - self.vclock else 0;
    }

    /// Arm a receive-timeout entry for `pid` (`wait_timeout` finite). The DEADLINE
    /// is set once on the machine (`recv_timeout_deadline`) and PRESERVED across a
    /// non-matching intervening message, so a `receive after N` counts from first
    /// entry (BEAM semantics). A deadline already reached fires immediately.
    fn armReceiveTimer(self: *Vm, pid: Pid, ms: u64) !void {
        const p = self.proc(pid) orelse return;
        const m = &p.machine;
        const deadline = m.recv_timeout_deadline orelse (self.vclock + ms);
        m.recv_timeout_deadline = deadline;
        if (deadline <= self.vclock) {
            // Already due: wake with the timeout NOW (no wheel entry needed).
            m.timer_fired = true;
            m.status = .running;
            // gap-b-5a: push-based discovery — a timeout-wake makes pid runnable, so
            // enqueue it onto the ready inbox (an un-owned suspended receiver that
            // just went `.running`). Idempotent (dedups if already queued/owned).
            try self.markSchedulable(pid);
            return;
        }
        const idx = self.timer_meta.items.len;
        const wid = try self.timers.start(deadline, idx);
        try self.timer_meta.append(self.gpa, .{ .kind = .receive_timeout, .owner = pid, .deadline = deadline, .wheel_id = wid });
        p.recv_timer = idx;
    }

    /// Arm a `send_after`/`start_timer` entry; returns the fresh TRef term. `abs`
    /// treats `time` as an ABSOLUTE virtual-monotonic reading (deadline = time),
    /// else a RELATIVE delay (deadline = now + time). The message + dest terms live
    /// on the OWNER heap and are copied to the target heap at fire time.
    fn armBifTimer(self: *Vm, pid: Pid, kind: ia.TimerStartKind, time: FinalTerms.Term, dest: FinalTerms.Term, msg: FinalTerms.Term, abs: bool) !FinalTerms.Term {
        const p = self.proc(pid) orelse return FinalTerms.nil(&self.procs.items[pid].machine.ctx);
        const m = &p.machine;
        // gap-abs-timer-vclock (DIVERGENCE 729): an `{abs,true}` timer's `time` is an
        // ABSOLUTE `erlang:monotonic_time(millisecond)` reading (~1e9 ms uptime), but
        // the timer wheel runs in VCLOCK space (from 0) — so `deadline = time` armed
        // the abs timer ~1e9 ticks out, effectively NEVER reached (any relative
        // timer/receive-after always fired first). Verified by value: OTP fires
        // `start_timer(monotonic_time(ms)+80, _, _, [{abs,true}])`; zigvm never did.
        // FIX: translate the abs deadline into vclock space AT ARM TIME —
        // `vclock + (abs_ms - monotonic_now_ms)`, saturating (a past abs deadline →
        // clamp to `vclock`, fires on the next advance). The real monotonic clock is
        // NOT rebound, so system_time/timestamp stay truthful (FM-OBS-1). Relative
        // timers (the `else`) are unchanged. (NOTE: gen_statem's `{state_timeout,N}`
        // arms RELATIVE — a SEPARATE not-yet-fixed keystone; see the pass-2 plan Z1.)
        const deadline: u64 = if (abs) blk: {
            const now_ms: i128 = m.clock.monotonic(1000); // current monotonic ms (tps=1000)
            const abs_ms: i128 = @intCast(FinalTerms.smallValOf(time));
            const delta = abs_ms - now_ms;
            break :blk if (delta <= 0) self.vclock else self.vclock +| @as(u64, @intCast(delta));
        } else self.vclock + @as(u64, @intCast(FinalTerms.smallValOf(time)));
        const tref = self.next_tref;
        self.next_tref += 1;
        const idx = self.timer_meta.items.len;
        // A deadline in the past (abs with time <= now) fires on the next advance
        // only if >= wheel.now; clamp to now so it fires immediately rather than
        // being lost below the wheel cursor.
        const armed = if (deadline < self.vclock) self.vclock else deadline;
        const wid = try self.timers.start(armed, idx);
        try self.timer_meta.append(self.gpa, .{
            .kind = if (kind == .send_after) .send_after else .start_timer,
            .owner = pid,
            .dest = dest,
            .msg = msg,
            .tref = tref,
            .deadline = armed,
            .wheel_id = wid,
        });
        try self.timer_tref_idx.put(self.gpa, tref, idx); // e47: index the live BIF timer
        return try FinalTerms.ref(&m.ctx, refWordsForKey(tref));
    }

    /// `cancel_timer` — retire a live timer (wheel cancel + meta), returning the
    /// remaining ms; `false` if already fired/cancelled/unknown. `{info,false}` →
    /// `ok`; `{async,true}` → `ok` + a `{cancel_timer,TRef,Result}` message.
    fn doCancelTimer(self: *Vm, pid: Pid, tref_term: FinalTerms.Term, info: bool, is_async: bool) !FinalTerms.Term {
        const m = &self.procs.items[pid].machine;
        const okatom = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        const key = keyFromRefWords(FinalTerms.refWords(&m.ctx, tref_term));
        const result: FinalTerms.Term = blk: {
            if (self.timerByTref(key)) |idx| {
                const t = &self.timer_meta.items[idx];
                _ = self.timers.cancel(t.wheel_id);
                t.live = false;
                _ = self.timer_tref_idx.remove(t.tref); // e47: retire from the index
                if (self.proc(t.owner)) |op| {
                    if (op.recv_timer == idx) op.recv_timer = null;
                }
                break :blk FinalTerms.int(&m.ctx, @intCast(self.timerRemaining(t.deadline)));
            }
            break :blk FinalTerms.atom(&m.ctx, m.bool_false);
        };
        if (is_async) {
            // e47-a4 (the kill-restart livelock fix): {info,false} suppresses the
            // async reply ENTIRELY — erlang:cancel_timer/2 sends {cancel_timer,
            // TRef, Result} only when info is true (OTP semantics). gen_server's
            // server loop cancels with [{async,true},{info,false}]
            // (gen_server.erl:2353); an unconditional reply is an UNEXPECTED info
            // message its decode_msg wildcard answers with ANOTHER async cancel →
            // a self-feeding message livelock (99%-CPU spin in the supervisor
            // after a child kill+restart — perf-proven 69.7% in this fn).
            if (info) {
                const tup = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try self.atoms.intern("cancel_timer")), tref_term, result });
                try self.signal(pid, pid, .{ .message = tup });
                try self.drainSignals(pid);
            }
            return okatom;
        }
        return if (info) result else okatom;
    }

    /// `read_timer` — remaining ms of a live timer | `false`. `{async,true}` →
    /// `ok` + a `{read_timer,TRef,Result}` message.
    fn doReadTimer(self: *Vm, pid: Pid, tref_term: FinalTerms.Term, is_async: bool) !FinalTerms.Term {
        const m = &self.procs.items[pid].machine;
        const key = keyFromRefWords(FinalTerms.refWords(&m.ctx, tref_term));
        const result: FinalTerms.Term = if (self.timerByTref(key)) |idx|
            FinalTerms.int(&m.ctx, @intCast(self.timerRemaining(self.timer_meta.items[idx].deadline)))
        else
            FinalTerms.atom(&m.ctx, m.bool_false);
        if (is_async) {
            const tup = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try self.atoms.intern("read_timer")), tref_term, result });
            try self.signal(pid, pid, .{ .message = tup });
            try self.drainSignals(pid);
            return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        }
        return result;
    }

    /// True iff any timer is still pending (a live wheel entry). Pending timers are
    /// runnable WORK even when no process is currently `.running` (they wake procs).
    fn timersPending(self: *Vm) bool {
        for (self.timer_meta.items) |t| {
            if (t.live) return true;
        }
        return false;
    }

    /// Advance the virtual clock to the NEXT pending timer deadline and fire every
    /// entry now due, in wheel order (fire-order homomorphism). Deterministic: the
    /// clock jumps event-to-event, never a wall read. A single call fires ≥1 timer
    /// (strict progress — a bounded number of advances drains the wheel).
    fn advanceTimersToNext(self: *Vm) !void {
        var next: ?u64 = null;
        for (self.timer_meta.items) |t| {
            if (!t.live) continue;
            if (next == null or t.deadline < next.?) next = t.deadline;
        }
        const now = next orelse return;
        if (now > self.vclock) self.vclock = now;
        var fired: std.ArrayList(timer_wheel.Fired) = .empty;
        defer fired.deinit(self.gpa);
        try self.timers.advance(self.vclock, &fired);
        for (fired.items) |f| try self.fireTimer(@intCast(f.payload));
    }

    /// Fire one timer entry (already removed from the wheel). A `receive_timeout`
    /// sets the owner's `timer_fired` flag and wakes it (the re-entered
    /// `wait_timeout` takes the after-clause); a `send_after`/`start_timer`
    /// delivers its message (copying it OWNER→DEST) through the ordinary stamped
    /// signal path (per-pair order untouched). At-most-once: a non-live entry
    /// (cancelled after the fired list was built) is skipped.
    fn fireTimer(self: *Vm, idx: usize) !void {
        if (idx >= self.timer_meta.items.len) return;
        const t = &self.timer_meta.items[idx];
        if (!t.live) return;
        t.live = false;
        // e47-timer-meta-quadratic: retire the fired BIF timer from the tref→idx
        // index (receive timers are never indexed — guard by kind).
        if (t.kind == .send_after or t.kind == .start_timer) _ = self.timer_tref_idx.remove(t.tref);
        switch (t.kind) {
            .receive_timeout => {
                if (self.proc(t.owner)) |op| {
                    if (op.recv_timer == idx) op.recv_timer = null;
                    op.machine.timer_fired = true;
                    if (op.machine.status == .suspended and !op.io_gl) {
                        op.machine.status = .running;
                        // gap-b-5a: push-based discovery — the fired receive-timeout
                        // woke an un-owned suspended receiver; enqueue it (idempotent).
                        try self.markSchedulable(t.owner);
                    }
                }
            },
            .send_after, .start_timer => {
                const owner = self.proc(t.owner) orelse return; // owner gone: drop
                const to = self.resolveSendTarget(&owner.machine.ctx, t.dest) orelse return;
                const target = self.proc(to) orelse return;
                const payload: FinalTerms.Term = if (t.kind == .send_after)
                    try FinalTerms.gcCopy(&target.machine.ctx, &owner.machine.ctx, t.msg)
                else blk: {
                    // start_timer delivers {timeout, TRef, Msg} — built on DEST heap.
                    const tref_term = try FinalTerms.ref(&target.machine.ctx, refWordsForKey(t.tref));
                    const msg_copy = try FinalTerms.gcCopy(&target.machine.ctx, &owner.machine.ctx, t.msg);
                    const to_atom = FinalTerms.atom(&target.machine.ctx, try self.atoms.intern("timeout"));
                    break :blk try FinalTerms.tuple(&target.machine.ctx, &.{ to_atom, tref_term, msg_copy });
                };
                try self.signal(t.owner, to, .{ .message = payload });
            },
            .apoptosis_tick => {
                const apoptosis = @import("apoptosis.zig");
                try apoptosis.tick(self);
            },
        }
    }

    // ---- E5.4 (Task 4): the live os-port ENGINE (Stratum B over os_port's
    // Stratum-C seam). Each helper is TOTAL and BOUNDED: a bad/dead port yields
    // the `badarg` atom (never a crash), and every fd/child interaction is
    // fuel-bounded inside `os_port` (a wedged child is a failed law, not a hang).

    fn portOf(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term) ?*RunPort {
        if (!FinalTerms.repIsPort(&m.ctx, port_term)) return null;
        const number: u32 = @intCast(FinalTerms.portNumber(&m.ctx, port_term));
        for (self.ports.items) |*rp| {
            if (rp.number == number and rp.alive) return rp;
        }
        return null;
    }

    fn badargAtom(self: *Vm, m: *ia.Machine) FinalTerms.Term {
        return FinalTerms.atom(&m.ctx, self.atoms.intern("badarg") catch unreachable);
    }

    /// gap-erl-cli-args (DIVERGENCE 598): build a STRING (charlist) from bytes.
    fn stringTerm(m: *ia.Machine, bytes: []const u8) !FinalTerms.Term {
        var lst = FinalTerms.nil(&m.ctx);
        var i = bytes.len;
        while (i > 0) {
            i -= 1;
            lst = try FinalTerms.cons(&m.ctx, FinalTerms.int(&m.ctx, bytes[i]), lst);
        }
        return lst;
    }

    /// gap-erl-cli-args: `init:get_plain_arguments/0` — the parsed `-extra`/bare
    /// tokens as a list of strings (`[]` when no init args were provided). Built
    /// right-to-left so the list is in argv order.
    fn doInitPlainArgs(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        var lst = FinalTerms.nil(&m.ctx);
        if (self.init_args) |ia_view| {
            var i = ia_view.plain.len;
            while (i > 0) {
                i -= 1;
                const s = try stringTerm(m, ia_view.plain[i]);
                lst = try FinalTerms.cons(&m.ctx, s, lst);
            }
        }
        return lst;
    }

    /// gap-erl-cli-args: `init:get_argument/1` — `{ok, [[Value…]…]}` (one inner list
    /// per matching flag OCCURRENCE, values as strings) for a present, non-consumed
    /// user flag; else the atom `error` (missing OR a boot-consumed flag). `flag` is
    /// a flag atom.
    fn doInitGetArgument(self: *Vm, m: *ia.Machine, flag: FinalTerms.Term) !FinalTerms.Term {
        const err = FinalTerms.atom(&m.ctx, try self.atoms.intern("error"));
        const name = self.atoms.nameOf(FinalTerms.atomIdxOf(flag));
        if (Vm.initFlagConsumed(name)) return err; // init consumes it → not a user arg
        const ia_view = self.init_args orelse return err;
        // Collect matching occurrences (argv order). Each occurrence → a list of its
        // value strings. The result is [[occ0 vals],[occ1 vals],…]; error if none.
        var found = false;
        // Build the OUTER list right-to-left: walk occurrences in reverse.
        var outer = FinalTerms.nil(&m.ctx);
        var oi = ia_view.flags.len;
        while (oi > 0) {
            oi -= 1;
            const fl = ia_view.flags[oi];
            if (!std.mem.eql(u8, fl.name, name)) continue;
            found = true;
            var inner = FinalTerms.nil(&m.ctx);
            var vi = fl.values.len;
            while (vi > 0) {
                vi -= 1;
                const s = try stringTerm(m, fl.values[vi]);
                inner = try FinalTerms.cons(&m.ctx, s, inner);
            }
            outer = FinalTerms.cons(&m.ctx, inner, outer) catch return err;
        }
        if (!found) return err;
        const ok = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        return try FinalTerms.tuple(&m.ctx, &.{ ok, outer });
    }

    /// gap-hof-parse (DIVERGENCE 673): `init:get_arguments/0` — the whole parsed
    /// init argv as `[{Flag, [Value…]}…]` (one tuple per flag occurrence, argv
    /// order), `[]` when no CLI args. `erl_features:keywords/0` reads this to find
    /// `-enable-feature` flags; with none, its keyword set is the default, so
    /// `erl_scan`/`erl_parse` denote byte-EQ regardless of the flags returned.
    fn doInitGetArguments(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        const ia_view = self.init_args orelse return FinalTerms.nil(&m.ctx); // no args → []
        // Build the outer list right-to-left (walk flags in reverse) so it comes
        // out in argv order: [{name0,[vals0]}, {name1,[vals1]}, …].
        var outer = FinalTerms.nil(&m.ctx);
        var oi = ia_view.flags.len;
        while (oi > 0) {
            oi -= 1;
            const fl = ia_view.flags[oi];
            var inner = FinalTerms.nil(&m.ctx);
            var vi = fl.values.len;
            while (vi > 0) {
                vi -= 1;
                const s = try stringTerm(m, fl.values[vi]);
                inner = try FinalTerms.cons(&m.ctx, s, inner);
            }
            const flag_atom = FinalTerms.atom(&m.ctx, try self.atoms.intern(fl.name));
            const pair = try FinalTerms.tuple(&m.ctx, &.{ flag_atom, inner });
            outer = try FinalTerms.cons(&m.ctx, pair, outer);
        }
        return outer;
    }

    /// gap-open-port-exit-status (Slice B): the RunPort SLOT index for a port NUMBER
    /// (incl. a just-retired `alive=false` slot — distinct from `portOf`, which
    /// filters on `alive`). Used by the autonomous drain to re-locate the slot after
    /// any `self.ports` growth.
    fn portIndexOf(self: *Vm, number: u32) ?usize {
        for (self.ports.items, 0..) |rp, i| {
            if (rp.number == number) return i;
        }
        return null;
    }

    /// `erts_internal:open_port({spawn, Cmd}, Opts)` — spawn a live child running
    /// `Cmd` (a charlist/binary) behind the `os_port` seam; returns its Port term.
    /// Only `{spawn, Cmd}` is modeled (the corpus/echo shape); any other PortName
    /// or a spawn failure yields `badarg` (never a crash). Cmd is bounded to 512B.
    /// e50-halt: erlang:halt(Status) — terminate the node. A non-negative
    /// small int is the OS exit CODE (capped 0..255, erts truncation); the
    /// atom `abort` is an abnormal exit (code 134, SIGABRT convention); a
    /// STRING (charlist) is a crashdump SLOGAN → captured + exit code 1 (the
    /// erts halt(String) contract). The calling process (and every proc) is
    /// halted so the scheduler reaches quiescence and the driver returns the
    /// code. NO x0 write — the run ends.
    fn doNodeHalt(self: *Vm, pid: Pid, m: *ia.Machine, status: FinalTerms.Term) !void {
        if (FinalTerms.repIsSmall(status)) {
            const v = FinalTerms.smallValOf(status);
            self.halt_code = if (v < 0) 0 else if (v > 255) @intCast(@mod(v, 256)) else @intCast(v);
        } else if (FinalTerms.repIsAtom(status) and std.mem.eql(u8, self.atoms.nameOf(FinalTerms.atomIdxOf(status)), "abort")) {
            self.halt_code = 134;
        } else {
            // a charlist slogan → capture (best-effort latin1) + exit 1 (crashdump
            // slogan contract). `halt_1`/`halt_2` already VALIDATED the charlist, so a
            // codepoint > 255 (which iolistToBinary can't latin1-encode) is still a
            // VALID halt — set exit 1 with a best-effort/empty slogan and FALL THROUGH
            // to the termination loop. (The old early `return` on encode-failure SKIPPED
            // the halt entirely — `halt([256])` set the code but never stopped the node.)
            self.halt_slogan.clearRetainingCapacity();
            if (FinalTerms.iolistToBinary(&m.ctx, status)) |bin| {
                self.halt_slogan.appendSlice(self.gpa, FinalTerms.binBytes(&m.ctx, bin)) catch {};
            } else |_| {}
            self.halt_code = 1;
        }
        // terminate every live process so the run halts deterministically.
        _ = pid;
        for (self.procs.items, 0..) |p, i| {
            if (p.alive) {
                p.alive = false;
                p.machine.status = .halted;
            }
            _ = i;
        }
    }

    /// e50-tracing: erlang:trace(TargetPid, How, FlagList) — set/clear trace on
    /// the target (the CALLER becomes the tracer). Supported flags: send,
    /// 'receive' (the two message-event flags; `procs`/others parsed then
    /// ignored — a documented subset). Returns the matched count (1 for a live
    /// target, 0 otherwise) — the erlang:trace/3 contract.
    fn doTraceSet(self: *Vm, caller: Pid, m: *ia.Machine, target_t: FinalTerms.Term, how: bool, flags_t: FinalTerms.Term) !FinalTerms.Term {
        const target = pidOfTerm(&m.ctx, target_t) orelse return self.badargAtom(m);
        const tp = self.proc(target) orelse return FinalTerms.int(&m.ctx, 0);
        var want_send = false;
        var want_recv = false;
        var want_call = false; // gap-tracing-e7: the `call` flag
        var cur = flags_t;
        var guard: usize = 0;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons and guard < 64) : (guard += 1) {
            const h = FinalTerms.listHead(&m.ctx, cur);
            if (FinalTerms.repIsAtom(h)) {
                const n = self.atoms.nameOf(FinalTerms.atomIdxOf(h));
                if (std.mem.eql(u8, n, "send")) want_send = true;
                if (std.mem.eql(u8, n, "receive")) want_recv = true;
                if (std.mem.eql(u8, n, "call")) want_call = true;
            }
            cur = FinalTerms.listTail(&m.ctx, cur);
        }
        if (FinalTerms.kindOf(&m.ctx, cur) != .nil) return self.badargAtom(m);
        if (how) {
            tp.tracer = caller;
            if (want_send) tp.trace_send = true;
            if (want_recv) tp.trace_recv = true;
            // gap-tracing-e7: the `call` flag lives on the Machine (the dispatch
            // trap reads it there); the tracer pid stays on the Process.
            if (want_call) tp.machine.trace_call = true;
        } else {
            if (want_send) tp.trace_send = false;
            if (want_recv) tp.trace_recv = false;
            if (want_call) tp.machine.trace_call = false;
            if (!tp.trace_send and !tp.trace_recv and !tp.machine.trace_call) tp.tracer = null;
        }
        return FinalTerms.int(&m.ctx, 1);
    }

    /// e50-tracing: deliver a trace tuple to `tracer` in ITS heap (cross-heap
    /// copy), on the stamped signal path — never woken as work-bearing beyond
    /// the normal receive-wake. `extra` is the optional 5th element (the `To`
    /// pid of a send trace); pass `null` for a 4-tuple (a 'receive').
    fn emitTrace(self: *Vm, tracer: Pid, subject: Pid, tag: []const u8, payload_ctx: *FinalTerms.Ctx, payload: FinalTerms.Term, extra: ?FinalTerms.Term, extra_ctx: ?*FinalTerms.Ctx) !void {
        const tp = self.proc(tracer) orelse return;
        const tc = &tp.machine.ctx;
        const trace_a = FinalTerms.atom(tc, try self.atoms.intern("trace"));
        const subj = try FinalTerms.pid(tc, subject, 0);
        const tag_a = FinalTerms.atom(tc, try self.atoms.intern(tag));
        const pl = try FinalTerms.gcCopy(tc, payload_ctx, payload);
        const msg = if (extra) |ex| blk: {
            const exc = try FinalTerms.gcCopy(tc, extra_ctx.?, ex);
            break :blk try FinalTerms.tuple(tc, &.{ trace_a, subj, tag_a, pl, exc });
        } else try FinalTerms.tuple(tc, &.{ trace_a, subj, tag_a, pl });
        // deliver directly to the tracer's mailbox via a self-stamped signal.
        try self.signalTrace(tracer, msg);
    }

    /// e50-tracing: enqueue a pre-built trace message to `to`'s mailbox on the
    /// stamped path WITHOUT re-emitting a trace (avoids trace-of-trace loops).
    fn signalTrace(self: *Vm, to: Pid, msg: FinalTerms.Term) !void {
        const target = self.proc(to) orelse return;
        const stamp = self.next_stamp.fetchAdd(1, .monotonic);
        // S-epoch Option B: `L_sigq`-guarded append (see `signal`) — released
        // before the `L_c` wake section below (leaf, never held across a lock).
        {
            target.sigq_lock.lock();
            defer target.sigq_lock.unlock();
            try target.sigq.append(self.gpa, .{ .from = to, .stamp = stamp, .sig = .{ .message = msg } });
        }
        // N9-Q1: the same Dekker wake as `signal` (SC-N9-1).
        self.pending_wake_a.items[to].store(true, .seq_cst);
        if (self.owned.items[to].load(.seq_cst) == NO_OWNER) {
            if (self.pending_wake_a.items[to].swap(false, .seq_cst)) {
                self.applyWake(target);
                try self.enqueueDirect(to);
            }
        }
    }

    /// gap-tracing-e7: commit an `erlang:trace_pattern` breakpoint to the GLOBAL
    /// table (enable = insert-if-absent; clear = remove every matching predicate),
    /// then return the matched-function `count` the BIF computed. Idempotent on
    /// re-enable (a duplicate predicate is not appended) — the set semantics the
    /// call-event gate relies on.
    /// gap-tracing-trace-info (DIVERGENCE 601): `erlang:trace_info({M,F,A}, Item)` —
    /// query the GLOBAL call-trace pattern table. `{traced, global}` iff the concrete
    /// MFA matches an enabled pattern (`callPatternMatches`), else `{traced, false}`;
    /// `{match_spec|meta|call_count|call_time, false}` (bodies/meta/counters are the
    /// documented remainder — never modeled, so honestly `false`, never a wrong value);
    /// `{all, false}` for an untraced fn, the proplist when traced. A malformed MFA
    /// (non-atom M/F, non-int A) or unknown Item → badarg (raised by the caller arm).
    fn doTraceInfoMfa(self: *Vm, m: *ia.Machine, module_t: FinalTerms.Term, func_t: FinalTerms.Term, arity_t: FinalTerms.Term, item_t: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(module_t) or !FinalTerms.repIsAtom(func_t) or !FinalTerms.repIsSmall(arity_t) or !FinalTerms.repIsAtom(item_t))
            return error.Badarg;
        const arity_v = FinalTerms.smallValOf(arity_t);
        if (arity_v < 0 or arity_v > 255) return error.Badarg;
        const traced = self.callPatternMatches(FinalTerms.atomIdxOf(module_t), FinalTerms.atomIdxOf(func_t), @intCast(arity_v));
        const false_atom = FinalTerms.atom(&m.ctx, m.bool_false);
        const global_atom = FinalTerms.atom(&m.ctx, try self.atoms.intern("global"));
        const item = self.atoms.nameOf(FinalTerms.atomIdxOf(item_t));
        const pairTerm = struct {
            fn p(mm: *ia.Machine, key: FinalTerms.Term, val: FinalTerms.Term) !FinalTerms.Term {
                return FinalTerms.tuple(&mm.ctx, &.{ key, val });
            }
        }.p;
        if (std.mem.eql(u8, item, "traced"))
            return pairTerm(m, item_t, if (traced) global_atom else false_atom);
        // match_spec: an ENABLED global trace has the EMPTY match spec `[]` (trace all,
        // no filter — bodies are the documented remainder); an untraced fn → `false`.
        if (std.mem.eql(u8, item, "match_spec"))
            return pairTerm(m, item_t, if (traced) FinalTerms.nil(&m.ctx) else false_atom);
        // meta / meta_match_spec / call_count / call_time / call_memory are the
        // non-modeled tail → `false` (honest, never a wrong value), traced or not.
        if (std.mem.eql(u8, item, "meta") or std.mem.eql(u8, item, "meta_match_spec") or
            std.mem.eql(u8, item, "call_count") or std.mem.eql(u8, item, "call_time") or
            std.mem.eql(u8, item, "call_memory"))
            return pairTerm(m, item_t, false_atom);
        if (std.mem.eql(u8, item, "all")) {
            if (!traced) return pairTerm(m, item_t, false_atom);
            // the FULL traced proplist in erts order: traced, match_spec, meta,
            // meta_match_spec, call_memory, call_time, call_count.
            const ci = struct {
                fn kv(vm: *Vm, mm: *ia.Machine, k: []const u8, val: FinalTerms.Term) !FinalTerms.Term {
                    return FinalTerms.tuple(&mm.ctx, &.{ FinalTerms.atom(&mm.ctx, try vm.atoms.intern(k)), val });
                }
            };
            var lst = FinalTerms.nil(&m.ctx);
            lst = try FinalTerms.cons(&m.ctx, try ci.kv(self, m, "call_count", false_atom), lst);
            lst = try FinalTerms.cons(&m.ctx, try ci.kv(self, m, "call_time", false_atom), lst);
            lst = try FinalTerms.cons(&m.ctx, try ci.kv(self, m, "call_memory", false_atom), lst);
            lst = try FinalTerms.cons(&m.ctx, try ci.kv(self, m, "meta_match_spec", false_atom), lst);
            lst = try FinalTerms.cons(&m.ctx, try ci.kv(self, m, "meta", false_atom), lst);
            lst = try FinalTerms.cons(&m.ctx, try ci.kv(self, m, "match_spec", FinalTerms.nil(&m.ctx)), lst);
            lst = try FinalTerms.cons(&m.ctx, try ci.kv(self, m, "traced", global_atom), lst);
            return pairTerm(m, item_t, lst);
        }
        return error.Badarg; // unknown item
    }

    /// gap-tracing-trace-info (DIVERGENCE 601): `erlang:trace_delivered/1` — mint a
    /// fresh reference, deliver `{trace_delivered, Tracee, Ref}` to the caller NOW
    /// (single-scheduler: delivery is synchronous), return the Ref. `Tracee` is a pid
    /// or `all`/`new`/`new_processes`/`new_ports` (accepted verbatim as the message's
    /// 2nd element, matching OTP's echo of the argument).
    fn doTraceDelivered(self: *Vm, pid: Pid, m: *ia.Machine, tracee: FinalTerms.Term) !FinalTerms.Term {
        const key = self.next_ref;
        self.next_ref += 1;
        const ref = try FinalTerms.ref(&m.ctx, refWordsForKey(key));
        const tag = FinalTerms.atom(&m.ctx, try self.atoms.intern("trace_delivered"));
        const msg = try FinalTerms.tuple(&m.ctx, &.{ tag, tracee, ref });
        try self.signal(pid, m.self_pid, .{ .message = msg });
        try self.drainSignals(m.self_pid);
        return ref;
    }

    fn doTracePattern(self: *Vm, m: *ia.Machine, module: ?ta.AtomIdx, func: ?ta.AtomIdx, arity: ?u32, enable: bool, count: i64, spec_ms: ?FinalTerms.Term) !FinalTerms.Term {
        if (enable) {
            // gap-tracing-firepath: deep-copy the installed spec (caller heap →
            // the stable region) so it survives the caller's GC; `null` when the
            // spec is true/[]/beyond-subset (bare delivery).
            const stored: ?FinalTerms.Term = if (spec_ms) |s|
                try FinalTerms.gcCopy(&self.trace_spec_region, &m.ctx, s)
            else
                null;
            for (self.trace_patterns.items) |*tp| {
                if (tp.module == module and tp.func == func and tp.arity == arity) {
                    tp.spec = stored; // re-install replaces the spec (matching erts)
                    return FinalTerms.int(&m.ctx, count);
                }
            }
            try self.trace_patterns.append(self.gpa, .{ .module = module, .func = func, .arity = arity, .spec = stored });
        } else {
            var i: usize = 0;
            while (i < self.trace_patterns.items.len) {
                const tp = self.trace_patterns.items[i];
                if (tp.module == module and tp.func == func and tp.arity == arity) {
                    _ = self.trace_patterns.orderedRemove(i);
                } else i += 1;
            }
        }
        return FinalTerms.int(&m.ctx, count);
    }

    /// gap-tracing-e7: is `module:func/arity` covered by an ENABLED trace_pattern
    /// breakpoint? A `null` predicate component is the `'_'` wildcard.
    fn callPatternMatches(self: *Vm, module: ta.AtomIdx, func: ta.AtomIdx, arity: u8) bool {
        for (self.trace_patterns.items) |p| {
            if (p.module) |mm| {
                if (mm != module) continue;
            }
            if (p.func) |ff| {
                if (ff != func) continue;
            }
            if (p.arity) |pa| {
                if (pa != @as(u32, arity)) continue;
            }
            return true;
        }
        return false;
    }

    /// gap-tracing-e7: deliver `{trace, Pid, call, {M, F, Args}}` to the process's
    /// tracer — but only when the process still carries the `call` flag AND the
    /// dispatched MFA is covered by an enabled trace_pattern breakpoint. The payload
    /// `{M,F,Args}` is built on the SUBJECT's heap and cross-heap-copied into the
    /// tracer by `emitTrace` (the same path the send/receive events use).
    fn deliverCallTrace(self: *Vm, pid: Pid, p: *Process, m: *ia.Machine, module: ta.AtomIdx, func: ta.AtomIdx, arity: u8, args: FinalTerms.Term) !void {
        if (!m.trace_call) return;
        const tr = p.tracer orelse return;
        const pat = self.callPattern(module, func, arity) orelse return;
        // gap-tracing-firepath: run the installed match spec against the call's
        // ARGUMENT LIST — head/guard SUPPRESS a non-match, `{message,E}` shapes
        // the delivered message (5-tuple), `{message,false}` SUPPRESSES.
        var extra: ?FinalTerms.Term = null;
        if (pat.spec) |spec_region| switch (self.runTraceSpec(m, spec_region, args)) {
            .suppress => return,
            .bare => {},
            .message => |msgt| extra = msgt,
        };
        const ma = FinalTerms.atom(&m.ctx, module);
        const fa = FinalTerms.atom(&m.ctx, func);
        const mfa = try FinalTerms.tuple(&m.ctx, &.{ ma, fa, args });
        try self.emitTrace(tr, pid, "call", &m.ctx, mfa, extra, if (extra != null) &m.ctx else null);
    }

    const TraceOutcome = union(enum) { suppress, bare, message: FinalTerms.Term };

    /// Copy the stored trace spec into the delivery heap (`m.ctx`), compile + run
    /// it against the call's argument list, and classify the outcome:
    ///   head/guard no match  → suppress   (no trace message)
    ///   body result `false`  → suppress   ({message,false})
    ///   body result `true`   → bare       (the plain {trace,_,call,MFA} 4-tuple)
    ///   otherwise            → message T  (append T → the 5-tuple)
    /// A malformed/OOM path degrades to `.bare` (never a wrong message or a hang).
    fn runTraceSpec(self: *Vm, m: *ia.Machine, spec_region: FinalTerms.Term, args: FinalTerms.Term) TraceOutcome {
        var arena = std.heap.ArenaAllocator.init(self.gpa);
        defer arena.deinit();
        const spec_local = FinalTerms.gcCopy(&m.ctx, &self.trace_spec_region, spec_region) catch return .bare;
        const clauses = msc.compileTrace(&m.ctx, arena.allocator(), spec_local) catch return .bare;
        const tr = (msc.runTrace(&m.ctx, clauses, args) catch return .bare) orelse return .suppress;
        if (FinalTerms.repIsAtom(tr.result)) {
            const idx = FinalTerms.atomIdxOf(tr.result);
            if (idx == m.bool_true) return .bare;
            if (idx == m.bool_false) return .suppress;
        }
        return .{ .message = tr.result };
    }

    /// The FIRST enabled trace pattern whose (module,func,arity) predicate matches,
    /// or null. (`callPatternMatches` is the boolean form kept for `trace_info`.)
    fn callPattern(self: *Vm, module: ta.AtomIdx, func: ta.AtomIdx, arity: u8) ?TracePattern {
        for (self.trace_patterns.items) |p| {
            if (p.module) |mm| {
                if (mm != module) continue;
            }
            if (p.func) |ff| {
                if (ff != func) continue;
            }
            if (p.arity) |pa| {
                if (pa != @as(u32, arity)) continue;
            }
            return p;
        }
        return null;
    }

    /// e49-wire-real-file-io: map a prim_file error to the file:'s {error,Posix}
    /// reason atom (the file.erl contract — the POSIX name, lowercased).
    fn fileErrTuple(self: *Vm, m: *ia.Machine, e: anyerror) !FinalTerms.Term {
        const name = switch (e) {
            error.Enoent => "enoent",
            error.Eacces => "eacces",
            error.Eisdir => "eisdir",
            error.Enotdir => "enotdir",
            error.Eexist => "eexist",
            error.Ebadf => "ebadf",
            error.NameTooLong => "enametoolong",
            error.TooLarge => "enomem",
            else => "einval",
        };
        const err_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("error"));
        const reason = FinalTerms.atom(&m.ctx, try self.atoms.intern(name));
        return FinalTerms.tuple(&m.ctx, &.{ err_a, reason });
    }

    /// file:read_file(Path) → {ok, Binary} | {error, Reason}. No fs seam
    /// configured ⇒ {error, enoent} (the closed-world default — nothing on disk).
    fn doFileRead(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        const pbin = FinalTerms.iolistToBinary(&m.ctx, path_t) catch return self.fileErrTuple(m, error.Einval);
        const pbytes = FinalTerms.binBytes(&m.ctx, pbin);
        if (pbytes.len == 0 or pbytes.len >= 4096) return self.fileErrTuple(m, error.Einval);
        var pbuf: [4096]u8 = undefined;
        @memcpy(pbuf[0..pbytes.len], pbytes);
        const bytes = prim_file.readFile(fs.io, fs.root, self.gpa, pbuf[0..pbytes.len], file_read_max) catch |e| return self.fileErrTuple(m, e);
        defer self.gpa.free(bytes);
        const ok_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        const bin = FinalTerms.binary(&m.ctx, bytes) catch return error.OutOfMemory;
        return FinalTerms.tuple(&m.ctx, &.{ ok_a, bin });
    }

    /// file:write_file(Path, Data) → ok | {error, Reason}. Data is an iodata.
    fn doFileWrite(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term, data_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Eacces);
        const pbin = FinalTerms.iolistToBinary(&m.ctx, path_t) catch return self.fileErrTuple(m, error.Einval);
        const pbytes = FinalTerms.binBytes(&m.ctx, pbin);
        if (pbytes.len == 0 or pbytes.len >= 4096) return self.fileErrTuple(m, error.Einval);
        const dbin = FinalTerms.iolistToBinary(&m.ctx, data_t) catch return self.fileErrTuple(m, error.Einval);
        const dbytes = FinalTerms.binBytes(&m.ctx, dbin);
        var pbuf: [4096]u8 = undefined;
        @memcpy(pbuf[0..pbytes.len], pbytes);
        prim_file.writeFile(fs.io, fs.root, pbuf[0..pbytes.len], dbytes) catch |e| return self.fileErrTuple(m, e);
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    /// gap-real-file-io: helper — resolve a path term (iodata) into a bounded
    /// NUL-free byte buffer, or an {error,einval} tuple on a bad/oversize path.
    fn filePathBuf(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term, buf: []u8) !?[]const u8 {
        const pbin = FinalTerms.iolistToBinary(&m.ctx, path_t) catch return null;
        const pbytes = FinalTerms.binBytes(&m.ctx, pbin);
        if (pbytes.len == 0 or pbytes.len >= buf.len) return null;
        @memcpy(buf[0..pbytes.len], pbytes);
        _ = self;
        return buf[0..pbytes.len];
    }

    /// gap-real-file-io: file:list_dir(Path) → {ok,[Name]} | {error,Reason}.
    /// Each Name is a charlist (file.erl's default, non-`raw` form). Set-EQ to
    /// the real directory entries via the proven prim_file.listDir seam.
    fn doFileListDir(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        var pbuf: [4096]u8 = undefined;
        const path = (try self.filePathBuf(m, path_t, &pbuf)) orelse return self.fileErrTuple(m, error.Einval);
        const names = prim_file.listDir(fs.io, fs.root, self.gpa, path) catch |e| return self.fileErrTuple(m, e);
        defer {
            for (names) |n| self.gpa.free(n);
            self.gpa.free(names);
        }
        // Build [Name] where each Name is a charlist. Reverse order so the list
        // reads in the seam's sorted order (listDir sorts ascending).
        var lst = FinalTerms.nil(&m.ctx);
        var i = names.len;
        while (i > 0) {
            i -= 1;
            const nm = names[i];
            var chars = FinalTerms.nil(&m.ctx);
            var j = nm.len;
            while (j > 0) {
                j -= 1;
                chars = try FinalTerms.cons(&m.ctx, FinalTerms.int(&m.ctx, nm[j]), chars);
            }
            lst = try FinalTerms.cons(&m.ctx, chars, lst);
        }
        const ok_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        return FinalTerms.tuple(&m.ctx, &.{ ok_a, lst });
    }

    /// gap-real-file-io: file:read_file_info(Path) → {ok,#file_info{}} |
    /// {error,Reason}. The record is the 14-field `file_info` tuple; size/type/
    /// access are byte-EQ vs the oracle, the POSIX time fields are seconds (the
    /// `{time,posix}` form). Mode/device/uid/gid the seam cannot honestly project
    /// are emitted as 0 (a documented residual, not a fabricated value).
    const TimeMode = enum { local, posix, universal };

    fn doFileReadFileInfo(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term, time_mode: TimeMode, follow: bool) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        var pbuf: [4096]u8 = undefined;
        const path = (try self.filePathBuf(m, path_t, &pbuf)) orelse return self.fileErrTuple(m, error.Einval);
        // follow=true → read_file_info (stat, follows symlinks); false → read_link_info (lstat).
        const fi = (if (follow) prim_file.readFileInfo(fs.io, fs.root, path) else prim_file.readLinkInfo(fs.io, fs.root, path)) catch |e| return self.fileErrTuple(m, e);
        const type_name = switch (fi.type) {
            .device => "device",
            .directory => "directory",
            .regular => "regular",
            .symlink => "symlink",
            .other => "other",
        };
        const access_name = switch (fi.access) {
            .none => "none",
            .read => "read",
            .write => "write",
            .read_write => "read_write",
        };
        const rec_tag = FinalTerms.atom(&m.ctx, try self.atoms.intern("file_info"));
        const type_a = FinalTerms.atom(&m.ctx, try self.atoms.intern(type_name));
        const access_a = FinalTerms.atom(&m.ctx, try self.atoms.intern(access_name));
        // #file_info{size,type,access,atime,mtime,ctime,mode,links,
        //            major_device,minor_device,inode,uid,gid} → a 14-tuple.
        // gap-file-info-stat-tz: mode/major_device/minor_device/uid/gid now carry the
        // REAL statx values (were 0); atime/mtime/ctime are the DEFAULT file:read_file_info/1
        // LOCAL-datetime tuples `{{Y,Mo,D},{H,Mi,S}}` = universaltime(secs + tzOffset),
        // where tzOffset comes from the host TZif (`prim_file.tzOffsetAt`). (`/2` with
        // `[{time,posix}]` — raw seconds — is a NARROWED residual: only `/1` is wired.)
        const dt = struct {
            fn go(mm: *ia.Machine, secs: i64, mode: TimeMode) !FinalTerms.Term {
                switch (mode) {
                    .posix => return FinalTerms.intFromI128(&mm.ctx, secs), // raw seconds
                    .universal => return conv.posixtime_to_universaltime_1(mm, &.{FinalTerms.int(&mm.ctx, secs)}), // UTC tuple
                    .local => { // local-datetime tuple = universaltime(secs + host TZ offset)
                        const local = secs + prim_file.tzOffsetAt(secs);
                        return conv.posixtime_to_universaltime_1(mm, &.{FinalTerms.int(&mm.ctx, local)});
                    },
                }
            }
        }.go;
        const rec = try FinalTerms.tuple(&m.ctx, &.{
            rec_tag,
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.size)),
            type_a,
            access_a,
            try dt(m, fi.atime_s, time_mode),
            try dt(m, fi.mtime_s, time_mode),
            try dt(m, fi.ctime_s, time_mode),
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.mode)),
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.links)),
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.major_device)),
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.minor_device)),
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.inode)),
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.uid)),
            try FinalTerms.intFromI128(&m.ctx, @intCast(fi.gid)),
        });
        const ok_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        return FinalTerms.tuple(&m.ctx, &.{ ok_a, rec });
    }

    // ── gap-file-handle-io: the live file:open/2 handle API over prim_file ──

    /// Map an `IoDevice` term `{file_descriptor, prim_file, N}` back to its live
    /// RunFd. Returns null for a malformed term OR a CLOSED handle (alive=false) —
    /// both render as `{error, einval}`, matching erts' pread/pwrite-after-close.
    fn fdOf(self: *Vm, m: *ia.Machine, dev: FinalTerms.Term) ?*RunFd {
        if (FinalTerms.kindOf(&m.ctx, dev) != .tuple or FinalTerms.tupleArity(&m.ctx, dev) != 3) return null;
        const tag = FinalTerms.tupleElem(&m.ctx, dev, 0);
        if (!FinalTerms.repIsAtom(tag) or !std.mem.eql(u8, self.atoms.nameOf(FinalTerms.atomIdxOf(tag)), "file_descriptor")) return null;
        const nterm = FinalTerms.tupleElem(&m.ctx, dev, 2);
        if (!FinalTerms.repIsSmall(nterm)) return null;
        const n: u32 = @intCast(FinalTerms.smallValOf(nterm) & 0xffff_ffff);
        for (self.fds.items) |*rf| {
            if (rf.number == n and rf.alive) return rf;
        }
        return null;
    }

    /// Parse a `file:open/2` Modes list into a prim_file.Mode. read+write →
    /// read_write; append → append; write-only → write; else read. `raw`/`binary`
    /// and other tuning atoms are accepted-and-ignored (zigvm's IoDevice is always
    /// the raw positioned-handle model). A non-list Modes → null (→ badarg).
    fn parseFileModes(self: *Vm, m: *ia.Machine, modes: FinalTerms.Term) ?prim_file.Mode {
        var has_read = false;
        var has_write = false;
        var has_append = false;
        var cur = modes;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons) {
            const h = FinalTerms.listHead(&m.ctx, cur);
            if (FinalTerms.repIsAtom(h)) {
                const nm = self.atoms.nameOf(FinalTerms.atomIdxOf(h));
                if (std.mem.eql(u8, nm, "read")) has_read = true;
                if (std.mem.eql(u8, nm, "write")) has_write = true;
                if (std.mem.eql(u8, nm, "append")) has_append = true;
            }
            cur = FinalTerms.listTail(&m.ctx, cur);
        }
        if (FinalTerms.kindOf(&m.ctx, cur) != .nil) return null; // improper list
        if (has_append) return .append;
        if (has_read and has_write) return .read_write;
        if (has_write) return .write;
        return .read; // read-only default (a bare [] opens read-only)
    }

    /// `file:open(Path, Modes)` → `{ok, {file_descriptor, prim_file, N}}` |
    /// `{error, Reason}`. Opens the real fd via the proven prim_file seam and
    /// records it in the RunFd table (closed in doFileClose/deinit — no leak).
    fn doFileOpen(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term, modes_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        var pbuf: [4096]u8 = undefined;
        const path = (try self.filePathBuf(m, path_t, &pbuf)) orelse return self.fileErrTuple(m, error.Einval);
        const mode = self.parseFileModes(m, modes_t) orelse return self.badargAtom(m);
        const handle = prim_file.open(fs.io, fs.root, path, mode) catch |e| return self.fileErrTuple(m, e);
        self.fd_counter += 1;
        const number = self.fd_counter;
        try self.fds.append(self.gpa, .{ .number = number, .handle = handle, .alive = true });
        const dev = try FinalTerms.tuple(&m.ctx, &.{
            FinalTerms.atom(&m.ctx, try self.atoms.intern("file_descriptor")),
            FinalTerms.atom(&m.ctx, try self.atoms.intern("prim_file")),
            FinalTerms.int(&m.ctx, @intCast(number)),
        });
        const ok_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        return FinalTerms.tuple(&m.ctx, &.{ ok_a, dev });
    }

    /// `file:pread(IoDevice, Location, Number)` → `{ok, Binary}` | `eof` |
    /// `{error, einval}`. Positioned read (the fd offset is not consumed). `n==0`
    /// at/after EOF → the bare atom `eof`. A closed/bad handle → `{error, einval}`.
    fn doFilePread(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term, pos_t: FinalTerms.Term, len_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        if (!FinalTerms.repIsSmall(pos_t) or !FinalTerms.repIsSmall(len_t)) return self.badargAtom(m);
        const posv = FinalTerms.smallValOf(pos_t);
        const lenv = FinalTerms.smallValOf(len_t);
        if (posv < 0 or lenv < 0) return self.badargAtom(m);
        const want: usize = @intCast(@min(lenv, 1024 * 1024)); // bounded read
        const buf = try self.gpa.alloc(u8, want);
        defer self.gpa.free(buf);
        const n = prim_file.pread(self.fs.?.io, rf.handle, @intCast(posv), buf) catch |e| return self.fileErrTuple(m, e);
        if (n == 0) return FinalTerms.atom(&m.ctx, try self.atoms.intern("eof"));
        const ok_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        const bin = try FinalTerms.binary(&m.ctx, buf[0..n]);
        return FinalTerms.tuple(&m.ctx, &.{ ok_a, bin });
    }

    /// `file:pwrite(IoDevice, Location, Bytes)` → `ok` | `{error, einval}`.
    /// Positioned write (extends with a hole if Location > size). Closed → einval.
    fn doFilePwrite(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term, pos_t: FinalTerms.Term, data_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        if (!FinalTerms.repIsSmall(pos_t)) return self.badargAtom(m);
        const posv = FinalTerms.smallValOf(pos_t);
        if (posv < 0) return self.badargAtom(m);
        const dbin = FinalTerms.iolistToBinary(&m.ctx, data_t) catch return self.badargAtom(m);
        const dbytes = FinalTerms.binBytes(&m.ctx, dbin);
        prim_file.pwrite(self.fs.?.io, rf.handle, @intCast(posv), dbytes) catch |e| return self.fileErrTuple(m, e);
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    /// `file:close(IoDevice)` → `ok` | `{error, einval}`. Closing a LIVE handle
    /// frees the OS fd and returns `ok`; closing an already-closed / bad handle is
    /// `{error, einval}` (erts' raw-fd contract — NOT idempotent-ok, unlike a
    /// socket). Frees the fd (no leak, FMEA FM-FD-1).
    fn doFileClose(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        prim_file.close(self.fs.?.io, rf.handle);
        rf.alive = false;
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    // ── gap-file-seq-io: the SEQUENTIAL fd surface (read/write/position advance/seek
    // the RunFd's tracked offset; implemented over the SAME pread/pwrite seam) ──

    /// `file:read(IoDevice, Number)` → `{ok, Data}` | `eof` | `{error, einval}`.
    /// Reads up to Number bytes AT the tracked offset, then ADVANCES it by the count.
    fn doFileReadSeq(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term, len_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        if (!FinalTerms.repIsSmall(len_t)) return self.badargAtom(m);
        const lenv = FinalTerms.smallValOf(len_t);
        if (lenv < 0) return self.badargAtom(m);
        const want: usize = @intCast(@min(lenv, 1024 * 1024)); // bounded read
        const buf = try self.gpa.alloc(u8, want);
        defer self.gpa.free(buf);
        const n = prim_file.pread(self.fs.?.io, rf.handle, rf.pos, buf) catch |e| return self.fileErrTuple(m, e);
        if (n == 0) return FinalTerms.atom(&m.ctx, try self.atoms.intern("eof"));
        rf.pos += n; // ADVANCE the sequential offset
        const ok_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        const bin = try FinalTerms.binary(&m.ctx, buf[0..n]);
        return FinalTerms.tuple(&m.ctx, &.{ ok_a, bin });
    }

    /// `file:write(IoDevice, Bytes)` → `ok` | `{error, einval}`. Writes AT the tracked
    /// offset, then ADVANCES it by the byte count (sequential append within a handle).
    fn doFileWriteSeq(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term, data_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        const dbin = FinalTerms.iolistToBinary(&m.ctx, data_t) catch return self.badargAtom(m);
        const dbytes = FinalTerms.binBytes(&m.ctx, dbin);
        prim_file.pwrite(self.fs.?.io, rf.handle, rf.pos, dbytes) catch |e| return self.fileErrTuple(m, e);
        rf.pos += dbytes.len; // ADVANCE
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    /// `file:position(IoDevice, Location)` → `{ok, NewPos}` | `{error, einval}`.
    /// Location = Integer(≡{bof,N}) | bof|cur|eof | {bof|cur|eof, Offset}. A resulting
    /// negative position → `{error, einval}` (erts contract).
    fn doFilePosition(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term, loc_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        // resolve (base, offset): the base atom (bof/cur/eof) + a signed offset.
        var base: i64 = 0;
        var offset: i64 = 0;
        if (FinalTerms.repIsSmall(loc_t)) {
            base = 0; // an integer Location is absolute (≡ {bof, N})
            offset = FinalTerms.smallValOf(loc_t);
        } else if (FinalTerms.repIsAtom(loc_t)) {
            base = (try self.positionBase(loc_t, rf)) orelse return self.badargAtom(m);
        } else if (FinalTerms.kindOf(&m.ctx, loc_t) == .tuple and FinalTerms.tupleArity(&m.ctx, loc_t) == 2) {
            const b = FinalTerms.tupleElem(&m.ctx, loc_t, 0);
            const o = FinalTerms.tupleElem(&m.ctx, loc_t, 1);
            if (!FinalTerms.repIsAtom(b) or !FinalTerms.repIsSmall(o)) return self.badargAtom(m);
            base = (try self.positionBase(b, rf)) orelse return self.badargAtom(m);
            offset = FinalTerms.smallValOf(o);
        } else return self.badargAtom(m);
        const newpos = base + offset;
        if (newpos < 0) return self.fileErrTuple(m, error.Einval); // seek before BOF
        rf.pos = @intCast(newpos);
        const ok_a = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        return FinalTerms.tuple(&m.ctx, &.{ ok_a, FinalTerms.int(&m.ctx, newpos) });
    }

    /// Resolve a position base atom (`bof`→0, `cur`→the tracked offset, `eof`→the live
    /// size). Returns null for any other atom (→ badarg).
    fn positionBase(self: *Vm, atom_t: FinalTerms.Term, rf: *RunFd) !?i64 {
        const nm = self.atoms.nameOf(FinalTerms.atomIdxOf(atom_t));
        if (std.mem.eql(u8, nm, "bof")) return 0;
        if (std.mem.eql(u8, nm, "cur")) return @intCast(rf.pos);
        if (std.mem.eql(u8, nm, "eof")) {
            const sz = prim_file.handleSize(self.fs.?.io, rf.handle) catch return @as(?i64, 0);
            return @intCast(sz);
        }
        return null;
    }

    /// `file:read_file_info(Path, Opts)` — the option-carrying stat. Opts is a proper
    /// list; `{time, posix|local|universal}` selects the time representation (default
    /// local, matching read_file_info/1).
    fn doFileReadFileInfoOpts(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term, opts_t: FinalTerms.Term) !FinalTerms.Term {
        var mode: TimeMode = .local;
        var cur = opts_t;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons) {
            const h = FinalTerms.listHead(&m.ctx, cur);
            if (FinalTerms.kindOf(&m.ctx, h) == .tuple and FinalTerms.tupleArity(&m.ctx, h) == 2) {
                const k = FinalTerms.tupleElem(&m.ctx, h, 0);
                const v = FinalTerms.tupleElem(&m.ctx, h, 1);
                if (FinalTerms.repIsAtom(k) and std.mem.eql(u8, self.atoms.nameOf(FinalTerms.atomIdxOf(k)), "time") and FinalTerms.repIsAtom(v)) {
                    const vn = self.atoms.nameOf(FinalTerms.atomIdxOf(v));
                    if (std.mem.eql(u8, vn, "posix")) mode = .posix;
                    if (std.mem.eql(u8, vn, "universal")) mode = .universal;
                    if (std.mem.eql(u8, vn, "local")) mode = .local;
                }
            }
            cur = FinalTerms.listTail(&m.ctx, cur);
        }
        return self.doFileReadFileInfo(m, path_t, mode, true);
    }

    // ── gap-file-fs-mutation: the filesystem-mutation surface (the FINAL file: slice) ──

    /// `ok` if the closure succeeds, else `{error, Posix}` — the uniform fs-mutation
    /// return shape. `pathOp` resolves ONE path arg under the fs root and runs `f`.
    fn okOrErr(self: *Vm, m: *ia.Machine, r: anyerror!void) !FinalTerms.Term {
        r catch |e| return self.fileErrTuple(m, e);
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    fn doFileDelete(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        var pbuf: [4096]u8 = undefined;
        const path = (try self.filePathBuf(m, path_t, &pbuf)) orelse return self.fileErrTuple(m, error.Einval);
        return self.okOrErr(m, prim_file.delete(fs.io, fs.root, path));
    }

    fn doFileRename(self: *Vm, m: *ia.Machine, from_t: FinalTerms.Term, to_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        var fbuf: [4096]u8 = undefined;
        var tbuf: [4096]u8 = undefined;
        const from = (try self.filePathBuf(m, from_t, &fbuf)) orelse return self.fileErrTuple(m, error.Einval);
        const to = (try self.filePathBuf(m, to_t, &tbuf)) orelse return self.fileErrTuple(m, error.Einval);
        return self.okOrErr(m, prim_file.rename(fs.io, fs.root, from, to));
    }

    fn doFileMakeDir(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        var pbuf: [4096]u8 = undefined;
        const path = (try self.filePathBuf(m, path_t, &pbuf)) orelse return self.fileErrTuple(m, error.Einval);
        return self.okOrErr(m, prim_file.makeDir(fs.io, fs.root, path));
    }

    fn doFileDelDir(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term) !FinalTerms.Term {
        const fs = self.fs orelse return self.fileErrTuple(m, error.Enoent);
        var pbuf: [4096]u8 = undefined;
        const path = (try self.filePathBuf(m, path_t, &pbuf)) orelse return self.fileErrTuple(m, error.Einval);
        return self.okOrErr(m, prim_file.deleteDir(fs.io, fs.root, path));
    }

    /// `file:truncate(IoDevice)` — truncate the file to the tracked offset.
    fn doFileTruncate(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        return self.okOrErr(m, prim_file.truncateHandle(rf.handle, rf.pos));
    }

    fn doFileSync(self: *Vm, m: *ia.Machine, dev_t: FinalTerms.Term) !FinalTerms.Term {
        const rf = self.fdOf(m, dev_t) orelse return self.fileErrTuple(m, error.Einval);
        return self.okOrErr(m, prim_file.syncHandle(self.fs.?.io, rf.handle));
    }

    /// `file:read_link_info(Path[, Opts])` — lstat (no-follow), via the read_file_info
    /// builder with follow=false. Opts carries `{time, posix|local|universal}`.
    fn doFileReadLinkInfo(self: *Vm, m: *ia.Machine, path_t: FinalTerms.Term, opts_t: FinalTerms.Term) !FinalTerms.Term {
        var mode: TimeMode = .local;
        var cur = opts_t;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons) {
            const h = FinalTerms.listHead(&m.ctx, cur);
            if (FinalTerms.kindOf(&m.ctx, h) == .tuple and FinalTerms.tupleArity(&m.ctx, h) == 2) {
                const k = FinalTerms.tupleElem(&m.ctx, h, 0);
                const v = FinalTerms.tupleElem(&m.ctx, h, 1);
                if (FinalTerms.repIsAtom(k) and std.mem.eql(u8, self.atoms.nameOf(FinalTerms.atomIdxOf(k)), "time") and FinalTerms.repIsAtom(v)) {
                    const vn = self.atoms.nameOf(FinalTerms.atomIdxOf(v));
                    if (std.mem.eql(u8, vn, "posix")) mode = .posix;
                    if (std.mem.eql(u8, vn, "universal")) mode = .universal;
                    if (std.mem.eql(u8, vn, "local")) mode = .local;
                }
            }
            cur = FinalTerms.listTail(&m.ctx, cur);
        }
        return self.doFileReadFileInfo(m, path_t, mode, false); // follow=false → lstat
    }

    fn doOpenPort(self: *Vm, pid: Pid, m: *ia.Machine, name: FinalTerms.Term, binary_mode: bool, exit_status: bool, line_width: usize, stderr_to_stdout: bool) !FinalTerms.Term {
        if (FinalTerms.kindOf(&m.ctx, name) != .tuple or FinalTerms.tupleArity(&m.ctx, name) != 2)
            return self.badargAtom(m);
        const tag = FinalTerms.tupleElem(&m.ctx, name, 0);
        if (!FinalTerms.repIsAtom(tag)) return self.badargAtom(m);
        const tag_name = self.atoms.nameOf(FinalTerms.atomIdxOf(tag));
        if (!std.mem.eql(u8, tag_name, "spawn") and !std.mem.eql(u8, tag_name, "spawn_executable"))
            return self.badargAtom(m);
        // Collect the command string (charlist or binary) into a NUL-terminated buffer.
        const cmd_term = FinalTerms.tupleElem(&m.ctx, name, 1);
        const bin = FinalTerms.iolistToBinary(&m.ctx, cmd_term) catch return self.badargAtom(m);
        const bytes = FinalTerms.binBytes(&m.ctx, bin);
        if (bytes.len == 0 or bytes.len >= 512) return self.badargAtom(m);
        var cbuf: [512]u8 = undefined;
        @memcpy(cbuf[0..bytes.len], bytes);
        cbuf[bytes.len] = 0;
        const cmdz: [*:0]const u8 = @ptrCast(&cbuf);
        const live = os_port.LivePort.spawnShellOpts(cmdz, stderr_to_stdout) catch return self.badargAtom(m);
        const number = self.next_port;
        self.next_port += 1;
        // E6.7: own a copy of the command name for port_info(name)/ports/0.
        const name_owned = self.gpa.dupe(u8, bytes) catch {
            var l = live;
            l.deinit();
            return self.badargAtom(m);
        };
        try self.ports.append(self.gpa, .{
            .number = number,
            .connected = m.self_pid,
            .live = live,
            .alive = true,
            .name = name_owned,
            .binary_mode = binary_mode,
            .exit_status = exit_status,
            .line_width = line_width,
        });
        const port_term = try FinalTerms.port(&m.ctx, number);
        // gap-open-port-exit-status (Slice B): the AUTONOMOUS-PRODUCER path. A
        // `{spawn,Cmd}` child that writes output and EXITS on its own (echo/date/…)
        // — as opposed to an interactive filter (cat) that blocks on stdin — has its
        // stdout delivered as `{Port,{data,Out}}` and, if `exit_status` was given,
        // followed by `{Port,{exit_status,Code}}`. We DETECT the producer by draining
        // stdout to EOF with a bounded idle fuel WITHOUT closing stdin: a producer
        // hits EOF fast; an interactive filter hits the fuel and is left untouched
        // (its data still flows through port_command). Slice B; the interactive echo
        // (port_command reply) path is unchanged.
        try self.drainAutonomousPort(pid, number, port_term);
        return port_term;
    }

    /// gap-open-port-exit-status (Slice B): drain an autonomous-producer child's
    /// stdout at open time and deliver `{Port,{data,Out}}` (+ `{Port,{exit_status,
    /// Code}}` if armed). A no-op for an interactive filter (no EOF within the drain
    /// fuel → the child is left alive for port_command). `number` re-locates the
    /// RunPort after any `self.ports` growth; `port_term` is the Port for the message.
    /// gap-open-port-line (Slice C): build a charlist (list mode) or binary (binary
    /// mode) from `bytes`, in the owner's `octx`.
    fn buildBytesTerm(octx: *FinalTerms.Ctx, bytes: []const u8, is_binary: bool) !FinalTerms.Term {
        if (is_binary) return try FinalTerms.binary(octx, bytes);
        var lst = FinalTerms.nil(octx);
        var i = bytes.len;
        while (i > 0) {
            i -= 1;
            lst = try FinalTerms.cons(octx, FinalTerms.int(octx, bytes[i]), lst);
        }
        return lst;
    }

    /// gap-open-port-line (Slice C): deliver a child's output `bytes` to the owner as
    /// port data message(s). In `{line,N}` mode (`line_width > 0`), frame via
    /// `port_algebra.lineFrames` into one `{Port,{data,{eol|noeol,Line}}}` per line;
    /// otherwise ONE `{Port,{data,Out}}`. Each Line respects list/binary mode; empty
    /// non-line output delivers NO frame (OTP sends no empty data). Built in `octx`,
    /// delivered via `signal` (the caller drains). SCOPE: the framer runs over the
    /// bytes it is given (the full drained buffer for a producer, or one echo reply);
    /// a line split ACROSS reads/commands is the documented streaming residual.
    fn emitPortData(self: *Vm, pid: Pid, owner_pid: Pid, octx: *FinalTerms.Ctx, port_term: FinalTerms.Term, bytes: []const u8, is_binary: bool, line_width: usize) !void {
        const data_atom = FinalTerms.atom(octx, try self.atoms.intern("data"));
        if (line_width > 0) {
            var frames: std.ArrayList(port_algebra.LineFrame) = .empty;
            defer frames.deinit(self.gpa);
            try port_algebra.lineFrames(self.gpa, bytes, line_width, &frames);
            const eol_atom = FinalTerms.atom(octx, try self.atoms.intern("eol"));
            const noeol_atom = FinalTerms.atom(octx, try self.atoms.intern("noeol"));
            for (frames.items) |fr| {
                const line_o = try buildBytesTerm(octx, bytes[fr.off .. fr.off + fr.len], is_binary);
                const tag = if (fr.eol) eol_atom else noeol_atom;
                const tagged = try FinalTerms.tuple(octx, &.{ tag, line_o });
                const inner = try FinalTerms.tuple(octx, &.{ data_atom, tagged });
                const msg = try FinalTerms.tuple(octx, &.{ port_term, inner });
                try self.signal(pid, owner_pid, .{ .message = msg });
            }
            return;
        }
        if (bytes.len == 0) return; // OTP delivers no empty data frame (non-line)
        const data_o = try buildBytesTerm(octx, bytes, is_binary);
        const inner = try FinalTerms.tuple(octx, &.{ data_atom, data_o });
        const msg = try FinalTerms.tuple(octx, &.{ port_term, inner });
        try self.signal(pid, owner_pid, .{ .message = msg });
    }

    fn drainAutonomousPort(self: *Vm, pid: Pid, number: u32, port_term: FinalTerms.Term) !void {
        const idx = self.portIndexOf(number) orelse return;
        if (self.ports.items[idx].live.is_tty) return;
        // Drain WITHOUT closing stdin (closing would make `cat` exit — we must not
        // disturb an interactive filter). A producer reaches EOF within the fuel.
        const port_open_drain_fuel = 40; // ~400ms idle cap — robust for a fast producer, tolerable for a filter
        const out = self.ports.items[idx].live.readToEof(self.gpa, 1 << 20, port_open_drain_fuel) catch {
            return; // error.Fuel (interactive, still alive) or a read error → no autonomous delivery
        };
        defer self.gpa.free(out);
        const rp = &self.ports.items[idx];
        const owner_pid = rp.connected;
        const armed = rp.exit_status;
        const is_binary = rp.binary_mode;
        const line_width = rp.line_width;
        const owner = self.proc(owner_pid) orelse return;
        const octx = &owner.machine.ctx;
        // (1) the data frame(s): one {Port,{data,Out}} (raw/list/binary) OR — in
        // {line,N} mode — a {Port,{data,{eol|noeol,Line}}} per framed line.
        try self.emitPortData(pid, owner_pid, octx, port_term, out, is_binary, line_width);
        // The child reached EOF → reap it for the exit code and retire the port.
        const status = self.ports.items[idx].live.wait(200);
        self.ports.items[idx].alive = false;
        // (2) {Port, {exit_status, Code}} — ONLY when armed. A normal exit gives its
        // code (0 == normal); a signalled child gives 128+signal (shell convention).
        if (armed) {
            const code: i64 = switch (status) {
                .exited => |c| c,
                .signalled => |s| 128 + @as(i64, s),
            };
            const es_atom = FinalTerms.atom(octx, try self.atoms.intern("exit_status"));
            const inner = try FinalTerms.tuple(octx, &.{ es_atom, FinalTerms.int(octx, code) });
            const msg = try FinalTerms.tuple(octx, &.{ port_term, inner });
            try self.signal(pid, owner_pid, .{ .message = msg });
        }
        // Deliver both into the owner's mailbox NOW (the owner is `running`, so the
        // signal's suspend-wake did not fire — the doPortCommand/doIoRequest reason).
        try self.drainSignals(owner_pid);
    }

    /// `erts_internal:port_command(Port, Data, _Flags)` — write `Data`'s bytes to
    /// the live child; the echo driver's reply `{Port,{data,Echo}}` is delivered to
    /// the port's OWN connected process (built in the OWNER's heap). Returns `true`.
    fn doPortCommand(self: *Vm, pid: Pid, m: *ia.Machine, port_term: FinalTerms.Term, data: FinalTerms.Term) !FinalTerms.Term {
        // gap-open-port-dispatch (DIVERGENCE 594): a bad port / bad iodata RAISES
        // error:badarg — the erlang:port_command/2 contract (the `.port_cmd` pending
        // arm converts this Zig error to a catchable raise via raiseErrorAtom). Was
        // returning the atom `badarg` as a VALUE (uncatchable) — the compiled bad-port
        // differential surfaced it (`try port_command(BadPort,_) catch error:badarg`
        // gave `badarg` on zigvm vs `caught_badarg` on OTP-30).
        const rp = self.portOf(m, port_term) orelse return error.Badarg;
        const bin = FinalTerms.iolistToBinary(&m.ctx, data) catch return error.Badarg;
        const bytes = FinalTerms.binBytes(&m.ctx, bin);
        if (bytes.len == 0) return FinalTerms.atom(&m.ctx, m.bool_true); // nothing to echo
        if (rp.live.is_tty) {
            rp.live.writeAll(bytes) catch return error.Badarg;
            return FinalTerms.atom(&m.ctx, m.bool_true);
        }

        const out = try self.gpa.alloc(u8, bytes.len);
        defer self.gpa.free(out);
        const echoed = rp.live.command(bytes, out, 200) catch return error.Badarg;
        // Build + deliver the reply frame(s) in the OWNER's heap. Slice A gave the
        // list/binary shape (default `list` → charlist); Slice C adds the {line,N}
        // framing (rp.line_width>0 → {data,{eol|noeol,Line}} per line). One shared
        // emitter for both the autonomous-producer path and this echo-reply path.
        const owner = self.proc(rp.connected) orelse return FinalTerms.atom(&m.ctx, m.bool_true);
        const octx = &owner.machine.ctx;
        const port_o = try FinalTerms.port(octx, rp.number);
        try self.emitPortData(pid, rp.connected, octx, port_o, echoed, rp.binary_mode, rp.line_width);
        // The reply is synchronous in the driver: drain it into the owner's
        // mailbox NOW so a same-process `receive {Port,{data,_}}` sees it (the
        // owner is `running`, so `signal`'s suspend-wake did not fire — the io
        // protocol's `doIoRequest` drains for the same reason).
        try self.drainSignals(rp.connected);
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// gap-socket-gen-tcp-bifs: the VM execution seam for real gen_tcp sockets.
    /// Open a real loopback TCP pair (socket_algebra, Stratum C), send `data`
    /// (iodata) over the actual socket, read it back, and return the echoed
    /// binary — proving the interpret loop drives real socket I/O end-to-end
    /// through the trap mechanism. Bounded (payload ≤ 32 KiB, well under the
    /// loopback socket buffer so the single-threaded send never blocks), zero-leak
    /// (both fds closed), fail-closed (any syscall error → badarg, never a hang).
    fn doSocketRoundtrip(self: *Vm, m: *ia.Machine, data: FinalTerms.Term) !FinalTerms.Term {
        const bin = FinalTerms.iolistToBinary(&m.ctx, data) catch return self.badargAtom(m);
        const bytes = FinalTerms.binBytes(&m.ctx, bin);
        if (bytes.len > 32 * 1024) return self.badargAtom(m); // bounded: no send-block
        const pair = socket_algebra.openLoopbackPair() catch return self.badargAtom(m);
        defer socket_algebra.close(pair.server);
        defer socket_algebra.close(pair.client);
        if (bytes.len == 0) return try FinalTerms.binary(&m.ctx, bytes); // empty → empty
        socket_algebra.send(pair.client, bytes) catch return self.badargAtom(m);
        const buf = try self.gpa.alloc(u8, bytes.len);
        defer self.gpa.free(buf);
        var off: usize = 0;
        while (off < bytes.len) {
            const n = socket_algebra.recv(pair.server, buf[off..]) catch return self.badargAtom(m);
            if (n == 0) break; // peer closed early
            off += n;
        }
        return try FinalTerms.binary(&m.ctx, buf[0..off]);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // gap-socket-real-tcp: the HANDLE-based gen_tcp / gen_udp lifecycle over the
    // real loopback transport (socket_algebra). These handlers own the Vm socket
    // TABLE and render the OTP `{ok,Socket}` / `{error,Posix}` term shapes; a whole
    // -VM LAW below drives listen→connect→accept→send→recv→close as a real echo.
    // ═══════════════════════════════════════════════════════════════════════

    /// The socket handle term `{'$socket', Number}` (identity is observed only by
    /// the round-trip, never by the tuple's shape).
    fn socketTerm(self: *Vm, m: *ia.Machine, number: u32) !FinalTerms.Term {
        const tag = FinalTerms.atom(&m.ctx, try self.atoms.intern("$socket"));
        return FinalTerms.tuple(&m.ctx, &.{ tag, FinalTerms.int(&m.ctx, @intCast(number)) });
    }

    /// Map a `{'$socket', N}` term back to its live RunSocket (null = absent/dead
    /// → the caller renders `{error,closed}`, never a crash).
    fn socketOf(self: *Vm, m: *ia.Machine, term: FinalTerms.Term) ?*RunSocket {
        if (FinalTerms.kindOf(&m.ctx, term) != .tuple) return null;
        if (FinalTerms.tupleArity(&m.ctx, term) != 2) return null;
        const tag = FinalTerms.tupleElem(&m.ctx, term, 0);
        const want = FinalTerms.atom(&m.ctx, self.atoms.intern("$socket") catch return null);
        if (!FinalTerms.eqlExact(&m.ctx, tag, want)) return null;
        const num = FinalTerms.tupleElem(&m.ctx, term, 1);
        if (FinalTerms.kindOf(&m.ctx, num) != .number) return null;
        const n: u32 = @intCast(FinalTerms.smallValOf(num));
        for (self.sockets.items) |*rs| {
            if (rs.number == n and rs.alive) return rs;
        }
        return null;
    }

    /// Register a live fd in the socket table, returning its `{'$socket',N}` term.
    fn addSocket(self: *Vm, m: *ia.Machine, fd: i32, kind: @TypeOf(@as(RunSocket, undefined).kind), port: u16) !FinalTerms.Term {
        const number = self.next_socket;
        self.next_socket += 1;
        try self.sockets.append(self.gpa, .{ .number = number, .fd = fd, .kind = kind, .port = port, .alive = true });
        return self.socketTerm(m, number);
    }

    /// `{ok, Val}`.
    fn okTuple(self: *Vm, m: *ia.Machine, val: FinalTerms.Term) !FinalTerms.Term {
        const ok = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        return FinalTerms.tuple(&m.ctx, &.{ ok, val });
    }

    /// `{error, Reason}` for a posix atom name.
    fn errTuple(self: *Vm, m: *ia.Machine, reason: []const u8) !FinalTerms.Term {
        const err = FinalTerms.atom(&m.ctx, try self.atoms.intern("error"));
        const r = FinalTerms.atom(&m.ctx, try self.atoms.intern(reason));
        return FinalTerms.tuple(&m.ctx, &.{ err, r });
    }

    /// SockError → the OTP posix reason atom name.
    fn posixName(e: socket_algebra.SockError) []const u8 {
        return switch (e) {
            error.ConnRefused => "econnrefused",
            error.Timeout => "timeout",
            error.Closed, error.BadFd => "closed",
            else => "einval",
        };
    }

    /// gap-socket-active-mode: `inet:setopts(Socket, Opts)` → `ok`. Parses
    /// `{active, false|once|true}` and records the mode + the CALLER as the owner —
    /// NON-BLOCKING (no synchronous recv; the scheduler's `pollActiveSockets` does
    /// the delivery). Other opts are accepted+ignored.
    fn doInetSetopts(self: *Vm, pid: Pid, m: *ia.Machine, sock_term: FinalTerms.Term, opts: FinalTerms.Term) !FinalTerms.Term {
        const a_ok = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        const rs = self.socketOf(m, sock_term) orelse return a_ok; // unknown → ok (ranch-tolerant)
        const a_active = try self.atoms.intern("active");
        const a_once = try self.atoms.intern("once");
        var cur = opts;
        var guard: usize = 0;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons and guard < 64) : (guard += 1) {
            const head = FinalTerms.listHead(&m.ctx, cur);
            cur = FinalTerms.listTail(&m.ctx, cur);
            if (FinalTerms.kindOf(&m.ctx, head) == .tuple and FinalTerms.tupleArity(&m.ctx, head) == 2) {
                const k = FinalTerms.tupleElem(&m.ctx, head, 0);
                if (FinalTerms.repIsAtom(k) and FinalTerms.atomIdxOf(k) == a_active) {
                    const v = FinalTerms.tupleElem(&m.ctx, head, 1);
                    if (FinalTerms.repIsAtom(v)) {
                        const vi = FinalTerms.atomIdxOf(v);
                        rs.active = if (vi == a_once) 1 else if (vi == m.bool_true) 2 else 0;
                    } else if (FinalTerms.kindOf(&m.ctx, v) == .number) {
                        rs.active = if (FinalTerms.smallValOf(v) != 0) 2 else 0;
                    }
                    if (rs.active != 0) rs.owner = pid; // the process that armed it receives {tcp,_,_}
                }
            }
        }
        return a_ok;
    }

    /// gap-socket-active-mode: enqueue `{tcp, Socket, Data}` (or `{tcp_closed,
    /// Socket}`) to `to`'s mailbox and wake it (reuses the stamped signal path).
    fn deliverActiveTcp(self: *Vm, to: Pid, sock_number: u32, closed: bool, data: []const u8) !void {
        const target = self.proc(to) orelse return;
        const tc = &target.machine.ctx;
        const sock_term = try self.socketTerm(&target.machine, sock_number);
        const msg = if (closed) blk: {
            const a = FinalTerms.atom(tc, try self.atoms.intern("tcp_closed"));
            break :blk try FinalTerms.tuple(tc, &.{ a, sock_term });
        } else blk: {
            const a = FinalTerms.atom(tc, try self.atoms.intern("tcp"));
            const bin = try FinalTerms.binary(tc, data);
            break :blk try FinalTerms.tuple(tc, &.{ a, sock_term, bin });
        };
        try self.signalTrace(to, msg); // stamped enqueue + wake (name is historical; it is a plain message)
    }

    /// gap-os-signals-delivery: the SCHEDULER hook for OS signals — drain the
    /// handler's pending set and deliver each raised signal to the process
    /// registered as `erl_signal_server`.
    ///
    /// THE MESSAGE SHAPE IS THE ORACLE'S, MEASURED NOT GUESSED. Against pinned
    /// OTP-30 (`gen_event:add_handler(erl_signal_server, …)` after removing the
    /// default handler, then `kill -USR1`) the event delivered is the BARE
    /// signal-name atom:
    ///
    ///     {received,{sig_event,sigusr1}}
    ///
    /// not `{notify, Sig}` and not a tuple of any shape — which is what a
    /// reasonable reading of the docs would have produced, and what MUT-SIGD-1
    /// plants to prove the law would catch it.
    ///
    /// THE REACTOR DISCIPLINE, same as `pollActiveSockets`: a signal handler may
    /// do nothing but set a flag, so all the real work — atom interning, term
    /// building, mailbox enqueue, waking the receiver — happens HERE, on the
    /// scheduler thread, where allocation and locking are legal.
    ///
    /// NO REGISTERED SERVER ⇒ DROPPED, never an error. A signal can arrive
    /// before `erl_signal_server` is registered or after it dies, and OTP does
    /// not fault the runtime for that.
    pub fn pollPendingSignals(self: *Vm) !void {
        const mask = os_bif.drainPendingSignals();
        if (mask == 0) return;
        const server = try self.atoms.intern("erl_signal_server");
        const to = self.registry.whereis(server) orelse return; // dropped, by design
        const target = self.proc(to) orelse return;
        for (0..os_bif.pending_signal_count) |i| {
            if (mask & (@as(u32, 1) << @intCast(i)) == 0) continue;
            const name = os_bif.pendingSignalName(i);
            const msg = FinalTerms.atom(&target.machine.ctx, try self.atoms.intern(name));
            try self.signalTrace(to, msg); // stamped enqueue + wake
        }
    }

    /// gap-socket-active-mode: the SCHEDULER hook — each tick, non-blocking-poll
    /// every ACTIVE stream socket and deliver its data as `{tcp,S,Data}` (or
    /// `{tcp_closed,S}` on EOF/error) to the owner. `once` self-clears after one
    /// delivery. This is the reactor discipline (never a synchronous poll in a BIF),
    /// and a socket with pending data is runnable WORK (it wakes the owner), so a
    /// blocked-but-alive server node stays live to serve.
    pub fn pollActiveSockets(self: *Vm) !void {
        for (self.sockets.items) |*rs| {
            // active!=0 ⇒ setopts recorded an owner (pid 0 is a valid owner — the
            // entry process — so it must NOT be treated as "no owner").
            if (!rs.alive or rs.active == 0 or rs.kind != .stream) continue;
            const num = rs.number;
            const own = rs.owner;
            var buf: [16384]u8 = undefined;
            const n = socket_algebra.recvTimeout(rs.fd, buf[0..], 0) catch |e| switch (e) {
                error.Timeout => continue, // no data ready — leave armed
                else => { // closed / bad fd → one {tcp_closed,S}, disarm
                    rs.active = 0;
                    try self.deliverActiveTcp(own, num, true, "");
                    continue;
                },
            };
            if (n == 0) { // EOF
                rs.active = 0;
                try self.deliverActiveTcp(own, num, true, "");
                continue;
            }
            if (rs.active == 1) rs.active = 0; // {active,once} consumed
            try self.deliverActiveTcp(own, num, false, buf[0..n]);
        }
    }

    /// `inet:sockname(Socket)` → `{ok, {{0,0,0,0}, Port}}` — the bound local
    /// endpoint (IPv4 any-address + the socket's port; ranch reads it post-listen).
    fn doInetSockname(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        const zero = FinalTerms.int(&m.ctx, 0);
        const addr = try FinalTerms.tuple(&m.ctx, &.{ zero, zero, zero, zero });
        const pair = try FinalTerms.tuple(&m.ctx, &.{ addr, FinalTerms.int(&m.ctx, @intCast(rs.port)) });
        return self.okTuple(m, pair);
    }

    /// gap-app-boot-engine: `code:ensure_loaded(Module)` handler — autoload the
    /// module into the caller's code space (via `--code-path`) if not already
    /// resolvable, then render `{module,M}` | `{error,nofile}`. "Loaded" = the
    /// universal `module_info` export resolves (static OR runtime), so a following
    /// `erlang:function_exported` sees the module. Bypasses the unbooted code_server.
    fn doCodeEnsureLoaded(self: *Vm, m: *ia.Machine, module_term: FinalTerms.Term) !FinalTerms.Term {
        const a_module = FinalTerms.atom(&m.ctx, try self.atoms.intern("module"));
        const a_error = FinalTerms.atom(&m.ctx, try self.atoms.intern("error"));
        const a_nofile = FinalTerms.atom(&m.ctx, try self.atoms.intern("nofile"));
        if (!FinalTerms.repIsAtom(module_term))
            return FinalTerms.tuple(&m.ctx, &.{ a_error, a_nofile });
        const mod = FinalTerms.atomIdxOf(module_term);
        const mi = try self.atoms.intern("module_info");
        const isLoaded = struct {
            fn f(mm: *ia.Machine, md: ta.AtomIdx, mii: ta.AtomIdx) bool {
                return mm.resolveRuntime(md, mii, 0) != null or mm.resolveRuntime(md, mii, 1) != null or
                    mm.resolveExport(md, mii, 0) != null or mm.resolveExport(md, mii, 1) != null;
            }
        }.f;
        if (!isLoaded(m, mod, mi)) _ = self.autoloadModuleInto(m, mod) catch false;
        if (isLoaded(m, mod, mi))
            return FinalTerms.tuple(&m.ctx, &.{ a_module, module_term });
        return FinalTerms.tuple(&m.ctx, &.{ a_error, a_nofile });
    }

    /// `gen_tcp:listen(Port,_)` → `{ok, ListenSocket}` | `{error, Posix}`.
    /// Scan a gen_tcp option proper-list for a `{port, N}` 2-tuple. ranch calls
    /// `gen_tcp:listen(0, Opts)` and carries the real port HERE (the opts port takes
    /// precedence over arg-0), so a listener bound to arg-0 alone would bind an
    /// ephemeral port and never serve the requested one. Bounded walk; null if absent.
    fn portFromOpts(m: *ia.Machine, opts: FinalTerms.Term) ?u16 {
        const a_port = m.ctx.atoms.intern("port") catch return null;
        var cur = opts;
        var guard: usize = 0;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons and guard < 64) : (guard += 1) {
            const head = FinalTerms.listHead(&m.ctx, cur);
            cur = FinalTerms.listTail(&m.ctx, cur);
            if (FinalTerms.kindOf(&m.ctx, head) == .tuple and FinalTerms.tupleArity(&m.ctx, head) == 2) {
                const k = FinalTerms.tupleElem(&m.ctx, head, 0);
                if (FinalTerms.repIsAtom(k) and FinalTerms.atomIdxOf(k) == a_port) {
                    const v = FinalTerms.tupleElem(&m.ctx, head, 1);
                    if (FinalTerms.kindOf(&m.ctx, v) == .number)
                        return @intCast(@as(u64, @bitCast(FinalTerms.smallValOf(v))) & 0xffff);
                }
            }
        }
        return null;
    }

    fn doGenTcpListen(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term, opts: FinalTerms.Term) !FinalTerms.Term {
        var req_port: u16 = if (FinalTerms.kindOf(&m.ctx, port_term) == .number)
            @intCast(@as(u64, @bitCast(FinalTerms.smallValOf(port_term))) & 0xffff)
        else
            0;
        // ranch passes the real port as `{port,N}` in Opts with arg-0 = 0.
        if (req_port == 0) {
            if (portFromOpts(m, opts)) |p| req_port = p;
        }
        const l = socket_algebra.listen(req_port) catch |e| return self.errTuple(m, posixName(e));
        return self.okTuple(m, try self.addSocket(m, l.fd, .listen, l.port));
    }

    /// `inet:port(Socket)` → `{ok, Port}` — the bound port of a listener/udp
    /// socket, so a peer can connect/sendto it.
    fn doInetPort(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        return self.okTuple(m, FinalTerms.int(&m.ctx, @intCast(rs.port)));
    }

    /// `gen_tcp:connect(loopback, Port, _)` → `{ok, Socket}` | `{error, econnrefused}`.
    fn doGenTcpConnect(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term) !FinalTerms.Term {
        if (FinalTerms.kindOf(&m.ctx, port_term) != .number) return self.errTuple(m, "einval");
        const port: u16 = @intCast(@as(u64, @bitCast(FinalTerms.smallValOf(port_term))) & 0xffff);
        const fd = socket_algebra.connectPort(port) catch |e| return self.errTuple(m, posixName(e));
        return self.okTuple(m, try self.addSocket(m, fd, .stream, port));
    }

    /// `gen_tcp:accept(ListenSocket, Timeout)` → `{ok, Socket}` | `{error, Posix}`.
    /// gap-cowboy-trap-accept: REACTOR accept. A connection ready NOW returns
    /// immediately (non-blocking accept4). Otherwise: a FINITE `Timeout` is a
    /// bounded fail-closed sync accept (the accept-hang law — never blocks forever);
    /// `infinity` SUSPENDS the process as this socket's `accept_waiter` — the
    /// scheduler's `pollAcceptSockets` accept4()s the connection when it lands and
    /// RESUMES the waiter with `{ok, Socket}`, so the ranch acceptor never blocks
    /// the single-threaded drive (which would starve the spawned conn process).
    fn doGenTcpAccept(self: *Vm, pid: Pid, m: *ia.Machine, listen_term: FinalTerms.Term, timeout_term: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, listen_term) orelse return self.errTuple(m, "closed");
        if (rs.kind != .listen) return self.errTuple(m, "einval");
        // Fast path: a connection already pending → accept it now (no suspend).
        if (socket_algebra.acceptTimeout(rs.fd, 0)) |fd| {
            return self.okTuple(m, try self.addSocket(m, fd, .stream, 0));
        } else |e| switch (e) {
            error.Timeout => {}, // none ready — fall through to reactor / bounded sync
            else => return self.errTuple(m, posixName(e)),
        }
        const is_infinity = FinalTerms.repIsAtom(timeout_term) and
            std.mem.eql(u8, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(timeout_term)), "infinity");
        if (is_infinity) {
            // SUSPEND: ENQUEUE at the tail of the accept-waiter FIFO (a whole ranch
            // acceptor pool queues here); the scheduler resumes the front on a landed
            // connection. Idempotent: a pid already queued is not double-enqueued.
            for (rs.accept_waiters.items) |w| {
                if (w == pid) {
                    m.status = .suspended;
                    return m.regs[0];
                }
            }
            try rs.accept_waiters.append(self.gpa, pid);
            m.status = .suspended;
            return m.regs[0]; // no-op x0 — pollAcceptSockets overwrites it on resume
        }
        // A FINITE timeout: bounded fail-closed sync accept (the accept-hang law).
        const ms: i32 = if (FinalTerms.repIsSmall(timeout_term)) @intCast(@min(FinalTerms.smallValOf(timeout_term), 60_000)) else 200;
        const fd = socket_algebra.acceptTimeout(rs.fd, ms) catch |e| return self.errTuple(m, posixName(e));
        return self.okTuple(m, try self.addSocket(m, fd, .stream, 0));
    }

    /// gap-cowboy-trap-accept: does the node have pending EXTERNAL socket work — a
    /// LISTEN socket with an accept-waiter, or an ACTIVE stream socket to poll? Such
    /// a node is NOT quiescent (it awaits a connection / data), so `driveResident`
    /// must NOT declare it `.idle`; it keeps polling (a real HTTP listener stays up).
    fn anySocketWaiter(self: *Vm) bool {
        for (self.sockets.items) |*rs| {
            if (!rs.alive) continue;
            if (rs.kind == .listen and rs.accept_waiters.items.len > 0) return true;
            if (rs.kind == .stream and rs.active != 0) return true;
        }
        return false;
    }

    /// gap-cowboy-trap-accept + gap-accept-waiters-queue: the scheduler hook —
    /// accept4() pending connections NON-BLOCKING for every LISTEN socket with a
    /// queued accept-waiter, RESUMING the FRONT (oldest) waiter per connection with
    /// `{ok, ConnSocket}` (x0). Mirrors `pollActiveSockets`. A landed accept is
    /// runnable WORK, so the served waiter wakes; the rest of the pool stays queued.
    pub fn pollAcceptSockets(self: *Vm) !void {
        // Two passes: capture ready (waiter, fd) first (accept4 doesn't touch the
        // table), THEN addSocket + resume (addSocket APPENDS → may realloc `sockets`,
        // invalidating the `rs` pointer, so never do it mid-iteration).
        var ready: [64]struct { waiter: Pid, fd: i32 } = undefined;
        var n: usize = 0;
        outer: for (self.sockets.items) |*rs| {
            if (!rs.alive or rs.kind != .listen) continue;
            // Serve as many pending connections as there are queued waiters, FRONT
            // (oldest) first — a ranch acceptor POOL drains here in one poll cycle.
            while (rs.accept_waiters.items.len > 0) {
                if (n >= ready.len) break :outer;
                const front = rs.accept_waiters.items[0];
                // A waiter whose process died while suspended is DROPPED (never served).
                if (self.proc(front) == null) {
                    _ = rs.accept_waiters.orderedRemove(0);
                    continue;
                }
                if (socket_algebra.acceptTimeout(rs.fd, 0)) |fd| {
                    ready[n] = .{ .waiter = front, .fd = fd };
                    n += 1;
                    _ = rs.accept_waiters.orderedRemove(0); // dequeue the SERVED waiter (FIFO)
                } else |_| break; // no connection ready (Timeout) / transient — leave the queue armed
            }
        }
        for (ready[0..n]) |r| {
            const wp = self.proc(r.waiter) orelse {
                socket_algebra.close(r.fd);
                continue;
            };
            const wm = &wp.machine;
            const sock_term = try self.addSocket(wm, r.fd, .stream, 0);
            wm.regs[0] = try self.okTuple(wm, sock_term); // resume value {ok, ConnSocket}
            if (wm.status == .suspended and !wp.io_gl) wm.status = .running;
            try self.markSchedulable(r.waiter);
        }
    }

    /// `gen_tcp:send(Socket, Data)` → `ok` | `{error, closed}`. Data is iodata.
    fn doGenTcpSend(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term, data: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        const bin = FinalTerms.iolistToBinary(&m.ctx, data) catch return self.badargAtom(m);
        const bytes = FinalTerms.binBytes(&m.ctx, bin);
        if (bytes.len > 32 * 1024) return self.badargAtom(m); // bounded: no send-block
        socket_algebra.send(rs.fd, bytes) catch |e| return self.errTuple(m, posixName(e));
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    /// `gen_tcp:recv(Socket, Length)` → `{ok, Binary}` | `{error, closed|timeout}`.
    /// Length>0 reads EXACTLY Length bytes (blocking, poll-bounded); Length==0
    /// reads whatever's currently available. Peer-close before Length → closed.
    fn doGenTcpRecv(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term, len_term: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        if (FinalTerms.kindOf(&m.ctx, len_term) != .number) return self.badargAtom(m);
        const want: usize = @intCast(@as(u64, @bitCast(FinalTerms.smallValOf(len_term))) & 0xffffffff);
        if (want > 64 * 1024) return self.badargAtom(m); // bounded read
        if (want == 0) {
            var buf: [4096]u8 = undefined;
            const n = socket_algebra.recvTimeout(rs.fd, buf[0..], 200) catch |e| return self.errTuple(m, posixName(e));
            if (n == 0) return self.errTuple(m, "closed");
            return self.okTuple(m, try FinalTerms.binary(&m.ctx, buf[0..n]));
        }
        const buf = try self.gpa.alloc(u8, want);
        defer self.gpa.free(buf);
        var off: usize = 0;
        while (off < want) {
            const n = socket_algebra.recvTimeout(rs.fd, buf[off..], 200) catch |e| return self.errTuple(m, posixName(e));
            if (n == 0) return self.errTuple(m, "closed"); // peer closed before Length bytes
            off += n;
        }
        return self.okTuple(m, try FinalTerms.binary(&m.ctx, buf[0..off]));
    }

    /// `gen_tcp:close(Socket)` / `gen_udp:close(Socket)` → `ok`. Idempotent: a
    /// dead/absent socket is inert `ok` (BEAM-close semantics from the caller).
    fn doGenTcpClose(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term) !FinalTerms.Term {
        if (self.socketOf(m, sock_term)) |rs| {
            socket_algebra.close(rs.fd);
            rs.alive = false;
        }
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    /// gap-socket-gen-tcp-bifs: `gen_tcp:shutdown(Socket, How)` → `ok` | `{error,_}`.
    /// Half-closes the connection via the real `shutdown(2)` syscall. `How` ∈
    /// {read, write, read_write} → `SHUT.{RD,WR,RDWR}`; `write` sends the peer an
    /// orderly EOF once its buffered data drains (the graceful teardown pattern —
    /// a subsequent peer `recv` returns the buffered bytes, then `{error,closed}`).
    /// A bad `How` → the `badarg` atom (the socket surface's uniform arg-rejection
    /// convention, cf. `doGenTcpRecv`); a closed/absent socket → `{error,closed}`.
    /// The socket STAYS in the table (shutdown ≠ close — the fd is still open for the
    /// un-shut direction and must still be `close`d).
    fn doGenTcpShutdown(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term, how_term: FinalTerms.Term) !FinalTerms.Term {
        if (FinalTerms.kindOf(&m.ctx, how_term) != .atom) return self.badargAtom(m);
        const a_read = FinalTerms.atom(&m.ctx, try self.atoms.intern("read"));
        const a_write = FinalTerms.atom(&m.ctx, try self.atoms.intern("write"));
        const a_rw = FinalTerms.atom(&m.ctx, try self.atoms.intern("read_write"));
        const how: i32 =
            if (FinalTerms.eqlExact(&m.ctx, how_term, a_write)) socket_algebra.SHUT_WR else if (FinalTerms.eqlExact(&m.ctx, how_term, a_read)) socket_algebra.SHUT_RD else if (FinalTerms.eqlExact(&m.ctx, how_term, a_rw)) socket_algebra.SHUT_RDWR else return self.badargAtom(m);
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        socket_algebra.shutdown(rs.fd, how) catch |e| return self.errTuple(m, posixName(e));
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    /// gap-socket-gen-tcp-bifs: `inet:getopts(Socket, OptNames)` → `{ok, [{Opt,Val}]}`.
    /// The read-back complement of `doInetSetopts`. For each requested option NAME (in
    /// order), zigvm emits `{Opt,Val}` ONLY where it can answer TRUTHFULLY: `active` →
    /// `{active, false|once|true}` from the recorded `rs.active`. Options zigvm does
    /// NOT model are OMITTED — never a fabricated value (FM-OBS-1); the honest bound is
    /// a possibly-shorter list than OTP (which reads every real socket option). A
    /// closed/absent socket → `{error, closed}`.
    fn doInetGetopts(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term, names: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        const a_active = try self.atoms.intern("active");
        var pairs: [64]FinalTerms.Term = undefined;
        var n: usize = 0;
        var cur = names;
        var guard: usize = 0;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons and guard < 64) : (guard += 1) {
            const head = FinalTerms.listHead(&m.ctx, cur);
            cur = FinalTerms.listTail(&m.ctx, cur);
            if (FinalTerms.repIsAtom(head) and FinalTerms.atomIdxOf(head) == a_active) {
                const mode = switch (rs.active) {
                    1 => FinalTerms.atom(&m.ctx, try self.atoms.intern("once")),
                    2 => FinalTerms.atom(&m.ctx, m.bool_true),
                    else => FinalTerms.atom(&m.ctx, m.bool_false),
                };
                pairs[n] = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, a_active), mode });
                n += 1;
            }
            // any other requested opt is OMITTED (FM-OBS-1: never fabricate an unmodeled value)
        }
        var list = FinalTerms.nil(&m.ctx);
        var i: usize = n;
        while (i > 0) {
            i -= 1;
            list = try FinalTerms.cons(&m.ctx, pairs[i], list);
        }
        return self.okTuple(m, list);
    }

    /// `gen_udp:open(Port,_)` → `{ok, Socket}` bound to loopback:ephemeral.
    fn doGenUdpOpen(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        const fd = socket_algebra.udpSocket() catch |e| return self.errTuple(m, posixName(e));
        const port = socket_algebra.udpBindEphemeral(fd) catch |e| {
            socket_algebra.close(fd);
            return self.errTuple(m, posixName(e));
        };
        return self.okTuple(m, try self.addSocket(m, fd, .udp, port));
    }

    /// `gen_udp:send(Socket, loopback, Port, Data)` → `ok` | `{error, Posix}`.
    fn doGenUdpSend(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term, port_term: FinalTerms.Term, data: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        if (FinalTerms.kindOf(&m.ctx, port_term) != .number) return self.errTuple(m, "einval");
        const port: u16 = @intCast(@as(u64, @bitCast(FinalTerms.smallValOf(port_term))) & 0xffff);
        const bin = FinalTerms.iolistToBinary(&m.ctx, data) catch return self.badargAtom(m);
        const bytes = FinalTerms.binBytes(&m.ctx, bin);
        if (bytes.len > 32 * 1024) return self.badargAtom(m);
        socket_algebra.udpSendTo(rs.fd, bytes, port) catch |e| return self.errTuple(m, posixName(e));
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    /// `gen_udp:recv(Socket, Length)` → `{ok, {Address, Port, Packet}}` (passive).
    /// Bounded (poll-timeout). Address is the loopback tuple `{127,0,0,1}`; Port is
    /// modeled as 0 (the sender's ephemeral port is not observed on the recv path).
    fn doGenUdpRecv(self: *Vm, m: *ia.Machine, sock_term: FinalTerms.Term) !FinalTerms.Term {
        const rs = self.socketOf(m, sock_term) orelse return self.errTuple(m, "closed");
        var buf: [2048]u8 = undefined;
        // poll-bound then recvfrom (udpRecv itself blocks; guard with poll first)
        const fd = rs.fd;
        var pfd = [_]std.os.linux.pollfd{.{ .fd = fd, .events = std.os.linux.POLL.IN, .revents = 0 }};
        const pr = std.os.linux.poll(&pfd, 1, 200);
        if (std.posix.errno(pr) != .SUCCESS) return self.errTuple(m, "einval");
        if (pr == 0) return self.errTuple(m, "timeout");
        const n = socket_algebra.udpRecv(fd, buf[0..]) catch |e| return self.errTuple(m, posixName(e));
        const addr = try FinalTerms.tuple(&m.ctx, &.{
            FinalTerms.int(&m.ctx, 127), FinalTerms.int(&m.ctx, 0),
            FinalTerms.int(&m.ctx, 0),   FinalTerms.int(&m.ctx, 1),
        });
        const packet = try FinalTerms.binary(&m.ctx, buf[0..n]);
        const triple = try FinalTerms.tuple(&m.ctx, &.{ addr, FinalTerms.int(&m.ctx, 0), packet });
        return self.okTuple(m, triple);
    }

    /// `erts_internal:port_close(Port)` — retire the port and reap its child.
    /// Returns `true`; a closed/absent port is inert `true` (BEAM-close is
    /// idempotent from the caller's view).
    fn doPortClose(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term) FinalTerms.Term {
        if (self.portOf(m, port_term)) |rp| {
            rp.live.deinit(); // close fds + reap the child (bounded)
            rp.alive = false;
        }
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// `erlang:port_set_data(Port, Term)` — store an opaque term on the port
    /// (copied into the OWNER's heap). Returns `true`; a bad port → `badarg`.
    fn doPortSetData(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term, data: FinalTerms.Term) FinalTerms.Term {
        const rp = self.portOf(m, port_term) orelse return self.badargAtom(m);
        const owner = self.proc(rp.connected) orelse return self.badargAtom(m);
        rp.data = FinalTerms.gcCopy(&owner.machine.ctx, &m.ctx, data) catch return self.badargAtom(m);
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// `erlang:port_get_data(Port)` — read back the stored term (copied into the
    /// CALLER's heap); `undefined` if unset; `badarg` on a bad port.
    fn doPortGetData(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term) !FinalTerms.Term {
        const rp = self.portOf(m, port_term) orelse return self.badargAtom(m);
        const stored = rp.data orelse return FinalTerms.atom(&m.ctx, try self.atoms.intern("undefined"));
        const owner = self.proc(rp.connected) orelse return self.badargAtom(m);
        return try FinalTerms.gcCopy(&m.ctx, &owner.machine.ctx, stored);
    }

    /// E6.7: `erlang:ports/0` — every live port as a Port term, in the CALLER's
    /// heap (fresh port terms; the Port VALUE is observed only by membership).
    fn doPortsList(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        var acc = FinalTerms.nil(&m.ctx);
        var i: usize = self.ports.items.len;
        while (i > 0) {
            i -= 1;
            const rp = self.ports.items[i];
            if (!rp.alive) continue;
            const pt = try FinalTerms.port(&m.ctx, rp.number);
            acc = try FinalTerms.cons(&m.ctx, pt, acc);
        }
        return acc;
    }

    /// E6.7: a single `port_info/2` item value for `rp`, built in `m.ctx`.
    /// Supports the representation-observable items; an unmodeled item → null
    /// (the caller maps that to `badarg`, erts' behavior for an unknown item).
    fn charlistTerm(ctx: *FinalTerms.Ctx, s: []const u8) !FinalTerms.Term {
        var acc = FinalTerms.nil(ctx);
        var i = s.len;
        while (i > 0) {
            i -= 1;
            acc = try FinalTerms.cons(ctx, FinalTerms.int(ctx, s[i]), acc);
        }
        return acc;
    }

    fn portInfoItemValue(self: *Vm, m: *ia.Machine, rp: *const RunPort, item_name: []const u8) !?FinalTerms.Term {
        if (std.mem.eql(u8, item_name, "name")) return try charlistTerm(&m.ctx, rp.name);
        if (std.mem.eql(u8, item_name, "id")) return FinalTerms.int(&m.ctx, @intCast(rp.number));
        if (std.mem.eql(u8, item_name, "connected")) return try FinalTerms.pid(&m.ctx, rp.connected, 0);
        if (std.mem.eql(u8, item_name, "links")) {
            const cp = try FinalTerms.pid(&m.ctx, rp.connected, 0);
            return try FinalTerms.cons(&m.ctx, cp, FinalTerms.nil(&m.ctx));
        }
        if (std.mem.eql(u8, item_name, "input")) return FinalTerms.int(&m.ctx, 0);
        if (std.mem.eql(u8, item_name, "output")) return FinalTerms.int(&m.ctx, 0);
        _ = self;
        return null;
    }

    /// E6.7: `erlang:port_info/1,2`. `port_info/1` (item == nil) → the info
    /// proplist; `port_info/2` → `{Item, Value}`. A dead/absent port → the atom
    /// `undefined` (erts' contract); an unknown /2 item → `badarg`.
    fn doPortInfo(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term, item: FinalTerms.Term) !FinalTerms.Term {
        const rp = self.portOf(m, port_term) orelse
            return FinalTerms.atom(&m.ctx, try self.atoms.intern("undefined"));
        if (FinalTerms.kindOf(&m.ctx, item) == .nil) {
            // port_info/1: the proplist [{name,_},{links,_},{id,_},{connected,_},{input,0},{output,0}].
            const keys = [_][]const u8{ "name", "links", "id", "connected", "input", "output" };
            var acc = FinalTerms.nil(&m.ctx);
            var i: usize = keys.len;
            while (i > 0) {
                i -= 1;
                const kt = FinalTerms.atom(&m.ctx, try self.atoms.intern(keys[i]));
                const vt = (try self.portInfoItemValue(m, rp, keys[i])).?;
                const pair = try FinalTerms.tuple(&m.ctx, &.{ kt, vt });
                acc = try FinalTerms.cons(&m.ctx, pair, acc);
            }
            return acc;
        }
        // port_info/2.
        if (!FinalTerms.repIsAtom(item)) return self.badargAtom(m);
        const item_name = self.atoms.nameOf(FinalTerms.atomIdxOf(item));
        const vt = (try self.portInfoItemValue(m, rp, item_name)) orelse return self.badargAtom(m);
        const kt = FinalTerms.atom(&m.ctx, FinalTerms.atomIdxOf(item));
        return try FinalTerms.tuple(&m.ctx, &.{ kt, vt });
    }

    /// E6.7: `erts_internal:port_connect(Port, Pid)` — reassign the port's
    /// connected (owner) process to a LIVE local `Pid`. Returns `true`; `badarg`
    /// on a bad/absent port or a non-live-pid target (erts' contract).
    fn doPortConnect(self: *Vm, m: *ia.Machine, port_term: FinalTerms.Term, pid_term: FinalTerms.Term) FinalTerms.Term {
        const rp = self.portOf(m, port_term) orelse return self.badargAtom(m);
        const target = pidOfTerm(&m.ctx, pid_term) orelse return self.badargAtom(m);
        const tp = self.proc(target) orelse return self.badargAtom(m);
        if (!tp.alive) return self.badargAtom(m);
        rp.connected = target;
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// E6.7: `ets:give_away(Tab, Pid, Gift)` — reassign the table's owner to the
    /// LIVE local `Pid` (≠ the caller, which must be the current owner) and
    /// deliver `{'ETS-TRANSFER', Tab, From, Gift}` to it. Returns `true`;
    /// `badarg` on a bad table / non-owner caller / non-live-pid / self target.
    /// The table lives on the CALLER's Machine (single-Machine ETS scope); this
    /// moves the OWNER field + delivers the signal — the recipient observes the
    /// transfer message (its cross-Machine ACCESS to the table stays a shared-ETS
    /// follow-on, but the ownership transfer + delivery are fully modeled).
    fn doEtsGiveAway(self: *Vm, pid: Pid, m: *ia.Machine, tid: FinalTerms.Term, to: FinalTerms.Term, gift: FinalTerms.Term) !FinalTerms.Term {
        const t = ets_bifs.resolveTable(m, tid) catch return self.badargAtom(m);
        if (t.owner != m.self_pid) return self.badargAtom(m); // caller must own it
        const target = pidOfTerm(&m.ctx, to) orelse return self.badargAtom(m);
        if (target == m.self_pid) return self.badargAtom(m); // cannot give to self
        const tp = self.proc(target) orelse return self.badargAtom(m);
        if (!tp.alive) return self.badargAtom(m);
        // Reassign the owner (the registry half; contents untouched).
        t.owner = target;
        // Deliver {'ETS-TRANSFER', Tab, From, Gift} to the recipient, built in ITS heap.
        const rm = &tp.machine.ctx;
        const et = FinalTerms.atom(rm, try self.atoms.intern("ETS-TRANSFER"));
        const tab_o = try FinalTerms.gcCopy(rm, &m.ctx, tid);
        const from_o = try FinalTerms.pid(rm, m.self_pid, 0);
        const gift_o = try FinalTerms.gcCopy(rm, &m.ctx, gift);
        const msg = try FinalTerms.tuple(rm, &.{ et, tab_o, from_o, gift_o });
        try self.signal(pid, target, .{ .message = msg });
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// E5.5: `unalias/1` — deactivate a CALLER-owned active alias. Returns `true`
    /// iff `ref_term` named a currently-active alias of this process (erts
    /// contract); a non-ref, an alias owned by another process, or an
    /// already-retired alias → `false`. Process-local: only the caller's table
    /// is ever touched (Mutant 1: leave the entry active → the retirement law
    /// reddens — a post-`unalias` send would still be delivered).
    fn doUnalias(self: *Vm, p: *Process, ref_term: FinalTerms.Term) bool {
        _ = self;
        if (!FinalTerms.repIsRef(&p.machine.ctx, ref_term)) return false;
        const key = keyFromRefWords(FinalTerms.refWords(&p.machine.ctx, ref_term));
        for (p.aliases.items) |*a| {
            if (a.key == key and a.active) {
                a.active = false;
                return true;
            }
        }
        return false;
    }

    /// E5.5: `erts_internal:is_process_alive/2` — the ASYNC form of
    /// `is_process_alive/1`. Sends the caller a genuine mailbox message
    /// `{Ref, boolean()}` (the alive result of `pid`), then returns `ok` in x0.
    /// The reply is built in the CALLER's heap and enqueued through the same
    /// stamped signal path as any message (the sacred per-pair order untouched),
    /// then drained INTO the mailbox synchronously so the caller's following
    /// `receive {Ref, _}` finds it (the io_reply precedent — an async reply the
    /// caller then selectively receives). Reply sender = the checked pid if live,
    /// else the caller itself (erts replies from `am_system` when dead).
    fn doIsAliveRequest(self: *Vm, pid: Pid, m: *ia.Machine, pid_term: FinalTerms.Term, ref_term: FinalTerms.Term) !FinalTerms.Term {
        const to = pidOfTerm(&m.ctx, pid_term);
        const alive = to != null and self.proc(to.?) != null;
        const ref_copy = try FinalTerms.ref(&m.ctx, FinalTerms.refWords(&m.ctx, ref_term));
        const res = FinalTerms.atom(&m.ctx, if (alive) m.bool_true else m.bool_false);
        const reply = try FinalTerms.tuple(&m.ctx, &.{ ref_copy, res });
        const from: Pid = if (alive) to.? else pid;
        try self.signal(from, pid, .{ .message = reply });
        try self.drainSignals(pid); // deliver into the mailbox for the caller's receive
        return FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
    }

    // ---- E4.6 (Task 6): the io / group-leader message protocol. ----
    //
    // Semantic domain: an `{io_request, From, ReplyAs, Request}` message
    // delivered to a group-leader io fixture maps to (a) an EFFECT on the Vm's
    // captured stdout sink (`put_chars` appends the flattened chars; `get_line`
    // consumes a line of the input tape) and (b) EXACTLY ONE reply
    // `{io_reply, ReplyAs, Reply}` sent back to From. `serviceGroupLeader` is the
    // oracle of that map; `doIoRequest` is the synchronous BIF driver that rides
    // it (both io_request and io_reply genuinely traverse mailboxes).

    /// E4.6: spawn a PASSIVE group-leader io fixture (the `user`/`standard_io`
    /// server). Returns its pid. It runs no code (`.suspended`, `io_gl = true`),
    /// so the scheduler never grants it and quiescence is unaffected; it is
    /// serviced only by `serviceGroupLeader`. Callers point a process's
    /// `machine.group_leader` at the returned pid to route that process's io.
    pub fn installGroupLeader(self: *Vm, prog: ia.Program) !Pid {
        const gl = try self.spawn(prog, 0, null);
        const p = self.procs.items[gl];
        p.io_gl = true;
        p.machine.status = .suspended; // never scheduled
        p.machine.group_leader = gl; // a GL is its own group leader
        return gl;
    }

    /// E4.6: append `w` (a char, a charlist, a binary, or an iolist of those)
    /// to `out` as raw bytes. Bounded (a total-node budget guards against a
    /// cyclic/huge structure — a hang would be a failed law). A code point > 255
    /// is UTF-8 encoded (the `unicode` put_chars encoding); a plain byte 0..255
    /// is emitted verbatim. Silently stops at the budget (never a crash/UAF).
    fn flattenChars(ctx: *FinalTerms.Ctx, w: FinalTerms.Term, out: *std.ArrayList(u8), gpa: std.mem.Allocator, budget: *usize) !void {
        if (budget.* == 0) return;
        budget.* -= 1;
        switch (FinalTerms.kindOf(ctx, w)) {
            .number => {
                if (!FinalTerms.repIsSmall(w)) return; // bignum/float — not a char
                const v = FinalTerms.smallValOf(w);
                if (v < 0) return; // not a char — skip (bounded, no crash)
                if (v < 0x80) {
                    try out.append(gpa, @intCast(v));
                } else {
                    var buf: [4]u8 = undefined;
                    const cp: u21 = if (v <= 0x10FFFF) @intCast(v) else return;
                    const n = std.unicode.utf8Encode(cp, &buf) catch return;
                    try out.appendSlice(gpa, buf[0..n]);
                }
            },
            .binary => try out.appendSlice(gpa, FinalTerms.binBytes(ctx, w)),
            .nil => {},
            .cons => {
                var cur = w;
                while (FinalTerms.kindOf(ctx, cur) == .cons and budget.* > 0) {
                    try flattenChars(ctx, FinalTerms.listHead(ctx, cur), out, gpa, budget);
                    cur = FinalTerms.listTail(ctx, cur);
                }
            },
            else => {}, // any other term contributes nothing (bounded)
        }
    }

    /// E4.6: service EVERY `{io_request, From, ReplyAs, Request}` message sitting
    /// in group leader `gl`'s mailbox, in arrival order. For each: apply the
    /// Request's effect (`{put_chars,Chars}` / `{put_chars,Enc,Chars}` → append to
    /// `io_output`; `{get_line,_}` / `{get_line,_,_}` → next input line or `eof`),
    /// then send EXACTLY ONE `{io_reply, ReplyAs, Reply}` back to From (the reply
    /// carries the SAME ReplyAs — the protocol law). Returns the count serviced.
    /// A message that is not a well-formed io_request is left in place (untouched).
    pub fn serviceGroupLeader(self: *Vm, gl: Pid) !usize {
        try self.drainSignals(gl); // move any queued io_request signals into the mbox
        const p = self.proc(gl) orelse return 0;
        const gm = &p.machine;
        const a_io_request = try self.atoms.intern("io_request");
        const a_io_reply = try self.atoms.intern("io_reply");
        var serviced: usize = 0;
        var i: usize = 0;
        while (try gm.mbox.peekAt(i)) |msg| {
            const req = msg.payload;
            if (!(FinalTerms.kindOf(&gm.ctx, req) == .tuple and FinalTerms.tupleArity(&gm.ctx, req) == 4 and
                FinalTerms.repIsAtom(FinalTerms.tupleElem(&gm.ctx, req, 0)) and
                FinalTerms.atomIdxOf(FinalTerms.tupleElem(&gm.ctx, req, 0)) == a_io_request))
            {
                i += 1; // not an io_request — leave it, advance past it
                continue;
            }
            const from_term = FinalTerms.tupleElem(&gm.ctx, req, 1);
            const reply_as = FinalTerms.tupleElem(&gm.ctx, req, 2);
            const request = FinalTerms.tupleElem(&gm.ctx, req, 3);
            const reply = try self.applyIoRequest(gm, request);
            // {io_reply, ReplyAs, Reply}, copied cross-heap into From's heap, then
            // signalled — exactly ONE reply per io_request (the protocol law).
            if (pidOfTerm(&gm.ctx, from_term)) |from| {
                if (self.proc(from)) |fp| {
                    const fc = &fp.machine.ctx;
                    const tup = try FinalTerms.tuple(fc, &.{
                        FinalTerms.atom(fc, a_io_reply),
                        try FinalTerms.gcCopy(fc, &gm.ctx, reply_as),
                        try FinalTerms.gcCopy(fc, &gm.ctx, reply),
                    });
                    try self.signal(gl, from, .{ .message = tup });
                }
            }
            try gm.mbox.removeAt(i); // consume the serviced request (do not advance i)
            serviced += 1;
        }
        return serviced;
    }

    /// E4.6: apply ONE io Request against the sink/input, returning the Reply
    /// term (built in the group leader's heap `gm.ctx`). Unknown requests reply
    /// with `{error, request}` — never a crash. **Mutant m2 site:** `put_chars`
    /// must flatten via `flattenChars` (the diag/erts term-writer shape); a wrong
    /// writer here reddens the io-round-trip differential.
    fn applyIoRequest(self: *Vm, gm: *ia.Machine, request: FinalTerms.Term) !FinalTerms.Term {
        const ok = FinalTerms.atom(&gm.ctx, try self.atoms.intern("ok"));
        if (FinalTerms.kindOf(&gm.ctx, request) != .tuple or FinalTerms.tupleArity(&gm.ctx, request) < 1)
            return FinalTerms.tuple(&gm.ctx, &.{ FinalTerms.atom(&gm.ctx, try self.atoms.intern("error")), FinalTerms.atom(&gm.ctx, try self.atoms.intern("request")) });
        const head = FinalTerms.tupleElem(&gm.ctx, request, 0);
        if (!FinalTerms.repIsAtom(head))
            return FinalTerms.atom(&gm.ctx, try self.atoms.intern("ok"));
        const name = self.atoms.nameOf(FinalTerms.atomIdxOf(head));
        const ar = FinalTerms.tupleArity(&gm.ctx, request);
        if (std.mem.eql(u8, name, "put_chars")) {
            // {put_chars, Chars} | {put_chars, Enc, Chars} | {put_chars, M,F,As}
            // The Chars are the LAST element for the 2/3-arity forms; the M,F,As
            // apply form (arity 4) is out of scope (reply ok, no output).
            const chars = if (ar == 2) FinalTerms.tupleElem(&gm.ctx, request, 1) else if (ar == 3) FinalTerms.tupleElem(&gm.ctx, request, 2) else return ok;
            var budget: usize = 1_000_000;
            try flattenChars(&gm.ctx, chars, &self.io_output, self.gpa, &budget);
            return ok;
        }
        if (std.mem.eql(u8, name, "get_line") or std.mem.eql(u8, name, "get_until")) {
            // Consume up to and including the next '\n' from the input tape; at
            // EOF reply with the atom `eof` (BEAM's io protocol reply).
            if (self.io_input_cursor >= self.io_input.len)
                return FinalTerms.atom(&gm.ctx, try self.atoms.intern("eof"));
            const rest = self.io_input[self.io_input_cursor..];
            const nl = std.mem.indexOfScalar(u8, rest, '\n');
            const line_end = if (nl) |k| k + 1 else rest.len;
            const line = rest[0..line_end];
            self.io_input_cursor += line_end;
            // reply as a charlist (the get_line list form)
            var lst = FinalTerms.nil(&gm.ctx);
            var j = line.len;
            while (j > 0) {
                j -= 1;
                lst = try FinalTerms.cons(&gm.ctx, FinalTerms.int(&gm.ctx, line[j]), lst);
            }
            return lst;
        }
        return ok; // setopts/getopts/etc: acknowledged, no effect
    }

    /// E4.6: the synchronous BIF driver for `io:put_chars`/`io:nl` (bifs/io.zig).
    /// Routes the caller's io `request` to its GROUP LEADER as a real
    /// `{io_request, From, ReplyAs, Request}` message, services the group leader
    /// (which appends output and replies), then reads the single
    /// `{io_reply, ReplyAs, Reply}` back out of the caller's mailbox and returns
    /// Reply for x0. ReplyAs is a fresh per-call token (a small int) so the reply
    /// is matched by identity — **mutant m1** drops that tag and the read fails.
    fn doIoRequest(self: *Vm, pid: Pid, m: *ia.Machine, request: FinalTerms.Term) !FinalTerms.Term {
        const ok = FinalTerms.atom(&m.ctx, try self.atoms.intern("ok"));
        const gl = m.group_leader;
        // A process that is its OWN group leader with no io fixture cannot service
        // io (there is no server) — reply `ok` without output rather than loop.
        const glp = self.proc(gl) orelse return ok;
        if (gl == pid or !glp.io_gl) return ok;
        const a_io_request = try self.atoms.intern("io_request");
        const reply_as: FinalTerms.Term = FinalTerms.int(&m.ctx, @as(i64, @intCast(self.next_stamp.load(.monotonic))) + 1);
        // Build {io_request, From, ReplyAs, Request} in the GROUP LEADER's heap.
        const gc = &glp.machine.ctx;
        const req_msg = try FinalTerms.tuple(gc, &.{
            FinalTerms.atom(gc, a_io_request),
            try FinalTerms.pid(gc, pid, 0),
            try FinalTerms.gcCopy(gc, &m.ctx, reply_as),
            try FinalTerms.gcCopy(gc, &m.ctx, request),
        });
        try self.signal(pid, gl, .{ .message = req_msg });
        _ = try self.serviceGroupLeader(gl);
        try self.drainSignals(pid); // move the io_reply into the caller's mailbox
        // Read the single {io_reply, ReplyAs, Reply} whose ReplyAs matches.
        const a_io_reply = try self.atoms.intern("io_reply");
        var i: usize = 0;
        while (try m.mbox.peekAt(i)) |msg| : (i += 1) {
            const r = msg.payload;
            if (FinalTerms.kindOf(&m.ctx, r) == .tuple and FinalTerms.tupleArity(&m.ctx, r) == 3 and
                FinalTerms.repIsAtom(FinalTerms.tupleElem(&m.ctx, r, 0)) and
                FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, r, 0)) == a_io_reply and
                FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, r, 1), reply_as))
            {
                const reply = FinalTerms.tupleElem(&m.ctx, r, 2);
                try m.mbox.removeAt(i);
                return reply;
            }
        }
        return ok; // no matching reply (should not happen with a live fixture)
    }

    // ---- E3.8 helpers: link/monitor/registry BIF-family bodies (kept out of
    // the `interpret` switch above for readability; each is a pure function of
    // (self, the caller's process/machine, the resolved arguments) that returns
    // the x0 RESULT term — the same convention as every other trap here). ----

    // gap-erlang-cover-registry (DIVERGENCE 658): register/2 RAISES `error:badarg`
    // on every rejection (a non-atom name, the reserved `undefined` name, a
    // non-pid/dead target, a name already in use, an already-registered pid) — it
    // does NOT return `false`. OTP's `register/2` is a raising BIF; returning
    // `false` let `catch register(...)` (the gen_server/global name-claim idiom)
    // silently succeed where OTP faults. Curation-found via eco_registry.
    fn doRegister(self: *Vm, m: *ia.Machine, pid: Pid, name: FinalTerms.Term, target_term: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(name)) return error.Badarg;
        // `undefined` is RESERVED — it is whereis/1's not-registered sentinel, so
        // a process may never claim it (OTP raises badarg).
        if (std.mem.eql(u8, self.atoms.nameOf(FinalTerms.atomIdxOf(name)), "undefined")) return error.Badarg;
        const target = pidOfTerm(&m.ctx, target_term) orelse return error.Badarg;
        const alive = self.proc(target) != null;
        _ = pid;
        self.registry.register(FinalTerms.atomIdxOf(name), target, alive) catch |e| switch (e) {
            error.BadArg => return error.Badarg,
            else => return e,
        };
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    // gap-erlang-cover-registry (DIVERGENCE 658): unregister/1 RAISES `error:badarg`
    // for a non-atom name or a name that is not currently registered — it does NOT
    // return `false` (OTP's `unregister/1` is a raising BIF).
    fn doUnregister(self: *Vm, m: *ia.Machine, name: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(name)) return error.Badarg;
        const idx = FinalTerms.atomIdxOf(name);
        const was_net_kernel = std.mem.eql(u8, self.atoms.nameOf(idx), "net_kernel");
        self.registry.unregister(idx) catch return error.Badarg;
        if (was_net_kernel) try self.clearDistLocalIdentity();
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    fn doWhereis(self: *Vm, m: *ia.Machine, name: FinalTerms.Term) !FinalTerms.Term {
        if (FinalTerms.repIsAtom(name)) {
            if (self.registry.whereis(FinalTerms.atomIdxOf(name))) |target| {
                return try FinalTerms.pid(&m.ctx, target, 0);
            }
        }
        const idx = try self.atoms.intern("undefined");
        return FinalTerms.atom(&m.ctx, idx);
    }

    /// e4-registered0: `registered/0` — the SORTED list of registered name
    /// atoms. Sorted by NAME (not by `registry.zig`'s internal `AtomIdx`
    /// HashMap iteration order) — the exact `erlang:loaded/0` ORDER-FREEDOM
    /// discipline (bifs/code.zig): a HashMap iteration order must never leak
    /// into an observable result.
    fn doListRegistered(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        // gap-b-2: snapshot the registered name atoms atomically under L_reg
        // (instead of iterating `by_name` directly), so the whole-table read
        // can't tear against a concurrent register/unregister.
        var name_idxs: std.ArrayList(registry.Name) = .empty;
        defer name_idxs.deinit(self.gpa);
        self.registry.snapshotNames(&name_idxs, self.gpa) catch return error.OutOfMemory;
        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.gpa);
        for (name_idxs.items) |k| names.append(self.gpa, self.atoms.nameOf(k)) catch return error.OutOfMemory;

        std.mem.sort([]const u8, names.items, {}, struct {
            fn lt(_: void, a: []const u8, b: []const u8) bool {
                return std.mem.lessThan(u8, a, b);
            }
        }.lt);

        var acc = FinalTerms.nil(&m.ctx);
        var i = names.items.len;
        while (i > 0) {
            i -= 1;
            const idx = m.ctx.atoms.intern(names.items[i]) catch return error.OutOfMemory;
            acc = FinalTerms.cons(&m.ctx, FinalTerms.atom(&m.ctx, idx), acc) catch return error.OutOfMemory;
        }
        return acc;
    }

    /// A `{'DOWN', Ref, process, Pid, Reason}`-shaped tuple? (used by
    /// `doDemonitorFlush` to spot an already-delivered race DOWN).
    fn isDownTupleForRef(ctx: *FinalTerms.Ctx, t: FinalTerms.Term, ref: u64, a_down: ta.AtomIdx) bool {
        if (FinalTerms.kindOf(ctx, t) != .tuple) return false;
        if (FinalTerms.tupleArity(ctx, t) != 5) return false;
        const tag = FinalTerms.tupleElem(ctx, t, 0);
        if (!FinalTerms.repIsAtom(tag) or FinalTerms.atomIdxOf(tag) != a_down) return false;
        const refelem = FinalTerms.tupleElem(ctx, t, 1);
        if (!FinalTerms.repIsRef(ctx, refelem)) return false;
        const got: u64 = keyFromRefWords(FinalTerms.refWords(ctx, refelem));
        return got == ref;
    }

    /// `demonitor(Ref, [flush])`: cancel the monitor (same bookkeeping as
    /// `demonitor_ref`) AND clear any race 'DOWN' for this ref — whether it is
    /// still queued (signaled but not yet drained) or already delivered to the
    /// mailbox. Mutant 1 targets exactly this: if the already-delivered case is
    /// skipped, a DOWN can be observed even after a `[flush]` demonitor raced
    /// the exit — the exactly-once law (procsys.zig) catches it.
    fn doDemonitorFlush(self: *Vm, p: *Process, m: *ia.Machine, ref_term: FinalTerms.Term, info: bool) !FinalTerms.Term {
        // E3.8-fix: `ref_term` is now a genuine boxed ref; decode via its words.
        if (!FinalTerms.repIsRef(&m.ctx, ref_term)) return FinalTerms.atom(&m.ctx, m.bool_true);
        const ref: u64 = keyFromRefWords(FinalTerms.refWords(&m.ctx, ref_term));
        var existed = false;
        // (1) standard demonitor bookkeeping: forget the monitor on both sides.
        for (p.monitors_held.items, 0..) |mh, k| {
            if (mh.ref == ref) {
                existed = true;
                if (self.proc(mh.target)) |t| {
                    for (t.monitored_by.items, 0..) |mb, j| {
                        if (mb.ref == ref) {
                            _ = t.monitored_by.swapRemove(j);
                            break;
                        }
                    }
                }
                _ = p.monitors_held.swapRemove(k);
                break;
            }
        }
        // (2) a DOWN signal for this ref may already be enqueued but not yet
        // drained (the race window) — drop it before it is ever observed.
        // S-epoch Option B: the sweep mutates `sigq` → `L_sigq`-guarded (a
        // concurrent sender's append must not interleave with the swapRemove).
        {
            p.sigq_lock.lock();
            defer p.sigq_lock.unlock();
            var i: usize = 0;
            while (i < p.sigq.items.len) {
                if (p.sigq.items[i].sig == .down and p.sigq.items[i].sig.down.ref == ref) {
                    // N8: the DOWN's reason rides a fragment — free it before
                    // the entry is dropped (zero-leak sweep).
                    self.freeSigFragment(&p.sigq.items[i]);
                    _ = p.sigq.swapRemove(i);
                } else i += 1;
            }
        }
        // (3) a DOWN for this ref may ALREADY be sitting in the mailbox
        // (delivered before `demonitor` ran) — flush removes it too.
        var buf: [256]mba.Msg(FinalTerms) = undefined;
        const q = m.mbox.toSeq(&buf);
        var found: ?usize = null;
        for (q, 0..) |msg, k| {
            if (isDownTupleForRef(&m.ctx, msg.payload, ref, self.a_down)) {
                found = k;
                break;
            }
        }
        if (found) |k| try m.mbox.removeAt(k);
        if (info) {
            return FinalTerms.atom(&m.ctx, if (existed) m.bool_true else m.bool_false);
        } else {
            return FinalTerms.atom(&m.ctx, m.bool_true);
        }
    }

    // ========================================================================
    // E6.4 (Task 4) / gap-b-6a: the process-suspension family (bifs/procsys.zig traps).
    // The suspend/resume COUNTING MONOID over the `L_c`-domain `Vm.suspend_a[pid]`,
    // gated by `schedulable`. A live target's count is incremented by suspend and
    // decremented by resume; `resume_process` on a NON-suspended (count 0) target
    // raises `badarg` (real BEAM's contract, host-verified on OTP-28). An absent
    // target pid also raises `badarg`. These write true|badarg to x0.
    // gap-b-6a: the count is mutated under `L_c` (not just the caller's `L_v`) — the
    // TARGET may be OWNED + running on another worker, whose `L_c`-alone epilogue reads
    // `suspend_a[target]` to gate the requeue; both sides serialize on `L_c`, so a
    // suspend of a running proc takes effect at its next scheduling point (async
    // suspend), never a torn read that requeues a suspended proc.
    // ========================================================================

    /// `erts_internal:suspend_process/2` → `true` on a live target (increments the
    /// suspend count; nested suspends stack — the monoid). Bad/absent pid → badarg.
    fn doSuspend(self: *Vm, m: *ia.Machine, pid_term: FinalTerms.Term) FinalTerms.Term {
        const to = pidOfTerm(&m.ctx, pid_term);
        if (to == null or self.proc(to.?) == null) return self.badargTerm(m);
        self.l_c.lock(); // gap-b-6a: `suspend_a` is `L_c`-domain
        _ = self.suspend_a.items[to.?].fetchAdd(1, .monotonic);
        self.l_c.unlock();
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// `erlang:resume_process/1` → `true` on a SUSPENDED target (decrements the
    /// count; the last matching resume makes it schedulable again). A non-suspended
    /// (count 0) or bad/absent target → badarg (the monoid's balance guard: resume
    /// can never drive the count below zero — Mutant 1's target).
    fn doResume(self: *Vm, m: *ia.Machine, pid_term: FinalTerms.Term) FinalTerms.Term {
        const to = pidOfTerm(&m.ctx, pid_term);
        if (to == null or self.proc(to.?) == null) return self.badargTerm(m);
        // gap-b-6a: the balance guard + decrement + push-based re-enqueue are ONE
        // `L_c` section — `suspend_a` (the count) and `ready`/`queued`/`owned` (the
        // enqueue) are all `L_c`-domain, so the check-then-act is atomic against a
        // concurrent worker's `L_c`-alone epilogue reading `suspend_a[to]`.
        self.l_c.lock();
        defer self.l_c.unlock();
        if (self.suspend_a.items[to.?].load(.monotonic) == 0) return self.badargTerm(m); // never below zero
        _ = self.suspend_a.items[to.?].fetchSub(1, .monotonic);
        // push-based discovery — the LAST matching resume makes the target schedulable
        // again; enqueue it onto the ready inbox (the old scanning `discover` re-found
        // it every tick). Idempotent via `enqueueReadyLocked`: no-op if the target is
        // still OWNED (its owner requeues it at release, having re-read the now-0 count
        // under `L_c`), already queued, or still count > 0. `enqueueReadyLocked` needs
        // `L_c` HELD (we hold it) — NOT `markSchedulable`, which would re-lock `L_c`.
        // Best-effort on OOM (this BIF returns a value, not an error union).
        self.enqueueDirect(to.?) catch {};
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// `erts_internal:is_system_process/1` → `true` iff the target pid is a SYSTEM
    /// process (`Process.system`, set by `spawn_system_process/3`), else `false`.
    /// A non-pid arg was rejected synchronously in the BIF; an absent pid → badarg.
    fn doIsSystemProcess(self: *Vm, m: *ia.Machine, pid_term: FinalTerms.Term) FinalTerms.Term {
        const to = pidOfTerm(&m.ctx, pid_term);
        if (to == null or self.proc(to.?) == null) return self.badargTerm(m);
        const is_sys = self.procs.items[to.?].system;
        return FinalTerms.atom(&m.ctx, if (is_sys) m.bool_true else m.bool_false);
    }

    /// A synchronous `badarg` VALUE written to x0 (the Vm cannot unwind the caller's
    /// stack to RAISE, the register_2/group_leader_2 bool-not-raise precedent). The
    /// suspend/resume corpus differential catches these via the atom, not an
    /// exception — both VMs fold the `badarg` return identically (a `try ... catch`
    /// in the corpus case, so the value is representation-free).
    fn badargTerm(self: *Vm, m: *ia.Machine) FinalTerms.Term {
        _ = self;
        return FinalTerms.atom(&m.ctx, m.ctx.atoms.intern("badarg") catch m.bool_false);
    }

    const proc_info_items = [_][]const u8{ "status", "links", "monitors", "registered_name", "messages", "dictionary" };

    /// Build the VALUE for one documented `process_info` item (see the
    /// procsys.zig BIF doc comment for the exact subset + the entry-9(d)
    /// unsupported-item precedent — item-name VALIDATION happens synchronously
    /// in procsys.zig before the trap is ever set, so every `item_name` reaching
    /// here is guaranteed supported). `target`'s terms are copied into the
    /// CALLER's heap (`m.ctx`) — the same cross-heap copy discipline as
    /// `messages`/`send_to` elsewhere in this file.
    fn procInfoValue(self: *Vm, m: *ia.Machine, target: *Process, target_pid: Pid, item_name: []const u8) !FinalTerms.Term {
        if (std.mem.eql(u8, item_name, "status")) {
            // E6.4 (Task 4): a BIF-suspended process reports `suspended` regardless
            // of its receive/run state (erts' `process_info(Pid, status)` contract),
            // so the suspension family's effect is visible through process_info too.
            const s: []const u8 = if (self.suspend_a.items[target_pid].load(.monotonic) > 0) "suspended" else switch (target.machine.status) {
                .running => "running",
                .suspended => "waiting",
                .halted, .crashed => "exiting",
            };
            return FinalTerms.atom(&m.ctx, try self.atoms.intern(s));
        } else if (std.mem.eql(u8, item_name, "links")) {
            var list = FinalTerms.nil(&m.ctx);
            var i = target.links.items.len;
            while (i > 0) {
                i -= 1;
                const pt = try FinalTerms.pid(&m.ctx, target.links.items[i], 0);
                list = try FinalTerms.cons(&m.ctx, pt, list);
            }
            return list;
        } else if (std.mem.eql(u8, item_name, "monitors")) {
            var list = FinalTerms.nil(&m.ctx);
            var i = target.monitors_held.items.len;
            const process_atom = try self.atoms.intern("process");
            while (i > 0) {
                i -= 1;
                const mh = target.monitors_held.items[i];
                const tup = try FinalTerms.tuple(&m.ctx, &.{
                    FinalTerms.atom(&m.ctx, process_atom),
                    try FinalTerms.pid(&m.ctx, mh.target, 0),
                });
                list = try FinalTerms.cons(&m.ctx, tup, list);
            }
            return list;
        } else if (std.mem.eql(u8, item_name, "registered_name")) {
            // real erlang: `{registered_name, Name}` if registered, ELSE the
            // bare atom `[]` (NOT a `{registered_name, []}` tuple) — a caller
            // asking for this ONE item unregistered gets `[]` back directly.
            if (self.registry.nameOf(target_pid)) |name_idx| return FinalTerms.atom(&m.ctx, name_idx);
            return FinalTerms.nil(&m.ctx);
        } else if (std.mem.eql(u8, item_name, "messages")) {
            var buf: [256]mba.Msg(FinalTerms) = undefined;
            const q = target.machine.mbox.toSeq(&buf);
            var list = FinalTerms.nil(&m.ctx);
            var i = q.len;
            while (i > 0) {
                i -= 1;
                const copy = try FinalTerms.gcCopy(&m.ctx, &target.machine.ctx, q[i].payload);
                list = try FinalTerms.cons(&m.ctx, copy, list);
            }
            return list;
        } else if (std.mem.eql(u8, item_name, "message_queue_len")) {
            // E5.9: the number of messages currently in the target's mailbox —
            // an int scalar, byte-total against OTP's `{message_queue_len, N}`.
            var buf: [256]mba.Msg(FinalTerms) = undefined;
            const q = target.machine.mbox.toSeq(&buf);
            return FinalTerms.int(&m.ctx, @intCast(q.len));
        } else if (std.mem.eql(u8, item_name, "trap_exit")) {
            // E5.9: the target's trap_exit flag (Machine.trap_exit) — a bool.
            const b = if (target.machine.trap_exit) m.bool_true else m.bool_false;
            return FinalTerms.atom(&m.ctx, b);
        } else if (std.mem.eql(u8, item_name, "current_stacktrace")) {
            // DIVERGENCE 684 (fractal-sweep RANK 1): the target's CURRENT call
            // stack as `[{M,F,Arity,[{file,F},{line,L}]}]` — what OTP's
            // `?STACKTRACE()` reads (every gen_* behaviour error path). Built on
            // the TARGET's machine, then cross-heap-copied into the CALLER's heap
            // (same discipline as `messages`; a no-op-equivalent copy when the
            // target IS the caller — the common `process_info(self(), ...)` case).
            const st = try target.machine.currentStacktrace();
            return try FinalTerms.gcCopy(&m.ctx, &target.machine.ctx, st);
        } else if (std.mem.eql(u8, item_name, "current_function")) {
            // gap-procinfo-keys (DIVERGENCE 735): `{M, F, Arity}` of the target's
            // CURRENTLY-executing function — the HEAD frame's mfa (the same pc→loc
            // `currentStacktrace` reads). BYTE-EQ (the mfa is deterministic +
            // driver-independent). Atoms are GLOBAL, so the mfa is built directly in
            // the caller's ctx. `undefined` when the pc has no loc (an empty/hand-
            // built program, or an AUTOLOADED-module pc the frozen `locs` table does
            // not cover — the DIVERGENCE 730 locs-coverage residual).
            const tm = &target.machine;
            const hp: usize = if (tm.pc > 0) tm.pc - 1 else 0;
            if (tm.locs.len > 0 and hp < tm.locs.len) {
                const loc = tm.locs[hp];
                return try FinalTerms.tuple(&m.ctx, &.{
                    FinalTerms.atom(&m.ctx, loc.m),
                    FinalTerms.atom(&m.ctx, loc.f),
                    FinalTerms.int(&m.ctx, @intCast(loc.a)),
                });
            }
            return FinalTerms.atom(&m.ctx, try self.atoms.intern("undefined"));
        } else if (std.mem.eql(u8, item_name, "initial_call")) {
            // gap-procinfo-initial-call (DIVERGENCE 754): the {M,F,A} the target was
            // SPAWNED with — recorded at birth in `resolveSpawnMFA` (discharges the 735
            // `initial_call (needs a spawn-mfa field)` residual). BYTE-EQ vs OTP's PCB
            // `initial_call`: atoms are GLOBAL + the arity is exact. A process with NO
            // spawn MFA (the root/hand-built proc) defaults to OTP's documented
            // `{erlang, apply, 2}` (host-verified). Atoms are built directly in the
            // caller's ctx (global), so no cross-heap copy is needed.
            if (target.initial_call) |ic| {
                return try FinalTerms.tuple(&m.ctx, &.{
                    FinalTerms.atom(&m.ctx, ic.m),
                    FinalTerms.atom(&m.ctx, ic.f),
                    FinalTerms.int(&m.ctx, @intCast(ic.a)),
                });
            }
            return try FinalTerms.tuple(&m.ctx, &.{
                FinalTerms.atom(&m.ctx, try self.atoms.intern("erlang")),
                FinalTerms.atom(&m.ctx, try self.atoms.intern("apply")),
                FinalTerms.int(&m.ctx, 2),
            });
        } else if (std.mem.eql(u8, item_name, "catchlevel")) {
            // gap-procinfo-keys (DIVERGENCE 735): the count of the target's active
            // try/catch landing pads — a REAL function of state. EQUIV: the absolute
            // baseline is driver-coupled (OTP's `erl -eval` wrapper starts at 1; a
            // bare `zigvm run` proc at 0) but the DELTA per `try` is byte-EQ. Never a
            // fabricated constant.
            return FinalTerms.int(&m.ctx, @intCast(target.machine.catch_stack.items.len));
        } else if (std.mem.eql(u8, item_name, "reductions")) {
            // gap-procinfo-keys (DIVERGENCE 735): the reduction count — a REAL
            // function of state. EQUIV: zigvm's per-op reduction weights differ from
            // erts, so the absolute value is impl-specific (monotone, non-negative,
            // like erts — never a made-up constant, FM-OBS-1).
            return FinalTerms.int(&m.ctx, @intCast(target.machine.reductions));
        } else if (std.mem.eql(u8, item_name, "stack_size")) {
            // gap-procinfo-keys (DIVERGENCE 735): the target's stack depth (y-register
            // slots) — a REAL function of state. EQUIV: zigvm's stack layout is not
            // erts's word-for-word.
            return FinalTerms.int(&m.ctx, @intCast(target.machine.ystack.items.len));
        } else if (std.mem.eql(u8, item_name, "group_leader")) {
            // gap-procinfo-keys2 (DIVERGENCE 736): the target's group-leader pid — a
            // REAL value (the `group_leader` proc index). EQUIV: the pid NUMBER is
            // VM-run-specific (like every pid-valued item — links/monitors), never a
            // fabricated constant.
            return try FinalTerms.pid(&m.ctx, target.machine.group_leader, 0);
        } else if (std.mem.eql(u8, item_name, "monitored_by")) {
            // gap-procinfo-keys2 (DIVERGENCE 736): the pids MONITORING the target,
            // from its reverse-monitor list. `[]` when none (BYTE-EQ — the common
            // case), else a list of watcher pids (EQUIV pid numbers). Built head-first
            // (most-recent last, matching the append order reversed onto nil).
            var list = FinalTerms.nil(&m.ctx);
            var i = target.monitored_by.items.len;
            while (i > 0) {
                i -= 1;
                const watcher = target.monitored_by.items[i].watcher;
                list = try FinalTerms.cons(&m.ctx, try FinalTerms.pid(&m.ctx, watcher, 0), list);
            }
            return list;
        } else if (std.mem.eql(u8, item_name, "priority")) {
            // gap-priority-classes: the TARGET's real priority.
            //
            // This used to return a hardcoded `normal`, with the justification
            // that "the single-scheduler VM has no priority classes". That was
            // honest when written and stopped being honest the moment
            // `gap-eep76-priority-flag` landed `process_flag(priority, Level)`:
            // from then on a process could SET `high` and read back `normal`,
            // which is a divergence from OTP, not a defensible default. A
            // constant is only an honest answer while it is the only true one.
            return FinalTerms.atom(&m.ctx, try self.atoms.intern(target.machine.priority.name()));
        } else if (std.mem.eql(u8, item_name, "error_handler")) {
            // E7.5 (Task 5): the module handling undefined-function calls — the
            // default `error_handler` for every process (host-verified byte-total:
            // `{error_handler, error_handler}`). A portable config default, not an
            // impl-specific counter.
            return FinalTerms.atom(&m.ctx, try self.atoms.intern("error_handler"));
        } else if (std.mem.eql(u8, item_name, "message_queue_data")) {
            // E7.5 (Task 5): where the mailbox is stored — the default `on_heap`
            // for a default-shaped process (host-verified byte-total:
            // `{message_queue_data, on_heap}`). A portable config default.
            return FinalTerms.atom(&m.ctx, try self.atoms.intern("on_heap"));
        } else if (std.mem.eql(u8, item_name, "dictionary")) {
            // E3.9: the real pdict (S24, bifs/pdict.zig) — a `[{K,V}]`
            // proplist, terms copied into the CALLER's heap (same cross-heap
            // copy discipline as "messages" above).
            const n = FinalTerms.mapSize(&target.machine.ctx, target.machine.pdict);
            const pk = try self.gpa.alloc(FinalTerms.Term, n);
            defer self.gpa.free(pk);
            const pv = try self.gpa.alloc(FinalTerms.Term, n);
            defer self.gpa.free(pv);
            const got = FinalTerms.mapPairs(&target.machine.ctx, target.machine.pdict, pk, pv);
            std.debug.assert(got == n);
            var list = FinalTerms.nil(&m.ctx);
            var i = n;
            while (i > 0) {
                i -= 1;
                const kc = try FinalTerms.gcCopy(&m.ctx, &target.machine.ctx, pk[i]);
                const vc = try FinalTerms.gcCopy(&m.ctx, &target.machine.ctx, pv[i]);
                const kv = try FinalTerms.tuple(&m.ctx, &.{ kc, vc });
                list = try FinalTerms.cons(&m.ctx, kv, list);
            }
            return list;
        }
        // Every other name is rejected before the trap is ever set (see doc
        // comment) — this is unreachable on a well-formed call, but a safe
        // `[]` fallback (never a panic) if that invariant is ever loosened.
        return FinalTerms.nil(&m.ctx);
    }

    fn doProcessInfoAll(self: *Vm, m: *ia.Machine, pid_term: FinalTerms.Term) !FinalTerms.Term {
        const target_pid = pidOfTerm(&m.ctx, pid_term) orelse return try undefinedAtom(self, m);
        const target = self.proc(target_pid) orelse return try undefinedAtom(self, m);
        var list = FinalTerms.nil(&m.ctx);
        var i = proc_info_items.len;
        while (i > 0) {
            i -= 1;
            const name = proc_info_items[i];
            const val = try self.procInfoValue(m, target, target_pid, name);
            const tup = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try self.atoms.intern(name)), val });
            list = try FinalTerms.cons(&m.ctx, tup, list);
        }
        return list;
    }

    fn doProcessInfoItem(self: *Vm, m: *ia.Machine, pid_term: FinalTerms.Term, item: FinalTerms.Term) !FinalTerms.Term {
        const target_pid = pidOfTerm(&m.ctx, pid_term) orelse return try undefinedAtom(self, m);
        const target = self.proc(target_pid) orelse return try undefinedAtom(self, m);
        if (FinalTerms.repIsAtom(item)) {
            // process_info/2 with a SINGLE item atom → {Item, Value}.
            const name = self.atoms.nameOf(FinalTerms.atomIdxOf(item));
            const val = try self.procInfoValue(m, target, target_pid, name);
            // e21-t2b (DIVERGENCE 490-amend): erts' `registered_name` QUIRK — an
            // UNREGISTERED process returns the BARE atom `[]` (the value nil), NOT a
            // `{registered_name, []}` tuple; a registered one returns the normal
            // `{registered_name, Name}` tuple. `procInfoValue` already denotes the
            // value nil for the unregistered case, so the whole result IS that nil.
            // This is the byte-total shape `proc_lib:get_my_name/0` reads on the
            // gen_server boot path (host-verified: `[]`). Every other item keeps the
            // `{Item, Value}` shape.
            if (std.mem.eql(u8, name, "registered_name") and
                FinalTerms.kindOf(&m.ctx, val) == .nil)
                return val;
            return try FinalTerms.tuple(&m.ctx, &.{ item, val });
        }
        if (FinalTerms.kindOf(&m.ctx, item) == .tuple) {
            // gap-stdlib-bif-audit: process_info/2 with the TUPLE item
            // `{dictionary, Key}` → `{{dictionary, Key}, Value}`, where Value is
            // the value stored under Key in the target's process dictionary, or
            // the ATOM `undefined` if the target has no such key (host-verified on
            // the pin: `{{dictionary,nope},undefined}`, NOT nil). procsys.zig has
            // already validated the item shape (`{dictionary, _}`, arity 2), so
            // element 0 is the `dictionary` tag and element 1 is the lookup Key.
            //
            // This is the exact byte-total item `proc_lib` reads for
            // `$initial_call` / `$process_label` / `$ancestors` (proc_lib.erl
            // `get_process_info(Pid, {dictionary, Tag})`): a single-key projection
            // of the process dictionary — a domain the VM models fully (S24, the
            // real pdict). The Key lives in the CALLER's heap; the pdict lives in
            // the TARGET's heap, so we copy the whole pdict map into the caller's
            // heap (the same cross-heap copy discipline as the `dictionary`/
            // `messages` items above) and look Key up there, keeping both operands
            // in one Ctx for `mapGet`'s term-equality compare. No mutation of the
            // observed process.
            const key = FinalTerms.tupleElem(&m.ctx, item, 1);
            const dict_copy = try FinalTerms.gcCopy(&m.ctx, &target.machine.ctx, target.machine.pdict);
            const val = FinalTerms.mapGet(&m.ctx, dict_copy, key) orelse
                FinalTerms.atom(&m.ctx, try self.atoms.intern("undefined"));
            return try FinalTerms.tuple(&m.ctx, &.{ item, val });
        }
        // process_info/2 with a LIST of items → a list of {Item, Value}.
        var out_rev: [proc_info_items.len]FinalTerms.Term = undefined;
        var n: usize = 0;
        var cur = item;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons and n < proc_info_items.len) {
            const head = FinalTerms.listHead(&m.ctx, cur);
            const name = self.atoms.nameOf(FinalTerms.atomIdxOf(head));
            const val = try self.procInfoValue(m, target, target_pid, name);
            out_rev[n] = try FinalTerms.tuple(&m.ctx, &.{ head, val });
            n += 1;
            cur = FinalTerms.listTail(&m.ctx, cur);
        }
        var list = FinalTerms.nil(&m.ctx);
        var i = n;
        while (i > 0) {
            i -= 1;
            list = try FinalTerms.cons(&m.ctx, out_rev[i], list);
        }
        return list;
    }

    fn undefinedAtom(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        const idx = try self.atoms.intern("undefined");
        return FinalTerms.atom(&m.ctx, idx);
    }

    /// `spawn_request/4` — the LOCAL-node subset (see `bifs/procsys.zig`).
    /// MFA→entry resolution is Task 12 (same blocker as `spawn_mfa`): the child
    /// is created, `link`/`monitor` opts are honored BEFORE it exits (so a
    /// `monitor` opt's DOWN fires correctly), it immediately exits `undef`
    /// (BEAM-faithful for an unresolvable MFA), and — because this VM has no
    /// async scheduling window between "spawn requested" and "reply delivered"
    /// — the `{spawn_reply, ReqId, ok, ChildPid}` reply is enqueued to the
    /// REQUESTING process as an ordinary self-message in the SAME reduction
    /// (a documented simplification of the real async protocol; see the module
    /// doc comment and `spawn_request_abandon_1`'s note on why abandon is a
    /// no-op here).
    fn doSpawnRequest(self: *Vm, p: *Process, pid: Pid, m: *ia.Machine, v: anytype) !FinalTerms.Term {
        const link = optsHaveAtom(m, v.opts, "link");
        const monitor = optsHaveAtom(m, v.opts, "monitor");
        const reqref = self.next_ref;
        self.next_ref += 1;

        // Spawn the child EXACTLY as `spawn_mfa` does (the local subset): a
        // resolvable `M:F/A` runs its function with the arg list unpacked into the
        // child's low x-registers; an unresolvable MFA spawns a process that
        // immediately exits `undef` (BEAM-faithful). link/monitor opts honored.
        const child = try self.spawn(p.prog, 0, null);
        const cp = self.procs.items[child];
        cp.machine.group_leader = m.group_leader;
        try self.inheritCode(child, m);
        try self.emitEvent(.{ .spawned = .{ .parent = pid, .child = child } });
        if (link) {
            try p.links.append(self.gpa, child);
            try self.signal(pid, child, .link_req);
        }
        if (monitor) {
            const mref = self.next_ref;
            self.next_ref += 1;
            try p.monitors_held.append(self.gpa, .{ .ref = mref, .target = child });
            try cp.monitored_by.append(self.gpa, .{ .ref = mref, .watcher = pid });
        }
        const reqid_term = try FinalTerms.ref(&m.ctx, refWordsForKey(reqref));
        if (self.resolveSpawnMFA(cp, m, v.module, v.func, v.args)) |ppc| {
            cp.machine.pc = ppc;
        } else {
            const undef = FinalTerms.atom(&cp.machine.ctx, try self.atoms.intern("undef"));
            try self.terminate(child, undef); // fires the monitor DOWN, if any
        }

        // The `{spawn_reply, ReqId, ok, ChildPid}` reply is PARKED (built in the
        // caller's heap), NOT delivered in this reduction — the async window.
        // `deliverParkedSpawn` (next scheduler tick) signals it; until then
        // `spawn_request_abandon(ReqId)` can cancel it. Returns the ReqId ref.
        const child_term = try FinalTerms.pid(&m.ctx, child, 0);
        const reply = try FinalTerms.tuple(&m.ctx, &.{
            FinalTerms.atom(&m.ctx, try self.atoms.intern("spawn_reply")),
            reqid_term,
            FinalTerms.atom(&m.ctx, try self.atoms.intern("ok")),
            child_term,
        });
        // gap-b-3: STAGE the park (was an inline write to the global `parked_spawn`
        // from inside the `L_v`-held `interpret`) — applied to the global list at the
        // grant epilogue by `applyStagedParks` (the future `L_c` site). A same-grant
        // `spawn_request_abandon` still cancels it: `doAbandonSpawn` searches staging.
        try self.staged_spawn.append(self.gpa, .{ .reqid = reqref, .to = pid, .child = child, .reply = reply, .vhash = FinalTerms.hashTerm(&m.ctx, reply) });
        self.staged_nonempty.store(true, .release); // N3: arm the epilogue's lock-free peek
        return reqid_term;
    }

    fn distEntryByNode(self: *Vm, node: ta.AtomIdx) ?usize {
        for (self.dist_entries.items, 0..) |e, i| {
            if (e.node == node) return i;
        }
        return null;
    }

    const DistConnectionKey = struct { conn_id: u64, handle_ref: u64 };
    const DistLiveOpts = struct { dflags: i64, creation: u32 };
    const dist_dflags_required: i64 = 468283523004;
    const dist_dflags_mandatory: i64 = 17230663572;
    const dist_dflag_unicode_io: i64 = 0x1000;
    const dist_dflag_unlink_id: i64 = 0x02000000;
    const dist_dflag_strict_order: i64 = 0x2000;

    fn distDFlagsMandatoryAdmitted(dflags: i64) bool {
        return (dflags & dist_dflags_mandatory) == dist_dflags_mandatory;
    }

    fn distLocalActive(self: *Vm) bool {
        if (self.dist_local_node == null) return false;
        const owner = self.dist_net_kernel orelse return false;
        if (self.proc(owner) == null) return false;
        const name = self.registry.nameOf(owner) orelse return false;
        return std.mem.eql(u8, self.atoms.nameOf(name), "net_kernel");
    }

    fn registeredNetKernel(self: *Vm) !?Pid {
        const name = try self.atoms.intern("net_kernel");
        const pid = self.registry.whereis(name) orelse return null;
        return if (self.proc(pid) != null) pid else null;
    }

    fn distNodeIsLocal(self: *Vm, node: ta.AtomIdx) bool {
        if (std.mem.eql(u8, self.atoms.nameOf(node), ta.local_node_name)) return true;
        if (!self.distLocalActive()) return false;
        return self.dist_local_node.? == node;
    }

    fn syncDistLocalObserver(self: *Vm) void {
        const active = self.distLocalActive();
        const node = if (active) self.dist_local_node else null;
        const creation = if (active) self.dist_local_creation else 0;
        for (self.procs.items) |p| {
            p.machine.dist_local_node = node;
            p.machine.dist_local_creation = creation;
        }
    }

    fn clearDistLocalIdentity(self: *Vm) !void {
        if (self.dist_local_node == null and self.dist_net_kernel == null) return;
        self.dist_local_node = null;
        self.dist_local_creation = 0;
        self.dist_net_kernel = null;
        self.syncDistLocalObserver();
        var i: usize = 0;
        while (i < self.dist_entries.items.len) : (i += 1) {
            var e = &self.dist_entries.items[i];
            const was_live = e.live;
            const node = e.node;
            e.pending = false;
            e.live = false;
            e.controller = null;
            if (was_live) {
                self.clearDistRemoteExitsForNode(node);
                try self.notifyDistNodeDown(node);
            }
        }
    }

    fn clearDistLocalForPid(self: *Vm, pid: Pid) !void {
        if (self.dist_net_kernel) |owner| {
            if (owner == pid) try self.clearDistLocalIdentity();
        }
    }

    fn doGetDistNode(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        const node = if (self.distLocalActive())
            self.dist_local_node.?
        else
            try m.ctx.atoms.intern(ta.local_node_name);
        return FinalTerms.atom(&m.ctx, node);
    }

    fn doGetDistCreation(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        if (!self.distLocalActive())
            return FinalTerms.atom(&m.ctx, try self.atoms.intern("undefined"));
        return FinalTerms.int(&m.ctx, @intCast(self.dist_local_creation));
    }

    fn doSetDistNode(self: *Vm, m: *ia.Machine, node_term: FinalTerms.Term, creation_term: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(node_term)) return error.Badarg;
        if (!FinalTerms.repIsSmall(creation_term)) return error.Badarg;
        const creation_raw = FinalTerms.smallValOf(creation_term);
        if (creation_raw < 0) return error.Badarg;
        const node = FinalTerms.atomIdxOf(node_term);
        if (self.distNodeIsLocal(node)) return error.Badarg;
        if (self.dist_local_node != null) {
            if (self.distLocalActive()) return error.Badarg;
            try self.clearDistLocalIdentity();
        }
        const net_kernel = (try self.registeredNetKernel()) orelse return error.Badarg;
        const creation_in = std.math.cast(u32, creation_raw) orelse return error.Badarg;
        self.dist_local_node = node;
        self.dist_local_creation = if (creation_in < 4) 4 else creation_in;
        self.dist_net_kernel = net_kernel;
        self.syncDistLocalObserver();
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    fn distConnectionTerm(m: *ia.Machine, e: *const DistEntry) !FinalTerms.Term {
        const cid: i64 = std.math.cast(i64, e.conn_id) orelse return error.OutOfMemory;
        const cid_term = FinalTerms.int(&m.ctx, cid);
        const ref_term = try FinalTerms.ref(&m.ctx, refWordsForKey(e.handle_ref));
        return try FinalTerms.tuple(&m.ctx, &.{ cid_term, ref_term });
    }

    fn distConnectionKey(m: *ia.Machine, conn_term: FinalTerms.Term) !DistConnectionKey {
        if (FinalTerms.kindOf(&m.ctx, conn_term) != .tuple or FinalTerms.tupleArity(&m.ctx, conn_term) != 2) return error.Badarg;
        const cid_term = FinalTerms.tupleElem(&m.ctx, conn_term, 0);
        const ref_term = FinalTerms.tupleElem(&m.ctx, conn_term, 1);
        if (!FinalTerms.repIsSmall(cid_term)) return error.Badarg;
        const cid_raw = FinalTerms.smallValOf(cid_term);
        if (cid_raw < 0) return error.Badarg;
        if (!FinalTerms.repIsRef(&m.ctx, ref_term)) return error.Badarg;
        return .{
            .conn_id = std.math.cast(u64, cid_raw) orelse return error.Badarg,
            .handle_ref = keyFromRefWords(FinalTerms.refWords(&m.ctx, ref_term)),
        };
    }

    fn distLiveOpts(m: *ia.Machine, opts_term: FinalTerms.Term) !DistLiveOpts {
        if (FinalTerms.kindOf(&m.ctx, opts_term) != .tuple or FinalTerms.tupleArity(&m.ctx, opts_term) != 2) return error.Badarg;
        const dflags_term = FinalTerms.tupleElem(&m.ctx, opts_term, 0);
        const creation_term = FinalTerms.tupleElem(&m.ctx, opts_term, 1);
        if (!FinalTerms.repIsSmall(dflags_term) or !FinalTerms.repIsSmall(creation_term)) return error.Badarg;
        const creation_raw = FinalTerms.smallValOf(creation_term);
        if (creation_raw < 0) return error.Badarg;
        const dflags = FinalTerms.smallValOf(dflags_term);
        if (!distDFlagsMandatoryAdmitted(dflags)) return error.Badarg;
        return .{
            .dflags = dflags,
            .creation = std.math.cast(u32, creation_raw) orelse return error.Badarg,
        };
    }

    /// E18.3 reverse carrier (DIVERGENCE 211 residual): register a peer that was
    /// authenticated by a REAL live v6 handshake on a socket (`dist.liveConnectOpen`)
    /// as a LIVE dist node, so THIS VM's own `nodes/0` observer lists it. Distinct
    /// from the E8.2l pending→live promotion: there is no local-BIF pending handle
    /// here — the connection was authenticated OUT OF BAND over TCP, so this is the
    /// carrier bridge the connected-node surface was built to receive. Idempotent
    /// per node (a re-register of the same node refreshes its incarnation and keeps
    /// it live). Returns the connection id (distinct per node, monotonic).
    pub fn registerLiveDistPeer(self: *Vm, node: ta.AtomIdx, creation: u32, dflags: i64) !u64 {
        if (self.distEntryByNode(node)) |idx| {
            var e = &self.dist_entries.items[idx];
            e.pending = false;
            e.live = true;
            e.controller = null;
            e.peer_creation = creation;
            e.peer_dflags = dflags;
            return e.conn_id;
        }
        const conn_id = self.next_dist_conn;
        self.next_dist_conn += 1;
        const entry = DistEntry{
            .node = node,
            .handle_ref = self.next_ref,
            .conn_id = conn_id,
            .pending = false,
            .live = true,
            .peer_creation = creation,
            .peer_dflags = dflags,
        };
        self.next_ref += 1;
        try self.dist_entries.append(self.gpa, entry);
        return conn_id;
    }

    /// E18.3 reverse carrier: tear a live peer connection down (carrier closed /
    /// tick timeout). Mirrors `disconnect_dist_node`'s node-removal semantics: the
    /// row leaves the connected-node observer, buffered remote-exit intents for it
    /// are dropped, and any `monitor_node` watcher gets `{nodedown,Node}`. Returns
    /// true iff a live row for the node was actually removed (teardown→node-removed).
    pub fn removeLiveDistPeer(self: *Vm, node: ta.AtomIdx) !bool {
        const idx = self.distEntryByNode(node) orelse return false;
        var e = &self.dist_entries.items[idx];
        if (!e.live) return false;
        e.live = false;
        e.pending = false;
        e.controller = null;
        self.clearDistRemoteExitsForNode(node);
        try self.notifyDistNodeDown(node);
        return true;
    }

    pub fn distLiveNodesTerm(self: *Vm, m: *ia.Machine) !FinalTerms.Term {
        var out = FinalTerms.nil(&m.ctx);
        var i = self.dist_entries.items.len;
        while (i > 0) {
            i -= 1;
            const e = self.dist_entries.items[i];
            if (!e.live) continue;
            const node = FinalTerms.atom(&m.ctx, e.node);
            out = try FinalTerms.cons(&m.ctx, node, out);
        }
        return out;
    }

    fn doListDistNodes(self: *Vm, m: *ia.Machine, v: anytype) !FinalTerms.Term {
        var out = FinalTerms.nil(&m.ctx);
        if (v.connected or v.visible) out = try self.distLiveNodesTerm(m);
        if (v.known or v.this_node) {
            out = try FinalTerms.cons(&m.ctx, try self.doGetDistNode(m), out);
        }
        return out;
    }

    fn distNodeInfoMap(m: *ia.Machine, want_node_type: bool, node_type_value: FinalTerms.Term, want_connection_id: bool, connection_id_value: FinalTerms.Term) !FinalTerms.Term {
        var keys: [2]FinalTerms.Term = undefined;
        var vals: [2]FinalTerms.Term = undefined;
        var n: usize = 0;
        if (want_connection_id) {
            keys[n] = FinalTerms.atom(&m.ctx, try m.ctx.atoms.intern("connection_id"));
            vals[n] = connection_id_value;
            n += 1;
        }
        if (want_node_type) {
            keys[n] = FinalTerms.atom(&m.ctx, try m.ctx.atoms.intern("node_type"));
            vals[n] = node_type_value;
            n += 1;
        }
        return try FinalTerms.mapNew(&m.ctx, keys[0..n], vals[0..n]);
    }

    fn distNodeInfoRow(m: *ia.Machine, node: FinalTerms.Term, info: FinalTerms.Term) !FinalTerms.Term {
        return try FinalTerms.tuple(&m.ctx, &.{ node, info });
    }

    fn doListDistNodeInfos(self: *Vm, m: *ia.Machine, v: anytype) !FinalTerms.Term {
        var out = FinalTerms.nil(&m.ctx);
        if (v.connected or v.visible) {
            var i = self.dist_entries.items.len;
            while (i > 0) {
                i -= 1;
                const e = self.dist_entries.items[i];
                if (!e.live) continue;
                const conn_id: i64 = std.math.cast(i64, e.conn_id) orelse return error.OutOfMemory;
                const info = try distNodeInfoMap(
                    m,
                    v.node_type,
                    FinalTerms.atom(&m.ctx, try m.ctx.atoms.intern("visible")),
                    v.connection_id,
                    FinalTerms.int(&m.ctx, conn_id),
                );
                const row = try distNodeInfoRow(m, FinalTerms.atom(&m.ctx, e.node), info);
                out = try FinalTerms.cons(&m.ctx, row, out);
            }
        }
        if (v.known or v.this_node) {
            const local = try self.doGetDistNode(m);
            const info = try distNodeInfoMap(
                m,
                v.node_type,
                FinalTerms.atom(&m.ctx, try m.ctx.atoms.intern("this")),
                v.connection_id,
                FinalTerms.atom(&m.ctx, try m.ctx.atoms.intern("undefined")),
            );
            const row = try distNodeInfoRow(m, local, info);
            out = try FinalTerms.cons(&m.ctx, row, out);
        }
        return out;
    }

    fn doDistDflagUnicodeIo(self: *Vm, m: *ia.Machine, pid_term: FinalTerms.Term) !FinalTerms.Term {
        var enabled = false;
        if (FinalTerms.repIsPid(&m.ctx, pid_term)) {
            const creation = FinalTerms.pidCreation(&m.ctx, pid_term);
            const node_name = FinalTerms.pidNodeName(&m.ctx, pid_term);
            if (creation == 0 and std.mem.eql(u8, node_name, ta.local_node_name)) {
                enabled = true;
            } else {
                const node = try m.ctx.atoms.intern(node_name);
                if (self.distEntryByNode(node)) |idx| {
                    const e = self.dist_entries.items[idx];
                    enabled = e.live and e.peer_creation == creation and (e.peer_dflags & dist_dflag_unicode_io) != 0;
                }
            }
        }
        return FinalTerms.atom(&m.ctx, if (enabled) m.bool_true else m.bool_false);
    }

    /// E8.2z carrier hook: update only a live row for the same node incarnation.
    pub fn refreshLiveDistPeerDFlags(self: *Vm, node: ta.AtomIdx, peer_creation: u32, peer_dflags: i64) bool {
        if (!distDFlagsMandatoryAdmitted(peer_dflags)) return false;
        const idx = self.distEntryByNode(node) orelse return false;
        var e = &self.dist_entries.items[idx];
        if (!e.live or e.peer_creation != peer_creation) return false;
        e.peer_dflags = peer_dflags;
        return true;
    }

    fn addDistNodeMonitor(self: *Vm, node: ta.AtomIdx, watcher: Pid) !void {
        const p = self.proc(watcher) orelse return;
        if (!p.alive) return;
        for (self.dist_node_monitors.items) |mon| {
            if (mon.node == node and mon.watcher == watcher) return;
        }
        try self.dist_node_monitors.append(self.gpa, .{ .node = node, .watcher = watcher });
    }

    fn removeDistNodeMonitor(self: *Vm, node: ta.AtomIdx, watcher: Pid) void {
        for (self.dist_node_monitors.items, 0..) |mon, i| {
            if (mon.node == node and mon.watcher == watcher) {
                _ = self.dist_node_monitors.swapRemove(i);
                return;
            }
        }
    }

    fn doMonitorDistNode(self: *Vm, m: *ia.Machine, watcher: Pid, node_term: FinalTerms.Term, enabled: bool) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(node_term)) return error.Badarg;
        const node = FinalTerms.atomIdxOf(node_term);
        if (self.distNodeIsLocal(node))
            return FinalTerms.atom(&m.ctx, m.bool_true);
        if (self.distEntryByNode(node)) |idx| {
            if (self.dist_entries.items[idx].live) {
                if (enabled) try self.addDistNodeMonitor(node, watcher) else self.removeDistNodeMonitor(node, watcher);
                return FinalTerms.atom(&m.ctx, m.bool_true);
            }
        }
        return error.Notalive;
    }

    fn appendDistRemoteExit(self: *Vm, from: Pid, m: *ia.Machine, node: ta.AtomIdx, to: u64, creation: u32, reason: FinalTerms.Term) !void {
        var wire = try etf.encode(self.gpa, &m.ctx, reason);
        defer wire.deinit(self.gpa);
        const owned_wire = try self.gpa.dupe(u8, wire.items);
        errdefer self.gpa.free(owned_wire);
        try self.dist_remote_exits.append(self.gpa, .{
            .from = from,
            .node = node,
            .to = to,
            .creation = creation,
            .reason = reason,
            .reason_wire = owned_wire,
        });
    }

    pub fn removeDistRemoteExitAt(self: *Vm, idx: usize) void {
        const e = self.dist_remote_exits.items[idx];
        self.gpa.free(e.reason_wire);
        _ = self.dist_remote_exits.orderedRemove(idx);
    }

    fn doRemoteExitSignal(self: *Vm, from: Pid, m: *ia.Machine, pid_term: FinalTerms.Term, reason: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsPid(&m.ctx, pid_term)) return FinalTerms.atom(&m.ctx, m.bool_true);
        const creation = FinalTerms.pidCreation(&m.ctx, pid_term);
        const node = try self.atoms.intern(FinalTerms.pidNodeName(&m.ctx, pid_term));
        if (self.distEntryByNode(node)) |idx| {
            const e = self.dist_entries.items[idx];
            if (e.live and e.peer_creation == creation) {
                try self.appendDistRemoteExit(from, m, node, FinalTerms.pidNumber(&m.ctx, pid_term), creation, reason);
            }
        }
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    fn clearDistRemoteExitsForNode(self: *Vm, node: ta.AtomIdx) void {
        var i: usize = 0;
        while (i < self.dist_remote_exits.items.len) {
            if (self.dist_remote_exits.items[i].node == node) {
                self.removeDistRemoteExitAt(i);
            } else {
                i += 1;
            }
        }
    }

    fn deliverDistNodeDown(self: *Vm, node: ta.AtomIdx, watcher: Pid) !void {
        const p = self.proc(watcher) orelse return;
        if (!p.alive) return;
        const m = &p.machine;
        const msg = try FinalTerms.tuple(&m.ctx, &.{
            FinalTerms.atom(&m.ctx, try self.atoms.intern("nodedown")),
            FinalTerms.atom(&m.ctx, node),
        });
        try self.signal(DIST_SYSTEM_PID, watcher, .{ .message = msg });
    }

    fn notifyDistNodeDown(self: *Vm, node: ta.AtomIdx) !void {
        var i: usize = 0;
        while (i < self.dist_node_monitors.items.len) {
            const mon = self.dist_node_monitors.items[i];
            if (mon.node != node) {
                i += 1;
                continue;
            }
            try self.deliverDistNodeDown(node, mon.watcher);
            _ = self.dist_node_monitors.swapRemove(i);
        }
    }

    fn doDisconnectDistNode(self: *Vm, m: *ia.Machine, node_term: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(node_term)) return error.Badarg;
        const node = FinalTerms.atomIdxOf(node_term);
        if (self.distEntryByNode(node)) |idx| {
            var e = &self.dist_entries.items[idx];
            if (e.live) {
                e.live = false;
                e.pending = false;
                e.controller = null;
                self.clearDistRemoteExitsForNode(node);
                try self.notifyDistNodeDown(node);
                return FinalTerms.atom(&m.ctx, m.bool_true);
            }
        }
        return FinalTerms.atom(&m.ctx, m.bool_false);
    }

    /// E8.2j: `erts_internal:new_connection/1` pending-handle identity. With no
    /// socket/channel owner, this is the only OTP-observable part: a node gets a
    /// stable handle ref; repeated calls while pending reuse `{ConnId,Ref}`; after
    /// abort the next call increments the connection id and reuses the handle ref.
    fn doNewDistConnection(self: *Vm, m: *ia.Machine, node_term: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(node_term)) return error.Badarg;
        const node = FinalTerms.atomIdxOf(node_term);
        if (self.distNodeIsLocal(node)) return error.Badarg;
        if (self.distEntryByNode(node)) |idx| {
            var e = &self.dist_entries.items[idx];
            if (e.live) return distConnectionTerm(m, e);
            if (!e.pending) {
                e.conn_id = self.next_dist_conn;
                self.next_dist_conn += 1;
                e.pending = true;
            }
            return distConnectionTerm(m, e);
        }
        const entry = DistEntry{
            .node = node,
            .handle_ref = self.next_ref,
            .conn_id = self.next_dist_conn,
            .pending = true,
        };
        self.next_ref += 1;
        self.next_dist_conn += 1;
        try self.dist_entries.append(self.gpa, entry);
        return distConnectionTerm(m, &self.dist_entries.items[self.dist_entries.items.len - 1]);
    }

    /// E8.2j: `erts_internal:abort_pending_connection/2` over the pending handle.
    /// A valid handle for the named node returns `true`; if the exact current
    /// connection id is pending, it becomes idle. Stale handles for the same node
    /// remain true in the no-connected-channel model, while wrong-node or non-ref
    /// handles are `badarg`.
    fn doAbortPendingDistConnection(self: *Vm, m: *ia.Machine, node_term: FinalTerms.Term, conn_term: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(node_term)) return error.Badarg;
        const key = try distConnectionKey(m, conn_term);
        const node = FinalTerms.atomIdxOf(node_term);
        const idx = self.distEntryByNode(node) orelse return error.Badarg;
        var e = &self.dist_entries.items[idx];
        if (e.handle_ref != key.handle_ref) return error.Badarg;
        if (e.live) return error.Badarg;
        if (e.pending and e.conn_id == key.conn_id) e.pending = false;
        return FinalTerms.atom(&m.ctx, m.bool_true);
    }

    /// E8.2l: live-carrier semantic precursor. A validated pending connection
    /// handle can be promoted to a live entry exactly once; the live entry then
    /// appears in the connected-node observer. This is VM-internal state, not an
    /// OTP direct-call EQ claim for `setnode/2` or `create_dist_channel/3`.
    fn doPromotePendingDistConnection(self: *Vm, m: *ia.Machine, node_term: FinalTerms.Term, conn_term: FinalTerms.Term, opts_term: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(node_term)) return error.Badarg;
        const key = try distConnectionKey(m, conn_term);
        const opts = try distLiveOpts(m, opts_term);
        const node = FinalTerms.atomIdxOf(node_term);
        const idx = self.distEntryByNode(node) orelse return error.Badarg;
        var e = &self.dist_entries.items[idx];
        if (!e.pending or e.live) return error.Badarg;
        if (e.conn_id != key.conn_id or e.handle_ref != key.handle_ref) return error.Badarg;
        e.pending = false;
        e.live = true;
        e.controller = null;
        e.peer_creation = opts.creation;
        e.peer_dflags = opts.dflags;
        const dhandle = try Vm.distConnectionTerm(m, e);
        return try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try self.atoms.intern("ok")), dhandle });
    }

    /// E8.2r: create_dist_channel/3 promotion bridge. A caller can promote an
    /// existing pending DistEntry only when it supplies a live local controller
    /// pid and bounded `{DFlags,Creation}` metadata. This is still not a socket.
    fn portTermIsLocal(ctx: *FinalTerms.Ctx, w: FinalTerms.Term) bool {
        return FinalTerms.repIsPort(ctx, w) and FinalTerms.portCreation(ctx, w) == 0;
    }

    fn doCreateDistChannel(self: *Vm, m: *ia.Machine, node_term: FinalTerms.Term, controller_term: FinalTerms.Term, opts_term: FinalTerms.Term) !FinalTerms.Term {
        if (!FinalTerms.repIsAtom(node_term)) return FinalTerms.atom(&m.ctx, m.badarg);
        if (!self.distLocalActive()) return FinalTerms.atom(&m.ctx, m.badarg);
        const node = FinalTerms.atomIdxOf(node_term);
        if (self.distNodeIsLocal(node)) return FinalTerms.atom(&m.ctx, m.badarg);
        if (!pidTermIsLocal(&m.ctx, controller_term) and !portTermIsLocal(&m.ctx, controller_term)) return FinalTerms.atom(&m.ctx, m.badarg);

        if (pidTermIsLocal(&m.ctx, controller_term)) {
            const controller = pidOfTerm(&m.ctx, controller_term) orelse return FinalTerms.atom(&m.ctx, m.badarg);
            const cp = self.proc(controller) orelse return FinalTerms.atom(&m.ctx, m.badarg);
            if (!cp.alive) return FinalTerms.atom(&m.ctx, m.badarg);
        } else {
            const controller_port = self.portOf(m, controller_term) orelse return FinalTerms.atom(&m.ctx, m.badarg);
            if (!controller_port.alive) return FinalTerms.atom(&m.ctx, m.badarg);
        }

        const opts = distLiveOpts(m, opts_term) catch return FinalTerms.atom(&m.ctx, m.badarg);
        const idx = self.distEntryByNode(node) orelse return FinalTerms.atom(&m.ctx, m.badarg);
        var e = &self.dist_entries.items[idx];
        if (!e.pending or e.live) return FinalTerms.atom(&m.ctx, m.badarg);
        e.pending = false;
        e.live = true;
        e.controller = controller_term;
        e.peer_creation = opts.creation;
        e.peer_dflags = opts.dflags;
        const dhandle = try Vm.distConnectionTerm(m, e);
        return try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try self.atoms.intern("ok")), dhandle });
    }

    /// E8.2i: direct `erts_internal:dist_spawn_request/4` no-carrier branch.
    /// There is no live dist entry, so no remote process is spawned and no
    /// carrier state is installed. OTP still mints the request ref and sends the
    /// local error reply before returning unless the reply options suppress
    /// error replies. The reply is drained into the caller mailbox immediately,
    /// matching the direct BIF observation.
    fn doDistSpawnRequest(self: *Vm, pid: Pid, m: *ia.Machine, v: anytype) !FinalTerms.Term {
        const reqref = self.next_ref;
        self.next_ref += 1;
        const ref_term = try FinalTerms.ref(&m.ctx, refWordsForKey(reqref));
        if (v.send_error_reply) {
            const err = try FinalTerms.tuple(&m.ctx, &.{
                v.tag,
                ref_term,
                FinalTerms.atom(&m.ctx, try self.atoms.intern("error")),
                v.error_reason,
            });
            try self.signal(pid, pid, .{ .message = err });
            try self.drainSignals(pid);
        }
        if (v.mode == .spawn_request) return ref_term;
        return FinalTerms.tuple(&m.ctx, &.{ ref_term, FinalTerms.atom(&m.ctx, if (v.spawns_monitor) m.bool_true else m.bool_false) });
    }

    /// E5.6 (Task 6): flush every parked spawn-reply to its caller through the
    /// stamped signal path (waking a suspended caller — the receive-wake). Called
    /// at `grant` start, so the reply lands one scheduler tick after the
    /// `spawn_request/4` reduction: the async window `spawn_request_abandon/1`
    /// races. `from = child` (the spawn's origin) so the per-pair order is the
    /// child→parent pair, distinct from any user pair (the sacred law untouched).
    /// A caller that has since died drops the reply. Bounded (parked count).
    fn deliverParkedSpawn(self: *Vm) !void {
        // gap-b-5a: SNAPSHOT-then-signal (see `deliverParkedSysTask`). `L_c` guards
        // ONLY the parked-list READ+DRAIN (snapshot into scratch + clear the global
        // list), then is RELEASED before the `signal` loop — because push-based
        // discovery made `signal` take `L_c` for its wake decision, and the spinlock
        // is non-reentrant. This REMOVES the old `L_c`-held-across-`signal` nesting:
        // each `signal` now runs `L_v→L_c→L_timer` on its own, the sanctioned order.
        // sender-narrowing N1: worker-local snapshot (see `deliverParkedSysTask`).
        var scratch: std.ArrayList(ParkedSpawn) = .empty;
        defer scratch.deinit(self.gpa);
        self.l_c.lock();
        if (self.parked_spawn.items.len == 0) {
            self.l_c.unlock();
            return;
        }
        scratch.appendSlice(self.gpa, self.parked_spawn.items) catch |e| {
            self.l_c.unlock(); // parked list UNTOUCHED on OOM (cleared only after a successful snapshot)
            return e;
        };
        self.parked_spawn.clearRetainingCapacity();
        self.l_c.unlock();
        for (scratch.items) |e| {
            if (self.proc(e.to) == null) continue; // caller gone: drop
            // N1: park-time vhash — delivery never hashes the requester's heap.
            try self.signalInner(e.child, e.to, .{ .message = e.reply }, e.vhash);
        }
    }

    /// gap-b-3 (SMP step 3): the SINGLE epilogue apply-point that publishes this
    /// grant's STAGED parks into the coordinator-owned global lists — the write that
    /// used to happen inline inside the `L_v`-held `interpret` (`doDistSpawnRequest`/
    /// `doRequestSystemTask`), now hoisted to ONE point in the locked epilogue so
    /// gap-b-4 can wrap it with the coherency lock `L_c` (strictly below `L_v`)
    /// WITHOUT the `L_v↔L_c` back-edge. Called once per grant (end of `grantOnly` and
    /// the SMP worker's epilogue). METAMORPHIC: after this returns the global lists
    /// hold exactly the entries the old inline writes would have — same set, same
    /// order (staged entries are appended in staging order). EXACTLY-ONCE: staging is
    /// cleared after the flush, so a park is applied once and never again. FMEA:
    /// `appendSlice` reserves capacity first, so an OOM is all-or-nothing per list —
    /// on failure neither list is mutated (no partial apply, no double apply, no lost
    /// park), and the error propagates to abort the grant rather than silently drop.
    fn applyStagedParks(self: *Vm) !void {
        // gap-b-4: `L_c` guards the PUBLISH of this grant's staged parks into the
        // coordinator-owned global lists — a coherency-domain WRITE. The per-grant
        // staging buffers (`staged_*`) are grant-local scratch (touched only by the
        // owning grant), so they need no lock; only the global `parked_*` write is
        // under `L_c`. Acquires no other lock (no `signal` here), so this is a leaf
        // `L_c` section — never nests, never re-enters, never reaches `L_v`.
        self.l_c.lock();
        defer self.l_c.unlock();
        if (self.staged_spawn.items.len != 0) {
            try self.parked_spawn.appendSlice(self.gpa, self.staged_spawn.items);
            self.staged_spawn.clearRetainingCapacity();
        }
        if (self.staged_systask.items.len != 0) {
            try self.parked_systask.appendSlice(self.gpa, self.staged_systask.items);
            self.staged_systask.clearRetainingCapacity();
        }
        // N2a: arm the lock-free parked-work flag AFTER the appends (inside the
        // `L_c` section, release-published) — the worker's top-of-loop peek.
        if (self.parked_spawn.items.len != 0 or self.parked_systask.items.len != 0)
            self.parked_nonempty.store(true, .release);
    }

    /// E5.6 (Task 6): `erlang:spawn_request_abandon/1`. Cancels a STILL-PARKED
    /// spawn-reply owned by the caller (`reqid` matches, `to == caller`): the
    /// reply is removed so it is never delivered, the child is ORPHANED (the
    /// caller's link to it dropped, matching the oracle's abandon), and the answer
    /// is `true`. If no such parked reply exists — already delivered (raced by
    /// `deliverParkedSpawn`), already abandoned, or an unknown/foreign ref — the
    /// answer is `false` (the erts contract). Mutant 2 (`always true`) reddens the
    /// abandon-race law's `false` arm.
    fn doAbandonSpawn(self: *Vm, p: *Process, pid: Pid, ref_term: FinalTerms.Term) FinalTerms.Term {
        const m = &p.machine;
        const f = FinalTerms.atom(&m.ctx, m.bool_false);
        if (!FinalTerms.repIsRef(&m.ctx, ref_term)) return f;
        const key = keyFromRefWords(FinalTerms.refWords(&m.ctx, ref_term));
        // gap-b-4: `L_c` guards the abandon's mutation of the GLOBAL `parked_spawn`
        // (a coherency-domain write); the `staged_spawn` half is grant-local scratch
        // but is covered by the same section so the {staging}∪{global} search is one
        // atomic coherency action. A leaf `L_c` section (no `signal`, no other lock),
        // called from `interpret` under `L_v` — order `L_v→L_c`, no back-edge.
        self.l_c.lock();
        defer self.l_c.unlock();
        // gap-b-3: a still-parked reply lives EITHER in this grant's staging buffer
        // (`staged_spawn`, requested this grant, not yet flushed) OR the global list
        // (`parked_spawn`, flushed by an earlier grant's epilogue, not yet delivered).
        // Their union is exactly the old inline-global set, so abandon must consult
        // BOTH — staging first (the most-recent request) — to preserve the race.
        for ([_]*std.ArrayList(ParkedSpawn){ &self.staged_spawn, &self.parked_spawn }) |list| {
            for (list.items, 0..) |e, i| {
                if (e.reqid == key and e.to == pid) {
                    const child = e.child;
                    _ = list.swapRemove(i);
                    for (p.links.items, 0..) |l, k| { // orphan: drop the caller's link
                        if (l == child) {
                            _ = p.links.swapRemove(k);
                            break;
                        }
                    }
                    return FinalTerms.atom(&m.ctx, m.bool_true);
                }
            }
        }
        return f;
    }

    /// E5.6 (Task 6): the CROSS-process form of `erts_internal:process_flag/3`
    /// (`save_calls` only). Sets the TARGET process's `save_calls` flag and
    /// replies `{ReqId, OldValue}` asynchronously to the caller (erts returns a
    /// ref for a non-self target; the SELF form is synchronous and handled inside
    /// the BIF). The reply is delivered synchronously into the caller's mailbox
    /// (the `is_alive_request` precedent) so a caller that later `receive`s it
    /// finds it; the caller may also just observe `is_reference(_)`. Returns the
    /// ReqId ref for x0. A dead/absent target: reply carries `OldValue = 0` from
    /// the caller (never a crash).
    fn doProcessFlag3(self: *Vm, pid: Pid, m: *ia.Machine, pid_term: FinalTerms.Term, value: i64) !FinalTerms.Term {
        const reqref = self.next_ref;
        self.next_ref += 1;
        const ref_term = try FinalTerms.ref(&m.ctx, refWordsForKey(reqref));
        const target = pidOfTerm(&m.ctx, pid_term);
        var old: i64 = 0;
        var from: Pid = pid;
        if (target != null) {
            if (self.proc(target.?)) |tp| {
                old = tp.machine.save_calls;
                tp.machine.save_calls = value;
                from = target.?;
            }
        }
        const reply = try FinalTerms.tuple(&m.ctx, &.{ ref_term, FinalTerms.int(&m.ctx, old) });
        try self.signal(from, pid, .{ .message = reply });
        try self.drainSignals(pid); // land the async reply in the caller's mailbox
        return ref_term;
    }

    /// Scan a proper option list for `name` (shared by `spawn_request`'s local
    /// `link`/`monitor` opts — the same LOCAL-subset convention as
    /// `procsys.optsHaveLink`).
    fn optsHaveAtom(m: *ia.Machine, opts: FinalTerms.Term, name: []const u8) bool {
        var cur = opts;
        var guard: usize = 0;
        while (FinalTerms.kindOf(&m.ctx, cur) == .cons and guard < 64) : (guard += 1) {
            const head = FinalTerms.listHead(&m.ctx, cur);
            if (FinalTerms.repIsAtom(head)) {
                const got = m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(head));
                if (std.mem.eql(u8, got, name)) return true;
            }
            cur = FinalTerms.listTail(&m.ctx, cur);
        }
        return false;
    }

    /// Grant `pid` a slice of `fuel` reductions: drain signals, run, and
    /// interpret every effect trap that fires inside the slice.
    /// e48-smp-s1 (the PHASE SPLIT): `grant` = the GLOBAL scheduler-tick services
    /// (parked spawn/systask reply delivery — coordinator work) + `grantOnly`
    /// (the pure PER-PROCESS grant — the future thread-parallel unit). Every
    /// existing caller keeps `grant` and is byte-identical; the SMP ladder's
    /// worker calls the two phases explicitly so the parallel unit never touches
    /// the global parked lists (S3 narrows the lock to `grantOnly` alone).
    pub fn grant(self: *Vm, pid: Pid, fuel: u64) !void {
        // E5.6 (Task 6): flush parked spawn-request replies at the scheduler tick
        // (one reduction after `spawn_request/4` — the async window that
        // `spawn_request_abandon/1` races). Waking targets ride the signal path.
        try self.deliverParkedSpawn();
        // E7.5 (Task 5): flush parked async system-task replies on the same tick
        // (the `{RequestId, Result}` reply lands one tick after the request).
        try self.deliverParkedSysTask();
        try self.grantOnly(pid, fuel);
    }

    /// e48-smp-s1: the pure per-process grant — signals drained, the machine run
    /// under fuel, traps interpreted, exit paths taken. NO global-service calls:
    /// the parked lists are coordinator-owned from this slice on.
    pub fn grantOnly(self: *Vm, pid: Pid, fuel: u64) !void {
        const p = self.proc(pid) orelse return;
        try self.emitEvent(.{ .grant = pid });
        try self.drainSignals(pid);
        if (!p.alive) return;
        const m = &p.machine;
        // gap-reduction-cost-model R4 ({R} LIVE scheduling-latency): record THIS
        // grant's latency BEFORE the proc runs — `grant_reduction_total` and
        // `last_grant_total` still hold their pre-grant values, so the difference
        // is exactly the reductions OTHER processes burned since this proc's
        // previous grant. Opt-in: `null` histogram ⇒ this whole block is skipped
        // and the counters stay 0 (zero overhead / byte-identical when absent).
        const r_before_grant: u64 = m.reductions;
        if (self.latency_histogram) |h| {
            h.record(self.grant_reduction_total - p.last_grant_total);
        }
        // gap-r2c-behavioral-parity (DIVERGENCE 607, Inc1): OPT-IN reduction-preempt.
        // When `reduction_preempt` is set, `fuel` is a REDUCTION budget and the grant
        // preempts on the OTP-faithful per-call `m.reductions` via the interpreter
        // (per-op reduction granularity), with an instr fail-safe that bounds a
        // 0-reduction straight-line hog (UCA-R2C-1). Default (false) = the R2b
        // instr-preempt grant below, byte-identical.
        if (self.reduction_preempt) {
            const red_target = m.reductions + fuel;
            const instr_cap = m.instrs + fuel * REDUCTION_PREEMPT_INSTR_CAP_MULT;
            while (p.alive and m.status == .running and m.reductions < red_target and m.instrs < instr_cap) {
                if (self.reduction_preempt_native) {
                    // Inc2: reduction-bound the PRODUCTION JIT — a reduction-preempted
                    // proc keeps its native hot path (exact by the {0,1}-reductionCost
                    // theorem; same yield point as the interpreter path).
                    try dispatch.runProductionReds(&self.prod_cache, self.gpa, m, p.prog, red_target - m.reductions, instr_cap - m.instrs);
                } else {
                    // Inc1: reduction-bound via the interpreter (per-op granularity).
                    try ia.runReductionPreempt(m, p.prog, red_target - m.reductions, instr_cap - m.instrs);
                }
                if (m.pending != null) {
                    try self.interpret(pid);
                    try self.drainSignals(pid);
                }
            }
        } else {
            // R2b: a scheduler grant of `fuel` is bounded on the per-INSTRUCTION
            // counter `m.instrs` (preemption rides `instrs`, byte-identical to the
            // pre-R2b `reductions`-fuel model), so a CPU-bound process — even a pure
            // straight-line loop charging 0 per-call reductions — is always preempted.
            const target = m.instrs + fuel;
            while (p.alive and m.status == .running and m.instrs < target) {
                // jit-wire-production: engine #4 (native block JIT + threaded fallback)
                // instead of `ia.run`, cached compile-once per program identity.
                // `runProduction ≡ ia.run` (whole-corpus law) — a pure engine swap that
                // transparently defers to the interpreter on the non-native host, on a
                // hot-code-loaded process (dyn_code non-empty), or a compile failure.
                try dispatch.runProduction(&self.prod_cache, self.gpa, m, p.prog, target - m.instrs);
                if (m.pending != null) {
                    try self.interpret(pid);
                    try self.drainSignals(pid);
                }
            }
        }
        // gap-reduction-cost-model R4: fold THIS proc's own reductions into the
        // global grant clock, then snapshot it as this proc's `last_grant_total`
        // (AFTER its own contribution) so its NEXT latency counts OTHER procs only.
        // Ordering matters: recording at grant entry (above) + advancing here is the
        // "others-only" difference the e50 staircase law pins down. Opt-in.
        if (self.latency_histogram != null) {
            self.grant_reduction_total += m.reductions - r_before_grant;
            p.last_grant_total = self.grant_reduction_total;
        }
        if (m.status == .halted and p.alive) try self.normalExit(pid);
        if (m.status == .crashed and p.alive) {
            // DIVERGENCE 683: a self-inflicted uncaught exception's exit reason is
            // COOKED by class (error->{R,St}, throw->{{nocatch,V},St}, exit->bare)
            // for delivery to linkers/monitors — matching OTP `terminate_proc`.
            const r = try m.cookedExitReason();
            try self.terminate(pid, r);
        }
        // gap-b-3: the grant EPILOGUE apply-point — publish this grant's staged
        // parks into the global lists (identical set/order to the old inline write).
        try self.applyStagedParks();
    }

    pub fn liveCount(self: *Vm) usize {
        var n: usize = 0;
        for (0..self.procs.items.len) |i| {
            if (schedulable(self, @intCast(i))) n += 1; // E6.4: a suspended process is not runnable
        }
        return n;
    }

    /// gap-resident-node: the count of processes that are ALIVE (not yet halted/
    /// crashed), regardless of whether they are currently RUNNABLE. `liveCount`
    /// counts only `schedulable` procs (runnable now); a process blocked in
    /// `receive` with no pending signal is alive but not schedulable, so it
    /// contributes to `aliveCount` but NOT `liveCount`. The resident node stays up
    /// while `aliveCount > 0` (an idle-but-alive supervision tree), and halts only
    /// when `aliveCount == 0` — the CTRL-RESIDENT-NODE liveness distinction.
    pub fn aliveCount(self: *Vm) usize {
        var n: usize = 0;
        for (self.procs.items) |p| {
            if (p.alive) n += 1;
        }
        return n;
    }

    /// gap-e46-resident-cli: the count of alive NON-INFRASTRUCTURE processes — a
    /// resident node is DONE when no USER process remains, even though the group
    /// leader (`io_gl`) and kernel `system` processes stay alive forever (they are
    /// the node's infrastructure, not its workload). `driveResident` halts on this,
    /// not `aliveCount`, so a completed one-shot computation (only the group leader
    /// left) shuts down cleanly instead of reporting an idle node.
    pub fn residentAliveCount(self: *Vm) usize {
        var n: usize = 0;
        for (self.procs.items) |p| {
            if (p.alive and !p.system and !p.io_gl) n += 1;
        }
        return n;
    }

    /// E7.4 (DIVERGENCE 151): `erts_internal:processes_next/1` — the CHUNKED
    /// live-pid iterator. A cursor is an index into the process table; a step
    /// returns up to `chunk` live pids from the cursor plus the NEXT cursor, and
    /// folding from cursor 0 to the end enumerates EXACTLY the live-pid set — the
    /// SAME multiset `processes/0` (the `list_processes` trap) returns, order-
    /// independent (the set-equality / iteration-totality property). The cursor is
    /// an internal, per-node NONDETERMINISTIC value, which is why the row stays
    /// deferred: the `{Cursor,[Pid]}` tuple never byte-matches the oracle. This is
    /// an INTERNAL property law, not a differential. Bounded: each step advances
    /// the cursor past ≥1 table slot, so the fold terminates in ≤ table-size steps
    /// (a wedged cursor is `error.CursorStuck` — a failed law, never a hang).
    /// Returns the caller-owned pid slice.
    pub fn processesNextFold(self: *Vm, gpa: std.mem.Allocator, chunk: usize) ![]Pid {
        std.debug.assert(chunk >= 1);
        var out: std.ArrayList(Pid) = .empty;
        errdefer out.deinit(gpa);
        const n = self.procs.items.len;
        var cursor: usize = 0;
        var guard: usize = 0;
        while (cursor < n) {
            guard += 1;
            if (guard > n + 1) return error.CursorStuck; // bounded: a wedged cursor fails the law
            var taken: usize = 0;
            var i = cursor;
            while (i < n and taken < chunk) : (i += 1) {
                if (self.procs.items[i].alive) {
                    try out.append(gpa, @intCast(i));
                    taken += 1;
                }
            }
            if (i == cursor) i += 1; // no live pid in this window: still advance (boundedness)
            cursor = i;
        }
        return out.toOwnedSlice(gpa);
    }
};

// ============================================================================
// Schedulers (S17): the round-robin ORACLE and a seeded ENGINE. Both must
// satisfy the same trace laws; deterministic topologies must agree exactly.
// ============================================================================

/// gap-priority-classes: the highest priority class with a schedulable process,
/// or null when nothing is schedulable.
///
/// SEMANTIC DOMAIN. The schedulable set partitions into the four OTP classes
/// (`max > high > normal > low`), and dispatch draws from the non-empty class of
/// greatest priority. Within a class the pre-existing selection is unchanged —
/// round-robin for the oracle, fair-but-random for the seeded engine — so the
/// fairness guarantees each already carried survive intact, one class at a time.
///
/// INERT BY CONSTRUCTION when nobody sets a priority. Every process defaults to
/// `normal`, so on a program that never calls `process_flag(priority, _)` the top
/// class is `normal`, the filter admits exactly the previously-schedulable set,
/// and the pick is byte-identical to the pre-slice scheduler. That is what lets
/// this land under the existing trace/fairness laws (including the SACRED
/// per-pair signal-order law and `Scheduler_Signal.v`) rather than beside them —
/// the change is unobservable until a program asks for it.
///
/// STARVATION IS THE POINT, and is OTP's semantics, not an oversight: a
/// perpetually-runnable `high` process WILL starve `normal` and `low`. zigvm's
/// no-starvation laws quantify over a single class, which is the strongest
/// statement that remains true under real priority scheduling.
fn topRunnablePriority(vm: *const Vm) ?ia.ProcPriority {
    var best: ?ia.ProcPriority = null;
    for (0..vm.procs.items.len) |k| {
        if (!schedulable(vm, @intCast(k))) continue;
        const p = vm.procs.items[k].machine.priority;
        if (best == null or @intFromEnum(p) > @intFromEnum(best.?)) best = p;
    }
    return best;
}

pub const Scheduler = union(enum) {
    round_robin,
    seeded: u64,

    /// Run the VM until quiescent (no live running process) or `max_slices`.
    pub fn drive(self: Scheduler, vm: *Vm, fuel_per_slice: u64, max_slices: usize) !void {
        var prng = std.Random.DefaultPrng.init(switch (self) {
            .seeded => |s| s,
            .round_robin => 0,
        });
        const random = prng.random();
        var slice: usize = 0;
        var cursor: Pid = 0;
        // E5.6 (Task 6): a parked spawn-reply is pending work even when no process
        // is currently runnable (its caller sits suspended in `receive`), so the
        // loop stays live while `parked_spawn` is non-empty; the tick flushes it
        // (waking the caller) BEFORE the runnable check so it can be scheduled.
        // E6.2 (Task 2): a pending TIMER is runnable WORK even when no process is
        // currently `.running` (a `receive after N` process sits suspended until
        // its wheel entry fires). The loop stays live while timers pend; when
        // nothing is runnable, `advanceTimersToNext` jumps the virtual clock to the
        // next deadline and fires — deterministically, never a wall read (the
        // receive-after determinism requirement). Bounded: each advance fires ≥1
        // timer, `max_slices` caps the whole run (an unfired timer is a failed law).
        while (slice < max_slices) : (slice += 1) {
            try vm.deliverParkedSpawn();
            try vm.pollPendingSignals(); // gap-os-signals-delivery: raised signals -> erl_signal_server
            try vm.pollActiveSockets(); // gap-socket-active-mode: {tcp,S,Data} delivery
            try vm.pollAcceptSockets(); // gap-cowboy-trap-accept: resume infinity-accept waiters
            for (vm.procs.items, 0..) |p, k| {
                if (p.alive and p.io_gl) {
                    _ = try vm.serviceGroupLeader(@intCast(k));
                }
            }
            if (vm.liveCount() == 0 and vm.parked_spawn.items.len == 0) {
                if (vm.timersPending()) {
                    try vm.advanceTimersToNext();
                    continue; // fired timers may have woken processes
                }
                break;
            }
            const n: u32 = @intCast(vm.procs.items.len);
            var pid: Pid = undefined;
            switch (self) {
                .round_robin => {
                    // next runnable at or after cursor, WITHIN the highest
                    // runnable priority class (gap-priority-classes).
                    const top = topRunnablePriority(vm) orelse .normal;
                    var k: u32 = 0;
                    pid = cursor;
                    while (k < n) : (k += 1) {
                        const cand: Pid = (cursor + k) % n;
                        if (schedulable(vm, cand) and // E6.4: skip suspended
                            vm.procs.items[cand].machine.priority == top)
                        {
                            pid = cand;
                            break;
                        }
                    }
                    cursor = (pid + 1) % n;
                },
                .seeded => {
                    // fair-but-random: random runnable, with a rotating
                    // guarantee — every N slices force the round-robin pick
                    // (keeps the no-starvation law honest by construction;
                    // the LAW still measures it)
                    // gap-priority-classes: the candidate set is the highest
                    // runnable class, THEN the existing fair-but-random pick
                    // inside it — so the within-class no-starvation guarantee
                    // the seeded engine carries is preserved exactly, one class
                    // at a time.
                    const top = topRunnablePriority(vm) orelse .normal;
                    var runnable: [64]Pid = undefined;
                    var rn: usize = 0;
                    for (0..vm.procs.items.len) |k| {
                        if (schedulable(vm, @intCast(k)) and // E6.4: skip suspended
                            vm.procs.items[k].machine.priority == top)
                        {
                            runnable[rn] = @intCast(k);
                            rn += 1;
                        }
                    }
                    if (rn == 0) break;
                    if (slice % (2 * rn + 1) == 0) {
                        pid = runnable[slice % rn];
                    } else {
                        pid = runnable[random.uintLessThan(usize, rn)];
                    }
                },
            }
            try vm.grant(pid, fuel_per_slice);
        }
    }

    /// gap-resident-node: the outcome of a resident drive. `done` = every process
    /// halted (clean shutdown); `idle` = the node is ALIVE but quiescent (all procs
    /// blocked in `receive`, no timers) and the bounded-idle budget was reached.
    pub const ResidentOutcome = enum { done, idle };

    /// gap-resident-node: drive the VM as a RESIDENT node — it STAYS UP while any
    /// process is alive (even if all are blocked in `receive`), firing timers, and
    /// halts cleanly only when `aliveCount()==0`. Distinct from `drive` (the
    /// one-shot ORACLE, kept byte-identical for the SMP engine + the
    /// `Scheduler_Signal.v` per-pair-order proof): `drive` exits the instant nothing
    /// is RUNNABLE, so a blocked-but-alive supervision tree looks like a deadlock;
    /// `driveResident` keeps that tree up until it exits. `idle_budget` bounds a
    /// genuinely-quiescent CLOSED-world node to the `.idle` verdict instead of
    /// spinning to `max_slices` (the bounded-idle law). The signal/delivery
    /// machinery (`grant`/`drainSignals`/`advanceTimersToNext`) is UNCHANGED, so the
    /// per-pair signal-order proof holds by construction — this only reclassifies
    /// the loop's quiescence predicate (the scheduling policy the proof already
    /// quantifies over).
    pub fn driveResident(self: Scheduler, vm: *Vm, fuel_per_slice: u64, max_slices: usize, idle_budget: usize) !ResidentOutcome {
        var prng = std.Random.DefaultPrng.init(switch (self) {
            .seeded => |s| s,
            .round_robin => 0,
        });
        const random = prng.random();
        var slice: usize = 0;
        var cursor: Pid = 0;
        var idle_ticks: usize = 0;
        while (slice < max_slices) : (slice += 1) {
            try vm.deliverParkedSpawn();
            try vm.pollActiveSockets(); // gap-socket-active-mode: {tcp,S,Data} delivery
            try vm.pollAcceptSockets(); // gap-cowboy-trap-accept: resume infinity-accept waiters
            for (vm.procs.items, 0..) |p, k| {
                if (p.alive and p.io_gl) _ = try vm.serviceGroupLeader(@intCast(k));
            }
            // gap-cowboy-trap-accept: a resident HTTP listener with pending socket
            // work (a suspended accept-waiter / an active stream socket) but NO
            // runnable proc must POLL-WAIT on its sockets, not busy-spin to .idle /
            // max_slices — a real server stays up for the next connection. Sleep a
            // short poll interval and re-poll (efficient, not a busy-spin; the next
            // pollAcceptSockets/pollActiveSockets services a ready socket).
            if (vm.anySocketWaiter()) {
                var any_run = false;
                for (0..vm.procs.items.len) |k| {
                    if (schedulable(vm, @intCast(k))) {
                        any_run = true;
                        break;
                    }
                }
                if (!any_run) {
                    // Reactor poll-wait: block up to 50ms until a listen/active fd is
                    // ready (or the timeout), then re-poll. Efficient kernel poll.
                    var fdbuf: [64]i32 = undefined;
                    var fdn: usize = 0;
                    for (vm.sockets.items) |*rs| {
                        if (fdn >= fdbuf.len) break;
                        if (!rs.alive) continue;
                        if ((rs.kind == .listen and rs.accept_waiters.items.len > 0) or (rs.kind == .stream and rs.active != 0)) {
                            fdbuf[fdn] = rs.fd;
                            fdn += 1;
                        }
                    }
                    socket_algebra.pollWait(fdbuf[0..fdn], 50);
                    idle_ticks = 0;
                    continue;
                }
            }
            if (vm.liveCount() == 0 and vm.parked_spawn.items.len == 0) {
                if (vm.timersPending()) {
                    try vm.advanceTimersToNext();
                    idle_ticks = 0; // progress: a timer fired (may have woken a proc)
                    continue;
                }
                // nothing runnable, no timers pending.
                if (vm.residentAliveCount() == 0) return .done; // no USER proc left → clean shutdown
                idle_ticks += 1; // ALIVE but idle (blocked in receive, closed world)
                if (idle_ticks >= idle_budget) return .idle; // bounded-idle verdict
                continue;
            }
            const n: u32 = @intCast(vm.procs.items.len);
            var pid: Pid = undefined;
            switch (self) {
                .round_robin => {
                    var k: u32 = 0;
                    pid = cursor;
                    while (k < n) : (k += 1) {
                        const cand: Pid = (cursor + k) % n;
                        if (schedulable(vm, cand)) {
                            pid = cand;
                            break;
                        }
                    }
                    cursor = (pid + 1) % n;
                },
                .seeded => {
                    var runnable: [64]Pid = undefined;
                    var rn: usize = 0;
                    for (0..vm.procs.items.len) |k| {
                        if (schedulable(vm, @intCast(k))) {
                            runnable[rn] = @intCast(k);
                            rn += 1;
                        }
                    }
                    if (rn == 0) {
                        if (vm.residentAliveCount() == 0) return .done;
                        idle_ticks += 1;
                        if (idle_ticks >= idle_budget) return .idle;
                        continue;
                    }
                    if (slice % (2 * rn + 1) == 0) {
                        pid = runnable[slice % rn];
                    } else {
                        pid = runnable[random.uintLessThan(usize, rn)];
                    }
                },
            }
            try vm.grant(pid, fuel_per_slice);
            idle_ticks = 0; // progress: a slice ran
        }
        // max_slices reached while still busy — a long-running node (a self-ticking
        // tree); the run budget bounds it. A genuinely-idle node returned .idle above.
        return .done;
    }
};

// ============================================================================
// E6.1 (Task 1): the SMP scheduler ENGINE — N per-scheduler run queues + work
// stealing. The scheduler ALGEBRA is UNCHANGED: `Scheduler.round_robin` is the
// ORACLE and the SMP engine is admitted ONLY by trace/differential equivalence
// against it (SC-20.1). THE KEY DESIGN INSIGHT — why the SACRED M7 per-pair
// signal-order law survives SMP: ALL inter-process signalling flows through the
// SINGLE stamping authority `Vm.signal` (a global monotonic `next_stamp`), and
// `drainSignals` delivers in that stamp order — so the scheduler decides only
// WHEN a process runs, NEVER the delivery order of a pair's signals. Per-pair
// order is therefore a representation invariant of the signal layer, held under
// ANY schedule; the scheduler cannot reorder a pair without also breaking mutual
// exclusion (running one process on two schedulers), which CONSERVATION forbids.
//
// Two encodings (initial/final, glued by "same denote()"):
//   * `driveModel` — a DETERMINISTIC seeded interleaving of the run-queue +
//     work-stealing logic (reproducible, seed-echoing, mutant-killable): the
//     model ORACLE the laws are proven over. Bounded by `max_steps` — a
//     non-completing schedule is a FAILED law, never a hung loop.
//   * `driveThreads` — the REAL `std.Thread` workers behind a Stratum-C VM-lock
//     seam: one coarse atomic spinlock makes every VM mutation a critical
//     section (zero data races, thread-sanitizer-friendly). Bounded joins: each
//     worker is capped by a grant count + a wall deadline, so `join` ALWAYS
//     returns (a deadlock blows the bound). Admitted by producing the ORACLE's
//     denote().
// ============================================================================

pub const SmpEngine = struct {
    n_sched: u32,
    seed: u64,

    pub const MAX_SCHED = 8;

    /// A raw monotonic-ns read (the `time_algebra.RealSource` raw-`clock_gettime`
    /// precedent — no libc; linux-only, as the whole VM already is). The wall
    /// bound the bounded-joins law rides; a failed syscall reads 0 (degenerate
    /// but total). NOT a semantic clock — only the thread deadline uses it.
    pub fn nowNs() u64 {
        var ts: std.os.linux.timespec = undefined;
        if (@as(isize, @bitCast(std.os.linux.clock_gettime(.MONOTONIC, &ts))) < 0) return 0;
        return @as(u64, @intCast(ts.sec)) *% 1_000_000_000 +% @as(u64, @intCast(ts.nsec));
    }

    /// A pid's HOME scheduler (static partition by pid; stealing moves work off
    /// its home onto an idle scheduler — the migration CA-20 realizes).
    fn home(self: SmpEngine, pid: Pid) u32 {
        return homeOf(pid, self.n_sched);
    }

    /// gap-b-5a: the STATIC home-scheduler map (pid mod n) — usable by `Vm.drainReady`
    /// (push-based discovery), which knows `n_sched` but not the `SmpEngine` value.
    /// Identical policy to `home`; a `home(pid) == homeOf(pid, n_sched)` identity.
    fn homeOf(pid: Pid, n_sched: u32) u32 {
        return @intCast(pid % n_sched);
    }

    /// CONSERVATION probe: how many of the `n` run queues currently hold `pid`.
    /// The invariant is ≤ 1 at every observable step (a pid is runnable on at
    /// most one scheduler); a lost steal (mutant m1) makes it 2 → the law reds.
    fn queueCountOf(qs: []const std.ArrayList(Pid), n: u32, pid: Pid) usize {
        var c: usize = 0;
        var s: u32 = 0;
        while (s < n) : (s += 1) {
            for (qs[s].items) |p| if (p == pid) {
                c += 1;
            };
        }
        return c;
    }

    fn queueTotal(qs: []const std.ArrayList(Pid), n: u32) usize {
        var t: usize = 0;
        var s: u32 = 0;
        while (s < n) : (s += 1) t += qs[s].items.len;
        return t;
    }

    /// Enqueue every runnable pid that is NOT already in some queue at its home
    /// scheduler's tail — the "newly runnable" discovery (spawned children,
    /// receivers woken by an incoming signal). Never enqueues twice (the
    /// `queueCountOf == 0` guard is the conservation invariant at the source).
    /// gap-b-5a: this scanning `discover` now serves ONLY the single-threaded
    /// `driveModel` (the deterministic oracle for scheduler-count invariance),
    /// where the `procs` scan is race-free. The REAL-THREAD worker uses PUSH-based
    /// discovery (`Vm.drainReady`) instead, so it never scans `procs`. Ownership
    /// now lives in the `L_c`-domain `vm.owned[pid]` array (relocated out of
    /// `Process`); in the single-threaded model nothing is ever owned, so this
    /// reads `null` throughout — behaviour-identical to the old `p.owned_by`.
    fn discover(self: SmpEngine, vm: *Vm, qs: []std.ArrayList(Pid), gpa: std.mem.Allocator) !void {
        for (0..vm.procs.items.len) |i| {
            const pid: Pid = @intCast(i);
            if (vm.owned.items[pid].load(.monotonic) == NO_OWNER and schedulable(vm, pid) and queueCountOf(qs, self.n_sched, pid) == 0) { // E6.4 skip suspended; e48-smp-s3 skip OWNED (no double-grant)
                try qs[self.home(pid)].append(gpa, pid);
            }
        }
    }

    pub const ModelRun = struct {
        /// AND over every step: the popped/granted pid was in NO queue while it
        /// ran (mutual exclusion) and no pid was ever in two queues. A lost
        /// steal breaks this.
        conserved: bool,
        steps: usize,
        grants: usize,
    };

    /// Drive the VM to quiescence under a DETERMINISTIC seeded SMP schedule.
    /// Bounded by `max_steps`; returns the conservation observation. Each step
    /// grants exactly one process (its own queue head, else a stolen victim
    /// tail) and re-enqueues it on the granting scheduler if still runnable.
    pub fn driveModel(self: SmpEngine, vm: *Vm, fuel: u64, max_steps: usize) !ModelRun {
        std.debug.assert(self.n_sched >= 1 and self.n_sched <= MAX_SCHED);
        const gpa = vm.gpa;
        var qs: [MAX_SCHED]std.ArrayList(Pid) = undefined;
        for (&qs) |*q| q.* = .empty;
        defer for (&qs) |*q| q.deinit(gpa);

        var prng = std.Random.DefaultPrng.init(self.seed);
        const random = prng.random();

        var conserved = true;
        var step: usize = 0;
        var grants: usize = 0;
        while (step < max_steps) : (step += 1) {
            try vm.deliverParkedSpawn();
            try self.discover(vm, &qs, gpa);

            // conservation invariant (measured every step, before scheduling):
            // no runnable pid sits in two queues at once.
            {
                var pid: Pid = 0;
                while (pid < vm.procs.items.len) : (pid += 1) {
                    if (queueCountOf(&qs, self.n_sched, pid) > 1) conserved = false;
                }
            }

            if (queueTotal(&qs, self.n_sched) == 0) break; // quiescent (no runnable)

            // pick a scheduler (seeded), then take its head or STEAL a victim
            // tail. Stealing always makes progress while ANY queue is nonempty,
            // so the loop never livelocks.
            const s = random.uintLessThan(u32, self.n_sched);
            var pid: Pid = undefined;
            if (qs[s].items.len > 0) {
                pid = qs[s].orderedRemove(0); // FIFO head off own queue
            } else {
                // steal from the seeded-first nonempty OTHER queue's TAIL. The
                // steal REMOVES the victim (mutant m1 leaves it → conservation).
                var found = false;
                var k: u32 = 0;
                while (k < self.n_sched) : (k += 1) {
                    const v = (s + 1 + k) % self.n_sched;
                    if (qs[v].items.len > 0) {
                        pid = qs[v].pop().?; // victim TAIL, removed
                        found = true;
                        break;
                    }
                }
                if (!found) break; // nothing to run anywhere
            }
            // mutual exclusion: the running pid is now in no queue.
            if (queueCountOf(&qs, self.n_sched, pid) != 0) conserved = false;

            try vm.grant(pid, fuel);
            grants += 1;

            // migration: a still-runnable process re-enters THIS scheduler's
            // queue tail (mutant m2 drops this → the process is lost → the ring
            // never completes → the invariance/completion law reds).
            if (schedulable(vm, pid)) { // E6.4: a just-suspended process does not re-enqueue
                try qs[s].append(gpa, pid);
            }
        }
        return .{ .conserved = conserved, .steps = step, .grants = grants };
    }

    // -- E6.6 (Task 6): the DIRTY POOL model ---------------------------------
    //
    // Dirty schedulers are, algebraically, EXTRA run queues: a dirty-tagged
    // process (one entering a dirty-cpu/dirty-io BIF) migrates OFF a normal
    // scheduler onto a dirty pool queue, runs there, and migrates BACK when the
    // dirty BIF returns. The `grant` is IDENTICAL wherever a process runs (the
    // single stamping authority `Vm.signal` still orders every signal — the M7
    // key insight), so routing through a dirty queue NEVER changes `denote`:
    //
    //   DIRTY-MIGRATION HOMOMORPHISM: denote(driveModelDirty) == denote(driveModel)
    //
    // over the confluent corpus. And because signals to a process on the dirty
    // pool are stamped by the same authority and delivered on its return (parked
    // in its mailbox, discovered on the next tick), the SACRED per-pair order is
    // preserved across a dirty round-trip (SIGNAL-DELIVERY-TO-A-DIRTY-PROCESS).

    /// Two dirty pools: index 0 = dirty CPU, index 1 = dirty IO.
    const DIRTY_POOLS = 2;

    fn dirtyBit(pid: Pid) u64 {
        return if (pid < 64) (@as(u64, 1) << @intCast(pid)) else 0;
    }

    /// Drive to quiescence with the `dirty0` pids routed through the dirty pools.
    /// Each dirty grant MIGRATES the process BACK to a normal scheduler on return
    /// (the dirty BIF completed) — the round-trip whose homomorphism the law pins.
    /// Bounded by `max_steps`; conservation is measured across BOTH pools.
    pub fn driveModelDirty(self: SmpEngine, vm: *Vm, fuel: u64, max_steps: usize, dirty0: u64) !ModelRun {
        std.debug.assert(self.n_sched >= 1 and self.n_sched <= MAX_SCHED);
        const gpa = vm.gpa;
        var nq: [MAX_SCHED]std.ArrayList(Pid) = undefined; // normal pools
        for (&nq) |*q| q.* = .empty;
        defer for (&nq) |*q| q.deinit(gpa);
        var dq: [DIRTY_POOLS]std.ArrayList(Pid) = undefined; // dirty CPU/IO pools
        for (&dq) |*q| q.* = .empty;
        defer for (&dq) |*q| q.deinit(gpa);

        var dirty = dirty0; // the CURRENT dirty membership (cleared on return)
        var prng = std.Random.DefaultPrng.init(self.seed);
        const random = prng.random();

        var conserved = true;
        var step: usize = 0;
        var grants: usize = 0;

        // count occurrences of `pid` across BOTH pools (the ≤1 conservation invariant).
        const bothCount = struct {
            fn f(n: [*]const std.ArrayList(Pid), nn: u32, d: [*]const std.ArrayList(Pid), pid: Pid) usize {
                var c = queueCountOf(n[0..nn], nn, pid);
                var k: u32 = 0;
                while (k < DIRTY_POOLS) : (k += 1) for (d[k].items) |p| {
                    if (p == pid) c += 1;
                };
                return c;
            }
        }.f;

        while (step < max_steps) : (step += 1) {
            try vm.deliverParkedSpawn();
            // discovery: a schedulable pid in NO queue enters its home pool — the
            // dirty-tagged ones onto a dirty pool, the rest onto their normal home.
            for (0..vm.procs.items.len) |i| {
                const pid: Pid = @intCast(i);
                if (schedulable(vm, pid) and bothCount(&nq, self.n_sched, &dq, pid) == 0) {
                    if (dirty & dirtyBit(pid) != 0) {
                        try dq[pid % DIRTY_POOLS].append(gpa, pid);
                    } else {
                        try nq[self.home(pid)].append(gpa, pid);
                    }
                }
            }

            // conservation: no runnable pid sits in two queues at once.
            {
                var pid: Pid = 0;
                while (pid < vm.procs.items.len) : (pid += 1) {
                    if (bothCount(&nq, self.n_sched, &dq, pid) > 1) conserved = false;
                }
            }

            const dirty_total = dq[0].items.len + dq[1].items.len;
            if (queueTotal(&nq, self.n_sched) + dirty_total == 0) break; // quiescent

            // seeded pick: service a dirty pool (when nonempty) or a normal one.
            var pid: Pid = undefined;
            var was_dirty = false;
            if (dirty_total > 0 and random.boolean()) {
                const d = random.uintLessThan(u32, DIRTY_POOLS);
                const use: u32 = if (dq[d].items.len > 0) d else (d + 1) % DIRTY_POOLS;
                pid = dq[use].orderedRemove(0);
                was_dirty = true;
            } else {
                const s = random.uintLessThan(u32, self.n_sched);
                if (nq[s].items.len > 0) {
                    pid = nq[s].orderedRemove(0);
                } else {
                    // steal a normal victim tail, else fall back to a dirty pool.
                    var found = false;
                    var k: u32 = 0;
                    while (k < self.n_sched) : (k += 1) {
                        const v = (s + 1 + k) % self.n_sched;
                        if (nq[v].items.len > 0) {
                            pid = nq[v].pop().?;
                            found = true;
                            break;
                        }
                    }
                    if (!found) {
                        const use: u32 = if (dq[0].items.len > 0) 0 else 1;
                        pid = dq[use].orderedRemove(0);
                        was_dirty = true;
                    }
                }
            }
            if (bothCount(&nq, self.n_sched, &dq, pid) != 0) conserved = false;

            try vm.grant(pid, fuel);
            grants += 1;

            // MIGRATION BACK: a dirty grant "returned" from its dirty BIF, so the
            // process leaves the dirty set and re-enters a NORMAL scheduler.
            // (mutant m1 target: dropping this re-enqueue loses the process → the
            // dirty ring never completes → the homomorphism/completion law reds.)
            if (was_dirty) dirty &= ~dirtyBit(pid);
            if (schedulable(vm, pid)) {
                try nq[self.home(pid)].append(gpa, pid);
            }
        }
        return .{ .conserved = conserved, .steps = step, .grants = grants };
    }

    // -- the real-thread engine (Stratum-C seam) -----------------------------

    // The Stratum-C VM lock (`L_v`) — S-epoch Option B LIFTED it to module
    // scope (see `VmLock` next to `EventLock`) so `drainSignals` can escalate
    // onto it through `tl_drain_lv`. `ThreadCtx.mutex` below is unchanged.

    /// e48-smp-s4: the fairness stride — at most FAIR_STRIDE-1 consecutive
    /// own-queue (locality) grants before a FORCED rotation pick; any
    /// non-empty queue is serviced within n*FAIR_STRIDE grants (proved:
    /// Sampler_Fairness.v hybrid section).
    const FAIR_STRIDE: usize = 4;

    const ThreadCtx = struct {
        engine: SmpEngine,
        vm: *Vm,
        gpa: std.mem.Allocator,
        mutex: VmLock = .{},
        // e48-smp-s3: procs currently OWNED by a worker (lock-guarded). The
        // quiescence verdict must include it: empty queues while a peer still
        // RUNS a proc is NOT quiescent (that proc may wake/spawn more work) —
        // the premature-done race the unlocked run window opens.
        // N5: atomic so the idle peek reads it lock-free; every MUTATION stays
        // inside an `L_c` section (the coherency unit is unchanged).
        owned_count: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),
        // N7: per-WORKER event shards (see `SeqEvent`). Registered into the
        // worker's threadlocal at thread start, merged seq-sorted at the join.
        event_shards: [MAX_SCHED]std.ArrayList(SeqEvent) = undefined,
        qs: [MAX_SCHED]std.ArrayList(Pid),
        fuel: u64,
        // S-epoch S-shard-grants (DIVERGENCE 612): the SHARED grant/fairness counter,
        // relocated from an `L_v`-guarded `usize` to a lock-free ATOMIC. It was
        // incremented under a STANDALONE `L_v` acquire every grant (the pure
        // counter-bump critical section) — the residual `L_v` term the SMP-OBS
        // contention measurement attributed (L_v wait_p99 dominates). As an atomic
        // monotonic counter the bump takes NO lock, removing one full `L_v` acquire
        // per grant. Denotation-identical: the counter VALUE is unchanged; the
        // fairness stride reads a possibly-momentarily-stale snapshot, which only
        // steers WHICH non-empty queue is served (fairness), never correctness
        // (Sampler_Fairness.v). Reads use `.monotonic` (a counter, not a lock).
        grants: std.atomic.Value(usize) = std.atomic.Value(usize).init(0),
        max_grants: usize,
        deadline_ns: u64,
        // sender-narrowing N2a (DIVERGENCE 616): done/err are LOCK-FREE atomic
        // latches (they were L_v-domain — the top-of-loop exit check took a
        // full L_v acquire EVERY worker iteration, the 57%-dominant site the
        // per-site probe attributed). `err_code` holds @intFromError(e)
        // (0 = none); the FIRST error wins via cmpxchg; `done` is a plain
        // release/acquire bool. Latching needs no lock and no order slot.
        done: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
        err_code: std.atomic.Value(u16) = std.atomic.Value(u16).init(0),

        fn latchErr(ctx: *ThreadCtx, e: anyerror) void {
            _ = ctx.err_code.cmpxchgStrong(0, @intCast(@intFromError(e)), .acq_rel, .monotonic);
            ctx.done.store(true, .release);
        }
    };

    fn worker(ctx: *ThreadCtx, id: u32) void {
        // N7: register this worker's event shard — every emitEvent on this
        // thread now appends lock-free with an atomic seq stamp.
        tl_event_buf = &ctx.event_shards[id];
        defer tl_event_buf = null;
        while (true) {
            // N2a: the exit check is LOCK-FREE — no L_v at the loop top.
            if (ctx.done.load(.acquire) or ctx.err_code.load(.acquire) != 0 or ctx.grants.load(.monotonic) >= ctx.max_grants or nowNs() >= ctx.deadline_ns) {
                return; // bounded exit — the join ALWAYS returns
            }
            // e48-smp-s4: the FAIRNESS STRIDE — a worker may serve its OWN
            // queue (locality, the work-stealing win) except on every
            // FAIR_STRIDE-th grant, which FORCES a rotation pick whose start
            // advances with (grants / FAIR_STRIDE) — so any non-empty queue is
            // serviced within n*FAIR_STRIDE grants REGARDLESS of which OS
            // threads run (the Sampler_Fairness.v hybrid theorems). An empty
            // own queue steals via the same rotation scan (FIFO steal).
            // e48-smp-s1: the COORDINATOR PHASE under the lock — the global
            // scheduler-tick services (BOTH parked queues; the old worker ran
            // only the spawn side here and leaned on grant's internal delivery
            // for systasks — the phase split makes the tick service explicit
            // and exactly-once per iteration) + discovery. The per-proc phase
            // below is `grantOnly` — it never touches the global lists, which
            // is what lets S3 narrow the lock around it.
            // N2a: the parked tick takes `L_v` ONLY when parked work EXISTS —
            // the `parked_nonempty` atomic (set by every publish under `L_c`)
            // is claimed BEFORE the drain, so a publish racing the drain
            // re-arms it for the next iteration (never a stranded park; the
            // publisher still owns its proc, so quiescence cannot be declared
            // before the flag is visible). The common idle iteration now
            // acquires NO lock at all.
            if (ctx.vm.parked_nonempty.load(.acquire)) {
                // N9-Q1: `delivering` brackets the WHOLE tick (claim included)
                // so the atomics-only quiescence cannot fire between a
                // delivery's Dekker flag-win and its queue append.
                _ = ctx.vm.delivering.fetchAdd(1, .seq_cst);
                ctx.vm.parked_nonempty.store(false, .release);
                ctx.mutex.lock();
                ctx.vm.deliverParkedSpawn() catch |err| {
                    ctx.mutex.unlock();
                    _ = ctx.vm.delivering.fetchSub(1, .seq_cst);
                    ctx.latchErr(err);
                    return;
                };
                ctx.vm.deliverParkedSysTask() catch |err| {
                    ctx.mutex.unlock();
                    _ = ctx.vm.delivering.fetchSub(1, .seq_cst);
                    ctx.latchErr(err);
                    return;
                };
                ctx.mutex.unlock();
                _ = ctx.vm.delivering.fetchSub(1, .seq_cst);
            }
            // gap-b-5 (THE LOCK FLIP): snapshot the SHARED grant counter under `L_v`
            // (its home domain — incremented in the epilogue under `L_v`) for the
            // pick's fairness heuristic, so the `L_c`-alone section below touches NO
            // `L_v`-domain field. A momentarily-stale stride only steers WHICH
            // non-empty queue is served (fairness), never correctness (denotation/
            // conservation). `n` is immutable engine config.
            const grants_snap = ctx.grants.load(.monotonic);
            const n = ctx.engine.n_sched;
            // (gap-b-5's FLIP is now total: N2a removed the loop-top L_v hold
            // entirely, so there is nothing to release here any more.)

            // N5 (DIVERGENCE 619): the LOCK-FREE idle peek — if the runnable
            // HINT says nothing is queued anywhere, skip the `L_c` coordinator
            // tick entirely. The hint may be momentarily stale EITHER way:
            // a false-positive costs one truthful (as-today) L_c tick; a
            // false-negative defers the tick one iteration (the enqueue's
            // fetchAdd is visible to the next peek — bounded, never lost).
            // QUIESCENCE IS NEVER DECLARED FROM THE HINT: when the peek says
            // idle AND nothing is owned, we take `L_c` and re-observe the REAL
            // state (queues + owned + ready) — the stable-fixed-point argument
            // is unchanged; the peek only decides whether the probe is worth
            // taking. While a peer RUNS a proc (owned>0, queues empty) the
            // idle worker now touches NO lock at all.
            if (ctx.vm.runnable_total.load(.seq_cst) == 0) {
                // N9-Q1: ATOMICS-ONLY quiescence. Invariant: at every instant,
                // pending work is visible in >=1 of {runnable_total (bumped
                // BEFORE any queue append), owned_count (a running proc),
                // delivering (a parked tick in flight)} — so the triple-zero
                // read, with runnable re-checked LAST, is a stable fixed point.
                if (ctx.owned_count.load(.seq_cst) == 0 and ctx.vm.delivering.load(.seq_cst) == 0) {
                    if (ctx.vm.runnable_total.load(.seq_cst) == 0) {
                        ctx.done.store(true, .release);
                    }
                }
                std.Thread.yield() catch {};
                continue;
            }

            // ---- N9-Q1 (DIVERGENCE 623): the LOCK-FREE-COORDINATED pick ----
            // The old single-`L_c` drain/pick/mark-owned section is gone. The
            // pick pops from a per-worker `QLock` queue (own first, else the
            // grant-stride rotation steal — NEVER two QLocks held), then takes
            // ownership by fail-closed CAS (SC-N9-2: a queued pid is owned by
            // nobody — a CAS failure is a conservation breach and PANICS at
            // the acquire, the UCA-SMP-9 pattern applied to ownership), then
            // clears the dedup bit (only the popper does) and settles the
            // hint. Conservation transition queued→owned is: pop-under-QLock
            // (sole popper) → CAS(NO_OWNER→id) (sole owner) → dedup clear.
            var pid: ?Pid = null;
            {
                const forced = (grants_snap % FAIR_STRIDE) == 0;
                if (!forced) {
                    ctx.vm.qlocks[id].lock();
                    if (ctx.vm.run_qs[id].items.len > 0) pid = ctx.vm.run_qs[id].orderedRemove(0);
                    ctx.vm.qlocks[id].unlock();
                }
                if (pid == null) {
                    // FAIRNESS backstop / steal: rotation scan, stride-advanced
                    // (CAST-19: source selection is a function of the grant
                    // sequence, never of which OS thread got CPU).
                    const start_q: u32 = @intCast((grants_snap / FAIR_STRIDE) % n);
                    var k: u32 = 0;
                    while (k < n) : (k += 1) {
                        const v = (start_q + k) % n;
                        ctx.vm.qlocks[v].lock();
                        if (ctx.vm.run_qs[v].items.len > 0) pid = ctx.vm.run_qs[v].orderedRemove(0);
                        ctx.vm.qlocks[v].unlock();
                        if (pid != null) break;
                    }
                }
            }
            if (pid == null) {
                // hint said runnable>0 but the queues raced empty (a pick on
                // another worker won) — just retry; quiescence is the peek's job.
                std.Thread.yield() catch {};
                continue;
            }
            if (ctx.vm.owned.items[pid.?].cmpxchgStrong(NO_OWNER, id, .seq_cst, .seq_cst)) |cur| {
                std.debug.panic("N9 ownership conservation violated (SC-N9-2): pid {d} popped from a run queue but already owned by {d}", .{ pid.?, cur });
            }
            // N9 TSan fix: we are the OWNER now — `alive`/`status` reads are
            // safe. A spurious queue entry (dead/suspended pid — lock-free
            // enqueues no longer pre-check) is absorbed here by a mini-release
            // (Dekker order preserved), with NO grant emitted.
            if (!schedulable(ctx.vm, pid.?)) {
                _ = ctx.owned_count.fetchAdd(1, .seq_cst);
                ctx.vm.queued.items[pid.?].store(false, .seq_cst);
                _ = ctx.vm.runnable_total.fetchSub(1, .seq_cst);
                ctx.vm.owned.items[pid.?].store(NO_OWNER, .seq_cst);
                if (ctx.vm.pending_wake_a.items[pid.?].swap(false, .seq_cst)) {
                    if (ctx.vm.stable_procs.get(pid.?)) |bp| ctx.vm.applyWake(bp);
                    ctx.vm.enqueueDirect(pid.?) catch |err| {
                        _ = ctx.owned_count.fetchSub(1, .seq_cst);
                        ctx.latchErr(err);
                        return;
                    };
                }
                _ = ctx.owned_count.fetchSub(1, .seq_cst);
                std.Thread.yield() catch {};
                continue;
            }
            // OVERLAP INVARIANT (quiescence soundness): the destination
            // counter rises BEFORE the source falls, so at every instant of
            // the queued->owned transition at least one of {runnable_total,
            // owned_count} is nonzero and the atomics-only quiescence read can
            // never catch the pid "between" counters.
            _ = ctx.owned_count.fetchAdd(1, .seq_cst);
            ctx.vm.queued.items[pid.?].store(false, .seq_cst);
            _ = ctx.vm.runnable_total.fetchSub(1, .seq_cst); // N5 hint

            // ---- L_v SECTION 2: grant event + proc deref + drain signals ----
            // gap-b-5: re-acquire `L_v` ALONE (nothing held → no back-edge) for the
            // residual `L_v`-domain ops: the grant event write (now `emitEvent`, which
            // self-locks `L_events` for the append — the sanctioned `L_v→L_events`
            // down-edge, gap-b-5b), the `vm.procs` deref, and `drainSignals` (writes
            // deliver events via `emitEvent`; takes `L_timer` via `applyWake` — the
            // sanctioned `L_v→L_timer` down-edge). Option B narrowed this site's `L_v`
            // to the brief `vm.procs` deref; the drain itself runs OFF `L_v` via the
            // `tl_drain_lv` escalation. The pid is already OWNED, so no peer can pick it
            // in the gap between the two locks and the system stays non-quiescent. On
            // grant-event OOM, roll ownership back under `L_c` — here `L_v→L_c` IS the
            // sanctioned order (hold `L_v`, reach DOWN to `L_c`), the mirror of the
            // up-edge the flip forbids.
            // S-shard-grant-emit (DIVERGENCE 613, S-epoch Option A): the grant EVENT
            // needs only `L_events` (a leaf, self-locked in `emitEvent`) — emit it
            // WITHOUT `L_v` held, shortening SECTION 2's `L_v` hold to the genuinely
            // `L_v`-domain ops (the `procs` deref + `drainSignals`). Safe + gate-
            // certifiable (NOT a nondeterministic race): `emitEvent` is `L_events`-
            // serialized, so the grant event is still atomically appended by the single
            // writer — only its position moves, and the per-pair SEND/DELIVER order law
            // is unaffected (it inspects deliver stamps, not grant events). The rare
            // OOM rollback takes `L_c` from an EMPTY held-set (in-order), then latches
            // under `L_v` alone. The dominant `drainSignals` hold — Option A's stated
            // residual — is now GONE too: Option B (below, DIVERGENCE 614) de-globalized
            // `sigq` under the `L_sigq` leaf and runs the drain off `L_v`.
            ctx.vm.emitEvent(.{ .grant = pid.? }) catch |err| {
                // N9-Q1: ownership rollback is atomic — no lock needed.
                ctx.vm.owned.items[pid.?].store(NO_OWNER, .seq_cst);
                _ = ctx.owned_count.fetchSub(1, .monotonic);
                ctx.latchErr(err); // N2a: lock-free latch
                return;
            };
            // S-epoch Option B (DIVERGENCE 614): SECTION 2's `L_v` hold no longer
            // spans the drain. The `procs`-array deref stays under a BRIEF `L_v`
            // (the array reallocs on spawn; the box `vp` is heap-stable and safe
            // to hold across the unlock). The drain itself runs OFF `L_v` with
            // the ESCALATION pointer set: `drainSignals` takes `L_v` only for
            // the detach and the `L_v`-domain arms (exit/down/link/unlink +
            // emitTrace), delivering the owner-exclusive message bulk lock-free.
            // This worker is the ONLY setter of its threadlocal — every other
            // drain call (interpret paths, under a HELD `L_v`) sees `null`.
            var run_err: ?anyerror = null;
            // Option B: ONE `L_v` acquire serves both the `procs` deref and
            // the sigq detach — the drain stashes the stable box in
            // `tl_drain_vp` (acquire-merge; the A/B probe attributed the
            // extra pre-deref hold). The bulk then delivers off `L_v`.
            tl_drain_lv = &ctx.mutex;
            tl_drain_vp = null;
            ctx.vm.drainSignals(pid.?) catch |err| {
                run_err = err;
            };
            tl_drain_lv = null;
            const vp: *Process = tl_drain_vp orelse blk: {
                // drain saw no live proc (cannot happen for a just-granted
                // owned pid, but stay total): deref under a brief hold.
                ctx.mutex.lock();
                defer ctx.mutex.unlock();
                break :blk ctx.vm.procs.items[pid.?];
            };
            tl_drain_vp = null;

            // ---- UNLOCKED: the per-process machine run ----
            if (run_err == null and vp.alive) {
                const m = &vp.machine;
                // R2b: bound the parallel-worker grant on `m.instrs` (preemption
                // currency), byte-identical to the pre-R2b reductions-fuel model.
                const target_reds = m.instrs + ctx.fuel;
                while (vp.alive and m.status == .running and m.instrs < target_reds) {
                    ia.run(m, vp.prog, target_reds - m.instrs) catch |err| {
                        run_err = err;
                        break;
                    };
                    if (m.pending != null) {
                        // a trapped effect is Vm work — take the lock for it
                        ctx.mutex.lock();
                        ctx.vm.interpret(pid.?) catch |err| {
                            run_err = err;
                        };
                        if (run_err == null) ctx.vm.drainSignals(pid.?) catch |err| {
                            run_err = err;
                        };
                        ctx.mutex.unlock();
                        if (run_err != null) break;
                    }
                }
            }

            // ---- L_v SECTION A (gap-b-6): exits + staged-park SNAPSHOT ----
            // gap-b-6 (SMP step 6, the EPILOGUE narrowing — symmetric to gap-b-5's
            // prologue flip): the L_c-domain parked-list PUBLISH is lifted OUT of the
            // `L_v` hold into an `L_c`-ALONE section (below). Exits STAY here — they
            // touch `procs`/`vm.events`/`sigq`/`dyn_code`, all genuinely `L_v`-domain.
            // The staged parks are grant-local ONLY because `L_v` serializes the
            // `interpret` writes that fill `staged_*` against this drain, so the drain
            // SOURCE read must stay under `L_v`: we take a grant-local zero-copy
            // SNAPSHOT here (move the backing buffer out, reset `staged_*` to empty)
            // and publish the snapshot into the coherency-domain `parked_*` under
            // `L_c`-ALONE. The DESTINATION `parked_*` append is the `L_c`-contended
            // write (it serializes with peers' `deliverParked*`/abandon on `L_c`);
            // moving it off `L_v` lets a peer that only needs `L_v` proceed during this
            // worker's parked append. In the common (no-parks) case this ALSO drops the
            // per-grant `L_c` acquire that `applyStagedParks` always took.
            // N3 (DIVERGENCE 617): SECTION A's per-grant L_v acquire is now
            // CONDITIONAL. The exit check reads OWNER-EXCLUSIVE state
            // (`vp.alive`, `vp.machine.status` — written only by this worker's
            // own run/interpret while owned), so it needs no lock; the staged
            // snapshot is gated on the `staged_nonempty` atomic armed by the
            // staging sites (which run under L_v — arm/clear totally ordered).
            // The common grant (no exit, nothing staged) takes NO L_v here.
            // The staging grant's OWN interpret armed the flag before its
            // epilogue (program order), and the pid stays owned until SECTION
            // B — so a staged park is always published before quiescence can
            // fire (the n2a-parked-flag law drives this chain end-to-end).
            var snap_spawn: @TypeOf(ctx.vm.staged_spawn) = .empty;
            var snap_systask: @TypeOf(ctx.vm.staged_systask) = .empty;
            const needs_exit = run_err == null and vp.alive and
                (vp.machine.status == .halted or vp.machine.status == .crashed);
            if (needs_exit or (run_err == null and ctx.vm.staged_nonempty.load(.acquire))) {
                ctx.mutex.lock();
                if (run_err == null and vp.alive) {
                    if (vp.machine.status == .halted) ctx.vm.normalExit(pid.?) catch |err| {
                        run_err = err;
                    };
                    if (run_err == null and vp.machine.status == .crashed and vp.alive) {
                        // DIVERGENCE 683: cook the self-inflicted exit reason by
                        // class before propagating (mirrors the sequential path).
                        const r = vp.machine.cookedExitReason() catch |err| blk: {
                            run_err = err;
                            break :blk vp.machine.result;
                        };
                        ctx.vm.terminate(pid.?, r) catch |err| {
                            run_err = err;
                        };
                    }
                }
                // gap-b-6: SNAPSHOT the staged parks under `L_v` (zero-copy MOVE —
                // `staged_*` is `L_v`-domain: filled by `interpret` under `L_v`, so
                // the read must exclude a concurrent `interpret`). On the abort path
                // the snapshot is skipped, matching the old `run_err == null` guard.
                if (run_err == null) {
                    ctx.vm.staged_nonempty.store(false, .release); // clear INSIDE the hold
                    snap_spawn = ctx.vm.staged_spawn;
                    ctx.vm.staged_spawn = .empty;
                    snap_systask = ctx.vm.staged_systask;
                    ctx.vm.staged_systask = .empty;
                }
                ctx.mutex.unlock(); // gap-b-6 THE EPILOGUE FLIP: publish runs under `L_c` ALONE

            }

            // ---- L_c-ALONE (gap-b-6): publish the snapshot into the parked lists ----
            // The pid is STILL OWNED here (`owned[pid]`/`owned_count` cleared only in
            // SECTION B below), so the system is provably NON-QUIESCENT during the
            // publish: a peer's quiescence test (`owned_count == 0` under `L_c`) cannot
            // fire, so NO park is lost to premature quiescence. The append is atomic
            // w.r.t. `deliverParked*`/abandon via `L_c` (all take `L_c`); the parks
            // being published belong to THIS pid (filled by its `interpret`), and the
            // pid cannot run its next grant — hence cannot `spawn_request_abandon` them
            // — while still owned, so no abandon races this publish. NO `L_v` is
            // acquired while holding `L_c` (no `L_c→L_v` back-edge): on OOM we release
            // `L_c` FIRST, then take `L_v` ALONE to roll ownership back + latch.
            if (snap_spawn.items.len != 0 or snap_systask.items.len != 0) {
                ctx.vm.l_c.lock();
                const pub_err: ?anyerror = blk: {
                    if (snap_spawn.items.len != 0) ctx.vm.parked_spawn.appendSlice(ctx.gpa, snap_spawn.items) catch |err| break :blk err;
                    if (snap_systask.items.len != 0) ctx.vm.parked_systask.appendSlice(ctx.gpa, snap_systask.items) catch |err| break :blk err;
                    break :blk null;
                };
                // N2a: arm the parked-work flag inside the same `L_c` section.
                if (pub_err == null) ctx.vm.parked_nonempty.store(true, .release);
                ctx.vm.l_c.unlock();
                snap_spawn.deinit(ctx.gpa);
                snap_systask.deinit(ctx.gpa);
                if (pub_err) |err| {
                    // N9-Q1: ownership rollback is atomic — no locks needed.
                    ctx.vm.owned.items[pid.?].store(NO_OWNER, .seq_cst);
                    _ = ctx.owned_count.fetchSub(1, .monotonic);
                    ctx.latchErr(err); // N2a: lock-free latch
                    return;
                }
            } else {
                snap_spawn.deinit(ctx.gpa);
                snap_systask.deinit(ctx.gpa);
            }

            // ---- N9-Q1 SECTION B: the DEKKER release (SC-N9-1) ----
            // Announce NO_OWNER FIRST (.seq_cst), then consume the wake flag:
            // both sides (this release and `signal`'s wake) store-their-
            // announcement-then-check, so at least one observes the other and
            // the flag is consumed by EXACTLY one winner — a signal landing in
            // the release window is never lost (UCA-SMP-12; the Quint model
            // specs/lc_wake_release.qnt checks this protocol; acq_rel is NOT
            // sufficient and TSan is BLIND to that weakness — the model +
            // bounded-join laws are the net). The requeue then rides the same
            // lock-free `enqueueDirect` as every other wake (dedup-swapped, so
            // a concurrent wake-winner's enqueue and this one collapse to one).
            // N9 TSan fix: the requeue decision reads `alive`/`status` — do it
            // BEFORE relinquishing ownership (we are still the unique owner;
            // after the NO_OWNER store a waker may enqueue and a peer may be
            // RUNNING this proc already, making any status read a race).
            // N9: capture the pre-release schedulability WHILE still owner
            // (reading `alive`/`status` is safe only under our claim). A wake
            // applied AT release (won_flag below) also implies a requeue — the
            // flag means the proc wants to run — so requeue on EITHER signal;
            // a straggler that is actually non-runnable is absorbed at the next
            // pick (enqueueDirect no longer pre-checks). run_err gates both.
            const sched_pre = schedulable(ctx.vm, pid.?);
            ctx.vm.owned.items[pid.?].store(NO_OWNER, .seq_cst);
            if (comptime @import("builtin").is_test) std.Thread.yield() catch {}; // widen the Dekker window
            const won_flag = ctx.vm.pending_wake_a.items[pid.?].swap(false, .seq_cst);
            if (won_flag) {
                ctx.vm.applyWake(vp); // sole flag-winner: unique status writer
            }
            const want_requeue = run_err == null and (sched_pre or won_flag);
            if (run_err) |err| {
                _ = ctx.owned_count.fetchSub(1, .seq_cst);
                ctx.latchErr(err); // N2a: lock-free latch
                return;
            }
            if (want_requeue) {
                ctx.vm.enqueueDirect(pid.?) catch |err| {
                    _ = ctx.owned_count.fetchSub(1, .seq_cst);
                    ctx.latchErr(err); // N2a: lock-free latch
                    return;
                };
            }
            // OVERLAP INVARIANT: `owned_count` falls LAST — the requeue's
            // `runnable_total` bump (inside enqueueDirect, BEFORE its append)
            // is already visible, so the owned->queued transition never shows
            // both counters zero to the quiescence read.
            _ = ctx.owned_count.fetchSub(1, .seq_cst);

            // S-shard-grants (DIVERGENCE 612): bump the grant COUNTER LOCK-FREE — the
            // atomic `fetchAdd` replaces the former standalone `L_v` acquire (the pure
            // counter-bump critical section the SMP-OBS measurement flagged as residual
            // `L_v`). No lock is taken, so no `L_c→L_v` back-edge is possible and one
            // full `L_v` acquire per grant is eliminated. Reached only on the success
            // path (`run_err == null` and no requeue-OOM), the same placement as before.
            _ = ctx.grants.fetchAdd(1, .monotonic);
        }
    }

    pub const ThreadRun = struct { grants: usize, elapsed_ns: u64 };

    /// Drive the VM under REAL `std.Thread` workers (one per scheduler up to
    /// `n_sched`). Bounded by `max_grants` AND a `wall_ns` deadline so every
    /// worker returns and `join` never hangs. Returns the grants + wall elapsed
    /// (the bounded-joins law asserts `elapsed_ns < wall_ns`).
    pub fn driveThreads(self: SmpEngine, vm: *Vm, fuel: u64, max_grants: usize, wall_ns: u64) !ThreadRun {
        std.debug.assert(self.n_sched >= 1 and self.n_sched <= MAX_SCHED);
        const start = nowNs();
        var ctx: ThreadCtx = .{
            .engine = self,
            .vm = vm,
            .gpa = vm.gpa,
            .qs = undefined,
            .fuel = fuel,
            .max_grants = max_grants,
            .deadline_ns = start +% wall_ns,
        };
        for (&ctx.qs) |*q| q.* = .empty;
        defer for (&ctx.qs) |*q| q.deinit(vm.gpa);
        for (&ctx.event_shards) |*sh| sh.* = .empty;
        defer for (&ctx.event_shards) |*sh| sh.deinit(vm.gpa);
        // N9-Q1/Q2: go LIVE — publish the scheduler count (wake-side enqueues
        // now target the per-worker home queues directly) and drain the
        // PRE-RUN staging (`ready`: boot/model-time spawns) into the home
        // queues, single-threaded. Reverted to 0 at exit so post-run wakes
        // (tests driving grant/driveModel after a threaded run) stage again.
        vm.n_sched_live.store(self.n_sched, .release);
        defer vm.n_sched_live.store(0, .release);
        {
            for (vm.ready.items) |rpid| {
                try vm.run_qs[homeOf(rpid, self.n_sched)].append(vm.gpa, rpid);
            }
            vm.ready.clearRetainingCapacity();
        }

        var threads: [MAX_SCHED]std.Thread = undefined;
        var spawned: u32 = 0;
        errdefer {
            ctx.done.store(true, .release); // N2a: lock-free latch
            var j: u32 = 0;
            while (j < spawned) : (j += 1) threads[j].join();
        }
        while (spawned < self.n_sched) : (spawned += 1) {
            threads[spawned] = try std.Thread.spawn(.{}, worker, .{ &ctx, spawned });
        }
        var j: u32 = 0;
        while (j < spawned) : (j += 1) threads[j].join();
        // N7: merge the per-worker event shards into the global log (post-join,
        // single-threaded) — seq-sorted, i.e. the linearization the L_events
        // lock used to produce. Runs BEFORE the error check so a failing run
        // still surrenders its events (deliver-count laws stay observable).
        try mergeEventShards(vm, ctx.event_shards[0..self.n_sched]);
        const ec = ctx.err_code.load(.acquire);
        if (ec != 0) return @errorFromInt(@as(std.meta.Int(.unsigned, @bitSizeOf(anyerror)), @intCast(ec)));
        return .{ .grants = ctx.grants.load(.monotonic), .elapsed_ns = nowNs() -% start };
    }
};

// ============================================================================
// Trace observations for the laws
// ============================================================================

/// The sacred law: for every ordered pair, delivery stamps ascend and form a
/// subsequence of send stamps in send order.
fn checkPerPairOrder(events: []const Event) bool {
    var last: [64][64]?u64 = .{.{null} ** 64} ** 64;
    for (events) |e| {
        switch (e) {
            .deliver => |d| {
                if (d.from < 64 and d.to < 64) {
                    if (last[d.from][d.to]) |prev| {
                        if (d.stamp <= prev) return false;
                    }
                    last[d.from][d.to] = d.stamp;
                }
            },
            else => {},
        }
    }
    return true;
}

fn perProcessDeliverSeq(gpa: std.mem.Allocator, events: []const Event, to: Pid) !std.ArrayList(u64) {
    var out: std.ArrayList(u64) = .empty;
    for (events) |e| switch (e) {
        .deliver => |d| {
            if (d.to == to) try out.append(gpa, d.vhash);
        },
        else => {},
    };
    return out;
}

// ============================================================================
// Shared G3 programs
// ============================================================================

/// Token ring: N workers + a collector. Worker k receives an int token,
/// adds its own pid, forwards to the next pid held in x2. The last forwards
/// to the collector, which halts with the token. Entry 0 = worker loop.
///
/// Register conventions: x14 = self pid (set by VM), x15 = spawn arg.
/// Worker: x2 = next pid (sent to it as the FIRST message).
const ring_prog: ia.Program = &.{
    // 0: worker — first receive the next-pid
    .{ .recv_any = .{ .dst = 2, .else_to = 0 } },
    // 1: then receive the token
    .{ .recv_any = .{ .dst = 3, .else_to = 1 } },
    // 2: token += self pid
    .{ .add = .{ .a = .{ .x = 3 }, .b = .{ .x = 14 }, .dst = 3 } },
    // 3: forward to next
    .{ .send_to = .{ .pid = .{ .x = 2 }, .msg = .{ .x = 3 } } },
    // 4: done
    .{ .halt = .{ .src = .{ .x = 3 } } },
    // 5: collector — wait for the final token, halt with it
    .{ .recv_any = .{ .dst = 0, .else_to = 5 } },
    .{ .halt = .{ .src = .{ .x = 0 } } },
};

// ============================================================================
// E6.9 (Task 9): the SCALABILITY WORKLOAD — the throughput subject the harness
// measures at n ∈ {1,2,4} schedulers (OTP30_PARITY_PLAN.md §2.3).
//
// A spawn-storm of INDEPENDENT bounded workers driven under the SMP model. Each
// worker runs the SAME straight-line program (initialize x0, then a fixed run of
// increments, then halt), so the total COMPLETED WORK — the number of grants
// summed over all workers — is a pure function of (`n_workers`, the per-worker
// program length, `fuel`) ALONE. It is INVARIANT of the scheduler count, because
// a confluent independent workload performs the same total work however many
// schedulers share it: only wall-time varies with `n_sched`, never the work.
//
// That `work(n)==work(1)` invariance is the scaling law the harness's throughput
// ratio s(n)=throughput(n)/throughput(1) rides on. The harness measures the
// wall-time of a fixed storm at each n and bands the normalized curve; the Zig
// side supplies the deterministic, conserved WORK the wall-time is divided by.
// ============================================================================

/// Increments per scale worker. Straight-line (no branches), so the worker's
/// reduction cost is exactly its instruction length — a worker takes
/// `ceil(len / fuel)` grants to finish, independent of the schedule.
const scale_work_adds = 48;

/// The scale worker program: `x0 = 0 + 1`, then `scale_work_adds` increments of
/// x0, then `halt x0`. A pure, deterministic, self-terminating unit of work.
const scale_worker_body = blk: {
    var prog: [scale_work_adds + 2]ia.CInstr = undefined;
    prog[0] = .{ .add = .{ .a = .{ .imm = 0 }, .b = .{ .imm = 1 }, .dst = 0 } };
    var k: usize = 1;
    while (k <= scale_work_adds) : (k += 1) {
        prog[k] = .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } };
    }
    prog[scale_work_adds + 1] = .{ .halt = .{ .src = .{ .x = 0 } } };
    break :blk prog;
};
const scale_worker: ia.Program = &scale_worker_body;

/// The completed-work observation of one scaling storm.
pub const ScaleRun = struct {
    /// Grants summed over the whole storm — the throughput NUMERATOR (the
    /// harness divides it by wall-time). Invariant of `n_sched` for a fixed
    /// `n_workers` (the scaling law).
    grants: usize,
    steps: usize,
    /// Every worker reached `.halted` within the step bound (bounded completion).
    completed: bool,
    /// Work-stealing conservation held at every observed step (a pid runnable on
    /// ≤ 1 scheduler).
    conserved: bool,
};

/// Drive a spawn-storm of `n_workers` independent `scale_worker` processes under
/// the SMP model at `n_sched` schedulers, bounded by `max_steps`. The seed is
/// FIXED (independent of `n_sched`) so the schedule is the only thing the
/// scheduler count changes — the completed-work count `grants` stays invariant,
/// which is exactly the scaling law the harness's throughput ratio needs. A
/// non-completing storm is a FAILED law (`completed=false`), never a hang.
pub fn scaleWork(
    gpa: std.mem.Allocator,
    atoms: *AtomTable,
    n_sched: u32,
    n_workers: u32,
    max_steps: usize,
) !ScaleRun {
    std.debug.assert(n_sched >= 1 and n_sched <= SmpEngine.MAX_SCHED);
    var vm = try Vm.init(gpa, atoms);
    defer vm.deinit();
    var k: u32 = 0;
    while (k < n_workers) : (k += 1) _ = try vm.spawn(scale_worker, 0, null);
    const eng = SmpEngine{ .n_sched = n_sched, .seed = 0x5CA1E5EED };
    const run = try eng.driveModel(&vm, 7, max_steps);
    var completed = true;
    for (vm.procs.items) |p| {
        if (p.machine.status != .halted) completed = false;
    }
    return .{
        .grants = run.grants,
        .steps = run.steps,
        .completed = completed,
        .conserved = run.conserved,
    };
}

/// e48-smp-s5: the REAL-thread scaling workload. Each worker runs a LOOPED
/// CPU-bound body (`real_scale_loops` iterations of `scale_work_adds` adds —
/// ~a quarter-million reductions) so the UNLOCKED machine run dominates the
/// locked prologue/epilogue phases; `driveThreads` (the S3/S4 concurrent
/// engine) executes the storm. Completed work is invariant of `n_sched`;
/// what varies is WALL TIME — the caller divides grants by seconds. Honest by
/// construction: the number reports whatever the engine actually does — no
/// model, no fabricated speedup.
pub const real_scale_loops: i64 = 4000;

const real_scale_worker: ia.Program = &.{
    // x1 = loop counter (counts up to real_scale_loops); x0 = accumulator
    .{ .move = .{ .src = .{ .imm = 0 }, .dst = 1 } }, // 0
    .{ .add = .{ .a = .{ .imm = 0 }, .b = .{ .imm = 1 }, .dst = 0 } }, // 1: (re)seed x0 each iteration
    .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } },
    .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } },
    .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } },
    .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } },
    .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } },
    .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } },
    .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } }, // 8 adds
    .{ .add = .{ .a = .{ .x = 1 }, .b = .{ .imm = 1 }, .dst = 1 } }, // 9: counter += 1
    .{ .is_lt = .{ .a = .{ .x = 1 }, .b = .{ .imm = real_scale_loops }, .else_to = 12 } }, // 10: fall through while counter < N
    .{ .jump = .{ .to = 1 } }, // 11: loop
    .{ .halt = .{ .src = .{ .x = 0 } } }, // 12
};

pub fn scaleWorkReal(
    gpa: std.mem.Allocator,
    atoms: *AtomTable,
    n_sched: u32,
    n_workers: u32,
) !ScaleRun {
    std.debug.assert(n_sched >= 1 and n_sched <= SmpEngine.MAX_SCHED);
    var vm = try Vm.init(gpa, atoms);
    defer vm.deinit();
    var k: u32 = 0;
    while (k < n_workers) : (k += 1) _ = try vm.spawn(real_scale_worker, 0, null);
    const eng = SmpEngine{ .n_sched = n_sched, .seed = 0x5CA1E4EA1 };
    // fuel spans a worker's WHOLE looped body: ~one grant per worker = the
    // unlocked run is the measurement.
    const per_worker_reds: u64 = @intCast(real_scale_loops * 16 + 64);
    const run = try eng.driveThreads(&vm, per_worker_reds, @as(usize, n_workers) * 8 + 64, 120 * std.time.ns_per_s);
    var completed = true;
    for (vm.procs.items) |p| {
        if (p.machine.status != .halted) completed = false;
    }
    return .{
        .grants = run.grants,
        .steps = run.grants,
        .completed = completed,
        .conserved = true,
    };
}

test "E6.9 SCALE: completed-work is conserved across scheduler count (throughput invariance)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // work(n=1) == work(n=2) == work(n=4): a spawn-storm of independent workers
    // does the SAME total work however many schedulers share it — the invariance
    // the harness's throughput ratio s(n) rides on (only wall-time varies with
    // the scheduler count, never the work done). This is the honest reason the
    // zigvm scaling curve is flat under the single-threaded model: the work is
    // conserved, so a wall-time ratio near 1 is the TRUTH, not a measurement bug.
    const n_workers: u32 = 24;
    const g1 = try scaleWork(gpa, &atoms, 1, n_workers, 20_000);
    const g2 = try scaleWork(gpa, &atoms, 2, n_workers, 20_000);
    const g4 = try scaleWork(gpa, &atoms, 4, n_workers, 20_000);

    try std.testing.expect(g1.completed and g2.completed and g4.completed);
    try std.testing.expect(g1.conserved and g2.conserved and g4.conserved);
    try std.testing.expect(g1.grants > 0);
    // The conservation law: the scheduler count NEVER changes the total work.
    try std.testing.expectEqual(g1.grants, g2.grants);
    try std.testing.expectEqual(g2.grants, g4.grants);
    // Capacity: the storm actually spawned every worker (the throughput sample
    // reflects the whole workload, not a truncated one).
    try std.testing.expect(g1.grants >= n_workers); // each worker took ≥1 grant
}

/// Ring-fixture capacity. It was 8, which silently bounded every soak to a
/// runnable set no larger than `SmpEngine.MAX_SCHED` — so the regime where
/// processes far OUTNUMBER schedulers, the one that actually contends the
/// per-worker run queues, could not be expressed by the fixture at all.
const MAX_RING = 64;

const RingResult = struct { total: i64, events: std.ArrayList(Event) };

fn runRing(gpa: std.mem.Allocator, atoms: *AtomTable, sched: Scheduler, n_workers: u32) !RingResult {
    var vm = try Vm.init(gpa, atoms);
    defer vm.deinit();

    const collector = try vm.spawn(ring_prog, 5, null);
    var workers: [MAX_RING]Pid = undefined;
    for (0..n_workers) |k| workers[k] = try vm.spawn(ring_prog, 0, null);

    // wire the ring: worker k's next = worker k+1; last → collector.
    // "next pid" arrives as the first message (per-pair FIFO guarantees it
    // precedes any token from the same sender — here sender is the driver
    // process 0? We have no driver: use the collector to seed instead.)
    // Simpler: the VM test injects the wiring messages directly.
    for (0..n_workers) |k| {
        const target = vm.procs.items[workers[k]];
        const next: Pid = if (k + 1 < n_workers) workers[k + 1] else collector;
        const w = FinalTerms.int(&target.machine.ctx, next);
        try vm.signal(collector, workers[k], .{ .message = w });
    }
    // seed the token 100 into worker 0
    {
        const target = vm.procs.items[workers[0]];
        const w = FinalTerms.int(&target.machine.ctx, 100);
        try vm.signal(collector, workers[0], .{ .message = w });
    }

    try sched.drive(&vm, 7, 4000);

    const cm = &vm.procs.items[collector].machine;
    std.debug.assert(cm.status == .halted);
    // extract the small-int result directly
    const total = @as(i64, @bitCast(cm.result)) >> 4;

    var events: std.ArrayList(Event) = .empty;
    try events.appendSlice(gpa, vm.events.items);
    return .{ .total = total, .events = events };
}

