test "SACRED: per-pair signal order over random multi-process workloads" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const cfg = LawConfig{ .seed = 0x51D0, .iterations = 25 };

    for (0..cfg.iterations) |i| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        var prng = std.Random.DefaultPrng.init(cfg.seed +% i);
        const random = prng.random();

        // random programs sprayed across 4 processes; send_to targets are
        // register values (ints — i.e. pids 0..15 or garbage: dropped)
        var bufs: [4][16]ia.CInstr = undefined;
        for (0..4) |k| {
            const prog = ia.randProgram(random, &bufs[k]);
            _ = try vm.spawn(prog, 0, @intCast(k));
        }
        // seed registers with small ints so pids get hit
        for (vm.procs.items) |p| {
            for (&p.machine.regs) |*r| r.* = FinalTerms.int(&p.machine.ctx, random.uintLessThan(u8, 6));
        }
        const sched = Scheduler{ .seeded = cfg.seed +% i };
        try sched.drive(&vm, 5, 300);

        try expectLaw(checkPerPairOrder(vm.events.items), "signals: per-pair delivery order (the sacred law)", cfg, i);
    }
}

// ── E7.3 (DIVERGENCE 143): shared, Vm-owned ETS — cross-process visibility +
// the owner-death exit hook ──────────────────────────────────────────────────
const halt_prog: ia.Program = &.{.{ .halt = .{ .src = .{ .x = 0 } } }};

fn listLenPr(m: *ia.Machine, l: FinalTerms.Term) usize {
    var n: usize = 0;
    var cur = l;
    while (FinalTerms.kindOf(&m.ctx, cur) == .cons) : (cur = FinalTerms.listTail(&m.ctx, cur)) n += 1;
    return n;
}

test "LAW E7.3 shared ETS: process A inserts, process B looks up the SAME table; owner-death exit hook auto-deletes (mutants m1/m2)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // Two processes sharing the Vm's ONE ETS table space (spawn sets shared_ets).
    const pa = try vm.spawn(halt_prog, 0, null);
    const pb = try vm.spawn(halt_prog, 0, null);
    const ma = &vm.procs.items[pa].machine;
    const mb = &vm.procs.items[pb].machine;

    // A creates a NAMED public table `sh` and inserts {k, 42}. (A named table is
    // resolvable by its global atom from any process — the cross-process handle.)
    const sh_a = FinalTerms.atom(&ma.ctx, try atoms.intern("sh"));
    const named = FinalTerms.atom(&ma.ctx, try atoms.intern("named_table"));
    const opts = try FinalTerms.cons(&ma.ctx, named, FinalTerms.nil(&ma.ctx));
    _ = try ets_bifs.new_2(ma, &.{ sh_a, opts });
    const k_a = FinalTerms.atom(&ma.ctx, try atoms.intern("k"));
    const obj = try FinalTerms.tuple(&ma.ctx, &.{ k_a, FinalTerms.int(&ma.ctx, 42) });
    _ = try ets_bifs.insert_2(ma, &.{ sh_a, obj });

    // CROSS-PROCESS VISIBILITY (the entry-124 observation, now real): B resolves
    // `sh` in the SHARED registry and looks up k -> [{k,42}], the object COPIED
    // into B's own heap (the M1 copy law at the table boundary). MUTANT 2:
    // `etsReg()` ignoring `shared_ets` (returning &self.ets) leaves B's table
    // space empty -> resolveTable badargs -> this expectEqual reddens.
    const sh_b = FinalTerms.atom(&mb.ctx, try atoms.intern("sh"));
    const k_b = FinalTerms.atom(&mb.ctx, try atoms.intern("k"));
    const got = try ets_bifs.lookup_2(mb, &.{ sh_b, k_b });
    try std.testing.expectEqual(@as(usize, 1), listLenPr(mb, got));
    const head = FinalTerms.listHead(&mb.ctx, got);
    try std.testing.expectEqual(@as(i64, 42), FinalTerms.smallValOf(FinalTerms.tupleElem(&mb.ctx, head, 1)));

    // ISOLATION: B's OWN distinct table is independent — A never sees B's rows.
    const bt = FinalTerms.atom(&mb.ctx, try atoms.intern("bt"));
    const bnamed = FinalTerms.atom(&mb.ctx, try atoms.intern("named_table"));
    const bopts = try FinalTerms.cons(&mb.ctx, bnamed, FinalTerms.nil(&mb.ctx));
    _ = try ets_bifs.new_2(mb, &.{ bt, bopts });
    _ = try ets_bifs.insert_2(mb, &.{ bt, try FinalTerms.tuple(&mb.ctx, &.{ k_b, FinalTerms.int(&mb.ctx, 7) }) });
    // A looking up k in `sh` still sees ONLY {k,42}, not B's {k,7}.
    const got_a = try ets_bifs.lookup_2(ma, &.{ sh_a, k_a });
    try std.testing.expectEqual(@as(i64, 42), FinalTerms.smallValOf(FinalTerms.tupleElem(&ma.ctx, FinalTerms.listHead(&ma.ctx, got_a), 1)));

    // OWNER-DEATH via the REAL exit path: `sh` is owned by A, heir-less. Killing
    // A must auto-delete it from the SHARED set (E6.7 lifecycle, now wired into
    // terminate). MUTANT 1: the exit hook scanning A's per-Machine set (m.ets)
    // instead of the shared Vm registry leaves `sh` alive -> this reddens.
    try vm.terminate(pa, FinalTerms.atom(&ma.ctx, vm.a_normal));
    try std.testing.expect(vm.ets.byName(try atoms.intern("sh")) == null);
    // B can no longer resolve the dead table.
    try std.testing.expectError(error.Badarg, ets_bifs.lookup_2(mb, &.{ sh_b, k_b }));
    // B's own table survives A's death (owner check — a foreign owner untouched).
    try std.testing.expect(vm.ets.byName(try atoms.intern("bt")) != null);
}

// ============================================================================
// E24-T2 (proc scheduler hardening — coverage-driven, hotspot #2). Before this
// slice `doEtsGiveAway` was DARK: zero test coverage on the multi-process ETS
// OWNERSHIP-TRANSFER surface of the scheduler. The law below exercises the
// success path AND all badarg guards, each correlated to the pinned OTP-30
// source, so a regression in any branch reddens.
//
// SEMANTIC DOMAIN. `ets:give_away(Tab, To, Gift)` is a PARTIAL function on the
// (table-registry × process-table) state:
//   • DEFINED (→ `true`) iff the CALLER owns `Tab` AND `To` is a DISTINCT,
//     currently-ALIVE local process. Effect: `Tab.owner := To`, and the message
//     `{'ETS-TRANSFER', Tab, FromPid, Gift}` is delivered to `To`, built in
//     `To`'s OWN heap (the cross-process copy law at the ownership boundary).
//   • UNDEFINED (→ `badarg`) otherwise: not-owner, give-to-self, or a dead/
//     absent target. The VM returns the `badarg` ATOM via `badargAtom`; real
//     BEAM raises it — the SAME observable at the BIF boundary (true | badarg).
//
// OTP-30 CORRELATION — `third_party/otp/erts/emulator/beam/erl_db.c`
// `ets_give_away_3` (lines 3087–3143). OTP's guards, in order: resolve `to_proc`
// (`erts_pid2proc`); resolve the table (`db_get_table` — a table error is
// reported even when the pid is also bad); then `!to_proc` → BADARG;
// `owner != caller` → BADARG (fvalue `EXI_NOT_OWNER`); `to == from` → BADARG
// (fvalue `EXI_OWNER`); success reassigns `tb->common.owner = to_pid` and calls
// `send_ets_transfer_message(...)`. The VM's `doEtsGiveAway` checks
// table-resolve → owner → target-is-pid → not-self → target-alive, ALSO all →
// `badarg`. Because EVERY failure mode collapses to `badarg` in BOTH, the guard
// ORDERING differences are UNOBSERVABLE: the two are observationally EQ on the
// full observable set (true | badarg | resulting ownership | ETS-TRANSFER
// message). The success message tuple is byte-identical to OTP's.
//
// EVOLUTION NOTES (for the next agent/human extending proc's ETS surface):
//   • OTP attaches EXTENDED error info (`fvalue` `EXI_NOT_OWNER` / `EXI_OWNER`)
//     to the badarg; this VM raises PLAIN badarg (error-info extension not
//     modeled) — a documented divergence, invisible unless a caller inspects
//     `error_info`. Model it here if/when the error-info surface is built.
//   • The HEIR path (owner-death auto-transfer to a registered heir —
//     `erl_db.c` `give_away_to_heir` @4865) is a SEPARATE, still-dark surface: a
//     natural next slice (spawn owner with a `{heir,Pid,Data}` option, kill it,
//     assert the heir receives `{'ETS-TRANSFER',Tab,From,HeirData}` and owns it).
//   • This law calls `doEtsGiveAway` DIRECTLY (the operation under law). The full
//     BIF path (`ets.give_away_3` → `m.pending = .ets_give_away` → the pending
//     bridge @proc.zig:1285 → `doEtsGiveAway`) is the integration route; add a
//     law here if that bridge itself needs pinning.
//   • The DEAD-target guard here uses an absent pid (9999), caught by the
//     `self.proc(target) orelse` lookup — NOT the distinct `!tp.alive` branch
//     (a spawned-then-terminated process still present in the table). Covering
//     `!tp.alive` distinctly (spawn C, terminate C, give to C) is a tiny
//     follow-on that would tighten this law.
//   • Mutants MUTATION_LOG e24-t2 m1 (drop the not-self guard) / m2 (drop the
//     owner guard) pin the two guards a naive refactor is most likely to lose.
// ============================================================================
test "LAW E24-T2 ets:give_away/3 ownership TRANSFER + ETS-TRANSFER delivery + badarg guards (OTP-30 erl_db.c ets_give_away_3)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // Two live processes sharing the Vm's ETS space: A = owner, B = recipient.
    const pa = try vm.spawn(halt_prog, 0, null);
    const pb = try vm.spawn(halt_prog, 0, null);
    const ma = &vm.procs.items[pa].machine;
    const mb = &vm.procs.items[pb].machine;

    // A creates a NAMED table `tab` (owner = A = pa); named ⇒ resolvable by any
    // process via the shared registry (the cross-process handle).
    const tab = FinalTerms.atom(&ma.ctx, try atoms.intern("tab"));
    const named = FinalTerms.atom(&ma.ctx, try atoms.intern("named_table"));
    const opts = try FinalTerms.cons(&ma.ctx, named, FinalTerms.nil(&ma.ctx));
    _ = try ets_bifs.new_2(ma, &.{ tab, opts });
    const tab_id = try atoms.intern("tab");

    // pid TERMs in A's heap: B (target), A (self), and a never-spawned pid.
    const to_b = try FinalTerms.pid(&ma.ctx, pb, 0);
    const to_self = try FinalTerms.pid(&ma.ctx, pa, 0);
    const to_dead = try FinalTerms.pid(&ma.ctx, 9999, 0);
    const gift = FinalTerms.int(&ma.ctx, 7);
    const badarg_a = FinalTerms.atom(&ma.ctx, try atoms.intern("badarg"));
    const true_a = FinalTerms.atom(&ma.ctx, ma.bool_true);

    // GUARD — give to SELF → badarg (OTP: `to_pid == from_pid`, EXI_OWNER).
    try std.testing.expect(FinalTerms.eqlExact(&ma.ctx, try vm.doEtsGiveAway(pa, ma, tab, to_self, gift), badarg_a));
    // GUARD — give to a DEAD/absent target → badarg (OTP: `!to_proc`).
    try std.testing.expect(FinalTerms.eqlExact(&ma.ctx, try vm.doEtsGiveAway(pa, ma, tab, to_dead, gift), badarg_a));
    // GUARD — a NON-OWNER (B) giving A's table → badarg (OTP: `owner != caller`).
    const tab_b = FinalTerms.atom(&mb.ctx, tab_id);
    const to_a_fromb = try FinalTerms.pid(&mb.ctx, pa, 0);
    try std.testing.expect(FinalTerms.eqlExact(&mb.ctx, try vm.doEtsGiveAway(pb, mb, tab_b, to_a_fromb, FinalTerms.int(&mb.ctx, 1)), FinalTerms.atom(&mb.ctx, try atoms.intern("badarg"))));
    // Every failed guard is INERT: ownership is still A.
    try std.testing.expectEqual(@as(u64, pa), vm.ets.byName(tab_id).?.owner);

    // SUCCESS — A gives `tab` to B with gift 7: → `true`; owner becomes B; and B
    // receives exactly one `{'ETS-TRANSFER', tab, A, 7}` message.
    const res = try vm.doEtsGiveAway(pa, ma, tab, to_b, gift);
    try std.testing.expect(FinalTerms.eqlExact(&ma.ctx, res, true_a));
    try std.testing.expectEqual(@as(u64, pb), vm.ets.byName(tab_id).?.owner);
    try vm.drainSignalsPub(pb);
    try std.testing.expectEqual(@as(usize, 1), mb.mbox.len()); // the ETS-TRANSFER message landed
}

// ============================================================================
// E24-T3 (proc scheduler hardening — the ETS owner-death HEIR path). A BUG this
// slice FOUND AND FIXED. The heir owner-death lifecycle was DARK; the E24 probe
// showed that on owner death the VM transferred a table to its live heir but
// SILENTLY DROPPED the `{'ETS-TRANSFER', Tab, DeadOwner, HeirData}` message
// OTP-30 delivers, and never checked that the heir was ALIVE (it would orphan a
// table onto a dead heir instead of deleting it). Root cause: the owner-death
// hook was `EtsRegistry.ownerDied`, which sees only tables — not the process
// table or the signal path — so it structurally COULD NOT deliver a message or
// test liveness. Fixed by moving the lifecycle up to `Vm.etsOwnerDied` (see its
// doc); this LAW pins both halves.
//
// SEMANTIC DOMAIN. On the death of a table's owner, the table's fate is:
//   • heir set ∧ heir ≠ owner ∧ heir ALIVE ⇒ owner := heir, and heir receives
//     `{'ETS-TRANSFER', Tab, DeadOwner, HeirData}` (built in the heir's heap);
//   • otherwise ⇒ the table is DELETED.
//
// OTP-30 CORRELATION — `erl_db.c` `give_away_to_heir` (@4865) + its owner-death
// caller (@5079): `if (heir != none && heir != pid && give_away_to_heir(...))`
// transfers + `send_ets_transfer_message`; else the table is deleted.
// `give_away_to_heir` returns 0 (⇒ delete) when the heir is not alive / pid
// reused — exactly the two branches below.
//
// EVOLUTION NOTES: heir_data is stored as a raw Term offset into the SETTER's
// heap (`bifs/ets.zig` new_2/setopts); this law + fix assume it is the OWNER's
// heap (valid at owner death). If `setopts/2` ever lets a NON-owner set the
// heir_data, that term could dangle — copy it into the registry `region` at
// set-time then. The pid-reuse guard (OTP's `started_interval` check) is not
// modeled (this VM does not reuse pids within a run). Mutants MUTATION_LOG
// e24-t3 m1 (drop the ETS-TRANSFER delivery) / m2 (drop the heir-liveness check).
// ============================================================================
test "LAW E24-T3 ETS owner-death HEIR: live heir gains ownership AND gets {'ETS-TRANSFER',...}; a dead heir ⇒ table deleted (OTP-30 give_away_to_heir)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // A owns `htab` with heir = B (alive) and heir_data = 99.
    const pa = try vm.spawn(halt_prog, 0, null);
    const pb = try vm.spawn(halt_prog, 0, null);
    const ma = &vm.procs.items[pa].machine;
    const mb = &vm.procs.items[pb].machine;
    const htab = FinalTerms.atom(&ma.ctx, try atoms.intern("htab"));
    const named = FinalTerms.atom(&ma.ctx, try atoms.intern("named_table"));
    const heir_opt = try FinalTerms.tuple(&ma.ctx, &.{
        FinalTerms.atom(&ma.ctx, try atoms.intern("heir")),
        try FinalTerms.pid(&ma.ctx, pb, 0),
        FinalTerms.int(&ma.ctx, 99),
    });
    const opts = try FinalTerms.cons(&ma.ctx, named, try FinalTerms.cons(&ma.ctx, heir_opt, FinalTerms.nil(&ma.ctx)));
    _ = try ets_bifs.new_2(ma, &.{ htab, opts });

    // A dies → B OWNS htab AND receives exactly one {'ETS-TRANSFER', htab, A, 99}.
    try vm.terminate(pa, FinalTerms.atom(&ma.ctx, vm.a_normal));
    try std.testing.expectEqual(@as(u64, pb), vm.ets.byName(try atoms.intern("htab")).?.owner);
    try vm.drainSignalsPub(pb);
    try std.testing.expectEqual(@as(usize, 1), mb.mbox.len()); // the ETS-TRANSFER (the FIXED bug)

    // DEAD-HEIR branch: C owns `dtab` with heir = D, but D dies FIRST. On C's
    // death the heir is not alive → the table must be DELETED (never orphaned
    // onto the dead heir).
    const pc = try vm.spawn(halt_prog, 0, null);
    const pd = try vm.spawn(halt_prog, 0, null);
    const mc = &vm.procs.items[pc].machine;
    const dtab = FinalTerms.atom(&mc.ctx, try atoms.intern("dtab"));
    const dnamed = FinalTerms.atom(&mc.ctx, try atoms.intern("named_table"));
    const dheir = try FinalTerms.tuple(&mc.ctx, &.{
        FinalTerms.atom(&mc.ctx, try atoms.intern("heir")),
        try FinalTerms.pid(&mc.ctx, pd, 0),
        FinalTerms.int(&mc.ctx, 1),
    });
    const dopts = try FinalTerms.cons(&mc.ctx, dnamed, try FinalTerms.cons(&mc.ctx, dheir, FinalTerms.nil(&mc.ctx)));
    _ = try ets_bifs.new_2(mc, &.{ dtab, dopts });
    try vm.terminate(pd, FinalTerms.atom(&mc.ctx, vm.a_normal)); // heir D dies first
    try vm.terminate(pc, FinalTerms.atom(&mc.ctx, vm.a_normal)); // then owner C
    try std.testing.expect(vm.ets.byName(try atoms.intern("dtab")) == null); // DELETED, not orphaned
}

// ============================================================================
// E6.1 (Task 1): the SMP scheduler ENGINE laws. The sequential `round_robin` is
// the ORACLE; `SmpEngine` is admitted ONLY by trace/differential equivalence
// (SC-20.1). The SACRED M7 per-pair law is re-proven under seeded multi-thread
// stress; scheduler-count invariance pins denote()==denote(); conservation pins
// the work-stealing bookkeeping; bounded joins pin the real-thread engine.
// ============================================================================

/// Build the single-sender token ring (collector = pid 0, workers = pids 1..5)
/// used by the SMP laws — the same topology `runRing` drives, so the sequential
/// oracle's total (100 + Σpid) is the homomorphism target.
fn seedRing(vm: *Vm, comptime n_workers: u32) !Pid {
    const collector = try vm.spawn(ring_prog, 5, null);
    var workers: [MAX_RING]Pid = undefined;
    inline for (0..n_workers) |k| workers[k] = try vm.spawn(ring_prog, 0, null);
    inline for (0..n_workers) |k| {
        const target = vm.procs.items[workers[k]];
        const next: Pid = if (k + 1 < n_workers) workers[k + 1] else collector;
        try vm.signal(collector, workers[k], .{ .message = FinalTerms.int(&target.machine.ctx, next) });
    }
    const first = vm.procs.items[workers[0]];
    try vm.signal(collector, workers[0], .{ .message = FinalTerms.int(&first.machine.ctx, 100) });
    return collector;
}

test "E6.1 SMP: scheduler-count invariance homomorphism + work-stealing conservation + bounded completion" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const cfg = LawConfig{ .seed = 0x5117 };

    // ORACLE: the sequential round-robin total (a single-sender ring is
    // confluent, so its result is schedule-independent — the homomorphism
    // target denote() must equal for ANY scheduler count).
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total; // 100 + 1+2+3+4+5

    for ([_]u32{ 1, 2, 3, 4 }) |n| {
        for (0..6) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 5);
            const eng = SmpEngine{ .n_sched = n, .seed = cfg.seed +% i };
            const run = try eng.driveModel(&vm, 7, 5000);

            try expectLaw(run.conserved, "smp: work-stealing conservation (a pid is runnable on ≤1 scheduler)", cfg, i);
            const cm = &vm.procs.items[collector].machine;
            try expectLaw(cm.status == .halted, "smp: bounded completion (the ring finishes under N schedulers)", cfg, i);
            const total = @as(i64, @bitCast(cm.result)) >> 4;
            try expectLaw(total == oracle, "smp: scheduler-count invariance homomorphism denote(P,1)==denote(P,N)", cfg, n);
            try expectLaw(checkPerPairOrder(vm.events.items), "smp: SACRED per-pair order under the SMP model", cfg, i);
        }
    }
}

test "E6.1 SMP: the SACRED per-pair signal order survives seeded multi-scheduler STRESS" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const cfg = LawConfig{ .seed = 0x5AC5ED, .iterations = 18 };

    // random programs sprayed across 4 processes, driven under 2/3/4 schedulers:
    // the sacred law must hold under EVERY seeded SMP schedule (per-pair delivery
    // order is a representation invariant of the single stamping authority).
    for (0..cfg.iterations) |i| {
        for ([_]u32{ 2, 3, 4 }) |n| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            var prng = std.Random.DefaultPrng.init(cfg.seed +% i);
            const random = prng.random();
            var bufs: [4][16]ia.CInstr = undefined;
            for (0..4) |k| {
                const prog = ia.randProgram(random, &bufs[k]);
                _ = try vm.spawn(prog, 0, @intCast(k));
            }
            for (vm.procs.items) |p| {
                for (&p.machine.regs) |*r| r.* = FinalTerms.int(&p.machine.ctx, random.uintLessThan(u8, 6));
            }
