}

test "E6.1 SMP: linearizability spot-law — a monitor's 'DOWN' fires exactly once under the SMP model" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const crasher: ia.Program = &.{
        .{ .exit_proc = .{ .reason = .{ .imm = 777 } } },
    };

    for ([_]u32{ 2, 3 }) |n| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const w = try vm.spawn(idle, 0, null); // watcher: loops forever (never halts)
        const t = try vm.spawn(crasher, 0, null); // target: crashes immediately
        const pw = vm.procs.items[w];
        pw.machine.pending = .{ .monitor_to = .{ .pid = FinalTerms.int(&pw.machine.ctx, t), .dst = 5 } };
        try vm.interpret(w); // install the monitor (watcher observes target)

        const eng = SmpEngine{ .n_sched = n, .seed = 0xD00D +% n };
        // the watcher never halts, so the run is bounded by max_steps (a hang is
        // a failed law) — quiescence is NOT reached, but the DOWN must fire once.
        _ = try eng.driveModel(&vm, 6, 200);

        var downs: usize = 0;
        for (vm.events.items) |e| switch (e) {
            .down_delivered => |d| {
                if (d.to == w) downs += 1;
            },
            else => {},
        };
        try std.testing.expectEqual(@as(usize, 1), downs); // exactly-once, SMP-invariant
    }
}

test "E6.1 SMP: real std.Thread workers — bounded joins + differential equivalence to the ORACLE" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;

    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const collector = try seedRing(&vm, 5);

    const eng = SmpEngine{ .n_sched = 3, .seed = 0xBEEF };
    const wall: u64 = 5 * std.time.ns_per_s;
    const run = try eng.driveThreads(&vm, 7, 100_000, wall);

    // bounded joins: the whole real-thread run returned well within the wall
    // bound (a deadlock would blow it — a FAILED law, never a hung suite).
    try std.testing.expect(run.elapsed_ns < wall);
    // differential: the SMP thread engine produces the ORACLE's denote() exactly.
    const cm = &vm.procs.items[collector].machine;
    try std.testing.expectEqual(ia.Status.halted, cm.status);
    try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4);
    // and the SACRED law holds over the real-thread trace.
    try std.testing.expect(checkPerPairOrder(vm.events.items));
}

// LAW E28-T1 — the real-thread engine is DENOTATION-NEUTRAL across n_sched
// (DIVERGENCE 540 SUCCESSOR — e48-smp-s3). The engine is NO LONGER the
// lock-serialized sampler E28-T1 originally pinned: since e48-smp-s3 the
// MACHINE RUN executes OUTSIDE the VM lock (three-phase worker: locked
// prologue = ownership + grant event + drain; UNLOCKED ia.run on the proc's
// own heap — the atom table is lock-free, ETS self-locks, S2 fragments keep
// senders out; locked epilogue = trap interpretation/exits/deferred wake/
// release). What the law asserts is therefore the OBSERVATION QUOTIENT over
// real concurrency: for the same workload, ANY thread count computes the
// SAME denotation and completes within the same deterministic WORK budget —
// threads change the interleaving, never the result (per-pair order + mailbox
// FIFO stay the machine-checked invariants: proofs/Scheduler_Signal.v +
// Sampler_Fairness.v; E6.1 asserts them over the live trace).
//
// DIVERGENCE 540 history: originally CLOSED as a category mismatch (the old
// engine was a serialized verification sampler, so no CPU-throughput curve
// existed BY DESIGN). e48-smp-s3 changes the category: real parallel
// execution now EXISTS; the throughput curve becomes measurable at S5 (the
// scale-band slice) — until S5 lands, zigvm still claims only FUNCTIONAL SMP
// equivalence, now over genuinely concurrent runs.
//
// Mutants MUTATION_LOG e28-t1 m1/m2 (historical) + e48-smp-s3 (ownership/
// wake/quiescence — see its entry).
test "LAW E28-T1 driveThreads is THROUGHPUT-NEUTRAL: n=1 and n=4 compute the IDENTICAL denotation (DIVERGENCE 540 byte-clean)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // The oracle total (schedule-independent) — the denotation both runs must equal.
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;

    // e47-e28t1-load-harden (CAST-19): the wall deadline is ONLY the anti-hang
    // backstop, never a law observation. The old law asserted `elapsed_ns <
    // wall` with wall=5s — a REAL-TIME coupling that flaked once when the host
    // was saturated by a concurrent perf run (run 993): the deadline fired
    // before the (tiny) ring finished, so an incomplete run failed the halted
    // check. Constructive determinism: the law now observes WORK (grants under
    // the deterministic max_grants budget) and RESULT (halted + denotation)
    // only; wall=60s bounds a genuinely-hung engine by 4 orders of margin
    // above any plausible load-slowdown of this ~ms workload.
    const wall: u64 = 60 * std.time.ns_per_s;
    const max_grants: usize = 100_000;
    var results: [2]i64 = undefined;
    const sched_counts = [_]u32{ 1, 4 };
    for (sched_counts, 0..) |n, i| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const collector = try seedRing(&vm, 5);
        const eng = SmpEngine{ .n_sched = n, .seed = 0xC0FFEE +% n };
        const run = try eng.driveThreads(&vm, 7, max_grants, wall);
        try std.testing.expect(run.grants < max_grants); // completed WITHIN the work budget (deterministic, load-independent)
        const cm = &vm.procs.items[collector].machine;
        try std.testing.expectEqual(ia.Status.halted, cm.status); // completed
        results[i] = @as(i64, @bitCast(cm.result)) >> 4;
    }
    // THROUGHPUT-NEUTRAL: n=1 and n=4 compute the SAME denotation, which is the
    // oracle — n_sched changes only the interleaving, never the work/result.
    try std.testing.expectEqual(oracle, results[0]);
    try std.testing.expectEqual(results[0], results[1]);
}

test "LAW s-shard-grants: the driveThreads ATOMIC grant counter ADVANCES correctly — a saturating workload retires grants>0, ≥1 per worker, and stays work-bounded (<max_grants); the guard the SMP-OBS shard (DIVERGENCE 612) needs so a lost/mis-count is caught (the model `scaleWork` never exercised ctx.grants)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // driveThreads (the REAL engine — ctx.grants is the atomic counter under test),
    // for several scheduler counts. Each of the W workers must retire ≥1 grant to
    // reach `.halted`, and the run must stay within its work budget (bounded).
    const W: u32 = 12;
    for ([_]u32{ 1, 2, 4 }) |n| {
        const r = try scaleWorkReal(gpa, &atoms, n, W);
        try std.testing.expect(r.grants > 0); // ADVANCES — kills the drop-increment mutant (fetchAdd(0))
        try std.testing.expect(r.grants >= W); // ≥1 grant per worker (all ran to halt)
        // work-bounded: scaleWorkReal's own max_grants (W*8+64) is the ceiling; a
        // DOUBLE-count (fetchAdd(2)) blows past the real grant count → this trips.
        try std.testing.expect(r.grants < @as(usize, W) * 8 + 64);
    }
}

// LAW e51-t1 — the REAL-THREAD engine is the OBSERVATION-QUOTIENT of the
// sequential oracle at GRADED SCALE (gap-smp-wire-realsched, E51-T1 first
// increment). This is the EQ-ADMISSION GATE that justifies routing the graded
// scalability pillar through `driveThreads` (the real std.Thread engine)
// instead of the deterministic `driveModel` sampler — closing DIVERGENCE 540's
// "category mismatch" in the *graded* verdict without touching the coarse lock.
//
// Where E28-T1 checks driveThreads only at n∈{1,4} for a single seed, this law
// is the STRONG cross-engine differential the design (E51-T1 §5) specifies: for
// a MESSAGING workload (the single-sender ring — sends + receives, so the two
// SMP hazards actually bite) the real concurrent engine computes the IDENTICAL
// denotation as the sequential round-robin oracle over N seeds × n∈{1,2,4},
// with the SACRED per-pair order preserved under real thread interleaving.
//
// The workload is deliberately RECEIVE-BEARING so both E51-T1 mutants red it —
// each is a load-bearing invariant of the real concurrent engine, killed
// DETERMINISTICALLY (never a timing flake): (m1) drop the ownership mark
// `vp.owned_by = id` (proc.zig ~4378) → two workers race one machine heap →
// nondeterministic total across seeds; (m2) skip the locked-prologue fragment
// drain `drainSignals(pid)` (proc.zig ~4388) → inbound ring messages (S2
// fragment heaps) never merge into the receiver → the ring stalls → the
// collector never halts → total ≠ oracle. (MUTATION_LOG e51-t1 m1/m2; controls
// CTRL-SMP-EXECUTION / UCA-SMP-1,2.) NOTE: the epilogue deferred-wake
// (`applyWake`) is guarded by the SAME lock discipline but is NOT deterministically
// reachable on this small ring under real threads, so it is not the chosen
// mutant here — the drain-merge is the ring's load-bearing message path.
//
// EQ SCOPE (honest bound): this admits the real engine as the graded pillar's
// measured path (FUNCTIONAL SMP equivalence over genuinely concurrent runs).
// The *general* parallel EQ flip additionally needs the coordinator-phase +
// trap-path lock-narrowing (GAP-B) — a named, isolated successor increment.
test "LAW e51-t1 REAL-THREAD ≡ ORACLE at graded scale: driveThreads on the messaging ring equals the sequential oracle over N seeds × n∈{1,2,4}, per-pair order preserved (SMP EQ-admission gate, DIVERGENCE 540 graded)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // ORACLE — the sequential round-robin ring total (schedule-independent).
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total; // 100 + 1+2+3+4+5

    // The wall deadline is ONLY the anti-hang backstop (CAST-19), never a
    // real-time observation: the law observes WORK (grants < budget) + RESULT
    // (halted + denotation) + ORDER only.
    const wall: u64 = 60 * std.time.ns_per_s;
    const max_grants: usize = 100_000;

    // Strong differential: the REAL thread engine over n∈{1,2,4} × 6 seeds must
    // reproduce the oracle EXACTLY, every time — no seed, no thread count, no
    // interleaving changes the denotation.
    for ([_]u32{ 1, 2, 4 }) |n| {
        for (0..6) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 5);
            const eng = SmpEngine{ .n_sched = n, .seed = 0x5117 +% i +% (@as(u64, n) << 32) };
            const run = try eng.driveThreads(&vm, 7, max_grants, wall);
            try std.testing.expect(run.grants < max_grants); // completed within the deterministic work budget
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status); // the ring finished under real threads
            const total = @as(i64, @bitCast(cm.result)) >> 4;
            try std.testing.expectEqual(oracle, total); // REAL ≡ ORACLE (kills m1 ownership-race, m2 lost-wakeup)
            try std.testing.expect(checkPerPairOrder(vm.events.items)); // SACRED per-pair order under real interleaving
        }
    }
}

test "LAW smp-shard-conservation: after driveThreads on the messaging ring, EVERY proc's sigq is EMPTY at quiescence — the DROP-NET that per-pair-order CANNOT see (a lost/stranded signal leaves a non-empty sigq; checkPerPairOrder is blind to a pure drop). The prerequisite guard the Option-B sigq de-globalization needs before it may relocate the drain off L_v (S-epoch, DIVERGENCE 613)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;
    const wall: u64 = 60 * std.time.ns_per_s;
    const max_grants: usize = 100_000;
    // n ∈ {1,2,4,8=MAX_SCHED}: more schedulers = more append/drain contention on
    // the sigq — the interleaving pressure Option B's trust argument demands.
    for ([_]u32{ 1, 2, 4, 8 }) |n| {
        for (0..8) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 5);
            const eng = SmpEngine{ .n_sched = n, .seed = 0x51C0 +% i +% (@as(u64, n) << 40) };
            const run = try eng.driveThreads(&vm, 7, max_grants, wall);
            try std.testing.expect(run.grants < max_grants); // no lost-wakeup livelock
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status);
            try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4); // denotation == oracle
            // ★ THE DROP-NET: at quiescence NO proc may hold an undrained signal.
            // A relocated (off-L_v) drain that DROPS or STRANDS a signal (FM-SMP-
            // SIGQ-LOST-WAKE) leaves a non-empty sigq HERE even though per-pair-order
            // and the denotation can pass — this is the only guard that sees it.
            for (vm.procs.items) |p| {
                try std.testing.expectEqual(@as(usize, 0), p.sigq.items.len);
            }
        }
    }
}

// LAW drainSignals-relocated — the S-epoch Option B METAMORPHIC law (DIVERGENCE
// 614): relocating the SECTION-2 drain OFF `L_v` (batch-detach under the
// `L_sigq` leaf + per-arm `tl_drain_lv` escalation) is an OBSERVATION-QUOTIENT
// refactor — the relocated drain denotes IDENTICALLY to the under-`L_v` drain
// the sequential oracle still runs. Four observations per run, each catching a
// distinct failure mode of the relocation:
//   (1) DENOTATION — collector total == oracle (a torn detach / double-deliver
//       skews the sum);
//   (2) the SACRED per-pair order (a batch reorder inverts SEND/DELIVER stamps
//       for some pair — MUT-SIGQ-1's kill);
//   (3) DELIVER-COUNT == oracle's (a drop AND a duplicate both move the count —
//       per-pair-order alone is blind to a pure drop);
//   (4) CONSERVATION — every sigq empty at quiescence (a STRANDED signal — one
//       appended during the detach window and never re-drained — parks here;
//       MUT-SIGQ-2's kill, FM-SMP-SIGQ-LOST-WAKE).
// n∈{1,2,4,8=MAX_SCHED} × 8 seeds on the receive-bearing ring = the interleaving
// pressure where append-vs-detach actually races; the bounded driveThreads wall
// is the anti-hang backstop (a lost wakeup = grants exhausted / never-halted =
// RED, never a hung suite). The ThreadSanitizer leg of the trust argument runs
// this same law under `-fllvm -fsanitize-thread` (skills/smp-concurrency-slice
// §3b) — a green gate alone is necessary-but-not-sufficient (CTRL-SMP-INTERLEAVING).
test "LAW drainSignals-relocated ≡ under-L_v: the off-L_v batch-detach drain (Option B) denotes identically to the sequential under-L_v oracle — total, sacred per-pair order, deliver-count, and sigq conservation over n∈{1,2,4,8} × 8 seeds (S-epoch, DIVERGENCE 614)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;
    var oracle_delivers: usize = 0;
    for (rr.events.items) |ev| {
        if (ev == .deliver) oracle_delivers += 1;
    }
    try std.testing.expect(oracle_delivers > 0); // the ring is genuinely message-bearing
    const wall: u64 = 60 * std.time.ns_per_s;
    const max_grants: usize = 100_000;
    for ([_]u32{ 1, 2, 4, 8 }) |n| {
        for (0..8) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 5);
            const eng = SmpEngine{ .n_sched = n, .seed = 0x0B0B +% i +% (@as(u64, n) << 44) };
            const run = try eng.driveThreads(&vm, 7, max_grants, wall);
            try std.testing.expect(run.grants < max_grants); // bounded: no relocation livelock
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status);
            try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4); // (1) denotation
            try std.testing.expect(checkPerPairOrder(vm.events.items)); // (2) sacred order
            var delivers: usize = 0;
            for (vm.events.items) |ev| {
                if (ev == .deliver) delivers += 1;
            }
            try std.testing.expectEqual(oracle_delivers, delivers); // (3) no drop, no duplicate
            for (vm.procs.items) |p| {
                try std.testing.expectEqual(@as(usize, 0), p.sigq.items.len); // (4) conservation
            }
        }
    }
}

// LAW n1-send-deliver-vhash-agreement — the sender-narrowing N1 invariant: for
// every stamp that has BOTH a send and a deliver event, the two vhashes AGREE.
// This is what makes the park-time vhash precompute (ParkedSpawn/ParkedSysTask
// .vhash, delivered via signalInner's pre_vhash) an observation-quotient
// refactor: the send event's hash no longer READS the requester's heap at
// delivery time (that heap may belong to a proc running UNLOCKED on another
// worker — the latent race N1 closes), yet denotes identically. Leg 1 proves
// the invariant GLOBALLY under real threads (ring, n∈{1,4} × 4 seeds — this
// also machine-checks the e48-smp-s3 claim that a fragment's sender-heap hash
// equals the receiver-merge hash); leg 2 drives the PARKED spawn path
// explicitly (stage → applyStagedParks → deliverParkedSpawn → drain) and pins
// the send vhash to an independent recomputation. MUT-N1-1 (park vhash := 0)
// and MUT-N1-2 (snapshot drops the last parked entry) both red leg 2.
test "LAW n1-send-deliver-vhash-agreement: every stamp with both send+deliver events agrees on vhash — under real threads (ring n in {1,4} x 4 seeds) and on the explicit parked-spawn path (park-time precompute == delivery == independent hash)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const wall: u64 = 60 * std.time.ns_per_s;
    // Leg 1 — GLOBAL agreement under real concurrency.
    for ([_]u32{ 1, 4 }) |n| {
        for (0..4) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            _ = try seedRing(&vm, 5);
            const eng = SmpEngine{ .n_sched = n, .seed = 0x11A5 +% i +% (@as(u64, n) << 48) };
            _ = try eng.driveThreads(&vm, 7, 100_000, wall);
            var pairs: usize = 0;
            for (vm.events.items) |ev| {
                if (ev != .send) continue;
                for (vm.events.items) |ev2| {
                    if (ev2 == .deliver and ev2.deliver.stamp == ev.send.stamp) {
                        try std.testing.expectEqual(ev.send.vhash, ev2.deliver.vhash);
                        pairs += 1;
                    }
                }
            }
            try std.testing.expect(pairs > 0); // non-vacuous: the ring really pairs sends with delivers
        }
    }
    // Leg 2 — the PARKED path: park-time precompute == delivery-time event == independent hash.
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const requester = try seedRing(&vm, 5);
    const rm = &vm.procs.items[requester].machine;
    const reply = FinalTerms.int(&rm.ctx, 424242);
    const want = FinalTerms.hashTerm(&rm.ctx, reply);
    try vm.staged_spawn.append(gpa, .{ .reqid = 7, .to = requester, .child = 1, .reply = reply, .vhash = FinalTerms.hashTerm(&rm.ctx, reply) });
    try vm.applyStagedParks();
    try vm.deliverParkedSpawn();
    var found = false;
    for (vm.events.items) |ev| {
        if (ev == .send and ev.send.to == requester) {
            try std.testing.expectEqual(want, ev.send.vhash); // MUT-N1-1 (vhash:=0) reds here
            found = true;
        }
    }
    try std.testing.expect(found); // MUT-N1-2 (snapshot drops the entry) reds here
}

// LAW n2a-parked-flag — the sender-narrowing N2a invariant (DIVERGENCE 616):
// the worker top-of-loop is now LOCK-FREE on the idle path (atomic done/err
// latches + the `parked_nonempty` peek); `L_v` is taken for the parked tick
// ONLY when parked work exists. The load-bearing edge is the FLAG ARMING —
// a publish that fails to arm it strands the park forever (quiescence does
// NOT inspect the parked lists), the FM-SMP-SHARD-DROP shape. Leg 1 (unit):
// `applyStagedParks` arms the flag (MUT-N2A-1: skip arming → red). Leg 2
// (REAL THREADS, end-to-end): a proc whose preset `spawn_request` pending is
// trapped mid-run under driveThreads — staged in interpret, published by the
// EPILOGUE snapshot path, delivered only via the flag-gated top-of-loop tick —
// must have its reply DELIVERED at quiescence: parked/staged lists empty + a
// deliver event to the requester exists (MUT-N2A-2: the epilogue publish
// skips arming → the park is stranded at quiescence → red, deterministically).
test "LAW n2a-parked-flag: every parked publish ARMS the lock-free parked_nonempty flag, and under real threads the flag-gated top-of-loop tick delivers a spawn_request reply (no stranded park at quiescence)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // Leg 1 — unit: staged → applyStagedParks arms the flag.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const po = try vm.spawn(halt_prog, 0, null);
        const mo = &vm.procs.items[po].machine;
        try std.testing.expect(!vm.parked_nonempty.load(.acquire));
        const reply = FinalTerms.int(&mo.ctx, 99);
        try vm.staged_spawn.append(gpa, .{ .reqid = 1, .to = po, .child = po, .reply = reply, .vhash = FinalTerms.hashTerm(&mo.ctx, reply) });
        try vm.applyStagedParks();
        try std.testing.expect(vm.parked_nonempty.load(.acquire)); // MUT-N2A-1 reds here
    }
    // Leg 2 — real threads: trap → epilogue publish → flag-gated delivery.
    const wall: u64 = 60 * std.time.ns_per_s;
    for ([_]u32{ 1, 4 }) |n| {
        for (0..4) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            // recv-then-halt: empty mbox -> wait (suspend); on wake take the
            // message and HALT (a bare `wait` proc would spin once mail arrives).
            const idle: ia.Program = &.{
                .{ .recv_any = .{ .dst = 0, .else_to = 2 } },
                .{ .halt = .{ .src = .{ .x = 0 } } },
                .{ .wait = .{ .to = 0 } },
            };
            const req = try vm.spawn(idle, 0, null);
            const rp = vm.procs.items[req];
            const req_term = try FinalTerms.pid(&rp.machine.ctx, req, 0);
            const reqid_term = try FinalTerms.ref(&rp.machine.ctx, .{ 0, 0, 42 });
            rp.machine.pending = .{ .request_system_task = .{ .requester = req_term, .reqid = reqid_term, .op = .garbage_collect } };
            const eng = SmpEngine{ .n_sched = n, .seed = 0x02A0 +% i +% (@as(u64, n) << 40) };
            const run = try eng.driveThreads(&vm, 7, 100_000, wall);
            try std.testing.expect(run.grants < 100_000); // bounded
            // NO STRANDED PARK: the trap's reply was published AND delivered.
            try std.testing.expectEqual(@as(usize, 0), vm.staged_systask.items.len);
            try std.testing.expectEqual(@as(usize, 0), vm.parked_systask.items.len); // MUT-N2A-2 reds here
            var delivered = false;
            for (vm.events.items) |ev| {
                if (ev == .deliver and ev.deliver.to == req) delivered = true;
            }
            try std.testing.expect(delivered); // the reply reached the requester's mailbox path
        }
    }
}

// LAW n3-staged-flag — the epilogue SECTION-A narrowing's arming edge
// (DIVERGENCE 617): SECTION A takes its per-grant `L_v` acquire ONLY when an
// exit is due (owner-exclusive status read) or `staged_nonempty` is armed. A
// staging site that fails to arm strands the park in `staged_*` (the epilogue
// never snapshots it) — leg 2 of n2a-parked-flag catches that end-to-end
// under real threads (MUT-N3-2's kill); this unit leg pins the arming edge
// itself, and MUT-N3-1 (exit gate forced false) is killed by e51-t1 (rings
// never complete when halted procs stop exiting).
test "LAW n3-staged-flag: a request_system_task staging ARMS the staged_nonempty peek (the epilogue's conditional-L_v gate)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const req = try vm.spawn(idle, 0, null);
    const rp = vm.procs.items[req];
    try std.testing.expect(!vm.staged_nonempty.load(.acquire));
    const req_term = try FinalTerms.pid(&rp.machine.ctx, req, 0);
    const reqid_term = try FinalTerms.ref(&rp.machine.ctx, .{ 0, 0, 7 });
    rp.machine.pending = .{ .request_system_task = .{ .requester = req_term, .reqid = reqid_term, .op = .garbage_collect } };
    try vm.interpret(req);
    try std.testing.expectEqual(@as(usize, 1), vm.staged_systask.items.len);
    try std.testing.expect(vm.staged_nonempty.load(.acquire)); // the arming edge
}

// LAW n3-threaded-exit — the missing observable MUT-N3-1 exposed (DIVERGENCE
// 617): every prior threaded law completed via machine-halt + quiescence
// alone, so a worker epilogue that silently SKIPS `normalExit`/`terminate`
// (exit cascades, monitor DOWNs, registry cleanup) passed the ENTIRE suite.
// This law pins the exit SIDE-EFFECT under real threads: a watcher MONITORS a
// proc that halts — the DOWN must be delivered and wake the watcher to
// completion. Skipped exit ⇒ no DOWN ⇒ the watcher parks in `wait` forever ⇒
// quiescence with watcher NOT halted ⇒ RED (deterministic, n∈{1,4} × 4 seeds).
test "LAW n3-threaded-exit: under driveThreads a halted proc's normalExit fires its monitor DOWN — the watcher receives it and completes (the exit side-effect a machine-halt-only observation cannot see)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const wall: u64 = 60 * std.time.ns_per_s;
    for ([_]u32{ 1, 4 }) |n| {
        for (0..4) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            // watcher: wait for ONE message (the DOWN), then halt with it.
            const watcher_prog: ia.Program = &.{
                .{ .recv_any = .{ .dst = 0, .else_to = 2 } },
                .{ .halt = .{ .src = .{ .x = 0 } } },
                .{ .wait = .{ .to = 0 } },
            };
            const watcher = try vm.spawn(watcher_prog, 0, null);
            const target = try vm.spawn(halt_prog, 0, null);
            // wire the monitor by hand (the spawn_monitor shape).
            try vm.procs.items[watcher].monitors_held.append(gpa, .{ .ref = 77, .target = target });
            try vm.procs.items[target].monitored_by.append(gpa, .{ .ref = 77, .watcher = watcher });
            const eng = SmpEngine{ .n_sched = n, .seed = 0x0E7 +% i +% (@as(u64, n) << 36) };
            const run = try eng.driveThreads(&vm, 7, 100_000, wall);
            try std.testing.expect(run.grants < 100_000); // bounded
            // the target's normalExit ran (alive=false) and its DOWN reached the
            // watcher, which consumed it and HALTED (MUT-N3-1: skipped exit ⇒
            // watcher still .suspended ⇒ red).
            try std.testing.expect(!vm.procs.items[target].alive);
            try std.testing.expectEqual(ia.Status.halted, vm.procs.items[watcher].machine.status);
        }
    }
}

// LAW n4-stable-mirror — the sigq-detach merge's foundation (DIVERGENCE 618):
// `stable_procs` mirrors `procs` EXACTLY (count == len, same box per index),
// across the 1024-entry SEGMENT BOUNDARY, so the relocated drain's lock-free
// deref denotes the L_v deref it replaced. MUT-N4-1 (skip the mirror append)
// and MUT-N4-2 (write every box to slot 0) both red here deterministically.
test "LAW n4-stable-mirror: stable_procs == procs (count + per-index box identity) across the segment boundary (1100 spawns)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    var k: usize = 0;
    while (k < 1100) : (k += 1) _ = try vm.spawn(halt_prog, 0, null);
    try std.testing.expectEqual(vm.procs.items.len, vm.stable_procs.count.load(.acquire));
    for (vm.procs.items, 0..) |bp, i| {
        try std.testing.expectEqual(bp, vm.stable_procs.get(i).?);
    }
    try std.testing.expect(vm.stable_procs.get(1100) == null); // bound is exact
}

// LAW n5-hint-conservation — the L_c coordinator narrowing's guard
// (DIVERGENCE 619): `runnable_total` (the lock-free idle-peek HINT) must
// CONSERVE the `queued`-bit population — at driveThreads quiescence both are
// exactly ZERO (every enqueue paired with its pick; a skipped increment
// wraps negative, a skipped decrement strands a positive residue — either is
// a deterministic RED). The hint is advisory for the peek, but its
// conservation is what bounds a false-negative to ONE deferred tick; the
// quiescence verdict itself is still taken under `L_c` on the real state.
test "LAW n5-hint-conservation: runnable_total == queued-bit count == 0 at driveThreads quiescence over n in {1,2,4,8} x 8 seeds (the lock-free coordinator peek never strands or fabricates runnable work)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const wall: u64 = 60 * std.time.ns_per_s;
    for ([_]u32{ 1, 2, 4, 8 }) |n| {
        for (0..8) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            _ = try seedRing(&vm, 5);
            const eng = SmpEngine{ .n_sched = n, .seed = 0x5A11 +% i +% (@as(u64, n) << 52) };
            const run = try eng.driveThreads(&vm, 7, 100_000, wall);
            try std.testing.expect(run.grants < 100_000);
            var bits: usize = 0;
            for (vm.queued.items) |*q| {
                if (q.load(.monotonic)) bits += 1;
            }
            try std.testing.expectEqual(@as(usize, 0), bits); // real state drained
            try std.testing.expectEqual(@as(usize, 0), vm.runnable_total.load(.acquire)); // hint conserves
        }
    }
}

// LAW n6-mixed-workload — the POST-NARROWING composition law (DIVERGENCE 620):
// the N1..N5 lock cuts were each proven on focused workloads; this law drives
// ALL the narrowed fronts AT ONCE under real threads — a messaging ring
// (sigq/L_sigq + wakes), a compute storm (grant/pick + epilogue exits), and
// parked system-task traps (staged→published→flag-tick→delivered) — and
// asserts every standing invariant plus hard denotations on ONE run: ring
// total == sequential oracle, all compute workers halt with IDENTICAL
// results, every trap reply delivered, queues/hints/parks/sigqs all ZERO at
// quiescence, sacred per-pair order. This is also the fixed MIXED WORKLOAD
// the per-lock contention probe measures (the {S} serial-term attribution
// now happens here, not on the coordination-floor-saturated bare ring).
test "LAW n6-mixed-workload: ring + compute storm + parked traps compose under driveThreads — oracle denotation, uniform worker results, delivered traps, and every conservation observable zero at quiescence (n in {2,8} x 4 seeds)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;
    const wall: u64 = 90 * std.time.ns_per_s;
    for ([_]u32{ 2, 8 }) |n| {
        for (0..4) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 5);
            var compute: [16]Pid = undefined;
            for (0..16) |w| compute[w] = try vm.spawn(scale_worker, 0, null);
            const trap_recv: ia.Program = &.{
                .{ .recv_any = .{ .dst = 0, .else_to = 2 } },
                .{ .halt = .{ .src = .{ .x = 0 } } },
                .{ .wait = .{ .to = 0 } },
            };
            var traps: [3]Pid = undefined;
            for (0..3) |t| {
                traps[t] = try vm.spawn(trap_recv, 0, null);
                const tp = vm.procs.items[traps[t]];
                const req_term = try FinalTerms.pid(&tp.machine.ctx, traps[t], 0);
                const reqid_term = try FinalTerms.ref(&tp.machine.ctx, .{ 0, 0, @intCast(40 + t) });
                tp.machine.pending = .{ .request_system_task = .{ .requester = req_term, .reqid = reqid_term, .op = .garbage_collect } };
            }
            const eng = SmpEngine{ .n_sched = n, .seed = 0x316D +% i +% (@as(u64, n) << 44) };
            const run = try eng.driveThreads(&vm, 7, 100_000, wall);
            try std.testing.expect(run.grants < 100_000); // bounded
            // ring denotation == the sequential oracle
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status);
            try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4);
            // compute storm: every worker halted, all with the SAME result
            const r0 = vm.procs.items[compute[0]].machine.result;
            for (compute) |w| {
                try std.testing.expectEqual(ia.Status.halted, vm.procs.items[w].machine.status);
                try std.testing.expectEqual(r0, vm.procs.items[w].machine.result);
            }
            // every trap reply delivered (recv-then-halt consumed it)
            for (traps) |t| {
                try std.testing.expectEqual(ia.Status.halted, vm.procs.items[t].machine.status);
            }
            // conservation sweep: parks, staging, hints, queues, sigqs all zero
            try std.testing.expectEqual(@as(usize, 0), vm.parked_systask.items.len);
            try std.testing.expectEqual(@as(usize, 0), vm.staged_systask.items.len);
            try std.testing.expectEqual(@as(usize, 0), vm.runnable_total.load(.acquire));
            var bits: usize = 0;
            for (vm.queued.items) |*q| {
                if (q.load(.monotonic)) bits += 1;
            }
            try std.testing.expectEqual(@as(usize, 0), bits);
            for (vm.procs.items) |p| {
                try std.testing.expectEqual(@as(usize, 0), p.sigq.items.len);
            }
            try std.testing.expect(checkPerPairOrder(vm.events.items)); // sacred order
        }
    }
}

// LAW n7-event-shard-merge — the L_events sharding's kernel (DIVERGENCE 621):
// the join-time merge of per-worker event shards must reproduce the exact
// seq linearization the `L_events` lock's append order used to produce —
// ORDER (globally seq-ascending, interleaving across shards), CONSERVATION
// (every entry exactly once; shards left empty), and PRE-RUN PREFIX (events
// already in the log stay in front). MUT-N7-1 (merge skips a shard) and
// MUT-N7-2 (merge skips the sort) both red here deterministically; the
// threaded suite (per-pair order + deliver-count + vhash agreement on the
// merged log) re-proves the observation quotient end-to-end.
test "LAW n7-event-shard-merge: interleaved shards merge into the exact seq linearization — order + conservation + pre-run prefix, shards drained" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    try vm.events.append(gpa, .{ .grant = 99 }); // pre-run prefix entry
    var shards: [2]std.ArrayList(SeqEvent) = .{ .empty, .empty };
    defer for (&shards) |*sh| sh.deinit(gpa);
    // shard 0 gets seqs {0,2,5}, shard 1 gets {1,3,4} — interleaved.
    try shards[0].append(gpa, .{ .seq = 0, .ev = .{ .grant = 0 } });
    try shards[0].append(gpa, .{ .seq = 2, .ev = .{ .grant = 2 } });
    try shards[0].append(gpa, .{ .seq = 5, .ev = .{ .grant = 5 } });
    try shards[1].append(gpa, .{ .seq = 1, .ev = .{ .grant = 1 } });
    try shards[1].append(gpa, .{ .seq = 3, .ev = .{ .grant = 3 } });
    try shards[1].append(gpa, .{ .seq = 4, .ev = .{ .grant = 4 } });
    try mergeEventShards(&vm, shards[0..]);
    try std.testing.expectEqual(@as(usize, 7), vm.events.items.len); // conservation
    try std.testing.expectEqual(@as(Pid, 99), vm.events.items[0].grant); // pre-run prefix
    for (0..6) |k| {
        try std.testing.expectEqual(@as(Pid, @intCast(k)), vm.events.items[k + 1].grant); // exact seq order
    }
    try std.testing.expectEqual(@as(usize, 0), shards[0].items.len); // drained
    try std.testing.expectEqual(@as(usize, 0), shards[1].items.len);
}

// LAW n8-exit-during-run — the exit-cascade race hunt (DIVERGENCE 622): the
// send-time exit-reason copy (`.exit_to`/`terminate` gcCopy INTO the target's
// heap, under the SENDER's L_v) can overlap the target's OWN unlocked heap
// appends — its run-loop `put_list` conses and its off-L_v drain merges. No
// prior law drove an exit INTO a proc that is actively RUNNING and consing;
// this one does, under n∈{2,4} × 6 seeds, and is the fixture the TSan verdict
// (fix vs documented bound) is taken on. The receiver traps exits, so the
// boxed reason must ARRIVE as an {'EXIT',...} message (delivery observable),
// and the run must stay bounded + conserved.
test "LAW n8-exit-during-run: a boxed exit reason sent into an actively-consing receiver arrives intact under real threads — bounded, delivered, conserved (the send-time cross-heap copy exercised against the owner's unlocked appends)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const wall: u64 = 90 * std.time.ns_per_s;
    for ([_]u32{ 2, 4 }) |n| {
        for (0..6) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            // P: an actively-CONSING receiver — every message is consed onto a
            // list in x1 (real owner-side heap appends in the unlocked run),
            // looping until the mailbox drains, then suspending.
            const consumer: ia.Program = &.{
                .{ .recv_any = .{ .dst = 0, .else_to = 3 } },
                .{ .put_list = .{ .h = .{ .x = 0 }, .t = .{ .x = 1 }, .dst = 1 } },
                .{ .jump = .{ .to = 0 } },
                .{ .wait = .{ .to = 0 } },
            };
            const peer = try vm.spawn(consumer, 0, null);
            vm.procs.items[peer].machine.trap_exit = true; // exit arrives as a message
            // Preload a burst so P is mid-cons when the exit lands.
            for (0..60) |k| {
                const pp = vm.procs.items[peer];
                try vm.signal(peer, peer, .{ .message = FinalTerms.int(&pp.machine.ctx, @intCast(k)) });
            }
            // A: sends exit/2 with a BOXED tuple reason (built in A's heap —
            // the send-time gcCopy writes P's heap under A's L_v).
            const idleA: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
            const exiter = try vm.spawn(idleA, 0, null);
            const am = &vm.procs.items[exiter].machine;
            const reason = try FinalTerms.tuple(&am.ctx, &.{
                FinalTerms.atom(&am.ctx, try atoms.intern("boom")),
                FinalTerms.int(&am.ctx, 4242),
            });
            am.pending = .{ .exit_to = .{ .pid = try FinalTerms.pid(&am.ctx, peer, 0), .reason = reason } };
            const eng = SmpEngine{ .n_sched = n, .seed = 0x0E8 +% i +% (@as(u64, n) << 32) };
            const run = try eng.driveThreads(&vm, 7, 100_000, wall);
            try std.testing.expect(run.grants < 100_000); // bounded
            // P survived (trapping), consumed the burst AND the {'EXIT',..}
            // message: ≥61 delivers to P, sigq/mbox drained, P suspended.
            var delivers: usize = 0;
            for (vm.events.items) |ev| {
                if (ev == .deliver and ev.deliver.to == peer) delivers += 1;
            }
            try std.testing.expect(delivers >= 61);
            try std.testing.expect(vm.procs.items[peer].alive);
            try std.testing.expectEqual(@as(usize, 0), vm.procs.items[peer].sigq.items.len);
            try std.testing.expect(checkPerPairOrder(vm.events.items));
        }
    }
}

// LAW n9-ownership-conservation — the Q1 redesign's residue check (DIVERGENCE
// 623): after a threaded run on the MIXED workload, ownership/queueing state
// is fully retired — every `owned[pid] == NO_OWNER`, `owned_count == 0`,
// `delivering == 0`, every per-worker run queue empty. Together with the
// fail-closed pick CAS (SC-N9-2: a conservation breach PANICS in-run) and the
// existing hint/sigq conservation laws this pins the queued→owned→released
// lifecycle end-to-end. MUT-N9-1 (signal drops the Dekker re-read: wakes to
// un-owned procs are silently deferred forever) reds the standing bounded
// laws (rings never start); MUT-N9-3 (enqueue skips the dedup swap: double
// membership) fires the CAS panic deterministically.
test "LAW n9-ownership-conservation: after driveThreads on the mixed workload every owned==NO_OWNER, owned_count==0, delivering==0, and all per-worker run queues are empty (n in {2,8} x 4 seeds)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const wall: u64 = 90 * std.time.ns_per_s;
    for ([_]u32{ 2, 8 }) |n| {
        for (0..4) |i| {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            _ = try seedRing(&vm, 5);
            for (0..16) |_| _ = try vm.spawn(scale_worker, 0, null);
            const eng = SmpEngine{ .n_sched = n, .seed = 0x0919 +% i +% (@as(u64, n) << 28) };
            const run = try eng.driveThreads(&vm, 7, 100_000, wall);
            try std.testing.expect(run.grants < 100_000);
            for (vm.owned.items) |*o| {
                try std.testing.expectEqual(NO_OWNER, o.load(.monotonic));
            }
            try std.testing.expectEqual(@as(u32, 0), vm.delivering.load(.monotonic));
            for (vm.run_qs[0..n]) |q| {
                try std.testing.expectEqual(@as(usize, 0), q.items.len);
            }
        }
    }
}

// LAW gap-b-inc0 — CONCURRENT SHARED-ETS LINEARIZATION (the SMP lock-narrowing
// REGRESSION BASELINE, GAP-B Increment 0). The GAP-B hazard analysis (its STPA
// packet: CTRL-SMP-EXECUTION / UCA-SMP-5..10) concluded that NO coarse-lock
// narrowing is a "small safe increment" — any coordinator lock disjoint from the
// VM lock forms an L_v↔L_c deadlock cycle via the trap path's parked-list
// writes, and the registry + timer wheel have NO internal lock, so a narrowing
// risks a bounded-join hang or a cross-thread UAF. GAP-B.1/B.2 are therefore a
// SCOPED DEFERRAL (DIVERGENCE 540-successor). This law is the one genuinely SAFE
// increment that lands NOW: it strengthens the SMP evidence with the observable
// e51-t1 lacked — a SHARED MUTABLE STORE under REAL concurrency — WITHOUT any
// lock change, so any future narrowing that breaks shared-store linearization is
// observable-if-wrong against this baseline.
//
// N real std.Thread workers each do M `ets:update_counter/3` on ONE shared,
// public, named table. The only thing serializing them is the ETS reentrant
// spinlock (ets_algebra lockShared, the VM→ets lock order). The counter MUST end
// at exactly N*M for EVERY thread count — concurrent read-modify-writes linearize
// (no lost update), invariant of the real interleaving. This is UCA-SMP-4/C-10
// (in-run shared-store races) made a positive, measured law.
//
// MUTANT gap-b-inc0/m1 (ETS lock removed → cross-thread corruption, KILLED):
// make `lockShared`/`unlockShared` (src/ets_algebra.zig) no-ops → concurrent
// update_counter read-modify-writes race the shared ETS REGION heap (its
// ArrayList grows/frees under two threads at once) → allocator corruption
// (invalid-free / segfault) on n≥2 — a genuine cross-thread UAF, not merely a
// lost counter value. This is the hazard UCA-SMP-4 / C-10 names: the ETS
// reentrant spinlock is the load-bearing linearization point that ANY future
// coordinator narrowing (GAP-B.1/B.2) must preserve. (No second mutant: this is
// a single-invariant regression-baseline law; the ownership/wake mutants are
// already killed by LAW e51-t1.)
test "LAW gap-b-inc0 CONCURRENT SHARED-ETS LINEARIZATION: N real threads x M ets:update_counter/3 on one shared table end at EXACTLY N*M for every thread count — no lost update (the SMP lock-narrowing regression baseline; GAP-B.1/B.2 deferred)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const iters: usize = 400;

    const Worker = struct {
        fn run(m: *ia.Machine, tab: FinalTerms.Term, key: FinalTerms.Term, incr: FinalTerms.Term, n: usize) void {
            var i: usize = 0;
            while (i < n) : (i += 1) {
                // the ONLY synchronization is update_counter_3's internal ETS
                // reentrant spinlock — the real concurrent shared-store path.
                _ = ets_bifs.update_counter_3(m, &.{ tab, key, incr }) catch return;
            }
        }
    };

    for ([_]u32{ 1, 2, 4 }) |nthreads| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();

        // one shared PUBLIC named table with a counter row {counter, 0}. Public
        // so every worker's machine may write it (protected would reject peers).
        const setup = try vm.spawn(halt_prog, 0, null);
        const sm = &vm.procs.items[setup].machine;
        const tname = try atoms.intern("ctr_tab");
        const opts = try FinalTerms.cons(
            &sm.ctx,
            FinalTerms.atom(&sm.ctx, try atoms.intern("named_table")),
            try FinalTerms.cons(&sm.ctx, FinalTerms.atom(&sm.ctx, try atoms.intern("public")), FinalTerms.nil(&sm.ctx)),
        );
        _ = try ets_bifs.new_2(sm, &.{ FinalTerms.atom(&sm.ctx, tname), opts });
        const key0 = FinalTerms.atom(&sm.ctx, try atoms.intern("k"));
        _ = try ets_bifs.insert_2(sm, &.{ FinalTerms.atom(&sm.ctx, tname), try FinalTerms.tuple(&sm.ctx, &.{ key0, FinalTerms.int(&sm.ctx, 0) }) });

        // N workers, each with its OWN machine (heap) but the SHARED vm.ets.
        var machines: [4]*ia.Machine = undefined;
        for (0..nthreads) |w| {
            const wp = try vm.spawn(halt_prog, 0, null);
            machines[w] = &vm.procs.items[wp].machine;
        }
        var threads: [4]std.Thread = undefined;
        for (0..nthreads) |w| {
            const m = machines[w];
            const tab = FinalTerms.atom(&m.ctx, tname); // atoms are shared-table immediates
            const key = FinalTerms.atom(&m.ctx, try atoms.intern("k"));
            const incr = FinalTerms.int(&m.ctx, 1);
            threads[w] = try std.Thread.spawn(.{}, Worker.run, .{ m, tab, key, incr, iters });
        }
        for (0..nthreads) |w| threads[w].join();

        // LINEARIZATION: every one of N*M increments landed — no lost update.
        const got = try ets_bifs.lookup_2(sm, &.{ FinalTerms.atom(&sm.ctx, tname), key0 });
        const row = FinalTerms.listHead(&sm.ctx, got);
        const final = FinalTerms.smallValOf(FinalTerms.tupleElem(&sm.ctx, row, 1));
        try std.testing.expectEqual(@as(i64, @intCast(@as(usize, nthreads) * iters)), final);
    }
}

test "LAW gap-resident-node: a RESIDENT node STAYS UP while any process is ALIVE (idle-but-alive → .idle, never a deadlock); halts only at aliveCount==0; default drive UNCHANGED" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // a process that SUSPENDS forever (alive, not schedulable) — the shape of every
    // idle gen_server in a supervision tree, blocked in `receive` with no message
    // (`wait` sets `.suspended`; recv_any-else_to-self would BUSY-loop, not block).
    const idle: ia.Program = &.{
        .{ .wait = .{ .to = 0 } }, // suspend forever (resume at pc 0 when signalled)
    };
    // a process that runs one instruction then falls off the end → halts.
    const halter: ia.Program = &.{
        .{ .move = .{ .src = .{ .imm = 0 }, .dst = 0 } },
    };
    const sched: Scheduler = .round_robin;

    // (1) IDLE-BUT-ALIVE: a blocked process keeps the resident node UP. driveResident
    //     reaches the bounded `.idle` verdict — NOT a deadlock — with the process
    //     ALIVE (aliveCount=1) but not runnable (liveCount=0): the CTRL-RESIDENT-NODE
    //     state the one-shot driver would mislabel a deadlock (FM-NODE-1).
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        _ = try vm.spawn(idle, 0, null);
        const outcome = try sched.driveResident(&vm, 7, 100_000, 4);
        try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, outcome);
        try std.testing.expectEqual(@as(usize, 1), vm.aliveCount());
        try std.testing.expectEqual(@as(usize, 0), vm.liveCount());
    }
    // (2) DONE: when every process has halted, the resident node shuts down cleanly
    //     (aliveCount==0), not a spin to max_slices.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        _ = try vm.spawn(halter, 0, null);
        const outcome = try sched.driveResident(&vm, 7, 100_000, 4);
        try std.testing.expectEqual(Scheduler.ResidentOutcome.done, outcome);
        try std.testing.expectEqual(@as(usize, 0), vm.aliveCount());
    }
    // (3) DEFAULT UNCHANGED: the one-shot `drive` still exits the instant nothing is
    //     RUNNABLE, leaving the idle process ALIVE-but-blocked — the resident verdict
    //     is opt-in (driveResident), so every existing law/suite is byte-preserved.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        _ = try vm.spawn(idle, 0, null);
        try sched.drive(&vm, 7, 100_000);
        try std.testing.expectEqual(@as(usize, 1), vm.aliveCount());
        try std.testing.expectEqual(@as(usize, 0), vm.liveCount());
    }
}

test "LAW gap-file-handle-io: compiled file:open/pread/pwrite/close reach the RunFd handle table via resolveLibrary (the WHOLE file: surface was DEAD in implOf → undef, DIVERGENCE 586); positioned round-trip + eof + closed→einval byte-EQ vs OTP-30" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const bdisp = @import("bifs/dispatch.zig");
    const file_bifs = @import("bifs/file.zig");

    // (1) THE WIRING — the regression guard for DIVERGENCE 586: the file: LIBRARY
    // surface resolves on the resolveLibrary path. It USED to sit in `implOf`
    // (reached by `resolve` ONLY for bif.tab `.implemented` rows, AND its file arm
    // early-returns on native_name_encoding) → the WHOLE file: surface was DEAD →
    // a compiled `file:read_file`/`open`/... resolved to neither table → undef.
    try std.testing.expect(bdisp.resolveLibrary("file", "open", 2) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "pread", 3) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "pwrite", 3) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "close", 1) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "read_file", 1) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "write_file", 2) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "read_file_info", 1) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "list_dir", 1) != null);

    // (2) THE FULL HANDLE ROUND-TRIP through bif→pending→interpret→handler over a
    // REAL temp dir: open → pwrite → pread(byte-exact) → pread-past-EOF(eof) →
    // close(ok) → double-close({error,einval}) → pread-after-close({error,einval}).
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    vm.fs = .{ .io = io, .root = tmp.dir };
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;

    const path = try FinalTerms.binary(&m.ctx, "handle_io.dat");
    var modes = FinalTerms.nil(&m.ctx); // [read, write] → read_write
    modes = try FinalTerms.cons(&m.ctx, FinalTerms.atom(&m.ctx, try atoms.intern("write")), modes);
    modes = try FinalTerms.cons(&m.ctx, FinalTerms.atom(&m.ctx, try atoms.intern("read")), modes);

    _ = try file_bifs.open_2(m, &.{ path, modes });
    try std.testing.expect(m.pending != null); // the bif EMITTED the file_op trap
    try vm.interpret(p0);
    const dev = try sockUnwrapOk(m, m.regs[0], &atoms); // {ok, {file_descriptor,prim_file,N}}
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, dev) == .tuple and FinalTerms.tupleArity(&m.ctx, dev) == 3);

    const ok_a = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));
    const payload = try FinalTerms.binary(&m.ctx, "HELLO-world-0123456789");
    _ = try file_bifs.pwrite_3(m, &.{ dev, FinalTerms.int(&m.ctx, 0), payload });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], ok_a)); // pwrite → ok

    _ = try file_bifs.pread_3(m, &.{ dev, FinalTerms.int(&m.ctx, 6), FinalTerms.int(&m.ctx, 5) });
    try vm.interpret(p0);
    const got = try sockUnwrapOk(m, m.regs[0], &atoms);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, got, try FinalTerms.binary(&m.ctx, "world"))); // byte-exact positioned read

    _ = try file_bifs.pread_3(m, &.{ dev, FinalTerms.int(&m.ctx, 1000), FinalTerms.int(&m.ctx, 4) });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], FinalTerms.atom(&m.ctx, try atoms.intern("eof")))); // past EOF → eof

    const einval = try vm.fileErrTuple(m, error.Einval);
    _ = try file_bifs.close_1(m, &.{dev});
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], ok_a)); // close → ok
    _ = try file_bifs.close_1(m, &.{dev});
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], einval)); // double-close → {error,einval}
    _ = try file_bifs.pread_3(m, &.{ dev, FinalTerms.int(&m.ctx, 0), FinalTerms.int(&m.ctx, 1) });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], einval)); // pread after close → {error,einval}
}

test "LAW gap-file-seq-io: compiled file:read/2, write/2, position/2 reach the RunFd offset model via resolveLibrary; sequential read/write ADVANCE + position seeks (bof/cur/eof), byte-EQ vs OTP-30" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const bdisp = @import("bifs/dispatch.zig");
    const file_bifs = @import("bifs/file.zig");
    // (1) THE WIRING (dispatch-reachability net for the sequential surface).
    try std.testing.expect(bdisp.resolveLibrary("file", "read", 2) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "write", 2) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "position", 2) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "read_file_info", 2) != null);

    // (2) THE SEQUENTIAL ROUND-TRIP over a real tmp dir: two writes ADVANCE the
    // offset; reads consume+advance; position seeks bof/cur/eof; seek-before-BOF einval.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    vm.fs = .{ .io = io, .root = tmp.dir };
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const ok_a = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));
    const eof_a = FinalTerms.atom(&m.ctx, try atoms.intern("eof"));
    const einval = try vm.fileErrTuple(m, error.Einval);
    const H = struct {
        fn open(mm: *ia.Machine, vmm: *Vm, at: *AtomTable, p: Pid, wr: bool) !FinalTerms.Term {
            var modes = FinalTerms.nil(&mm.ctx);
            modes = try FinalTerms.cons(&mm.ctx, FinalTerms.atom(&mm.ctx, try at.intern(if (wr) "write" else "read")), modes);
            _ = try @import("bifs/file.zig").open_2(mm, &.{ try FinalTerms.binary(&mm.ctx, "seq.dat"), modes });
            try vmm.interpret(p);
            return sockUnwrapOk(mm, mm.regs[0], at);
        }
    };
    // write "HELLO" then "world" — the second write must ADVANCE (append), not overwrite.
    const w = try H.open(m, &vm, &atoms, p0, true);
    _ = try file_bifs.write_2(m, &.{ w, try FinalTerms.binary(&m.ctx, "HELLO") });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], ok_a));
    _ = try file_bifs.write_2(m, &.{ w, try FinalTerms.binary(&m.ctx, "world") });
    try vm.interpret(p0);
    _ = try file_bifs.close_1(m, &.{w});
    try vm.interpret(p0);
    // read back sequentially.
    const r = try H.open(m, &vm, &atoms, p0, false);
    const rd = struct {
        fn go(mm: *ia.Machine, vmm: *Vm, p: Pid, fd: FinalTerms.Term, n: i64) !FinalTerms.Term {
            _ = try @import("bifs/file.zig").read_2(mm, &.{ fd, FinalTerms.int(&mm.ctx, n) });
            try vmm.interpret(p);
            return mm.regs[0];
        }
    }.go;
    const pos = struct {
        fn go(mm: *ia.Machine, vmm: *Vm, p: Pid, fd: FinalTerms.Term, loc: FinalTerms.Term) !FinalTerms.Term {
            _ = try @import("bifs/file.zig").position_2(mm, &.{ fd, loc });
            try vmm.interpret(p);
            return mm.regs[0];
        }
    }.go;
    // read 5 → {ok,"HELLO"}; the offset advanced to 5.
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try sockUnwrapOk(m, try rd(m, &vm, p0, r, 5), &atoms), try FinalTerms.binary(&m.ctx, "HELLO")));
    // read 100 → {ok,"world"} (only 5 remain); then eof.
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try sockUnwrapOk(m, try rd(m, &vm, p0, r, 100), &atoms), try FinalTerms.binary(&m.ctx, "world")));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try rd(m, &vm, p0, r, 1), eof_a));
    // position bof → {ok,0}; eof → {ok,10}; {eof,-4} → {ok,6}; then read → "orld".
    const okpos = struct {
        fn expect(mm: *ia.Machine, at: *AtomTable, got: FinalTerms.Term, want: i64) !void {
            const v = try sockUnwrapOk(mm, got, at);
            try std.testing.expectEqual(want, FinalTerms.smallValOf(v));
        }
    }.expect;
    try okpos(m, &atoms, try pos(m, &vm, p0, r, FinalTerms.atom(&m.ctx, try atoms.intern("bof"))), 0);
    try okpos(m, &atoms, try pos(m, &vm, p0, r, FinalTerms.atom(&m.ctx, try atoms.intern("eof"))), 10);
    const eof_neg = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try atoms.intern("eof")), FinalTerms.int(&m.ctx, -4) });
    try okpos(m, &atoms, try pos(m, &vm, p0, r, eof_neg), 6);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try sockUnwrapOk(m, try rd(m, &vm, p0, r, 100), &atoms), try FinalTerms.binary(&m.ctx, "orld")));
    // seek before BOF → {error, einval}.
    const bof_neg = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try atoms.intern("bof")), FinalTerms.int(&m.ctx, -1) });
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try pos(m, &vm, p0, r, bof_neg), einval));
}

test "LAW gap-file-fs-mutation: compiled file:delete/rename/make_dir/del_dir/truncate/sync/read_link_info reach the handlers via resolveLibrary; ok/{error,Posix} shapes byte-EQ vs OTP-30 (the FINAL file: slice → real_file_io EQ)" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const bdisp = @import("bifs/dispatch.zig");
    const file_bifs = @import("bifs/file.zig");
    // (1) THE WIRING (dispatch-reachability net for the fs-mutation surface).
    inline for (.{ "delete", "make_dir", "del_dir", "truncate", "sync", "read_link_info" }) |nm|
        try std.testing.expect(bdisp.resolveLibrary("file", nm, 1) != null);
    try std.testing.expect(bdisp.resolveLibrary("file", "rename", 2) != null);

    // (2) BEHAVIOUR over a real tmp dir: make_dir→del_dir round-trip; write+rename+read;
    // delete then a missing delete → {error,enoent}; make_dir twice → {error,eexist}.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    vm.fs = .{ .io = io, .root = tmp.dir };
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const ok_a = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));
    const enoent = try vm.fileErrTuple(m, error.Enoent);
    const eexist = try vm.fileErrTuple(m, error.Eexist);
    const call = struct {
        fn go1(mm: *ia.Machine, vmm: *Vm, p: Pid, comptime f: anytype, a0: FinalTerms.Term) !FinalTerms.Term {
            _ = try f(mm, &.{a0});
            try vmm.interpret(p);
            return mm.regs[0];
        }
    };
    const dir = try FinalTerms.binary(&m.ctx, "d");
    // make_dir → ok; make_dir again → {error,eexist}; del_dir → ok.
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try call.go1(m, &vm, p0, file_bifs.make_dir_1, dir), ok_a));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try call.go1(m, &vm, p0, file_bifs.make_dir_1, dir), eexist));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try call.go1(m, &vm, p0, file_bifs.del_dir_1, dir), ok_a));
    // write a file, rename it, delete the new name → ok; delete a missing name → enoent.
    _ = try file_bifs.write_file_2(m, &.{ try FinalTerms.binary(&m.ctx, "a.dat"), try FinalTerms.binary(&m.ctx, "hi") });
    try vm.interpret(p0);
    _ = try file_bifs.rename_2(m, &.{ try FinalTerms.binary(&m.ctx, "a.dat"), try FinalTerms.binary(&m.ctx, "b.dat") });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], ok_a)); // rename → ok
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try call.go1(m, &vm, p0, file_bifs.delete_1, try FinalTerms.binary(&m.ctx, "b.dat")), ok_a));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try call.go1(m, &vm, p0, file_bifs.delete_1, try FinalTerms.binary(&m.ctx, "b.dat")), enoent));
}

test "LAW gap-fs-autoloader SPAWN-AUTOLOAD: resolveSpawnMFA loads a spawn target off --code-path (a real-app process TREE births instead of dying undef)" {
    // The M2 fix: a supervised behaviour tree (proc_lib/gen_server/supervisor
    // spawn each other) under `--code-path` was dying `{error,undef}` because
    // resolveSpawnMFA resolved ONLY the child's static exports — a not-yet-loaded
    // spawn target failed CLOSED to `undef` (no dispatch miss, so no autoload).
    // Now it resolves via the child's RUNTIME code too and AUTOLOADS the target on
    // a miss (the process-birth analog of dispatchMFA's ensure_loaded-then-retry).
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const mylists = try atoms.intern("mylists");
    const f_seq = try atoms.intern("seq");

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try prim_file.writeFile(io, tmp.dir, "mylists.beam", @embedFile("mylists.beam"));

    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    vm.autoload = .{ .io = io, .root = tmp.dir, .code_path = &.{"."} };

    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const parent = try vm.spawn(idle, 0, null); // source of the spawn arg terms
    const child = try vm.spawn(idle, 0, null); // the fresh child being born
    const pm = &vm.procs.items[parent].machine;
    const mod_t = FinalTerms.atom(&pm.ctx, mylists);
    const fun_t = FinalTerms.atom(&pm.ctx, f_seq);
    const args = try FinalTerms.cons(&pm.ctx, FinalTerms.int(&pm.ctx, 20), FinalTerms.nil(&pm.ctx));

    // BEFORE: mylists is NOT in the child's code space (a static-export-only
    // resolveSpawnMFA would return null → the caller renders the child dead `undef`).
    try std.testing.expect(vm.procs.items[child].machine.resolveRuntime(mylists, f_seq, 1) == null);
    try std.testing.expect(vm.procs.items[child].machine.resolveExport(mylists, f_seq, 1) == null);

    // resolveSpawnMFA AUTOLOADS mylists.beam into the CHILD and resolves it.
    const pc = vm.resolveSpawnMFA(vm.procs.items[child], pm, mod_t, fun_t, args);
    try std.testing.expect(pc != null); // the child BIRTHS instead of dying undef
    try std.testing.expect(vm.procs.items[child].machine.resolveRuntime(mylists, f_seq, 1) != null); // autoloaded into the child (runtime code)
    // the arg list was cross-heap-copied into the child's x0.
    try std.testing.expect(FinalTerms.eqlExact(&vm.procs.items[child].machine.ctx, vm.procs.items[child].machine.regs[0], FinalTerms.int(&vm.procs.items[child].machine.ctx, 20)));

    // DEFAULT-OFF: with no autoload cfg, the same spawn stays a CLOSED miss (undef).
    var vm2 = try Vm.init(gpa, &atoms);
    defer vm2.deinit();
    _ = try vm2.spawn(idle, 0, null);
    const child2 = try vm2.spawn(idle, 0, null);
    const pm2 = &vm2.procs.items[0].machine;
    const args2 = try FinalTerms.cons(&pm2.ctx, FinalTerms.int(&pm2.ctx, 20), FinalTerms.nil(&pm2.ctx));
    try std.testing.expect(vm2.resolveSpawnMFA(vm2.procs.items[child2], pm2, FinalTerms.atom(&pm2.ctx, mylists), FinalTerms.atom(&pm2.ctx, f_seq), args2) == null);
}

test "LAW gap-fs-autoloader AUTOLOAD≡STATIC-LINK: a dispatchMFA miss loads mylists.beam OFF DISK and denotes the statically-pinned sum(seq(20)); default-off stays undef; a failed load is a ONE-SHOT bounded miss" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const mylists = try atoms.intern("mylists");
    const f_seq = try atoms.intern("seq");
    const f_sum = try atoms.intern("sum");
    // The calling program: sum(seq(20)) through TWO cross-module dispatches into
    // a module that is NOT statically linked — every call must miss and go
    // through the autoload path (the first primes `autoload_tried`+`dyn_exports`,
    // the second proves a LOADED module dispatches via `resolveRuntime` with no
    // second trap).
    const caller: ia.Program = &.{
        .{ .move = .{ .src = .{ .imm = 20 }, .dst = 0 } },
        .{ .call_ext_code = .{ .module = mylists, .func = f_seq, .arity = 1, .push_ret = true } },
        .{ .call_ext_code = .{ .module = mylists, .func = f_sum, .arity = 1, .push_ret = true } },
        .{ .halt = .{ .src = .{ .x = 0 } } },
    };
    const sched: Scheduler = .round_robin;

    // (1) AUTOLOAD≡STATIC-LINK: with mylists.beam ON DISK, the run denotes exactly
    //     the statically-linked pin (sum(seq(20)) == 210 — the M8/E3.12
    //     differential laws' value for this fixture): the load is a pure
    //     representation change, invisible in the denotation.
    {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        try prim_file.writeFile(io, tmp.dir, "mylists.beam", @embedFile("mylists.beam"));
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.autoload = .{ .io = io, .root = tmp.dir, .code_path = &.{"."} };
        const p = try vm.spawn(caller, 0, null);
        try sched.drive(&vm, 50, 100_000);
        const m = &vm.procs.items[p].machine;
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.result, FinalTerms.int(&m.ctx, 210)));
        try std.testing.expect(m.autoloadTried(mylists)); // the trap fired
        try std.testing.expect(m.resolveRuntime(mylists, f_seq, 1) != null); // committed
    }
    // (2) DEFAULT-OFF BYTE-IDENTITY: no autoload config → the very same program
    //     exits `undef` exactly as before the seam existed (opt-in only).
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const p = try vm.spawn(caller, 0, null);
        try sched.drive(&vm, 50, 100_000);
        const m = &vm.procs.items[p].machine;
        try std.testing.expect(!vm.procs.items[p].alive); // undef exit, exactly as pre-seam (E4.1 shape)
        try std.testing.expect(!FinalTerms.eqlExact(&m.ctx, m.result, FinalTerms.int(&m.ctx, 210)));
        try std.testing.expect(!m.autoloadTried(mylists)); // no trap ever armed
    }
    // (3b/e47-a3) DENYLIST: the three natively-served modules are NEVER
    //     autoloaded (a stock error_handler.beam would livelock the undef hook;
    //     logger/error_logger stay the e47-a1 native surface) — and nothing
    //     else is denied (mylists/supervisor load normally).
    try std.testing.expect(Vm.autoloadDenied("error_handler"));
    try std.testing.expect(Vm.autoloadDenied("logger"));
    try std.testing.expect(Vm.autoloadDenied("error_logger"));
    try std.testing.expect(!Vm.autoloadDenied("mylists"));
    try std.testing.expect(!Vm.autoloadDenied("supervisor"));
    {
        // behavioral: a denylisted miss is a BOUNDED undef even with autoload ON
        // and a same-named file present (the file must never be consulted).
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        try prim_file.writeFile(io, tmp.dir, "error_handler.beam", @embedFile("mylists.beam"));
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.autoload = .{ .io = io, .root = tmp.dir, .code_path = &.{"."} };
        const eh = try atoms.intern("error_handler");
        const f_x = try atoms.intern("undefined_function");
        // x0 = 77 sentinel: if the denial DROPPED the retry, execution would
        // fall through to halt(77) — a normal exit with 77 — instead of the
        // undef raise the real path takes. The sentinel makes that observable.
        const deny_prog: ia.Program = &.{
            .{ .move = .{ .src = .{ .imm = 77 }, .dst = 0 } },
            .{ .call_ext_code = .{ .module = eh, .func = f_x, .arity = 0, .push_ret = true } },
            .{ .halt = .{ .src = .{ .x = 0 } } },
        };
        const p = try vm.spawn(deny_prog, 0, null);
        try sched.drive(&vm, 50, 100_000);
        const dm = &vm.procs.items[p].machine;
        try std.testing.expect(!vm.procs.items[p].alive); // undef exit, bounded
        try std.testing.expect(dm.autoloadTried(eh)); // trapped once, denied, done
        try std.testing.expect(dm.resolveRuntime(eh, f_x, 0) == null); // NOT loaded
        try std.testing.expect(!FinalTerms.eqlExact(&dm.ctx, dm.result, FinalTerms.int(&dm.ctx, 77))); // the RETRY ran (undef), not a silent fall-through
    }
    // (3) ONE-SHOT REJECTION: autoload ON over an EMPTY directory — the miss is
    //     TRIED once, the retry falls through to `undef`, and the bounded driver
    //     terminates (a load↔miss loop would hang here = a failed law).
    {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.autoload = .{ .io = io, .root = tmp.dir, .code_path = &.{"."} };
        const p = try vm.spawn(caller, 0, null);
        try sched.drive(&vm, 50, 100_000);
        const m = &vm.procs.items[p].machine;
        try std.testing.expect(!vm.procs.items[p].alive); // fell through to the undef exit
        try std.testing.expect(!FinalTerms.eqlExact(&m.ctx, m.result, FinalTerms.int(&m.ctx, 210)));
        try std.testing.expect(m.autoloadTried(mylists)); // tried exactly once, then undef
    }
}

test "LAW gap-autoload-u32 (DIVERGENCE 679): a module autoloads and denotes correctly when the unified pc space is ABOVE maxInt(u16) — the dynamic-load bound is u32 (the runtime pc width), not the stale u16 beam-label limit that silently killed EVERY autoload once the stdlib preload pushed code_base past 65535" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const mylists = try atoms.intern("mylists");
    const f_seq = try atoms.intern("seq");
    const f_sum = try atoms.intern("sum");
    const caller: ia.Program = &.{
        .{ .move = .{ .src = .{ .imm = 20 }, .dst = 0 } },
        .{ .call_ext_code = .{ .module = mylists, .func = f_seq, .arity = 1, .push_ret = true } },
        .{ .call_ext_code = .{ .module = mylists, .func = f_sum, .arity = 1, .push_ret = true } },
        .{ .halt = .{ .src = .{ .x = 0 } } },
    };
    const sched: Scheduler = .round_robin;
    // A pc BASE beyond maxInt(u16): the real CLI reaches this because the stock
    // stdlib preload alone links ~123k instruction slots. The caller's own pcs
    // (0..3) still fetch the static image (pc < code_base); the autoloaded
    // mylists lands in dyn_code at pc_off == code_base (>= 70000), and the
    // interpreter fetches it via dyn_code[pc - code_base] exactly as at low pc.
    const high_base: usize = 70_000; // > std.math.maxInt(u16) == 65535
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try prim_file.writeFile(io, tmp.dir, "mylists.beam", @embedFile("mylists.beam"));
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    vm.autoload = .{ .io = io, .root = tmp.dir, .code_path = &.{"."} };
    const p = try vm.spawn(caller, 0, null);
    vm.procs.items[p].machine.code_base = high_base; // force the unified pc base high
    try sched.drive(&vm, 50, 200_000);
    const m = &vm.procs.items[p].machine;
    // DENOTATION UNCHANGED: sum(seq(20)) == 210 even though the module loaded far
    // above the old u16 ceiling (the OLD `maxInt(u16)` cap rejected the load with
    // badfile → undef → result != 210; a truncating `pc_off` would land the code
    // at a wrong pc → crash/garbage, also != 210).
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.result, FinalTerms.int(&m.ctx, 210)));
    try std.testing.expect(m.autoloadTried(mylists)); // the trap fired
    // The export committed and its pc is genuinely in the HIGH space (proves the
    // offset was not u16-truncated back under 65536).
    const seq_pc = m.resolveRuntime(mylists, f_seq, 1) orelse return error.TestUnexpectedResult;
    try std.testing.expect(@as(usize, seq_pc) >= high_base);
    try std.testing.expect(seq_pc > std.math.maxInt(u16));
}

test "LAW gap-real-metrics stat-run-queue-real: statistics(run_queue) reports the REAL Vm.liveCount() and tracks schedulable transitions (not the fabricated 0)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    // three fresh processes: all `.running` → schedulable.
    const p0 = try vm.spawn(idle, 0, null);
    _ = try vm.spawn(idle, 0, null);
    _ = try vm.spawn(idle, 0, null);
    const Trap = struct {
        fn q(v: *Vm, pid: Pid) !i64 {
            v.procs.items[pid].machine.pending = .stat_run_queue;
            try v.interpret(pid);
            return FinalTerms.smallValOf(v.procs.items[pid].machine.regs[0]);
        }
    };
    // all three runnable → run_queue == liveCount == 3, NOT the old fabricated 0.
    try std.testing.expectEqual(@as(usize, 3), vm.liveCount());
    try std.testing.expectEqual(@as(i64, 3), try Trap.q(&vm, p0));
    // suspend one → liveCount 2 → run_queue tracks it DOWN (kills a "return total" mutant).
    vm.procs.items[1].machine.status = .suspended;
    try std.testing.expectEqual(@as(usize, 2), vm.liveCount());
    try std.testing.expectEqual(@as(i64, 2), try Trap.q(&vm, p0));
    // resume it → back to 3 (monotone response to the schedulable transition).
    vm.procs.items[1].machine.status = .running;
    try std.testing.expectEqual(@as(i64, 3), try Trap.q(&vm, p0));
}

test "LAW gap-resident-node-smoke: a RESIDENT node runs a SUPERVISED tree — a worker crash is TRAPPED and the node STAYS UP (crash isolation), a restart self-heals it, and root-exit halts cleanly" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // a WORKER blocks in receive forever (bare wait). a SUPERVISOR runs a real
    // message-DRAINING receive loop: consume all mailbox messages (the trapped
    // {'EXIT',_,_} signals), then suspend — so a delivered exit does NOT busy-spin
    // the node (a bare `wait` would, since its lost-wakeup guard keeps it runnable
    // over an un-consumed message).
    const worker: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const supervisor: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 2 } }, // 0: consume oldest msg → x0; empty → 2
        .{ .jump = .{ .to = 0 } }, //                    1: loop (drain the next)
        .{ .wait = .{ .to = 0 } }, //                    2: suspend (empty); resume at 0 on a new signal
    };
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const sched: Scheduler = .round_robin;

    // Boot a supervised tree: a trapping SUPERVISOR linked to a WORKER (the
    // supervisor primitive — process_flag(trap_exit,true) + spawn_link — on the
    // already-EXACT link/exit-signal core).
    const sup = try vm.spawn(supervisor, 0, null);
    const w1 = try vm.spawn(worker, 0, null);
    vm.procs.items[sup].machine.trap_exit = true;
    try vm.procs.items[sup].links.append(gpa, w1);
    try vm.signal(sup, w1, .link_req);
    try vm.drainSignals(w1);

    // (1) the resident node STAYS UP while the tree is idle (2 alive, both blocked).
    try std.testing.expectEqual(@as(usize, 2), vm.aliveCount());
    try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, try sched.driveResident(&vm, 7, 100_000, 4));
    try std.testing.expectEqual(@as(usize, 2), vm.aliveCount());

    // (2) CRASH ISOLATION: the worker crashes abnormally; the trapping supervisor
    //     receives the exit signal and SURVIVES — the node does NOT come down (the
    //     whole point of supervision). aliveCount drops to 1 (the supervisor).
    const boom = FinalTerms.int(&vm.procs.items[w1].machine.ctx, 777);
    try vm.terminate(w1, boom);
    try vm.drainSignals(sup);
    try std.testing.expect(vm.procs.items[sup].alive); // supervisor survived
    try std.testing.expect(!vm.procs.items[w1].alive); // worker died
    try std.testing.expectEqual(@as(usize, 1), vm.aliveCount());
    // the node is STILL RESIDENT (a live supervisor keeps it up), not a deadlock.
    try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, try sched.driveResident(&vm, 7, 100_000, 4));

    // (3) RESTART: the supervisor replaces the worker (spawn_link a fresh one) — the
    //     tree self-heals, aliveCount returns to 2, the node stays resident.
    const w2 = try vm.spawn(worker, 0, null);
    try vm.procs.items[sup].links.append(gpa, w2);
    try vm.signal(sup, w2, .link_req);
    try vm.drainSignals(w2);
    try std.testing.expectEqual(@as(usize, 2), vm.aliveCount());
    try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, try sched.driveResident(&vm, 7, 100_000, 4));

    // (4) ROOT EXIT → CLEAN HALT: when the supervisor (the tree root) exits
    //     abnormally, the linked non-trapping worker is taken down with it and the
    //     node shuts down cleanly (aliveCount==0 → .done), not a spin.
    const shutdown = FinalTerms.int(&vm.procs.items[sup].machine.ctx, 1);
    try vm.terminate(sup, shutdown);
    try vm.drainSignals(w2);
    try std.testing.expectEqual(@as(usize, 0), vm.aliveCount());
    try std.testing.expectEqual(Scheduler.ResidentOutcome.done, try sched.driveResident(&vm, 7, 100_000, 4));
}

test "LAW gap-resident-node-serving: a RESIDENT node SERVES a request/reply BEFORE and AFTER a child crash — the served worker is restarted while the node stays UP (aliveCount preserved across the crash), the request is answered both times, and root-exit halts cleanly (zero leaks)" {
    // The state machine the CTRL-RESIDENT-NODE lifecycle must realise:
    //   boot → serving → child-crash(isolated) → restart → still-serving → shutdown.
    // Distinct from the -smoke law (which proves crash isolation + restart via
    // aliveCount alone): THIS law adds the missing SERVING clause — a real
    // request/reply round-trip is answered BEFORE the crash and AFTER the restart,
    // so "the node stays up" is witnessed by observable service, not just liveness.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // SERVER: a persistent request/reply loop. A request message carries the
    // client's pid; the server replies its OWN pid to it and loops back to wait —
    // it never halts (a resident service), so the node stays UP while it is idle.
    // Replying self() makes each service event DISTINGUISHABLE: a restarted server
    // has a fresh pid, so a reply from the restart is provably a new server.
    const server_prog: ia.Program = &.{
        .{ .loop_rec = .{ .else_to = 5, .dst = 0 } }, // 0: peek request (client pid) → x0
        .remove_message, //                              1: commit the pop
        bifCall(&procsys.self_0, .{ .nil, .nil, .nil }, 0, 1), // 2: x1 = server's own pid
        .{ .send_to = .{ .pid = .{ .x = 0 }, .msg = .{ .x = 1 } } }, // 3: reply self() to client
        .{ .jump = .{ .to = 0 } }, //                    4: loop (drain the next request)
        .{ .wait = .{ .to = 0 } }, //                    5: suspend (empty); resume on a signal
    };
    // SUPERVISOR: a trapping, message-DRAINING loop (consumes trapped
    // {'EXIT',_,_} so a delivered exit does not busy-spin the node).
    const supervisor: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 2 } }, // 0: consume oldest msg → x0; empty → 2
        .{ .jump = .{ .to = 0 } }, //                    1: loop
        .{ .wait = .{ .to = 0 } }, //                    2: suspend (empty)
    };
    // CLIENT: a message-DRAINING loop; the LAST reply received sits in x0 (we read
    // regs[0] to witness the served reply). A draining loop consumes the reply and
    // goes quiescent, so the resident node returns to `.idle` after each serve.
    const client_prog: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 2 } }, // 0: consume reply → x0; empty → 2
        .{ .jump = .{ .to = 0 } }, //                    1: loop
        .{ .wait = .{ .to = 0 } }, //                    2: suspend (empty)
    };

    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const sched: Scheduler = .round_robin;

    // link `child` to the trapping supervisor `sup` (spawn_link on the exact
    // link/exit-signal core): sup traps the child's exit; a sup exit cascades to
    // the child. Establishes the link from sup's side + delivers link_req.
    const linkChild = struct {
        fn f(v: *Vm, g: std.mem.Allocator, sup_: Pid, child: Pid) !void {
            try v.procs.items[sup_].links.append(g, child);
            try v.signal(sup_, child, .link_req);
            try v.drainSignals(child);
        }
    }.f;

    // the pid the client last received a reply FROM (its x0 after draining) — the
    // observable witness that the request was served by the expected server.
    const servedBy = struct {
        fn f(v: *Vm, cl: Pid) ?u64 {
            const m = &v.procs.items[cl].machine;
            if (!FinalTerms.repIsPid(&m.ctx, m.regs[0])) return null;
            return FinalTerms.pidNumber(&m.ctx, m.regs[0]);
        }
    }.f;

    // Boot the supervised, serving tree: sup ↔ server, sup ↔ client.
    const sup = try vm.spawn(supervisor, 0, null);
    const client = try vm.spawn(client_prog, 0, null);
    var server = try vm.spawn(server_prog, 0, null);
    vm.procs.items[sup].machine.trap_exit = true;
    try linkChild(&vm, gpa, sup, server);
    try linkChild(&vm, gpa, sup, client);

    // (1) BOOT → SERVING-IDLE: the resident node STAYS UP while quiescent (3 alive,
    //     all blocked). A resident service at rest is `.idle`, never a deadlock.
    try std.testing.expectEqual(@as(usize, 3), vm.aliveCount());
    try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, try sched.driveResident(&vm, 7, 100_000, 4));
    try std.testing.expectEqual(@as(usize, 3), vm.aliveCount());

    // (2) SERVE #1: the client sends a request (its own pid) to the server; the
    //     resident drive lets the server answer it. The reply lands in the client
    //     mailbox — the node SERVES while resident.
    const req1 = try FinalTerms.pid(&vm.procs.items[server].machine.ctx, client, 0);
    try vm.signal(client, server, .{ .message = req1 });
    try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, try sched.driveResident(&vm, 7, 100_000, 4));
    // served: the client received a reply FROM the running server (pid == server).
    try std.testing.expectEqual(@as(?u64, @intCast(server)), servedBy(&vm, client));

    // (3) CHILD CRASH (ISOLATED): the server crashes abnormally. The trapping
    //     supervisor receives the exit and SURVIVES; the node does NOT come down.
    const boom = FinalTerms.int(&vm.procs.items[server].machine.ctx, 777);
    try vm.terminate(server, boom);
    try vm.drainSignals(sup);
    try std.testing.expect(vm.procs.items[sup].alive); // supervisor survived
    try std.testing.expect(!vm.procs.items[server].alive); // server died
    try std.testing.expect(vm.procs.items[client].alive); // client untouched (not linked to server)
    try std.testing.expectEqual(@as(usize, 2), vm.aliveCount()); // sup + client
    // the node is STILL RESIDENT (a live supervisor + client keep it up).
    try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, try sched.driveResident(&vm, 7, 100_000, 4));

    // (4) RESTART: the supervisor replaces the crashed server (spawn_link a fresh
    //     one) — the tree self-heals, aliveCount returns to 3, node stays resident.
    server = try vm.spawn(server_prog, 0, null);
    try linkChild(&vm, gpa, sup, server);
    try std.testing.expectEqual(@as(usize, 3), vm.aliveCount());

    // (5) STILL SERVING: a SECOND request is answered by the restarted server —
    //     service resumed across the crash (the served count is now 2).
    // reset the client's reply register to nil so serve #2 must deliver a FRESH
    // reply to satisfy the assertion (robust to pid-slot reuse on restart).
    vm.procs.items[client].machine.regs[0] = FinalTerms.nil(&vm.procs.items[client].machine.ctx);
    try std.testing.expectEqual(@as(?u64, null), servedBy(&vm, client)); // cleared
    const req2 = try FinalTerms.pid(&vm.procs.items[server].machine.ctx, client, 0);
    try vm.signal(client, server, .{ .message = req2 });
    try std.testing.expectEqual(Scheduler.ResidentOutcome.idle, try sched.driveResident(&vm, 7, 100_000, 4));
    // served AGAIN, by the RESTARTED server: a fresh reply pid == the new server —
    // service resumed across the crash (a stale/no reply would leave x0 nil).
    try std.testing.expectEqual(@as(?u64, @intCast(server)), servedBy(&vm, client));

    // (6) SHUTDOWN: the supervisor (tree root) exits abnormally; the linked
    //     non-trapping server + client are taken down with it and the node halts
    //     cleanly (aliveCount==0 → .done), not a spin. Zero leaks (testing.allocator).
    const shutdown = FinalTerms.int(&vm.procs.items[sup].machine.ctx, 1);
    try vm.terminate(sup, shutdown);
    try vm.drainSignals(server);
    try vm.drainSignals(client);
    try std.testing.expectEqual(@as(usize, 0), vm.aliveCount());
    try std.testing.expectEqual(Scheduler.ResidentOutcome.done, try sched.driveResident(&vm, 7, 100_000, 4));
}

test "E6.6 DIRTY POOL: dirty-migration homomorphism + conservation + SACRED order across a dirty round-trip" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const cfg = LawConfig{ .seed = 0xD127 };

    // ORACLE: the confluent single-sender ring total (schedule-independent), the
    // homomorphism target denote() must equal WHATEVER pool routes each process.
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;

    // Route several DIFFERENT subsets of the ring through the dirty pools; the
    // total is invariant (dirty is a scheduling hint, never a denotation change)
    // and a process signalled while it sat on the dirty pool still delivers in
    // per-pair order (it migrates back and drains its parked mailbox).
    for ([_]u64{ 0b000010, 0b010101, 0b111110, 0b111111 }) |mask| {
        for ([_]u32{ 1, 2, 3 }) |n| {
            for (0..4) |i| {
                var vm = try Vm.init(gpa, &atoms);
                defer vm.deinit();
                const collector = try seedRing(&vm, 5);
                const eng = SmpEngine{ .n_sched = n, .seed = cfg.seed +% i +% mask };
                const run = try eng.driveModelDirty(&vm, 7, 8000, mask);

                try expectLaw(run.conserved, "dirty: work-stealing conservation across normal+dirty pools", cfg, i);
                const cm = &vm.procs.items[collector].machine;
                try expectLaw(cm.status == .halted, "dirty: bounded completion (the ring finishes through the dirty pool)", cfg, i);
                const total = @as(i64, @bitCast(cm.result)) >> 4;
                try expectLaw(total == oracle, "dirty: dirty-migration homomorphism denote(dirty)==denote(normal)", cfg, @intCast(mask));
                try expectLaw(checkPerPairOrder(vm.events.items), "dirty: SACRED per-pair order across a dirty round-trip", cfg, i);
            }
        }
    }
}

test "Send copies preserve denotation across heaps (cross-cutting copy law)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    var arena = std.heap.ArenaAllocator.init(gpa);
    defer arena.deinit();
    const sa = arena.allocator();
    var prng = std.Random.DefaultPrng.init(0xC0B7);
    const random = prng.random();

    // receiver: loops on recv_any forever
    const recv_prog: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const rx = try vm.spawn(recv_prog, 0, null);

    for (0..40) |_| {
        const sender = try vm.spawn(recv_prog, 0, null);
        const sp = vm.procs.items[sender];
        const payload = try ta.genTerm(FinalTerms, random, &sp.machine.ctx, 3);
        const before = try FinalTerms.denote(&sp.machine.ctx, sa, payload);
        sp.machine.pending = .{ .send_to = .{
            .pid = FinalTerms.int(&sp.machine.ctx, rx),
            .msg = payload,
        } };
        try vm.interpret(sender);
        try vm.drainSignals(rx);
        const rp = vm.procs.items[rx];
        var qbuf: [64]mba.Msg(FinalTerms) = undefined;
        const q = rp.machine.mbox.toSeq(&qbuf);
        const got = q[q.len - 1].payload;
        try std.testing.expect(spec.eqlExact(before, try FinalTerms.denote(&rp.machine.ctx, sa, got)));
    }
}

test "Links: symmetry, exit propagation, trap_exit, normal-exit semantics" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const crasher: ia.Program = &.{
        .{ .exit_proc = .{ .reason = .{ .imm = 777 } } },
    };
    const normal_exit: ia.Program = &.{
        .{ .halt = .{ .src = .{ .imm = 0 } } },
    };

    // (a) untrapped link to a crasher: both die, reason propagates
    {
        const a = try vm.spawn(idle, 0, null);
        const b = try vm.spawn(crasher, 0, null);
        const pa = vm.procs.items[a];
        pa.machine.pending = .{ .link_to = .{ .pid = FinalTerms.int(&pa.machine.ctx, b) } };
        try vm.interpret(a);
        try vm.drainSignals(b); // b records the link
        try std.testing.expect(blk: { // symmetry: both sides hold the link
            var found = false;
            for (vm.procs.items[b].links.items) |l| {
                if (l == a) found = true;
            }
            break :blk found;
        });
        try vm.grant(b, 10); // b exits with 777
        try vm.grant(a, 10); // a drains the exit signal → dies (untrapped)
        try std.testing.expect(!vm.procs.items[a].alive);
    }
    // (b) trapped link: the exit becomes an {'EXIT', From, Reason} message
    {
        const a = try vm.spawn(idle, 0, null);
        const b = try vm.spawn(crasher, 0, null);
        const pa = vm.procs.items[a];
        pa.machine.trap_exit = true;
        pa.machine.pending = .{ .link_to = .{ .pid = FinalTerms.int(&pa.machine.ctx, b) } };
        try vm.interpret(a);
        try vm.drainSignals(b);
        try vm.grant(b, 10);
        try vm.drainSignals(a);
        try std.testing.expect(vm.procs.items[a].alive);
        var qbuf: [8]mba.Msg(FinalTerms) = undefined;
        const q = pa.machine.mbox.toSeq(&qbuf);
        try std.testing.expect(q.len == 1);
        // {'EXIT', b, 777}
        const t = q[0].payload;
        try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&pa.machine.ctx, t));
        try std.testing.expectEqual(@as(usize, 3), FinalTerms.tupleArity(&pa.machine.ctx, t));
        try std.testing.expect(FinalTerms.eqlExact(&pa.machine.ctx, FinalTerms.tupleElem(&pa.machine.ctx, t, 2), FinalTerms.int(&pa.machine.ctx, 777)));
    }
    // (c) normal exit through a link, untrapped: survivor lives
    {
        const a = try vm.spawn(idle, 0, null);
        const b = try vm.spawn(normal_exit, 0, null);
        const pa = vm.procs.items[a];
        pa.machine.pending = .{ .link_to = .{ .pid = FinalTerms.int(&pa.machine.ctx, b) } };
        try vm.interpret(a);
        try vm.drainSignals(b);
        try vm.grant(b, 10); // halts normally
        try vm.grant(a, 10); // drains 'normal' exit signal: ignored
        try std.testing.expect(vm.procs.items[a].alive);
    }
}

test "E4.3 no-kill-cascade: a SYSTEM process absorbs an untrapped abnormal linked exit; a plain process dies; kill overrides" {
    // The kernel bring-up set (Task 3) runs as SYSTEM processes so a supervision-
    // tree crash cannot cascade into it. This law pins the exit-signal handler's
    // `!p.system` guard: a system process survives an untrapped abnormal exit
    // delivered over a link, a plain one does not (the mutant-catching contrast),
    // and an untrappable `kill` stops even a system process.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const crasher: ia.Program = &.{
        .{ .exit_proc = .{ .reason = .{ .imm = 777 } } },
    };

    // (a) SYSTEM process linked to a crasher: absorbs the abnormal exit → survives
    {
        const sys = try vm.spawn(idle, 0, null);
        vm.procs.items[sys].system = true;
        const b = try vm.spawn(crasher, 0, null);
        const ps = vm.procs.items[sys];
        ps.machine.pending = .{ .link_to = .{ .pid = FinalTerms.int(&ps.machine.ctx, b) } };
        try vm.interpret(sys);
        try vm.drainSignals(b);
        try vm.grant(b, 10); // b exits 777, signals sys over the link
        try vm.grant(sys, 10); // sys drains the untrapped abnormal exit: ABSORBED
        try std.testing.expect(vm.procs.items[sys].alive);
    }
    // (b) PLAIN process, identical scenario: dies (no-cascade is system-only)
    {
        const plain = try vm.spawn(idle, 0, null);
        const b = try vm.spawn(crasher, 0, null);
        const pp = vm.procs.items[plain];
        pp.machine.pending = .{ .link_to = .{ .pid = FinalTerms.int(&pp.machine.ctx, b) } };
        try vm.interpret(plain);
        try vm.drainSignals(b);
        try vm.grant(b, 10);
        try vm.grant(plain, 10);
        try std.testing.expect(!vm.procs.items[plain].alive);
    }
    // (c) `kill` is untrappable: it stops even a system process
    {
        const sys = try vm.spawn(idle, 0, null);
        vm.procs.items[sys].system = true;
        const killer = try vm.spawn(idle, 0, null);
        const pk = vm.procs.items[killer];
        pk.machine.pending = .{ .exit_to = .{
            .pid = FinalTerms.int(&pk.machine.ctx, sys),
            .reason = FinalTerms.atom(&pk.machine.ctx, try atoms.intern("kill")),
        } };
        try vm.interpret(killer);
        try vm.drainSignals(sys);
        try std.testing.expect(!vm.procs.items[sys].alive);
    }
}

test "E4.3 spawn_system_process/3: traps spawn_system, flags the child a system process, returns its pid" {
    // The BIF→trap→scheduler path: `spawn_system_process_3` sets `.spawn_system`,
    // the VM creates the child flagged `system=true` and NOT linked to the spawner,
    // and writes its pid to x0. A non-atom module is a synchronous badarg.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const parent = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[parent].machine;
    const m_atom = FinalTerms.atom(&m.ctx, try atoms.intern("some_mod"));
    const f_atom = FinalTerms.atom(&m.ctx, try atoms.intern("start"));

    // badarg: non-atom module (validated before the trap)
    try std.testing.expectError(error.Badarg, procsys.spawn_system_process_3(m, &.{ FinalTerms.int(&m.ctx, 1), f_atom, FinalTerms.nil(&m.ctx) }));
    try std.testing.expect(m.pending == null);

    // valid call sets the trap; the parent is NOT linked to the child
    _ = try procsys.spawn_system_process_3(m, &.{ m_atom, f_atom, FinalTerms.nil(&m.ctx) });
    try std.testing.expect(m.pending != null);
    const before = vm.procs.items.len;
    try vm.interpret(parent);
    try std.testing.expectEqual(before + 1, vm.procs.items.len); // one child created
    const child: Pid = @intCast(before);
    try std.testing.expect(vm.procs.items[child].system); // flagged system
    try std.testing.expectEqual(@as(usize, 0), vm.procs.items[parent].links.items.len); // not linked
    // x0 holds the child's pid (its number == the proc index)
    try std.testing.expect(FinalTerms.repIsPid(&m.ctx, m.regs[0]));
    try std.testing.expectEqual(@as(u64, child), FinalTerms.pidNumber(&m.ctx, m.regs[0]));
}

// CP-6: the VM-level `doPortCommand` handler (proc.zig) — the os-port
// command/control byte-delivery + error arms. E26-T1 laws the os_port `LivePort`
// arms directly, and the port_algebra E4.5/E5.4 laws drive a SEPARATE endpoint
// model; but the Vm's own `doPortCommand` control flow (byte-delivery to the
// owner's mailbox, the empty-data short-circuit, the bad-port badarg arm) is dark
// at the proc-VM level. This law drives `doOpenPort`+`doPortCommand` directly on a
// real `cat` echo child (as E4.3 drives spawn_system_process_3 directly).
// Semantic domain: doPortCommand denotes (owner-mailbox, reply) — a non-empty
// command against a live port delivers EXACTLY ONE byte-conserved
// {Port,{data,Echo}} to the OWNER and returns `true`; an empty command is inert
// (`true`, no delivery); a bad port rejects (`badarg`, no delivery).
test "LAW CP-6 os-port port_command VM handler: byte-delivery to owner mailbox; empty-data inert; bad-port badarg (dark arms over E26-T1)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const parent = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[parent].machine;

    // Open a REAL `cat` echo port owned by the parent.
    const spawn_atom = FinalTerms.atom(&m.ctx, try atoms.intern("spawn"));
    const cmd = try FinalTerms.binary(&m.ctx, "cat");
    const name = try FinalTerms.tuple(&m.ctx, &.{ spawn_atom, cmd });
    // binary_mode=true: this law asserts binary byte-conservation of the echo, so
    // open the port in `binary` mode (default `list` delivers a charlist —
    // gap-open-port-dispatch/DIVERGENCE 594; covered by the compiled differential).
    const port = try vm.doOpenPort(parent, m, name, true, false, 0, false);
    try std.testing.expect(FinalTerms.repIsPort(&m.ctx, port));

    // (arm 1) BYTE-DELIVERY: command "hello" → `true`, and the owner mailbox gains
    // EXACTLY ONE {Port, {data, <<"hello">>}} echo, byte-for-byte.
    const before = m.mbox.len();
    const payload = try FinalTerms.binary(&m.ctx, "hello");
    const r1 = try vm.doPortCommand(parent, m, port, payload);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, r1, FinalTerms.atom(&m.ctx, m.bool_true)));
    try std.testing.expectEqual(before + 1, m.mbox.len());
    const msg = (try m.mbox.peekAt(before)).?;
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, msg.payload, 0), port));
    const inner = FinalTerms.tupleElem(&m.ctx, msg.payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, inner, 0), FinalTerms.atom(&m.ctx, try atoms.intern("data"))));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, inner, 1), payload)); // byte-conserved

    // (arm 2) EMPTY-DATA short-circuit: nothing to echo → `true`, mailbox UNCHANGED
    // (kills a mutant that deletes the `bytes.len == 0` early return).
    const before2 = m.mbox.len();
    const empty = try FinalTerms.binary(&m.ctx, "");
    const r2 = try vm.doPortCommand(parent, m, port, empty);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, r2, FinalTerms.atom(&m.ctx, m.bool_true)));
    try std.testing.expectEqual(before2, m.mbox.len());

    // (arm 3) BAD-PORT error arm: an unknown port number RAISES error:badarg
    // (gap-open-port-dispatch/DIVERGENCE 594 — the port_command/2 contract raises a
    // CATCHABLE error, not a returned atom; the compiled differential's `try ...
    // catch error:badarg` gave `caught_badarg` on OTP-30 but `badarg` before this).
    // Kills a mutant that turns the `portOf orelse error.Badarg` guard into a
    // fallthrough AND one that reverts the raise to a returned atom.
    const before3 = m.mbox.len();
    const bogus = try FinalTerms.port(&m.ctx, 9999);
    try std.testing.expectError(error.Badarg, vm.doPortCommand(parent, m, bogus, payload));
    try std.testing.expectEqual(before3, m.mbox.len());
}

// gap-open-port-exit-status (Slice B, DIVERGENCE 595): the AUTONOMOUS-PRODUCER
// drain. A `{spawn,Cmd}` child that writes output and EXITS on its own delivers
// {Port,{data,Out}} then — IFF the `exit_status` option is armed —
// {Port,{exit_status,Code}}, both to the OWNER's mailbox at open time. Drives
// doOpenPort directly on a real `echo` child (the CP-6 precedent). Semantic domain:
// doOpenPort(producer) denotes (owner-mailbox) = [data] ++ (armed ? [exit_status] : []).
test "LAW gap-open-port-exit-status: autonomous producer delivers {data,_} then (if armed) {exit_status,Code}; unarmed → data only (Slice B)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const parent = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[parent].machine;
    const spawn_atom = FinalTerms.atom(&m.ctx, try atoms.intern("spawn"));
    const data_atom = FinalTerms.atom(&m.ctx, try atoms.intern("data"));
    const es_atom = FinalTerms.atom(&m.ctx, try atoms.intern("exit_status"));

    // (arm 1) ARMED: `echo done` (list mode) → EXACTLY two messages in order:
    // {Port,{data,"done\n"}} then {Port,{exit_status,0}}.
    const echo = try FinalTerms.binary(&m.ctx, "echo done");
    const name1 = try FinalTerms.tuple(&m.ctx, &.{ spawn_atom, echo });
    const before = m.mbox.len();
    const port1 = try vm.doOpenPort(parent, m, name1, false, true, 0, false); // list, exit_status ARMED
    try std.testing.expectEqual(before + 2, m.mbox.len());
    const m1 = (try m.mbox.peekAt(before)).?; // {Port,{data,_}}
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, m1.payload, 0), port1));
    const in1 = FinalTerms.tupleElem(&m.ctx, m1.payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, in1, 0), data_atom));
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.tupleElem(&m.ctx, in1, 1)) == .cons); // charlist (list mode)
    const m2 = (try m.mbox.peekAt(before + 1)).?; // {Port,{exit_status,0}}
    const in2 = FinalTerms.tupleElem(&m.ctx, m2.payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, in2, 0), es_atom));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, in2, 1), FinalTerms.int(&m.ctx, 0)));

    // (arm 2) UNARMED: `echo two` with exit_status=false → the data frame ONLY, NO
    // exit_status message (kills a mutant that delivers exit_status unconditionally).
    const echo2 = try FinalTerms.binary(&m.ctx, "echo two");
    const name2 = try FinalTerms.tuple(&m.ctx, &.{ spawn_atom, echo2 });
    const before2 = m.mbox.len();
    _ = try vm.doOpenPort(parent, m, name2, false, false, 0, false); // exit_status UNARMED
    try std.testing.expectEqual(before2 + 1, m.mbox.len()); // data only
    const m3 = (try m.mbox.peekAt(before2)).?;
    const in3 = FinalTerms.tupleElem(&m.ctx, m3.payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, in3, 0), data_atom));
}

// gap-open-port-line (Slice C, DIVERGENCE 596): the {line,N} port option frames a
// producer's output into {Port,{data,{eol|noeol,Line}}} messages. Drives doOpenPort
// with `printf 'a\nb\n'` at {line,80} directly and asserts TWO {data,{eol,_}} frames
// (the port_algebra.lineFrames VM-integration; the pure framing rule is proven in
// port_algebra's LAW gap-open-port-line).
test "LAW gap-open-port-line: {line,N} producer delivers one {data,{eol|noeol,Line}} per framed line (Slice C)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const parent = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[parent].machine;
    const spawn_atom = FinalTerms.atom(&m.ctx, try atoms.intern("spawn"));
    const data_atom = FinalTerms.atom(&m.ctx, try atoms.intern("data"));
    const eol_atom = FinalTerms.atom(&m.ctx, try atoms.intern("eol"));

    // `printf 'a\nb\n'` at {line,80} (list mode) → exactly two {Port,{data,{eol,L}}}.
    const cmd = try FinalTerms.binary(&m.ctx, "printf 'a\\nb\\n'");
    const name = try FinalTerms.tuple(&m.ctx, &.{ spawn_atom, cmd });
    const before = m.mbox.len();
    const port = try vm.doOpenPort(parent, m, name, false, false, 80, false); // list, line_width=80
    try std.testing.expectEqual(before + 2, m.mbox.len());
    // each message = {Port, {data, {eol, Line}}} — the eol tag + a charlist line.
    for (0..2) |k| {
        const msg = (try m.mbox.peekAt(before + k)).?;
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, msg.payload, 0), port));
        const inner = FinalTerms.tupleElem(&m.ctx, msg.payload, 1);
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, inner, 0), data_atom));
        const tagged = FinalTerms.tupleElem(&m.ctx, inner, 1); // {eol, Line}
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, tagged, 0), eol_atom));
        try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.tupleElem(&m.ctx, tagged, 1)) == .cons); // charlist
    }
}

// gap-open-port-stderr (Slice D, DIVERGENCE 597): the `stderr_to_stdout` option
// merges the child's stderr (fd2) into the port's data stream. Drives doOpenPort on
// `sh -c 'echo out; echo err 1>&2'` with the flag ON (binary mode for a stable byte
// compare) and asserts the delivered data contains BOTH "out" and "err"; with the
// flag OFF, only "out" (stderr goes to the tty, never the port).
test "LAW gap-open-port-stderr: stderr_to_stdout merges fd2 into the port data stream; OFF keeps stderr off the port (Slice D)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const parent = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[parent].machine;
    const spawn_atom = FinalTerms.atom(&m.ctx, try atoms.intern("spawn"));
    const cmd = try FinalTerms.binary(&m.ctx, "sh -c 'echo out; echo err 1>&2'");
    const name = try FinalTerms.tuple(&m.ctx, &.{ spawn_atom, cmd });

    // helper: the first {Port,{data,Binary}} message's bytes for a given stderr flag.
    const H = struct {
        fn firstData(vmp: *Vm, mp: *ia.Machine, nm: FinalTerms.Term, merge: bool, par: Pid) ![]const u8 {
            const before = mp.mbox.len();
            _ = try vmp.doOpenPort(par, mp, nm, true, false, 0, merge); // binary, no es, no line, stderr=merge
            if (mp.mbox.len() == before) return &.{};
            const msg = (try mp.mbox.peekAt(before)).?;
            const inner = FinalTerms.tupleElem(&mp.ctx, msg.payload, 1); // {data, Bin}
            const bin = FinalTerms.tupleElem(&mp.ctx, inner, 1);
            return FinalTerms.binBytes(&mp.ctx, bin);
        }
    };
    // (arm 1) merge ON → the data stream contains BOTH stdout ("out") and stderr ("err").
    const merged = try H.firstData(&vm, m, name, true, parent);
    try std.testing.expect(std.mem.indexOf(u8, merged, "out") != null);
    try std.testing.expect(std.mem.indexOf(u8, merged, "err") != null);
    // (arm 2) merge OFF → "out" reaches the port, "err" does NOT (stderr → tty).
    // Kills a mutant that dups fd2 unconditionally (or never).
    const plain = try H.firstData(&vm, m, name, false, parent);
    try std.testing.expect(std.mem.indexOf(u8, plain, "out") != null);
    try std.testing.expect(std.mem.indexOf(u8, plain, "err") == null);
}

// gap-erl-cli-args (DIVERGENCE 598): the init CLI-argument BIFs. Drives
// doInitPlainArgs + doInitGetArgument DIRECTLY over a hand-built init_args view (NO
// boot path — deterministic, unaffected by the flaky boot-entry non-determinism
// FILED separately as CAST-erl-cli-boot-entry). Semantic domain: get_plain_arguments
// = the plain tokens as strings; get_argument(F) = {ok,[[Vals]…]} for a present
// non-consumed user flag (one inner list per occurrence), else `error`.
test "LAW gap-erl-cli-args: init:get_plain_arguments/0 → plain strings; init:get_argument/1 → {ok,[[Vals]…]} per occurrence | error (missing/consumed)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const p = try vm.spawn(&.{.{ .recv_any = .{ .dst = 0, .else_to = 0 } }}, 0, null);
    const m = &vm.procs.items[p].machine;
    // a hand-built init argv: -myflag a -two x y -dup p -dup q -s mod fn -extra e1 e2
    const two_vals = [_][]const u8{ "x", "y" };
    const flags = [_]Vm.InitArg{
        .{ .name = "myflag", .values = &.{"a"} },
        .{ .name = "two", .values = &two_vals },
        .{ .name = "dup", .values = &.{"p"} },
        .{ .name = "dup", .values = &.{"q"} }, // repeated → two occurrences
        .{ .name = "s", .values = &.{ "mod", "fn" } }, // boot-consumed
    };
    const plain = [_][]const u8{ "e1", "e2" };
    vm.init_args = .{ .flags = &flags, .plain = &plain };
    const errA = FinalTerms.atom(&m.ctx, try atoms.intern("error"));
    const okA = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));
    const A = struct {
        fn atom(mm: *ia.Machine, at: *AtomTable, s: []const u8) FinalTerms.Term {
            return FinalTerms.atom(&mm.ctx, at.intern(s) catch unreachable);
        }
    };

    // (1) get_plain_arguments → a 2-element list of strings ["e1","e2"].
    const pl = try vm.doInitPlainArgs(m);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, pl) == .cons);
    const e1 = FinalTerms.listHead(&m.ctx, pl);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, e1) == .cons); // "e1" is a charlist
    const tail1 = FinalTerms.listTail(&m.ctx, pl);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, tail1) == .cons); // a 2nd element exists
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.listTail(&m.ctx, tail1)) == .nil); // exactly 2

    // (2) get_argument(myflag) → {ok, [["a"]]} (tuple {ok, non-empty outer list}).
    const rf = try vm.doInitGetArgument(m, A.atom(m, &atoms, "myflag"));
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, rf) == .tuple);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, rf, 0), okA));
    const outer = FinalTerms.tupleElem(&m.ctx, rf, 1);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, outer) == .cons); // [["a"]]

    // (3) get_argument(dup) → {ok, [["p"],["q"]]} — TWO occurrences (outer list len 2).
    const rd = try vm.doInitGetArgument(m, A.atom(m, &atoms, "dup"));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, rd, 0), okA));
    const dout = FinalTerms.tupleElem(&m.ctx, rd, 1);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, dout) == .cons);
    const dtail = FinalTerms.listTail(&m.ctx, dout);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, dtail) == .cons); // 2nd occurrence
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.listTail(&m.ctx, dtail)) == .nil); // exactly 2

    // (4) a MISSING flag → error.
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.doInitGetArgument(m, A.atom(m, &atoms, "nope")), errA));
    // (5) a BOOT-CONSUMED flag (present, but `s`) → error (kills a mutant that drops the consumed gate).
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.doInitGetArgument(m, A.atom(m, &atoms, "s")), errA));
    // (6) no init_args at all → get_plain_arguments = [] and get_argument = error.
    vm.init_args = null;
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, try vm.doInitPlainArgs(m)) == .nil);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.doInitGetArgument(m, A.atom(m, &atoms, "myflag")), errA));
}

test "LAW gap-hof-parse: init:get_arguments/0 → [{Flag,[Value…]}…] (argv order, incl consumed flags); [] when no init_args (DIVERGENCE 673)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const p = try vm.spawn(&.{.{ .recv_any = .{ .dst = 0, .else_to = 0 } }}, 0, null);
    const m = &vm.procs.items[p].machine;
    const xy = [_][]const u8{ "x", "y" };
    const flags = [_]Vm.InitArg{
        .{ .name = "myflag", .values = &.{"a"} },
        .{ .name = "two", .values = &xy },
    };
    const plain = [_][]const u8{};
    vm.init_args = .{ .flags = &flags, .plain = &plain };

    // get_arguments → [{myflag,["a"]}, {two,["x","y"]}] — TWO {atom, string-list} pairs.
    const r = try vm.doInitGetArguments(m);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, r) == .cons);
    const p0 = FinalTerms.listHead(&m.ctx, r);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, p0) == .tuple);
    // first pair's flag atom is `myflag`; its value list's head is the "a" charlist.
    const f0 = FinalTerms.tupleElem(&m.ctx, p0, 0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, f0, FinalTerms.atom(&m.ctx, try atoms.intern("myflag"))));
    const v0 = FinalTerms.tupleElem(&m.ctx, p0, 1);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, v0) == .cons); // ["a"]
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.listHead(&m.ctx, v0)) == .cons); // "a" is a charlist
    // exactly two pairs, argv order.
    const tail = FinalTerms.listTail(&m.ctx, r);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, tail) == .cons);
    const p1 = FinalTerms.listHead(&m.ctx, tail);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, p1, 0), FinalTerms.atom(&m.ctx, try atoms.intern("two"))));
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.listTail(&m.ctx, tail)) == .nil);

    // no init_args → [] (not error — the get_arguments contract, distinct from get_argument/1).
    vm.init_args = null;
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, try vm.doInitGetArguments(m)) == .nil);
}

// gap-tracing-trace-info (DIVERGENCE 601): erlang:trace_info({M,F,A},Item) queries the
// global call-trace pattern table; trace_delivered/1 mints a ref + delivers a flush
// message. Drives doTraceInfoMfa + doTraceDelivered directly (deterministic).
test "LAW gap-tracing-trace-info: trace_info({M,F,A},Item) reads the pattern table (traced/match_spec/all); trace_delivered mints a ref + delivers {trace_delivered,_,Ref} (Slice, DIVERGENCE 601)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const p = try vm.spawn(&.{.{ .recv_any = .{ .dst = 0, .else_to = 0 } }}, 0, null);
    const m = &vm.procs.items[p].machine;
    const mod = FinalTerms.atom(&m.ctx, try atoms.intern("mymod"));
    const func = FinalTerms.atom(&m.ctx, try atoms.intern("myfn"));
    const ar = FinalTerms.int(&m.ctx, 2);
    const traced_i = FinalTerms.atom(&m.ctx, try atoms.intern("traced"));
    const ms_i = FinalTerms.atom(&m.ctx, try atoms.intern("match_spec"));
    const global_a = FinalTerms.atom(&m.ctx, try atoms.intern("global"));
    const false_a = FinalTerms.atom(&m.ctx, m.bool_false);
    const snd = struct {
        fn e(mm: *ia.Machine, tup: FinalTerms.Term, i: usize) FinalTerms.Term {
            return FinalTerms.tupleElem(&mm.ctx, tup, i);
        }
    }.e;

    // (1) UNTRACED function: {traced,false}; match_spec {match_spec,false}.
    const r0 = try vm.doTraceInfoMfa(m, mod, func, ar, traced_i);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, snd(m, r0, 1), false_a));
    const ms0 = try vm.doTraceInfoMfa(m, mod, func, ar, ms_i);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, snd(m, ms0, 1), false_a));

    // (2) after enabling a matching pattern: {traced,global}; match_spec {match_spec,[]}.
    try vm.trace_patterns.append(gpa, .{ .module = FinalTerms.atomIdxOf(mod), .func = FinalTerms.atomIdxOf(func), .arity = 2 });
    const r1 = try vm.doTraceInfoMfa(m, mod, func, ar, traced_i);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, snd(m, r1, 1), global_a));
    const ms1 = try vm.doTraceInfoMfa(m, mod, func, ar, ms_i);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, snd(m, ms1, 1)) == .nil); // [] (traced)

    // (3) `all` proplist: a 7-element list, first pair {traced,global}. Kills a mutant
    // that maps match_spec(traced) -> false (the proplist's 2nd pair would be false).
    const allr = try vm.doTraceInfoMfa(m, mod, func, ar, FinalTerms.atom(&m.ctx, try atoms.intern("all")));
    const pl = snd(m, allr, 1);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, pl) == .cons);
    const first = FinalTerms.listHead(&m.ctx, pl);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, snd(m, first, 1), global_a)); // {traced,global}

    // (4) rejection: a non-atom module -> badarg.
    try std.testing.expectError(error.Badarg, vm.doTraceInfoMfa(m, FinalTerms.int(&m.ctx, 1), func, ar, traced_i));

    // (5) trace_delivered: returns a REF + delivers {trace_delivered, all, Ref} to self.
    const before = m.mbox.len();
    const all_atom = FinalTerms.atom(&m.ctx, try atoms.intern("all"));
    const ref = try vm.doTraceDelivered(p, m, all_atom);
    try std.testing.expect(FinalTerms.repIsRef(&m.ctx, ref));
    try std.testing.expectEqual(before + 1, m.mbox.len());
    const dmsg = (try m.mbox.peekAt(before)).?;
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, snd(m, dmsg.payload, 0), FinalTerms.atom(&m.ctx, try atoms.intern("trace_delivered"))));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, snd(m, dmsg.payload, 2), ref)); // the SAME ref
}

// gap-socket-gen-tcp-bifs: the VM execution seam for real gen_tcp sockets. The
// os-port test above proves the VM drives a real CHILD PROCESS through the trap
// mechanism; this proves the same interpret-loop seam drives a real SOCKET —
// doSocketRoundtrip opens a loopback TCP pair (socket_algebra), sends the iodata
// over the actual OS socket, and returns the byte-conserved echo. Semantic
// domain: doSocketRoundtrip denotes the IDENTITY on bytes across a real socket
// (BYTE CONSERVATION), flattens iodata, is empty-inert, and rejects oversize.
test "LAW gap-socket-gen-tcp-bifs: doSocketRoundtrip echoes iodata over a REAL loopback socket (byte-conserved); iodata flattens; empty inert; oversize badarg" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;

    // (arm 1) BYTE CONSERVATION: a binary round-trips over the real socket verbatim.
    const payload = try FinalTerms.binary(&m.ctx, "gen_tcp over a real loopback socket, driven by the VM");
    const echoed = try vm.doSocketRoundtrip(m, payload);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, echoed, payload));

    // (arm 2) IODATA FLATTENING: a deep iolist ["ab",[<<"cd">>,"ef"]] echoes as <<"abcdef">>
    // (kills a mutant that skips iolistToBinary and treats data as a raw binary).
    const s_ab = try FinalTerms.binary(&m.ctx, "ab");
    const s_cd = try FinalTerms.binary(&m.ctx, "cd");
    const s_ef = try FinalTerms.binary(&m.ctx, "ef");
    const inner = try FinalTerms.cons(&m.ctx, s_cd, try FinalTerms.cons(&m.ctx, s_ef, FinalTerms.nil(&m.ctx)));
    const iolist = try FinalTerms.cons(&m.ctx, s_ab, try FinalTerms.cons(&m.ctx, inner, FinalTerms.nil(&m.ctx)));
    const flat = try vm.doSocketRoundtrip(m, iolist);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, flat, try FinalTerms.binary(&m.ctx, "abcdef")));

    // (arm 3) EMPTY inert: empty iodata → empty binary (no socket block on 0 bytes).
    const empty = try vm.doSocketRoundtrip(m, try FinalTerms.binary(&m.ctx, ""));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, empty, try FinalTerms.binary(&m.ctx, "")));

    // (arm 4) OVERSIZE rejection: > 32 KiB fails CLOSED with badarg (bounds the
    // single-threaded send so it can never block — kills a mutant dropping the cap).
    const big = try FinalTerms.binary(&m.ctx, ("x" ** 40000));
    const r = try vm.doSocketRoundtrip(m, big);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, r, FinalTerms.atom(&m.ctx, try atoms.intern("badarg"))));
}

// gap-socket-real-tcp: the whole-VM HANDLE-based gen_tcp lifecycle over REAL
// loopback sockets. Where doSocketRoundtrip (above) proves ONE fused echo, this
// proves the DECOMPOSED gen_tcp API the OTP surface actually exposes —
// listen/inet:port/connect/accept/send/recv/close as separate handler calls that
// carry live socket handles across the Vm table — with `{ok,Socket}`/`{error,Posix}`
// term shapes. Semantic domain: RUNTIME-CAPABILITY-EQUIVALENCE — a client sends
// bytes, the server recv's EXACTLY those bytes and echoes them, the client recv's
// the echo; byte-exact over a real OS socket, not a mock. Every blocking call is
// poll-bounded (a hang on accept/recv is a failed law).
fn sockUnwrapOk(m: *ia.Machine, t: FinalTerms.Term, atoms: *AtomTable) !FinalTerms.Term {
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, t) == .tuple);
    try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&m.ctx, t));
    const ok = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, t, 0), ok));
    return FinalTerms.tupleElem(&m.ctx, t, 1);
}

test "LAW gap-socket-real-tcp PORT-FROM-OPTS: gen_tcp:listen reads {port,N} from the Opts list (ranch's convention: listen(0, [{port,N}|_]))" {
    // RCA-class fix: gen_tcp/inet options carried in the Opts LIST were dropped —
    // ranch calls gen_tcp:listen(0, [{port,N}|Opts]) (the opts port takes precedence
    // over arg-0), so binding arg-0 alone bound an EPHEMERAL port and the listener
    // never served the requested one. portFromOpts extracts it.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const a_port = FinalTerms.atom(&m.ctx, try atoms.intern("port"));
    const a_active = FinalTerms.atom(&m.ctx, try atoms.intern("active"));
    const mk = struct {
        fn tup(mm: *ia.Machine, k: FinalTerms.Term, v: FinalTerms.Term) !FinalTerms.Term {
            return FinalTerms.tuple(&mm.ctx, &.{ k, v });
        }
    };

    // Opts = [{active,false}, {port,18261}, {backlog,1024}] — the port buried mid-list.
    const nil = FinalTerms.nil(&m.ctx);
    const t_backlog = try mk.tup(m, FinalTerms.atom(&m.ctx, try atoms.intern("backlog")), FinalTerms.int(&m.ctx, 1024));
    const t_port = try mk.tup(m, a_port, FinalTerms.int(&m.ctx, 18261));
    const t_active = try mk.tup(m, a_active, FinalTerms.atom(&m.ctx, m.bool_false));
    const opts = try FinalTerms.cons(&m.ctx, t_active, try FinalTerms.cons(&m.ctx, t_port, try FinalTerms.cons(&m.ctx, t_backlog, nil)));

    try std.testing.expectEqual(@as(?u16, 18261), Vm.portFromOpts(m, opts)); // extracted, not the {active,_}/{backlog,_}
    try std.testing.expectEqual(@as(?u16, null), Vm.portFromOpts(m, nil)); // absent → null (arg-0 stands)
    try std.testing.expectEqual(@as(?u16, null), Vm.portFromOpts(m, try FinalTerms.cons(&m.ctx, t_active, nil))); // no {port,_} → null
}

test "LAW gap-app-boot-engine: code:ensure_loaded autoloads a module, function_exported then SEES it (runtime-aware), inet:sockname renders the endpoint, application:get_env is unset-safe" {
    // The stock-app boot intercepts (unblocking real ranch/cowboy): code:ensure_loaded
    // must ACTUALLY load a --code-path module (not route to the unbooted code_server),
    // and the following erlang:function_exported must SEE that runtime-loaded module
    // (ranch checks its transport this way). inet:sockname renders the bound endpoint;
    // application:get_env is unset-safe (no application_controller needed).
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const mylists = try atoms.intern("mylists");
    const f_seq = try atoms.intern("seq");

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try prim_file.writeFile(io, tmp.dir, "mylists.beam", @embedFile("mylists.beam"));
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    vm.autoload = .{ .io = io, .root = tmp.dir, .code_path = &.{"."} };
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const seq_t = FinalTerms.atom(&m.ctx, f_seq);
    const mod_t = FinalTerms.atom(&m.ctx, mylists);
    const one = FinalTerms.int(&m.ctx, 1);

    // BEFORE ensure_loaded: mylists is not loaded → function_exported is FALSE.
    try std.testing.expectEqual(m.bool_false, FinalTerms.atomIdxOf(try fun_info_bifs.function_exported_3(m, &.{ mod_t, seq_t, one })));

    // code:ensure_loaded(mylists) TRAPS → the Vm autoloads it → {module, mylists}.
    _ = try application_bifs.code_ensure_loaded_1(m, &.{mod_t});
    try std.testing.expect(m.pending != null);
    try vm.interpret(p0);
    const el = m.regs[0];
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, el, 0), FinalTerms.atom(&m.ctx, try atoms.intern("module"))));

    // AFTER: function_exported now SEES the runtime-loaded module (the dyn-aware fix).
    try std.testing.expectEqual(m.bool_true, FinalTerms.atomIdxOf(try fun_info_bifs.function_exported_3(m, &.{ mod_t, seq_t, one })));

    // inet:sockname(ListenSocket) → {ok, {{0,0,0,0}, Port}} via the trap.
    _ = try socket_bifs.gen_tcp_listen_2(m, &.{ FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx) });
    try vm.interpret(p0);
    const lsock = try sockUnwrapOk(m, m.regs[0], &atoms);
    _ = try socket_bifs.inet_sockname_1(m, &.{lsock});
    try vm.interpret(p0);
    const nm = try sockUnwrapOk(m, m.regs[0], &atoms); // {Addr, Port}
    try std.testing.expect(FinalTerms.tupleArity(&m.ctx, nm) == 2);
    try std.testing.expect(FinalTerms.smallValOf(FinalTerms.tupleElem(&m.ctx, nm, 1)) > 0); // real port

    // ranch socket API surface: setopts/controlling_process accepted (ok); peername → endpoint.
    const a_ok = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));
    _ = try socket_bifs.inet_setopts_2(m, &.{ lsock, FinalTerms.nil(&m.ctx) }); // setopts is a trap (active-mode)
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], a_ok));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try socket_bifs.gen_tcp_controlling_process_2(m, &.{ lsock, FinalTerms.int(&m.ctx, 0) }), a_ok));
    _ = try socket_bifs.inet_peername_1(m, &.{lsock});
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.tupleArity(&m.ctx, try sockUnwrapOk(m, m.regs[0], &atoms)) == 2); // {Addr,Port}

    _ = try socket_bifs.gen_tcp_close_1(m, &.{lsock});
    try vm.interpret(p0);

    // application:get_env — unset-safe (no application_controller): /1,/2 undefined, /3 default.
    const a_undef = FinalTerms.atom(&m.ctx, try atoms.intern("undefined"));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try application_bifs.get_env_1(m, &.{seq_t}), a_undef));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try application_bifs.get_env_2(m, &.{ mod_t, seq_t }), a_undef));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try application_bifs.get_env_3(m, &.{ mod_t, seq_t, one }), one)); // default
}

test "LAW gap-socket-active-mode: an armed {active,once} socket delivers {tcp,Socket,Data} via the SCHEDULER poll (not a synchronous BIF); once self-clears" {
    // cowboy_http's request loop: inet:setopts {active,once} → receive {tcp,S,Data}.
    // The fix is REACTOR-shaped: setopts only ARMS (non-blocking, records owner); the
    // scheduler's pollActiveSockets does the non-blocking read + delivery. A first
    // cut that recv'd synchronously in setopts regressed the boot (DIVERGENCE 580).
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const nil = FinalTerms.nil(&m.ctx);
    const a_ok = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));

    // Server: listen + accept a real client that has already sent "PING".
    _ = try socket_bifs.gen_tcp_listen_2(m, &.{ FinalTerms.int(&m.ctx, 0), nil });
    try vm.interpret(p0);
    const lsock = try sockUnwrapOk(m, m.regs[0], &atoms);
    _ = try socket_bifs.inet_port_1(m, &.{lsock});
    try vm.interpret(p0);
    const port: u16 = @intCast(FinalTerms.smallValOf(try sockUnwrapOk(m, m.regs[0], &atoms)));
    const cfd = try socket_algebra.connectPort(port);
    defer socket_algebra.close(cfd);
    try socket_algebra.send(cfd, "PING");
    _ = try socket_bifs.gen_tcp_accept_1(m, &.{lsock});
    try vm.interpret(p0);
    const ssock = try sockUnwrapOk(m, m.regs[0], &atoms);

    // BEFORE arming: the poll delivers NOTHING (the socket is passive).
    try vm.pollActiveSockets();
    try vm.drainSignals(p0);
    try std.testing.expectEqual(@as(usize, 0), m.mbox.len());

    // inet:setopts(SSock, [{active, once}]) — ARMS it (non-blocking; owner=p0, returns ok).
    const a_active = FinalTerms.atom(&m.ctx, try atoms.intern("active"));
    const a_once = FinalTerms.atom(&m.ctx, try atoms.intern("once"));
    const opt = try FinalTerms.tuple(&m.ctx, &.{ a_active, a_once });
    _ = try socket_bifs.inet_setopts_2(m, &.{ ssock, try FinalTerms.cons(&m.ctx, opt, nil) });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], a_ok)); // non-blocking ok

    // The SCHEDULER poll delivers {tcp, SSock, <<"PING">>} to p0's mailbox.
    try vm.pollActiveSockets();
    try vm.drainSignals(p0);
    try std.testing.expectEqual(@as(usize, 1), m.mbox.len());
    const msg = (try m.mbox.peekAt(0)).?.payload;
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, msg) == .tuple and FinalTerms.tupleArity(&m.ctx, msg) == 3);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, msg, 0), FinalTerms.atom(&m.ctx, try atoms.intern("tcp")))); // {tcp,_,_}
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, msg, 2), try FinalTerms.binary(&m.ctx, "PING"))); // byte-exact payload

    // {active,once} self-cleared: a further poll delivers nothing more.
    try vm.pollActiveSockets();
    try vm.drainSignals(p0);
    try std.testing.expectEqual(@as(usize, 1), m.mbox.len());

    _ = try socket_bifs.gen_tcp_close_1(m, &.{ssock});
    try vm.interpret(p0);
    _ = try socket_bifs.gen_tcp_close_1(m, &.{lsock});
    try vm.interpret(p0);
}

test "LAW gap-socket-real-tcp M1: a gen_tcp + decode_packet server returns a byte-correct HTTP/1.1 200 OK to a REAL client over a real socket" {
    // M1 (the 'it is a real node' proof): the SERVER runs the gen_tcp lifecycle
    // through the NAME-DISPATCH traps (as compiled erlang would), a REAL separate
    // client fd (curl's stand-in — a genuine second TCP endpoint) connects to the
    // server's ephemeral port and sends a real HTTP/1.1 request, the server parses
    // it with the (already-EQ) `decode_packet/3` HTTP decoder and sends back a
    // byte-correct `HTTP/1.1 200 OK`, and the client reads it verbatim. gen_tcp +
    // decode_packet, end-to-end, over the real kernel TCP stack.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const nil = FinalTerms.nil(&m.ctx);

    // SERVER: gen_tcp:listen(0,[]) → LSock; inet:port(LSock) → the real port.
    _ = try socket_bifs.gen_tcp_listen_2(m, &.{ FinalTerms.int(&m.ctx, 0), nil });
    try vm.interpret(p0);
    const lsock = try sockUnwrapOk(m, m.regs[0], &atoms);
    _ = try socket_bifs.inet_port_1(m, &.{lsock});
    try vm.interpret(p0);
    const port: u16 = @intCast(FinalTerms.smallValOf(try sockUnwrapOk(m, m.regs[0], &atoms)));

    // CLIENT (a real, separate TCP endpoint): connect to the server's port and send
    // a real HTTP/1.1 GET. On loopback connect completes into the listen backlog.
    const cfd = try socket_algebra.connectPort(port);
    defer socket_algebra.close(cfd);
    const request = "GET / HTTP/1.1\r\nHost: localhost\r\n\r\n";
    try socket_algebra.send(cfd, request);

    // SERVER: accept → recv the request bytes (through the traps).
    _ = try socket_bifs.gen_tcp_accept_1(m, &.{lsock});
    try vm.interpret(p0);
    const ssock = try sockUnwrapOk(m, m.regs[0], &atoms);
    _ = try socket_bifs.gen_tcp_recv_2(m, &.{ ssock, FinalTerms.int(&m.ctx, @intCast(request.len)) });
    try vm.interpret(p0);
    const req_bin = try sockUnwrapOk(m, m.regs[0], &atoms);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, req_bin) == .binary);

    // SERVER: decode_packet(http, Request, []) → {ok, {http_request,'GET',Uri,{1,1}}, _}.
    const http_atom = FinalTerms.atom(&m.ctx, try atoms.intern("http"));
    const dp = try erlang_bifs.decode_packet_3(m, &.{ http_atom, req_bin, nil });
    try std.testing.expect(FinalTerms.tupleArity(&m.ctx, dp) == 3);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, dp, 0), FinalTerms.atom(&m.ctx, try atoms.intern("ok"))));
    const packet = FinalTerms.tupleElem(&m.ctx, dp, 1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, packet, 0), FinalTerms.atom(&m.ctx, try atoms.intern("http_request"))));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, packet, 1), FinalTerms.atom(&m.ctx, try atoms.intern("GET")))); // parsed a real GET request line

    // SERVER: gen_tcp:send(SSock, <the 200 response>) → ok.
    const response = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nhi";
    _ = try socket_bifs.gen_tcp_send_2(m, &.{ ssock, try FinalTerms.binary(&m.ctx, response) });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], FinalTerms.atom(&m.ctx, try atoms.intern("ok"))));

    // CLIENT: read the response — a REAL HTTP 200 over a real socket.
    var buf: [256]u8 = undefined;
    const n = try socket_algebra.recv(cfd, &buf);
    try std.testing.expect(std.mem.startsWith(u8, buf[0..n], "HTTP/1.1 200 OK")); // M1: 200 OK
    try std.testing.expect(std.mem.endsWith(u8, buf[0..n], "hi")); // body delivered verbatim

    for ([_]FinalTerms.Term{ ssock, lsock }) |sock| {
        _ = try socket_bifs.gen_tcp_close_1(m, &.{sock});
        try vm.interpret(p0);
    }
}

test "LAW gap-socket-real-tcp DISPATCH: compiled gen_tcp:listen/inet:port/gen_tcp:close reach the handlers via the socket_op trap" {
    // The EQ-remainder mechanism: a COMPILED erlang `gen_tcp:listen(0,[])` resolves
    // (dispatch.resolveLibrary) to `socket.gen_tcp_listen_2`, which sets the
    // `socket_op` pending; the Vm `interpret` loop routes it to `doGenTcpListen`
    // (real fd + socket table) and overwrites x0 with `{ok, ListenSocket}`. This
    // law drives that exact bif→pending→interpret→handler path (no direct handler
    // call), then `inet:port` (→ a real ephemeral port) and `gen_tcp:close` (→ ok).
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const nil = FinalTerms.nil(&m.ctx);

    // gen_tcp:listen(0, []) — the BIF sets the pending; interpret routes to the handler.
    _ = try socket_bifs.gen_tcp_listen_2(m, &.{ FinalTerms.int(&m.ctx, 0), nil });
    try std.testing.expect(m.pending != null); // the bif EMITTED the socket_op trap
    try vm.interpret(p0); // the Vm routes socket_op → doGenTcpListen → x0
    try std.testing.expect(m.pending == null); // trap consumed
    const lsock = try sockUnwrapOk(m, m.regs[0], &atoms); // {ok, ListenSocket}
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, lsock) == .tuple); // {'$socket',N}

    // inet:port(ListenSocket) — a REAL ephemeral port (non-zero), through the trap.
    _ = try socket_bifs.inet_port_1(m, &.{lsock});
    try vm.interpret(p0);
    const port_t = try sockUnwrapOk(m, m.regs[0], &atoms); // {ok, Port}
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, port_t) == .number);
    try std.testing.expect(FinalTerms.smallValOf(port_t) > 0); // OTP: bind(0) → non-zero ephemeral

    const a_ok = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));

    // Wave 2 — the full echo lifecycle through the traps: connect → accept → send
    // → recv. On loopback the kernel completes the handshake at connect() time, so
    // a single process can connect then accept (the socket_algebra contract).
    const a_addr = FinalTerms.atom(&m.ctx, try atoms.intern("loopback"));
    _ = try socket_bifs.gen_tcp_connect_3(m, &.{ a_addr, port_t, nil });
    try vm.interpret(p0);
    const csock = try sockUnwrapOk(m, m.regs[0], &atoms); // client {ok, Socket}

    _ = try socket_bifs.gen_tcp_accept_1(m, &.{lsock});
    try vm.interpret(p0);
    const ssock = try sockUnwrapOk(m, m.regs[0], &atoms); // server {ok, Socket}

    const payload = try FinalTerms.binary(&m.ctx, "hi-http");
    _ = try socket_bifs.gen_tcp_send_2(m, &.{ csock, payload });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], a_ok)); // send → ok

    _ = try socket_bifs.gen_tcp_recv_2(m, &.{ ssock, FinalTerms.int(&m.ctx, 7) });
    try vm.interpret(p0);
    const got = try sockUnwrapOk(m, m.regs[0], &atoms); // {ok, <<"hi-http">>}
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, got) == .binary);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, got, payload)); // byte-exact echo through the trap

    // gen_tcp:close(each) → ok, through the trap.
    for ([_]FinalTerms.Term{ csock, ssock, lsock }) |sock| {
        _ = try socket_bifs.gen_tcp_close_1(m, &.{sock});
        try vm.interpret(p0);
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], a_ok)); // bare `ok`
    }
}

test "LAW gap-socket-udp-dispatch: compiled gen_udp:open/send/recv/close reach the handlers via the socket_op trap (byte-exact datagram)" {
    // The UDP half of the `gen_tcp_udp_sockets` capability, through the SAME
    // bif→pending→interpret→handler path a COMPILED erlang `gen_udp:*` call takes
    // (no direct handler call): gen_udp:open (→ a real udp fd), inet:port (→ real
    // ephemeral), gen_udp:send/4 (Socket,Addr,Port,Data — the Data rides the
    // pending's third slot, the new arg3), gen_udp:recv (→ {ok,{A,P,Pkt}}),
    // gen_udp:close (→ ok). Proves the name-dispatch surface is COMPLETE for UDP —
    // the EQ-admission mechanism for the datagram transport.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const zero = FinalTerms.int(&m.ctx, 0);
    const nil = FinalTerms.nil(&m.ctx);
    const a_ok = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));

    // gen_udp:open(0, []) → {ok, RxSocket}, through the trap.
    _ = try socket_bifs.gen_udp_open_2(m, &.{ zero, nil });
    try std.testing.expect(m.pending != null); // the bif EMITTED the socket_op trap
    try vm.interpret(p0);
    try std.testing.expect(m.pending == null); // trap consumed
    const rx = try sockUnwrapOk(m, m.regs[0], &atoms);

    // inet:port(Rx) → a real ephemeral port (non-zero), through the trap.
    _ = try socket_bifs.inet_port_1(m, &.{rx});
    try vm.interpret(p0);
    const rx_port = try sockUnwrapOk(m, m.regs[0], &atoms);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, rx_port) == .number);
    try std.testing.expect(FinalTerms.smallValOf(rx_port) > 0);

    // gen_udp:open(0) → {ok, TxSocket} (open/1 arity).
    _ = try socket_bifs.gen_udp_open_1(m, &.{zero});
    try vm.interpret(p0);
    const tx = try sockUnwrapOk(m, m.regs[0], &atoms);

    // gen_udp:send(Tx, loopback, RxPort, Data) → ok. Data rides arg3.
    const a_addr = FinalTerms.atom(&m.ctx, try atoms.intern("loopback"));
    const dg = try FinalTerms.binary(&m.ctx, "datagram-through-the-dispatch-trap");
    _ = try socket_bifs.gen_udp_send_4(m, &.{ tx, a_addr, rx_port, dg });
    try vm.interpret(p0);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], a_ok)); // send → ok

    // gen_udp:recv(Rx, 0) → {ok, {Addr, Port, Packet}}; Packet BYTE-EXACT through arg3.
    _ = try socket_bifs.gen_udp_recv_2(m, &.{ rx, zero });
    try vm.interpret(p0);
    const ures = try sockUnwrapOk(m, m.regs[0], &atoms);
    try std.testing.expectEqual(@as(usize, 3), FinalTerms.tupleArity(&m.ctx, ures));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, ures, 2), dg));

    // gen_udp:close(each) → ok, through the shared close trap.
    for ([_]FinalTerms.Term{ tx, rx }) |sock| {
        _ = try socket_bifs.gen_tcp_close_1(m, &.{sock});
        try vm.interpret(p0);
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], a_ok));
    }
}

test "LAW gap-socket-real-tcp: gen_tcp listen/connect/accept/send/recv/close ECHO round-trips over a REAL loopback socket; error shapes match OTP" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;

    // (ARM 1) ROUND-TRIP over the decomposed lifecycle, for several seeded payloads.
    // A seeded PRNG drives payload bytes+lengths so the byte-exactness is not a
    // single fixed string; the seed is echoed on failure by std.testing.
    const seed: u64 = 0xBEE5_0C1E;
    var trial: usize = 0;
    while (trial < 4) : (trial += 1) {
        var prng = std.Random.DefaultPrng.init(seed +% trial);
        const rnd = prng.random();
        const len: usize = 1 + rnd.uintLessThan(usize, 200);
        const payload = try gpa.alloc(u8, len);
        defer gpa.free(payload);
        rnd.bytes(payload);

        // gen_tcp:listen(0, _) → {ok, LSock}
        const lres = try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx));
        const lsock = try sockUnwrapOk(m, lres, &atoms);
        // inet:port(LSock) → {ok, Port}
        const pres = try vm.doInetPort(m, lsock);
        const port_term = try sockUnwrapOk(m, pres, &atoms);
        try std.testing.expect(FinalTerms.smallValOf(port_term) != 0);
        // gen_tcp:connect(loopback, Port, _) → {ok, CSock} (connect BEFORE accept)
        const cres = try vm.doGenTcpConnect(m, port_term);
        const csock = try sockUnwrapOk(m, cres, &atoms);
        // gen_tcp:accept(LSock) → {ok, SSock} (bounded; client already connected)
        const ares = try vm.doGenTcpAccept(0, m, lsock, FinalTerms.int(&m.ctx, 200));
        const ssock = try sockUnwrapOk(m, ares, &atoms);

        // client sends → server recv's EXACTLY those bytes
        const data = try FinalTerms.binary(&m.ctx, payload);
        const sres = try vm.doGenTcpSend(m, csock, data);
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, sres, FinalTerms.atom(&m.ctx, try atoms.intern("ok"))));
        const rres = try vm.doGenTcpRecv(m, ssock, FinalTerms.int(&m.ctx, @intCast(len)));
        const got = try sockUnwrapOk(m, rres, &atoms);
        try std.testing.expectEqualSlices(u8, payload, FinalTerms.binBytes(&m.ctx, got));

        // server echoes → client recv's the echo (both directions byte-exact)
        _ = try vm.doGenTcpSend(m, ssock, got);
        const eres = try vm.doGenTcpRecv(m, csock, FinalTerms.int(&m.ctx, @intCast(len)));
        const echoed = try sockUnwrapOk(m, eres, &atoms);
        try std.testing.expectEqualSlices(u8, payload, FinalTerms.binBytes(&m.ctx, echoed));

        // close everything (idempotent ok)
        _ = try vm.doGenTcpClose(m, csock);
        _ = try vm.doGenTcpClose(m, ssock);
        _ = try vm.doGenTcpClose(m, lsock);
    }

    // (ARM 2) ERROR SHAPE — recv on a CLOSED socket → {error, closed}, never a crash.
    const l2 = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const p2 = try sockUnwrapOk(m, try vm.doInetPort(m, l2), &atoms);
    const c2 = try sockUnwrapOk(m, try vm.doGenTcpConnect(m, p2), &atoms);
    const s2 = try sockUnwrapOk(m, try vm.doGenTcpAccept(0, m, l2, FinalTerms.int(&m.ctx, 200)), &atoms);
    _ = try vm.doGenTcpClose(m, s2); // close the server side
    const closed_recv = try vm.doGenTcpRecv(m, s2, FinalTerms.int(&m.ctx, 4));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, closed_recv, try vm.errTuple(m, "closed")));
    _ = try vm.doGenTcpClose(m, c2);
    _ = try vm.doGenTcpClose(m, l2);

    // (ARM 3) ERROR SHAPE — connect to a port nobody listens on → {error, econnrefused}.
    const l3 = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const p3 = try sockUnwrapOk(m, try vm.doInetPort(m, l3), &atoms);
    _ = try vm.doGenTcpClose(m, l3); // now nothing listens on p3
    const refused = try vm.doGenTcpConnect(m, p3);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, refused, try vm.errTuple(m, "econnrefused")));

    // (ARM 4) BOUNDED accept — accept on an idle listener → {error, timeout}, no hang.
    const l4 = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const idle_accept = try vm.doGenTcpAccept(0, m, l4, FinalTerms.int(&m.ctx, 200));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, idle_accept, try vm.errTuple(m, "timeout")));
    _ = try vm.doGenTcpClose(m, l4);

    // (ARM 5) gen_udp datagram round-trips: open two endpoints, send → recv {ok,{Addr,Port,Data}}.
    const u_rx = try sockUnwrapOk(m, try vm.doGenUdpOpen(m), &atoms);
    const u_rx_port = try sockUnwrapOk(m, try vm.doInetPort(m, u_rx), &atoms);
    const u_tx = try sockUnwrapOk(m, try vm.doGenUdpOpen(m), &atoms);
    const dg = try FinalTerms.binary(&m.ctx, "a udp datagram through the VM handle surface");
    _ = try vm.doGenUdpSend(m, u_tx, u_rx_port, dg);
    const ures = try sockUnwrapOk(m, try vm.doGenUdpRecv(m, u_rx), &atoms);
    // triple = {Addr, Port, Packet}; assert the Packet is byte-exact
    try std.testing.expectEqual(@as(usize, 3), FinalTerms.tupleArity(&m.ctx, ures));
    const pkt = FinalTerms.tupleElem(&m.ctx, ures, 2);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, pkt, dg));
    _ = try vm.doGenTcpClose(m, u_tx); // close is uniform across tcp/udp handles
    _ = try vm.doGenTcpClose(m, u_rx);
}

test "LAW gap-socket-gen-tcp-bifs SHUTDOWN: gen_tcp:shutdown(Socket, write) sends the peer an orderly EOF AFTER its buffered data drains (real half-close); read/read_write → ok; a bad How → the badarg atom; a closed socket → {error,closed}; the compiled gen_tcp:shutdown/2 reaches the handler (dispatch-reachability)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const ok = FinalTerms.atom(&m.ctx, try atoms.intern("ok"));

    // Bring up a real connected loopback pair: listen → connect → accept.
    const lsock = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const port = try sockUnwrapOk(m, try vm.doInetPort(m, lsock), &atoms);
    const csock = try sockUnwrapOk(m, try vm.doGenTcpConnect(m, port), &atoms);
    const ssock = try sockUnwrapOk(m, try vm.doGenTcpAccept(0, m, lsock, FinalTerms.int(&m.ctx, 200)), &atoms);

    // (1) HALF-CLOSE EOF: the client sends P, then shutdown(write). The server MUST
    // still drain P (buffered data survives the half-close), and only THEN see EOF.
    const payload = "graceful-half-close-payload-9876";
    _ = try vm.doGenTcpSend(m, csock, try FinalTerms.binary(&m.ctx, payload));
    const shut = try vm.doGenTcpShutdown(m, csock, FinalTerms.atom(&m.ctx, try atoms.intern("write")));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, shut, ok)); // shutdown(write) → ok
    // server drains the buffered payload (orderly — NOT lost by the shutdown)
    const drained = try sockUnwrapOk(m, try vm.doGenTcpRecv(m, ssock, FinalTerms.int(&m.ctx, @intCast(payload.len))), &atoms);
    try std.testing.expectEqualSlices(u8, payload, FinalTerms.binBytes(&m.ctx, drained));
    // the NEXT recv sees the orderly EOF the half-close delivered → {error,closed}
    const eof = try vm.doGenTcpRecv(m, ssock, FinalTerms.int(&m.ctx, 1));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, eof, try vm.errTuple(m, "closed")));

    // (2) read / read_write are also accepted (ok) — every valid How lands.
    const shut_r = try vm.doGenTcpShutdown(m, ssock, FinalTerms.atom(&m.ctx, try atoms.intern("read")));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, shut_r, ok));
    const shut_rw = try vm.doGenTcpShutdown(m, ssock, FinalTerms.atom(&m.ctx, try atoms.intern("read_write")));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, shut_rw, ok));

    // (3) a bad How is REJECTED as the `badarg` atom (the socket surface's uniform
    // arg-rejection convention, cf. doGenTcpRecv's bad-length) — never a silent ok.
    const bad_reason = FinalTerms.atom(&m.ctx, try atoms.intern("banana"));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.doGenTcpShutdown(m, ssock, bad_reason), FinalTerms.atom(&m.ctx, try atoms.intern("badarg"))));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.doGenTcpShutdown(m, ssock, FinalTerms.int(&m.ctx, 3)), FinalTerms.atom(&m.ctx, try atoms.intern("badarg"))));

    _ = try vm.doGenTcpClose(m, csock);
    _ = try vm.doGenTcpClose(m, ssock);
    _ = try vm.doGenTcpClose(m, lsock);

    // (4) a shutdown of an ALREADY-CLOSED socket → {error,closed}, never a crash.
    const gone = try vm.doGenTcpShutdown(m, csock, FinalTerms.atom(&m.ctx, try atoms.intern("write")));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, gone, try vm.errTuple(m, "closed")));

    // (5) DISPATCH-REACHABILITY: the compiled gen_tcp:shutdown/2 BifFn EMITS the
    // socket_op trap and the Vm routes it to the handler (not undef) — the standing
    // FM-DISPATCH-DEAD guard, proven through the real BifFn + interpret path.
    const l5 = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const p5 = try sockUnwrapOk(m, try vm.doInetPort(m, l5), &atoms);
    const c5 = try sockUnwrapOk(m, try vm.doGenTcpConnect(m, p5), &atoms);
    _ = try socket_bifs.gen_tcp_shutdown_2(m, &.{ c5, FinalTerms.atom(&m.ctx, try atoms.intern("write")) });
    try std.testing.expect(m.pending != null); // the BifFn emitted the socket_op trap
    try vm.interpret(p0); // the Vm routes socket_op(.shutdown) → doGenTcpShutdown → x0
    try std.testing.expect(m.pending == null); // trap consumed (reachable, not undef)
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], ok));
    _ = try vm.doGenTcpClose(m, c5);
    _ = try vm.doGenTcpClose(m, l5);
}

test "LAW gap-cowboy-trap-accept REACTOR: gen_tcp:accept(LSock, infinity) with no pending connection SUSPENDS the caller as the listen socket's accept_waiter (never blocks the drive); when a client later connects, pollAcceptSockets accept4()s it, RESUMES the waiter with {ok,ConnSocket} in x0, and re-arms the listener — mirroring pollActiveSockets. A FINITE timeout stays a bounded fail-closed sync accept (the accept-hang law)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const inf = FinalTerms.atom(&m.ctx, try atoms.intern("infinity"));

    // (ARM 1) SUSPEND: accept(infinity) on an idle listener registers the caller as
    // the accept_waiter and parks it — the reactor path, NOT a synchronous block.
    const lsock = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const port = try sockUnwrapOk(m, try vm.doInetPort(m, lsock), &atoms);
    m.status = .running;
    _ = try vm.doGenTcpAccept(p0, m, lsock, inf); // no client yet → suspend
    try std.testing.expect(m.status == .suspended);
    try std.testing.expectEqual(@as(usize, 1), vm.socketOf(m, lsock).?.accept_waiters.items.len);
    try std.testing.expectEqual(@as(Pid, p0), vm.socketOf(m, lsock).?.accept_waiters.items[0]);
    // A suspended acceptor keeps the node non-quiescent (driveResident must poll-wait).
    try std.testing.expect(vm.anySocketWaiter());

    // (ARM 2) RESUME: a client connects; pollAcceptSockets accept4()s it and wakes
    // the waiter with {ok, ConnSocket} in x0, clearing the arm (re-armed on next accept).
    const csock = try sockUnwrapOk(m, try vm.doGenTcpConnect(m, port), &atoms);
    try vm.pollAcceptSockets();
    try std.testing.expect(m.status == .running); // resumed
    try std.testing.expect(vm.socketOf(m, lsock).?.accept_waiters.items.len == 0); // served + dequeued
    // x0 now carries {ok, ConnSocket}; prove it round-trips real bytes end-to-end.
    const ssock = try sockUnwrapOk(m, m.regs[0], &atoms);
    _ = try vm.doGenTcpSend(m, csock, try FinalTerms.binary(&m.ctx, "reactor-accept-handoff"));
    const got = try sockUnwrapOk(m, try vm.doGenTcpRecv(m, ssock, FinalTerms.int(&m.ctx, 22)), &atoms);
    try std.testing.expectEqualSlices(u8, "reactor-accept-handoff", FinalTerms.binBytes(&m.ctx, got));
    _ = try vm.doGenTcpClose(m, csock);
    _ = try vm.doGenTcpClose(m, ssock);
    _ = try vm.doGenTcpClose(m, lsock);

    // (ARM 3) FINITE timeout is UNCHANGED — a bounded fail-closed sync accept on an
    // idle listener returns {error,timeout} and never suspends (the accept-hang law).
    const lf = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    m.status = .running;
    const fin = try vm.doGenTcpAccept(p0, m, lf, FinalTerms.int(&m.ctx, 100));
    try std.testing.expect(m.status == .running); // NOT suspended — finite path is synchronous
    try std.testing.expect(vm.socketOf(m, lf).?.accept_waiters.items.len == 0); // never armed
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, fin, try vm.errTuple(m, "timeout")));
    _ = try vm.doGenTcpClose(m, lf);
}

test "LAW gap-accept-waiters-queue MULTI-ACCEPTOR (DIVERGENCE 647): a POOL of processes each in gen_tcp:accept(LSock, infinity) all queue FIFO on ONE listen socket (a single ?Pid slot lost all but the last); pollAcceptSockets serves min(waiters,connections) of them FRONT-first, each resumed with its OWN distinct {ok,ConnSocket}, the rest staying queued in order; a dead waiter is dropped, never served (CONSERVATION: every connection → exactly one distinct waiter, each once)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };

    // Three acceptor processes (a ranch-pool stand-in) + the entry proc holding the
    // listen socket. Each waiter needs the {'$socket',N} term in ITS OWN heap (a real
    // pool gets it by message-copy); build it from the shared socket number.
    const p_entry = try vm.spawn(idle, 0, null);
    const me = &vm.procs.items[p_entry].machine;
    const lsock = try sockUnwrapOk(me, try vm.doGenTcpListen(me, FinalTerms.int(&me.ctx, 0), FinalTerms.nil(&me.ctx)), &atoms);
    const port = try sockUnwrapOk(me, try vm.doInetPort(me, lsock), &atoms);
    const lnum = vm.socketOf(me, lsock).?.number;
    const sock_tag = try atoms.intern("$socket");

    var waiters: [3]Pid = undefined;
    for (&waiters) |*w| {
        const pw = try vm.spawn(idle, 0, null);
        w.* = pw;
        const mw = &vm.procs.items[pw].machine;
        mw.status = .running;
        const lterm = try FinalTerms.tuple(&mw.ctx, &.{ FinalTerms.atom(&mw.ctx, sock_tag), FinalTerms.int(&mw.ctx, @intCast(lnum)) });
        const inf = FinalTerms.atom(&mw.ctx, try atoms.intern("infinity"));
        _ = try vm.doGenTcpAccept(pw, mw, lterm, inf); // all suspend + ENQUEUE FIFO
        try std.testing.expect(mw.status == .suspended);
    }
    // (ARM 1) all three queued, in suspend order (FIFO), on the ONE listen socket.
    const q = vm.socketOf(me, lsock).?;
    try std.testing.expectEqual(@as(usize, 3), q.accept_waiters.items.len);
    try std.testing.expectEqualSlices(Pid, &waiters, q.accept_waiters.items);

    // (ARM 2) TWO clients connect → pollAcceptSockets serves the FRONT two only.
    const c0 = try sockUnwrapOk(me, try vm.doGenTcpConnect(me, port), &atoms);
    const c1 = try sockUnwrapOk(me, try vm.doGenTcpConnect(me, port), &atoms);
    try vm.pollAcceptSockets();
    // waiters[0] and waiters[1] resumed with DISTINCT sockets; waiters[2] still queued.
    try std.testing.expect(vm.procs.items[waiters[0]].machine.status == .running);
    try std.testing.expect(vm.procs.items[waiters[1]].machine.status == .running);
    try std.testing.expect(vm.procs.items[waiters[2]].machine.status == .suspended);
    try std.testing.expectEqual(@as(usize, 1), vm.socketOf(me, lsock).?.accept_waiters.items.len);
    try std.testing.expectEqual(waiters[2], vm.socketOf(me, lsock).?.accept_waiters.items[0]);
    const s0 = try sockUnwrapOk(&vm.procs.items[waiters[0]].machine, vm.procs.items[waiters[0]].machine.regs[0], &atoms);
    const s1 = try sockUnwrapOk(&vm.procs.items[waiters[1]].machine, vm.procs.items[waiters[1]].machine.regs[0], &atoms);
    // distinct accepted connections (different socket numbers) — no double-serve.
    try std.testing.expect(vm.socketOf(&vm.procs.items[waiters[0]].machine, s0).?.number != vm.socketOf(&vm.procs.items[waiters[1]].machine, s1).?.number);

    // (ARM 3) a THIRD client → the last queued waiter is served; queue drains empty.
    const c2 = try sockUnwrapOk(me, try vm.doGenTcpConnect(me, port), &atoms);
    try vm.pollAcceptSockets();
    try std.testing.expect(vm.procs.items[waiters[2]].machine.status == .running);
    try std.testing.expectEqual(@as(usize, 0), vm.socketOf(me, lsock).?.accept_waiters.items.len);

    // (ARM 4) DEAD-WAITER DROP: waiters[0] re-arms then dies; a client connects; the
    // dead front waiter is dropped (never served), leaving the queue empty, no crash.
    {
        const pw = waiters[0];
        const mw = &vm.procs.items[pw].machine;
        mw.status = .running;
        const lterm = try FinalTerms.tuple(&mw.ctx, &.{ FinalTerms.atom(&mw.ctx, sock_tag), FinalTerms.int(&mw.ctx, @intCast(lnum)) });
        const inf = FinalTerms.atom(&mw.ctx, try atoms.intern("infinity"));
        _ = try vm.doGenTcpAccept(pw, mw, lterm, inf);
        try std.testing.expectEqual(@as(usize, 1), vm.socketOf(me, lsock).?.accept_waiters.items.len);
        try vm.terminate(pw, FinalTerms.atom(&mw.ctx, try atoms.intern("kill"))); // the waiter dies
        const c3 = try sockUnwrapOk(me, try vm.doGenTcpConnect(me, port), &atoms);
        try vm.pollAcceptSockets(); // drops the dead waiter; no live waiter → nothing served
        try std.testing.expectEqual(@as(usize, 0), vm.socketOf(me, lsock).?.accept_waiters.items.len);
        _ = try vm.doGenTcpClose(me, c3);
    }

    _ = try vm.doGenTcpClose(me, c0);
    _ = try vm.doGenTcpClose(me, c1);
    _ = try vm.doGenTcpClose(me, c2);
    _ = try vm.doGenTcpClose(me, lsock);
}

test "LAW gap-dynamic-native-dispatch (DIVERGENCE 650): a RUNTIME M:F/A dispatch (call_ext_code / apply — what a compiled Mod:Var call, e.g. ranch's error_logger:Function(Fmt,Args) crash-report, lowers to) resolves the NATIVE bif surface (resolve ∪ resolveLibrary) as a fallback ABOVE error_handler/undef, so a dynamic error_logger:error_report/1 returns ok INSTEAD of undef (the trapping supervisor survives a child crash — M3 recovery); an unknown M:F/A still crashes undef" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const el = try atoms.intern("error_logger");
    const er = try atoms.intern("error_report");

    // (ARM 1) a DYNAMIC error_logger:error_report/1 (ranch's report path) → ok, not undef.
    const prog: ia.Program = &.{
        .{ .call_ext_code = .{ .module = el, .func = er, .arity = 1, .push_ret = true } },
        .{ .halt = .{ .src = .{ .x = 0 } } },
    };
    const p = try vm.spawn(prog, 0, null);
    const m = &vm.procs.items[p].machine;
    m.regs[0] = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.atom(&m.ctx, try atoms.intern("reason")), FinalTerms.int(&m.ctx, 42) });
    try vm.grant(p, 20);
    try std.testing.expect(vm.procs.items[p].machine.status != .crashed); // resolved, did NOT undef-crash
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], FinalTerms.atom(&m.ctx, try atoms.intern("ok"))));

    // (ARM 2) an UNKNOWN M:F/A still crashes `undef` (the native resolver returns
    // null → error_handler-then-undef fall-through is preserved — no over-resolution).
    const prog2: ia.Program = &.{
        .{ .call_ext_code = .{ .module = try atoms.intern("no_such_mod"), .func = try atoms.intern("no_such_fun"), .arity = 1, .push_ret = true } },
        .{ .halt = .{ .src = .{ .x = 0 } } },
    };
    const p2 = try vm.spawn(prog2, 0, null);
    const m2 = &vm.procs.items[p2].machine;
    m2.regs[0] = FinalTerms.int(&m2.ctx, 1);
    try vm.grant(p2, 20);
    try std.testing.expect(vm.procs.items[p2].machine.status == .crashed);
    // DIVERGENCE 683: `grant`'s epilogue COOKS the self-inflicted exit reason by
    // class before terminate propagates it — an uncaught `undef` (error class) is
    // now the OTP exit reason `{undef, Stacktrace}`, not a bare atom. The head is
    // still `undef` (proves no over-resolution — the native resolver missed).
    try std.testing.expect(FinalTerms.kindOf(&m2.ctx, m2.result) == .tuple);
    try std.testing.expect(FinalTerms.eqlExact(&m2.ctx, FinalTerms.tupleElem(&m2.ctx, m2.result, 0), FinalTerms.atom(&m2.ctx, m2.undef)));
}

test "LAW gap-processes-0 (DIVERGENCE 651): a compiled erlang:processes/0 RESOLVES (not undef, via the process_info/1,2 dispatch-needed-deferred carve-out) and returns the TRUTHFUL live pid list — every ALIVE proc as a `.pid` term, including the caller; a DEAD proc is excluded (count == alive count). The ledger row stays `.justified` (the enumerated pid-VALUE list is not byte-EQ to OTP's per-node boot-set — a disclosed residual, FM-OBS-1: truthful, never fabricated)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const a = try vm.spawn(idle, 0, null);
    const b = try vm.spawn(idle, 0, null);
    // the caller runs a COMPILED erlang:processes/0 (resolves via the carve-out).
    const prog: ia.Program = &.{
        .{ .call_ext_code = .{ .module = try atoms.intern("erlang"), .func = try atoms.intern("processes"), .arity = 0, .push_ret = true } },
        .{ .halt = .{ .src = .{ .x = 0 } } },
    };
    const p = try vm.spawn(prog, 0, null);
    _ = a;
    // kill `b` to prove the DEAD proc is excluded (never a stale/fabricated pid).
    try vm.terminate(b, FinalTerms.atom(&vm.procs.items[p].machine.ctx, try atoms.intern("kill")));
    // expected = the alive procs (a + p; b killed) — compute it, don't hardcode.
    var expected: usize = 0;
    for (vm.procs.items) |pp| {
        if (pp.alive) expected += 1;
    }
    try vm.grant(p, 20);
    const m = &vm.procs.items[p].machine;
    try std.testing.expect(m.status != .crashed); // RESOLVED, not undef
    // m.result is the pid list: every element a `.pid`, count == alive count.
    var count: usize = 0;
    var saw_self = false;
    const self_pid = try FinalTerms.pid(&m.ctx, @intCast(p), 0);
    var cur = m.result;
    while (FinalTerms.kindOf(&m.ctx, cur) == .cons) {
        const h = FinalTerms.listHead(&m.ctx, cur);
        try std.testing.expect(FinalTerms.repIsPid(&m.ctx, h)); // all pids
        if (FinalTerms.eqlExact(&m.ctx, h, self_pid)) saw_self = true;
        count += 1;
        cur = FinalTerms.listTail(&m.ctx, cur);
    }
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, cur) == .nil); // proper list
    try std.testing.expectEqual(expected, count); // == ALIVE count (dead `b` excluded)
    try std.testing.expect(saw_self); // the caller is in its own processes() list
}

test "LAW gap-socket-gen-tcp-bifs GETOPTS: inet:getopts(Socket,[active]) reads BACK the mode setopts recorded (false/once/true round-trip, truthful); unmodeled opts are OMITTED (never fabricated, FM-OBS-1); a closed socket → {error,closed}; compiled inet:getopts/2 reaches the handler" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const p0 = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p0].machine;
    const a_active = FinalTerms.atom(&m.ctx, try atoms.intern("active"));

    // a connected loopback socket to introspect
    const lsock = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const port = try sockUnwrapOk(m, try vm.doInetPort(m, lsock), &atoms);
    const csock = try sockUnwrapOk(m, try vm.doGenTcpConnect(m, port), &atoms);
    const ssock = try sockUnwrapOk(m, try vm.doGenTcpAccept(0, m, lsock, FinalTerms.int(&m.ctx, 200)), &atoms);

    // [active] — the single-option query list, rebuilt per use (fresh term ctx).
    const activeQuery = struct {
        fn mk(mm: *ia.Machine, opt: FinalTerms.Term) !FinalTerms.Term {
            return FinalTerms.cons(&mm.ctx, opt, FinalTerms.nil(&mm.ctx));
        }
    }.mk;

    // (1) ROUND-TRIP: setopts records the mode; getopts reads EXACTLY it back.
    // We drive setopts through the same trap-owner path (pid p0) it uses live.
    for ([_]struct { set: []const u8, want: []const u8 }{
        .{ .set = "once", .want = "once" },
        .{ .set = "true", .want = "true" },
        .{ .set = "false", .want = "false" },
    }) |case| {
        const optval = try FinalTerms.tuple(&m.ctx, &.{ a_active, FinalTerms.atom(&m.ctx, try atoms.intern(case.set)) });
        const opts = try FinalTerms.cons(&m.ctx, optval, FinalTerms.nil(&m.ctx));
        _ = try vm.doInetSetopts(p0, m, csock, opts);
        const got = try sockUnwrapOk(m, try vm.doInetGetopts(m, csock, try activeQuery(m, a_active)), &atoms);
        // got == [{active, want}]
        try std.testing.expectEqual(@as(usize, 1), listLenPr(m, got));
        const pair = FinalTerms.listHead(&m.ctx, got);
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, pair, 0), a_active));
        const want_mode = FinalTerms.atom(&m.ctx, try atoms.intern(case.want));
        try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, pair, 1), want_mode));
    }

    // (2) FM-OBS-1: an UNMODELED opt (nodelay) is OMITTED, never fabricated. A query
    // of [active, nodelay] returns ONLY the truthful active entry (len 1, not 2).
    const optval2 = try FinalTerms.tuple(&m.ctx, &.{ a_active, FinalTerms.atom(&m.ctx, try atoms.intern("once")) });
    _ = try vm.doInetSetopts(p0, m, csock, try FinalTerms.cons(&m.ctx, optval2, FinalTerms.nil(&m.ctx)));
    const mixed = try FinalTerms.cons(&m.ctx, a_active, try FinalTerms.cons(&m.ctx, FinalTerms.atom(&m.ctx, try atoms.intern("nodelay")), FinalTerms.nil(&m.ctx)));
    const got2 = try sockUnwrapOk(m, try vm.doInetGetopts(m, csock, mixed), &atoms);
    try std.testing.expectEqual(@as(usize, 1), listLenPr(m, got2)); // nodelay OMITTED, active present

    _ = try vm.doGenTcpClose(m, csock);
    _ = try vm.doGenTcpClose(m, ssock);
    _ = try vm.doGenTcpClose(m, lsock);

    // (3) a getopts of a CLOSED socket → {error,closed}, never a crash.
    const gone = try vm.doInetGetopts(m, csock, try activeQuery(m, a_active));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, gone, try vm.errTuple(m, "closed")));

    // (4) DISPATCH-REACHABILITY: compiled inet:getopts/2 emits the socket_op trap and
    // the Vm routes it to the handler (not undef) — the FM-DISPATCH-DEAD guard.
    const l4 = try sockUnwrapOk(m, try vm.doGenTcpListen(m, FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx)), &atoms);
    const p4 = try sockUnwrapOk(m, try vm.doInetPort(m, l4), &atoms);
    const c4 = try sockUnwrapOk(m, try vm.doGenTcpConnect(m, p4), &atoms);
    _ = try socket_bifs.inet_getopts_2(m, &.{ c4, try FinalTerms.cons(&m.ctx, a_active, FinalTerms.nil(&m.ctx)) });
    try std.testing.expect(m.pending != null);
    try vm.interpret(p0);
    try std.testing.expect(m.pending == null);
    const rr = try sockUnwrapOk(m, m.regs[0], &atoms);
    try std.testing.expectEqual(@as(usize, 1), listLenPr(m, rr)); // {ok,[{active,_}]}
    _ = try vm.doGenTcpClose(m, c4);
    _ = try vm.doGenTcpClose(m, l4);
}

test "E7.4 processes_next iteration totality: folding the cursor enumerates EXACTLY the live-pid set, for every chunk size" {
    // erts_internal:processes_next/1 iterates the live process set in chunks. The
    // ITERATION-TOTALITY property: folding from cursor 0 to the end yields exactly
    // the live pids `processes/0` (the list_processes trap) reports — the same
    // SET, independent of the chunk size (the internal cursor is nondeterministic,
    // so this is a property law, not a differential). A just-spawned live process
    // MUST appear; an exited one MUST NOT. Bounded: a wedged cursor is a failed law.
    const gpa = std.testing.allocator;
    const cfg = LawConfig{ .seed = 0x7401 };
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const halter: ia.Program = &.{.{ .halt = .{ .src = .nil } }};

    // spawn a spread of processes; halt some so the live set has holes.
    var spawned: [7]Pid = undefined;
    for (&spawned) |*s| s.* = try vm.spawn(idle, 0, null);
    const dead = try vm.spawn(halter, 0, null);
    try vm.grant(dead, 4); // halts → normalExit → not alive
    try std.testing.expect(!vm.procs.items[dead].alive);

    // the EXPECTED live set (what processes/0 would enumerate): ascending live idx.
    var expected: std.ArrayList(Pid) = .empty;
    defer expected.deinit(gpa);
    for (vm.procs.items, 0..) |p, i| {
        if (p.alive) try expected.append(gpa, @intCast(i));
    }

    // for EVERY chunk size, the fold reproduces the live set exactly (set equality).
    for ([_]usize{ 1, 2, 3, 5, 100 }, 0..) |chunk, ci| {
        const got = try vm.processesNextFold(gpa, chunk);
        defer gpa.free(got);
        // the fold is ascending by construction, so element-wise equality == set equality
        try expectLaw(got.len == expected.items.len, "processes_next: fold size == live count", cfg, ci);
        for (got, expected.items, 0..) |g, e, k| {
            try expectLaw(g == e, "processes_next: fold enumerates exactly the live set", cfg, k);
        }
        // the just-spawned live processes appear; the halted one does not.
        var saw_dead = false;
        var saw_all_live = true;
        for (spawned) |s| {
            var found = false;
            for (got) |g| {
                if (g == s) found = true;
            }
            if (!found) saw_all_live = false;
        }
        for (got) |g| {
            if (g == dead) saw_dead = true;
        }
        try expectLaw(saw_all_live and !saw_dead, "processes_next: live in, exited out (totality)", cfg, ci);
    }
}

test "Monitors: 'DOWN' exactly once; demonitor prevents it; dead pid → noproc" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const crasher: ia.Program = &.{
        .{ .exit_proc = .{ .reason = .{ .imm = 55 } } },
    };

    // (a) monitor then target dies → exactly one 'DOWN'
    {
        const w = try vm.spawn(idle, 0, null);
        const t = try vm.spawn(crasher, 0, null);
        const pw = vm.procs.items[w];
        pw.machine.pending = .{ .monitor_to = .{ .pid = FinalTerms.int(&pw.machine.ctx, t), .dst = 5 } };
        try vm.interpret(w);
        // E3.8-fix: monitor/2 returns a GENUINE E3.5 boxed ref, not a small int.
        const mref = pw.machine.regs[5];
        try std.testing.expect(FinalTerms.repIsRef(&pw.machine.ctx, mref));
        try vm.grant(t, 10);
        try vm.drainSignals(w);
        var downs: usize = 0;
        for (vm.events.items) |e| switch (e) {
            .down_delivered => |d| {
                if (d.to == w) downs += 1;
            },
            else => {},
        };
        try std.testing.expectEqual(@as(usize, 1), downs);
        // E3.8-fix: {'DOWN', Ref, process, Pid, Reason} — the real 5-tuple
        // shape, element 2 `eqlExact` the returned ref, element 3 the atom
        // `process`, element 4 the monitored pid, element 5 the reason.
        {
            var buf: [8]mba.Msg(FinalTerms) = undefined;
            const q = pw.machine.mbox.toSeq(&buf);
            try std.testing.expectEqual(@as(usize, 1), q.len);
            const down_tup = q[0].payload;
            try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&pw.machine.ctx, down_tup));
            try std.testing.expectEqual(@as(usize, 5), FinalTerms.tupleArity(&pw.machine.ctx, down_tup));
            const tag = FinalTerms.tupleElem(&pw.machine.ctx, down_tup, 0);
            try std.testing.expect(FinalTerms.repIsAtom(tag) and FinalTerms.atomIdxOf(tag) == vm.a_down);
            const ref_elem = FinalTerms.tupleElem(&pw.machine.ctx, down_tup, 1);
            try std.testing.expect(FinalTerms.repIsRef(&pw.machine.ctx, ref_elem));
            try std.testing.expect(FinalTerms.eqlExact(&pw.machine.ctx, ref_elem, mref));
            const type_elem = FinalTerms.tupleElem(&pw.machine.ctx, down_tup, 2);
            try std.testing.expect(FinalTerms.repIsAtom(type_elem) and FinalTerms.atomIdxOf(type_elem) == vm.a_process);
            const pid_elem = FinalTerms.tupleElem(&pw.machine.ctx, down_tup, 3);
            try std.testing.expect(FinalTerms.repIsPid(&pw.machine.ctx, pid_elem));
            try std.testing.expectEqual(@as(u64, t), FinalTerms.pidNumber(&pw.machine.ctx, pid_elem));
            const reason_elem = FinalTerms.tupleElem(&pw.machine.ctx, down_tup, 4);
            try std.testing.expect(FinalTerms.eqlExact(&pw.machine.ctx, reason_elem, FinalTerms.int(&pw.machine.ctx, 55)));
        }
        // grant more slices; no second DOWN can appear
        try vm.grant(w, 10);
        var downs2: usize = 0;
        for (vm.events.items) |e| switch (e) {
            .down_delivered => |d| {
                if (d.to == w) downs2 += 1;
            },
            else => {},
        };
        try std.testing.expectEqual(@as(usize, 1), downs2);
    }
    // (b) demonitor before death → no DOWN
    {
        const w = try vm.spawn(idle, 0, null);
        const t = try vm.spawn(crasher, 0, null);
        const pw = vm.procs.items[w];
        pw.machine.pending = .{ .monitor_to = .{ .pid = FinalTerms.int(&pw.machine.ctx, t), .dst = 5 } };
        try vm.interpret(w);
        const ref = pw.machine.regs[5];
        pw.machine.pending = .{ .demonitor_ref = .{ .ref = ref, .info = false } };
        try vm.interpret(w);
        try vm.grant(t, 10);
        try vm.drainSignals(w);
        var downs: usize = 0;
        for (vm.events.items) |e| switch (e) {
            .down_delivered => |d| {
                if (d.to == w) downs += 1;
            },
            else => {},
        };
        try std.testing.expectEqual(@as(usize, 0), downs);
    }
    // (c) monitor of a dead pid → immediate noproc DOWN
    {
        const w = try vm.spawn(idle, 0, null);
        const pw = vm.procs.items[w];
        pw.machine.pending = .{ .monitor_to = .{ .pid = FinalTerms.int(&pw.machine.ctx, 9999), .dst = 5 } };
        try vm.interpret(w);
        try vm.drainSignals(w);
        try std.testing.expectEqual(@as(usize, 1), pw.machine.mbox.len());
    }
}

test "Schedulers: oracle vs seeded engine — same results, order laws, no starvation" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const cfg = LawConfig{ .seed = 0x5EED };

    // deterministic topology (single sender per receiver): engines must
    // agree on the final result EXACTLY, for several seeds
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    // 100 + sum(worker pids 1..5)
    try std.testing.expectEqual(@as(i64, 100 + 1 + 2 + 3 + 4 + 5), rr.total);

    for (0..8) |i| {
        var en = try runRing(gpa, &atoms, .{ .seeded = cfg.seed +% i }, 5);
        defer en.events.deinit(gpa);
        try expectLaw(en.total == rr.total, "sched: engines agree on deterministic topology", cfg, i);
        try expectLaw(checkPerPairOrder(en.events.items), "sched: per-pair order under the engine", cfg, i);

        // per-process delivery sequences identical across engines
        for (0..6) |pid| {
            var qa = try perProcessDeliverSeq(gpa, rr.events.items, @intCast(pid));
            defer qa.deinit(gpa);
            var qb = try perProcessDeliverSeq(gpa, en.events.items, @intCast(pid));
            defer qb.deinit(gpa);
            try expectLaw(std.mem.eql(u64, qa.items, qb.items), "sched: per-process delivery sequence engine-invariant", cfg, i);
        }

        // NO STARVATION: while ≥2 processes stay runnable, each runnable pid
        // is granted within a window of 4·N slices
        var grants: std.ArrayList(Pid) = .empty;
        defer grants.deinit(gpa);
        for (en.events.items) |e| switch (e) {
            .grant => |g| try grants.append(gpa, g),
            else => {},
        };
        const n: usize = 6;
        if (grants.items.len > 4 * n) {
            var w: usize = 0;
            while (w + 4 * n <= grants.items.len) : (w += 4 * n) {
                var seen = [_]bool{false} ** 8;
                for (grants.items[w .. w + 4 * n]) |g| seen[g] = true;
                // at least: the collector (0) must appear in every window
                // while it is alive — it is runnable the whole run
                try expectLaw(seen[0], "sched: no starvation (collector granted in every window)", cfg, i);
            }
        }
    }
}

test "G3 GATE: scatter/gather with selective receive under both engines" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // parent spawns 3 children; children send {tagged} answers out of order;
    // parent selectively receives tags 1,2,3 IN ORDER and halts with the
    // weighted sum — deterministic despite arrival races.
    //
    // child: x15 = arg (its tag); sends tag to parent (pid in x2, arrives
    // as first message), then halts.
    const prog: ia.Program = &.{
        // 0: child — receive parent pid, send own tag, halt
        .{ .recv_any = .{ .dst = 2, .else_to = 0 } },
        .{ .send_to = .{ .pid = .{ .x = 2 }, .msg = .{ .x = 15 } } },
        .{ .halt = .{ .src = .{ .imm = 0 } } },
        // 3: parent — spawn 3 children at label 0
        .{ .spawn = .{ .to = 0, .dst = 3 } },
        .{ .spawn = .{ .to = 0, .dst = 4 } },
        .{ .spawn = .{ .to = 0, .dst = 5 } },
        // 6..8: tell each child who I am
        .{ .send_to = .{ .pid = .{ .x = 3 }, .msg = .{ .x = 14 } } },
        .{ .send_to = .{ .pid = .{ .x = 4 }, .msg = .{ .x = 14 } } },
        .{ .send_to = .{ .pid = .{ .x = 5 }, .msg = .{ .x = 14 } } },
        // 9..11: selective receive tags 1, 2, 3 in THAT order
        .{ .recv_eq = .{ .m = .{ .imm = 1 }, .dst = 6, .else_to = 9 } },
        .{ .recv_eq = .{ .m = .{ .imm = 2 }, .dst = 7, .else_to = 10 } },
        .{ .recv_eq = .{ .m = .{ .imm = 3 }, .dst = 8, .else_to = 11 } },
        // 12: sum = x6 + 10*nothing… just add them with weights via adds
        .{ .add = .{ .a = .{ .x = 6 }, .b = .{ .x = 7 }, .dst = 6 } },
        .{ .add = .{ .a = .{ .x = 6 }, .b = .{ .x = 8 }, .dst = 6 } },
        .{ .halt = .{ .src = .{ .x = 6 } } },
    };
    _ = prog;

    // children need distinct tags — spawn arg carries it, but our spawn
    // action doesn't take args. Wire tags by sending them instead:
    const prog2: ia.Program = &.{
        // 0: child — receive parent pid, receive tag, send tag back, halt
        .{ .recv_any = .{ .dst = 2, .else_to = 0 } },
        .{ .recv_any = .{ .dst = 3, .else_to = 1 } },
        .{ .send_to = .{ .pid = .{ .x = 2 }, .msg = .{ .x = 3 } } },
        .{ .halt = .{ .src = .{ .imm = 0 } } },
        // 4: parent
        .{ .spawn = .{ .to = 0, .dst = 3 } },
        .{ .spawn = .{ .to = 0, .dst = 4 } },
        .{ .spawn = .{ .to = 0, .dst = 5 } },
        .{ .send_to = .{ .pid = .{ .x = 3 }, .msg = .{ .x = 14 } } }, // parent pid
        .{ .send_to = .{ .pid = .{ .x = 4 }, .msg = .{ .x = 14 } } },
        .{ .send_to = .{ .pid = .{ .x = 5 }, .msg = .{ .x = 14 } } },
        .{ .send_to = .{ .pid = .{ .x = 3 }, .msg = .{ .imm = 3 } } }, // tags scrambled
        .{ .send_to = .{ .pid = .{ .x = 4 }, .msg = .{ .imm = 1 } } },
        .{ .send_to = .{ .pid = .{ .x = 5 }, .msg = .{ .imm = 2 } } },
        // selective receive 1, 2, 3 in order
        .{ .recv_eq = .{ .m = .{ .imm = 1 }, .dst = 6, .else_to = 13 } },
        .{ .recv_eq = .{ .m = .{ .imm = 2 }, .dst = 7, .else_to = 14 } },
        .{ .recv_eq = .{ .m = .{ .imm = 3 }, .dst = 8, .else_to = 15 } },
        // weighted sum: x6 + x7 + x7 + x8 + x8 + x8 = 1 + 2·2 + 3·3 = 14
        .{ .add = .{ .a = .{ .x = 6 }, .b = .{ .x = 7 }, .dst = 6 } },
        .{ .add = .{ .a = .{ .x = 6 }, .b = .{ .x = 7 }, .dst = 6 } },
        .{ .add = .{ .a = .{ .x = 6 }, .b = .{ .x = 8 }, .dst = 6 } },
        .{ .add = .{ .a = .{ .x = 6 }, .b = .{ .x = 8 }, .dst = 6 } },
        .{ .add = .{ .a = .{ .x = 6 }, .b = .{ .x = 8 }, .dst = 6 } },
        .{ .halt = .{ .src = .{ .x = 6 } } },
    };

    const engines = [_]Scheduler{ .round_robin, .{ .seeded = 0xAB }, .{ .seeded = 0xCD } };
    var results: [3]i64 = undefined;
    for (engines, 0..) |sched, k| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const parent = try vm.spawn(prog2, 4, null);
        try sched.drive(&vm, 6, 5000);
        const pm = &vm.procs.items[parent].machine;
        try std.testing.expectEqual(ia.Status.halted, pm.status);
        results[k] = @as(i64, @bitCast(pm.result)) >> 4;
        try std.testing.expect(checkPerPairOrder(vm.events.items));
    }
    try std.testing.expectEqual(@as(i64, 14), results[0]);
    try std.testing.expectEqual(results[0], results[1]);
    try std.testing.expectEqual(results[0], results[2]);
}

// ============================================================================
// E3.7: the process bridge — spawn/self/send/exit over pid TERMs (Task 5), the
// proc.zig scheduler, and the E1.11 receive-wake. Every law is bounded (a hang
// is a FAILED law) and observational. These EXERCISE the procsys BIFs through
// the Vm: `self_0`, `spawn_1` (spawn_fun trap), `send_2` (send_to trap), and the
// loop_rec/wait suspend/resume the receive-wake upgrades. The sacred M7 per-pair
// order law + the whole pre-E3.7 suite above are UNTOUCHED (backward-compat).
// ============================================================================

/// Build a `bif_call` CInstr for an argc-`n` process BIF into register `dst`.
fn bifCall(f: ia.BifFn, args: [3]ia.Src, argc: u8, dst: u4) ia.CInstr {
    return .{ .bif_call = .{ .bif = .{ .func = f }, .args = args, .argc = argc, .dst = .{ .x = dst }, .else_to = null, .gc_live = null } };
}

test "E3.7 WORKED LAW: spawn/send/self round-trip — child echoes self() to parent" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const echo = try atoms.intern("echo");

    // The shared program. Labels are pc indices. CHILD entry = 0; PARENT = 7.
    // Parent: make a fun for the child, `spawn_1` it (BIF → child pid in x0),
    // save it, `self_0` its own pid, send it to the child, then receive the
    // child's {echo, ChildSelf} reply and halt with element 2. Child: receive
    // the parent pid P, build {echo, self()}, send it to P, halt. Both the
    // spawn and both self() calls go through the procsys BIFs; both receives use
    // the E1.11 loop_rec/wait suspend that the receive-wake resumes on delivery.
    const echo_elems = [_]ia.Src{ .{ .atom_ = @intCast(echo) }, .{ .x = 1 } };
    const prog: ia.Program = &.{
        // ---- CHILD (entry 0) ----
        .{ .loop_rec = .{ .else_to = 6, .dst = 0 } }, // 0: peek parent pid → x0 (else wait)
        .remove_message, //                              1: commit the pop
        bifCall(&procsys.self_0, .{ .nil, .nil, .nil }, 0, 1), // 2: x1 = child's own pid
        .{ .put_tuple2 = .{ .dst = .{ .x = 2 }, .elems = &echo_elems } }, // 3: {echo, self()}
        .{ .send_to = .{ .pid = .{ .x = 0 }, .msg = .{ .x = 2 } } }, // 4: reply to P
        .{ .halt = .{ .src = .{ .x = 0 } } }, //          5: exit normal
        .{ .wait = .{ .to = 0 } }, //                     6: WAIT_C — suspend, re-enter loop_rec
        // ---- PARENT (entry 7) ----
        .{ .make_fun3 = .{ .to = 0, .arity = 0, .dst = .{ .x = 0 }, .env = &.{} } }, // 7: fun @label 0
        bifCall(&procsys.spawn_1, .{ .{ .x = 0 }, .nil, .nil }, 1, 0), // 8: spawn_1 → child pid in x0
        .{ .move = .{ .src = .{ .x = 0 }, .dst = 5 } }, // 9: x5 = child pid (saved)
        bifCall(&procsys.self_0, .{ .nil, .nil, .nil }, 0, 6), // 10: x6 = parent's own pid
        .{ .send_to = .{ .pid = .{ .x = 5 }, .msg = .{ .x = 6 } } }, // 11: tell child who I am
        .{ .loop_rec = .{ .else_to = 16, .dst = 7 } }, // 12: receive {echo, ChildSelf} → x7
        .remove_message, //                              13: commit
        .{ .get_tuple_elem = .{ .src = .{ .x = 7 }, .index = 1, .dst = .{ .x = 0 } } }, // 14: x0 = elem 2
        .{ .halt = .{ .src = .{ .x = 0 } } }, //          15: halt with the echoed child pid
        .{ .wait = .{ .to = 12 } }, //                    16: WAIT_P
    };

    inline for (.{ @as(Scheduler, .round_robin), Scheduler{ .seeded = 0x77E } }) |sched| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const parent = try vm.spawn(prog, 7, null);
        try sched.drive(&vm, 20, 4000); // bounded — a hang is a failed law

        const pm = &vm.procs.items[parent].machine;
        try std.testing.expectEqual(ia.Status.halted, pm.status); // parent exited normal
        // parent's x0 (its result) == the child's pid it spawned (saved in x5).
        try std.testing.expect(FinalTerms.repIsPid(&pm.ctx, pm.result));
        try std.testing.expect(FinalTerms.eqlExact(&pm.ctx, pm.result, pm.regs[5]));
        // and it names the child process (number == the child's proc index).
        const child_idx = FinalTerms.pidNumber(&pm.ctx, pm.result);
        try std.testing.expect(child_idx != parent); // NOT the parent's pid (mutant 1)
        const cm = &vm.procs.items[@intCast(child_idx)].machine;
        try std.testing.expectEqual(ia.Status.halted, cm.status); // child exited normal
    }
}

test "E4.1 WORKED LAW: spawn/3 resolves a loaded MFA and runs the child; an unresolvable MFA exits undef" {
    // The scheduler-as-driver's new reachability: `spawn(M, F, Args)` (the BIF
    // dispatched via call_ext_bif from a compiled `.beam`) resolves M:F/arity
    // against the LIVE export index the child inherits, unpacks Args into the
    // child's x-registers (cross-heap), and runs it. This is the single change
    // that flips `deferred-E4-procdispatch` for the MFA-spawn rows.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const m_atom = try atoms.intern("m");
    const child_atom = try atoms.intern("child");

    // CHILD (label 0): halt with its single argument (x0). PARENT (label 2):
    // spawn m:child([x2]) — module in x0, func in x1, arglist in x2 — then halt.
    const prog: ia.Program = &.{
        .{ .halt = .{ .src = .{ .x = 0 } } }, // 0: child body → halt with arg
        .{ .halt = .{ .src = .{ .imm = 0 } } }, // 1: pad
        bifCall(&procsys.spawn_3, .{ .{ .x = 0 }, .{ .x = 1 }, .{ .x = 2 } }, 3, 3), // 2: spawn → pid x3
        .{ .halt = .{ .src = .{ .imm = 0 } } }, // 3: parent halts
    };
    const exports = [_]ia.Export{.{ .module = @intCast(m_atom), .func = @intCast(child_atom), .arity = 1, .pc = 0 }};

    // (a) RESOLVABLE: m:child([42]) runs and the child halts with 42.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const parent = try vm.spawn(prog, 2, null);
        const pm = &vm.procs.items[parent].machine;
        pm.exports = &exports;
        pm.regs[0] = FinalTerms.atom(&pm.ctx, m_atom);
        pm.regs[1] = FinalTerms.atom(&pm.ctx, child_atom);
        pm.regs[2] = try FinalTerms.cons(&pm.ctx, FinalTerms.int(&pm.ctx, 42), FinalTerms.nil(&pm.ctx));
        try (@as(Scheduler, .round_robin)).drive(&vm, 20, 2000);
        try std.testing.expect(vm.procs.items.len >= 2);
        const cm = &vm.procs.items[1].machine;
        try std.testing.expectEqual(ia.Status.halted, cm.status);
        try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, cm.result, FinalTerms.int(&cm.ctx, 42)));
    }
    // (b) UNRESOLVABLE: m:missing([]) spawns a process that immediately exits
    // `undef` (BEAM-faithful) — the child is reaped, not run.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const missing = try atoms.intern("missing");
        const parent = try vm.spawn(prog, 2, null);
        const pm = &vm.procs.items[parent].machine;
        pm.exports = &exports;
        pm.regs[0] = FinalTerms.atom(&pm.ctx, m_atom);
        pm.regs[1] = FinalTerms.atom(&pm.ctx, missing);
        pm.regs[2] = FinalTerms.nil(&pm.ctx);
        try (@as(Scheduler, .round_robin)).drive(&vm, 20, 2000);
        try std.testing.expect(vm.procs.items.len >= 2);
        try std.testing.expect(!vm.procs.items[1].alive); // reaped after undef exit
    }
}

test "e21-t2b LITERAL-CTX law: a spawned child's COMPOUND literal is rebased into the CHILD's ctx (denotation preserved cross-heap), never a parent-ctx OOB" {
    // DIVERGENCE 510. The bug this RED-shows: `inheritCode` borrowed
    // `parent.literals` — but a COMPOUND literal ({r,99}) is a BOXED term whose
    // words index the PARENT's ctx heap. A child resolving `.literal 0` in its OWN
    // ctx then read a foreign/out-of-range word → an OOB panic (`bigParts`/
    // `listHead`) or a mis-tagged term that silently fails to match `{r,X}` in the
    // receiver (the spawned-child `{r,99}` send that deadlocked/panicked the
    // gen_server boot). The fix: each child gets its OWN literal table, every entry
    // gcCopy'd into the child ctx. This law drives a child that HALTS with the
    // compound literal and asserts its result DENOTES {r,99} — impossible to pass
    // while the child reads the parent's ctx.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const m_atom = try atoms.intern("m");
    const child_atom = try atoms.intern("child");
    const r_atom = try atoms.intern("r");

    // CHILD (label 0): move .literal 0 -> x0; halt x0. PARENT (label 1):
    // spawn m:child([]) then halt.
    const prog: ia.Program = &.{
        .{ .move = .{ .dst = 0, .src = .{ .literal = 0 } } }, // 0: child: x0 = literal 0
        .{ .halt = .{ .src = .{ .x = 0 } } }, // 1: child halts with x0
        bifCall(&procsys.spawn_3, .{ .{ .x = 0 }, .{ .x = 1 }, .{ .x = 2 } }, 3, 3), // 2: parent spawn
        .{ .halt = .{ .src = .{ .imm = 0 } } }, // 3: parent halt
    };
    const exports = [_]ia.Export{.{ .module = @intCast(m_atom), .func = @intCast(child_atom), .arity = 0, .pc = 0 }};

    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const parent = try vm.spawn(prog, 2, null);
    const pm = &vm.procs.items[parent].machine;
    pm.exports = &exports;
    // the PARENT's literal table: a COMPOUND literal {r,99} built in the PARENT ctx.
    const parent_lit = try FinalTerms.tuple(&pm.ctx, &.{
        FinalTerms.atom(&pm.ctx, r_atom), FinalTerms.int(&pm.ctx, 99),
    });
    const lits = [_]FinalTerms.Term{parent_lit};
    pm.literals = &lits;
    pm.regs[0] = FinalTerms.atom(&pm.ctx, m_atom);
    pm.regs[1] = FinalTerms.atom(&pm.ctx, child_atom);
    pm.regs[2] = FinalTerms.nil(&pm.ctx);
    try (@as(Scheduler, .round_robin)).drive(&vm, 20, 2000);

    try std.testing.expect(vm.procs.items.len >= 2);
    const cm = &vm.procs.items[1].machine;
    try std.testing.expectEqual(ia.Status.halted, cm.status);
    // the child owns its rebased table (never the borrowed parent slice).
    try std.testing.expect(cm.owns_literals);
    // the child's result DENOTES {r,99} — built fresh in the CHILD ctx to compare.
    const want = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.atom(&cm.ctx, r_atom), FinalTerms.int(&cm.ctx, 99),
    });
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, cm.result, want));
}

test "E4.1 trap_exit unification: process_flag(trap_exit,true) converts a linked exit into an {'EXIT',Pid,Reason} message with a pid-TERM sender" {
    // Before E4.1 a compiled `.beam`'s `process_flag(trap_exit, true)` set
    // `Machine.trap_exit` while the scheduler's exit-signal handler read a
    // SEPARATE `Process.trap_exit`, so the flag never took effect end-to-end.
    // E4.1 unifies on the one Machine field; this law drives the flag through the
    // BIF (`procsys.process_flag_2`) and checks the trapped message's FromPid is
    // a real pid TERM (so `receive {'EXIT', P, R}` binding the child pid matches).
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const crasher: ia.Program = &.{
        .{ .halt = .{ .src = .{ .imm = 0 } } }, // (unused)
    };
    const parent = try vm.spawn(crasher, 0, null);
    const child = try vm.spawn(crasher, 0, null);
    const pm = &vm.procs.items[parent].machine;

    // Drive trap_exit through the BIF (self-contained, sets Machine.trap_exit).
    const trap_exit_atom = FinalTerms.atom(&pm.ctx, try atoms.intern("trap_exit"));
    const true_atom = FinalTerms.atom(&pm.ctx, pm.bool_true);
    _ = try procsys.process_flag_2(pm, &.{ trap_exit_atom, true_atom });
    try std.testing.expect(vm.procs.items[parent].machine.trap_exit); // the ONE field

    // parent links to child, child exits abnormally → parent (trapping) gets the
    // {'EXIT', ChildPid, Reason} message instead of dying.
    try vm.procs.items[parent].links.append(gpa, child);
    try vm.signal(parent, child, .link_req);
    try vm.drainSignals(child);
    const reason = FinalTerms.int(&vm.procs.items[child].machine.ctx, 99);
    try vm.terminate(child, reason);
    try vm.drainSignals(parent);

    try std.testing.expect(vm.procs.items[parent].alive); // trapped, still alive
    var qbuf: [8]mba.Msg(FinalTerms) = undefined;
    const q = pm.mbox.toSeq(&qbuf);
    try std.testing.expectEqual(@as(usize, 1), q.len);
    const t = q[0].payload;
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&pm.ctx, t));
    try std.testing.expectEqual(@as(usize, 3), FinalTerms.tupleArity(&pm.ctx, t));
    // element 0 = 'EXIT'; element 1 = a pid TERM naming the child (the E4.1 fix).
    const from = FinalTerms.tupleElem(&pm.ctx, t, 1);
    try std.testing.expect(FinalTerms.repIsPid(&pm.ctx, from));
    try std.testing.expectEqual(@as(u64, child), FinalTerms.pidNumber(&pm.ctx, from));
}

test "LAW E5.9 process_info item-totality: every supported item resolves; the deterministic non-pid items match the target state" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const prog: ia.Program = &.{.{ .halt = .{ .src = .{ .imm = 0 } } }};
    const pid = try vm.spawn(prog, 0, null);
    const target = vm.procs.items[pid];
    const m = &target.machine; // observe on the target's own heap (self-info)

    // Give the target a distinguishable state: trap_exit on + two messages.
    target.machine.trap_exit = true;
    try target.machine.mbox.deliver(pid, FinalTerms.int(&target.machine.ctx, 10));
    try target.machine.mbox.deliver(pid, FinalTerms.int(&target.machine.ctx, 20));

    // TOTALITY: every supported item resolves without error. This list MIRRORS
    // procsys.isSupportedProcessInfoItem — a name here that the value-builder
    // cannot answer (the mutant) reddens this law.
    const supported = [_][]const u8{
        "status",   "links",         "monitors",           "registered_name",
        "messages", "dictionary",    "message_queue_len",  "trap_exit",
        "priority", "error_handler", "message_queue_data", "current_stacktrace",
    };
    for (supported) |name| {
        _ = try vm.procInfoValue(m, target, pid, name);
    }

    // E7.5 (Task 5): the two ADDED deterministic non-pid defaults are byte-total
    // portable config values (verified on the host): error_handler → the atom
    // `error_handler`; message_queue_data → `on_heap`.
    const eh = try vm.procInfoValue(m, target, pid, "error_handler");
    try std.testing.expect(FinalTerms.atomIdxOf(eh) == try atoms.intern("error_handler"));
    const mqd = try vm.procInfoValue(m, target, pid, "message_queue_data");
    try std.testing.expect(FinalTerms.atomIdxOf(mqd) == try atoms.intern("on_heap"));

    // The DETERMINISTIC non-pid items equal the target's own state.
    const mql = try vm.procInfoValue(m, target, pid, "message_queue_len");
    try std.testing.expectEqual(@as(i64, 2), FinalTerms.smallValOf(mql));
    const te = try vm.procInfoValue(m, target, pid, "trap_exit");
    try std.testing.expect(FinalTerms.atomIdxOf(te) == m.bool_true);
    const pr = try vm.procInfoValue(m, target, pid, "priority");
    try std.testing.expect(FinalTerms.atomIdxOf(pr) == try atoms.intern("normal"));
    // registered_name of an UNregistered process is the bare atom [] (nil).
    const rn = try vm.procInfoValue(m, target, pid, "registered_name");
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, rn, FinalTerms.nil(&m.ctx)));
}

test "LAW gap-current-stacktrace (DIVERGENCE 684, fractal-sweep RANK 1): process_info(Pid, current_stacktrace) returns the CURRENT call stack as [{M,F,Arity,[{file,_},{line,_}]}] (OTP `?STACKTRACE()`'s source, used by every gen_* error path) — the head names the current mfa+line; caller frames follow in return order" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const prog: ia.Program = &.{.{ .halt = .{ .src = .{ .imm = 0 } } }};
    const pid = try vm.spawn(prog, 0, null);
    const target = vm.procs.items[pid];
    const m = &target.machine; // self-info: the target IS the caller (same ctx)

    // A synthetic CURRENT call stack: head = frame at pc-1, one caller below it.
    const mi = try atoms.intern("mymod");
    const fh = try atoms.intern("myfun");
    const fc = try atoms.intern("caller");
    const filei = try atoms.intern("mymod.erl");
    const locs = [_]ia.Loc{
        .{ .m = mi, .f = fc, .a = 1, .line = 10, .file = filei }, // pc 0 = caller return site
        .{ .m = mi, .f = fh, .a = 2, .line = 42, .file = filei }, // pc 1 = head (current)
    };
    target.machine.locs = &locs;
    target.machine.pc = 2; // head = locs[pc-1] = locs[1]
    try target.machine.stack.append(target.machine.gpa, 0); // caller's return pc

    const val = try vm.procInfoValue(m, target, pid, "current_stacktrace");
    // a NON-EMPTY proper list of frames (was `badarg` before — the RANK-1 bug)
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, val) == .cons);
    const head = FinalTerms.listHead(&m.ctx, val);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, head) == .tuple and FinalTerms.tupleArity(&m.ctx, head) == 4);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, head, 0), FinalTerms.atom(&m.ctx, mi))); // module
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, head, 1), FinalTerms.atom(&m.ctx, fh))); // CURRENT function
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, head, 2), FinalTerms.int(&m.ctx, 2))); // arity
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.tupleElem(&m.ctx, head, 3)) == .cons); // {file,_},{line,_} loc list
    // the caller frame follows (return order: head first, then caller)
    const tail = FinalTerms.listTail(&m.ctx, val);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, tail) == .cons);
    const caller = FinalTerms.listHead(&m.ctx, tail);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, caller, 1), FinalTerms.atom(&m.ctx, fc)));
}

test "LAW gap-procinfo-keys (DIVERGENCE 735): process_info/2 current_function = {M,F,A} of the head loc (byte-EQ); catchlevel/reductions/stack_size = REAL functions of the target's live machine state (EQUIV) — all RETURN, not badarg" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
