        .{ .m = mi, .f = fh, .a = 3, .line = 7, .file = filei }, // pc 0
        .{ .m = mi, .f = fh, .a = 3, .line = 42, .file = filei }, // pc 1 = head (current)
    };
    target.machine.locs = &locs;
    target.machine.pc = 2; // head = locs[pc-1] = locs[1] → {mymod, myfun, 3}
    target.machine.reductions = 42;
    try target.machine.ystack.append(target.machine.gpa, FinalTerms.int(&m.ctx, 1));
    try target.machine.ystack.append(target.machine.gpa, FinalTerms.int(&m.ctx, 2));
    try target.machine.ystack.append(target.machine.gpa, FinalTerms.int(&m.ctx, 3)); // 3 y-slots
    try target.machine.catch_stack.append(target.machine.gpa, .{ .to = 0, .kind = .try_, .y_depth = 0, .c_depth = 0 });
    try target.machine.catch_stack.append(target.machine.gpa, .{ .to = 0, .kind = .catch_, .y_depth = 0, .c_depth = 0 }); // 2 frames

    // current_function = the head loc's {M, F, A} — BYTE-EQ (was badarg).
    const cf = try vm.procInfoValue(m, target, pid, "current_function");
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, cf) == .tuple and FinalTerms.tupleArity(&m.ctx, cf) == 3);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, cf, 0), FinalTerms.atom(&m.ctx, mi)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, cf, 1), FinalTerms.atom(&m.ctx, fh)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, cf, 2), FinalTerms.int(&m.ctx, 3)));

    // catchlevel/reductions/stack_size = the REAL counts (never badarg, never a made-up constant).
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.procInfoValue(m, target, pid, "catchlevel"), FinalTerms.int(&m.ctx, 2)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.procInfoValue(m, target, pid, "reductions"), FinalTerms.int(&m.ctx, 42)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.procInfoValue(m, target, pid, "stack_size"), FinalTerms.int(&m.ctx, 3)));
}

test "LAW gap-procinfo-initial-call (DIVERGENCE 754): process_info/2 initial_call = the {M,F,A} the target was SPAWNED with (byte-EQ, arity EXACT); a process with no spawn MFA defaults to {erlang,apply,2} — RETURNS, not badarg (discharges the 735 residual)" {
    const gpa = std.testing.allocator;
