    const pid = try vm.spawn(prog, 0, null);
    const target = vm.procs.items[pid];
    const m = &target.machine;

    // (a) a process WITH a recorded spawn MFA {probe, loop, 0} → {probe, loop, 0} byte-EQ.
    const mi = try atoms.intern("probe");
    const fi = try atoms.intern("loop");
    target.initial_call = .{ .m = mi, .f = fi, .a = 0 };
    const ic = try vm.procInfoValue(m, target, pid, "initial_call");
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, ic) == .tuple and FinalTerms.tupleArity(&m.ctx, ic) == 3);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, ic, 0), FinalTerms.atom(&m.ctx, mi)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, ic, 1), FinalTerms.atom(&m.ctx, fi)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, ic, 2), FinalTerms.int(&m.ctx, 0)));

    // (b) a NONZERO arity {lists, seq, 2} → the arity is EXACT (not a constant, FM-OBS-1).
    const li = try atoms.intern("lists");
    const si = try atoms.intern("seq");
    target.initial_call = .{ .m = li, .f = si, .a = 2 };
    const ic2 = try vm.procInfoValue(m, target, pid, "initial_call");
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, ic2, 0), FinalTerms.atom(&m.ctx, li)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, ic2, 1), FinalTerms.atom(&m.ctx, si)));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, ic2, 2), FinalTerms.int(&m.ctx, 2)));

    // (c) NO spawn MFA (null, the root/hand-built proc) → OTP's documented default
    // {erlang, apply, 2} — a valid key RETURNS a value, never badarg (FM-OBS-1).
    target.initial_call = null;
    const icd = try vm.procInfoValue(m, target, pid, "initial_call");
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, icd, 0), FinalTerms.atom(&m.ctx, try atoms.intern("erlang"))));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, icd, 1), FinalTerms.atom(&m.ctx, try atoms.intern("apply"))));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.tupleElem(&m.ctx, icd, 2), FinalTerms.int(&m.ctx, 2)));
}

