test "E3.7 SPAWN DENOTATION: a spawned fun's final result equals running it standalone" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // fun body @label 0: halt with the constant 42. PARENT @label 2: spawn it,
    // then loop forever (so the run stays live until the child completes). We
    // observe the CHILD's denotation directly.
    const prog: ia.Program = &.{
        .{ .halt = .{ .src = .{ .imm = 42 } } }, // 0: child fun body → 42
        .{ .halt = .{ .src = .{ .imm = 0 } } }, //  1: (pad)
        .{ .make_fun3 = .{ .to = 0, .arity = 0, .dst = .{ .x = 0 }, .env = &.{} } }, // 2: fun @0
        bifCall(&procsys.spawn_1, .{ .{ .x = 0 }, .nil, .nil }, 1, 0), // 3: spawn → x0
        .{ .halt = .{ .src = .{ .imm = 0 } } }, //  4: parent halts
    };
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    _ = try vm.spawn(prog, 2, null);
    try (@as(Scheduler, .round_robin)).drive(&vm, 20, 2000);

    // the child is process index 1 (parent is 0). Its result == the fun run
    // standalone (halt 42) — the M7 spawn law restated over the pid-term bridge.
    try std.testing.expect(vm.procs.items.len >= 2);
    const cm = &vm.procs.items[1].machine;
    try std.testing.expectEqual(ia.Status.halted, cm.status);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, cm.result, FinalTerms.int(&cm.ctx, 42)));
}

test "E21.1 FUN-SPAWN CLOSURE: spawn/1 captures a free var and the child sends it back (send-receive-between-spawned via a compiled closure, DIVERGENCE 450)" {
    // The env-capture half unique to spawn/1-of-a-fun (the empty-env denotation
    // test above does not exercise it): a `make_fun3` closure over [ParentPid, N]
    // is spawned; the child reads the captured free vars from its low x-regs
    // (x0=ParentPid, x1=N — the 0-arity fun env layout, copied CROSS-HEAP at the
    // spawn boundary, the M1 copy law), sends N back to the parent, and the parent
    // receives it. This is the exact shape of the empirically-verified sf:direct
    // corpus (spawn(fun() -> Parent ! N end)). Bounded driver — a hang is a failed
    // law. Runs under BOTH the round-robin oracle and a seeded engine.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // CHILD fun body @label 0: x0 = captured ParentPid, x1 = captured N.
    // Send x1 to x0, then halt normal. PARENT @label 3: build the env [self(), 99],
    // make a 0-arity fun over it, spawn_1 it, receive the child's N, halt with it.
    const prog: ia.Program = &.{
        // ---- CHILD fun body (entry 0) : free vars already in x0 (parent), x1 (N) ----
        .{ .send_to = .{ .pid = .{ .x = 0 }, .msg = .{ .x = 1 } } }, // 0: Parent ! N
        .{ .halt = .{ .src = .{ .x = 1 } } }, //                        1: exit normal
        .{ .wait = .{ .to = 0 } }, //                                   2: (pad)
        // ---- PARENT (entry 3) ----
        bifCall(&procsys.self_0, .{ .nil, .nil, .nil }, 0, 2), //       3: x2 = self()
        .{ .make_fun3 = .{ .to = 0, .arity = 0, .dst = .{ .x = 0 }, .env = &.{ .{ .x = 2 }, .{ .imm = 99 } } } }, // 4: fun over [self(),99]
        bifCall(&procsys.spawn_1, .{ .{ .x = 0 }, .nil, .nil }, 1, 0), // 5: spawn_1 → child pid
        .{ .loop_rec = .{ .else_to = 9, .dst = 7 } }, //                6: receive N → x7
        .remove_message, //                                            7: commit
        .{ .halt = .{ .src = .{ .x = 7 } } }, //                       8: halt with the captured N
        .{ .wait = .{ .to = 6 } }, //                                  9: WAIT_P
    };

    inline for (.{ @as(Scheduler, .round_robin), Scheduler{ .seeded = 0xC105 } }) |sched| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const parent = try vm.spawn(prog, 3, null);
        try sched.drive(&vm, 20, 4000); // bounded — a hang is a failed law
        const pm = &vm.procs.items[parent].machine;
        try std.testing.expectEqual(ia.Status.halted, pm.status);
        // the parent received EXACTLY the captured free var 99 — the closure env
        // survived the cross-heap copy at the spawn boundary and the child ran it.
        try std.testing.expect(FinalTerms.eqlExact(&pm.ctx, pm.result, FinalTerms.int(&pm.ctx, 99)));
        // a real child process was scheduled (index != parent) and exited normal.
        try std.testing.expect(vm.procs.items.len >= 2);
        try std.testing.expectEqual(ia.Status.halted, vm.procs.items[1].machine.status);
    }
}

test "E21.1 FUN-SPAWN LINK: spawn_link/1 of a fun that boots propagates {'EXIT',Child,boom} under trap_exit (link-exit-propagation via a compiled closure, DIVERGENCE 450)" {
    // The linked-fun half (the sf2:lk corpus shape: spawn_link(fun() -> exit(boom)
    // end) with trap_exit). spawn_link_1 installs the link ATOMICALLY before the
    // child runs, so the child's abnormal exit delivers an {'EXIT',ChildPid,boom}
    // message to the trapping parent (never kills it). Bounded driver.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const boom = try atoms.intern("boom");

    // CHILD fun body @label 0: exit(boom) via the exit_proc trap. PARENT @label 2:
    // trap_exit := true, spawn_link_1 the fun, receive the 'EXIT' tuple, halt with
    // its reason (elem 3). `loop_rec`'s else_to points at the halt so a not-yet-
    // delivered signal re-loops via wait-wake, and post-receive control flows
    // straight into the halt (no re-suspend).
    const prog: ia.Program = &.{
        .{ .exit_proc = .{ .reason = .{ .atom_ = @intCast(boom) } } }, // 0: child exit(boom)
        .{ .wait = .{ .to = 5 } }, //                                    1: parent WAIT_P (re-enter loop_rec)
        .{ .trap_exits = .{ .on = true } }, //                           2: parent trap_exit
        .{ .make_fun3 = .{ .to = 0, .arity = 0, .dst = .{ .x = 0 }, .env = &.{} } }, // 3: fun @0
        bifCall(&procsys.spawn_link_1, .{ .{ .x = 0 }, .nil, .nil }, 1, 0), // 4: spawn_link_1 → child pid
        .{ .loop_rec = .{ .else_to = 1, .dst = 3 } }, //                 5: receive {'EXIT',P,boom} → x3 (else WAIT)
        .remove_message, //                                             6: commit
        .{ .get_tuple_elem = .{ .src = .{ .x = 3 }, .index = 2, .dst = .{ .x = 0 } } }, // 7: x0 = reason
        .{ .halt = .{ .src = .{ .x = 0 } } }, //                         8: halt with the reason
    };

    inline for (.{ @as(Scheduler, .round_robin), Scheduler{ .seeded = 0xB007 } }) |sched| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const parent = try vm.spawn(prog, 2, null);
        try sched.drive(&vm, 20, 4000);
        const pm = &vm.procs.items[parent].machine;
        // parent SURVIVED (trapped the exit) and halted with the propagated reason.
        try std.testing.expectEqual(ia.Status.halted, pm.status);
        try std.testing.expect(FinalTerms.eqlExact(&pm.ctx, pm.result, FinalTerms.atom(&pm.ctx, boom)));
    }
}

test "E3.7 SEND/RECEIVE HOMOMORPHISM: same-sender messages observed in send order (mailbox FIFO)" {
    // Two messages sent to a pid by ONE sender are read by loop_rec in SEND
    // order, exactly once each — mailbox conservation + per-pair FIFO. Mutant 2
    // (delivery enqueues at the mailbox HEAD, LIFO) reverses the read order and
    // fails this law.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // Drive the two sends through the copy boundary (as the M7 copy-law test
    // does), then read via loop_rec — this isolates delivery order from
    // scheduling races so the mutant target (delivery order) is what the law sees.
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const rprog: ia.Program = &.{
        .{ .loop_rec = .{ .else_to = 5, .dst = 1 } }, // 0: first msg → x1
        .remove_message, //                              1
        .{ .loop_rec = .{ .else_to = 5, .dst = 2 } }, // 2: second msg → x2
        .remove_message, //                              3
        .{ .halt = .{ .src = .{ .x = 1 } } }, //          4: result = x1 (the FIRST-received)
        .{ .wait = .{ .to = 0 } }, //                     5
    };
    const rx = try vm.spawn(rprog, 0, null);
    const sender = try vm.spawn(rprog, 5, null); // sender just idles/suspends
    const sp = vm.procs.items[sender];
    // sender sends 1 then 2 to rx (same ordered pair) through the copy boundary.
    for ([_]i64{ 1, 2 }) |v| {
        sp.machine.pending = .{ .send_to = .{ .pid = try FinalTerms.pid(&sp.machine.ctx, rx, 0), .msg = FinalTerms.int(&sp.machine.ctx, v) } };
        try vm.interpret(sender);
    }
    try (@as(Scheduler, .round_robin)).drive(&vm, 20, 2000);
    const rm = &vm.procs.items[rx].machine;
    try std.testing.expectEqual(ia.Status.halted, rm.status);
    // FIRST received must be 1 (send order), NOT 2 (LIFO would give 2 → mutant 2).
    try std.testing.expect(FinalTerms.eqlExact(&rm.ctx, rm.result, FinalTerms.int(&rm.ctx, 1)));
    // and BOTH were consumed exactly once (mailbox empty, cursor reset).
    try std.testing.expectEqual(@as(usize, 0), rm.mbox.len());
    try std.testing.expect(FinalTerms.eqlExact(&rm.ctx, rm.regs[2], FinalTerms.int(&rm.ctx, 2)));
}

test "E3.7 EXIT-SIGNAL over the bridge: exit/2 respects per-pair order; sacred law holds" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // B traps exits and idles; A sends B an exit signal via the exit/2 BIF trap
    // (exit_to). With trap_exit set, B receives {'EXIT', A, reason} — the exit
    // SIGNAL flowed through the same stamped signal path as messages, so the
    // sacred per-pair order is preserved.
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const b = try vm.spawn(idle, 0, null);
    const a = try vm.spawn(idle, 0, null);
    vm.procs.items[b].machine.trap_exit = true;
    const ap = vm.procs.items[a];
    // exit(BPid, kill_reason) through the BIF: sets the exit_to trap; the VM signals B.
    const reason = FinalTerms.int(&ap.machine.ctx, 99);
    ap.machine.pending = .{ .exit_to = .{ .pid = try FinalTerms.pid(&ap.machine.ctx, b, 0), .reason = reason } };
    try vm.interpret(a);
    try vm.drainSignals(b);

    // B still alive (trapped), holds {'EXIT', A, 99}.
    try std.testing.expect(vm.procs.items[b].alive);
    var qbuf: [8]mba.Msg(FinalTerms) = undefined;
    const q = vm.procs.items[b].machine.mbox.toSeq(&qbuf);
    try std.testing.expectEqual(@as(usize, 1), q.len);
    const t = q[0].payload;
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&vm.procs.items[b].machine.ctx, t));
    try std.testing.expect(checkPerPairOrder(vm.events.items)); // sacred law over the bridge
}

test "E3.7 BOUNDED-DRIVER + RECEIVE-WAKE: a blocked receiver reaches quiescence, wakes on delivery" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // A lone process that waits forever with NO message: the scheduler must
    // REACH QUIESCENCE (liveCount → 0 as it suspends) within the slice budget —
    // a hang would be a failed law, never a stuck suite.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const waiter: ia.Program = &.{
            .{ .loop_rec = .{ .else_to = 1, .dst = 0 } }, // 0
            .{ .wait = .{ .to = 0 } }, //                   1: suspend forever
        };
        const w = try vm.spawn(waiter, 0, null);
        try (@as(Scheduler, .round_robin)).drive(&vm, 5, 500); // returns (quiescent), no hang
        try std.testing.expectEqual(ia.Status.suspended, vm.procs.items[w].machine.status);
    }
    // Now the WAKE half: a suspended receiver resumes when a message is delivered
    // and re-enters loop_rec at its saved cursor to find it.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const rprog: ia.Program = &.{
            .{ .loop_rec = .{ .else_to = 3, .dst = 0 } }, // 0: msg → x0
            .remove_message, //                              1
            .{ .halt = .{ .src = .{ .x = 0 } } }, //          2: halt with the received value
            .{ .wait = .{ .to = 0 } }, //                     3: suspend until woken
        };
        const rx = try vm.spawn(rprog, 0, null);
        // Grant once: the receiver suspends (empty mailbox).
        try vm.grant(rx, 10);
        try std.testing.expectEqual(ia.Status.suspended, vm.procs.items[rx].machine.status);
        // Deliver a message (the send boundary) — signal() WAKES the suspended proc.
        const rp = vm.procs.items[rx];
        try vm.signal(rx, rx, .{ .message = FinalTerms.int(&rp.machine.ctx, 7) });
        try std.testing.expectEqual(ia.Status.running, rp.machine.status); // woken
        try (@as(Scheduler, .round_robin)).drive(&vm, 10, 500);
        try std.testing.expectEqual(ia.Status.halted, rp.machine.status);
        try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, rp.machine.result, FinalTerms.int(&rp.machine.ctx, 7)));
    }
}

test "E3.7 BACKWARD-COMPAT: a lone non-spawning program runs identically under the scheduler" {
    // The single-process model is preserved: a program with no spawn behaves the
    // same driven by the scheduler loop as by a bare Machine (the cli.zig upgrade
    // relies on this). Here: seq/sum-free arithmetic to a halt.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const prog: ia.Program = &.{
        .{ .add = .{ .a = .{ .imm = 20 }, .b = .{ .imm = 22 }, .dst = 0 } }, // 0: x0 = 42
        .{ .halt = .{ .src = .{ .x = 0 } } }, //                                1
    };
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const p = try vm.spawn(prog, 0, null);
    try (@as(Scheduler, .round_robin)).drive(&vm, 7, 100);
    const m = &vm.procs.items[p].machine;
    try std.testing.expectEqual(ia.Status.halted, m.status);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.result, FinalTerms.int(&m.ctx, 42)));
}

// ============================================================================
// E3.8: link/monitor/registry process BIFs — the entry-11 remainder. These
// laws exercise the BIF SURFACE (`bifs/procsys.zig`'s `link_1`/`monitor_2`/
// `register_2`/`whereis_1`/`demonitor_2`/…) through THIS Vm, over proc.zig's
// ALREADY-LAW-COVERED link/monitor signal machinery (the "Links"/"Monitors"
// test suites above) plus the NEW registry integration (`Vm.registry`, DEATH
// unregisters via `terminate`/`normalExit`) and the demonitor-flush race
// guard (`doDemonitorFlush`). All bounded/observational, exactly E3.7's shape.
// ============================================================================

test "E3.8 WORKED LAW: register/whereis/link/monitor BIFs round-trip through the Vm bridge" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const crasher: ia.Program = &.{
        .{ .exit_proc = .{ .reason = .{ .imm = 42 } } },
    };
    const a = try vm.spawn(crasher, 0, null); // will exit(42)
    const b = try vm.spawn(idle, 0, null);
    vm.procs.items[b].machine.trap_exit = true;
    const ap = vm.procs.items[a];
    const bp = vm.procs.items[b];

    // A registers itself as `worker` via the register/2 BIF surface.
    const name = FinalTerms.atom(&ap.machine.ctx, try atoms.intern("worker"));
    const a_pid_term = try FinalTerms.pid(&ap.machine.ctx, a, 0);
    ap.machine.pending = .{ .register_name = .{ .name = name, .pid = a_pid_term } };
    try vm.interpret(a);
    try std.testing.expect(FinalTerms.eqlExact(&ap.machine.ctx, ap.machine.regs[0], FinalTerms.atom(&ap.machine.ctx, ap.machine.bool_true)));

    // B resolves it via whereis/1 (registry bijection, now Vm-owned).
    const bname = FinalTerms.atom(&bp.machine.ctx, try atoms.intern("worker"));
    bp.machine.pending = .{ .whereis_name = .{ .name = bname } };
    try vm.interpret(b);
    try std.testing.expect(FinalTerms.repIsPid(&bp.machine.ctx, bp.machine.regs[0]));
    try std.testing.expectEqual(@as(u64, a), FinalTerms.pidNumber(&bp.machine.ctx, bp.machine.regs[0]));

    // B links to A (link/1 → link_to, bidirectional, already M7-law-covered)
    // and monitors A (monitor/2 → monitor_to) — BOTH via the BIF surface.
    const a_term_b_heap = try FinalTerms.pid(&bp.machine.ctx, a, 0);
    bp.machine.pending = .{ .link_to = .{ .pid = a_term_b_heap } };
    try vm.interpret(b);
    bp.machine.pending = .{ .monitor_to = .{ .pid = a_term_b_heap, .dst = 5 } };
    try vm.interpret(b);
    const mref = bp.machine.regs[5];
    try vm.drainSignals(a); // A records the link

    // A exits(42) — the link fires an {'EXIT',A,42} to trapping B AND the
    // monitor fires exactly one 'DOWN'; the registry DEATH law unregisters A.
    try vm.grant(a, 20);
    try vm.drainSignals(b);
    try std.testing.expect(bp.machine.mbox.len() == 2); // {'EXIT',...} + {'DOWN',...}

    // whereis(worker) is now `undefined` — DEATH unregistered A.
    bp.machine.pending = .{ .whereis_name = .{ .name = bname } };
    try vm.interpret(b);
    const undef_name = try atoms.intern("undefined");
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, bp.machine.regs[0], FinalTerms.atom(&bp.machine.ctx, undef_name)));
    _ = mref;
}

test "E3.8 MONITOR EXACTLY-ONCE: demonitor(Ref,[flush]) clears a race DOWN, queued or already delivered" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const crasher: ia.Program = &.{
        .{ .exit_proc = .{ .reason = .{ .imm = 55 } } },
    };
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };

    // (a) the exit signal is QUEUED (not yet drained) when demonitor(flush) runs.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const w = try vm.spawn(idle, 0, null);
        const t = try vm.spawn(crasher, 0, null);
        const wp = vm.procs.items[w];
        const t_term = try FinalTerms.pid(&wp.machine.ctx, t, 0);
        wp.machine.pending = .{ .monitor_to = .{ .pid = t_term, .dst = 5 } };
        try vm.interpret(w);
        const ref = wp.machine.regs[5];
        try vm.grant(t, 10); // t exits, enqueues a .down signal into w.sigq (undrained)
        try std.testing.expectEqual(@as(usize, 1), wp.sigq.items.len);
        const flush_opts = try FinalTerms.cons(&wp.machine.ctx, FinalTerms.atom(&wp.machine.ctx, try atoms.intern("flush")), FinalTerms.nil(&wp.machine.ctx));
        wp.machine.pending = .{ .demonitor_flush = .{ .ref = ref, .info = false } };
        try vm.interpret(w);
        _ = flush_opts;
        try std.testing.expectEqual(@as(usize, 0), wp.sigq.items.len); // race-queued DOWN dropped
        try vm.drainSignals(w);
        try std.testing.expectEqual(@as(usize, 0), wp.machine.mbox.len()); // never observed
    }
    // (b) the DOWN is ALREADY DELIVERED to the mailbox when demonitor(flush) runs.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const w = try vm.spawn(idle, 0, null);
        const t = try vm.spawn(crasher, 0, null);
        const wp = vm.procs.items[w];
        const t_term = try FinalTerms.pid(&wp.machine.ctx, t, 0);
        wp.machine.pending = .{ .monitor_to = .{ .pid = t_term, .dst = 5 } };
        try vm.interpret(w);
        const ref = wp.machine.regs[5];
        try vm.grant(t, 10);
        try vm.drainSignals(w); // DOWN now sits in w's mailbox
        try std.testing.expectEqual(@as(usize, 1), wp.machine.mbox.len());
        wp.machine.pending = .{ .demonitor_flush = .{ .ref = ref, .info = false } };
        try vm.interpret(w);
        try std.testing.expectEqual(@as(usize, 0), wp.machine.mbox.len()); // flush removed it
    }
    // (c) PLAIN demonitor (no flush) does NOT retroactively remove an
    // already-delivered DOWN — contrasts (b), proving `flush` is load-bearing.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const w = try vm.spawn(idle, 0, null);
        const t = try vm.spawn(crasher, 0, null);
        const wp = vm.procs.items[w];
        const t_term = try FinalTerms.pid(&wp.machine.ctx, t, 0);
        wp.machine.pending = .{ .monitor_to = .{ .pid = t_term, .dst = 5 } };
        try vm.interpret(w);
        const ref = wp.machine.regs[5];
        try vm.grant(t, 10);
        try vm.drainSignals(w);
        try std.testing.expectEqual(@as(usize, 1), wp.machine.mbox.len());
        wp.machine.pending = .{ .demonitor_ref = .{ .ref = ref, .info = false } };
        try vm.interpret(w);
        try std.testing.expectEqual(@as(usize, 1), wp.machine.mbox.len()); // unchanged
    }
    // (d) grant more slices after a flush: still exactly zero DOWNs ever seen.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const w = try vm.spawn(idle, 0, null);
        const t = try vm.spawn(crasher, 0, null);
        const wp = vm.procs.items[w];
        const t_term = try FinalTerms.pid(&wp.machine.ctx, t, 0);
        wp.machine.pending = .{ .monitor_to = .{ .pid = t_term, .dst = 5 } };
        try vm.interpret(w);
        const ref = wp.machine.regs[5];
        try vm.grant(t, 10);
        wp.machine.pending = .{ .demonitor_flush = .{ .ref = ref, .info = false } };
        try vm.interpret(w);
        try vm.grant(w, 10);
        try std.testing.expectEqual(@as(usize, 0), wp.machine.mbox.len());
    }
}

test "E3.8 REGISTRY BIJECTION: register/2 RAISES badarg on a duplicate name or an already-registered pid (gap-erlang-cover-registry, DIVERGENCE 658)" {
    // OTP semantics (curation-found via eco_registry): register/2 and unregister/1
    // are RAISING BIFs — every rejection is `error:badarg`, never a `false` return.
    // The rejection paths are law-tested by calling the handlers DIRECTLY (they
    // return `error.Badarg`); the SUCCESS paths + the callsite raise-wiring are
    // driven through `interpret` (a separate law below covers the wiring).
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const p1 = try vm.spawn(idle, 0, null);
    const p2 = try vm.spawn(idle, 0, null);
    const owner = vm.procs.items[p1];
    const mc = &owner.machine;

    const name1 = FinalTerms.atom(&mc.ctx, try atoms.intern("alpha"));
    const name2 = FinalTerms.atom(&mc.ctx, try atoms.intern("beta"));
    const undef_name = FinalTerms.atom(&mc.ctx, try atoms.intern("undefined"));
    const p1_term = try FinalTerms.pid(&mc.ctx, p1, 0);
    const p2_term = try FinalTerms.pid(&mc.ctx, p2, 0);
    const true_t = FinalTerms.atom(&mc.ctx, mc.bool_true);

    // register(alpha, P1) succeeds → the atom `true`.
    try std.testing.expect(FinalTerms.eqlExact(&mc.ctx, try vm.doRegister(mc, p1, name1, p1_term), true_t));

    // register(alpha, P2): DUPLICATE NAME → error:badarg (never overwrites).
    try std.testing.expectError(error.Badarg, vm.doRegister(mc, p1, name1, p2_term));
    // register(beta, P1): P1 ALREADY registered (under alpha) → error:badarg.
    // Mutant target: if this bijection check is skipped, this wrongly succeeds,
    // letting one pid answer to two names.
    try std.testing.expectError(error.Badarg, vm.doRegister(mc, p1, name2, p1_term));
    try std.testing.expect(vm.registry.whereis(FinalTerms.atomIdxOf(name2)) == null); // beta stays unbound
    // register(undefined, P1): the RESERVED whereis-sentinel name → error:badarg.
    try std.testing.expectError(error.Badarg, vm.doRegister(mc, p1, undef_name, p1_term));

    // whereis(alpha) still resolves to P1 (unaffected by the three rejections).
    owner.machine.pending = .{ .whereis_name = .{ .name = name1 } };
    try vm.interpret(p1);
    try std.testing.expect(FinalTerms.repIsPid(&mc.ctx, mc.regs[0]));
    try std.testing.expectEqual(@as(u64, p1), FinalTerms.pidNumber(&mc.ctx, mc.regs[0]));

    // unregister(alpha) succeeds → `true`; then whereis(alpha) → undefined.
    try std.testing.expect(FinalTerms.eqlExact(&mc.ctx, try vm.doUnregister(mc, name1), true_t));
    // unregister(alpha) AGAIN (now unknown) → error:badarg.
    try std.testing.expectError(error.Badarg, vm.doUnregister(mc, name1));
    owner.machine.pending = .{ .whereis_name = .{ .name = name1 } };
    try vm.interpret(p1);
    const undef_idx = try atoms.intern("undefined");
    try std.testing.expect(FinalTerms.eqlExact(&mc.ctx, mc.regs[0], FinalTerms.atom(&mc.ctx, undef_idx)));

    // register a DEAD pid → error:badarg (registry's alive-check).
    try vm.grant(p2, 10);
    const p2p = vm.procs.items[p2];
    p2p.machine.pending = .{ .exit_proc = .{ .reason = FinalTerms.int(&p2p.machine.ctx, 1) } };
    try vm.interpret(p2);
    const name3 = FinalTerms.atom(&mc.ctx, try atoms.intern("gamma"));
    try std.testing.expectError(error.Badarg, vm.doRegister(mc, p1, name3, p2_term));
}

test "gap-erlang-cover-registry WIRING: a rejected register CRASHES an uncaught process with error:badarg (DIVERGENCE 658)" {
    // Proves the callsite converts doRegister's `error.Badarg` into a catchable
    // `raiseErrorAtom(badarg)` (not a swallowed `false`). With no catch frame the
    // raise sets status=.crashed + result=badarg — the exact catchable class the
    // compiled eco_registry differential observes as `{'EXIT',{badarg,_}}`.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const p1 = try vm.spawn(idle, 0, null);
    const p2 = try vm.spawn(idle, 0, null);
    const owner = vm.procs.items[p1];
    const mc = &owner.machine;
    const name1 = FinalTerms.atom(&mc.ctx, try atoms.intern("alpha"));
    const p1_term = try FinalTerms.pid(&mc.ctx, p1, 0);
    const p2_term = try FinalTerms.pid(&mc.ctx, p2, 0);

    // register(alpha, P1) via the trap succeeds (status stays runnable).
    owner.machine.pending = .{ .register_name = .{ .name = name1, .pid = p1_term } };
    try vm.interpret(p1);
    try std.testing.expect(FinalTerms.eqlExact(&mc.ctx, mc.regs[0], FinalTerms.atom(&mc.ctx, mc.bool_true)));
    try std.testing.expect(mc.status != .crashed);

    // register(alpha, P2) via the trap (DUP NAME) → the process CRASHES with badarg.
    owner.machine.pending = .{ .register_name = .{ .name = name1, .pid = p2_term } };
    try vm.interpret(p1);
    try std.testing.expectEqual(ia.Status.crashed, mc.status);
    try std.testing.expect(FinalTerms.eqlExact(&mc.ctx, mc.result, FinalTerms.atom(&mc.ctx, mc.badarg)));
}

test "LAW e4-registered0 registered/0 denotes the SORTED registered-name list (registry-backed, ORDER-FREEDOM)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const p1 = try vm.spawn(idle, 0, null);
    const owner = vm.procs.items[p1];

    // an EMPTY registry denotes [].
    owner.machine.pending = .list_registered;
    try vm.interpret(p1);
    try std.testing.expect(FinalTerms.eqlExact(&owner.machine.ctx, owner.machine.regs[0], FinalTerms.nil(&owner.machine.ctx)));

    // register THREE names OUT of alphabetic order, on THREE DISTINCT pids
    // (the registry bijection allows only ONE name per pid — see the
    // "REGISTRY BIJECTION" test above) — registered() must denote them
    // name-SORTED regardless of the registry HashMap's insertion/iteration
    // order (Mutant target: an unsorted / insertion-order answer would still
    // pass a same-set-membership check but fail this EXACT ordered
    // comparison).
    const p2 = try vm.spawn(idle, 0, null);
    const p3 = try vm.spawn(idle, 0, null);
    const p1_term = try FinalTerms.pid(&owner.machine.ctx, p1, 0);
    const p2_term = try FinalTerms.pid(&owner.machine.ctx, p2, 0);
    const p3_term = try FinalTerms.pid(&owner.machine.ctx, p3, 0);
    const zed = FinalTerms.atom(&owner.machine.ctx, try atoms.intern("zed"));
    const amy = FinalTerms.atom(&owner.machine.ctx, try atoms.intern("amy"));
    const mid = FinalTerms.atom(&owner.machine.ctx, try atoms.intern("mid"));
    owner.machine.pending = .{ .register_name = .{ .name = zed, .pid = p1_term } };
    try vm.interpret(p1);
    owner.machine.pending = .{ .register_name = .{ .name = amy, .pid = p2_term } };
    try vm.interpret(p1);
    owner.machine.pending = .{ .register_name = .{ .name = mid, .pid = p3_term } };
    try vm.interpret(p1);

    owner.machine.pending = .list_registered;
    try vm.interpret(p1);
    const got = owner.machine.regs[0];
    try std.testing.expect(FinalTerms.kindOf(&owner.machine.ctx, got) == .cons);
    const expected = try FinalTerms.cons(&owner.machine.ctx, amy, try FinalTerms.cons(&owner.machine.ctx, mid, try FinalTerms.cons(&owner.machine.ctx, zed, FinalTerms.nil(&owner.machine.ctx))));
    try std.testing.expect(FinalTerms.eqlExact(&owner.machine.ctx, got, expected));

    // DEATH unregisters (the registry.zig law) — killing p1/p2/p3 shrinks
    // registered() back to [].
    owner.machine.pending = .{ .exit_proc = .{ .reason = FinalTerms.int(&owner.machine.ctx, 1) } };
    try vm.interpret(p1);
    const p2o = vm.procs.items[p2];
    p2o.machine.pending = .{ .exit_proc = .{ .reason = FinalTerms.int(&p2o.machine.ctx, 1) } };
    try vm.interpret(p2);
    const p3o = vm.procs.items[p3];
    p3o.machine.pending = .{ .exit_proc = .{ .reason = FinalTerms.int(&p3o.machine.ctx, 1) } };
    try vm.interpret(p3);

    const p4 = try vm.spawn(idle, 0, null);
    const p4o = vm.procs.items[p4];
    p4o.machine.pending = .list_registered;
    try vm.interpret(p4);
    try std.testing.expect(FinalTerms.eqlExact(&p4o.machine.ctx, p4o.machine.regs[0], FinalTerms.nil(&p4o.machine.ctx)));
}

test "E3.8 process_info/1,2 over the Vm: documented items, dead pid -> undefined" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const a = try vm.spawn(idle, 0, null);
    const b = try vm.spawn(idle, 0, null);
    const bp = vm.procs.items[b];

    // wire a link + a registration on A, then query A's process_info from B.
    const a_term = try FinalTerms.pid(&bp.machine.ctx, a, 0);
    bp.machine.pending = .{ .link_to = .{ .pid = a_term } };
    try vm.interpret(b);
    try vm.drainSignals(a);
    const name = FinalTerms.atom(&bp.machine.ctx, try atoms.intern("alice"));
    bp.machine.pending = .{ .register_name = .{ .name = name, .pid = a_term } };
    try vm.interpret(b);

    bp.machine.pending = .{ .process_info_all = .{ .pid = a_term } };
    try vm.interpret(b);
    const list = bp.machine.regs[0];
    try std.testing.expectEqual(FinalTerms.Kind.cons, FinalTerms.kindOf(&bp.machine.ctx, list));

    // single-item form: registered_name → {registered_name, alice}.
    bp.machine.pending = .{ .process_info_item = .{ .pid = a_term, .item = name } };
    // (item is meaningless here — real callers pass an ATOM naming the item,
    // not the registered NAME; use the real item atom instead.)
    const rn_item = FinalTerms.atom(&bp.machine.ctx, try atoms.intern("registered_name"));
    bp.machine.pending = .{ .process_info_item = .{ .pid = a_term, .item = rn_item } };
    try vm.interpret(b);
    const tup = bp.machine.regs[0];
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&bp.machine.ctx, tup));
    try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&bp.machine.ctx, tup));
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, FinalTerms.tupleElem(&bp.machine.ctx, tup, 1), name));

    // an UNREGISTERED process's registered_name item is the bare atom `[]` — the
    // WHOLE result is nil, NOT a `{registered_name, []}` tuple (erts quirk; e21-t2b
    // DIVERGENCE 490-amend fixed the single-item /2 path to honor it, host-verified
    // against OTP-30: `process_info(self(),registered_name)` = `[]`).
    const c = try vm.spawn(idle, 0, null);
    const cp = vm.procs.items[c];
    const c_term = try FinalTerms.pid(&bp.machine.ctx, c, 0);
    _ = cp;
    bp.machine.pending = .{ .process_info_item = .{ .pid = c_term, .item = rn_item } };
    try vm.interpret(b);
    const tup2 = bp.machine.regs[0];
    try std.testing.expectEqual(FinalTerms.Kind.nil, FinalTerms.kindOf(&bp.machine.ctx, tup2));

    // a DEAD pid's process_info is the WHOLE atom `undefined`.
    const dead_term = try FinalTerms.pid(&bp.machine.ctx, 9999, 0);
    bp.machine.pending = .{ .process_info_all = .{ .pid = dead_term } };
    try vm.interpret(b);
    const undef_idx = try atoms.intern("undefined");
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, bp.machine.regs[0], FinalTerms.atom(&bp.machine.ctx, undef_idx)));
}

test "LAW gap-stdlib-bif-audit process_info(Pid,{dictionary,Key}): present->value, absent->undefined (the proc_lib $initial_call path)" {
    // process_info/2 with the TUPLE item {dictionary, Key} projects ONE key of
    // the target's process dictionary — the exact byte-total item proc_lib reads
    // for `$initial_call`/`$process_label`. Host-verified on the pin:
    //   present key  -> {{dictionary, Key}, StoredValue}
    //   absent key   -> {{dictionary, Key}, undefined}   (the ATOM undefined, not [])
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const a = try vm.spawn(idle, 0, null);
    const b = try vm.spawn(idle, 0, null);
    const ap = vm.procs.items[a];
    const bp = vm.procs.items[b];

    // Seed A's dictionary directly (S24 pdict-map homomorphism: the map term is
    // read/written with term_algebra's map ops VERBATIM). Store
    //   '$initial_call' => {m, f, 3}
    const key_idx = try atoms.intern("$initial_call");
    const a_key = FinalTerms.atom(&ap.machine.ctx, key_idx);
    const mfa = try FinalTerms.tuple(&ap.machine.ctx, &.{
        FinalTerms.atom(&ap.machine.ctx, try atoms.intern("m")),
        FinalTerms.atom(&ap.machine.ctx, try atoms.intern("f")),
        FinalTerms.int(&ap.machine.ctx, 3),
    });
    ap.machine.pdict = try FinalTerms.mapPut(&ap.machine.ctx, ap.machine.pdict, a_key, mfa);

    // From B, ask A for {dictionary, '$initial_call'} — a PRESENT key.
    const a_term = try FinalTerms.pid(&bp.machine.ctx, a, 0);
    const b_key = FinalTerms.atom(&bp.machine.ctx, key_idx);
    const dict_atom = FinalTerms.atom(&bp.machine.ctx, try atoms.intern("dictionary"));
    const item_present = try FinalTerms.tuple(&bp.machine.ctx, &.{ dict_atom, b_key });
    bp.machine.pending = .{ .process_info_item = .{ .pid = a_term, .item = item_present } };
    try vm.interpret(b);
    const r1 = bp.machine.regs[0];
    // Shape: {{dictionary, '$initial_call'}, {m,f,3}} — a 2-tuple whose element 0
    // is the ITEM tuple and element 1 is the stored value.
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&bp.machine.ctx, r1));
    try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&bp.machine.ctx, r1));
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, FinalTerms.tupleElem(&bp.machine.ctx, r1, 0), item_present));
    // element 1 == the stored {m,f,3}, copied into B's heap — compare by value.
    const want_mfa = try FinalTerms.tuple(&bp.machine.ctx, &.{
        FinalTerms.atom(&bp.machine.ctx, try atoms.intern("m")),
        FinalTerms.atom(&bp.machine.ctx, try atoms.intern("f")),
        FinalTerms.int(&bp.machine.ctx, 3),
    });
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, FinalTerms.tupleElem(&bp.machine.ctx, r1, 1), want_mfa));

    // ABSENT key → {{dictionary, nope}, undefined} (the atom undefined).
    const nope = FinalTerms.atom(&bp.machine.ctx, try atoms.intern("nope"));
    const item_absent = try FinalTerms.tuple(&bp.machine.ctx, &.{ dict_atom, nope });
    bp.machine.pending = .{ .process_info_item = .{ .pid = a_term, .item = item_absent } };
    try vm.interpret(b);
    const r2 = bp.machine.regs[0];
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&bp.machine.ctx, r2));
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, FinalTerms.tupleElem(&bp.machine.ctx, r2, 0), item_absent));
    const undef = FinalTerms.atom(&bp.machine.ctx, try atoms.intern("undefined"));
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, FinalTerms.tupleElem(&bp.machine.ctx, r2, 1), undef));
}

test "E3.8 group_leader inheritance + erts_internal:group_leader/2,3 setter" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // a fresh top-level spawn is its OWN group leader.
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const a = try vm.spawn(idle, 0, null);
    try std.testing.expectEqual(a, vm.procs.items[a].machine.group_leader);

    // a spawn_fun-spawned child inherits its PARENT's group leader.
    const child_body: ia.Program = &.{
        .{ .halt = .{ .src = .{ .imm = 0 } } },
        .{ .recv_any = .{ .dst = 0, .else_to = 2 } },
        .{ .jump = .{ .to = 1 } },
    };
    const fun = try FinalTerms.makeFun(&vm.procs.items[a].machine.ctx, 0, 0, &.{});
    vm.procs.items[a].machine.pending = .{ .spawn_fun = .{ .fun = fun, .link = false } };
    try vm.interpret(a);
    const child = FinalTerms.pidNumber(&vm.procs.items[a].machine.ctx, vm.procs.items[a].machine.regs[0]);
    try std.testing.expectEqual(a, vm.procs.items[@intCast(child)].machine.group_leader);
    _ = child_body;

    // erts_internal:group_leader/2 retargets a DIFFERENT process's leader.
    const b = try vm.spawn(idle, 0, null);
    const bp = vm.procs.items[b];
    const a_term = try FinalTerms.pid(&bp.machine.ctx, a, 0);
    const b_term = try FinalTerms.pid(&bp.machine.ctx, b, 0);
    bp.machine.pending = .{ .set_group_leader = .{ .leader = a_term, .pid = b_term } };
    try vm.interpret(b);
    try std.testing.expect(FinalTerms.eqlExact(&bp.machine.ctx, bp.machine.regs[0], FinalTerms.atom(&bp.machine.ctx, bp.machine.bool_true)));
    try std.testing.expectEqual(a, vm.procs.items[b].machine.group_leader);
}

test "LAW E5.3 GL-SETTER READBACK: a retargeted process's own group_leader/0 observes the new leader" {
    // The observability that flips erts_internal:group_leader/2,3 EQ (the
    // `glset` corpus case, representation-free): after `group_leader(A, B)`, B's
    // OWN `group_leader()` (the already-EQ get form) returns A — NOT B's
    // inherited leader. Pins that the SETTER mutates the TARGET, and that the
    // GET form reads the mutation. Mutant E5.3 m2 (set the CALLER's leader
    // instead of the target's) reddens this.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const a = try vm.spawn(idle, 0, null);
    const b = try vm.spawn(idle, 0, null);
    // B starts as its OWN leader (a top-level spawn) — distinct from A.
    try std.testing.expectEqual(b, vm.procs.items[b].machine.group_leader);

    // The caller (A) retargets B's leader to A.
    const ap = vm.procs.items[a];
    const a_term = try FinalTerms.pid(&ap.machine.ctx, a, 0);
    const b_term = try FinalTerms.pid(&ap.machine.ctx, b, 0);
    ap.machine.pending = .{ .set_group_leader = .{ .leader = a_term, .pid = b_term } };
    try vm.interpret(a);

    // B's OWN group_leader/0 now observes A (the get form the corpus reads).
    const bm = &vm.procs.items[b].machine;
    const gl = try procsys.group_leader_0(bm, &.{});
    try std.testing.expectEqual(a, FinalTerms.pidNumber(&bm.ctx, gl));
    // The caller A's own leader is UNCHANGED (the setter touched only B).
    try std.testing.expectEqual(a, vm.procs.items[a].machine.group_leader);
}

// ============================================================================
// E5.6 (Task 6): the async spawn/request protocol law suite (DIVERGENCE 72).
// ============================================================================

test "E5.6 SPAWN-REPLY PROTOCOL: spawn_request parks EXACTLY ONE {spawn_reply,ReqId,ok,Pid} carrying the minted ReqId, delivered on the next tick" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const req = try vm.spawn(idle, 0, null);
    const rp = vm.procs.items[req];
    const ma = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("m"));
    const fa = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("f"));
    const monitor_atom = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("monitor"));
    const opts = try FinalTerms.cons(&rp.machine.ctx, monitor_atom, FinalTerms.nil(&rp.machine.ctx));
    rp.machine.pending = .{ .spawn_request = .{ .module = ma, .func = fa, .args = FinalTerms.nil(&rp.machine.ctx), .opts = opts } };
    try vm.interpret(req);
    const reqid = rp.machine.regs[0];
    try std.testing.expect(FinalTerms.repIsRef(&rp.machine.ctx, reqid)); // ReqId is a ref

    // gap-b-3: the reply is STAGED by the trap (not written to the global list from
    // inside `interpret`), then APPLIED at the grant epilogue — so a bare `interpret`
    // leaves it in `staged_spawn`; `applyStagedParks` publishes it to `parked_spawn`
    // (identical set/order). This witnesses staged ≡ inline for the spawn park.
    try std.testing.expectEqual(@as(usize, 1), vm.staged_spawn.items.len);
    try std.testing.expectEqual(@as(usize, 0), vm.parked_spawn.items.len);
    try std.testing.expectEqual(@as(usize, 0), rp.machine.mbox.len());
    try vm.applyStagedParks(); // the grant-epilogue apply-point
    try std.testing.expectEqual(@as(usize, 0), vm.staged_spawn.items.len); // exactly-once: staging drained
    try std.testing.expectEqual(@as(usize, 1), vm.parked_spawn.items.len); // now in the global list

    // The reply is PARKED, not yet delivered — the async window (abandon can race).
    try std.testing.expectEqual(@as(usize, 0), rp.machine.mbox.len());

    // The scheduler tick flushes it; drain into the mailbox. EXACTLY ONE
    // spawn_reply arrives, carrying the SAME ReqId ref (Mutant 1: a fresh ref
    // reddens the reqid-eq check), `ok`, and the child pid.
    try vm.deliverParkedSpawn();
    try vm.drainSignals(req);
    var buf: [8]mba.Msg(FinalTerms) = undefined;
    const q = rp.machine.mbox.toSeq(&buf);
    var replies: usize = 0;
    var reqid_ok = false;
    for (q) |msg| {
        if (FinalTerms.kindOf(&rp.machine.ctx, msg.payload) == .tuple and FinalTerms.tupleArity(&rp.machine.ctx, msg.payload) == 4) {
            const tag = FinalTerms.tupleElem(&rp.machine.ctx, msg.payload, 0);
            if (FinalTerms.repIsAtom(tag) and std.mem.eql(u8, atoms.nameOf(FinalTerms.atomIdxOf(tag)), "spawn_reply")) {
                replies += 1;
                const rid = FinalTerms.tupleElem(&rp.machine.ctx, msg.payload, 1);
                const res = FinalTerms.tupleElem(&rp.machine.ctx, msg.payload, 2);
                const child = FinalTerms.tupleElem(&rp.machine.ctx, msg.payload, 3);
                if (FinalTerms.eqlExact(&rp.machine.ctx, rid, reqid) and
                    FinalTerms.repIsAtom(res) and std.mem.eql(u8, atoms.nameOf(FinalTerms.atomIdxOf(res)), "ok") and
                    FinalTerms.repIsPid(&rp.machine.ctx, child)) reqid_ok = true;
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 1), replies); // EXACTLY ONE reply
    try std.testing.expect(reqid_ok);
    try std.testing.expectEqual(@as(usize, 0), vm.parked_spawn.items.len); // window closed
}

// LAW E25-T4 — the DARK scheduler-side `doDistSpawnRequest` arms (E25 Task 4, the
// dist-spawn cluster). The BIF-level `dist_spawn_request/4` surface is tested in
// bifs/procsys (E8.2i); the proc.zig HANDLER that actually delivers the error
// reply + returns the mode-specific shape was never driven at the scheduler level.
//
// SEMANTIC DOMAIN. `erts_internal:dist_spawn_request/4` with NO live dist carrier
// mints a ReqId ref, delivers an error reply `{Tag, ReqId, error, Reason}` to the
// CALLER (Reason=`noconnection` — there is no peer), and returns: mode
// `spawn_request` → the bare ReqId ref; mode `spawn_opt` → `{ReqId, SpawnsMonitor}`
// (the second element is the monitor flag). When `send_error_reply=false` no
// message is delivered (the caller only observes the returned ref/tuple).
//
// OTP-30 CORRELATION. `erts/emulator/beam/erl_bif_ddll`/`dist.c` spawn-request
// path: a request to an unreachable node yields a `{spawn_reply, Ref, error,
// noconnection}` (or `notsup`) message to the requester and the async ReqId, exactly
// the no-carrier surface this VM models (the direct-BIF doorway, DIVERGENCE-bounded
// to no live remote spawn). This law pins the HANDLER's observable: the delivered
// message shape + the per-mode return, and the `send_error_reply=false` silence.
//
// Mutants MUTATION_LOG e25-t4 m1 (spawn_opt returns a bare ref, not {ref,bool}) /
// m2 (send_error_reply=false still delivers a message).
test "LAW E25-T4 doDistSpawnRequest no-carrier: error reply {Tag,Ref,error,noconnection} + per-mode return; no reply when suppressed (OTP-30 dist_spawn_request/4)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const req = try vm.spawn(idle, 0, null);
    const rp = vm.procs.items[req];
    const ctx = &rp.machine.ctx;
    const tag = FinalTerms.atom(ctx, try atoms.intern("spawn_reply"));
    const reason = FinalTerms.atom(ctx, try atoms.intern("noconnection"));

    // (1) mode = spawn_request, send_error_reply = true → bare ref return + an
    //     {spawn_reply, Ref, error, noconnection} message to the caller.
    rp.machine.pending = .{ .dist_spawn_request = .{
        .mode = .spawn_request,
        .spawns_monitor = false,
        .send_error_reply = true,
        .tag = tag,
        .error_reason = reason,
    } };
    try vm.interpret(req);
    const r1 = rp.machine.regs[0];
    try std.testing.expect(FinalTerms.repIsRef(ctx, r1)); // spawn_request → bare ref
    {
        var buf: [8]mba.Msg(FinalTerms) = undefined;
        const q = rp.machine.mbox.toSeq(&buf);
        try std.testing.expectEqual(@as(usize, 1), q.len);
        const p = q[0].payload;
        try std.testing.expect(FinalTerms.kindOf(ctx, p) == .tuple and FinalTerms.tupleArity(ctx, p) == 4);
        const et = FinalTerms.tupleElem(ctx, p, 0);
        const err = FinalTerms.tupleElem(ctx, p, 2);
        const rsn = FinalTerms.tupleElem(ctx, p, 3);
        try std.testing.expect(FinalTerms.repIsAtom(et) and std.mem.eql(u8, atoms.nameOf(FinalTerms.atomIdxOf(et)), "spawn_reply"));
        try std.testing.expect(FinalTerms.repIsAtom(err) and std.mem.eql(u8, atoms.nameOf(FinalTerms.atomIdxOf(err)), "error"));
        try std.testing.expect(FinalTerms.repIsAtom(rsn) and std.mem.eql(u8, atoms.nameOf(FinalTerms.atomIdxOf(rsn)), "noconnection"));
        // the ReqId in the message is the returned ref.
        try std.testing.expect(FinalTerms.eqlExact(ctx, FinalTerms.tupleElem(ctx, p, 1), r1));
    }

    // (2) mode = spawn_opt, spawns_monitor = true → {Ref, true} return (+ reply).
    //     Mailbox is cumulative (no clear API): it grows 1 → 2.
    rp.machine.pending = .{ .dist_spawn_request = .{
        .mode = .spawn_opt,
        .spawns_monitor = true,
        .send_error_reply = true,
        .tag = tag,
        .error_reason = reason,
    } };
    try vm.interpret(req);
    const r2 = rp.machine.regs[0];
    try std.testing.expect(FinalTerms.kindOf(ctx, r2) == .tuple and FinalTerms.tupleArity(ctx, r2) == 2);
    try std.testing.expect(FinalTerms.repIsRef(ctx, FinalTerms.tupleElem(ctx, r2, 0)));
    try std.testing.expect(FinalTerms.repIsAtom(FinalTerms.tupleElem(ctx, r2, 1)) and
        FinalTerms.atomIdxOf(FinalTerms.tupleElem(ctx, r2, 1)) == rp.machine.bool_true);
    try std.testing.expectEqual(@as(usize, 2), rp.machine.mbox.len()); // a 2nd error reply delivered

    // (3) send_error_reply = false → NO new message, only the returned ref.
    rp.machine.pending = .{ .dist_spawn_request = .{
        .mode = .spawn_request,
        .spawns_monitor = false,
        .send_error_reply = false,
        .tag = tag,
        .error_reason = reason,
    } };
    try vm.interpret(req);
    try std.testing.expect(FinalTerms.repIsRef(ctx, rp.machine.regs[0]));
    try std.testing.expectEqual(@as(usize, 2), rp.machine.mbox.len()); // unchanged — silence when suppressed
}

test "E5.6 ABANDON RACE: abandon BEFORE the tick returns true + orphans the child; abandon AFTER (or a foreign ref) returns false" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    // (a) abandon BEFORE the scheduler tick: the reply is still parked → true,
    //     and the caller's link to the child is dropped (orphaned).
    {
        const req = try vm.spawn(idle, 0, null);
        const rp = vm.procs.items[req];
        const ma = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("m"));
        const fa = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("f"));
        const link_atom = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("link"));
        const opts = try FinalTerms.cons(&rp.machine.ctx, link_atom, FinalTerms.nil(&rp.machine.ctx));
        rp.machine.pending = .{ .spawn_request = .{ .module = ma, .func = fa, .args = FinalTerms.nil(&rp.machine.ctx), .opts = opts } };
        try vm.interpret(req);
        const reqid = rp.machine.regs[0];
        try std.testing.expectEqual(@as(usize, 1), rp.links.items.len); // linked child
        // gap-b-3: BEFORE the epilogue flush the park sits in `staged_spawn`; a
        // same-grant abandon must cancel it there (abandon consults staging first).
        try std.testing.expectEqual(@as(usize, 1), vm.staged_spawn.items.len);
        rp.machine.pending = .{ .abandon_spawn = .{ .ref = reqid } };
        try vm.interpret(req);
        try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, rp.machine.regs[0], FinalTerms.atom(&rp.machine.ctx, rp.machine.bool_true))); // TRUE
        try std.testing.expectEqual(@as(usize, 0), vm.staged_spawn.items.len); // staged reply cancelled
        try std.testing.expectEqual(@as(usize, 0), vm.parked_spawn.items.len); // never reaches the global list
        try std.testing.expectEqual(@as(usize, 0), rp.links.items.len); // child orphaned

        // a SECOND abandon of the same ReqId → false (Mutant 2: always-true reddens).
        rp.machine.pending = .{ .abandon_spawn = .{ .ref = reqid } };
        try vm.interpret(req);
        try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, rp.machine.regs[0], FinalTerms.atom(&rp.machine.ctx, rp.machine.bool_false)));
        // no reply is ever delivered (it was cancelled).
        try vm.deliverParkedSpawn();
        try vm.drainSignals(req);
        try std.testing.expectEqual(@as(usize, 0), rp.machine.mbox.len());
    }

    // (b) abandon AFTER the tick delivered the reply → false; a FOREIGN ref → false.
    {
        const req = try vm.spawn(idle, 0, null);
        const rp = vm.procs.items[req];
        const ma = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("m"));
        const fa = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("f"));
        rp.machine.pending = .{ .spawn_request = .{ .module = ma, .func = fa, .args = FinalTerms.nil(&rp.machine.ctx), .opts = FinalTerms.nil(&rp.machine.ctx) } };
        try vm.interpret(req);
        const reqid = rp.machine.regs[0];
        try vm.applyStagedParks(); // gap-b-3: epilogue publishes the staged park
        try vm.deliverParkedSpawn(); // reply delivered
        rp.machine.pending = .{ .abandon_spawn = .{ .ref = reqid } };
        try vm.interpret(req);
        try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, rp.machine.regs[0], FinalTerms.atom(&rp.machine.ctx, rp.machine.bool_false))); // FALSE (delivered)

        const foreign = try FinalTerms.ref(&rp.machine.ctx, Vm.refWordsForKey(999999));
        rp.machine.pending = .{ .abandon_spawn = .{ .ref = foreign } };
        try vm.interpret(req);
        try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, rp.machine.regs[0], FinalTerms.atom(&rp.machine.ctx, rp.machine.bool_false))); // FALSE (unknown)
    }
}

// ============================================================================
// LAW gap-b-3 (SMP step 3): STAGED ≡ INLINE — the parked-list writes relocated
// out of the `L_v`-held `interpret` arms into the single grant-epilogue apply-
// point (`applyStagedParks`) denote IDENTICALLY to the old inline write. This is
// the STRUCTURAL PREREQUISITE for gap-b-4's coherency lock `L_c` (the write no
// longer takes a coordinator lock while holding `L_v` → the `L_v↔L_c` cycle's
// precondition is broken). CTRL-SCHED / UCA-SMP-9: a park lost/duplicated/
// reordered during the relocation → lost wakeup / double delivery / order
// violation. Proven here by: (1) ORDER PRESERVATION — staged entries reach the
// global list in staging order; (2) EXACTLY-ONCE — a park is applied once and a
// second apply is a no-op; (3) EPILOGUE WIRING — `grantOnly`'s epilogue performs
// the flush (the real per-grant path); (4) STAGED-ABANDON — a same-grant abandon
// cancels a staged park so it never reaches the global list. Mutants: g-b-3 m1
// (apply appends staging TWICE → double-park reddens exactly-once); g-b-3 m2
// (apply reverses staging order → the order-preservation check reddens).
test "LAW gap-b-3 STAGED≡INLINE: parked writes staged in `interpret`, applied once at the epilogue in order; grantOnly flushes; same-grant abandon cancels a staged park" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const req = try vm.spawn(idle, 0, null);
    const rp = vm.procs.items[req];
    const ma = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("m"));
    const fa = FinalTerms.atom(&rp.machine.ctx, try atoms.intern("f"));

    // (1) ORDER PRESERVATION. Two spawn_requests stage in FIFO order (reqids are
    //     minted monotonically, so A's reqid < B's). The trap writes STAGING, not
    //     the global list — both parked lists are untouched until the flush.
    rp.machine.pending = .{ .spawn_request = .{ .module = ma, .func = fa, .args = FinalTerms.nil(&rp.machine.ctx), .opts = FinalTerms.nil(&rp.machine.ctx) } };
    try vm.interpret(req);
    rp.machine.pending = .{ .spawn_request = .{ .module = ma, .func = fa, .args = FinalTerms.nil(&rp.machine.ctx), .opts = FinalTerms.nil(&rp.machine.ctx) } };
    try vm.interpret(req);
    try std.testing.expectEqual(@as(usize, 2), vm.staged_spawn.items.len);
    try std.testing.expectEqual(@as(usize, 0), vm.parked_spawn.items.len); // NOT written inline
    const reqid_a = vm.staged_spawn.items[0].reqid;
    const reqid_b = vm.staged_spawn.items[1].reqid;
    try std.testing.expect(reqid_a < reqid_b); // staged in request (FIFO) order

    // Apply at the epilogue: the global list receives EXACTLY the staged entries in
    // the SAME order (Mutant m2 — a reversed apply — reddens this order check).
    try vm.applyStagedParks();
    try std.testing.expectEqual(@as(usize, 0), vm.staged_spawn.items.len);
    try std.testing.expectEqual(@as(usize, 2), vm.parked_spawn.items.len);
    try std.testing.expectEqual(reqid_a, vm.parked_spawn.items[0].reqid);
    try std.testing.expectEqual(reqid_b, vm.parked_spawn.items[1].reqid);

    // (2) EXACTLY-ONCE. A second apply is a no-op (staging already drained) — the
    //     global list does not grow (Mutant m1 — apply appends staging twice —
    //     reddens: parked_spawn would be 4, or a re-apply after a manual re-stage
    //     would double the entries).
    try vm.applyStagedParks();
    try std.testing.expectEqual(@as(usize, 2), vm.parked_spawn.items.len); // unchanged

    // Drain the global list so the next sub-law starts clean.
    vm.parked_spawn.clearRetainingCapacity();

    // (3) EPILOGUE WIRING. A park staged by `interpret` is published to the global
    //     list by `grantOnly`'s OWN epilogue (the real per-grant flush point — the
    //     same place the SMP worker flushes), not only by a manual apply.
    rp.machine.pending = .{ .spawn_request = .{ .module = ma, .func = fa, .args = FinalTerms.nil(&rp.machine.ctx), .opts = FinalTerms.nil(&rp.machine.ctx) } };
    try vm.interpret(req);
    try std.testing.expectEqual(@as(usize, 1), vm.staged_spawn.items.len);
    try std.testing.expectEqual(@as(usize, 0), vm.parked_spawn.items.len);
    try vm.grantOnly(req, 4); // runs the idle loop; its epilogue flushes staging
    try std.testing.expectEqual(@as(usize, 0), vm.staged_spawn.items.len); // flushed
    try std.testing.expectEqual(@as(usize, 1), vm.parked_spawn.items.len); // now global
    vm.parked_spawn.clearRetainingCapacity();

    // (4) STAGED-ABANDON. A same-grant abandon cancels a park while it is still in
    //     staging, so it NEVER reaches the global list — the union {staging}∪{global}
    //     that abandon searches is exactly the old inline-global set.
    rp.machine.pending = .{ .spawn_request = .{ .module = ma, .func = fa, .args = FinalTerms.nil(&rp.machine.ctx), .opts = FinalTerms.nil(&rp.machine.ctx) } };
    try vm.interpret(req);
    const reqid_c = rp.machine.regs[0];
    try std.testing.expectEqual(@as(usize, 1), vm.staged_spawn.items.len);
    rp.machine.pending = .{ .abandon_spawn = .{ .ref = reqid_c } };
    try vm.interpret(req);
    try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, rp.machine.regs[0], FinalTerms.atom(&rp.machine.ctx, rp.machine.bool_true))); // cancelled → true
    try std.testing.expectEqual(@as(usize, 0), vm.staged_spawn.items.len); // gone from staging
    try vm.applyStagedParks();
    try std.testing.expectEqual(@as(usize, 0), vm.parked_spawn.items.len); // never reached the global list
}

// ============================================================================
// gap-b-4 (SMP step 4, THE CRUX): `L_c` — the COHERENCY-DOMAIN lock + the
// ACYCLIC total-order proof. This is the highest-risk step of the whole epoch:
// the `L_v↔L_c` deadlock cycle is real, and either the proven order breaks it or
// it does not. See `CoherencyLock` (the by-construction argument) + these two
// mechanized laws (the bounded model + the linearizability witness).
//
// SAFETY PACKET (SAFETY_ANALYSIS §10; controller = the coherency lock `L_c` / the
// lock hierarchy, CTRL-SCHED). UCA = UCA-SMP-9 (a lock acquired OUT OF ORDER on
// the concurrent scheduler path → `L_v↔L_c` priority-inversion / hold-and-wait
// DEADLOCK — the crux hazard). HAZARD = a scheduler thread NEVER returns / the
// node hangs. MITIGATION = the proven ACYCLIC total order `L_v→L_c→{L_reg,
// L_timer}→L_e` (C-8): (a) BY CONSTRUCTION — every `L_c` section references only
// the coherency domain, holds no `VmLock`, so it cannot acquire `L_v` (no
// `L_c→L_v` back-edge); (b) MECHANIZED — the bounded model below shows the
// sanctioned order makes full progress and a reversed acquire (the cycle) trips
// the abort watchdog at the wall bound (a deadlock is a FAILED LAW, never a hung
// suite) + BOUNDED joins. FMEA = a lock un-acquirable within the bound → RED, not
// a silent spin; a coherency-domain mutation OUTSIDE `L_c` → the conservation /
// linearizability law reddens (torn counters / lost update).

/// A test-only ABORTABLE spinlock: `tryLockUntil` bails out if the shared abort
/// flag is set, so a MODELLED lock-order cycle terminates as a failed law (the
/// wall bound trips `abort`) instead of hanging the suite — the bounded-join
/// contract made mechanical. Same shape as `timer_wheel.zig`'s gap-b-1 model.
const GapB4AbortableLock = struct {
    held: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
    fn tryLockUntil(self: *GapB4AbortableLock, abort: *std.atomic.Value(bool)) bool {
        while (self.held.swap(true, .acquire)) {
            if (abort.load(.acquire)) return false;
            std.Thread.yield() catch {};
        }
        return true;
    }
    fn unlock(self: *GapB4AbortableLock) void {
        self.held.store(false, .release);
    }
};

// LAW gap-b-4 (TOTAL-ORDER ACYCLIC, C-8): the total order
// `L_v → L_c → {L_reg,L_timer} → L_e` holds on EVERY acquisition path with NO
// back-edge. Modelled with four locks V,C,T,E standing for `L_v`, `L_c`, a
// `{L_reg,L_timer}` representative, and `L_e`. The SANCTIONED path acquires a
// DOWNWARD-CLOSED prefix in order (V, then C, then T, then E) and releases in
// reverse — the textbook resource-ordering theorem says a globally consistent
// acquisition order PRECLUDES a cycle, so all K workers complete their full
// iteration budget within the wall bound (nobody aborts). The MUTANT
// (MUT-GAPB4-1) reverses ONE worker to acquire C BEFORE V (order C,V,…): a
// worker holding V and reaching for C, meeting a worker holding C and reaching
// for V, is EXACTLY the `L_v↔L_c` cycle — the abort watchdog trips at the wall
// deadline and progress falls short (RED). This is the mechanized witness that
// the crux back-edge, if ever introduced, is caught by a bounded FAILED LAW
// rather than a hung node. On the REAL path no `L_c` section can even express the
// reverse (it holds no `VmLock`), so by construction the mutant is unreachable
// there — this test guards the invariant the construction relies on.
test "gap-b-4: lock-order L_v->L_c->{L_reg,L_timer}->L_e has no back-edge (bounded, deadlock=failed law)" {
    const OrderWorker = struct {
        v: *GapB4AbortableLock,
        c: *GapB4AbortableLock,
        t: *GapB4AbortableLock,
        e: *GapB4AbortableLock,
        abort: *std.atomic.Value(bool),
        reversed: bool, // MUT-GAPB4-1: acquire C before V → the L_v↔L_c cycle
        iters: usize,
        progress: *std.atomic.Value(usize),

        fn take(l: *GapB4AbortableLock, abort: *std.atomic.Value(bool), held: []?*GapB4AbortableLock, n: *usize) bool {
            if (!l.tryLockUntil(abort)) return false;
            held[n.*] = l;
            n.* += 1;
            return true;
        }
        fn run(w: *@This()) void {
            var i: usize = 0;
            while (i < w.iters) : (i += 1) {
                if (w.abort.load(.acquire)) return;
                var held: [4]?*GapB4AbortableLock = .{ null, null, null, null };
                var n: usize = 0;
                // The acquisition ORDER for this worker. Sanctioned = V,C,T,E
                // (a downward-closed prefix of the total order). Reversed swaps
                // the first two → C,V,T,E → the L_v↔L_c back-edge.
                const seq: [4]*GapB4AbortableLock = if (w.reversed)
                    .{ w.c, w.v, w.t, w.e }
                else
                    .{ w.v, w.c, w.t, w.e };
                var ok = true;
                for (seq) |l| {
                    if (!take(l, w.abort, &held, &n)) {
                        ok = false;
                        break;
                    }
                    std.Thread.yield() catch {}; // widen the interleaving window
                }
                if (ok) _ = w.progress.fetchAdd(1, .monotonic);
                // release in REVERSE acquisition order (whatever we got)
                while (n > 0) {
                    n -= 1;
                    held[n].?.unlock();
                }
                if (!ok) return; // aborted mid-acquire (a modelled cycle)
            }
        }
    };

    const Watchdog = struct {
        abort: *std.atomic.Value(bool),
        progress: *std.atomic.Value(usize),
        target: usize,
        deadline_ns: u64,
        fn run(w: *@This()) void {
            while (w.progress.load(.acquire) < w.target and SmpEngine.nowNs() < w.deadline_ns) {
                std.Thread.yield() catch {};
            }
            w.abort.store(true, .release);
        }
    };

    const K: usize = 4;
    const ITERS: usize = 4000;
    var v = GapB4AbortableLock{};
    var c = GapB4AbortableLock{};
    var t = GapB4AbortableLock{};
    var e = GapB4AbortableLock{};
    var abort = std.atomic.Value(bool).init(false);
    var progress = std.atomic.Value(usize).init(0);

    const wall_ns: u64 = 3 * std.time.ns_per_s;
    const start_ns = SmpEngine.nowNs();

    var workers: [K]OrderWorker = undefined;
    for (&workers) |*w| w.* = .{ .v = &v, .c = &c, .t = &t, .e = &e, .abort = &abort, .reversed = false, .iters = ITERS, .progress = &progress };
    // MUT-GAPB4-1: FLIP the next line to `true` on ONE worker → acquire L_c
    // before L_v → the L_v↔L_c cycle → progress stalls → RED at the wall bound.
    // workers[0].reversed = true;

    var wd = Watchdog{ .abort = &abort, .progress = &progress, .target = K * ITERS, .deadline_ns = start_ns + wall_ns };
    const wd_thread = try std.Thread.spawn(.{}, Watchdog.run, .{&wd});

    var threads: [K]std.Thread = undefined;
    for (&threads, 0..) |*th, k| th.* = try std.Thread.spawn(.{}, OrderWorker.run, .{&workers[k]});
    for (&threads) |th| th.join();
    abort.store(true, .release); // release the watchdog if all finished first
    wd_thread.join();

    const elapsed_ns: u64 = @intCast(SmpEngine.nowNs() -% start_ns);
    try std.testing.expect(elapsed_ns < wall_ns + std.time.ns_per_s); // BOUNDED join
    // With the sanctioned order on every path, NOBODY aborts: full progress.
    try std.testing.expectEqual(K * ITERS, progress.load(.acquire));
}

// LAW gap-b-4 (coherency-domain LINEARIZABILITY under `L_c` + CONSERVATION,
// bounded): N REAL `std.Thread` workers concurrently mutate a shared proxy of the
// coherency domain — real per-scheduler run queues (`ArrayList(pid)` tokens) +
// an `owned_count` — with `Vm.CoherencyLock` (`L_c`) the ONLY synchronization
// (the real engine takes `L_c` while ALSO holding `L_v`; here we isolate `L_c` to
// witness that `L_c` ALONE serializes the domain — the property `gap-b-5`/`-6`
// will rely on when they narrow `L_v` away). Each worker does grant/release
// cycles: pop a token (queue_total-=1, owned_count+=1), then requeue it
// (owned_count-=1, queue_total+=1) — the pick+mark and clear+requeue coherency
// pairs. CONSERVATION (the sacred invariant — a pid runnable on ≤1 scheduler):
// `queue_total + owned_count == P` at EVERY `L_c`-holding observation, and the
// token multiset is preserved (no lost/duplicated pid). The join is BOUNDED (wall
// deadline) — a torn queue or a lost update from a MISSING `L_c` (MUT-GAPB4-2)
// reddens conservation or crashes, never hangs.
test "gap-b-4: coherency domain linearizable under L_c (N threads on real run queues + ownership), bounded + conserved" {
    const gpa = std.testing.allocator;
    const K: usize = 4; // run queues (schedulers)
    const P: usize = 64; // tokens (pids)

    const Domain = struct {
        l_c: CoherencyLock = .{},
        queues: [4]std.ArrayList(u32) = .{ .empty, .empty, .empty, .empty },
        owned_count: u32 = 0,
        conserved: bool = true,
        gpa: std.mem.Allocator,

        fn queueTotalD(self: *@This()) usize {
            var s: usize = 0;
            for (&self.queues) |*q| s += q.items.len;
            return s;
        }
    };

    const Worker = struct {
        d: *Domain,
        m: usize,
        seed: u64,
        err: ?anyerror = null,

        fn run(w: *@This()) void {
            var prng = std.Random.DefaultPrng.init(w.seed);
            const r = prng.random();
            var i: usize = 0;
            while (i < w.m) : (i += 1) {
                w.d.l_c.lock(); // L_c — the ONLY synchronization on the domain
                // GRANT: pop a token from a seeded nonempty queue (queue→owned).
                var got: ?u32 = null;
                var k: usize = 0;
                while (k < 4) : (k += 1) {
                    const q = (r.uintLessThan(usize, 4) + k) % 4;
                    if (w.d.queues[q].items.len > 0) {
                        got = w.d.queues[q].orderedRemove(0);
                        w.d.owned_count += 1; // mark-owned, atomic with the pop under L_c
                        break;
                    }
                }
                // CONSERVATION check WHILE holding L_c (owned + queued == P).
                if (w.d.queueTotalD() + w.d.owned_count != P) w.d.conserved = false;
                // RELEASE: requeue the token to a seeded queue (owned→queue).
                if (got) |tok| {
                    const dst = r.uintLessThan(usize, 4);
                    w.d.queues[dst].append(w.d.gpa, tok) catch |e| {
                        w.d.owned_count -= 1;
                        w.err = e;
                        w.d.l_c.unlock();
                        return;
                    };
                    w.d.owned_count -= 1; // clear-owned, atomic with the requeue
                }
                if (w.d.queueTotalD() + w.d.owned_count != P) w.d.conserved = false;
                w.d.l_c.unlock();
            }
        }
    };

    for (0..6) |iter| {
        var d = Domain{ .gpa = gpa };
        defer for (&d.queues) |*q| q.deinit(gpa);
        // seed P unique tokens spread across the K queues.
        var tok: u32 = 0;
        while (tok < P) : (tok += 1) try d.queues[tok % K].append(gpa, tok);
        try std.testing.expectEqual(P, d.queueTotalD());

        const N: usize = 4;
        const M: usize = 500;
        var workers: [4]Worker = undefined;
        for (&workers, 0..) |*w, k| w.* = .{ .d = &d, .m = M, .seed = 0xB4 +% iter *% 13 +% k };

        const wall_ns: u64 = 5 * std.time.ns_per_s;
        const t0 = SmpEngine.nowNs();
        var threads: [4]std.Thread = undefined;
        for (&threads, 0..) |*th, k| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[k]});
        for (&threads) |th| th.join(); // BOUNDED: L_c is a leaf w.r.t. the model, no cycle
        const elapsed: u64 = @intCast(SmpEngine.nowNs() -% t0);
        try std.testing.expect(elapsed < wall_ns); // bounded-join witness
        _ = N;

        for (&workers) |*w| if (w.err) |e| return e;
        // CONSERVED across the whole concurrent history (no lost/dup update).
        try std.testing.expect(d.conserved);
        try std.testing.expectEqual(@as(u32, 0), d.owned_count); // every grant released
        try std.testing.expectEqual(P, d.queueTotalD()); // token count conserved
        // the token MULTISET is exactly {0..P-1} — no pid lost or duplicated.
        var seen: std.AutoHashMapUnmanaged(u32, void) = .empty;
        defer seen.deinit(gpa);
        for (&d.queues) |*q| for (q.items) |x| {
            try std.testing.expect(!seen.contains(x)); // uniqueness: ≤1 queue per pid
            try seen.put(gpa, x, {});
        };
        try std.testing.expectEqual(P, seen.count());
    }
}

// ============================================================================
// gap-b-5 (SMP step 5, THE LOCK FLIP): `L_v` is RELEASED around the coordinator
// coherency section (`drainReady → pick → mark-owned`) so it runs under `L_c`
// ALONE — schedulers genuinely overlap (a worker in its `L_c`-alone coordinator
// no longer blocks a peer that only needs `L_v` for `deliverParked*`/
// `drainSignals`/the grant event, and vice-versa; the grant `vm.events` write is
// MOVED into a separate `L_v` section). This introduces a NEW acquisition
// pattern: a path that takes `L_c` WITHOUT `L_v`. These two laws witness that the
// flip keeps (1) the acyclic total order and (2) ownership conservation.
//
// SAFETY PACKET (SAFETY_ANALYSIS §CTRL-SCHED; controller = the coherency lock
// `L_c` / the lock hierarchy). UCA = UCA-SMP-9 (a lock acquired OUT OF ORDER on
// the narrowed concurrent path → `L_v↔L_c` hold-and-wait DEADLOCK — the crux
// hazard, now on the `L_c`-WITHOUT-`L_v` path) + UCA-SMP-11 (ownership torn/lost/
// duplicated across the NARROWER critical section → double-grant / lost pid /
// conservation break). HAZARD = a scheduler thread never returns / a process is
// lost or double-granted. MITIGATION = (1) the bounded lock-order model below —
// the sanctioned down-path (`L_v→L_c`) PLUS the new `L_c`-alone coordinator path
// make full progress, while the MUTANT that reaches UP to `L_v` while HOLDING
// `L_c` (the `L_c→L_v` back-edge the flip must never introduce) trips the abort
// watchdog at the wall bound (a deadlock is a FAILED LAW, never a hung node); (2)
// the quotient re-witness — `driveThreads` on the flipped worker still denotes
// the oracle at n∈{1,2,4}, preserves the sacred per-pair order, and leaves the
// `L_c`-domain arrays CLEAN at quiescence (conservation under the narrower
// section). FMEA = a lock un-acquirable within the bound → RED; a coherency
// mutation escaping `L_c` → conservation/quotient reddens; both BOUNDED.
//
// MUT-GAPB5-1 (the `L_c→L_v` BACK-EDGE — the cycle the flip must never allow):
//   set `coord_backedge = true` on the coordinator worker in the order model → it
//   reaches UP to `L_v` WHILE holding `L_c`, meeting a down-worker holding `L_v`
//   and reaching for `L_c` → the exact `L_v↔L_c` deadlock → progress stalls →
//   RED at the wall bound. (On the REAL flipped path this is unreachable: every
//   `L_c`-alone section RELEASES `L_c` before taking `L_v`.)
// MUT-GAPB5-2 (DROP `L_c` on the now-`L_v`-free coordinator): run the flipped
//   `drainReady→pick→mark-owned` with NO `L_c` (the coordinator no longer has
//   `L_v` to serialize it) → two workers pick the SAME pid / tear `owned_count` →
//   double-grant / a `queued` bit or `owned` slot dirty at quiescence → the
//   quotient's denotation and clean-arrays assertions RED. (Witnessed by the
//   conservation model's requirement that `L_c` ALONE serializes the domain — the
//   gap-b-4 linearizability law with `L_c` removed reddens conservation.)

// LAW gap-b-5 (TOTAL-ORDER ACYCLIC WITH THE `L_c`-WITHOUT-`L_v` PATH, C-8): the
// order `L_v → L_c → {L_reg,L_timer} → L_e` still has NO back-edge once a path may
// take `L_c` WITHOUT `L_v`. Modelled with the four locks V,C,T,E. DOWN-workers
// take the sanctioned prefix V,C,T,E (the epilogue/interpret/rollback paths —
// they hold `L_v` and reach DOWN to `L_c`). COORDINATOR-workers model the gap-b-5
// flip: take `L_c` ALONE (no `L_v`), release it, THEN take `L_v` ALONE — two
// DISJOINT critical sections, never `L_c`-then-`L_v`. With every path respecting
// the order, ALL workers complete their iteration budget within the wall bound
// (nobody aborts). The MUTANT (MUT-GAPB5-1) flips the coordinator to reach UP to
// `L_v` while STILL holding `L_c` (`L_c`-then-`L_v`) — the `L_v↔L_c` cycle against
// a down-worker — and the abort watchdog trips at the deadline (RED). This is the
// mechanized witness that the flip's new pattern introduces no back-edge.
test "gap-b-5: lock-order with the L_c-WITHOUT-L_v coordinator path has no back-edge (bounded, deadlock=failed law)" {
    const DownWorker = struct { // sanctioned: V,C,T,E (holds L_v, reaches DOWN to L_c)
        v: *GapB4AbortableLock,
        c: *GapB4AbortableLock,
        t: *GapB4AbortableLock,
        e: *GapB4AbortableLock,
        abort: *std.atomic.Value(bool),
        iters: usize,
        progress: *std.atomic.Value(usize),
        fn run(w: *@This()) void {
            var i: usize = 0;
            while (i < w.iters) : (i += 1) {
                if (w.abort.load(.acquire)) return;
                if (!w.v.tryLockUntil(w.abort)) return;
                std.Thread.yield() catch {}; // hold L_v, widen the window before reaching for L_c
                if (!w.c.tryLockUntil(w.abort)) {
                    w.v.unlock();
                    return;
                }
                _ = w.t.tryLockUntil(w.abort); // best-effort leaves (T,E below C)
                _ = w.e.tryLockUntil(w.abort);
                _ = w.progress.fetchAdd(1, .monotonic);
                w.e.unlock();
                w.t.unlock();
                w.c.unlock();
                w.v.unlock();
            }
        }
    };
    const CoordWorker = struct { // gap-b-5: L_c ALONE, then (disjoint) L_v ALONE
        v: *GapB4AbortableLock,
        c: *GapB4AbortableLock,
        abort: *std.atomic.Value(bool),
        backedge: bool, // MUT-GAPB5-1: reach UP to L_v WHILE holding L_c → the cycle
        iters: usize,
        progress: *std.atomic.Value(usize),
        fn run(w: *@This()) void {
            var i: usize = 0;
            while (i < w.iters) : (i += 1) {
                if (w.abort.load(.acquire)) return;
                // The L_c-ALONE coordinator section (drain/pick/mark-owned).
                if (!w.c.tryLockUntil(w.abort)) return;
                std.Thread.yield() catch {}; // widen: hold L_c, let a down-worker grab L_v
                if (w.backedge) {
                    // MUT-GAPB5-1: the FORBIDDEN up-edge — take L_v while holding L_c.
                    if (!w.v.tryLockUntil(w.abort)) {
                        w.c.unlock();
                        return; // aborted mid-cycle (the modelled deadlock)
                    }
                    w.v.unlock();
                    w.c.unlock();
                } else {
                    // SANCTIONED: release L_c FIRST, then take L_v as a DISJOINT section.
                    w.c.unlock();
                    if (!w.v.tryLockUntil(w.abort)) return;
                    w.v.unlock();
                }
                _ = w.progress.fetchAdd(1, .monotonic);
            }
        }
    };
    const Watchdog = struct {
        abort: *std.atomic.Value(bool),
        progress: *std.atomic.Value(usize),
        target: usize,
        deadline_ns: u64,
        fn run(w: *@This()) void {
            while (w.progress.load(.acquire) < w.target and SmpEngine.nowNs() < w.deadline_ns) {
                std.Thread.yield() catch {};
            }
            w.abort.store(true, .release);
        }
    };

    const K_DOWN: usize = 2;
    const K_COORD: usize = 2;
    const ITERS: usize = 4000;
    var v = GapB4AbortableLock{};
    var c = GapB4AbortableLock{};
    var t = GapB4AbortableLock{};
    var e = GapB4AbortableLock{};
    var abort = std.atomic.Value(bool).init(false);
    var progress = std.atomic.Value(usize).init(0);

    const wall_ns: u64 = 3 * std.time.ns_per_s;
    const start_ns = SmpEngine.nowNs();

    var downs: [K_DOWN]DownWorker = undefined;
    for (&downs) |*w| w.* = .{ .v = &v, .c = &c, .t = &t, .e = &e, .abort = &abort, .iters = ITERS, .progress = &progress };
    var coords: [K_COORD]CoordWorker = undefined;
    // MUT-GAPB5-1: FLIP `.backedge = false` → `true` on ONE coordinator → it takes
    // L_v while holding L_c → the L_v↔L_c cycle → progress stalls → RED at the bound.
    for (&coords) |*w| w.* = .{ .v = &v, .c = &c, .abort = &abort, .backedge = false, .iters = ITERS, .progress = &progress };

    const target = (K_DOWN + K_COORD) * ITERS;
    var wd = Watchdog{ .abort = &abort, .progress = &progress, .target = target, .deadline_ns = start_ns + wall_ns };
    const wd_thread = try std.Thread.spawn(.{}, Watchdog.run, .{&wd});

    var dth: [K_DOWN]std.Thread = undefined;
    var cth: [K_COORD]std.Thread = undefined;
    for (&dth, 0..) |*th, k| th.* = try std.Thread.spawn(.{}, DownWorker.run, .{&downs[k]});
    for (&cth, 0..) |*th, k| th.* = try std.Thread.spawn(.{}, CoordWorker.run, .{&coords[k]});
    for (&dth) |th| th.join();
    for (&cth) |th| th.join();
    abort.store(true, .release);
    wd_thread.join();

    const elapsed_ns: u64 = @intCast(SmpEngine.nowNs() -% start_ns);
    try std.testing.expect(elapsed_ns < wall_ns + std.time.ns_per_s); // BOUNDED join
    // With the sanctioned order on EVERY path (incl. the new L_c-without-L_v
    // coordinator), NOBODY aborts: full progress. MUT-GAPB5-1 stalls this.
    try std.testing.expectEqual(target, progress.load(.acquire));
}

// LAW gap-b-5 QUOTIENT RE-WITNESS (denote-invariance + per-pair order +
// ownership conservation under the NARROWED L_v): with `L_v` released around the
// coordinator, `driveThreads` on the flipped worker STILL denotes the sequential
// oracle at n∈{1,2,4}, preserves the sacred per-pair signal order, is work-bounded
// (no lost wake / livelock), AND leaves the `L_c`-domain coherency arrays CLEAN at
// quiescence (owned all-null / queued all-false / ready empty) — conservation on
// the narrower critical section. MUT-GAPB5-2 (drop `L_c` on the now-`L_v`-free
// coordinator) reds the denotation (double-grant) or the clean-arrays assertion.
test "LAW gap-b-5 QUOTIENT RE-WITNESS under the narrowed L_v: driveThreads with L_v released around the L_c-alone coordinator denotes the oracle at n∈{1,2,4}, keeps the sacred per-pair order, is work-bounded, and leaves owned/queued/ready CLEAN at quiescence" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var rr = try runRing(gpa, &atoms, .round_robin, 6);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;
    const max_grants: usize = 100_000;
    const scheds = [_]u32{ 1, 2, 4 };
    for (scheds) |ns| {
        var rep: usize = 0;
        while (rep < 10) : (rep += 1) {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 6);
            const eng = SmpEngine{ .n_sched = ns, .seed = 0xB5B5 +% @as(u64, rep) *% 11 +% ns };
            const run = try eng.driveThreads(&vm, 5, max_grants, 60 * std.time.ns_per_s);
            try std.testing.expect(run.grants < max_grants); // work-bounded (the flip kept no lost wake)
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status); // completed
            try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4); // QUOTIENT under narrowed L_v (MUT-GAPB5-2 double-count reds this)
            try std.testing.expect(checkPerPairOrder(vm.events.items)); // sacred per-pair order under REAL overlap
            // CONSERVATION at quiescence under the narrower section.
            try std.testing.expectEqual(@as(usize, 0), vm.ready.items.len);
            for (vm.owned.items) |*o| try std.testing.expectEqual(NO_OWNER, o.load(.monotonic));
            for (vm.queued.items) |*q| try std.testing.expect(!q.load(.monotonic));
        }
    }
}

// ============================================================================
// gap-b-5b (SMP step 5b, the LOWEST leaf): `L_events` — the global event-log lock.
// Every mutation of `Vm.events` is routed through `Vm.emitEvent`, which holds
// `L_events` for exactly the append. `L_events` is the LOWEST leaf of the total
// order `L_v→L_c→{L_reg,L_timer}→L_e→L_events`: `emitEvent`'s body references only
// the events buffer + its own lock, so it can never acquire a higher lock — the
// back-edge is impossible by construction. This makes the event appends (which
// today ride inside `L_v` holds) individually linearizable, a prerequisite for
// later shrinking those `L_v` holds.
//
// SAFETY PACKET (SAFETY_ANALYSIS §CTRL-SCHED; controller = the lock hierarchy /
// the event-log lock acquisition). UCA = UCA-SMP-9 (a lock acquired OUT OF ORDER
// → a `L_events→(higher)` back-edge → hold-and-wait DEADLOCK) + a concurrent
// unsynchronized `vm.events` append (torn ArrayList / lost event / a trace the
// per-pair order law reads as reordered). HAZARD = a scheduler thread never
// returns (hung node) / the event log is corrupt or loses a delivery record.
// MITIGATION = (a) BY CONSTRUCTION — `emitEvent` holds no reference to any higher
// lock, so `L_events` is a true leaf (no back-edge); (b) MECHANIZED — the
// linearizability law below shows N threads appending through `emitEvent` lose /
// tear NO event and preserve each thread's emission order, and the bounded
// lock-order model shows the sanctioned `(higher)→L_events` down-path makes full
// progress while the reversed acquire trips the abort watchdog at the wall bound
// (a deadlock is a FAILED LAW, never a hung suite) + BOUNDED joins. FMEA = a lock
// un-acquirable within the bound → RED; a `vm.events` write escaping `L_events` →
// the linearizability law reddens (lost/torn event), never a silent spin.
//
// MUT-GAPB5B-1 (DROP `L_events` — the concurrent events race): make `emitEvent`
//   append WITHOUT taking `L_events` (comment out the lock/unlock) → N threads
//   append into the same ArrayList with no synchronization → torn length / lost
//   update / a use-after-realloc crash → the linearizability law reddens (count
//   != N*M, or a duplicated/lost grant value, or a trap). KILLED by the law
//   below (its whole point is that `L_events` ALONE serializes the appends).
// MUT-GAPB5B-2 (ACQUIRE a higher lock while holding `L_events` — the back-edge):
//   in the order model, flip a worker to take `L_events` FIRST and then reach UP
//   to the higher lock (`L_events`-then-`O`) → meeting a worker holding `O` and
//   reaching DOWN to `L_events` is the exact `O↔L_events` cycle → progress stalls
//   → RED at the wall bound. (On the REAL path this is unreachable: `emitEvent`
//   holds no reference to any higher lock, so it CANNOT express the reverse.)

/// A grant value that encodes (worker, seq) so the linearizability law can prove
/// per-worker emission order is preserved AND every append is unique.
fn gapB5bEnc(worker: usize, seq: usize) Pid {
    return @intCast(worker * 1_000_000 + seq);
}

// LAW gap-b-5b (events-linearizable-under-L_events + bounded-join): N REAL
// std.Thread workers concurrently append to ONE shared `Vm.events` — each worker
// `w` emits M grant events `enc(w, 0..M)` through the real `Vm.emitEvent`, with
// `L_events` the ONLY synchronization. Because every append is serialized by
// `L_events`, the outcome is LINEARIZABLE: exactly N*M events landed (none lost,
// none torn — a MISSING `L_events`, MUT-GAPB5B-1, tears the ArrayList and reddens
// the count / crashes), every grant value is UNIQUE (no duplicated/lost update),
// and each worker's values appear in its EMISSION ORDER (a strictly increasing
// subsequence — the atomicity witness). The join is BOUNDED (wall deadline) — a
// torn-list crash or deadlock blows the bound rather than hanging.
test "gap-b-5b: events linearizable under L_events (N threads on one Vm.events), bounded + order-preserving" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    const Worker = struct {
        vm: *Vm,
        w: usize,
        m: usize,
        err: ?anyerror = null,
        fn run(self: *@This()) void {
            var i: usize = 0;
            while (i < self.m) : (i += 1) {
                self.vm.emitEvent(.{ .grant = gapB5bEnc(self.w, i) }) catch |e| {
                    self.err = e;
                    return;
                };
            }
        }
    };

    for (0..8) |iter| {
        const N: usize = 4;
        const M: usize = 400;
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();

        var workers: [4]Worker = undefined;
        for (&workers, 0..) |*wk, k| wk.* = .{ .vm = &vm, .w = k, .m = M };

        const wall_ns: u64 = 5 * std.time.ns_per_s; // anti-hang bound
        const t0 = SmpEngine.nowNs();
        var threads: [4]std.Thread = undefined;
        for (&threads, 0..) |*th, k| th.* = try std.Thread.spawn(.{}, Worker.run, .{&workers[k]});
        for (&threads) |th| th.join(); // BOUNDED: L_events is a leaf, no cycle can form
        const elapsed: u64 = @intCast(SmpEngine.nowNs() -% t0);
        try std.testing.expect(elapsed < wall_ns); // bounded-join witness
        _ = iter;

        for (&workers) |*wk| if (wk.err) |e| return e;
        // NO LOST/TORN EVENT: exactly N*M appends took effect.
        try std.testing.expectEqual(N * M, vm.events.items.len);
        // UNIQUENESS (no duplicated/lost update) + per-worker ORDER PRESERVED
        // (each worker's seq is strictly increasing in log order — atomicity).
        var seen: std.AutoHashMapUnmanaged(u32, void) = .empty;
        defer seen.deinit(gpa);
        var last: [4]?usize = .{ null, null, null, null };
        for (vm.events.items) |e| {
            const g: u32 = switch (e) {
                .grant => |x| x,
                else => unreachable, // this Vm only ever emitted grants
            };
            try std.testing.expect(!seen.contains(g)); // no duplicate append
            try seen.put(gpa, g, {});
            const w = g / 1_000_000;
            const seq = g % 1_000_000;
            if (last[w]) |prev| try std.testing.expect(seq > prev); // emission order kept
            last[w] = seq;
        }
        try std.testing.expectEqual(N * M, seen.count());
    }
}

// LAW gap-b-5b (lock-order `(higher) → L_events` no-back-edge, bounded): the total
// order puts `L_events` STRICTLY BELOW every other lock. Modelled with an outer
// lock `O` (stands for any higher lock — `L_v`/`L_c`/`L_reg`/`L_timer`/`L_e`) and
// a leaf lock `E` (stands for `L_events`). Workers that ALWAYS take `O` then `E`
// (the sanctioned DOWN-edge, exactly what `emitEvent`-under-`L_v` does) can never
// form a cycle, so all K workers complete their full iteration budget within the
// wall bound. The MUTANT (MUT-GAPB5B-2: one worker reversed to `E` then `O`)
// forms the `O↔L_events` cycle; the abort watchdog trips at the wall deadline and
// progress falls short — a deadlock surfaces as a FAILED LAW, never a hung suite.
// On the REAL path this is unreachable: `emitEvent` holds NO reference to any
// higher lock, so it CANNOT reverse the order (proof by construction).
test "gap-b-5b: lock-order (higher)->L_events has no back-edge (bounded, deadlock=failed law)" {
    const OrderWorker = struct {
        o: *GapB4AbortableLock,
        e: *GapB4AbortableLock,
        abort: *std.atomic.Value(bool),
        reversed: bool, // MUT-GAPB5B-2: take E before O → the O↔L_events cycle
        iters: usize,
        progress: *std.atomic.Value(usize),
        fn run(w: *@This()) void {
            var i: usize = 0;
            while (i < w.iters) : (i += 1) {
                if (w.abort.load(.acquire)) return;
                const first = if (w.reversed) w.e else w.o;
                const second = if (w.reversed) w.o else w.e;
                if (!first.tryLockUntil(w.abort)) return;
                std.Thread.yield() catch {}; // widen the interleaving window
                if (!second.tryLockUntil(w.abort)) {
                    first.unlock();
                    return;
                }
                _ = w.progress.fetchAdd(1, .monotonic);
                second.unlock();
                first.unlock();
            }
        }
    };
    const Watchdog = struct {
        abort: *std.atomic.Value(bool),
        progress: *std.atomic.Value(usize),
        target: usize,
        deadline_ns: u64,
        fn run(w: *@This()) void {
            while (w.progress.load(.acquire) < w.target and SmpEngine.nowNs() < w.deadline_ns) {
                std.Thread.yield() catch {};
            }
            w.abort.store(true, .release);
        }
    };

    const K: usize = 4;
    const ITERS: usize = 5000;
    var o = GapB4AbortableLock{};
    var e = GapB4AbortableLock{};
    var abort = std.atomic.Value(bool).init(false);
    var progress = std.atomic.Value(usize).init(0);

    const wall_ns: u64 = 3 * std.time.ns_per_s;
    const start_ns = SmpEngine.nowNs();

    var workers: [K]OrderWorker = undefined;
    for (&workers) |*w| w.* = .{ .o = &o, .e = &e, .abort = &abort, .reversed = false, .iters = ITERS, .progress = &progress };
    // MUT-GAPB5B-2: FLIP the next line to `true` on ONE worker → take L_events
    // before the higher lock → the O↔L_events cycle → RED at the wall bound.
    // workers[0].reversed = true;

    var wd = Watchdog{ .abort = &abort, .progress = &progress, .target = K * ITERS, .deadline_ns = start_ns + wall_ns };
    const wd_thread = try std.Thread.spawn(.{}, Watchdog.run, .{&wd});

    var threads: [K]std.Thread = undefined;
    for (&threads, 0..) |*th, k| th.* = try std.Thread.spawn(.{}, OrderWorker.run, .{&workers[k]});
    for (&threads) |th| th.join();
    abort.store(true, .release); // release the watchdog if all finished first
    wd_thread.join();

    const elapsed_ns: u64 = @intCast(SmpEngine.nowNs() -% start_ns);
    try std.testing.expect(elapsed_ns < wall_ns + std.time.ns_per_s); // bounded join
    // With the sanctioned order on every path, NOBODY aborts: full progress.
    try std.testing.expectEqual(K * ITERS, progress.load(.acquire));
}

// ============================================================================
// gap-b-6 (SMP step 6, THE EPILOGUE narrowing — symmetric to gap-b-5's prologue
// flip): the L_c-domain parked-list PUBLISH is lifted OUT of the `L_v` epilogue
// hold into an `L_c`-ALONE section. The worker snapshots this grant's `staged_*`
// under `L_v` (grant-local: `staged_*` is filled by `interpret` under `L_v`, so
// the SOURCE read must exclude a concurrent `interpret`), then appends the
// snapshot into the coherency-domain `parked_*` under `L_c` ALONE — while the pid
// is STILL OWNED (`owned_count > 0`), so the publish cannot be lost to premature
// quiescence. gap-b-6a (THIS slice) then lifts the RESIDUAL SECTION B — the
// deferred-wake + schedulable-gated requeue + clear-owned — to `L_c` ALONE too, by
// relocating the suspend count off `Process` into the `L_c`-domain `Vm.suspend_a`
// (so `schedulable` is fully `L_c`-readable) and reading+clearing `pending_wake_a`
// inside the SAME `L_c` section as clear-owned (atomic against `signal`, which sets
// it under `L_c`). `applyWake`'s status write is owner-exclusive (signal defers when
// owned; the threaded engine never fires timers), so it is safe under `L_c` alone.
// The grant counter alone is bumped in a trivial `L_v`-ALONE tail (its home domain).
// After gap-b-6a the `L_v` critical section is minimal in BOTH prologue and epilogue.
//
// SAFETY PACKET (SAFETY_ANALYSIS §CTRL-SCHED; controller = the coherency lock
// `L_c` / the lock hierarchy). UCA = UCA-SMP-9 (a lock acquired OUT OF ORDER on
// the narrowed epilogue path → `L_v↔L_c` deadlock — now with the parked publish
// on the `L_c`-WITHOUT-`L_v` path) + UCA-SMP-11 (a staged park LOST/DUPLICATED
// across the narrower publish, or a pid lost to premature quiescence →
// conservation break / a spawn/systask reply never delivered). HAZARD = a
// scheduler thread never returns / a parked reply or a process is lost. MITIGATION
// = (1) the gap-b-5 bounded lock-order model already witnesses the `L_c`-alone
// pattern (which the parked publish reuses) introduces no `L_c→L_v` back-edge;
// (2) the metamorphic law below — the grant-local snapshot + `L_c`-alone publish
// is denote-IDENTICAL to the old single-section `applyStagedParks` (same `parked_*`
// set + order), and the snapshot DRAINS `staged_*` (grant-locality guard); (3) the
// gap-b-5 QUOTIENT RE-WITNESS (unchanged) re-runs the FULL narrowed epilogue and
// still denotes the oracle with conservation clean at quiescence. FMEA = a dropped/
// duplicated park → metamorphic RED; an un-drained `staged_*` → grant-locality RED.
//
// MUT-GAPB6-1 (LOSE a park in the narrowed publish): append `staged_spawn.items`
//   AFTER resetting `staged_spawn` to empty (publish the emptied buffer) → the
//   spawn park is dropped → `parked_spawn` differs from the `applyStagedParks`
//   oracle → metamorphic RED.
// MUT-GAPB6-2 (DON'T drain `staged_*` in the snapshot — copy instead of move):
//   leave `staged_*` populated after the snapshot → grant-locality broken (a
//   concurrent `interpret`'s next stage would mix into an un-drained buffer, and
//   the entry would be double-published next grant) → the "staged empty after
//   snapshot" conservation assertion RED.

// LAW gap-b-6 METAMORPHIC (denote-invariant PUBLISH relocation + grant-locality):
// the SMP epilogue's grant-local SNAPSHOT (move `staged_*` out under `L_v`) plus
// the `L_c`-ALONE append into `parked_*` produces EXACTLY the `parked_*` set/order
// the old single-`L_v`-section `applyStagedParks` produced from the same `staged_*`
// input (relocation is behaviour-preserving), AND the snapshot DRAINS `staged_*`
// to empty (the grant-locality guard that lets a concurrent `interpret` refill it
// without mixing). MUT-GAPB6-1 (drop a park) reds the metamorphic equality;
// MUT-GAPB6-2 (don't drain) reds the staged-empty assertion.
test "LAW gap-b-6 METAMORPHIC: the grant-local snapshot + L_c-alone parked publish is denote-identical to applyStagedParks (same parked set/order) and drains staged (grant-locality)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();

    // Build a fixed staged input over a few seeds' worth of shapes.
    var seed: u64 = 0;
    while (seed < 8) : (seed += 1) {
        const n_spawn: usize = @intCast(seed % 4); // 0..3 spawn parks
        const n_sys: usize = @intCast((seed / 4) % 3); // 0..2 systask parks

        // ---- ORACLE path: staged -> parked via applyStagedParks (old, all under one section)
        var vo = try Vm.init(gpa, &atoms);
        defer vo.deinit();
        const po = try vo.spawn(halt_prog, 0, null);
        const mo = &vo.procs.items[po].machine;
        var k: usize = 0;
        while (k < n_spawn) : (k += 1) {
            try vo.staged_spawn.append(gpa, .{ .reqid = seed *% 100 + k, .to = po, .child = @intCast(k), .reply = FinalTerms.int(&mo.ctx, @intCast(seed *% 10 + k)), .vhash = FinalTerms.hashTerm(&mo.ctx, FinalTerms.int(&mo.ctx, @intCast(seed *% 10 + k))) });
        }
        k = 0;
        while (k < n_sys) : (k += 1) {
            try vo.staged_systask.append(gpa, .{ .to = po, .reply = FinalTerms.int(&mo.ctx, @intCast(seed *% 20 + k)), .vhash = FinalTerms.hashTerm(&mo.ctx, FinalTerms.int(&mo.ctx, @intCast(seed *% 20 + k))) });
        }
        try vo.applyStagedParks();
        // oracle drained staged and holds n_spawn/n_sys parked entries.
        try std.testing.expectEqual(@as(usize, 0), vo.staged_spawn.items.len);
        try std.testing.expectEqual(@as(usize, 0), vo.staged_systask.items.len);
        try std.testing.expectEqual(n_spawn, vo.parked_spawn.items.len);
        try std.testing.expectEqual(n_sys, vo.parked_systask.items.len);

        // ---- FINAL path: the gap-b-6 grant-local snapshot MOVE + L_c-alone append
        var vf = try Vm.init(gpa, &atoms);
        defer vf.deinit();
        const pf = try vf.spawn(halt_prog, 0, null);
        const mf = &vf.procs.items[pf].machine;
        k = 0;
        while (k < n_spawn) : (k += 1) {
            try vf.staged_spawn.append(gpa, .{ .reqid = seed *% 100 + k, .to = pf, .child = @intCast(k), .reply = FinalTerms.int(&mf.ctx, @intCast(seed *% 10 + k)), .vhash = FinalTerms.hashTerm(&mf.ctx, FinalTerms.int(&mf.ctx, @intCast(seed *% 10 + k))) });
        }
        k = 0;
        while (k < n_sys) : (k += 1) {
            try vf.staged_systask.append(gpa, .{ .to = pf, .reply = FinalTerms.int(&mf.ctx, @intCast(seed *% 20 + k)), .vhash = FinalTerms.hashTerm(&mf.ctx, FinalTerms.int(&mf.ctx, @intCast(seed *% 20 + k))) });
        }
        // (A) SNAPSHOT under `L_v` (grant-local zero-copy move) — exactly the worker code.
        var snap_spawn: @TypeOf(vf.staged_spawn) = .empty;
        var snap_systask: @TypeOf(vf.staged_systask) = .empty;
        snap_spawn = vf.staged_spawn;
        vf.staged_spawn = .empty;
        snap_systask = vf.staged_systask;
        vf.staged_systask = .empty;
        // GRANT-LOCALITY guard: staged is DRAINED (MUT-GAPB6-2 leaves it populated → RED).
        try std.testing.expectEqual(@as(usize, 0), vf.staged_spawn.items.len);
        try std.testing.expectEqual(@as(usize, 0), vf.staged_systask.items.len);
        // (B) `L_c`-ALONE append (pid still owned in the worker; here just the publish).
        vf.l_c.lock();
        if (snap_spawn.items.len != 0) try vf.parked_spawn.appendSlice(gpa, snap_spawn.items);
        if (snap_systask.items.len != 0) try vf.parked_systask.appendSlice(gpa, snap_systask.items);
        vf.l_c.unlock();
        snap_spawn.deinit(gpa);
        snap_systask.deinit(gpa);

        // METAMORPHIC: FINAL parked_* == ORACLE parked_* (same count + same entries in order).
        try std.testing.expectEqual(vo.parked_spawn.items.len, vf.parked_spawn.items.len);
        try std.testing.expectEqual(vo.parked_systask.items.len, vf.parked_systask.items.len);
        for (vo.parked_spawn.items, vf.parked_spawn.items) |a, b| {
            try std.testing.expectEqual(a.reqid, b.reqid); // MUT-GAPB6-1 (dropped park) reds this
            try std.testing.expectEqual(a.child, b.child);
        }
        for (vo.parked_systask.items, vf.parked_systask.items) |a, b| {
            try std.testing.expectEqual(a.to, b.to);
        }
    }
}

test "E8.2j PENDING DIST CONNECTION: node handle is reused while pending and connection id increments after abort" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const caller = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[caller].machine;
    const node1 = FinalTerms.atom(&m.ctx, try atoms.intern("other@host"));
    const node2 = FinalTerms.atom(&m.ctx, try atoms.intern("more@host"));

    const c1 = try vm.doNewDistConnection(m, node1);
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&m.ctx, c1));
    try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&m.ctx, c1));
    const cid1 = FinalTerms.smallValOf(FinalTerms.tupleElem(&m.ctx, c1, 0));
    const ref1 = FinalTerms.tupleElem(&m.ctx, c1, 1);
    try std.testing.expect(FinalTerms.repIsRef(&m.ctx, ref1));

    const c2 = try vm.doNewDistConnection(m, node1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, c1, c2));

    const c3 = try vm.doNewDistConnection(m, node2);
    try std.testing.expect(!FinalTerms.eqlExact(&m.ctx, c1, c3));
    try std.testing.expect(FinalTerms.repIsRef(&m.ctx, FinalTerms.tupleElem(&m.ctx, c3, 1)));

    try std.testing.expectError(error.Badarg, vm.doAbortPendingDistConnection(m, node2, c1));
    const ok1 = try vm.doAbortPendingDistConnection(m, node1, c1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, ok1, FinalTerms.atom(&m.ctx, m.bool_true)));
    const ok2 = try vm.doAbortPendingDistConnection(m, node1, c1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, ok2, FinalTerms.atom(&m.ctx, m.bool_true)));

    const c4 = try vm.doNewDistConnection(m, node1);
    const cid4 = FinalTerms.smallValOf(FinalTerms.tupleElem(&m.ctx, c4, 0));
    const ref4 = FinalTerms.tupleElem(&m.ctx, c4, 1);
    try std.testing.expect(cid4 > cid1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, ref1, ref4));

    try std.testing.expectError(error.Badarg, vm.doAbortPendingDistConnection(m, node1, ref1));
}

test "E8.2l LIVE DIST ENTRY: pending handle promotion gates connected-node observation" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const caller = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[caller].machine;
    const node1 = FinalTerms.atom(&m.ctx, try atoms.intern("other@host"));
    const node2 = FinalTerms.atom(&m.ctx, try atoms.intern("more@host"));
    const opts = try FinalTerms.tuple(&m.ctx, &.{
        FinalTerms.int(&m.ctx, 468283523004),
        FinalTerms.int(&m.ctx, 4),
    });

    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.distLiveNodesTerm(m), FinalTerms.nil(&m.ctx)));

    const c1 = try vm.doNewDistConnection(m, node1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.distLiveNodesTerm(m), FinalTerms.nil(&m.ctx)));
    try std.testing.expectError(error.Badarg, vm.doPromotePendingDistConnection(m, node2, c1, opts));
    try std.testing.expectError(error.Badarg, vm.doPromotePendingDistConnection(m, node1, c1, FinalTerms.int(&m.ctx, 0)));

    _ = try vm.doAbortPendingDistConnection(m, node1, c1);
    try std.testing.expectError(error.Badarg, vm.doPromotePendingDistConnection(m, node1, c1, opts));

    const c2 = try vm.doNewDistConnection(m, node1);
    const ok = try vm.doPromotePendingDistConnection(m, node1, c2, opts);
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, ok) == .tuple);
    try std.testing.expectEqual(@as(usize, 1), vm.dist_entries.items.len);
    try std.testing.expect(vm.dist_entries.items[0].live);
    try std.testing.expect(!vm.dist_entries.items[0].pending);
    try std.testing.expectEqual(@as(u32, 4), vm.dist_entries.items[0].peer_creation);
    try std.testing.expectEqual(@as(i64, 468283523004), vm.dist_entries.items[0].peer_dflags);

    const connected = try vm.distLiveNodesTerm(m);
    try std.testing.expectEqual(FinalTerms.Kind.cons, FinalTerms.kindOf(&m.ctx, connected));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.listHead(&m.ctx, connected), node1));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.listTail(&m.ctx, connected), FinalTerms.nil(&m.ctx)));

    try std.testing.expectError(error.Badarg, vm.doAbortPendingDistConnection(m, node1, c2));
    const c3 = try vm.doNewDistConnection(m, node1);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, c2, c3));
    try std.testing.expectError(error.Badarg, vm.doPromotePendingDistConnection(m, node1, c2, opts));
}

test "E8.2m CHANNEL-START ACTION BRIDGE: Vm preserves no-carrier rejection without live install" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };

    const set_pid = try vm.spawn(idle, 0, null);
    const sm = &vm.procs.items[set_pid].machine;
    const node = FinalTerms.atom(&sm.ctx, try atoms.intern("other@host"));
    sm.pending = .{ .set_dist_node = .{
        .node = node,
        .creation = FinalTerms.int(&sm.ctx, 4),
    } };
    try vm.interpret(set_pid);
    try std.testing.expectEqual(ia.Status.crashed, sm.status);
    try std.testing.expect(FinalTerms.eqlExact(&sm.ctx, sm.result, FinalTerms.atom(&sm.ctx, sm.badarg)));
    try std.testing.expectEqual(@as(usize, 0), vm.dist_entries.items.len);

    const chan_pid = try vm.spawn(idle, 0, null);
    const cm = &vm.procs.items[chan_pid].machine;
    const cnode = FinalTerms.atom(&cm.ctx, try atoms.intern("other@host"));
    const controller = try FinalTerms.pid(&cm.ctx, chan_pid, 0);
    const opts = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.int(&cm.ctx, 468283523004),
        FinalTerms.int(&cm.ctx, 4),
    });
    cm.pending = .{ .create_dist_channel = .{
        .node = cnode,
        .controller = controller,
        .opts = opts,
    } };
    try vm.interpret(chan_pid);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, cm.regs[0], FinalTerms.atom(&cm.ctx, cm.badarg)));
    try std.testing.expectEqual(@as(usize, 0), vm.dist_entries.items.len);
}

test "E8.2r CREATE DIST CHANNEL: pending entry promotes only with live controller" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const controller_pid = try vm.spawn(idle, 0, null);
    const caller_pid = try vm.spawn(idle, 0, null);
    const dead_controller_pid = try vm.spawn(idle, 0, null);
    const net_kernel_pid = try vm.spawn(idle, 0, null);
    const cm = &vm.procs.items[caller_pid].machine;
    const node = FinalTerms.atom(&cm.ctx, try atoms.intern("other@host"));
    const controller = try FinalTerms.pid(&cm.ctx, controller_pid, 0);
    const dead_controller = try FinalTerms.pid(&cm.ctx, dead_controller_pid, 0);
    try vm.terminate(dead_controller_pid, FinalTerms.atom(&cm.ctx, vm.a_normal));
    const opts = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.int(&cm.ctx, 468283523004),
        FinalTerms.int(&cm.ctx, 4),
    });

    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, node, controller, opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
    const conn = try vm.doNewDistConnection(cm, node);
    try std.testing.expectEqual(@as(usize, 1), vm.dist_entries.items.len);
    try std.testing.expect(vm.dist_entries.items[0].pending);
    try std.testing.expect(!vm.dist_entries.items[0].live);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, node, controller, opts), FinalTerms.atom(&cm.ctx, cm.badarg)));

    const net_kernel_name = try atoms.intern("net_kernel");
    try vm.registry.register(net_kernel_name, net_kernel_pid, true);
    const local_node = FinalTerms.atom(&cm.ctx, try atoms.intern("zig@host"));
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doSetDistNode(cm, local_node, FinalTerms.int(&cm.ctx, 4)), FinalTerms.atom(&cm.ctx, cm.bool_true)));

    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, node, FinalTerms.int(&cm.ctx, controller_pid), opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
    const foreign_controller = try FinalTerms.pidExt(&cm.ctx, controller_pid, 0, try atoms.intern("remote@host"), 0);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, node, foreign_controller, opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
    const absent_controller = try FinalTerms.pid(&cm.ctx, 9999, 0);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, node, absent_controller, opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, node, dead_controller, opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, conn, try vm.doNewDistConnection(cm, node)));

    const res = try vm.doCreateDistChannel(cm, node, controller, opts);
    try std.testing.expect(FinalTerms.kindOf(&cm.ctx, res) == .tuple);
    try std.testing.expect(vm.dist_entries.items[0].live);
    try std.testing.expect(!vm.dist_entries.items[0].pending);
    try std.testing.expectEqual(controller, vm.dist_entries.items[0].controller.?);
    try std.testing.expectEqual(@as(u32, 4), vm.dist_entries.items[0].peer_creation);
    try std.testing.expectEqual(@as(i64, 468283523004), vm.dist_entries.items[0].peer_dflags);

    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, node, controller, opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
}

test "E8.2ac MANDATORY DFLAGS: live channel promotion rejects missing mandatory bits" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const controller_pid = try vm.spawn(idle, 0, null);
    const caller_pid = try vm.spawn(idle, 0, null);
    const net_kernel_pid = try vm.spawn(idle, 0, null);
    const cm = &vm.procs.items[caller_pid].machine;
    const peer = FinalTerms.atom(&cm.ctx, try atoms.intern("peer@host"));
    const controller = try FinalTerms.pid(&cm.ctx, controller_pid, 0);
    const missing_mandatory = Vm.dist_dflags_required & ~Vm.dist_dflags_mandatory;
    const optional_unicode_missing = Vm.dist_dflags_required & ~Vm.dist_dflag_unicode_io;
    const bad_opts = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.int(&cm.ctx, missing_mandatory),
        FinalTerms.int(&cm.ctx, 9),
    });
    const good_opts = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.int(&cm.ctx, optional_unicode_missing),
        FinalTerms.int(&cm.ctx, 9),
    });

    const net_kernel_name = try atoms.intern("net_kernel");
    try vm.registry.register(net_kernel_name, net_kernel_pid, true);
    const local_node = FinalTerms.atom(&cm.ctx, try atoms.intern("local@host"));
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doSetDistNode(cm, local_node, FinalTerms.int(&cm.ctx, 4)), FinalTerms.atom(&cm.ctx, cm.bool_true)));

    _ = try vm.doNewDistConnection(cm, peer);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, peer, controller, bad_opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
    try std.testing.expect(vm.dist_entries.items[0].pending);
    try std.testing.expect(!vm.dist_entries.items[0].live);
    try std.testing.expect(vm.dist_entries.items[0].controller == null);
    try std.testing.expectError(error.Badarg, vm.doPromotePendingDistConnection(cm, peer, try Vm.distConnectionTerm(cm, &vm.dist_entries.items[0]), bad_opts));

    const res = try vm.doCreateDistChannel(cm, peer, controller, good_opts);
    try std.testing.expect(FinalTerms.kindOf(&cm.ctx, res) == .tuple);
    try std.testing.expect(vm.dist_entries.items[0].live);
    try std.testing.expect(!vm.dist_entries.items[0].pending);
    try std.testing.expectEqual(controller, vm.dist_entries.items[0].controller.?);
    try std.testing.expectEqual(@as(i64, optional_unicode_missing), vm.dist_entries.items[0].peer_dflags);
}

test "E8.2ad MANDATORY DFLAGS: strict-order is not the mandatory bitset" {
    const gpa = std.testing.allocator;
