    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doSetDistNode(cm, local_node, FinalTerms.int(&cm.ctx, 4)), FinalTerms.atom(&cm.ctx, cm.bool_true)));

    const strict_ok_node = FinalTerms.atom(&cm.ctx, try atoms.intern("strict-ok@host"));
    const strict_order_missing = Vm.dist_dflags_required & ~Vm.dist_dflag_strict_order;
    const strict_ok_opts = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.int(&cm.ctx, strict_order_missing),
        FinalTerms.int(&cm.ctx, 10),
    });
    _ = try vm.doNewDistConnection(cm, strict_ok_node);
    const res = try vm.doCreateDistChannel(cm, strict_ok_node, controller, strict_ok_opts);
    try std.testing.expect(FinalTerms.kindOf(&cm.ctx, res) == .tuple);
    const strict_idx = vm.distEntryByNode(FinalTerms.atomIdxOf(strict_ok_node)).?;
    try std.testing.expect(vm.dist_entries.items[strict_idx].live);
    try std.testing.expectEqual(strict_order_missing, vm.dist_entries.items[strict_idx].peer_dflags);

    const real_mandatory_missing = Vm.dist_dflags_required & ~Vm.dist_dflag_unlink_id;
    const bad_node = FinalTerms.atom(&cm.ctx, try atoms.intern("bad-mandatory@host"));
    const bad_opts = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.int(&cm.ctx, real_mandatory_missing),
        FinalTerms.int(&cm.ctx, 11),
    });
    _ = try vm.doNewDistConnection(cm, bad_node);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doCreateDistChannel(cm, bad_node, controller, bad_opts), FinalTerms.atom(&cm.ctx, cm.badarg)));
    const bad_idx = vm.distEntryByNode(FinalTerms.atomIdxOf(bad_node)).?;
    try std.testing.expect(vm.dist_entries.items[bad_idx].pending);
    try std.testing.expect(!vm.dist_entries.items[bad_idx].live);

    try std.testing.expect(!vm.refreshLiveDistPeerDFlags(FinalTerms.atomIdxOf(strict_ok_node), 10, real_mandatory_missing));
    try std.testing.expectEqual(strict_order_missing, vm.dist_entries.items[strict_idx].peer_dflags);
}

test "E8.2s LOCAL DIST NODE IDENTITY: setnode is net_kernel-owned and observers are Vm-owned" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const net_kernel_pid = try vm.spawn(idle, 0, null);
    const caller_pid = try vm.spawn(idle, 0, null);
    const cm = &vm.procs.items[caller_pid].machine;
    const local_node = FinalTerms.atom(&cm.ctx, try atoms.intern("zig@host"));
    const other_node = FinalTerms.atom(&cm.ctx, try atoms.intern("other@host"));

    try std.testing.expectError(error.Badarg, vm.doSetDistNode(cm, local_node, FinalTerms.int(&cm.ctx, 0)));
    try std.testing.expectEqualStrings(ta.local_node_name, cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(try vm.doGetDistNode(cm))));
    try std.testing.expectEqualStrings("undefined", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(try vm.doGetDistCreation(cm))));

    // DIVERGENCE 723: is_alive/0 is FALSE before the node is distributed.
    cm.pending = .is_node_alive;
    try vm.interpret(caller_pid);
    try std.testing.expectEqualStrings("false", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(cm.regs[0])));

    const net_kernel_name = try atoms.intern("net_kernel");
    try vm.registry.register(net_kernel_name, net_kernel_pid, true);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doSetDistNode(cm, local_node, FinalTerms.int(&cm.ctx, 0)), FinalTerms.atom(&cm.ctx, cm.bool_true)));
    try std.testing.expectEqualStrings("zig@host", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(try vm.doGetDistNode(cm))));
    try std.testing.expectEqual(@as(i64, 4), FinalTerms.smallValOf(try vm.doGetDistCreation(cm)));
    try std.testing.expectError(error.Badarg, vm.doSetDistNode(cm, other_node, FinalTerms.int(&cm.ctx, 4)));

    // DIVERGENCE 723: is_alive/0 flips to TRUE once distributed (a real function
    // of the VM dist state, not a hardcoded constant).
    cm.pending = .is_node_alive;
    try vm.interpret(caller_pid);
    try std.testing.expectEqualStrings("true", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(cm.regs[0])));

    cm.pending = .get_dist_node;
    try vm.interpret(caller_pid);
    try std.testing.expectEqualStrings("zig@host", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(cm.regs[0])));

    cm.pending = .get_dist_creation;
    try vm.interpret(caller_pid);
    try std.testing.expectEqual(@as(i64, 4), FinalTerms.smallValOf(cm.regs[0]));

    cm.pending = .{ .list_dist_nodes = .{
        .connected = false,
        .visible = false,
        .hidden = false,
        .known = true,
        .this_node = false,
    } };
    try vm.interpret(caller_pid);
    const known = cm.regs[0];
    try std.testing.expectEqual(FinalTerms.Kind.cons, FinalTerms.kindOf(&cm.ctx, known));
    try std.testing.expectEqualStrings("zig@host", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.listHead(&cm.ctx, known))));
    try std.testing.expectEqual(FinalTerms.Kind.nil, FinalTerms.kindOf(&cm.ctx, FinalTerms.listTail(&cm.ctx, known)));

    const net_kernel_term = FinalTerms.atom(&cm.ctx, net_kernel_name);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doUnregister(cm, net_kernel_term), FinalTerms.atom(&cm.ctx, cm.bool_true)));
    try std.testing.expectEqualStrings(ta.local_node_name, cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(try vm.doGetDistNode(cm))));
    try std.testing.expectEqualStrings("undefined", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(try vm.doGetDistCreation(cm))));

    try vm.registry.register(net_kernel_name, net_kernel_pid, true);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doSetDistNode(cm, local_node, FinalTerms.int(&cm.ctx, 5)), FinalTerms.atom(&cm.ctx, cm.bool_true)));
    try std.testing.expectEqual(@as(i64, 5), FinalTerms.smallValOf(try vm.doGetDistCreation(cm)));
    const conn = try vm.doNewDistConnection(cm, other_node);
    const controller = try FinalTerms.pid(&cm.ctx, caller_pid, 0);
    const opts = try FinalTerms.tuple(&cm.ctx, &.{
        FinalTerms.int(&cm.ctx, 468283523004),
        FinalTerms.int(&cm.ctx, 4),
    });
    const res = try vm.doCreateDistChannel(cm, other_node, controller, opts);
    try std.testing.expect(FinalTerms.kindOf(&cm.ctx, res) == .tuple);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doMonitorDistNode(cm, caller_pid, other_node, true), FinalTerms.atom(&cm.ctx, cm.bool_true)));
    try std.testing.expectEqual(@as(usize, 1), vm.dist_node_monitors.items.len);
    try std.testing.expectEqual(FinalTerms.smallValOf(FinalTerms.tupleElem(&cm.ctx, conn, 0)), @as(i64, @intCast(vm.dist_entries.items[0].conn_id)));
    const expected_handle_words = Vm.refWordsForKey(vm.dist_entries.items[0].handle_ref);
    try std.testing.expectEqual(expected_handle_words, FinalTerms.refWords(&cm.ctx, FinalTerms.tupleElem(&cm.ctx, conn, 1)));

    try vm.terminate(net_kernel_pid, FinalTerms.atom(&cm.ctx, vm.a_normal));
    try std.testing.expectEqualStrings(ta.local_node_name, cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(try vm.doGetDistNode(cm))));
    try std.testing.expectEqualStrings("undefined", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(try vm.doGetDistCreation(cm))));
    try std.testing.expectEqual(@as(usize, 0), vm.dist_node_monitors.items.len);
    try std.testing.expectEqual(@as(usize, 1), vm.dist_entries.items.len);
    try std.testing.expect(!vm.dist_entries.items[0].live);
    try std.testing.expect(!vm.dist_entries.items[0].pending);
    try std.testing.expectEqual(@as(?FinalTerms.Term, null), vm.dist_entries.items[0].controller);
    try vm.drainSignalsPub(caller_pid);
    var qbuf: [4]mba.Msg(FinalTerms) = undefined;
    const q = cm.mbox.toSeq(&qbuf);
    try std.testing.expectEqual(@as(usize, 1), q.len);
    const msg = q[0].payload;
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&cm.ctx, msg));
    try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&cm.ctx, msg));
    try std.testing.expectEqualStrings("nodedown", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&cm.ctx, msg, 0))));
    try std.testing.expectEqualStrings("other@host", cm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&cm.ctx, msg, 1))));
}

// e21-t2 (DIVERGENCE 490, amending 97): the `node/0` bif-trap DST-DELIVERY law.
// A guard-bif compiled as `bif0` (e.g. `node/0`) TRAPS (`get_dist_node`), and its
// resolved value must reach the OPCODE's real Dst — which is a NON-x0 register
// when the other comparison operand (`node(self())`) is live in x0. The pre-fix
// scheduler delivered the trap result to x0 UNCONDITIONALLY, so the trapping
// operand kept its nil placeholder ([]) and `node(self()) =:= node()` returned
// false — the exact miss that blocked proc_lib:proc_info/2's first guard on the
// OTP-behaviour boot path. The fix threads the Dst through `bif_trap_dst` +
// `Machine.deliverTrap`. Two arms: (1) a recorded non-x0 Dst receives the value
// and x0 is UNTOUCHED (the mutant that ignores bif_trap_dst dies here); (2) the
// default (bif_trap_dst == null, the call_ext_bif convention) delivers to x0.
test "LAW e21-t2 node-trap-dst-delivery: a trapped bif0 result lands in its opcode Dst, not x0 (DIVERGENCE 490)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const pid = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[pid].machine;

    // Arm (1): pin a sentinel in x0 (as if it held node(self())'s result), record
    // a non-x0 Dst for the trapping node/0, then interpret the get_dist_node trap.
    const sentinel = FinalTerms.atom(&m.ctx, try atoms.intern("sentinel_x0"));
    m.regs[0] = sentinel;
    m.bif_trap_dst = .{ .x = 3 };
    m.pending = .get_dist_node;
    try vm.interpret(pid);
    // the resolved local node landed in x3 …
    try std.testing.expectEqualStrings(ta.local_node_name, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(m.regs[3])));
    // … and x0 was NOT clobbered (the pre-fix bug wrote x0).
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], sentinel));
    // the redirect is consumed exactly once.
    try std.testing.expect(m.bif_trap_dst == null);

    // Arm (2): with no recorded Dst (call_ext_bif convention) delivery is x0.
    m.regs[0] = sentinel;
    m.bif_trap_dst = null;
    m.pending = .get_dist_node;
    try vm.interpret(pid);
    try std.testing.expectEqualStrings(ta.local_node_name, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(m.regs[0])));
}

fn readU32beBytes(bytes: []const u8, pos: usize) u32 {
    return (@as(u32, bytes[pos]) << 24) |
        (@as(u32, bytes[pos + 1]) << 16) |
        (@as(u32, bytes[pos + 2]) << 8) |
        @as(u32, bytes[pos + 3]);
}

fn expectIdentityWire(bytes: []const u8, tag: u8, node_name: []const u8, creation: u32) !void {
    try std.testing.expect(bytes.len >= 4);
    try std.testing.expectEqual(etf.VERSION_MAGIC, bytes[0]);
    try std.testing.expectEqual(tag, bytes[1]);
    const node_start: usize = switch (tag) {
        88, 120 => 2,
        90 => 4,
        else => unreachable,
    };
    try std.testing.expectEqual(@as(u8, 119), bytes[node_start]);
    const n: usize = bytes[node_start + 1];
    try std.testing.expectEqualSlices(u8, node_name, bytes[node_start + 2 .. node_start + 2 + n]);
    const after_node = node_start + 2 + n;
    const creation_pos = switch (tag) {
        88, 120 => after_node + 8,
        90 => after_node,
        else => unreachable,
    };
    try std.testing.expectEqual(creation, readU32beBytes(bytes, creation_pos));
}

