test "E8.2u LOCAL IDENTITY ETF OBSERVER: term_to_binary and external_size follow setnode without payload rewrite" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
