        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const net_kernel_pid = try vm.spawn(idle, 0, null);
    const caller_pid = try vm.spawn(idle, 0, null);
