        try std.testing.expectEqual(FinalTerms.atomIdxOf(configured_node), p.machine.dist_local_node.?);
        try std.testing.expectEqual(@as(u32, 7), p.machine.dist_local_creation);
    }

    try std.testing.expectEqualStrings(ta.local_node_name, FinalTerms.pidNodeName(&cm.ctx, local_pid));
    try std.testing.expectEqual(@as(u32, 0), FinalTerms.pidCreation(&cm.ctx, local_pid));
    var pure_after = try etf.encode(gpa, &cm.ctx, local_pid);
    defer pure_after.deinit(gpa);
    try expectIdentityWire(pure_after.items, 88, ta.local_node_name, 0);

    const pid_bin = try conv.term_to_binary_1(cm, &.{local_pid});
    try expectIdentityWire(FinalTerms.binBytes(&cm.ctx, pid_bin), 88, "zig@host", 7);
    const port_bin = try conv.term_to_binary_1(cm, &.{local_port});
    try expectIdentityWire(FinalTerms.binBytes(&cm.ctx, port_bin), 120, "zig@host", 7);
    const ref_bin = try conv.term_to_binary_1(cm, &.{local_ref});
    try expectIdentityWire(FinalTerms.binBytes(&cm.ctx, ref_bin), 90, "zig@host", 7);
    const foreign_bin = try conv.term_to_binary_1(cm, &.{foreign_pid});
    try expectIdentityWire(FinalTerms.binBytes(&cm.ctx, foreign_bin), 88, "other@host", 3);

    const nested = try FinalTerms.tuple(&cm.ctx, &.{ local_pid, local_port, local_ref, foreign_pid });
    const nested_bin = try conv.term_to_binary_1(cm, &.{nested});
    const nested_size = try conv.external_size_1(cm, &.{nested});
    try std.testing.expectEqual(@as(i64, @intCast(FinalTerms.binSize(&cm.ctx, nested_bin))), FinalTerms.smallValOf(nested_size));
    const decoded = try conv.binary_to_term_1(cm, &.{nested_bin});
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&cm.ctx, decoded));
    const dp = FinalTerms.tupleElem(&cm.ctx, decoded, 0);
    const dport = FinalTerms.tupleElem(&cm.ctx, decoded, 1);
    const dr = FinalTerms.tupleElem(&cm.ctx, decoded, 2);
    const df = FinalTerms.tupleElem(&cm.ctx, decoded, 3);
    try std.testing.expectEqualStrings("zig@host", FinalTerms.pidNodeName(&cm.ctx, dp));
    try std.testing.expectEqual(@as(u32, 7), FinalTerms.pidCreation(&cm.ctx, dp));
    try std.testing.expectEqualStrings("zig@host", FinalTerms.portNodeName(&cm.ctx, dport));
    try std.testing.expectEqual(@as(u32, 7), FinalTerms.portCreation(&cm.ctx, dport));
    try std.testing.expectEqualStrings("zig@host", FinalTerms.refNodeName(&cm.ctx, dr));
    try std.testing.expectEqual(@as(u32, 7), FinalTerms.refCreation(&cm.ctx, dr));
    try std.testing.expectEqualStrings("other@host", FinalTerms.pidNodeName(&cm.ctx, df));
    try std.testing.expectEqual(@as(u32, 3), FinalTerms.pidCreation(&cm.ctx, df));

    const spawned_after = try vm.spawn(idle, 0, null);
    const am = &vm.procs.items[spawned_after].machine;
    try std.testing.expectEqual(FinalTerms.atomIdxOf(configured_node), am.dist_local_node.?);
    try std.testing.expectEqual(@as(u32, 7), am.dist_local_creation);

    const net_kernel_term = FinalTerms.atom(&cm.ctx, net_kernel_name);
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, try vm.doUnregister(cm, net_kernel_term), FinalTerms.atom(&cm.ctx, cm.bool_true)));
    for (vm.procs.items) |p| {
        try std.testing.expect(p.machine.dist_local_node == null);
        try std.testing.expectEqual(@as(u32, 0), p.machine.dist_local_creation);
    }
    const cleared_bin = try conv.term_to_binary_1(cm, &.{local_pid});
    try expectIdentityWire(FinalTerms.binBytes(&cm.ctx, cleared_bin), 88, ta.local_node_name, 0);
}

test "E8.2n DIST NODES OBSERVER: public nodes action reads only live DistEntries" {
