    try std.testing.expect(FinalTerms.kindOf(&lm.ctx, observed) == .cons);
    try std.testing.expectEqualStrings(ta.local_node_name, lm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.listHead(&lm.ctx, observed))));
    const tail = FinalTerms.listTail(&lm.ctx, observed);
    try std.testing.expect(FinalTerms.kindOf(&lm.ctx, tail) == .cons);
    try std.testing.expect(FinalTerms.eqlExact(&lm.ctx, FinalTerms.listHead(&lm.ctx, tail), node));
    try std.testing.expect(FinalTerms.kindOf(&lm.ctx, FinalTerms.listTail(&lm.ctx, tail)) == .nil);
}

