test "LAW E18.3 REVERSE-CARRIER: registerLiveDistPeer makes nodes/0 reflect the peer; teardown removes it" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const pid = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[pid].machine;

    // A real handshake authenticates the peer OUT OF BAND; register the outcome.
    // 468283523004 admits the mandatory dist DFLAGs (matching the E8.2 vectors).
    const peer1 = try atoms.intern("zigvmrev@127.0.0.1");
    const peer2 = try atoms.intern("other@127.0.0.1");
    const peer1_term = FinalTerms.atom(&m.ctx, peer1);
    const peer2_term = FinalTerms.atom(&m.ctx, peer2);

    // nodes/0-reflects-peer: before any register, connected-nodes is empty.
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.distLiveNodesTerm(m), FinalTerms.nil(&m.ctx)));

    const c1 = try vm.registerLiveDistPeer(peer1, 7, 468283523004);
    const c2 = try vm.registerLiveDistPeer(peer2, 9, 468283523004);
    try std.testing.expect(c1 != c2); // distinct connection ids

    // The REAL nodes/0 BIF path (a .list_dist_nodes pending action interpreted)
    // now reflects both peers — this is zigvm's OWN running-VM observation.
    m.pending = .{ .list_dist_nodes = .{
        .connected = true,
        .visible = false,
        .hidden = false,
        .known = false,
        .this_node = false,
    } };
    try vm.interpret(pid);
    const listed = m.regs[0];
    // Walk the list; both peer atoms must be present, nothing else.
    var seen1 = false;
    var seen2 = false;
    var count: usize = 0;
    var cur = listed;
    while (FinalTerms.kindOf(&m.ctx, cur) == .cons) {
        const head = FinalTerms.listHead(&m.ctx, cur);
        const idx = FinalTerms.atomIdxOf(head);
        if (idx == peer1) seen1 = true;
        if (idx == peer2) seen2 = true;
        count += 1;
        cur = FinalTerms.listTail(&m.ctx, cur);
    }
    try std.testing.expect(seen1 and seen2);
    try std.testing.expectEqual(@as(usize, 2), count);

    // Idempotent re-register: same node, new incarnation — still ONE live row.
    const c1b = try vm.registerLiveDistPeer(peer1, 11, 468283523004);
    try std.testing.expectEqual(c1, c1b);
    try std.testing.expectEqual(@as(usize, 2), vm.dist_entries.items.len);
    try std.testing.expectEqual(@as(u32, 11), vm.dist_entries.items[0].peer_creation);

    // teardown→node-removed: removing peer1 drops it from nodes/0; peer2 stays.
    try std.testing.expect(try vm.removeLiveDistPeer(peer1));
    try std.testing.expect(!try vm.removeLiveDistPeer(peer1)); // second remove is a no-op
    const after = try vm.distLiveNodesTerm(m);
    try std.testing.expectEqual(FinalTerms.Kind.cons, FinalTerms.kindOf(&m.ctx, after));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, FinalTerms.listHead(&m.ctx, after), peer2_term));
    try std.testing.expect(FinalTerms.kindOf(&m.ctx, FinalTerms.listTail(&m.ctx, after)) == .nil);

    // And removing peer2 empties nodes/0 entirely.
    try std.testing.expect(try vm.removeLiveDistPeer(peer2));
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.distLiveNodesTerm(m), FinalTerms.nil(&m.ctx)));
    _ = peer1_term;
}

