test "E8.2q DIST NODE MONITOR: live DistEntry gates monitor_node and nodedown delivery" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const node_idx = try atoms.intern("other@host");

    const no_live_pid = try vm.spawn(idle, 0, null);
    const nm = &vm.procs.items[no_live_pid].machine;
    const no_live_node = FinalTerms.atom(&nm.ctx, node_idx);
    if (vm.doMonitorDistNode(nm, no_live_pid, no_live_node, true)) |_| {
        return error.TestUnexpectedResult;
    } else |err| switch (err) {
        error.Notalive => {},
        else => return err,
    }

    const watcher = try vm.spawn(idle, 0, null);
    const wm = &vm.procs.items[watcher].machine;
    const node = FinalTerms.atom(&wm.ctx, node_idx);
    const conn = try vm.doNewDistConnection(wm, node);
    const opts = try FinalTerms.tuple(&wm.ctx, &.{
        FinalTerms.int(&wm.ctx, 468283523004),
        FinalTerms.int(&wm.ctx, 3),
    });
    _ = try vm.doPromotePendingDistConnection(wm, node, conn, opts);

    try std.testing.expect(FinalTerms.eqlExact(&wm.ctx, try vm.doMonitorDistNode(wm, watcher, node, true), FinalTerms.atom(&wm.ctx, wm.bool_true)));
    try std.testing.expectEqual(@as(usize, 1), vm.dist_node_monitors.items.len);
    _ = try vm.doMonitorDistNode(wm, watcher, node, true);
    try std.testing.expectEqual(@as(usize, 1), vm.dist_node_monitors.items.len);
    _ = try vm.doMonitorDistNode(wm, watcher, node, false);
    try std.testing.expectEqual(@as(usize, 0), vm.dist_node_monitors.items.len);
    _ = try vm.doMonitorDistNode(wm, watcher, node, true);
    try std.testing.expectEqual(@as(usize, 1), vm.dist_node_monitors.items.len);

    try std.testing.expect(FinalTerms.eqlExact(&wm.ctx, try vm.doDisconnectDistNode(wm, node), FinalTerms.atom(&wm.ctx, wm.bool_true)));
    try std.testing.expectEqual(@as(usize, 0), vm.dist_node_monitors.items.len);
    try vm.drainSignalsPub(watcher);
    var qbuf: [4]mba.Msg(FinalTerms) = undefined;
    const q = wm.mbox.toSeq(&qbuf);
    try std.testing.expectEqual(@as(usize, 1), q.len);
    const msg = q[0].payload;
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&wm.ctx, msg));
    try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&wm.ctx, msg));
    try std.testing.expectEqualStrings("nodedown", wm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&wm.ctx, msg, 0))));
    try std.testing.expectEqualStrings("other@host", wm.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&wm.ctx, msg, 1))));

    try std.testing.expect(FinalTerms.eqlExact(&wm.ctx, try vm.doDisconnectDistNode(wm, node), FinalTerms.atom(&wm.ctx, wm.bool_false)));
    try vm.drainSignalsPub(watcher);
    const q2 = wm.mbox.toSeq(&qbuf);
    try std.testing.expectEqual(@as(usize, 1), q2.len);
}

test "E8.2v REMOTE EXIT SIGNAL: foreign pid records only live DistEntry outbound exits" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .recv_any = .{ .dst = 0, .else_to = 0 } }};
    const caller = try vm.spawn(idle, 0, null);
    const cp = vm.procs.items[caller];
    const m = &cp.machine;

    const node = try atoms.intern("other@host");
    const node_term = FinalTerms.atom(&m.ctx, node);
    const reason1 = FinalTerms.atom(&m.ctx, try atoms.intern("boom"));
    const reason2 = FinalTerms.atom(&m.ctx, try atoms.intern("again"));
    const priority = FinalTerms.atom(&m.ctx, try atoms.intern("priority"));
    const prio_opts = try FinalTerms.cons(&m.ctx, priority, FinalTerms.nil(&m.ctx));
    const foreign_pid = try FinalTerms.pidExt(&m.ctx, 44, 0, node, 3);

    // No live entry: public result stays true, but no outbound frame intent is fabricated.
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ foreign_pid, reason1 }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try std.testing.expect(m.pending.? == .remote_exit_signal);
    try vm.interpret(caller);
    try std.testing.expectEqual(@as(usize, 0), vm.dist_remote_exits.items.len);

    // A pending handle is not a live channel.
    const conn = try vm.doNewDistConnection(m, node_term);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ foreign_pid, reason1 }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try vm.interpret(caller);
    try std.testing.expectEqual(@as(usize, 0), vm.dist_remote_exits.items.len);

    // Only a live entry with matching peer creation records the outbound exit intent.
    const opts = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.int(&m.ctx, 468283523004), FinalTerms.int(&m.ctx, 3) });
    _ = try vm.doPromotePendingDistConnection(m, node_term, conn, opts);
    const stale_pid = try FinalTerms.pidExt(&m.ctx, 44, 0, node, 4);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ stale_pid, reason1 }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try vm.interpret(caller);
    try std.testing.expectEqual(@as(usize, 0), vm.dist_remote_exits.items.len);

    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_3(m, &.{ foreign_pid, reason1, prio_opts }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try vm.interpret(caller);
    try std.testing.expectEqual(@as(usize, 1), vm.dist_remote_exits.items.len);
    try std.testing.expectEqual(caller, vm.dist_remote_exits.items[0].from);
    try std.testing.expectEqual(node, vm.dist_remote_exits.items[0].node);
    try std.testing.expectEqual(@as(u64, 44), vm.dist_remote_exits.items[0].to);
    try std.testing.expectEqual(@as(u32, 3), vm.dist_remote_exits.items[0].creation);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, vm.dist_remote_exits.items[0].reason, reason1));

    const foreign_pid2 = try FinalTerms.pidExt(&m.ctx, 45, 0, node, 3);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ foreign_pid2, reason2 }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try vm.interpret(caller);
    try std.testing.expectEqual(@as(usize, 2), vm.dist_remote_exits.items.len);
    try std.testing.expectEqual(@as(u64, 45), vm.dist_remote_exits.items[1].to);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, vm.dist_remote_exits.items[1].reason, reason2));
}

test "LAW E20.3 TRANSITIVE-NODES-VISIBILITY (node table): zigvm's own nodes/0 is the SET of live peers — registering peer A + peer B yields {A,B}, register is idempotent, teardown of one leaves the other, of both empties it" {
    // The local vertex of the 3-node triad: zigvm holding TWO live carriers (peer
    // A and peer B, `dist-mesh`) must have its OWN nodes/0 list BOTH — the real
    // node-table observable the harness `dist-coord.transitive-nodes` row reads
    // live. distLiveNodesTerm is a SET projection (order-independent, deduped);
    // registerLiveDistPeer is idempotent per node; removeLiveDistPeer retracts.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .recv_any = .{ .dst = 0, .else_to = 0 } }};
    const self = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[self].machine;
    const a = try atoms.intern("peerA@127.0.0.1");
    const b = try atoms.intern("peerB@127.0.0.1");

    const contains = struct {
        fn f(vmp: *Vm, mm: *ia.Machine, node: ta.AtomIdx) !bool {
            const term = try vmp.distLiveNodesTerm(mm);
            var cur = term;
            while (FinalTerms.kindOf(&mm.ctx, cur) == .cons) {
                const head = FinalTerms.listHead(&mm.ctx, cur);
                if (FinalTerms.atomIdxOf(head) == node) return true;
                cur = FinalTerms.listTail(&mm.ctx, cur);
            }
            return false;
        }
        fn len(vmp: *Vm, mm: *ia.Machine) !usize {
            const term = try vmp.distLiveNodesTerm(mm);
            var cur = term;
            var n: usize = 0;
            while (FinalTerms.kindOf(&mm.ctx, cur) == .cons) : (cur = FinalTerms.listTail(&mm.ctx, cur)) n += 1;
            return n;
        }
    };

    // Empty at start.
    try std.testing.expectEqual(@as(usize, 0), try contains.len(&vm, m));
    // Register BOTH peers → nodes/0 == {A,B} (sees the other two).
    _ = try vm.registerLiveDistPeer(a, 3, 0);
    _ = try vm.registerLiveDistPeer(b, 4, 0);
    try std.testing.expectEqual(@as(usize, 2), try contains.len(&vm, m));
    try std.testing.expect(try contains.f(&vm, m, a));
    try std.testing.expect(try contains.f(&vm, m, b));
    // IDEMPOTENT: re-registering A does not duplicate the row.
    _ = try vm.registerLiveDistPeer(a, 3, 0);
    try std.testing.expectEqual(@as(usize, 2), try contains.len(&vm, m));
    // Teardown of B leaves A; teardown of A empties the view.
    try std.testing.expect(try vm.removeLiveDistPeer(b));
    try std.testing.expectEqual(@as(usize, 1), try contains.len(&vm, m));
    try std.testing.expect(try contains.f(&vm, m, a));
    try std.testing.expect(!try contains.f(&vm, m, b));
    try std.testing.expect(try vm.removeLiveDistPeer(a));
    try std.testing.expectEqual(@as(usize, 0), try contains.len(&vm, m));
}

test "E8.2w DIST DISCONNECT QUEUE BOUNDARY: outbound remote exits do not outlive a peer" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
