    const node1_term = FinalTerms.atom(&m.ctx, node1);
    const node2_term = FinalTerms.atom(&m.ctx, node2);
    const reason1 = FinalTerms.atom(&m.ctx, try atoms.intern("boom"));
    const reason2 = FinalTerms.atom(&m.ctx, try atoms.intern("stay"));
    const reason3 = FinalTerms.atom(&m.ctx, try atoms.intern("again"));
    const opts1 = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.int(&m.ctx, 468283523004), FinalTerms.int(&m.ctx, 3) });
    const opts2 = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.int(&m.ctx, 468283523004), FinalTerms.int(&m.ctx, 5) });

    const conn1 = try vm.doNewDistConnection(m, node1_term);
    const conn2 = try vm.doNewDistConnection(m, node2_term);
    _ = try vm.doPromotePendingDistConnection(m, node1_term, conn1, opts1);
    _ = try vm.doPromotePendingDistConnection(m, node2_term, conn2, opts2);

    const pid1 = try FinalTerms.pidExt(&m.ctx, 44, 0, node1, 3);
    const pid2 = try FinalTerms.pidExt(&m.ctx, 55, 0, node2, 5);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ pid1, reason1 }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try vm.interpret(caller);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ pid2, reason2 }), FinalTerms.atom(&m.ctx, m.bool_true)));
