    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.doDisconnectDistNode(m, node1_term), FinalTerms.atom(&m.ctx, m.bool_true)));
    try std.testing.expectEqual(@as(usize, 1), vm.dist_remote_exits.items.len);
    try std.testing.expectEqual(node2, vm.dist_remote_exits.items[0].node);
    try std.testing.expectEqual(@as(u64, 55), vm.dist_remote_exits.items[0].to);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, vm.dist_remote_exits.items[0].reason, reason2));

    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ pid1, reason3 }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try vm.interpret(caller);
    try std.testing.expectEqual(@as(usize, 1), vm.dist_remote_exits.items.len);

    const conn1b = try vm.doNewDistConnection(m, node1_term);
    const opts1b = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.int(&m.ctx, 468283523004), FinalTerms.int(&m.ctx, 4) });
    _ = try vm.doPromotePendingDistConnection(m, node1_term, conn1b, opts1b);
    const pid1b = try FinalTerms.pidExt(&m.ctx, 44, 0, node1, 4);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try procsys.exit_signal_2(m, &.{ pid1b, reason3 }), FinalTerms.atom(&m.ctx, m.bool_true)));
    try vm.interpret(caller);
    try std.testing.expectEqual(@as(usize, 2), vm.dist_remote_exits.items.len);
    try std.testing.expectEqual(node2, vm.dist_remote_exits.items[0].node);
    try std.testing.expectEqual(node1, vm.dist_remote_exits.items[1].node);
    try std.testing.expectEqual(@as(u32, 4), vm.dist_remote_exits.items[1].creation);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, vm.dist_remote_exits.items[1].reason, reason3));
