    _ = try vm.doPromotePendingDistConnection(m, node2_term, conn2, opts2);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, try vm.doMonitorDistNode(m, watcher, node1_term, true), FinalTerms.atom(&m.ctx, m.bool_true)));

    const pid1 = try FinalTerms.pidExt(&m.ctx, 101, 0, node1, 7);
    const pid2 = try FinalTerms.pidExt(&m.ctx, 202, 0, node2, 8);
