    try std.testing.expectEqual(node2, vm.dist_remote_exits.items[0].node);
    try std.testing.expectEqual(@as(u64, 202), vm.dist_remote_exits.items[0].to);

    const entry1 = vm.dist_entries.items[vm.distEntryByNode(node1).?];
    try std.testing.expect(!entry1.live);
    try std.testing.expect(!entry1.pending);
    try std.testing.expect(entry1.controller == null);

    try vm.drainSignalsPub(watcher);
    var qbuf: [4]mba.Msg(FinalTerms) = undefined;
    const q = m.mbox.toSeq(&qbuf);
    try std.testing.expectEqual(@as(usize, 1), q.len);
    const down = q[0].payload;
    try std.testing.expectEqualStrings("nodedown", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, down, 0))));
    try std.testing.expectEqualStrings("socket@peer", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, down, 1))));

    m.pending = .{ .disconnect_dist_node = .{ .node = node1_term } };
    try vm.interpret(watcher);
