test "E5.6 process_flag/3 save_calls: self is synchronous OLD value; a non-self target replies {ReqId, Old} with a ref via x0" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const caller = try vm.spawn(idle, 0, null);
    const target = try vm.spawn(idle, 0, null);
    const cp = vm.procs.items[caller];
    const tp = vm.procs.items[target];

    // Non-self target: the BIF traps process_flag3; the VM mints a ReqId ref
    // (x0), sets the TARGET's save_calls, and replies {ReqId, OldValue} to the
    // caller's mailbox. Old default 0; the new value lands on the target.
    const target_term = try FinalTerms.pid(&cp.machine.ctx, target, 0);
    cp.machine.pending = .{ .process_flag3 = .{ .pid = target_term, .value = 7 } };
    try vm.interpret(caller);
    try std.testing.expect(FinalTerms.repIsRef(&cp.machine.ctx, cp.machine.regs[0])); // x0 = ReqId ref
    try std.testing.expectEqual(@as(i64, 7), tp.machine.save_calls); // target flag set
    try std.testing.expectEqual(@as(usize, 1), cp.machine.mbox.len());
    var buf: [4]mba.Msg(FinalTerms) = undefined;
    const q = cp.machine.mbox.toSeq(&buf);
    try std.testing.expect(FinalTerms.tupleArity(&cp.machine.ctx, q[0].payload) == 2);
    const old = FinalTerms.tupleElem(&cp.machine.ctx, q[0].payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&cp.machine.ctx, old, FinalTerms.int(&cp.machine.ctx, 0))); // OLD = 0

    // The SELF form is handled inside the BIF (bifs/procsys.zig) — covered by its
    // own law there; here we only assert the cross-process trap semantics.
}

// ============================================================================
// E7.5 (Task 5): process-engine completions — hibernate reentry + the async
// system-task reply queue (DIVERGENCE entry 154; the E5.6 parked-reply
// precedent). Kept as one clearly-blocked test group.
// ============================================================================

test "LAW E7.5 hibernate-reentry homomorphism: hibernate DISCARDS the call stack and re-enters at M:F/A with the args; the mailbox survives" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    // A 2-function program: label 0 is the initial entry, label 2 is `loop/1`.
    const prog: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, // 0: entry (unused post-hibernate)
        .{ .jump = .{ .to = 0 } }, // 1
        .{ .recv_any = .{ .dst = 0, .else_to = 2 } }, // 2: loop/1 body
        .{ .jump = .{ .to = 2 } }, // 3
    };
    const pid = try vm.spawn(prog, 0, null);
    const p = vm.procs.items[pid];
    const m = &p.machine;
    const mod_idx = try atoms.intern("corpus");
    const fun_idx = try atoms.intern("loop");
    const exports = [_]ia.Export{.{ .module = mod_idx, .func = fun_idx, .arity = 1, .pc = 2 }};
    m.exports = &exports;

    // Give the process a NON-trivial call stack + a queued message: hibernate must
    // discard the stack yet PRESERVE the mailbox (the reentry homomorphism).
    try m.stack.append(gpa, 99);
    try m.ystack.append(gpa, FinalTerms.int(&m.ctx, 7));
    m.recv_cursor = 1;
    try vm.signal(pid, pid, .{ .message = FinalTerms.atom(&m.ctx, try atoms.intern("queued")) });
    try vm.drainSignals(pid);
    try std.testing.expectEqual(@as(usize, 1), m.mbox.len()); // queued before hibernate

    // hibernate(corpus, loop, [42]).
    const mod = FinalTerms.atom(&m.ctx, mod_idx);
    const fun = FinalTerms.atom(&m.ctx, fun_idx);
    const arglist = try FinalTerms.cons(&m.ctx, FinalTerms.int(&m.ctx, 42), FinalTerms.nil(&m.ctx));
    m.pending = .{ .hibernate = .{ .module = mod, .func = fun, .args = arglist } };
    try vm.interpret(pid);

    // The stack is DISCARDED (Mutant 2 — a resumed old frame — reddens both):
    try std.testing.expectEqual(@as(usize, 0), m.stack.items.len);
    try std.testing.expectEqual(@as(usize, 0), m.ystack.items.len);
    try std.testing.expectEqual(@as(usize, 0), m.recv_cursor);
    // RE-ENTERED at loop/1's pc with the arg in x0 (Mutant 1 — a skipped MFA
    // resolve — would leave pc/x0 unchanged):
    try std.testing.expectEqual(@as(usize, 2), m.pc);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], FinalTerms.int(&m.ctx, 42)));
    // The MAILBOX survives (the queued message is still there for the re-entered
    // `receive` to find):
    try std.testing.expectEqual(@as(usize, 1), m.mbox.len());
    try std.testing.expect(p.alive); // a resolvable MFA does NOT kill the process
}

test "LAW E7.5 hibernate to an unresolvable MFA exits `undef` (BEAM-faithful)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const pid = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[pid].machine;
    // No exports set → the MFA cannot resolve → the process exits `undef`.
    const mod = FinalTerms.atom(&m.ctx, try atoms.intern("nope"));
    const fun = FinalTerms.atom(&m.ctx, try atoms.intern("gone"));
    m.pending = .{ .hibernate = .{ .module = mod, .func = fun, .args = FinalTerms.nil(&m.ctx) } };
    try vm.interpret(pid);
    try std.testing.expect(!vm.procs.items[pid].alive); // killed
}

test "LAW e32-t1 SIGKILL: the direct exit/2 kill signal is UNTRAPPABLE and renamed `killed`; a plain kill-reason signal is ordinary (trappable)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    // Victim 1 TRAPS exits — yet the DIRECT kill signal (kill=true) must
    // terminate it anyway, with the reason RENAMED to `killed` (observed via a
    // watcher's DOWN, the erts SIGKILL contract; the pre-fix arm converted it
    // to a {'EXIT',...} message — the fleet's c_exit2_kill_trapping finding).
    const watcher = try vm.spawn(idle, 0, null);
    const v1 = try vm.spawn(idle, 0, null);
    vm.procs.items[v1].machine.trap_exit = true;
    try vm.procs.items[v1].monitored_by.append(gpa, .{ .ref = 777, .watcher = watcher });
    try vm.procs.items[watcher].monitors_held.append(gpa, .{ .ref = 777, .target = v1 });
    const kill_atom = FinalTerms.atom(&vm.procs.items[v1].machine.ctx, try atoms.intern("kill"));
    try vm.signal(watcher, v1, .{ .exit_sig = .{ .rfrag = try vm.reasonFrag(&vm.procs.items[v1].machine.ctx, kill_atom), .kill = true } });
    try vm.drainSignals(v1);
    try std.testing.expect(!vm.procs.items[v1].alive);
    // The watcher's DOWN carries `killed`, not `kill`.
    try vm.drainSignals(watcher);
    const wm = &vm.procs.items[watcher].machine;
    const down = (try wm.mbox.peekAt(0)).?.payload;
    const reason = FinalTerms.tupleElem(&wm.ctx, down, 4);
    try std.testing.expect(FinalTerms.eqlExact(&wm.ctx, reason, FinalTerms.atom(&wm.ctx, try atoms.intern("killed"))));

    // Victim 2 traps and receives an ORDINARY signal whose reason merely IS the
    // atom `kill` (kill=false — the link-propagated shape): trappable, alive,
    // converted to a {'EXIT', From, kill} message (never renamed).
    const v2 = try vm.spawn(idle, 0, null);
    vm.procs.items[v2].machine.trap_exit = true;
    const kill2 = FinalTerms.atom(&vm.procs.items[v2].machine.ctx, try atoms.intern("kill"));
    try vm.signal(watcher, v2, .{ .exit_sig = .{ .rfrag = try vm.reasonFrag(&vm.procs.items[v2].machine.ctx, kill2) } });
    try vm.drainSignals(v2);
    try std.testing.expect(vm.procs.items[v2].alive);
    const m2 = &vm.procs.items[v2].machine;
    const exit_msg = (try m2.mbox.peekAt(0)).?.payload;
    try std.testing.expect(FinalTerms.eqlExact(&m2.ctx, FinalTerms.tupleElem(&m2.ctx, exit_msg, 2), FinalTerms.atom(&m2.ctx, try atoms.intern("kill"))));
}

test "LAW E7.5 system-task EXACTLY-ONCE reply: request_system_task parks ONE {ReqId, Result} to the REQUESTER, delivered on the next tick" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const req = try vm.spawn(idle, 0, null);
    const other = try vm.spawn(idle, 0, null); // a DIFFERENT process (Mutant 1 target)
    const rp = vm.procs.items[req];
    const op_val = vm.procs.items[other];
    const m = &rp.machine;

    // request_system_task/4: requester = req, task = {garbage_collect, ReqId, major}.
    // Drive the REAL BIF (procsys.request_system_task_4) so its arg parsing + trap
    // staging are exercised, not just the interpret arm.
    const reqid = try FinalTerms.ref(&m.ctx, Vm.refWordsForKey(4242));
    const requester = try FinalTerms.pid(&m.ctx, req, 0);
    const target_term = try FinalTerms.pid(&m.ctx, other, 0);
    const gc_atom = FinalTerms.atom(&m.ctx, try atoms.intern("garbage_collect"));
    const major_atom = FinalTerms.atom(&m.ctx, try atoms.intern("major"));
    const task = try FinalTerms.tuple(&m.ctx, &.{ gc_atom, reqid, major_atom });
    const prio = FinalTerms.int(&m.ctx, 4);
    m.self_pid = @intCast(req);
    const ret = try procsys.request_system_task_4(m, &.{ requester, target_term, prio, task });
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, ret, FinalTerms.atom(&m.ctx, m.bool_true))); // synchronous true
    try vm.interpret(req);
    // Synchronous return is `true`; the reply is PARKED (not yet delivered).
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.regs[0], FinalTerms.atom(&m.ctx, m.bool_true)));
    // gap-b-3: the systask reply is STAGED by the trap, then APPLIED at the grant
    // epilogue (staged ≡ inline). A bare `interpret` leaves it in `staged_systask`.
    try std.testing.expectEqual(@as(usize, 1), vm.staged_systask.items.len);
    try std.testing.expectEqual(@as(usize, 0), vm.parked_systask.items.len);
    try vm.applyStagedParks(); // the grant-epilogue apply-point
    try std.testing.expectEqual(@as(usize, 0), vm.staged_systask.items.len); // exactly-once: staging drained
    try std.testing.expectEqual(@as(usize, 1), vm.parked_systask.items.len); // now in the global list
    try std.testing.expectEqual(@as(usize, 0), rp.machine.mbox.len());
    try std.testing.expectEqual(@as(usize, 0), op_val.machine.mbox.len());

    // The scheduler tick flushes it; drain into the requester's mailbox. EXACTLY
    // ONE {ReqId, true} reply arrives — to the REQUESTER (Mutant 1: routing it to
    // the target `other` would leave req's mailbox empty).
    try vm.deliverParkedSysTask();
    try vm.drainSignals(req);
    try std.testing.expectEqual(@as(usize, 1), rp.machine.mbox.len());
    try std.testing.expectEqual(@as(usize, 0), op_val.machine.mbox.len());
    var buf: [4]mba.Msg(FinalTerms) = undefined;
    const q = rp.machine.mbox.toSeq(&buf);
    try std.testing.expect(FinalTerms.tupleArity(&rp.machine.ctx, q[0].payload) == 2);
    const rid = FinalTerms.tupleElem(&rp.machine.ctx, q[0].payload, 0);
    const res = FinalTerms.tupleElem(&rp.machine.ctx, q[0].payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, rid, reqid)); // carries the ReqId
    try std.testing.expect(FinalTerms.eqlExact(&rp.machine.ctx, res, FinalTerms.atom(&rp.machine.ctx, rp.machine.bool_true))); // Result = true

    // EXACTLY-ONCE: a second flush delivers NOTHING (the queue was cleared).
    try vm.deliverParkedSysTask();
    try vm.drainSignals(req);
    try std.testing.expectEqual(@as(usize, 1), rp.machine.mbox.len());
    try std.testing.expectEqual(@as(usize, 0), vm.parked_systask.items.len);
}

// ============================================================================
// E5.5 (Task 5): the alias-signal model law suite (DIVERGENCE entry 19/21/33).
// ============================================================================

// Reconstruct a ref term with the SAME words in `ctx` (refs are content-
// addressed — `eqlExact`/`cmpRef` compare words — so this is observably the
// same ref in a different heap: the cross-heap ref path the send/reply uses).
fn refIn(ctx: *FinalTerms.Ctx, src: *FinalTerms.Ctx, r: FinalTerms.Term) !FinalTerms.Term {
    return FinalTerms.ref(ctx, FinalTerms.refWords(src, r));
}

test "E5.5 ALIAS DELIVERY + RETIREMENT: a send to an active alias lands in the owner's mailbox; unalias retires it and future sends drop" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const owner = try vm.spawn(idle, 0, null); // mints the alias
    const sender = try vm.spawn(idle, 0, null); // sends via the alias
    const op = vm.procs.items[owner];
    const sp = vm.procs.items[sender];

    // owner mints an alias via alias/1 (make_alias trap → ref in x3).
    op.machine.pending = .{ .make_alias = .{ .dst = 3 } };
    try vm.interpret(owner);
    const aref = op.machine.regs[3];
    try std.testing.expect(FinalTerms.repIsRef(&op.machine.ctx, aref));

    // sender sends `hello` to the alias ref (reconstructed in ITS heap).
    const hello = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("hello"));
    const sref = try refIn(&sp.machine.ctx, &op.machine.ctx, aref);
    sp.machine.pending = .{ .send_to = .{ .pid = sref, .msg = hello } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    try std.testing.expectEqual(@as(usize, 1), op.machine.mbox.len()); // DELIVERED to the owner

    // owner unaliases: first call true (was active), second false (already retired).
    op.machine.pending = .{ .unalias_ref = .{ .ref = aref } };
    try vm.interpret(owner);
    try std.testing.expect(FinalTerms.eqlExact(&op.machine.ctx, op.machine.regs[0], FinalTerms.atom(&op.machine.ctx, op.machine.bool_true)));
    op.machine.pending = .{ .unalias_ref = .{ .ref = aref } };
    try vm.interpret(owner);
    try std.testing.expect(FinalTerms.eqlExact(&op.machine.ctx, op.machine.regs[0], FinalTerms.atom(&op.machine.ctx, op.machine.bool_false)));

    // a send via the RETIRED alias is dropped — the mailbox is unchanged.
    const sref2 = try refIn(&sp.machine.ctx, &op.machine.ctx, aref);
    sp.machine.pending = .{ .send_to = .{ .pid = sref2, .msg = hello } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    try std.testing.expectEqual(@as(usize, 1), op.machine.mbox.len()); // STILL 1 — the retired send dropped (Mutant 1/2 target)
}

test "LAW e50-eep76 PRIORITY-ALIAS front-of-mailbox: a message sent through alias([priority]) is received AHEAD of normal messages already queued (EEP-76 model)" {
    // MODEL BOUND (HONEST): pinned OTP-30-rc0 rejects
    // `process_flag(priority_messages,true)` as `badopt` (the feature is not
    // enabled in the rc build), so priority-ordering is NOT oracle-differential-
    // verifiable on the pin. This law verifies the front-of-mailbox SEMANTICS
    // as a model; the surface (`alias([priority])` mints a valid ref) IS oracle-
    // confirmed. Ledger: eep76 flips ABSENT→EQUIV under exactly this bound.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const owner = try vm.spawn(idle, 0, null);
    const sender = try vm.spawn(idle, 0, null);
    const op = vm.procs.items[owner];
    const sp = vm.procs.items[sender];

    // owner mints a NORMAL alias (x3) and a PRIORITY alias (x4 = alias([priority])).
    op.machine.pending = .{ .make_alias = .{ .dst = 3 } };
    try vm.interpret(owner);
    const normal_ref = op.machine.regs[3];
    op.machine.pending = .{ .make_alias = .{ .dst = 4, .priority = true } };
    try vm.interpret(owner);
    const prio_ref = op.machine.regs[4];
    try std.testing.expect(FinalTerms.repIsRef(&op.machine.ctx, prio_ref)); // surface: valid ref

    const a_n1 = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("normal1"));
    const a_p = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("prio"));
    const a_n2 = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("normal2"));

    // 1) normal1 via the NORMAL alias, drain, then FORCE a flush (peek) so
    // normal1 is committed to the inner queue — this is the state EEP-76 has to
    // beat: a priority message must still land AHEAD of a normal message that is
    // ALREADY in the mailbox, not merely ahead of ones still in transit.
    sp.machine.pending = .{ .send_to = .{ .pid = try refIn(&sp.machine.ctx, &op.machine.ctx, normal_ref), .msg = a_n1 } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    _ = try op.machine.mbox.peekAt(0); // flush: normal1 now sits in `inner`
    // 2) prio via the PRIORITY alias, then normal2 via the normal alias.
    sp.machine.pending = .{ .send_to = .{ .pid = try refIn(&sp.machine.ctx, &op.machine.ctx, prio_ref), .msg = a_p } };
    try vm.interpret(sender);
    sp.machine.pending = .{ .send_to = .{ .pid = try refIn(&sp.machine.ctx, &op.machine.ctx, normal_ref), .msg = a_n2 } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);

    // EEP-76: even though normal1 arrived FIRST, the priority message is at the
    // FRONT of the mailbox — received ahead of both normals (Mutant target).
    try std.testing.expectEqual(@as(usize, 3), op.machine.mbox.len());
    const first = (try op.machine.mbox.peekAt(0)).?;
    try std.testing.expect(FinalTerms.eqlExact(&op.machine.ctx, first.payload, FinalTerms.atom(&op.machine.ctx, try atoms.intern("prio"))));
    // and the two normals keep their arrival order behind it.
    const second = (try op.machine.mbox.peekAt(1)).?;
    const third = (try op.machine.mbox.peekAt(2)).?;
    try std.testing.expect(FinalTerms.eqlExact(&op.machine.ctx, second.payload, FinalTerms.atom(&op.machine.ctx, try atoms.intern("normal1"))));
    try std.testing.expect(FinalTerms.eqlExact(&op.machine.ctx, third.payload, FinalTerms.atom(&op.machine.ctx, try atoms.intern("normal2"))));
}

test "LAW e50-realtime REDUCTION-COST + BOUNDED-PREEMPTION: a CPU-bound process granted fuel F yields having consumed EXACTLY F reductions (preemption latency <= F, independent of F); two such processes round-robin FAIR-SHARE (the {R} real-time axis)" {
    // THE {R} (real-time) MEASUREMENT. BEAM's soft-real-time guarantee is
    // reduction-budget preemption: no process monopolizes a scheduler — it is
    // forced to yield after a bounded number of reductions, so scheduling
    // latency for every OTHER runnable process is bounded. This law MEASURES
    // that property in zigvm directly (it is a scheduler MODEL property, not an
    // oracle byte-differential — OTP does not expose per-grant reduction gaps at
    // this granularity; the ledger records {R} as PARTIAL/model-verified).
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    // A CPU-bound process: an infinite TAIL self-call (`cpu_hog() -> cpu_hog()`).
    // R2b: the back-edge is a TAIL jump, so each iteration charges EXACTLY ONE
    // per-call reduction AND ONE retired instruction (they coincide for a
    // single-op tail loop) and NEVER halts/blocks — a pure compute hog. Preemption
    // is bounded on `m.instrs`; because reductions==instrs for this hog, a grant of
    // fuel F consumes exactly F reductions == F instrs (the {R} per-call model made
    // observable on a call-based workload).
    const hog: ia.Program = &.{.{ .jump = .{ .to = 0, .tail = true } }};

    // PROPERTY 1 — BOUNDED PREEMPTION / the reduction COST MODEL: granting fuel F
    // consumes EXACTLY F reductions before the process yields, for every F. The
    // preemption latency the scheduler imposes is thus F reductions — bounded,
    // predictable, and proportional to the granted budget (never a monopoly).
    const p = try vm.spawn(hog, 0, null);
    const mp = &vm.procs.items[p].machine;
    for ([_]u64{ 1, 4, 100, 4_000, 250_000 }) |fuel| {
        const before = mp.reductions;
        try vm.grant(p, fuel);
        // yields having advanced by EXACTLY the granted budget — bounded latency.
        try std.testing.expectEqual(fuel, mp.reductions - before);
    }

    // PROPERTY 2 — FAIR SHARE / no starvation: two CPU-bound hogs granted the
    // same fuel per round-robin slice make EQUAL progress; neither starves. After
    // K equal slices their reduction counts are identical (skew 0 <= fuel).
    const a = try vm.spawn(hog, 0, null);
    const b = try vm.spawn(hog, 0, null);
    const ma = &vm.procs.items[a].machine;
    const mb = &vm.procs.items[b].machine;
    const ra0 = ma.reductions;
    const rb0 = mb.reductions;
    const slice_fuel: u64 = 1_000;
    var round: usize = 0;
    while (round < 8) : (round += 1) {
        try vm.grant(a, slice_fuel);
        try vm.grant(b, slice_fuel);
    }
    // each hog advanced 8*1000 reductions; the skew between the two is 0 (fair).
    try std.testing.expectEqual(@as(u64, 8 * slice_fuel), ma.reductions - ra0);
    try std.testing.expectEqual(@as(u64, 8 * slice_fuel), mb.reductions - rb0);
    const skew = if (ma.reductions - ra0 > mb.reductions - rb0)
        (ma.reductions - ra0) - (mb.reductions - rb0)
    else
        (mb.reductions - rb0) - (ma.reductions - ra0);
    try std.testing.expect(skew <= slice_fuel); // bounded-fairness: no starvation
}

test "LAW gap-r2c-behavioral-parity-wire: with reduction_preempt ON the SCHEDULER grant preempts on m.reductions (a MIXED proc granted F reduction-fuel yields at F reds despite 2F instrs); OFF is byte-identical (R2b instrs); a 0-red hog is cap-bounded (R2c epoch Inc1, DIVERGENCE 607)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // A MIXED loop: a straight-line move (0 red, 1 instr) + a tail-jump back-edge
    // (1 red, 1 instr) ⇒ 1 reduction / 2 instrs per iteration.
    const mixed: ia.Program = &.{
        .{ .move = .{ .src = .{ .imm = 0 }, .dst = 0 } },
        .{ .jump = .{ .to = 0, .tail = true } },
    };
    const F: u64 = 100;

    // (1) reduction_preempt ON: a scheduler grant of F REDUCTION-fuel yields at EXACTLY
    // F reductions, having run 2F instrs — the OTP behavioral parity, now at the
    // SCHEDULER level (not just the raw ia primitive). Kills a mutant that ignores the
    // flag (would yield at F instrs = F/2 reds).
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.reduction_preempt = true;
        const p = try vm.spawn(mixed, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(F, mp.reductions); // yielded on F reductions
        try std.testing.expectEqual(@as(u64, 2) * F, mp.instrs); // 2F instrs (parity)
    }

    // (2) DEFAULT (reduction_preempt OFF): the SAME grant yields on F INSTRS = F/2
    // reductions — the R2b behavior, byte-identical to before this seam.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const p = try vm.spawn(mixed, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(F, mp.instrs); // yielded on F instrs (default)
        try std.testing.expectEqual(F / 2, mp.reductions); // half the reductions
    }

    // (3) SAFETY-CAP (flag ON): a 0-reduction straight-line hog is force-yielded at the
    // instr fail-safe (F * MULT), NEVER hangs — UCA-R2C-1's standing scheduler guard.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.reduction_preempt = true;
        const straightline: ia.Program = &.{.{ .jump = .{ .to = 0, .tail = false } }};
        const p = try vm.spawn(straightline, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(@as(u64, 0), mp.reductions); // never charged a reduction
        try std.testing.expectEqual(F * REDUCTION_PREEMPT_INSTR_CAP_MULT, mp.instrs); // cap-bounded
    }
}

test "LAW gap-r2c-behavioral-parity-native: with BOTH reduction_preempt AND reduction_preempt_native the reduction-preempted grant drives the PRODUCTION JIT — same EXACT yield point as the interpreter path (F reds / 2F instrs) BUT the native hot path is KEPT (the move runs as machine code); the native flag ALONE is a no-op (R2c epoch Inc2, DIVERGENCE 608)" {
    const jit_codegen = @import("jit_codegen.zig");
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // Same MIXED loop as Inc1: a native-COVERABLE straight-line move (0 red, 1 instr,
    // `buildMove`) + a tail-jump back-edge (1 red, 1 instr, an uncovered fallback op)
    // ⇒ 1 reduction / 2 instrs per iteration, and a genuine native/fallback split.
    const mixed: ia.Program = &.{
        .{ .move = .{ .src = .{ .imm = 0 }, .dst = 0 } },
        .{ .jump = .{ .to = 0, .tail = true } },
    };
    const F: u64 = 100;

    // (1) EXACTNESS via the JIT: BOTH flags ON ⇒ the reduction-preempted grant runs
    // `dispatch.runProductionReds`, which yields at EXACTLY F reductions / 2F instrs —
    // byte-identical yield point to the interpreter path (Inc1), proving the {0,1}-
    // reductionCost theorem holds through the native engine (no overshoot, exact tail).
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.reduction_preempt = true;
        vm.reduction_preempt_native = true;
        const p = try vm.spawn(mixed, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(F, mp.reductions); // EXACT — no overshoot past the budget
        try std.testing.expectEqual(@as(u64, 2) * F, mp.instrs); // 2F instrs (behavioral parity)
        // ROUTING PROOF: on a native host the grant actually drove `runProductionReds`
        // (which compiles into `prod_cache`), NOT the interpreter (`ia.runReductionPreempt`
        // never touches the cache). This is the observable that distinguishes Inc2 from
        // Inc1 — the yield point is identical by design, so without it the routing would
        // be untestable. Kills a mutant that routes the native flag back to the interpreter.
        if (jit_codegen.native_supported and dispatch.use_native_codegen and dispatch.use_production_native) {
            try std.testing.expect(vm.prod_cache.map.count() > 0);
        }
    }

    // (2) THE JIT IS KEPT (non-vacuous): the same program, run through the counted
    // native engine, executes the F `move` ops as MACHINE CODE (native_reds == F) while
    // the F tail-jumps are the threaded fallback (fallback_reds == F) — on a native host.
    // On a non-native host the whole thing is fallback (coverage honestly 0), and Inc2
    // still preempts exactly (part 1) via `runProduction`'s transparent interpreter
    // deferral. Kills the "Inc2 secretly falls back to the interpreter" doubt.
    if (jit_codegen.native_supported and dispatch.use_native_codegen and dispatch.use_production_native) {
        var nbp = try dispatch.compileNativeBlock(gpa, mixed);
        defer nbp.deinit(gpa);
        var mm = try ia.Machine.init(gpa, &atoms);
        defer mm.deinit();
        const split = try dispatch.runNativeBlockCounted(&mm, &nbp, 2 * F);
        // NON-VACUOUS: real native execution happened (machine code ran), and every
        // one of the 2F retired instrs is accounted native-or-fallback. The exact
        // split is a codegen detail (here the block JIT covers BOTH the move AND the
        // tail-jump ⇒ native_reds == 2F, fallback_reds == 0); the LAW pins the
        // invariant "the JIT is KEPT", not the coverage ratio.
        try std.testing.expect(split.native_reds > 0); // machine code genuinely ran
        try std.testing.expectEqual(2 * F, split.native_reds + split.fallback_reds);
    }

    // (3) THE NATIVE FLAG ALONE IS A NO-OP: `reduction_preempt_native` without
    // `reduction_preempt` leaves the R2b instr-preempt grant untouched — byte-identical
    // default (yields on F instrs = F/2 reds). Guards against the flag leaking behavior.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.reduction_preempt_native = true; // but reduction_preempt stays false
        const p = try vm.spawn(mixed, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(F, mp.instrs); // R2b instr-preempt (unchanged)
        try std.testing.expectEqual(F / 2, mp.reductions);
    }

    // (4) SAFETY-CAP through the JIT path: a 0-reduction straight-line hog under BOTH
    // flags is force-yielded at the instr fail-safe (UCA-R2C-1) — the native driver
    // carries the SAME cap as the interpreter, never hangs.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.reduction_preempt = true;
        vm.reduction_preempt_native = true;
        const straightline: ia.Program = &.{.{ .jump = .{ .to = 0, .tail = false } }};
        const p = try vm.spawn(straightline, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(@as(u64, 0), mp.reductions); // 0 reds forever
        try std.testing.expectEqual(F * REDUCTION_PREEMPT_INSTR_CAP_MULT, mp.instrs); // cap-bounded
    }
}

test "LAW gap-r2c-behavioral-parity-corpus-blocker: the R2c epoch CLOSE — a 0-REDUCTION program (the synthetic straight-line loops pervasive in the verification corpus) runs MULT× longer per grant under a hypothetical GLOBAL flip to reduction-preemption (the empirical gate-timeout pathology, CAST-24); the instr-preempt DEFAULT bounds it at exactly F. The mechanically-proven reason the epoch closes mechanism-complete + OPT-IN, default UNFLIPPED (R2c epoch Inc3, DIVERGENCE 611)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // A 0-REDUCTION straight-line loop — a `jump{tail=false}` self-loop charges no
    // per-call reduction (reductionCost 0: neither a call nor a tail-jump). It stands
    // for the synthetic 0-reduction programs the verification corpus is full of (tight
    // move/jump loops, spin fixtures). real erlc NEVER emits such a loop — every BEAM
    // loop back-edge is a tail-call charging 1 reduction — so this pathology is a
    // VERIFICATION-MODEL artifact, not a production concern.
    const spin: ia.Program = &.{.{ .jump = .{ .to = 0, .tail = false } }};
    const F: u64 = 100;

    // (A) DEFAULT (instr-preempt): the spin yields at EXACTLY F instrs — cheap, the
    // correct verification-model bound. This is why the gate stays fast UNFLIPPED.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const p = try vm.spawn(spin, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(F, mp.instrs); // instr-preempt: bounded at F
        try std.testing.expectEqual(@as(u64, 0), mp.reductions); // charges 0 reductions
    }

    // (B) HYPOTHETICAL GLOBAL FLIP (reduction_preempt=true): the SAME spin charges 0
    // reductions, so it runs to the instr safety-cap = F*MULT instrs — MULT× the work.
    // Multiplied across the corpus's many 0-reduction procs, THIS is the empirical gate
    // TIMEOUT that defeats a global default-flip (CAST-24). The mechanism is exact +
    // proven (Inc0-2); the DEFAULT correctly stays instr-preempt.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.reduction_preempt = true;
        const p = try vm.spawn(spin, 0, null);
        const mp = &vm.procs.items[p].machine;
        try vm.grant(p, F);
        try std.testing.expectEqual(@as(u64, 0), mp.reductions); // still 0 reds (nothing to preempt on)
        try std.testing.expectEqual(F * REDUCTION_PREEMPT_INSTR_CAP_MULT, mp.instrs); // MULT× the work
        // the RATIO is the flip's cost multiplier — the checked flip-blocker invariant.
        try std.testing.expectEqual(REDUCTION_PREEMPT_INSTR_CAP_MULT, mp.instrs / F);
    }
}

test "LAW e50-bump PREEMPTION-LATENCY: a bump_reductions(N) during a fuel-F slice brings preemption FORWARD by exactly N (remaining_fuel' = remaining_fuel - N, clamped) — differential vs a pure reduction-accounting oracle (the {R} axis)" {
    // gap-reduction-cost-model. SEMANTIC DOMAIN: a scheduler grant of fuel F is a
    // reduction BUDGET. Every ordinary instruction charges 1 reduction; a
    // `bump_reductions(N)` call charges 1 (the call) + N (the bump) in one
    // indivisible step. The process is preempted at the first step whose
    // cumulative charge reaches F. So a bump of N inside the slice STEALS N
    // reductions from useful work: the work-budget after the mandatory call+bump
    // is F-1-N (clamped at 0) — preemption is brought forward by exactly N. This
    // is a scheduler MODEL / trace-differential property, NOT an OTP byte-
    // differential (erts does not expose per-grant reduction gaps at this
    // granularity; the {R} ledger records it as model-verified). HONEST BOUND: we
    // prove the engine's grant honors the pure accounting ORACLE below; we do not
    // claim OTP emits the same intermediate gaps.
    const gpa = std.testing.allocator;

    // ORACLE (initial encoding): a pure reduction-accounting model of the program
    // `[bump(N); (add,jump)*]`. Step 0 charges 1+N; every later step charges 1;
    // the pc==1 `add` steps are the observable "useful work". `run` executes
    // steps until the cumulative charge reaches the fuel budget (a step is
    // indivisible — the last step may overshoot F, the CLAMP case).
    const Oracle = struct {
        fn run(fuel: u64, bumpN: u64) struct { consumed: u64, work: u64 } {
            var consumed: u64 = 0;
            var work: u64 = 0;
            var i: u64 = 0;
            while (consumed < fuel) : (i += 1) {
                if (i == 0) {
                    consumed += 1 + bumpN; // the call_ext_bif(bump) step
                } else {
                    consumed += 1;
                    if ((i - 1) % 2 == 0) work += 1; // pc==1 `add` = useful work
                }
            }
            return .{ .consumed = consumed, .work = work };
        }
    };

    // FINAL (engine path): the compiled program. x0 carries N for the bump; x1 is
    // the useful-work counter incremented once per loop iteration.
    const prog: ia.Program = &.{
        .{ .call_ext_bif = .{ .func = &procsys.bump_reductions_1, .arity = 1 } },
        .{ .add = .{ .a = .{ .x = 1 }, .b = .{ .imm = 1 }, .dst = 1 } },
        .{ .jump = .{ .to = 1 } },
    };

    // Seeded, bounded sweep over (fuel, bump) — echo the pair on failure.
    const fuels = [_]u64{ 1, 2, 3, 5, 10, 33, 100, 1000 };
    const bumps = [_]u64{ 0, 1, 3, 50, 999 };
    for (fuels) |fuel| {
        for (bumps) |bumpN| {
            errdefer std.debug.print("FAIL seed (fuel={d}, bumpN={d})\n", .{ fuel, bumpN });
            var atoms = AtomTable.init(gpa);
            defer atoms.deinit();
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const p = try vm.spawn(prog, 0, null);
            const m = &vm.procs.items[p].machine;
            m.regs[0] = FinalTerms.int(&m.ctx, @intCast(bumpN)); // N for bump_reductions
            m.regs[1] = FinalTerms.int(&m.ctx, 0); // work counter starts at 0
            // R2b: preemption is bounded on `m.instrs`; `bump_reductions(N)` bumps
            // BOTH counters by N, so the instr-budget consumption matches the
            // oracle EXACTLY (step 0 = call_ext_bif 1 instr + bump N = 1+N instrs;
            // each add/jump = 1 instr). The latency-forward-by-N property is thus
            // observed on the instr budget (byte-identical to the pre-R2b model).
            const r0 = m.instrs;
            try vm.grant(p, fuel);

            const exp = Oracle.run(fuel, bumpN);
            // DIFFERENTIAL: the engine consumes exactly the oracle's budget...
            try std.testing.expectEqual(exp.consumed, m.instrs - r0);
            // ...and accomplishes exactly the oracle's useful work.
            const x1: u64 = @intCast(FinalTerms.smallValOf(m.regs[1]));
            try std.testing.expectEqual(exp.work, x1);

            if (fuel >= 1 + bumpN) {
                // THE LATENCY LAW: the whole bump fits, so the budget is honored
                // EXACTLY (== fuel) and the budget left for non-bump work is
                // fuel-1-N (remaining_fuel' = remaining_fuel - N).
                try std.testing.expectEqual(fuel, m.instrs - r0);
                try std.testing.expectEqual(fuel - 1 - bumpN, (m.instrs - r0) - (1 + bumpN));
                // preempted (yielded), never halted — a CPU-bound loop.
                try std.testing.expect(vm.procs.items[p].alive and m.status == .running);
            } else {
                // CLAMP: one indivisible bump step exceeds the budget → overshoot
                // by exactly the bump, zero useful work this slice (remaining' = 0).
                try std.testing.expectEqual(1 + bumpN, m.instrs - r0);
                try std.testing.expectEqual(@as(u64, 0), x1);
            }
        }
    }
}

/// gap-reduction-cost-model R3 (the {R} scheduling-latency measure): a bucketed
/// histogram of per-grant scheduling latency — how long (in reductions consumed by
/// OTHER processes) a runnable process waits before its next grant. Fixed-width
/// buckets aligned to a fuel/CONTEXT_REDS quantum, with a final OVERFLOW bucket, so
/// every possible sample lands in exactly one bucket. This is the reusable runtime
/// structure the scheduler folds real grants into (and `--latency-oracle` compares
/// against OTP-30's distribution) — promoting the e50-latency law's test-local
/// computation to a first-class measure. Soundness is a CONSERVATION law
/// (Σ bucket counts == #records) plus monotone percentiles.
pub const LatencyHistogram = struct {
    width: u64,
    buckets: [N_BUCKETS]u32 = [_]u32{0} ** N_BUCKETS,
    n: u32 = 0,

    pub const N_BUCKETS: usize = 16; // buckets 0..14 = [b*width, (b+1)*width); 15 = overflow

    pub fn init(width: u64) LatencyHistogram {
        return .{ .width = if (width == 0) 1 else width };
    }

    /// Fold one latency sample into bucket `min(latency/width, N_BUCKETS-1)` — the
    /// `@min` clamp routes any large latency into the overflow bucket (total).
    pub fn record(self: *LatencyHistogram, latency: u64) void {
        const b: usize = @intCast(@min(latency / self.width, @as(u64, N_BUCKETS - 1)));
        self.buckets[b] += 1;
        self.n += 1;
    }

    /// CONSERVATION: Σ bucket counts == #records (no sample lost or duplicated).
    pub fn conserves(self: *const LatencyHistogram) bool {
        var s: u32 = 0;
        for (self.buckets) |c| s += c;
        return s == self.n;
    }

    /// The lower bound (in reductions) of the bucket at the `p`-th percentile
    /// (0..100), non-decreasing in `p`. Empty → 0. `ceil(n*p/100)` picks the bucket
    /// whose cumulative count first reaches the p-th sample.
    pub fn percentile(self: *const LatencyHistogram, p: u8) u64 {
        if (self.n == 0) return 0;
        const target: u64 = (@as(u64, self.n) * @min(p, 100) + 99) / 100;
        var cum: u64 = 0;
        for (self.buckets, 0..) |c, b| {
            cum += c;
            if (cum >= target) return @as(u64, @intCast(b)) * self.width;
        }
        return @as(u64, N_BUCKETS - 1) * self.width;
    }

    /// gap-reduction-latency-percentiles (DIVERGENCE 605): the TAIL-latency summary a
    /// soft-real-time SLO reads — the median and the p90/p99 tail (not just the max).
    /// A pure derived view (mutates nothing); percentiles are monotone p50≤p90≤p99≤p100.
    pub const Summary = struct { n: u32, p50: u64, p90: u64, p99: u64, p100: u64 };
    pub fn summary(self: *const LatencyHistogram) Summary {
        return .{
            .n = self.n,
            .p50 = self.percentile(50),
            .p90 = self.percentile(90),
            .p99 = self.percentile(99),
            .p100 = self.percentile(100),
        };
    }
};

test "LAW e50-t3 LATENCY-HISTOGRAM FAITHFUL-FOLD: conservation + correct bucketing + monotone percentiles ({R} scheduling-latency measure)" {
    const F: u64 = 1000;
    const W: usize = 5;
    var h = LatencyHistogram.init(F);
    // Record the e50 staircase latencies {0, F, 2F, 3F, 4F}: sample j*F → bucket j.
    for (0..W) |j| h.record(@as(u64, j) * F);
    for (0..W) |j| try std.testing.expectEqual(@as(u32, 1), h.buckets[j]); // correct bucketing
    try std.testing.expect(h.conserves()); // Σ buckets == n
    try std.testing.expectEqual(@as(u32, W), h.n);
    // Percentiles: monotone non-decreasing, with min/max bounds.
    var prev: u64 = 0;
    var p: u8 = 0;
    while (p <= 100) : (p += 10) {
        const v = h.percentile(p);
        try std.testing.expect(v >= prev);
        prev = v;
    }
    try std.testing.expectEqual(@as(u64, 0), h.percentile(0));
    try std.testing.expectEqual((@as(u64, W) - 1) * F, h.percentile(100)); // p100 = max sample bucket (4F)
    // Overflow: a huge latency lands in the LAST bucket, still conserved (the clamp).
    h.record(1_000_000 * F);
    try std.testing.expectEqual(@as(u32, 1), h.buckets[LatencyHistogram.N_BUCKETS - 1]);
    try std.testing.expect(h.conserves());
}

test "LAW gap-reduction-latency-percentiles: the tail-latency summary (p50/p90/p99/p100) on a SKEWED distribution — the median is low but the p99 tail is high (DIVERGENCE 605)" {
    // A soft-real-time SLO cares about the TAIL, not the max. Build a SKEWED
    // distribution: 90 fast grants (bucket 0), 9 slow (bucket 5), 1 pathological
    // (bucket 14) — the shape a bursty scheduler produces. The summary must SEPARATE
    // the low median from the high tail (a uniform staircase can't show this).
    const F: u64 = 100;
    var h = LatencyHistogram.init(F);
    var k: usize = 0;
    while (k < 90) : (k += 1) h.record(0); // bucket 0 (fast)
    k = 0;
    while (k < 9) : (k += 1) h.record(5 * F); // bucket 5 (slow)
    h.record(14 * F); // bucket 14 (pathological outlier)
    try std.testing.expectEqual(@as(u32, 100), h.n);
    try std.testing.expect(h.conserves());

    const s = h.summary();
    try std.testing.expectEqual(@as(u32, 100), s.n);
    // p50 sits in the fast bucket (0); p99 in the slow bucket (5*F); p100 the outlier (14*F).
    try std.testing.expectEqual(@as(u64, 0), s.p50); // median is FAST
    try std.testing.expectEqual(@as(u64, 5 * F), s.p99); // the TAIL is SLOW (the SLO signal)
    try std.testing.expectEqual(@as(u64, 14 * F), s.p100); // the worst case
    // the KEY separation: median ≪ p99 (a real distribution, not a degenerate point).
    try std.testing.expect(s.p50 < s.p99);
    try std.testing.expect(s.p99 <= s.p100);
    // p90 is still in the fast bucket (90 fast of 100) — the 90th sample is the last fast one.
    try std.testing.expectEqual(@as(u64, 0), s.p90);
}

test "LAW e50-latency SCHEDULING-LATENCY: round-robin first-schedule latency is bounded by (W-1)*fuel; the latency histogram conserves its samples (a well-defined {R} scheduling-latency measure)" {
    // gap-reduction-cost-model. SEMANTIC DOMAIN: reduction-budget preemption makes
    // scheduling latency WELL-DEFINED — the time (in reductions of OTHER processes)
    // a runnable process waits before its first grant. For W CPU-bound hogs served
    // round-robin at fuel F, process j (0-indexed) waits behind j peers each
    // spending F, so its first-schedule latency is exactly j*F, bounded above by
    // (W-1)*F. We MEASURE these latencies from real grants and fold them into a
    // histogram; the measure's soundness is a conservation law (every sample lands
    // in exactly one bucket) plus the latency bound.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    // R2b: a TAIL self-call hog — each iteration charges 1 per-call reduction ==
    // 1 instr, so a grant of F consumes F reductions and the latency staircase is
    // measured in the OTP per-call currency.
    const hog: ia.Program = &.{.{ .jump = .{ .to = 0, .tail = true } }};

    const W: usize = 5;
    const F: u64 = 1000;
    var pids: [W]Pid = undefined;
    for (&pids) |*pp| pp.* = try vm.spawn(hog, 0, null);

    // One scheduling round: grant each hog once, in order, MEASURING the running
    // total of reductions consumed before each hog's FIRST grant (= its latency).
    var latency: [W]u64 = undefined;
    var running_total: u64 = 0;
    for (pids, 0..) |pid, j| {
        latency[j] = running_total; // reductions others burned before j runs
        const m = &vm.procs.items[pid].machine;
        const r0 = m.reductions;
        try vm.grant(pid, F);
        running_total += m.reductions - r0;
    }

    // LATENCY BOUND + exact staircase, folded into the reusable LatencyHistogram
    // (R3): the e50-latency law now rides on the SAME first-class measure the
    // scheduler maintains — the test-local histogram is gone.
    var h = LatencyHistogram.init(F);
    for (latency, 0..) |lat, j| {
        try std.testing.expectEqual(@as(u64, j) * F, lat); // exact first-schedule latency
        try std.testing.expect(lat <= (@as(u64, W) - 1) * F); // BOUNDED by (W-1)*fuel
        h.record(lat);
    }
    // CONSERVATION: Σ bucket counts == #records == W (no sample lost or duplicated).
    try std.testing.expect(h.conserves());
    try std.testing.expectEqual(@as(u32, W), h.n);
    // FAIR STAIRCASE: exactly one process per latency bucket (no starvation skew).
    for (0..W) |b| try std.testing.expectEqual(@as(u32, 1), h.buckets[b]);
}

test "LAW e50-t4 LIVE-LATENCY: a histogram attached to the LIVE round-robin Scheduler.drive records the e50 staircase then the (W-1)*fuel steady-state; conserves #grants ({R} live scheduling-latency instrumentation)" {
    // gap-reduction-cost-model R4. SEMANTIC DOMAIN: the e50-latency law measured
    // the staircase from a hand-rolled one-round grant loop; R4 promotes that to
    // the LIVE scheduler — a `LatencyHistogram` ATTACHED to `Vm.latency_histogram`
    // is folded by `grantOnly` on every real grant of `Scheduler.drive`. Over R
    // round-robin rounds of W CPU-bound tail hogs at fuel F: ROUND 1 is the
    // first-schedule staircase (proc j waits j*F ⇒ bucket j), and every LATER
    // grant waits behind exactly the W-1 OTHER hogs ⇒ steady-state latency
    // (W-1)*F ⇒ bucket W-1. The measure's soundness is CONSERVATION (Σ buckets ==
    // n == #grants) + the (W-1)*F BOUND (nothing lands above bucket W-1).
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const hog: ia.Program = &.{.{ .jump = .{ .to = 0, .tail = true } }};

    const W: usize = 5;
    const F: u64 = 1000;
    const rounds: usize = 4;
    for (0..W) |_| _ = try vm.spawn(hog, 0, null);

    // Attach the histogram to the LIVE scheduler (opt-in) and drive W*rounds
    // grants — strict round-robin, so grant order is 0,1,..,W-1,0,1,.. repeated.
    var h = LatencyHistogram.init(F);
    vm.latency_histogram = &h;
    const sched: Scheduler = .round_robin;
    try sched.drive(&vm, F, W * rounds);
    vm.latency_histogram = null;

    // CONSERVATION: every grant recorded exactly one sample; tail hogs never halt,
    // so each of the W*rounds slices granted once ⇒ n == W*rounds.
    try std.testing.expect(h.conserves());
    try std.testing.expectEqual(@as(u32, @intCast(W * rounds)), h.n);
    // (W-1)*F BOUND: no sample exceeds (W-1)*F, so NOTHING lands above bucket W-1
    // (buckets W..N_BUCKETS-1, incl. the overflow bucket, are empty). Mutant (a)
    // [latency includes self] and mutant (b) [last_grant_total never advances]
    // both grow latency past this bound ⇒ these buckets fill ⇒ RED.
    for (W..LatencyHistogram.N_BUCKETS) |b| try std.testing.expectEqual(@as(u32, 0), h.buckets[b]);
    // ROUND-1 STAIRCASE: buckets 0..W-2 each hold exactly ONE sample (proc j's
    // first-schedule latency j*F, seen once). Buckets 0..W-1 are the staircase.
    for (0..W - 1) |b| try std.testing.expectEqual(@as(u32, 1), h.buckets[b]);
    // STEADY STATE: every remaining sample is (W-1)*F ⇒ bucket W-1. That bucket
    // holds n minus the (W-1) staircase samples in buckets 0..W-2.
    try std.testing.expectEqual(@as(u32, @intCast(W * rounds - (W - 1))), h.buckets[W - 1]);
    // The measured steady-state percentile IS the (W-1)*F bound (the {R} signal
    // `--latency-oracle` compares against OTP): median and p100 both sit there.
    try std.testing.expectEqual((@as(u64, W) - 1) * F, h.percentile(100));
    try std.testing.expectEqual((@as(u64, W) - 1) * F, h.percentile(50));
}

test "E8.2h EXIT-SIGNAL aliases route only for active local refs; retired and foreign refs drop" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const owner = try vm.spawn(idle, 0, null);
    const sender = try vm.spawn(idle, 0, null);
    const op = vm.procs.items[owner];
    const sp = vm.procs.items[sender];
    op.machine.trap_exit = true;

    op.machine.pending = .{ .make_alias = .{ .dst = 3 } };
    try vm.interpret(owner);
    const aref = op.machine.regs[3];
    const boom = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("boom"));

    const sref = try refIn(&sp.machine.ctx, &op.machine.ctx, aref);
    sp.machine.pending = .{ .exit_to = .{ .pid = sref, .reason = boom } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    try std.testing.expect(op.alive);
    try std.testing.expectEqual(@as(usize, 1), op.machine.mbox.len()); // active alias delivered an EXIT message

    op.machine.pending = .{ .unalias_ref = .{ .ref = aref } };
    try vm.interpret(owner);
    const retired = try refIn(&sp.machine.ctx, &op.machine.ctx, aref);
    sp.machine.pending = .{ .exit_to = .{ .pid = retired, .reason = boom } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    try std.testing.expectEqual(@as(usize, 1), op.machine.mbox.len()); // retired local alias dropped

    const foreign_node = try atoms.intern("other@host");
    const foreign_same_words = try FinalTerms.refExt(&sp.machine.ctx, FinalTerms.refWords(&op.machine.ctx, aref), foreign_node, 3);
    sp.machine.pending = .{ .exit_to = .{ .pid = foreign_same_words, .reason = boom } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    try std.testing.expectEqual(@as(usize, 1), op.machine.mbox.len()); // foreign ref never aliases the local alias table
}

test "E5.8 REGISTERED-NAME SEND DELIVERY: `Name ! Msg` routes to the registered pid; an unregistered name drops (DIVERGENCE entry 50(a))" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const owner = try vm.spawn(idle, 0, null);
    const sender = try vm.spawn(idle, 0, null);
    const op = vm.procs.items[owner];
    const sp = vm.procs.items[sender];

    // register the name `srv` -> owner (the bijection resolveSendTarget reads).
    const nm = try atoms.intern("srv");
    try vm.registry.register(nm, owner, true);

    // sender: `srv ! hello` — the destination is an ATOM (registered name), not a
    // pid. The atom lives in the SENDER's heap; resolveSendTarget maps it to the
    // registered owner pid.
    const name_term = FinalTerms.atom(&sp.machine.ctx, nm);
    const hello = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("hello"));
    sp.machine.pending = .{ .send_to = .{ .pid = name_term, .msg = hello } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    try std.testing.expectEqual(@as(usize, 1), op.machine.mbox.len()); // DELIVERED to the registered pid (Mutant 1 target)

    // an UNREGISTERED name drops (the dead/absent-target model) — no crash.
    const bogus = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("nosuchsrv"));
    sp.machine.pending = .{ .send_to = .{ .pid = bogus, .msg = hello } };
    try vm.interpret(sender);
    try vm.drainSignals(owner);
    try std.testing.expectEqual(@as(usize, 1), op.machine.mbox.len()); // STILL 1 — the unregistered-name send dropped
}

test "E6.4 SUSPEND/RESUME COUNTING MONOID + scheduler-skip + is_system_process (DIVERGENCE entry 112)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const caller = try vm.spawn(idle, 0, null);
    const target = try vm.spawn(idle, 0, null);
    const cm = &vm.procs.items[caller].machine;
    const tpid = try FinalTerms.pid(&cm.ctx, target, 0);

    const isTrue = struct {
        fn f(m: *ia.Machine, x: FinalTerms.Term) bool {
            return FinalTerms.repIsAtom(x) and FinalTerms.atomIdxOf(x) == m.bool_true;
        }
    }.f;
    const isBadarg = struct {
        fn f(m: *ia.Machine, x: FinalTerms.Term) bool {
            return FinalTerms.repIsAtom(x) and std.mem.eql(u8, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(x)), "badarg");
        }
    }.f;

    // a fresh target is not suspended → schedulable (the scheduler grants it).
    try std.testing.expectEqual(@as(u32, 0), vm.suspend_a.items[target].load(.monotonic));
    try std.testing.expect(schedulable(&vm, target));

    // MONOID unit + nesting: suspend twice stacks the count to 2 (both `true`),
    // and a count > 0 makes the process NOT schedulable (the scheduler-skip law).
    try std.testing.expect(isTrue(cm, vm.doSuspend(cm, tpid)));
    try std.testing.expect(isTrue(cm, vm.doSuspend(cm, tpid)));
    try std.testing.expectEqual(@as(u32, 2), vm.suspend_a.items[target].load(.monotonic));
    try std.testing.expect(!schedulable(&vm, target));

    // one resume unwinds ONE suspend (count 1) — STILL not schedulable (the
    // monoid: nested suspends need MATCHING resumes; one resume is not enough).
    try std.testing.expect(isTrue(cm, vm.doResume(cm, tpid)));
    try std.testing.expectEqual(@as(u32, 1), vm.suspend_a.items[target].load(.monotonic));
    try std.testing.expect(!schedulable(&vm, target));

    // the matching second resume balances the pair (count 0) → schedulable again.
    try std.testing.expect(isTrue(cm, vm.doResume(cm, tpid)));
    try std.testing.expectEqual(@as(u32, 0), vm.suspend_a.items[target].load(.monotonic));
    try std.testing.expect(schedulable(&vm, target));

    // BALANCE GUARD (Mutant 1's target): a resume on a non-suspended process is
    // `badarg` and NEVER drives the count below zero (the monoid has no inverse
    // past the unit — resume_process' host contract).
    try std.testing.expect(isBadarg(cm, vm.doResume(cm, tpid)));
    try std.testing.expectEqual(@as(u32, 0), vm.suspend_a.items[target].load(.monotonic));

    // is_system_process totality: a normal process → false; the `system` flag → true.
    const isFalse = struct {
        fn f(m: *ia.Machine, x: FinalTerms.Term) bool {
            return FinalTerms.repIsAtom(x) and FinalTerms.atomIdxOf(x) == m.bool_false;
        }
    }.f;
    try std.testing.expect(isFalse(cm, vm.doIsSystemProcess(cm, tpid)));
    vm.procs.items[target].system = true;
    try std.testing.expect(isTrue(cm, vm.doIsSystemProcess(cm, tpid)));

    // absent-pid totality: suspend/resume/is_system on a dead pid → badarg.
    const dead = try FinalTerms.pid(&cm.ctx, 999, 0);
    try std.testing.expect(isBadarg(cm, vm.doSuspend(cm, dead)));
    try std.testing.expect(isBadarg(cm, vm.doResume(cm, dead)));
    try std.testing.expect(isBadarg(cm, vm.doIsSystemProcess(cm, dead)));
}

test "E5.8 SPAWN_MONITOR: a [monitor] spawn returns {Pid,Ref} and installs a monitor whose child-exit delivers a 'DOWN' (DIVERGENCE entry 50(c))" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const parent = try vm.spawn(idle, 0, null);
    const pp = vm.procs.items[parent];

    // spawn_monitor of an UNRESOLVABLE MFA: the child spawns, the monitor is
    // installed, then the child exits `undef` — the monitor's 'DOWN' fires.
    const bogus_m = FinalTerms.atom(&pp.machine.ctx, try atoms.intern("nomod"));
    const bogus_f = FinalTerms.atom(&pp.machine.ctx, try atoms.intern("nofun"));
    pp.machine.pending = .{ .spawn_mfa = .{
        .module = bogus_m,
        .func = bogus_f,
        .args = FinalTerms.nil(&pp.machine.ctx),
        .link = false,
        .monitor = true,
    } };
    try vm.interpret(parent);

    // x0 = {Pid, Ref} (Mutant 2 target: a bare pid fails this shape).
    const res = pp.machine.regs[0];
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&pp.machine.ctx, res));
    try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&pp.machine.ctx, res));
    try std.testing.expect(FinalTerms.repIsPid(&pp.machine.ctx, FinalTerms.tupleElem(&pp.machine.ctx, res, 0)));
    try std.testing.expect(FinalTerms.repIsRef(&pp.machine.ctx, FinalTerms.tupleElem(&pp.machine.ctx, res, 1)));

    // the child's `undef` exit delivered a 5-tuple 'DOWN' to the parent.
    try vm.drainSignals(parent);
    var qbuf: [8]mba.Msg(FinalTerms) = undefined;
    const q = pp.machine.mbox.toSeq(&qbuf);
    try std.testing.expectEqual(@as(usize, 1), q.len);
    const down = q[0].payload;
    try std.testing.expectEqual(FinalTerms.Kind.tuple, FinalTerms.kindOf(&pp.machine.ctx, down));
    try std.testing.expectEqual(@as(usize, 5), FinalTerms.tupleArity(&pp.machine.ctx, down));
    const dtag = FinalTerms.tupleElem(&pp.machine.ctx, down, 0);
    try std.testing.expect(FinalTerms.repIsAtom(dtag) and FinalTerms.atomIdxOf(dtag) == vm.a_down);
    // the 'DOWN' ref matches the ref returned in the {Pid,Ref} result.
    try std.testing.expect(FinalTerms.eqlExact(&pp.machine.ctx, FinalTerms.tupleElem(&pp.machine.ctx, down, 1), FinalTerms.tupleElem(&pp.machine.ctx, res, 1)));
}

test "E5.5 is_process_alive/2 ASYNC REPLY: {Ref, true} for a live pid / {Ref, false} for a dead one, delivered to the caller's mailbox" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    const caller = try vm.spawn(idle, 0, null);
    const target = try vm.spawn(idle, 0, null);
    const cp = vm.procs.items[caller];

    // caller asks: is `target` alive? (async form; ref carried by the caller)
    const ref = try FinalTerms.ref(&cp.machine.ctx, Vm.refWordsForKey(777));
    const target_term = try FinalTerms.pid(&cp.machine.ctx, target, 0);
    cp.machine.pending = .{ .is_alive_request = .{ .pid = target_term, .ref = ref } };
    try vm.interpret(caller);
    try std.testing.expect(cp.machine.mbox.len() == 1); // the {Ref,true} reply is queued
    var buf: [4]mba.Msg(FinalTerms) = undefined;
    const q = cp.machine.mbox.toSeq(&buf);
    try std.testing.expect(FinalTerms.tupleArity(&cp.machine.ctx, q[0].payload) == 2);
    const res = FinalTerms.tupleElem(&cp.machine.ctx, q[0].payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&cp.machine.ctx, res, FinalTerms.atom(&cp.machine.ctx, cp.machine.bool_true)));

    // now kill the target and ask again: the reply flips to {Ref, false}.
    try vm.terminate(target, FinalTerms.atom(&vm.procs.items[target].machine.ctx, atoms.intern("normal") catch unreachable));
    const ref2 = try FinalTerms.ref(&cp.machine.ctx, Vm.refWordsForKey(778));
    const target_term2 = try FinalTerms.pid(&cp.machine.ctx, target, 0);
    cp.machine.pending = .{ .is_alive_request = .{ .pid = target_term2, .ref = ref2 } };
    try vm.interpret(caller);
    const q2 = cp.machine.mbox.toSeq(&buf);
    const last = q2[q2.len - 1];
    const res2 = FinalTerms.tupleElem(&cp.machine.ctx, last.payload, 1);
    try std.testing.expect(FinalTerms.eqlExact(&cp.machine.ctx, res2, FinalTerms.atom(&cp.machine.ctx, cp.machine.bool_false)));
}

test "E5.5 MONITOR-ALIAS DOWN-RETIREMENT: a {alias,demonitor} monitor's alias retires on 'DOWN'; {alias,explicit_unalias} survives it" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{
        .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
        .{ .jump = .{ .to = 0 } },
    };
    // Case A (retire): watcher monitors a target with the default (retire) alias.
    const watcher = try vm.spawn(idle, 0, null);
    const target = try vm.spawn(idle, 0, null);
    const sender = try vm.spawn(idle, 0, null);
    const wp = vm.procs.items[watcher];
    const sp = vm.procs.items[sender];
    const t_term = try FinalTerms.pid(&wp.machine.ctx, target, 0);
    wp.machine.pending = .{ .monitor_to = .{ .pid = t_term, .dst = 4, .alias = .retire } };
    try vm.interpret(watcher);
    const aref = wp.machine.regs[4];

    // the alias is live: a send via it lands in the watcher's mailbox.
    const ping = FinalTerms.atom(&sp.machine.ctx, try atoms.intern("ping"));
    sp.machine.pending = .{ .send_to = .{ .pid = try refIn(&sp.machine.ctx, &wp.machine.ctx, aref), .msg = ping } };
    try vm.interpret(sender);
    try vm.drainSignals(watcher);
    try std.testing.expectEqual(@as(usize, 1), wp.machine.mbox.len());

    // target dies → 'DOWN' delivered to the watcher AND the alias auto-retires.
    try vm.terminate(target, FinalTerms.atom(&vm.procs.items[target].machine.ctx, atoms.intern("normal") catch unreachable));
    try vm.drainSignals(watcher);
    try std.testing.expectEqual(@as(usize, 2), wp.machine.mbox.len()); // ping + 'DOWN'

    // a further send via the (now retired) alias is dropped.
    sp.machine.pending = .{ .send_to = .{ .pid = try refIn(&sp.machine.ctx, &wp.machine.ctx, aref), .msg = ping } };
    try vm.interpret(sender);
    try vm.drainSignals(watcher);
    try std.testing.expectEqual(@as(usize, 2), wp.machine.mbox.len()); // STILL 2 — retired

    // Case B (explicit_unalias): the alias SURVIVES the 'DOWN'.
    const watcher2 = try vm.spawn(idle, 0, null);
    const target2 = try vm.spawn(idle, 0, null);
    const w2 = vm.procs.items[watcher2];
    const t2_term = try FinalTerms.pid(&w2.machine.ctx, target2, 0);
    w2.machine.pending = .{ .monitor_to = .{ .pid = t2_term, .dst = 4, .alias = .explicit } };
    try vm.interpret(watcher2);
    const aref2 = w2.machine.regs[4];
    try vm.terminate(target2, FinalTerms.atom(&vm.procs.items[target2].machine.ctx, atoms.intern("normal") catch unreachable));
    try vm.drainSignals(watcher2);
    const before = w2.machine.mbox.len(); // the 'DOWN'
    sp.machine.pending = .{ .send_to = .{ .pid = try refIn(&sp.machine.ctx, &w2.machine.ctx, aref2), .msg = ping } };
    try vm.interpret(sender);
    try vm.drainSignals(watcher2);
    try std.testing.expectEqual(before + 1, w2.machine.mbox.len()); // DELIVERED — explicit_unalias survives 'DOWN'
}

// ============================================================================
// E4.6 (Task 6): the io / group-leader message protocol law suite.
// ============================================================================

const gl_idle: ia.Program = &.{
    .{ .recv_any = .{ .dst = 0, .else_to = 0 } },
    .{ .jump = .{ .to = 0 } },
};

/// Build a charlist term (a proper list of byte ints) in `ctx` from `s`.
fn charlistOf(ctx: *FinalTerms.Ctx, s: []const u8) !FinalTerms.Term {
    var lst = FinalTerms.nil(ctx);
    var i = s.len;
    while (i > 0) {
        i -= 1;
        lst = try FinalTerms.cons(ctx, FinalTerms.int(ctx, s[i]), lst);
    }
    return lst;
}

test "E4.6 GROUP-LEADER PROTOCOL: one io_request -> exactly one io_reply with matching ReplyAs; put_chars appends exactly" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const gl = try vm.installGroupLeader(gl_idle);
    const caller = try vm.spawn(gl_idle, 0, null);
    vm.procs.items[caller].machine.group_leader = gl;

    // Hand-build {io_request, From, ReplyAs, {put_chars, unicode, "hi"}} in the
    // GL's heap and deliver it as a real message, exactly as a process would.
    const gm = &vm.procs.items[gl].machine;
    const a_io_request = try atoms.intern("io_request");
    const a_put_chars = try atoms.intern("put_chars");
    const a_unicode = try atoms.intern("unicode");
    const rtag = FinalTerms.int(&gm.ctx, 4242);
    const req = try FinalTerms.tuple(&gm.ctx, &.{
        FinalTerms.atom(&gm.ctx, a_io_request),
        try FinalTerms.pid(&gm.ctx, caller, 0),
        rtag,
        try FinalTerms.tuple(&gm.ctx, &.{
            FinalTerms.atom(&gm.ctx, a_put_chars),
            FinalTerms.atom(&gm.ctx, a_unicode),
            try charlistOf(&gm.ctx, "hi"),
        }),
    });
    try vm.signal(caller, gl, .{ .message = req });

    const serviced = try vm.serviceGroupLeader(gl);
    try std.testing.expectEqual(@as(usize, 1), serviced);
    // put_chars appended EXACTLY the bytes.
    try std.testing.expectEqualStrings("hi", vm.io_output.items);

    // EXACTLY ONE io_reply, carrying the SAME ReplyAs (the protocol law).
    try vm.drainSignals(caller);
    const cm = &vm.procs.items[caller].machine;
    try std.testing.expectEqual(@as(usize, 1), cm.mbox.len());
    const got = (try cm.mbox.peekAt(0)).?.payload;
    try std.testing.expect(FinalTerms.kindOf(&cm.ctx, got) == .tuple and FinalTerms.tupleArity(&cm.ctx, got) == 3);
    try std.testing.expectEqualStrings("io_reply", atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&cm.ctx, got, 0))));
    try std.testing.expect(FinalTerms.eqlExact(&cm.ctx, FinalTerms.tupleElem(&cm.ctx, got, 1), FinalTerms.int(&cm.ctx, 4242)));
    try std.testing.expectEqualStrings("ok", atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&cm.ctx, got, 2))));
}

test "E4.6 BOUNDED: N io_requests -> N replies, each matching; the GL never runs code" {
    const gpa = std.testing.allocator;
