test "E4.6 IO ROUND-TRIP: put_chars(Chars) sink == flattenChars(Chars) for charlist/binary/iolist" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    var ctx = FinalTerms.Ctx.init(gpa, &atoms);
    defer ctx.deinit();

    // A nested iolist flattens to the SAME bytes as its concatenation (the
    // homomorphism at the heart of the io writer): ["He", <<"ll">>, [111]] == "Hello".
    const he = try charlistOf(&ctx, "He");
    const ll = try FinalTerms.binary(&ctx, "ll");
    const o = try charlistOf(&ctx, "o");
    const iolist = try FinalTerms.cons(&ctx, he, try FinalTerms.cons(&ctx, ll, try FinalTerms.cons(&ctx, o, FinalTerms.nil(&ctx))));

    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(gpa);
    var budget: usize = 1_000_000;
    try Vm.flattenChars(&ctx, iolist, &out, gpa, &budget);
    try std.testing.expectEqualStrings("Hello", out.items);
}

test "E4.6-fix LOST-WAKEUP GUARD: a message delivered between loop_rec's empty peek and `wait` is received, not slept over (GL fixture installed)" {
    // The EXACT shape that escaped to the c_spawn suite regression: the parent
    // exhausts its slice fuel BETWEEN loop_rec's empty peek and the `wait`
    // instruction; the child's message is then enqueued+delivered while the
    // parent is still `.running` (the E3.7 enqueue-wake is a no-op), and the
    // parent executes `wait` LAST. Pre-fix `wait` suspended unconditionally —
    // sleeping forever over a nonempty mailbox (RunDidNotTerminate). The guard
    // (`wait`/`wait_timeout infinity` suspend ONLY when no message beyond the
    // save-pointer exists) makes the parent re-enter the loop and consume it.
    // Driven WITH the standard_io GL fixture installed, mirroring cli.runMulti.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // parent: the real E1.11 receive loop — loop_rec / wait, halt on the message.
    const recv_prog: ia.Program = &.{
        .{ .loop_rec = .{ .else_to = 3, .dst = 0 } }, // 0: peek cursor -> x0, empty => 3
        .remove_message, //                               1: commit the pop
        .{ .halt = .{ .src = .{ .x = 0 } } }, //          2: result = the message
        .{ .wait = .{ .to = 0 } }, //                     3: sleep (resume at 0)
    };
    const parent = try vm.spawn(recv_prog, 0, null);
    const gl = try vm.installGroupLeader(recv_prog);
    vm.procs.items[parent].machine.group_leader = gl;

    // Step the parent ONE reduction at a time to park it EXACTLY at the `wait`
    // pc (loop_rec peeked empty, wait not yet executed) — the fuel-boundary
    // window the scheduler produced in the wild.
    try vm.grant(parent, 1); // executes loop_rec (empty) -> pc = 3, still running
    const pm = &vm.procs.items[parent].machine;
    try std.testing.expectEqual(@as(u16, 3), pm.pc);
    try std.testing.expectEqual(ia.Status.running, pm.status);

    // The child's message arrives IN the window (enqueue-wake is a no-op:
    // the parent is already running).
    const sender = try vm.spawn(recv_prog, 3, null); // parked at wait; only sends
    const sp = vm.procs.items[sender];
    sp.machine.pending = .{ .send_to = .{
        .pid = FinalTerms.int(&sp.machine.ctx, @intCast(parent)),
        .msg = FinalTerms.int(&sp.machine.ctx, 42),
    } };
    try vm.interpret(sender);

    // The parent now executes `wait` — it must RE-ENTER the loop (running),
    // never suspend over the nonempty mailbox, and halt with the message.
    var guard: usize = 0;
    while (pm.status == .running and guard < 100) : (guard += 1) try vm.grant(parent, 1);
    try std.testing.expectEqual(ia.Status.halted, pm.status);
    try std.testing.expect(FinalTerms.eqlExact(&pm.ctx, pm.result, FinalTerms.int(&pm.ctx, 42)));

    // Contrast pin (the pre-existing law's shape stays true): an EMPTY-mailbox
    // wait still suspends — the guard never turns wait into a spin.
    const lone = try vm.spawn(recv_prog, 0, null);
    const lm = &vm.procs.items[lone].machine;
    var g2: usize = 0;
    while (lm.status == .running and g2 < 100) : (g2 += 1) try vm.grant(lone, 1);
    try std.testing.expectEqual(ia.Status.suspended, lm.status);
}

