// ============================================================================
// E6.2 (Task 2): the LIVE receive/BIF timer laws — the timer_wheel goes LIVE
// (DIVERGENCE entry 5's residual discharged). The wheel's own oracle≡final
// homomorphism + at-most-once + cancel-then-fire-impossible live in
// timer_wheel.zig; these laws pin the INTEGRATION: `wait_timeout` finite arms a
// real entry, the scheduler fires it in deadline order, and a message before the
// timeout cancels the entry EXACTLY-ONCE (the lost-wakeup guard's timer half).
// ============================================================================

// A real E1.11 receive with a finite `after` clause: `receive Msg -> Msg after
// N -> N end`. x15 carries N (the spawn arg); the message path halts the message,
// the after-clause halts N (distinct sentinels so the two paths are observable).
const recv_after_prog: ia.Program = &.{
    .{ .loop_rec = .{ .else_to = 3, .dst = 0 } }, // 0: peek cursor -> x0; empty => 3
    .remove_message, //                              1: commit the pop
    .{ .halt = .{ .src = .{ .x = 0 } } }, //         2: message path: result = Msg
    .{ .wait_timeout = .{ .to = 0, .src = .{ .x = 15 } } }, // 3: arm N-ms timer / suspend
    .timeout, //                                     4: after-clause entry
    .{ .halt = .{ .src = .{ .x = 15 } } }, //        5: timeout path: result = N
};

test "E6.2 RECEIVE-AFTER FIRES via the live wheel: `receive after N` with no message takes the after-clause; the virtual clock advances to N exactly (never early)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const p = try vm.spawn(recv_after_prog, 0, 5); // x15 = N = 5 ms
    try (@as(Scheduler, .round_robin)).drive(&vm, 20, 500);

    const m = &vm.procs.items[p].machine;
    // The after-clause ran (result == N), the wheel fired at EXACTLY N (never
    // early), and no timer is left live (at-most-once at the Vm layer).
    try std.testing.expectEqual(ia.Status.halted, m.status);
    try std.testing.expect(FinalTerms.eqlExact(&m.ctx, m.result, FinalTerms.int(&m.ctx, 5)));
    try std.testing.expectEqual(@as(u64, 5), vm.vclock);
    try std.testing.expect(!vm.timersPending());
}

test "E6.2 LOST-WAKEUP TIMER CANCEL: a message arriving before the timeout cancels the armed receive entry EXACTLY-ONCE; no spurious timeout, the virtual clock does not advance" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // Park the receiver EXACTLY at the armed `wait_timeout` (a long 50-ms timeout).
    const p = try vm.spawn(recv_after_prog, 0, 50);
    const pm = &vm.procs.items[p].machine;
    var guard: usize = 0;
    while (pm.status == .running and guard < 100) : (guard += 1) try vm.grant(p, 1);
    try std.testing.expectEqual(ia.Status.suspended, pm.status);
    // The receive timer is ARMED: a live wheel entry + the process handle.
    try std.testing.expect(vm.timersPending());
    try std.testing.expect(vm.procs.items[p].recv_timer != null);

    // A message arrives BEFORE the timeout — Vm.signal wakes the process AND
    // cancels the armed entry exactly-once (recv_timer cleared, meta not live).
    try vm.signal(p, p, .{ .message = FinalTerms.int(&pm.ctx, 7) });
    try std.testing.expect(vm.procs.items[p].recv_timer == null);
    try std.testing.expect(!vm.timersPending()); // cancelled: no live entry remains

    // Drive to completion: the MESSAGE path runs (result == 7), the clock never
    // advanced (no time passed — the delivery was event-driven), and no spurious
    // `timeout` was ever taken.
    try (@as(Scheduler, .round_robin)).drive(&vm, 20, 500);
    try std.testing.expectEqual(ia.Status.halted, pm.status);
    try std.testing.expect(FinalTerms.eqlExact(&pm.ctx, pm.result, FinalTerms.int(&pm.ctx, 7)));
    try std.testing.expectEqual(@as(u64, 0), vm.vclock);
    try std.testing.expect(!pm.timer_fired);
}

test "E6.2 FIRE-ORDER HOMOMORPHISM + CANCEL-RACE TOTALITY + ARM/CANCEL ROUND-TRIP: send_after timers fire in deadline order; a cancel before fire returns remaining and never delivers; a cancel/read after fire returns false" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    // One owner that arms the timers, delivering to a DISTINCT target proc; both
    // stay suspended so they run no code — we observe only the wheel engine.
    const owner = try vm.spawn(recv_after_prog, 0, null);
    const target = try vm.spawn(recv_after_prog, 0, null);
    const om = &vm.procs.items[owner].machine;
    vm.procs.items[owner].machine.status = .suspended;
    vm.procs.items[target].machine.status = .suspended;
    const dest = try FinalTerms.pid(&om.ctx, target, 0); // fires deliver to `target`
    const msg = FinalTerms.int(&om.ctx, 0);

    // Arm three send_after timers OUT of deadline order (30, 10, 20 ms).
    const t30 = try vm.armBifTimer(owner, .send_after, FinalTerms.int(&om.ctx, 30), dest, msg, false);
    const t10 = try vm.armBifTimer(owner, .send_after, FinalTerms.int(&om.ctx, 10), dest, msg, false);
    const t20 = try vm.armBifTimer(owner, .send_after, FinalTerms.int(&om.ctx, 20), dest, msg, false);

    // read_timer of a LIVE timer returns its remaining ms (vclock == 0).
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doReadTimer(owner, t10, false), FinalTerms.int(&om.ctx, 10)));
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doReadTimer(owner, t30, false), FinalTerms.int(&om.ctx, 30)));

    // ARM/CANCEL ROUND-TRIP: cancel t20 BEFORE it fires — returns the remaining
    // ms (20), and the entry is retired so it never fires.
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doCancelTimer(owner, t20, true, false), FinalTerms.int(&om.ctx, 20)));
    // CANCEL-RACE (at-most-once): a SECOND cancel of the same TRef is `false`.
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doCancelTimer(owner, t20, true, false), FinalTerms.atom(&om.ctx, om.bool_false)));
    // read_timer of the cancelled timer is also `false`.
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doReadTimer(owner, t20, false), FinalTerms.atom(&om.ctx, om.bool_false)));

    // FIRE-ORDER HOMOMORPHISM (+ never-early): advance event-to-event; the fired
    // deadlines ascend (10 then 30 — the cancelled 20 never fires), and the clock
    // equals the fired timer's deadline at each step (never early).
    try vm.advanceTimersToNext();
    try std.testing.expectEqual(@as(u64, 10), vm.vclock);
    try vm.advanceTimersToNext();
    try std.testing.expectEqual(@as(u64, 30), vm.vclock); // jumped PAST the cancelled 20
    try std.testing.expect(!vm.timersPending());

    // RIGHT-PROCESS DELIVERY: exactly the two fired timers delivered to `target`
    // (the cancelled 20 delivered nothing) — a fire that enqueues to the wrong
    // process reddens here. The owner received nothing (it only armed them).
    try vm.drainSignals(target);
    try vm.drainSignals(owner);
    try std.testing.expectEqual(@as(usize, 2), vm.procs.items[target].machine.mbox.len());
    try std.testing.expectEqual(@as(usize, 0), vm.procs.items[owner].machine.mbox.len());

    // CANCEL-RACE TOTALITY after fire: cancel/read a FIRED timer → false.
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doCancelTimer(owner, t10, true, false), FinalTerms.atom(&om.ctx, om.bool_false)));
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doReadTimer(owner, t30, false), FinalTerms.atom(&om.ctx, om.bool_false)));
}

test "LAW gap-abs-timer-vclock (DIVERGENCE 729): an {abs,true} timer's absolute monotonic deadline is translated into vclock space and FIRES — was armed ~1e9 ticks out (never reached before any relative timer)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const owner = try vm.spawn(recv_after_prog, 0, null);
    const target = try vm.spawn(recv_after_prog, 0, null);
    const om = &vm.procs.items[owner].machine;
    vm.procs.items[owner].machine.status = .suspended;
    vm.procs.items[target].machine.status = .suspended;
    const dest = try FinalTerms.pid(&om.ctx, target, 0);
    const msg = FinalTerms.int(&om.ctx, 0);

    // Arm an ABS timer at monotonic_now_ms + 5000 (a huge ~1e9-scale absolute value)
    // PLUS a RELATIVE 1_000_000 ms timer. Pre-fix, `deadline = time` armed the abs at
    // ~1e9 verbatim in vclock space → the relative-1e6 was the minimum and fired
    // FIRST, the abs NEVER firing. Post-fix, the abs is translated to ~vclock+5000 →
    // it is the minimum and fires FIRST, well before the relative 1e6.
    const now_ms: i128 = om.clock.monotonic(1000); // current monotonic ms
    const abs_deadline = FinalTerms.int(&om.ctx, @as(i64, @intCast(now_ms + 5000)));
    _ = try vm.armBifTimer(owner, .start_timer, abs_deadline, dest, msg, true);
    _ = try vm.armBifTimer(owner, .start_timer, FinalTerms.int(&om.ctx, 1_000_000), dest, msg, false);

    // The abs fires FIRST at ~vclock+5000 (translated), NOT ~1e9. Tolerant of the
    // sub-ms skew between the test's clock read and armBifTimer's read: the assertion
    // is "advanced a small positive amount" (0 < vclock < 100_000), which neither the
    // ~1e9 bug (vclock would jump to 1_000_000) nor a wrong-sign clamp (vclock stays
    // 0) can satisfy.
    try vm.advanceTimersToNext();
    try std.testing.expect(vm.vclock > 0); // the abs actually fired (not clamped to 0)
    try std.testing.expect(vm.vclock < 100_000); // and at ~5000, NOT ~1e9 / not the 1e6 relative
    // it DELIVERED to `target` (fired, not merely advanced).
    try vm.drainSignals(target);
    try std.testing.expect(vm.procs.items[target].machine.mbox.len() >= 1);
}

test "LAW e47-timer-meta-quadratic: the tref→idx index is O(1) + AGREES with the old linear scan + CONSERVES (map count == live BIF timers, 0 after all fire — no leak)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const owner = try vm.spawn(recv_after_prog, 0, null);
    const target = try vm.spawn(recv_after_prog, 0, null);
    const om = &vm.procs.items[owner].machine;
    vm.procs.items[owner].machine.status = .suspended;
    vm.procs.items[target].machine.status = .suspended;
    const dest = try FinalTerms.pid(&om.ctx, target, 0);
    const msg = FinalTerms.int(&om.ctx, 0);

    // The reference: the ORIGINAL linear scan `timerByTref` replaced + the live
    // BIF-timer count `timer_tref_idx.count()` must equal.
    const Ref = struct {
        fn scan(v: *Vm, key: u64) ?usize {
            for (v.timer_meta.items, 0..) |*t, i| {
                if (t.live and t.tref == key) return i;
            }
            return null;
        }
        fn liveBif(v: *Vm) usize {
            var n: usize = 0;
            for (v.timer_meta.items) |t| {
                if (t.live and (t.kind == .send_after or t.kind == .start_timer)) n += 1;
            }
            return n;
        }
    };

    var trefs: [8]u64 = undefined;
    for (0..8) |i| {
        const tr = try vm.armBifTimer(owner, .send_after, FinalTerms.int(&om.ctx, @intCast((i + 1) * 10)), dest, msg, false);
        trefs[i] = Vm.keyFromRefWords(FinalTerms.refWords(&om.ctx, tr));
    }
    // CONSERVATION + AGREEMENT after arming.
    try std.testing.expectEqual(Ref.liveBif(&vm), vm.timer_tref_idx.count());
    for (trefs) |k| try std.testing.expectEqual(Ref.scan(&vm, k), vm.timerByTref(k));
    try std.testing.expectEqual(Ref.scan(&vm, 0xDEAD_BEEF), vm.timerByTref(0xDEAD_BEEF)); // a miss: both null

    // Cancel two → the index + conservation track; cancelled trefs miss on BOTH.
    _ = try vm.doCancelTimer(owner, try FinalTerms.ref(&om.ctx, Vm.refWordsForKey(trefs[1])), true, false);
    _ = try vm.doCancelTimer(owner, try FinalTerms.ref(&om.ctx, Vm.refWordsForKey(trefs[3])), true, false);
    try std.testing.expectEqual(Ref.liveBif(&vm), vm.timer_tref_idx.count());
    for (trefs) |k| try std.testing.expectEqual(Ref.scan(&vm, k), vm.timerByTref(k));

    // Fire the rest → the index drains to EMPTY (every fire retires its entry — no
    // leak) and conservation holds at 0.
    while (vm.timersPending()) try vm.advanceTimersToNext();
    try std.testing.expectEqual(@as(usize, 0), Ref.liveBif(&vm));
    try std.testing.expectEqual(@as(usize, 0), vm.timer_tref_idx.count());
    for (trefs) |k| try std.testing.expect(vm.timerByTref(k) == null);
}

// gap-proc-density (SCALE, Sev-4): zigvm's `Process` EMBEDS the full `Machine`, so
// each process carries a heavyweight fixed struct vs BEAM's ~338-word (~2704 B)
// initial process. The density-engine CLOSE is XL (a slab/tiny-proc substrate);
// this slice QUANTIFIES the gap with an exact, deterministic figure + a regression
// guard against further struct bloat — "you can't close a gap you can't measure".
const beam_initial_proc_bytes: usize = 2704; // ~338 words × 8 (documented erts PCB+heap)
fn procStructBytes() usize {
    return @sizeOf(Process);
}
/// Density ratio ×1000 — zigvm's fixed per-proc struct vs BEAM's total initial proc.
/// A LOWER bound on the real gap (excludes the ArrayList backing + the term heap).
fn procDensityRatioX1000() usize {
    return procStructBytes() * 1000 / beam_initial_proc_bytes;
}

test "LAW gap-proc-density: per-process struct footprint — regression guard + BEAM density-gap quantification (MEASUREMENT)" {
    const b = procStructBytes();
    // REGRESSION GUARD: the Process struct must not silently bloat (or shrink to a
    // suspiciously-small size that means a field was dropped). Current: 3968 B.
    try std.testing.expect(b >= 3072 and b <= 4608);
    // GAP IS REAL: even the fixed struct — NO heap, NO ArrayList backing — exceeds
    // BEAM's ~2704 B TOTAL initial process, so the density ratio is a lower bound > 1.
    try std.testing.expect(procDensityRatioX1000() > 1000);
    // THE LEVER: the embedded Machine dominates the footprint (≥80% of Process), so
    // shrinking Machine (the register file + fields) is where a density engine pays.
    try std.testing.expect(@sizeOf(ia.Machine) * 100 / b >= 80);
}

test "DEBUG doUnalias" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{ .{ .recv_any = .{ .dst = 0, .else_to = 0 } }, .{ .jump = .{ .to = 0 } } };
    const w = try vm.spawn(idle, 0, null);
    const pw = vm.procs.items[w];
    pw.machine.pending = .{ .monitor_to = .{ .pid = FinalTerms.int(&pw.machine.ctx, 9999), .dst = 5, .alias = .explicit } };
    try vm.interpret(w);
    const ref = pw.machine.regs[5];
    pw.machine.pending = .{ .unalias_ref = .{ .ref = ref } };
    try vm.interpret(w);
    try std.testing.expectEqual(pw.machine.bool_true, FinalTerms.atomIdxOf(pw.machine.regs[0]));
}

test "LAW e47-a4 cancel-timer async-reply gating: {async,true},{info,false} SUPPRESSES the {cancel_timer,..} reply (OTP erlang:cancel_timer/2 — the gen_server kill-restart livelock fix); {info,true} replies EXACTLY once; both CANCEL" {
    // The livelock seam (perf-proven 69.7% doCancelTimer under a kill+restart):
    // gen_server's loop cancels with [{async,true},{info,false}]; a reply it
    // never asked for hits decode_msg's wildcard, which cancels AGAIN → a
    // self-feeding message loop. The law pins the OTP gating exactly.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const owner = try vm.spawn(idle, 0, null);
    const om = &vm.procs.items[owner].machine;
    vm.procs.items[owner].machine.status = .suspended;
    const dest = try FinalTerms.pid(&om.ctx, owner, 0);
    const msg = FinalTerms.int(&om.ctx, 0);
    const t_a = try vm.armBifTimer(owner, .send_after, FinalTerms.int(&om.ctx, 50), dest, msg, false);
    const t_b = try vm.armBifTimer(owner, .send_after, FinalTerms.int(&om.ctx, 60), dest, msg, false);
    const before = om.mbox.len();

    // async + info=false: `ok`, and the mailbox is UNCHANGED (no reply message).
    const r1 = try vm.doCancelTimer(owner, t_a, false, true);
    try std.testing.expect(FinalTerms.repIsAtom(r1));
    try std.testing.expectEqual(before, om.mbox.len());

    // async + info=true: `ok` and EXACTLY ONE {cancel_timer, TRef, Remaining}.
    const r2 = try vm.doCancelTimer(owner, t_b, true, true);
    try std.testing.expect(FinalTerms.repIsAtom(r2));
    try std.testing.expectEqual(before + 1, om.mbox.len());

    // Suppressing the REPLY never suppresses the CANCEL: both timers are dead.
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doReadTimer(owner, t_a, false), FinalTerms.atom(&om.ctx, om.bool_false)));
    try std.testing.expect(FinalTerms.eqlExact(&om.ctx, try vm.doReadTimer(owner, t_b, false), FinalTerms.atom(&om.ctx, om.bool_false)));
}

test "LAW e48-smp-s1 PHASE-SPLIT: grantOnly (the per-proc parallel unit) NEVER runs the global tick services — a parked spawn-reply stays parked; grant (coordinator+unit) delivers it. Default callers byte-identical" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const requester = try vm.spawn(idle, 0, null);
    const bystander = try vm.spawn(idle, 0, null);
    // Park a spawn-request reply by hand (the E5.6 window shape): the reply
    // term lives in the requester's heap, delivery is a TICK service.
    const rm = &vm.procs.items[requester].machine;
    const reply = try FinalTerms.tuple(&rm.ctx, &.{ FinalTerms.atom(&rm.ctx, try atoms.intern("ok")), FinalTerms.int(&rm.ctx, 7) });
    try vm.parked_spawn.append(gpa, .{ .reqid = 1, .to = requester, .child = bystander, .reply = reply, .vhash = FinalTerms.hashTerm(&rm.ctx, reply) });
    const parked_before = vm.parked_spawn.items.len;
    try std.testing.expectEqual(@as(usize, 1), parked_before);
    const mbox_before = rm.mbox.len();
    // PHASE SPLIT: the per-proc unit does NOT deliver the parked reply...
    try vm.grantOnly(requester, 5);
    try std.testing.expectEqual(@as(usize, 1), vm.parked_spawn.items.len);
    try std.testing.expectEqual(mbox_before, rm.mbox.len());
    // ...the full grant (coordinator phase + unit) DOES.
    try vm.grant(requester, 5);
    try std.testing.expectEqual(@as(usize, 0), vm.parked_spawn.items.len);
    try std.testing.expectEqual(mbox_before + 1, rm.mbox.len());
}

test "LAW e48-smp-s2 FRAGMENT SEND: the sender NEVER writes the receiver's heap (untouched until the receiver's OWN drain merges the fragment); denotation preserved; a death-before-drain fragment is freed (allocator-proven zero-leak)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const sender = try vm.spawn(idle, 0, null);
    const receiver = try vm.spawn(idle, 0, null);
    const sm = &vm.procs.items[sender].machine;
    const rm = &vm.procs.items[receiver].machine;

    // the message lives in the SENDER's heap
    const msg = try FinalTerms.tuple(&sm.ctx, &.{ FinalTerms.atom(&sm.ctx, try atoms.intern("hello")), FinalTerms.int(&sm.ctx, 99) });
    const rwords_before = rm.ctx.words.items.len;

    // SENDER PHASE: interpret the send trap — the receiver's heap must be
    // UNTOUCHED (the S3 precondition: no cross-thread heap write), the signal
    // queued as a fragment.
    sm.pending = .{ .send_to = .{ .pid = try FinalTerms.pid(&sm.ctx, receiver, 0), .msg = msg } };
    try vm.interpret(sender);
    try std.testing.expectEqual(rwords_before, rm.ctx.words.items.len); // receiver heap untouched
    try std.testing.expectEqual(@as(usize, 1), vm.procs.items[receiver].sigq.items.len);
    try std.testing.expect(vm.procs.items[receiver].sigq.items[0].sig == .message_frag);

    // RECEIVER PHASE: the drain merges the fragment into the receiver's heap;
    // the delivered term denotes EXACTLY the original.
    try vm.drainSignals(receiver);
    try std.testing.expectEqual(@as(usize, 1), rm.mbox.len());
    const got = (try rm.mbox.peekAt(0)).?.payload;
    try std.testing.expect(FinalTerms.kindOf(&rm.ctx, got) == .tuple);
    try std.testing.expectEqual(@as(i64, 99), FinalTerms.smallValOf(FinalTerms.tupleElem(&rm.ctx, got, 1)));
    try std.testing.expect(rm.ctx.words.items.len > rwords_before); // the merge landed HERE

    // DEATH-BEFORE-DRAIN: a fragment parked at a receiver that dies undrained
    // is freed by the deinit sweep — std.testing.allocator proves it (a leak
    // here fails the whole test block).
    const msg2 = try FinalTerms.tuple(&sm.ctx, &.{FinalTerms.int(&sm.ctx, 7)});
    sm.pending = .{ .send_to = .{ .pid = try FinalTerms.pid(&sm.ctx, receiver, 0), .msg = msg2 } };
    try vm.interpret(sender);
    try std.testing.expectEqual(@as(usize, 1), vm.procs.items[receiver].sigq.items.len);
    try vm.terminate(receiver, FinalTerms.atom(&rm.ctx, try atoms.intern("normal")));
    // (no drain — vm.deinit's sweep must free the fragment; the allocator is the judge)
}

test "LAW e48-smp-s3 CONCURRENT-EXECUTION QUOTIENT: 20 repetitions at n=4 with UNLOCKED machine runs — every run completes in the work budget, denotes the oracle EXACTLY, and keeps the sacred per-pair order (ownership/deferred-wake/quiescence all load-bearing)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var rr = try runRing(gpa, &atoms, .round_robin, 5);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;
    const max_grants: usize = 100_000;
    var rep: usize = 0;
    while (rep < 20) : (rep += 1) {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const collector = try seedRing(&vm, 5);
        const eng = SmpEngine{ .n_sched = 4, .seed = 0xBEEF +% @as(u64, rep) };
        const run = try eng.driveThreads(&vm, 7, max_grants, 60 * std.time.ns_per_s);
        try std.testing.expect(run.grants < max_grants); // no starvation/livelock (work-bounded)
        const cm = &vm.procs.items[collector].machine;
        try std.testing.expectEqual(ia.Status.halted, cm.status); // completed (a lost wake would leave .running)
        try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4); // the QUOTIENT: denotation invariant
        try std.testing.expect(checkPerPairOrder(vm.events.items)); // the sacred order under real concurrency
    }
}

// ============================================================================
// gap-b-5a (SMP step 5a, the ENABLING REFACTOR): the concurrent-execution
// quotient + ownership conservation RE-WITNESSED on the RELOCATED state layout —
// ownership moved off `Process` into the `L_c`-domain `Vm.owned[pid]` array, and
// discovery made PUSH-BASED (the `Vm.ready` inbox + `queued` dedup) so the SMP
// coordinator never scans `vm.procs`. This is NOT a mere critical-section move,
// so the concurrency correctness is proven AFRESH on the new state — not merely
// inherited from e48-smp-s3/gap-b-4.
//
// SAFETY PACKET (SAFETY_ANALYSIS §CTRL-SCHED; controller = the ownership-state
// RELOCATION + the push-based wake enqueue). UCA = UCA-SMP-11 (ownership state
// torn/duplicated/lost across the relocation → double-grant / lost pid /
// conservation break) + UCA-SMP-9 (any lock on the new path keeps the acyclic
// order). MITIGATION = the conservation law below (`owned`/`queued`/`ready` are
// clean at quiescence AND the denotation equals the oracle) + the re-witnessed
// quotient (real threads, per-pair order) + the unchanged acyclic order (`owned`
// and `ready` are `L_c`-domain, no new back-edge; `enqueueReadyLocked` re-takes
// no lock, `signal`'s wake decision is ONE `L_c` section, `deliverParked*` no
// longer hold `L_c` across `signal`). FMEA = a wake that fails to enqueue → a
// stranded process → the ring never completes → BOUNDED red (never a hung node).
//
// MUT-GAPB5A-1 (push-based DOUBLE-ENQUEUE): drop the `if (self.queued.items[pid])
//   return;` dedup in `enqueueReadyLocked` → a woken pid already in a run queue is
//   pushed to `ready` AGAIN → drained into `qs` twice → granted twice → the ring
//   sum double-counts / a `queued` bit is left set at quiescence → RED (the
//   denotation and the clean-`queued` assertions below both fire).
// MUT-GAPB5A-2 (owned NOT cleared on release): drop `ctx.vm.owned.items[pid.?] =
//   null;` in the worker's release epilogue → a released pid stays `owned` →
//   `signal` defers its wake forever (owner-check sees non-null) → lost wakeup →
//   the ring hangs to the wall bound (BOUNDED red) / `owned` is non-null at
//   quiescence → the clean-`owned` assertion fires → RED.
test "LAW gap-b-5a ENABLING-REFACTOR RE-WITNESS: driveThreads on the relocated (owned[pid]) + push-based (ready) layout denotes the oracle at n∈{1,2,4}, preserves the sacred per-pair order, AND leaves the L_c-domain coherency arrays CLEAN at quiescence (owned all-null / queued all-false / ready empty) — ownership conservation on the new state" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var rr = try runRing(gpa, &atoms, .round_robin, 6);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;
    const max_grants: usize = 100_000;
    const scheds = [_]u32{ 1, 2, 4 };
    for (scheds) |ns| {
        var rep: usize = 0;
        while (rep < 8) : (rep += 1) {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 6);
            const eng = SmpEngine{ .n_sched = ns, .seed = 0x5A5A +% @as(u64, rep) *% 7 +% ns };
            const run = try eng.driveThreads(&vm, 5, max_grants, 60 * std.time.ns_per_s);
            try std.testing.expect(run.grants < max_grants); // work-bounded (no lost wake → no livelock)
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status); // completed (MUT-2's lost wake would leave it .running / hang)
            try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4); // the QUOTIENT on the new layout (MUT-1 double-count reds this)
            try std.testing.expect(checkPerPairOrder(vm.events.items)); // sacred per-pair order under real concurrency
            // CONSERVATION at quiescence — the terminal state of `queue_total +
            // owned_count == P`: with every proc halted, NOTHING is owned, NOTHING
            // is queued, the ready inbox is empty. MUT-1 leaves a `queued` bit set
            // (double-enqueue); MUT-2 leaves an `owned` slot non-null (unreleased).
            try std.testing.expectEqual(@as(usize, 0), vm.ready.items.len);
            for (vm.owned.items) |*o| try std.testing.expectEqual(NO_OWNER, o.load(.monotonic));
            for (vm.queued.items) |*q| try std.testing.expect(!q.load(.monotonic));
        }
    }
}

// ============================================================================
// gap-b-6a (SMP step 6a, THE FINAL EPILOGUE FLIP): relocate the BIF-suspension
// count off `Process` into the `L_c`-domain per-pid `Vm.suspend_a`, so the whole
// `schedulable` predicate is `L_c`-readable and the epilogue SECTION B (deferred
// wake + schedulable-gated requeue + clear-owned) runs under `L_c` ALONE — the
// symmetric partner of gap-b-5a's prologue flip. After this the `L_v` critical
// section is minimal in BOTH prologue and epilogue (only the grant COUNTER, the
// `procs` deref + `drainSignals`, and the genuine exit paths remain `L_v`-bound).
//
// SAFETY PACKET (SAFETY_ANALYSIS §CTRL-SCHED; controller = the scheduler epilogue /
// the coherency lock `L_c` + the suspension gate). UCA:
//   * UCA-SMP-11 (CONSERVATION): the clear-owned + schedulable-gated requeue is now
//     under `L_c` ALONE — if it is not ONE atomic `L_c` mutation a pid could be
//     observably owned AND queued, or lost between the two (queue_total+owned≠P).
//   * SUSPENSION INVARIANT (the new one this slice must preserve — exactly what the
//     old `L_v`-bound `schedulable` protected): a proc that is BIF-suspended at its
//     release point must NEVER be requeued/run while suspended. A torn read of the
//     count (if it stayed a `Process` field written by a concurrent suspend/resume
//     BIF on another worker) could requeue a suspended proc → the run loop RUNS it →
//     suspension violated. Relocating the count to `L_c`-domain `suspend_a`, mutated
//     under `L_c` by suspend/resume and read under `L_c` by the epilogue, closes it.
//   * UCA-SMP-9 (ORDER): the release path must keep the total lock order
//     `L_v→L_c→…` with NO back-edge — `L_c` is released FIRST on every exit before
//     any `L_v` acquire (err/grant-counter), and `suspend_a` adds NO new lock (the
//     suspend/resume BIFs reach DOWN `L_v→L_c`, the sanctioned direction).
// HAZARD = a scheduler thread never returns (hung node); a suspended process RUNS
// (correctness/safety violation); a process is lost or double-granted (a hung ring /
// corrupt result). MITIGATION = (1) the RE-WITNESS law below re-runs the FULL
// concurrent quotient on the new layout — denote==oracle at n∈{1,2,4}, sacred
// per-pair order, work-bounded, coherency arrays (owned/queued/ready AND suspend_a)
// CLEAN at quiescence; (2) the SUSPENSION-CORRECTNESS law drives `driveThreads` with
// a BIF-suspended proc and proves it is NEVER completed while suspended yet the run
// still quiesces clean, and that a real `resume_process` re-admits it; (3) the
// existing gap-b-5 bounded lock-order model still witnesses `L_v→L_c` has no
// back-edge (suspend/resume add no lock). FMEA = a suspended proc that runs, or a
// lost/double-granted proc, reddens laws (1)/(2) rather than silently corrupting.
//
// MUT-GAPB6A-1 (requeue IGNORES suspension — drop the gate): make epilogue SECTION B
//   requeue UNCONDITIONALLY (`if (true)` instead of `if (schedulable(ctx.vm, pid))`)
//   → a BIF-suspended proc is put back in the run queue and RUN → the
//   SUSPENSION-CORRECTNESS law sees `psusp` reach `.halted` while suspended → RED.
// MUT-GAPB6A-2 (suspend/resume NOT deferred to L_c — torn read): make `doSuspend`/
//   `doResume` mutate a per-`Process` count WITHOUT `L_c` (i.e. re-introduce the
//   `L_v`-only write the residual note warned of) → the epilogue's `L_c`-alone read
//   races the concurrent BIF write → under the soak/quotient the requeue gate sees a
//   torn/stale count → either a suspended proc requeues (RED SUSPENSION) or a
//   runnable one is dropped (owned/queued non-clean at quiescence → RED CONSERVATION).
//   (Modelled here as: if `suspend_a` were not read under `L_c` at the epilogue, the
//   RE-WITNESS conservation check catches the dropped/duplicated pid.)

// LAW gap-b-6a QUOTIENT RE-WITNESS: the concurrent-execution quotient re-proved on
// the RELOCATED suspension layout with the epilogue SECTION B running under `L_c`
// ALONE. `driveThreads` on the confluent messaging ring at n∈{1,2,4} still denotes
// the sequential oracle EXACTLY, preserves the sacred per-pair order, is work-bounded
// (no lost wake → no livelock under the narrower epilogue), and leaves the FULL
// `L_c`-domain coherency state — `owned` all-null, `queued` all-false, `ready` empty,
// AND the relocated `suspend_a` all-zero — CLEAN at quiescence (ownership + suspension
// conservation on the new state). This is the from-scratch re-witness the slice
// demands: it does NOT lean on the old proof, it re-runs the whole engine.
test "LAW gap-b-6a QUOTIENT RE-WITNESS: driveThreads with epilogue SECTION B under L_c-ALONE (suspend count relocated to the L_c-domain suspend_a) denotes the oracle at n∈{1,2,4}, keeps the sacred per-pair order, is work-bounded, and leaves owned/queued/ready/suspend_a CLEAN at quiescence" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var rr = try runRing(gpa, &atoms, .round_robin, 6);
    defer rr.events.deinit(gpa);
    const oracle = rr.total;
    const max_grants: usize = 100_000;
    const scheds = [_]u32{ 1, 2, 4 };
    for (scheds) |ns| {
        var rep: usize = 0;
        while (rep < 10) : (rep += 1) {
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, 6);
            const eng = SmpEngine{ .n_sched = ns, .seed = 0xB6A6 +% @as(u64, rep) *% 13 +% ns };
            const run = try eng.driveThreads(&vm, 5, max_grants, 60 * std.time.ns_per_s);
            try std.testing.expect(run.grants < max_grants); // work-bounded under the L_c-alone epilogue
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status); // completed
            try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4); // QUOTIENT on the relocated layout
            try std.testing.expect(checkPerPairOrder(vm.events.items)); // sacred per-pair order under REAL overlap
            // CONSERVATION at quiescence — ownership AND suspension state clean.
            try std.testing.expectEqual(@as(usize, 0), vm.ready.items.len);
            for (vm.owned.items) |*o| try std.testing.expectEqual(NO_OWNER, o.load(.monotonic));
            for (vm.queued.items) |*q| try std.testing.expect(!q.load(.monotonic));
            for (vm.suspend_a.items) |*sv| try std.testing.expectEqual(@as(u32, 0), sv.load(.monotonic)); // relocated state inert & clean
        }
    }
}

// LAW gap-b-6a SUSPENSION CORRECTNESS under the L_c-alone epilogue: the exact
// invariant the old `L_v`-bound `schedulable` protected, re-proved with the requeue
// gate now reading the `L_c`-domain `suspend_a` under `L_c` ALONE. A BIF-suspended
// proc (`suspend_a > 0`) is granted at most its already-queued quantum but is NEVER
// REQUEUED while suspended, so it never runs to completion — yet the run still
// reaches quiescence CLEAN (conservation holds even with a proc parked out of the
// run queue). A real `resume_process` (the `L_c` decrement + push-based re-enqueue)
// then re-admits it and a second drive completes it. MUT-GAPB6A-1 (unconditional
// requeue) makes `psusp` halt while suspended → the `!= .halted` assertion reds.
test "LAW gap-b-6a SUSPENSION CORRECTNESS: a BIF-suspended proc is NEVER requeued/completed by the L_c-alone epilogue while suspended (conservation still clean), and resume_process re-admits it — the invariant the L_v-bound schedulable protected, on the relocated suspend_a" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    // A small counting loop: with SMALL fuel it needs MANY grants to halt, so what
    // drives it to completion is the EPILOGUE REQUEUE — precisely the gate under test.
    const susp_loop: ia.Program = &.{
        .{ .add = .{ .a = .{ .imm = 0 }, .b = .{ .imm = 1 }, .dst = 0 } }, // 0: seed x0 = 1 (never read uninit)
        .{ .add = .{ .a = .{ .x = 0 }, .b = .{ .imm = 1 }, .dst = 0 } }, // 1: x0 += 1
        .{ .is_lt = .{ .a = .{ .x = 0 }, .b = .{ .imm = 40 }, .else_to = 4 } }, // 2: x0<40 → loop; else halt
        .{ .jump = .{ .to = 1 } }, // 3
        .{ .halt = .{ .src = .{ .x = 0 } } }, // 4
    };
    const scheds = [_]u32{ 1, 2, 4 };
    for (scheds) |ns| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const psusp = try vm.spawn(susp_loop, 0, null);
        const pfree = try vm.spawn(susp_loop, 0, null);
        // SUSPEND psusp (as `suspend_process` would: the `L_c`-domain count > 0). It is
        // already in the ready inbox (spawn pushed it while schedulable); the POINT of
        // this law is that the epilogue REQUEUE gate — reading `suspend_a` under `L_c`
        // ALONE — refuses to put it back, so it never runs to completion.
        vm.suspend_a.items[psusp].store(1, .monotonic);
        const eng = SmpEngine{ .n_sched = ns, .seed = 0xB6A0 +% ns };
        const run = try eng.driveThreads(&vm, 6, 100_000, 60 * std.time.ns_per_s);
        try std.testing.expect(run.grants < 100_000); // work-bounded — the gate stops the churn
        // SUSPENSION CORRECTNESS: psusp NEVER completed (never requeued while suspended).
        try std.testing.expect(vm.procs.items[psusp].machine.status != .halted);
        // the runnable proc DID complete — the engine still makes progress.
        try std.testing.expectEqual(ia.Status.halted, vm.procs.items[pfree].machine.status);
        // CONSERVATION at quiescence — even with a suspended proc parked out of queue.
        try std.testing.expectEqual(@as(usize, 0), vm.ready.items.len);
        for (vm.owned.items) |*o| try std.testing.expectEqual(NO_OWNER, o.load(.monotonic));
        for (vm.queued.items) |*q| try std.testing.expect(!q.load(.monotonic));
        // RESUME via the REAL BIF path (`doResume`: `L_c` decrement + push re-enqueue).
        const cm = &vm.procs.items[pfree].machine; // any live heap as the control term ctx
        const tp = try FinalTerms.pid(&cm.ctx, psusp, 0);
        _ = vm.doResume(cm, tp);
        try std.testing.expectEqual(@as(u32, 0), vm.suspend_a.items[psusp].load(.monotonic)); // count balanced
        // now schedulable + re-enqueued → a second drive completes it.
        const run2 = try eng.driveThreads(&vm, 6, 100_000, 60 * std.time.ns_per_s);
        try std.testing.expect(run2.grants < 100_000);
        try std.testing.expectEqual(ia.Status.halted, vm.procs.items[psusp].machine.status);
    }
}

test "LAW e48-smp-s3 DEFERRED-WAKE protocol: a signal to an OWNED suspended proc sets pending_wake WITHOUT touching its status (no cross-thread status write); the release applies the wake exactly-once" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const rx = try vm.spawn(idle, 0, null);
    const tx = try vm.spawn(idle, 0, null);
    vm.procs.items[rx].machine.status = .suspended; // blocked in receive
    // gap-b-5a: ownership + the deferred-wake flag now live in the `L_c`-domain
    // per-pid arrays (`Vm.owned[pid]`/`Vm.pending_wake_a[pid]`), NOT on `Process`.
    vm.owned.items[rx].store(3, .monotonic); // a peer worker is running it (simulated)

    // signal while OWNED: status untouched (the torn-write hazard), wake deferred.
    try vm.signal(tx, rx, .link_req);
    try std.testing.expectEqual(ia.Status.suspended, vm.procs.items[rx].machine.status);
    try std.testing.expect(vm.pending_wake_a.items[rx].load(.monotonic));

    // the release epilogue's exact semantics: apply-once, then idempotent-clear.
    const p = vm.procs.items[rx];
    if (vm.pending_wake_a.items[rx].load(.monotonic)) {
        vm.pending_wake_a.items[rx].store(false, .monotonic);
        vm.applyWake(p);
    }
    vm.owned.items[rx].store(NO_OWNER, .monotonic);
    try std.testing.expectEqual(ia.Status.running, p.machine.status); // woken at release
    try std.testing.expect(!vm.pending_wake_a.items[rx].load(.monotonic));

    // an UN-owned suspended proc wakes IMMEDIATELY (the pre-S3 receive-wake).
    p.machine.status = .suspended;
    try vm.signal(tx, rx, .link_req);
    try std.testing.expectEqual(ia.Status.running, p.machine.status);
}

test "LAW SC-N9-2 stale enqueue observation cannot publish queue membership after a popper claims ownership" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const pid = try vm.spawn(idle, 0, null);

    // Normalize the boot-time membership, then materialize the exact losing
    // interleaving: enqueueDirect already observed NO_OWNER; before its
    // continuation runs, a popper claims the pid and clears the old dedup bit.
    vm.ready.clearRetainingCapacity();
    vm.queued.items[pid].store(false, .seq_cst);
    vm.runnable_total.store(0, .seq_cst);
    vm.n_sched_live.store(1, .release);
    vm.owned.items[pid].store(0, .seq_cst);

    try vm.enqueueAfterUnownedObservation(pid, 1);

    // Queue membership and ownership are one conservation domain: stale
    // evidence may not append a now-owned pid or publish its dedup bit.
    try std.testing.expectEqual(@as(usize, 0), vm.run_qs[0].items.len);
    try std.testing.expect(!vm.queued.items[pid].load(.seq_cst));
    try std.testing.expectEqual(@as(usize, 0), vm.runnable_total.load(.seq_cst));
}

test "LAW e48-smp-s5 REAL-SCALE WORK CONSERVATION: the spawn_storm_real workload COMPLETES at n=1,2,4 with the SAME total work (denotation-invariant across real thread counts) — the measurement's precondition" {
    // The throughput CURVE is a measurement (cli.scale spawn_storm_real / the
    // harness scale pillar); THIS law pins what makes the measurement honest:
    // every storm completes within its work budget at every thread count, and
    // the completed work is the same — so ops_per_s differences are TIME, not
    // work leakage. (Measured 2026-07-25 on vm-1: s(1)=1.00 s(2)=1.99-2.05
    // s(4)=3.67-3.90 — recorded in the slice notes; the number itself is not
    // a law, machines differ.)
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var grants: [3]usize = undefined;
    const counts = [_]u32{ 1, 2, 4 };
    for (counts, 0..) |n, i| {
        const storm = try scaleWorkReal(gpa, &atoms, n, 24);
        try std.testing.expect(storm.completed); // every worker halted (work-bounded)
        grants[i] = storm.grants;
    }
    // Work conservation: same worker count + full-body fuel ⇒ the grant count
    // is the worker count at every n (one grant per worker, no re-grant churn).
    try std.testing.expectEqual(grants[0], grants[1]);
    try std.testing.expectEqual(grants[1], grants[2]);
}

test "LAW e48 hibernate/0: GC-minimize (heap SHRINKS) + suspend-until-signal with control resuming AFTER the call (x0=ok); queued mail/signals mean NO sleep (never dozing over work)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const p = try vm.spawn(idle, 0, null);
    const peer = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p].machine;

    // garbage, then the trap: the collect happened (heap shrank) and the
    // process SLEEPS (no mail) with x0 = ok staged for the resume.
    var k: usize = 0;
    while (k < 1500) : (k += 1) _ = try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.int(&m.ctx, @intCast(k)), FinalTerms.int(&m.ctx, 3) });
    const before = m.ctx.words.items.len;
    m.pending = .hibernate_wait;
    try vm.interpret(p);
    try std.testing.expect(m.ctx.words.items.len < before); // memory MINIMIZED (real collect)
    try std.testing.expectEqual(ia.Status.suspended, m.status); // hibernating
    try std.testing.expect(FinalTerms.repIsAtom(m.regs[0])); // ok staged in x0

    // a signal WAKES it (the standard receive-wake) — control resumes.
    try vm.signal(peer, p, .link_req);
    try std.testing.expectEqual(ia.Status.running, m.status);

    // queued mail ⇒ hibernate does NOT sleep (it has work).
    try m.mbox.deliver(peer, FinalTerms.int(&m.ctx, 5));
    m.pending = .hibernate_wait;
    try vm.interpret(p);
    try std.testing.expectEqual(ia.Status.running, m.status);
}

test "LAW e49-real-ports-io os:cmd/1 DIFFERENTIAL: stdout-to-EOF charlists byte-equal the pinned oracle (echo/printf/multiline/empty); badarg totality; bounded (a silent child is an error, never a hang)" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const p = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p].machine;

    const H = struct {
        fn chars(mm: *ia.Machine, s: []const u8) !FinalTerms.Term {
            var l = FinalTerms.nil(&mm.ctx);
            var i = s.len;
            while (i > 0) {
                i -= 1;
                l = try FinalTerms.cons(&mm.ctx, FinalTerms.int(&mm.ctx, s[i]), l);
            }
            return l;
        }
        fn collect(mm: *ia.Machine, gp: std.mem.Allocator, t: FinalTerms.Term, out: *std.ArrayList(u8)) !void {
            var cur = t;
            while (FinalTerms.kindOf(&mm.ctx, cur) == .cons) {
                try out.append(gp, @intCast(FinalTerms.smallValOf(FinalTerms.listHead(&mm.ctx, cur))));
                cur = FinalTerms.listTail(&mm.ctx, cur);
            }
        }
        fn run(vmm: *Vm, pid: Pid, mm: *ia.Machine, gp: std.mem.Allocator, cmd: []const u8, want: []const u8) !void {
            mm.pending = .{ .os_cmd = .{ .cmd = try chars(mm, cmd) } };
            try vmm.interpret(pid);
            var got: std.ArrayList(u8) = .empty;
            defer got.deinit(gp);
            try collect(mm, gp, mm.regs[0], &got);
            try std.testing.expectEqualStrings(want, got.items);
        }
    };

    // every `want` is the EXACT byte string the pinned oracle's os:cmd returned.
    try H.run(&vm, p, m, gpa, "echo hi", "hi\n");
    try H.run(&vm, p, m, gpa, "printf abc", "abc");
    try H.run(&vm, p, m, gpa, "echo a; echo b", "a\nb\n");
    try H.run(&vm, p, m, gpa, "true", ""); // empty output → []
    // badarg totality: an empty command
    m.pending = .{ .os_cmd = .{ .cmd = FinalTerms.nil(&m.ctx) } };
    try vm.interpret(p);
    try std.testing.expect(FinalTerms.repIsAtom(m.regs[0])); // badarg atom staged
}

test "LAW e49-wire-real-file-io: file:write_file then read_file ROUND-TRIPS bytes over the REAL prim_file fd seam ({ok,Bin}); a missing path is {error,enoent}; no fs seam ⇒ closed-world {error,enoent}/{error,eacces}" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const H = struct {
        fn chars(m: *ia.Machine, s: []const u8) !FinalTerms.Term {
            var l = FinalTerms.nil(&m.ctx);
            var i = s.len;
            while (i > 0) {
                i -= 1;
                l = try FinalTerms.cons(&m.ctx, FinalTerms.int(&m.ctx, s[i]), l);
            }
            return l;
        }
        fn isTag(m: *ia.Machine, t: FinalTerms.Term, tag: []const u8) bool {
            return FinalTerms.kindOf(&m.ctx, t) == .tuple and FinalTerms.tupleArity(&m.ctx, t) >= 1 and
                FinalTerms.repIsAtom(FinalTerms.tupleElem(&m.ctx, t, 0)) and
                std.mem.eql(u8, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, t, 0))), tag);
        }
    };

    // WITH the fs seam: write then read the SAME bytes off a real fd.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        vm.fs = .{ .io = io, .root = tmp.dir };
        const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
        const p = try vm.spawn(idle, 0, null);
        const m = &vm.procs.items[p].machine;
        const path = try H.chars(m, "rt.txt");
        const payload = try FinalTerms.binary(&m.ctx, "zigvm bytes \x00\xfe\xff");

        m.pending = .{ .file_write = .{ .path = path, .data = payload } };
        try vm.interpret(p);
        try std.testing.expect(FinalTerms.repIsAtom(m.regs[0]) and std.mem.eql(u8, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(m.regs[0])), "ok"));

        m.pending = .{ .file_read = .{ .path = path } };
        try vm.interpret(p);
        try std.testing.expect(H.isTag(m, m.regs[0], "ok")); // {ok, Bin}
        const got = FinalTerms.tupleElem(&m.ctx, m.regs[0], 1);
        try std.testing.expect(FinalTerms.repIsBinary(&m.ctx, got));
        try std.testing.expectEqualStrings("zigvm bytes \x00\xfe\xff", FinalTerms.binBytes(&m.ctx, got));

        // a MISSING path is {error, enoent}.
        m.pending = .{ .file_read = .{ .path = try H.chars(m, "nope.txt") } };
        try vm.interpret(p);
        try std.testing.expect(H.isTag(m, m.regs[0], "error"));
        try std.testing.expect(std.mem.eql(u8, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, m.regs[0], 1))), "enoent"));
    }
    // WITHOUT the fs seam: closed-world — read is {error,enoent}, write {error,eacces}.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
        const p = try vm.spawn(idle, 0, null);
        const m = &vm.procs.items[p].machine;
        m.pending = .{ .file_read = .{ .path = try H.chars(m, "x") } };
        try vm.interpret(p);
        try std.testing.expect(H.isTag(m, m.regs[0], "error"));
    }
}

test "LAW gap-real-file-io: file:list_dir/1 SET-EQ over the real dir + file:read_file_info/1 size/type/access byte-EQ; missing → {error,enoent}; no fs seam ⇒ {error,enoent}" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const H = struct {
        fn chars(m: *ia.Machine, s: []const u8) !FinalTerms.Term {
            var l = FinalTerms.nil(&m.ctx);
            var i = s.len;
            while (i > 0) {
                i -= 1;
                l = try FinalTerms.cons(&m.ctx, FinalTerms.int(&m.ctx, s[i]), l);
            }
            return l;
        }
        fn tag(m: *ia.Machine, t: FinalTerms.Term, want: []const u8) bool {
            return FinalTerms.kindOf(&m.ctx, t) == .tuple and FinalTerms.tupleArity(&m.ctx, t) >= 1 and
                FinalTerms.repIsAtom(FinalTerms.tupleElem(&m.ctx, t, 0)) and
                std.mem.eql(u8, m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, t, 0))), want);
        }
        // Read a charlist Name back into a byte buffer (returns the length).
        fn nameBytes(m: *ia.Machine, list: FinalTerms.Term, buf: []u8) usize {
            var cur = list;
            var n: usize = 0;
            while (FinalTerms.kindOf(&m.ctx, cur) == .cons and n < buf.len) {
                buf[n] = @intCast(FinalTerms.smallValOf(FinalTerms.listHead(&m.ctx, cur)));
                n += 1;
                cur = FinalTerms.listTail(&m.ctx, cur);
            }
            return n;
        }
    };

    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    vm.fs = .{ .io = io, .root = tmp.dir };
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const p = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p].machine;

    // Populate the real scratch dir via file:write_file, then list_dir it.
    const want = [_][]const u8{ "aaa", "bbb", "ccc" };
    for (want) |nm| {
        m.pending = .{ .file_write = .{ .path = try H.chars(m, nm), .data = try FinalTerms.binary(&m.ctx, "payload!!") } };
        try vm.interpret(p);
    }
    m.pending = .{ .file_list_dir = .{ .path = try H.chars(m, ".") } };
    try vm.interpret(p);
    try std.testing.expect(H.tag(m, m.regs[0], "ok"));
    // Collect the returned names; assert SET-EQUALITY with `want`.
    var seen: usize = 0;
    var cur = FinalTerms.tupleElem(&m.ctx, m.regs[0], 1);
    while (FinalTerms.kindOf(&m.ctx, cur) == .cons) : (cur = FinalTerms.listTail(&m.ctx, cur)) {
        var nb: [64]u8 = undefined;
        const nlen = H.nameBytes(m, FinalTerms.listHead(&m.ctx, cur), &nb);
        var matched = false;
        for (want) |w| if (std.mem.eql(u8, w, nb[0..nlen])) {
            matched = true;
        };
        try std.testing.expect(matched);
        seen += 1;
    }
    try std.testing.expectEqual(want.len, seen); // exactly the real entries (no drops)

    // read_file_info on "aaa" (9 bytes written) → {ok, #file_info{}} with
    // size==9, type==regular, access==read_write (byte-EQ fields).
    m.pending = .{ .file_read_file_info = .{ .path = try H.chars(m, "aaa") } };
    try vm.interpret(p);
    try std.testing.expect(H.tag(m, m.regs[0], "ok"));
    const rec = FinalTerms.tupleElem(&m.ctx, m.regs[0], 1);
    try std.testing.expectEqual(@as(u32, 14), FinalTerms.tupleArity(&m.ctx, rec));
    try std.testing.expectEqualStrings("file_info", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, rec, 0))));
    try std.testing.expectEqual(@as(i64, 9), FinalTerms.smallValOf(FinalTerms.tupleElem(&m.ctx, rec, 1))); // size
    try std.testing.expectEqualStrings("regular", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, rec, 2))));
    try std.testing.expectEqualStrings("read_write", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, rec, 3))));

    // "." stats as a directory.
    m.pending = .{ .file_read_file_info = .{ .path = try H.chars(m, ".") } };
    try vm.interpret(p);
    const drec = FinalTerms.tupleElem(&m.ctx, m.regs[0], 1);
    try std.testing.expectEqualStrings("directory", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, drec, 2))));

    // Missing path → {error, enoent} for both surfaces (byte-EQ error atom).
    m.pending = .{ .file_read_file_info = .{ .path = try H.chars(m, "nope") } };
    try vm.interpret(p);
    try std.testing.expect(H.tag(m, m.regs[0], "error"));
    try std.testing.expectEqualStrings("enoent", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, m.regs[0], 1))));
    m.pending = .{ .file_list_dir = .{ .path = try H.chars(m, "no_dir") } };
    try vm.interpret(p);
    try std.testing.expect(H.tag(m, m.regs[0], "error"));
    try std.testing.expectEqualStrings("enoent", m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(FinalTerms.tupleElem(&m.ctx, m.regs[0], 1))));

    // No fs seam ⇒ closed-world {error,enoent}.
    var vm2 = try Vm.init(gpa, &atoms);
    defer vm2.deinit();
    const p2 = try vm2.spawn(idle, 0, null);
    const m2 = &vm2.procs.items[p2].machine;
    m2.pending = .{ .file_list_dir = .{ .path = try H.chars(m2, ".") } };
    try vm2.interpret(p2);
    try std.testing.expect(H.tag(m2, m2.regs[0], "error"));
}

test "LAW e50-tracing erlang:trace/3: a TRACED proc's receive delivers {trace,Pid,receive,Msg} and its send delivers {trace,From,send,Msg,To} to the TRACER; how=false clears; an untraced proc emits nothing; matched-count is 1" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const tracer = try vm.spawn(idle, 0, null);
    const subject = try vm.spawn(idle, 0, null);
    const other = try vm.spawn(idle, 0, null);
    const tm = &vm.procs.items[tracer].machine;
    const sm = &vm.procs.items[subject].machine;

    const H = struct {
        fn atomName(m: *ia.Machine, t: FinalTerms.Term) []const u8 {
            return if (FinalTerms.repIsAtom(t)) m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(t)) else "";
        }
        // pop the tracer's next mailbox message
        fn pop(vmm: *Vm, trc: Pid) ?FinalTerms.Term {
            vmm.drainSignals(trc) catch {};
            const p = vmm.procs.items[trc];
            const mm = &p.machine;
            const r = (mm.mbox.peekAt(0) catch return null) orelse return null;
            mm.mbox.removeAt(0) catch {};
            return r.payload;
        }
    };

    // trace subject for [send, 'receive'] — matched count 1, tracer = the caller.
    var flags = FinalTerms.nil(&sm.ctx);
    flags = try FinalTerms.cons(&sm.ctx, FinalTerms.atom(&sm.ctx, try atoms.intern("receive")), flags);
    flags = try FinalTerms.cons(&sm.ctx, FinalTerms.atom(&sm.ctx, try atoms.intern("send")), flags);
    const cnt = try vm.doTraceSet(tracer, tm, try FinalTerms.pid(&tm.ctx, subject, 0), true, try FinalTerms.gcCopy(&tm.ctx, &sm.ctx, flags));
    try std.testing.expectEqual(@as(i64, 1), FinalTerms.smallValOf(cnt));
    try std.testing.expect(vm.procs.items[subject].trace_send and vm.procs.items[subject].trace_recv);
    try std.testing.expectEqual(tracer, vm.procs.items[subject].tracer.?);

    // RECEIVE: deliver a message TO subject → the tracer gets {trace,Pid,receive,Msg}.
    // (route it through the send trap so drainSignals fires.)
    const om = &vm.procs.items[other].machine;
    om.pending = .{ .send_to = .{ .pid = try FinalTerms.pid(&om.ctx, subject, 0), .msg = FinalTerms.int(&om.ctx, 42) } };
    try vm.interpret(other);
    try vm.drainSignals(subject);
    const rt = H.pop(&vm, tracer) orelse return error.TestUnexpectedResult;
    try std.testing.expect(FinalTerms.kindOf(&tm.ctx, rt) == .tuple and FinalTerms.tupleArity(&tm.ctx, rt) == 4);
    try std.testing.expect(std.mem.eql(u8, H.atomName(tm, FinalTerms.tupleElem(&tm.ctx, rt, 0)), "trace"));
    try std.testing.expect(std.mem.eql(u8, H.atomName(tm, FinalTerms.tupleElem(&tm.ctx, rt, 2)), "receive"));
    try std.testing.expectEqual(@as(i64, 42), FinalTerms.smallValOf(FinalTerms.tupleElem(&tm.ctx, rt, 3)));

    // SEND: subject sends → the tracer gets {trace,From,send,Msg,To} (5-tuple).
    sm.pending = .{ .send_to = .{ .pid = try FinalTerms.pid(&sm.ctx, other, 0), .msg = FinalTerms.int(&sm.ctx, 7) } };
    try vm.interpret(subject);
    const st = H.pop(&vm, tracer) orelse return error.TestUnexpectedResult;
    try std.testing.expect(FinalTerms.tupleArity(&tm.ctx, st) == 5);
    try std.testing.expect(std.mem.eql(u8, H.atomName(tm, FinalTerms.tupleElem(&tm.ctx, st, 2)), "send"));
    try std.testing.expectEqual(@as(i64, 7), FinalTerms.smallValOf(FinalTerms.tupleElem(&tm.ctx, st, 3)));
    try std.testing.expect(FinalTerms.repIsPid(&tm.ctx, FinalTerms.tupleElem(&tm.ctx, st, 4))); // To

    // CLEAR (how=false, all flags) → tracer detached; a later receive emits nothing.
    const off = try vm.doTraceSet(tracer, tm, try FinalTerms.pid(&tm.ctx, subject, 0), false, try FinalTerms.gcCopy(&tm.ctx, &sm.ctx, flags));
    try std.testing.expectEqual(@as(i64, 1), FinalTerms.smallValOf(off));
    try std.testing.expect(vm.procs.items[subject].tracer == null);
    om.pending = .{ .send_to = .{ .pid = try FinalTerms.pid(&om.ctx, subject, 0), .msg = FinalTerms.int(&om.ctx, 99) } };
    try vm.interpret(other);
    try vm.drainSignals(subject);
    try std.testing.expect(H.pop(&vm, tracer) == null); // no trace after clear
}

test "LAW gap-tracing-e7 erlang:trace_pattern/3: a call-traced proc calling a PATTERN-matched export delivers {trace,Pid,call,{M,F,Args}} to the tracer (byte-EQ shape vs the live erl vector); the matched COUNT is right; a cleared pattern (false) stops the call event" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const modA = try atoms.intern("tp_mod");
    const target = try atoms.intern("target");
    const other = try atoms.intern("other");
    const exports = [_]ia.Export{
        .{ .module = modA, .func = target, .arity = 1, .pc = 2 },
        .{ .module = modA, .func = other, .arity = 0, .pc = 3 },
    };
    // 0: call tp_mod:target/1 (push ret); 1: halt x0; 2: target/1 body (ret);
    // 3: other/0 body (ret, unreachable at run time — an export row for the count).
    const prog: ia.Program = &.{
        .{ .call_ext_code = .{ .module = modA, .func = target, .arity = 1, .push_ret = true } },
        .{ .halt = .{ .src = .{ .x = 0 } } },
        .ret,
        .ret,
    };
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};

    const H = struct {
        fn atomName(m: *ia.Machine, t: FinalTerms.Term) []const u8 {
            return if (FinalTerms.repIsAtom(t)) m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(t)) else "";
        }
        fn pop(vmm: *Vm, trc: Pid) ?FinalTerms.Term {
            vmm.drainSignals(trc) catch {};
            const p = vmm.procs.items[trc];
            const mm = &p.machine;
            const r = (mm.mbox.peekAt(0) catch return null) orelse return null;
            mm.mbox.removeAt(0) catch {};
            return r.payload;
        }
        // {M,F,A} term on the CONTROLLER's ctx (A a small; a wildcard atom for '_').
        fn mfa(cm: *ia.Machine, mo: ta.AtomIdx, fu: ta.AtomIdx, ar: i64) !FinalTerms.Term {
            return FinalTerms.tuple(&cm.ctx, &.{
                FinalTerms.atom(&cm.ctx, mo), FinalTerms.atom(&cm.ctx, fu), FinalTerms.int(&cm.ctx, ar),
            });
        }
        // erlang:trace_pattern(MFA, Spec, [local]) run on the (alive) CONTROLLER
        // machine `cm` + committed via its trap → the matched count.
        fn setPattern(vmm: *Vm, cm: *ia.Machine, cpid: Pid, mfa_t: FinalTerms.Term, enable: bool) !i64 {
            const trace_bifs = @import("bifs/trace_bifs.zig");
            const spec_t = FinalTerms.atom(&cm.ctx, if (enable) cm.bool_true else cm.bool_false);
            const flags = try FinalTerms.cons(&cm.ctx, FinalTerms.atom(&cm.ctx, try cm.ctx.atoms.intern("local")), FinalTerms.nil(&cm.ctx));
            _ = try trace_bifs.trace_pattern_3(cm, &.{ mfa_t, spec_t, flags });
            try vmm.interpret(cpid); // commit to the Vm + write count → x0
            return FinalTerms.smallValOf(cm.regs[0]);
        }
    };

    // Spawn EVERYTHING up front so no later spawn reallocates `procs` and dangles
    // the machine pointers. The tracer is the always-alive CONTROLLER for the
    // pattern ops (it holds the export table — zigvm's per-process code image is
    // the module table a node shares); the two subjects run the call.
    const tracer = try vm.spawn(idle, 0, null);
    const subject = try vm.spawn(prog, 0, null);
    const subject2 = try vm.spawn(prog, 0, null);
    const tm = &vm.procs.items[tracer].machine;
    const sm = &vm.procs.items[subject].machine;
    const sm2 = &vm.procs.items[subject2].machine;
    tm.exports = &exports;
    sm.exports = &exports;
    sm2.exports = &exports;

    // matched COUNT: exact {tp_mod,target,1} → 1; wildcard {tp_mod,'_','_'} → 2.
    const wild = try atoms.intern("_");
    const one = try H.setPattern(&vm, tm, tracer, try H.mfa(tm, modA, target, 1), true);
    try std.testing.expectEqual(@as(i64, 1), one);
    // wildcard on func AND arity: {tp_mod,'_','_'} counts both exports.
    const wmfa = try FinalTerms.tuple(&tm.ctx, &.{ FinalTerms.atom(&tm.ctx, modA), FinalTerms.atom(&tm.ctx, wild), FinalTerms.atom(&tm.ctx, wild) });
    try std.testing.expectEqual(@as(i64, 2), try H.setPattern(&vm, tm, tracer, wmfa, true));
    // keep only the exact {tp_mod,target,1} breakpoint enabled for the run below
    // (remove the wildcard so exactly one call event fires).
    _ = try H.setPattern(&vm, tm, tracer, wmfa, false);

    // trace the subject with [call]; the tracer is the caller.
    var cflags = FinalTerms.nil(&tm.ctx);
    cflags = try FinalTerms.cons(&tm.ctx, FinalTerms.atom(&tm.ctx, try atoms.intern("call")), cflags);
    _ = try vm.doTraceSet(tracer, tm, try FinalTerms.pid(&tm.ctx, subject, 0), true, cflags);
    try std.testing.expect(vm.procs.items[subject].machine.trace_call);
    try std.testing.expectEqual(tracer, vm.procs.items[subject].tracer.?);

    // run the subject: the call to target/1 fires a call trace, then completes.
    sm.regs[0] = FinalTerms.int(&sm.ctx, 41);
    try vm.grant(subject, 50);
    try std.testing.expectEqual(ia.Status.halted, sm.status);
    try std.testing.expectEqual(@as(i64, 41), FinalTerms.smallValOf(sm.result)); // callee returned the arg

    // BYTE-EQ SHAPE vs the live-erl vector {trace,<pid>,call,{tp_mod,target,[41]}}:
    // the tag atoms + MFA atoms + arg list are the version-stable projection (the
    // pid is repr-coupled, excluded exactly as the send/receive tracing law does).
    const ct = H.pop(&vm, tracer) orelse return error.TestUnexpectedResult;
    try std.testing.expect(FinalTerms.kindOf(&tm.ctx, ct) == .tuple and FinalTerms.tupleArity(&tm.ctx, ct) == 4);
    try std.testing.expect(std.mem.eql(u8, H.atomName(tm, FinalTerms.tupleElem(&tm.ctx, ct, 0)), "trace"));
    try std.testing.expect(FinalTerms.repIsPid(&tm.ctx, FinalTerms.tupleElem(&tm.ctx, ct, 1)));
    try std.testing.expect(std.mem.eql(u8, H.atomName(tm, FinalTerms.tupleElem(&tm.ctx, ct, 2)), "call"));
    const mfa_t = FinalTerms.tupleElem(&tm.ctx, ct, 3);
    try std.testing.expect(FinalTerms.tupleArity(&tm.ctx, mfa_t) == 3);
    try std.testing.expect(std.mem.eql(u8, H.atomName(tm, FinalTerms.tupleElem(&tm.ctx, mfa_t, 0)), "tp_mod"));
    try std.testing.expect(std.mem.eql(u8, H.atomName(tm, FinalTerms.tupleElem(&tm.ctx, mfa_t, 1)), "target"));
    const arglist = FinalTerms.tupleElem(&tm.ctx, mfa_t, 2);
    try std.testing.expect(FinalTerms.kindOf(&tm.ctx, arglist) == .cons);
    try std.testing.expectEqual(@as(i64, 41), FinalTerms.smallValOf(FinalTerms.listHead(&tm.ctx, arglist)));
    try std.testing.expect(FinalTerms.kindOf(&tm.ctx, FinalTerms.listTail(&tm.ctx, arglist)) == .nil); // [41] exactly
    try std.testing.expect(H.pop(&vm, tracer) == null); // exactly ONE call event

    // CLEAR: trace_pattern(false) removes the breakpoint (count still 1); the fresh
    // call-traced subject2 then emits NO call event.
    const cleared = try H.setPattern(&vm, tm, tracer, try H.mfa(tm, modA, target, 1), false);
    try std.testing.expectEqual(@as(i64, 1), cleared);
    var cflags2 = FinalTerms.nil(&tm.ctx);
    cflags2 = try FinalTerms.cons(&tm.ctx, FinalTerms.atom(&tm.ctx, try atoms.intern("call")), cflags2);
    _ = try vm.doTraceSet(tracer, tm, try FinalTerms.pid(&tm.ctx, subject2, 0), true, cflags2);
    sm2.regs[0] = FinalTerms.int(&sm2.ctx, 7);
    try vm.grant(subject2, 50);
    try std.testing.expectEqual(ia.Status.halted, sm2.status);
    try std.testing.expect(H.pop(&vm, tracer) == null); // MUTANT m1: fire-after-clear reddens here
}

test "LAW gap-tracing-firepath: an installed trace MATCH SPEC runs at the call-trace fire site — a failing guard SUPPRESSES the event, {message,E} shapes the 5-tuple {trace,_,call,MFA,E}, {message,false} suppresses, an empty body delivers the bare 4-tuple" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();

    const modA = try atoms.intern("tp_mod");
    const target = try atoms.intern("target");
    const exports = [_]ia.Export{.{ .module = modA, .func = target, .arity = 1, .pc = 2 }};
    const prog: ia.Program = &.{
        .{ .call_ext_code = .{ .module = modA, .func = target, .arity = 1, .push_ret = true } },
        .{ .halt = .{ .src = .{ .x = 0 } } },
        .ret,
    };
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};

    const H = struct {
        fn pop(vmm: *Vm, trc: Pid) ?FinalTerms.Term {
            vmm.drainSignals(trc) catch {};
            const mm = &vmm.procs.items[trc].machine;
            const r = (mm.mbox.peekAt(0) catch return null) orelse return null;
            mm.mbox.removeAt(0) catch {};
            return r.payload;
        }
        // install a match-spec LIST on {tp_mod,target,1} (replacing any prior),
        // committed via the controller's trap.
        fn setSpec(vmm: *Vm, cm: *ia.Machine, cpid: Pid, spec_list: FinalTerms.Term) !void {
            const trace_bifs = @import("bifs/trace_bifs.zig");
            const mfa = try FinalTerms.tuple(&cm.ctx, &.{ FinalTerms.atom(&cm.ctx, try cm.ctx.atoms.intern("tp_mod")), FinalTerms.atom(&cm.ctx, try cm.ctx.atoms.intern("target")), FinalTerms.int(&cm.ctx, 1) });
            const flags = try FinalTerms.cons(&cm.ctx, FinalTerms.atom(&cm.ctx, try cm.ctx.atoms.intern("local")), FinalTerms.nil(&cm.ctx));
            _ = try trace_bifs.trace_pattern_3(cm, &.{ mfa, spec_list, flags });
            try vmm.interpret(cpid);
        }
        // a one-clause trace spec [{Head,Guards,Body}] on the controller ctx.
        fn clause(cm: *ia.Machine, head: FinalTerms.Term, guards: FinalTerms.Term, body: FinalTerms.Term) !FinalTerms.Term {
            const c = try FinalTerms.tuple(&cm.ctx, &.{ head, guards, body });
            return FinalTerms.cons(&cm.ctx, c, FinalTerms.nil(&cm.ctx));
        }
        fn v1(cm: *ia.Machine) !FinalTerms.Term {
            return FinalTerms.atom(&cm.ctx, try cm.ctx.atoms.intern("$1"));
        }
    };

    const tracer = try vm.spawn(idle, 0, null);
    const subj = [_]Pid{ try vm.spawn(prog, 0, null), try vm.spawn(prog, 0, null), try vm.spawn(prog, 0, null), try vm.spawn(prog, 0, null) };
    const tm = &vm.procs.items[tracer].machine;
    tm.exports = &exports;
    for (subj) |s| {
        vm.procs.items[s].machine.exports = &exports;
        var cflags = FinalTerms.nil(&tm.ctx);
        cflags = try FinalTerms.cons(&tm.ctx, FinalTerms.atom(&tm.ctx, try atoms.intern("call")), cflags);
        _ = try vm.doTraceSet(tracer, tm, try FinalTerms.pid(&tm.ctx, s, 0), true, cflags);
    }

    const nil_ = FinalTerms.nil(&tm.ctx);
    const head1 = try FinalTerms.cons(&tm.ctx, try H.v1(tm), nil_); // ['$1']

    // CASE 1 — {message,{'*','$1',2}} on arg 41 → 5-tuple, message = 82.
    {
        const msgE = try FinalTerms.tuple(&tm.ctx, &.{ FinalTerms.atom(&tm.ctx, try atoms.intern("*")), try H.v1(tm), FinalTerms.int(&tm.ctx, 2) });
        const body = try FinalTerms.cons(&tm.ctx, try FinalTerms.tuple(&tm.ctx, &.{ FinalTerms.atom(&tm.ctx, try atoms.intern("message")), msgE }), nil_);
        try H.setSpec(&vm, tm, tracer, try H.clause(tm, head1, nil_, body));
        const sm = &vm.procs.items[subj[0]].machine;
        sm.regs[0] = FinalTerms.int(&sm.ctx, 41);
        try vm.grant(subj[0], 50);
        const ct = H.pop(&vm, tracer) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(usize, 5), FinalTerms.tupleArity(&tm.ctx, ct)); // {trace,Pid,call,MFA,Msg}
        try std.testing.expectEqual(@as(i64, 82), FinalTerms.smallValOf(FinalTerms.tupleElem(&tm.ctx, ct, 4)));
    }
    // CASE 2 — guard {'>','$1',100} FAILS on 41 → SUPPRESS (no message).
    {
        const g = try FinalTerms.cons(&tm.ctx, try FinalTerms.tuple(&tm.ctx, &.{ FinalTerms.atom(&tm.ctx, try atoms.intern(">")), try H.v1(tm), FinalTerms.int(&tm.ctx, 100) }), nil_);
        try H.setSpec(&vm, tm, tracer, try H.clause(tm, head1, g, nil_));
        const sm = &vm.procs.items[subj[1]].machine;
        sm.regs[0] = FinalTerms.int(&sm.ctx, 41);
        try vm.grant(subj[1], 50);
        try std.testing.expect(H.pop(&vm, tracer) == null); // suppressed
    }
    // CASE 3 — guard {'<','$1',100} HOLDS, empty body → bare 4-tuple.
    {
        const g = try FinalTerms.cons(&tm.ctx, try FinalTerms.tuple(&tm.ctx, &.{ FinalTerms.atom(&tm.ctx, try atoms.intern("<")), try H.v1(tm), FinalTerms.int(&tm.ctx, 100) }), nil_);
        try H.setSpec(&vm, tm, tracer, try H.clause(tm, head1, g, nil_));
        const sm = &vm.procs.items[subj[2]].machine;
        sm.regs[0] = FinalTerms.int(&sm.ctx, 41);
        try vm.grant(subj[2], 50);
        const ct = H.pop(&vm, tracer) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(usize, 4), FinalTerms.tupleArity(&tm.ctx, ct)); // bare 4-tuple
    }
    // CASE 4 — {message,false} → SUPPRESS.
    {
        const body = try FinalTerms.cons(&tm.ctx, try FinalTerms.tuple(&tm.ctx, &.{ FinalTerms.atom(&tm.ctx, try atoms.intern("message")), FinalTerms.atom(&tm.ctx, try atoms.intern("false")) }), nil_);
        try H.setSpec(&vm, tm, tracer, try H.clause(tm, head1, nil_, body));
        const sm = &vm.procs.items[subj[3]].machine;
        sm.regs[0] = FinalTerms.int(&sm.ctx, 41);
        try vm.grant(subj[3], 50);
        try std.testing.expect(H.pop(&vm, tracer) == null); // {message,false} suppresses
    }
}

test "LAW e50-halt erlang:halt/1,2: a non-neg int is the OS exit code (capped 0..255); the atom abort is 134; a STRING captures a crashdump slogan + exit 1; every process is halted so the run ends" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const misc = @import("bifs/misc.zig");

    const H = struct {
        fn run(gp: std.mem.Allocator, at: *AtomTable, status: FinalTerms.Term, wctx: *ia.Machine) !struct { code: u8, slogan: []const u8, halted: bool } {
            var vm = try Vm.init(gp, at);
            const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
            const p = try vm.spawn(idle, 0, null);
            const q = try vm.spawn(idle, 0, null);
            _ = q;
            const m = &vm.procs.items[p].machine;
            const s = try FinalTerms.gcCopy(&m.ctx, &wctx.ctx, status);
            m.pending = .{ .node_halt = .{ .status = s } };
            try vm.interpret(p);
            const code = vm.halt_code.?;
            const slog = try gp.dupe(u8, vm.halt_slogan.items);
            const halted = !vm.procs.items[0].alive and !vm.procs.items[1].alive;
            vm.deinit();
            return .{ .code = code, .slogan = slog, .halted = halted };
        }
    };
    var wm = try ia.Machine.init(gpa, &atoms);
    defer wm.deinit();

    // halt(7) → exit 7.
    const r7 = try H.run(gpa, &atoms, FinalTerms.int(&wm.ctx, 7), &wm);
    defer gpa.free(r7.slogan);
    try std.testing.expectEqual(@as(u8, 7), r7.code);
    try std.testing.expect(r7.halted);
    // halt(0) → exit 0.
    const r0 = try H.run(gpa, &atoms, FinalTerms.int(&wm.ctx, 0), &wm);
    defer gpa.free(r0.slogan);
    try std.testing.expectEqual(@as(u8, 0), r0.code);
    // halt(300) → capped (300 mod 256 = 44).
    const rc = try H.run(gpa, &atoms, FinalTerms.int(&wm.ctx, 300), &wm);
    defer gpa.free(rc.slogan);
    try std.testing.expectEqual(@as(u8, 44), rc.code);
    // halt(abort) → 134.
    const ra = try H.run(gpa, &atoms, FinalTerms.atom(&wm.ctx, try atoms.intern("abort")), &wm);
    defer gpa.free(ra.slogan);
    try std.testing.expectEqual(@as(u8, 134), ra.code);
    // halt("bye") → slogan captured, exit 1.
    var slg = FinalTerms.nil(&wm.ctx);
    slg = try FinalTerms.cons(&wm.ctx, FinalTerms.int(&wm.ctx, 'e'), slg);
    slg = try FinalTerms.cons(&wm.ctx, FinalTerms.int(&wm.ctx, 'y'), slg);
    slg = try FinalTerms.cons(&wm.ctx, FinalTerms.int(&wm.ctx, 'b'), slg);
    const rs = try H.run(gpa, &atoms, slg, &wm);
    defer gpa.free(rs.slogan);
    try std.testing.expectEqual(@as(u8, 1), rs.code);
    try std.testing.expectEqualStrings("bye", rs.slogan);

    // the BIF itself stages the trap (halt_1).
    var m2 = try ia.Machine.init(gpa, &atoms);
    defer m2.deinit();
    _ = try misc.halt_1(&m2, &.{FinalTerms.int(&m2.ctx, 5)});
    try std.testing.expect(m2.pending != null and m2.pending.? == .node_halt);
}

test "LAW gap-halt-dispatch: a COMPILED erlang:halt/0,1,2 reaches the node_halt handler via resolveLibrary (the wiring the e50-halt handler law didn't cover)" {
    // REGRESSION guard: resolveLibrary(erlang,halt,N) returned NULL — the halt arm
    // was misplaced in `implOf` (reached only for bif.tab `.implemented` rows, which
    // halt is NOT), so a compiled `halt(N)` missed BOTH resolve tables → call_ext_code
    // → `undef` instead of terminating the node (DIVERGENCE 584). The loader lowers a
    // `call_ext` to `call_ext_bif{resolveLibrary(...)}` after `resolve` misses.
    const bdisp = @import("bifs/dispatch.zig");
    // (1) THE WIRING: all three arities resolve on the LIBRARY path; there is no /3.
    try std.testing.expect(bdisp.resolveLibrary("erlang", "halt", 0) != null);
    try std.testing.expect(bdisp.resolveLibrary("erlang", "halt", 1) != null);
    try std.testing.expect(bdisp.resolveLibrary("erlang", "halt", 2) != null);
    try std.testing.expect(bdisp.resolveLibrary("erlang", "halt", 3) == null);

    // (2) THE FULL COMPILED PATH through the RESOLVED fn: resolve → BifFn → node_halt
    // pending → interpret → doNodeHalt → halt_code, on a real spawned process.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const p = try vm.spawn(idle, 0, null);
    const m = &vm.procs.items[p].machine;
    const halt1 = bdisp.resolveLibrary("erlang", "halt", 1).?;
    _ = try halt1(m, &.{FinalTerms.int(&m.ctx, 42)}); // the RESOLVED fn stages the trap
    try std.testing.expect(m.pending != null and m.pending.? == .node_halt);
    try vm.interpret(p); // the Vm routes node_halt → doNodeHalt → halt_code
    try std.testing.expectEqual(@as(u8, 42), vm.halt_code.?);
    try std.testing.expect(!vm.procs.items[p].alive); // the calling process is halted
}

test "LAW gap-halt-argcheck: erlang:halt/1,2 Status CONTRACT byte-EQ vs OTP-30 — accepts int>=0 / abort / a valid Unicode charlist; REJECTS with a CATCHABLE badarg a negative int, a non-abort atom, a binary, a float, a tuple, and an improper / out-of-range-codepoint list (the boundary the argument-validation gap left divergent)" {
    // This LAW is the regression net for gap-halt-argcheck: it exercises EVERY
    // Status class the OTP-30 679f9dbb differential established, so the badarg
    // boundary can never silently regress. `halt_1`/`halt_2` validate the Status
    // BEFORE arming the `node_halt` trap → an invalid Status is `error.Badarg`
    // (a catchable badarg leaving the node alive), a valid one arms the trap.
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const misc = @import("bifs/misc.zig");
    var m = try ia.Machine.init(gpa, &atoms);
    defer m.deinit();
    const chars = struct {
        fn go(mm: *ia.Machine, cs: []const i64) FinalTerms.Term {
            var l = FinalTerms.nil(&mm.ctx);
            var i = cs.len;
            while (i > 0) {
                i -= 1;
                l = FinalTerms.cons(&mm.ctx, FinalTerms.int(&mm.ctx, cs[i]), l) catch unreachable;
            }
            return l;
        }
    }.go;

    // ACCEPTED — halt_1 arms the node_halt trap (no error): the EXACT valid set.
    const accept = [_]FinalTerms.Term{
        FinalTerms.int(&m.ctx, 0),
        FinalTerms.int(&m.ctx, 255),
        FinalTerms.int(&m.ctx, 256), // no upper badarg limit (doNodeHalt caps the code)
        FinalTerms.int(&m.ctx, 1_000_000),
        FinalTerms.atom(&m.ctx, try atoms.intern("abort")),
        FinalTerms.nil(&m.ctx), // "" — the empty string is a valid (empty) slogan
        chars(&m, &.{ 's', 't', 'r' }), // "str"
        chars(&m, &.{0x10FFFF}), // the maximum Unicode codepoint
    };
    for (accept) |s| {
        m.pending = null;
        _ = misc.halt_1(&m, &.{s}) catch return error.TestUnexpectedResult; // must NOT reject
        try std.testing.expect(m.pending != null and m.pending.? == .node_halt); // trap armed
    }

    // REJECTED — halt_1 returns a CATCHABLE badarg and leaves the trap UN-armed.
    const reject = [_]FinalTerms.Term{
        FinalTerms.int(&m.ctx, -1), // a negative integer
        FinalTerms.atom(&m.ctx, try atoms.intern("foo")), // a non-abort atom
        FinalTerms.atom(&m.ctx, try atoms.intern("true")),
        try FinalTerms.binary(&m.ctx, "bin"), // a binary is NOT a slogan (only a charlist is)
        FinalTerms.float(&m.ctx, 1.5), // a float
        try FinalTerms.tuple(&m.ctx, &.{ FinalTerms.int(&m.ctx, 1), FinalTerms.int(&m.ctx, 2) }), // a tuple
        chars(&m, &.{0x110000}), // a codepoint one past the Unicode max
        chars(&m, &.{ 'a', -1 }), // a negative codepoint element
        FinalTerms.cons(&m.ctx, FinalTerms.int(&m.ctx, 65), FinalTerms.int(&m.ctx, 66)) catch unreachable, // improper list [65|66]
    };
    for (reject) |s| {
        m.pending = null;
        try std.testing.expectError(error.Badarg, misc.halt_1(&m, &.{s})); // catchable badarg
        try std.testing.expect(m.pending == null); // NOT armed — the node stays alive
    }

    // halt/2 validates Status IDENTICALLY (a bad Status → badarg regardless of Opts).
    m.pending = null;
    try std.testing.expectError(error.Badarg, misc.halt_2(&m, &.{ FinalTerms.int(&m.ctx, -1), FinalTerms.nil(&m.ctx) }));
    try std.testing.expect(m.pending == null);
    _ = try misc.halt_2(&m, &.{ FinalTerms.int(&m.ctx, 0), FinalTerms.nil(&m.ctx) }); // a valid Status arms it
    try std.testing.expect(m.pending != null and m.pending.? == .node_halt);
}

// LAW e51-smp-soak-eq (E51 T3): the soak carried to SATURATION.
//
// WHAT THE OLD SOAK PROVED, AND WHAT IT DID NOT. 120 reps at n∈{1,2,4} over a
// 6-ring is sustained stability of the engine as CONFIGURED — but n never
// reached SmpEngine.MAX_SCHED (8), and the fixture's [8]Pid array meant the
// runnable set could never exceed the scheduler count either. So the two
// regimes where a parallel scheduler actually differs from a sequential one
// were both outside the soak:
//
//   REGIME A  schedulers > runnable procs. Workers find empty queues, park,
//             and must be woken by another scheduler's push. This is where a
//             LOST WAKEUP lives (FM-SMP-SHARD-DROP) — a proc that is never
//             re-queued simply never runs again.
//   REGIME B  runnable procs >> schedulers. Every per-worker QLock is
//             contended, ownership CAS is live, and stealing runs continuously.
//             This is where a TORN QUEUE or a double-grant lives.
//
// Both now run, at every n up to MAX_SCHED, over 120 reps each.
//
// THE DROP-NET. `checkPerPairOrder` is blind to a pure DROP — a delivery that
// vanishes leaves the surviving order ascending and passes. The net here is the
// DENOTATION: the ring's collector sums a fixed contribution from every worker,
// so a lost message changes the total and the oracle equality reddens. The
// second net is quiescence — EVERY proc must be halted at the end. A lost
// wakeup strands a proc parked forever, which the grant bound alone would not
// necessarily catch on a ring whose collector had already finished.
//
// This is a STABILITY proof of the parallel engine, not a claim of OTP EQ for
// SMP as a whole. {S} stays PARTIAL and measurement-bound (DIVERGENCE 624); the
// scale-efficiency float is deliberately NOT ratcheted here (FM-SMP-CONTENTION-
// BLIND — a threshold on a contended shared host flakes).
//
// Mutants: MUT-SOAK-1 (n capped back below MAX_SCHED → the saturated regimes
// stop being exercised, caught by the coverage assertion), MUT-SOAK-2
// (quiescence check dropped → a stranded parked proc passes).
test "LAW e51-smp-soak-eq: EQ-grade stability under SATURATION — 120 reps at n∈{1,2,4,8}=MAX_SCHED across BOTH regimes (schedulers>procs and procs>>schedulers), every run leak-free, work-bounded, quiescent, denoting the oracle EXACTLY with the sacred per-pair order" {
    const gpa = std.testing.allocator; // the JUDGE: any leak/UAF across the soak fails
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const max_grants: usize = 400_000;
    const counts = [_]u32{ 1, 2, 4, SmpEngine.MAX_SCHED };
    // COVERAGE, asserted rather than assumed: the soak must actually reach full
    // scheduler width. A future edit that trims the ladder makes this fail
    // instead of quietly shrinking what "soak" means.
    comptime {
        var saw_max = false;
        for (counts) |c| {
            if (c == SmpEngine.MAX_SCHED) saw_max = true;
        }
        if (!saw_max) @compileError("e51-smp-soak-eq must drive n = MAX_SCHED");
    }
    // REGIME A: 6 workers — at n=8 the schedulers outnumber the runnable set.
    // REGIME B: 32 workers — 4x MAX_SCHED, so every queue stays contended.
    inline for ([_]u32{ 6, 32 }) |ring| {
        comptime {
            if (ring > MAX_RING) @compileError("ring exceeds MAX_RING");
        }
        var rr = try runRing(gpa, &atoms, .round_robin, ring);
        defer rr.events.deinit(gpa);
        const oracle = rr.total;
        var rep: usize = 0;
        while (rep < 120) : (rep += 1) {
            const n = counts[rep % counts.len];
            var vm = try Vm.init(gpa, &atoms);
            defer vm.deinit();
            const collector = try seedRing(&vm, ring);
            const eng = SmpEngine{
                .n_sched = n,
                .seed = 0x50AC +% @as(u64, rep) *% 2654435761 +% @as(u64, ring) *% 0x9E3779B1,
            };
            const run = try eng.driveThreads(&vm, ring + 1, max_grants, 60 * std.time.ns_per_s);
            try std.testing.expect(run.grants < max_grants); // no livelock/starvation
            const cm = &vm.procs.items[collector].machine;
            try std.testing.expectEqual(ia.Status.halted, cm.status); // completed
            try std.testing.expectEqual(oracle, @as(i64, @bitCast(cm.result)) >> 4); // drop-net
            try std.testing.expect(checkPerPairOrder(vm.events.items)); // sacred order
            // QUIESCENCE: no proc left parked. A lost wakeup strands a process
            // forever, and nothing above would necessarily notice once the
            // collector itself had finished.
            for (vm.procs.items) |p| {
                try std.testing.expectEqual(ia.Status.halted, p.machine.status);
            }
        }
    }
}

// LAW gap-real-metrics-memory (DIVERGENCE 627): erlang:memory/0,1 reports
// TRUTHFUL measured bytes (processes = Σ tagged-word heap*8, atom = Σ name
// bytes, total = their sum), never a fabricated value (FM-OBS-1). Property-
// verified (values host-nondeterministic, like statistics/1): the SUM
// INVARIANT (total == processes + atom), NON-NEGATIVITY, MONOTONICITY (interning
// an atom raises `atom`; the proplist shape is {atom,int} tuples), and the
// FM-OBS-1 REJECTION (an unmodeled category → badarg, never a faked 0).
// Mutants: MUT-MEM-1 (total drops atom → sum invariant reds), MUT-MEM-2
// (memory(code) fabricates 0 → the badarg-rejection reds).
test "LAW gap-real-metrics-memory: erlang:memory/0,1 reports truthful measured bytes (sum invariant, monotone atom, unmodeled→badarg) — FM-OBS-1" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    var vm = try Vm.init(gpa, &atoms);
    defer vm.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    const p0 = try vm.spawn(idle, 0, null);

    const memAll = struct {
        fn go(v: *Vm, pid: Pid) !struct { total: i64, procs: i64, atom: i64 } {
            v.procs.items[pid].machine.pending = .{ .stat_memory = .all };
            try v.interpret(pid);
            const m = &v.procs.items[pid].machine;
            const pl = m.regs[0];
            // walk [{total,T},{processes,P},{atom,A}] — order-independent read.
            var total: i64 = -1;
            var procs: i64 = -1;
            var at: i64 = -1;
            var cur = pl;
            while (FinalTerms.kindOf(&m.ctx, cur) == .cons) {
                const pair = FinalTerms.listHead(&m.ctx, cur);
                try std.testing.expectEqual(@as(usize, 2), FinalTerms.tupleArity(&m.ctx, pair)); // {k,v} shape
                const key = FinalTerms.tupleElem(&m.ctx, pair, 0);
                const val = FinalTerms.smallValOf(FinalTerms.tupleElem(&m.ctx, pair, 1));
                const kn = m.ctx.atoms.nameOf(FinalTerms.atomIdxOf(key));
                if (std.mem.eql(u8, kn, "total")) total = val;
                if (std.mem.eql(u8, kn, "processes")) procs = val;
                if (std.mem.eql(u8, kn, "atom")) at = val;
                cur = FinalTerms.listTail(&m.ctx, cur);
            }
            return .{ .total = total, .procs = procs, .atom = at };
        }
    }.go;

    const r1 = try memAll(&vm, p0);
    // shape: all three present, non-negative.
    try std.testing.expect(r1.total >= 0 and r1.procs >= 0 and r1.atom >= 0);
    // SUM INVARIANT: total == processes + atom (MUT-MEM-1 reds).
    try std.testing.expectEqual(r1.total, r1.procs + r1.atom);
    // MONOTONE: interning fresh atoms raises `atom` (and total).
    _ = try atoms.intern("a_fresh_atom_for_the_memory_law_0123456789");
    _ = try atoms.intern("another_fresh_atom_1234567890_abcdefghij");
    const r2 = try memAll(&vm, p0);
    try std.testing.expect(r2.atom > r1.atom);
    try std.testing.expectEqual(r2.total, r2.procs + r2.atom); // still holds
    // single-type reads agree with the proplist.
    vm.procs.items[p0].machine.pending = .{ .stat_memory = .atom };
    try vm.interpret(p0);
    try std.testing.expectEqual(r2.atom, FinalTerms.smallValOf(vm.procs.items[p0].machine.regs[0]));

    // FM-OBS-1 REJECTION: an unmodeled category → badarg (never a faked value).
    const it_code = FinalTerms.atom(&vm.procs.items[p0].machine.ctx, try atoms.intern("code"));
    try std.testing.expectError(error.Badarg, procsys.memory_1(&vm.procs.items[p0].machine, &.{it_code})); // MUT-MEM-2 reds
}

// ── gap-priority-classes: run-queue weighting by process priority ────────────
//
// `gap-eep76-priority-flag` landed `process_flag(priority, Level)` — it stores
// the level and returns the old one — and said in its own comment that the
// scheduler does not weight run-queues by it yet. This closes that, and closes
// a divergence the flag created on the way in:
//
//   process_info(P, priority) returned a HARDCODED `normal`.
//
// That constant was honest when written ("the single-scheduler VM has no
// priority classes") and stopped being honest the moment a process could set
// `high` and read back `normal`. A constant is a truthful answer only while it
// is the only true one; after the flag existed it was a fabricated value, which
// is the FM-OBS-1 failure whichever direction it points.
//
// SEMANTIC DOMAIN: the schedulable set partitions into `max > high > normal >
// low`, and dispatch draws from the non-empty class of greatest priority. Within
// a class the pre-existing pick is untouched, so each engine's fairness
// guarantee survives one class at a time.
//
// STARVATION IS OTP'S SEMANTICS, not a defect: a perpetually-runnable `high`
// starves `normal`. The no-starvation laws quantify over a single class, which
// is the strongest statement that stays true under real priority scheduling.
//
// Mutants: MUT-PRIO-1 (process_info returns the hardcoded `normal` again → the
// round-trip arm reds), MUT-PRIO-2 (dispatch takes the LOWEST runnable class →
// the ordering arm reds), MUT-PRIO-3 (the seeded engine ignores the class filter
// → the ordering arm reds on the seeded engine while the oracle still passes,
// which is why both engines are driven).
test "LAW gap-priority-classes: process_info reports the REAL priority, dispatch draws from the highest runnable class, and within-class fairness is preserved" {
    const gpa = std.testing.allocator;
    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};
    // A process that stays RUNNABLE across slices. `idle` (a bare `wait`)
    // suspends on its first slice, which would make every dispatch assertion
    // below vacuous after one iteration — the workload has to keep the
    // scheduler with a real choice to make.
    const spin: ia.Program = &.{.{ .jump = .{ .to = 0 } }};

    // (1) ROUND-TRIP — set every level through the real flag BIF and read it
    //     back through process_info. A hardcoded constant fails on three of the
    //     four, and the `normal` case alone would not have caught it.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const p0 = try vm.spawn(idle, 0, null);
        for ([_][]const u8{ "low", "normal", "high", "max" }) |lvl| {
            const m = &vm.procs.items[p0].machine;
            const lvl_atom = FinalTerms.atom(&m.ctx, try atoms.intern(lvl));
            const prio_atom = FinalTerms.atom(&m.ctx, try atoms.intern("priority"));
            _ = try @import("bifs/procsys.zig").process_flag_2(m, &.{ prio_atom, lvl_atom });
            const got = try vm.procInfoValue(m, vm.procs.items[p0], p0, "priority");
            try std.testing.expectEqualStrings(lvl, atoms.nameOf(FinalTerms.atomIdxOf(got)));
        }
    }

    // (2) STRICT ORDER, OBSERVED BY EXECUTION — a `high` process and two
    //     `normal` ones all spin. Over many slices ONLY the high one may retire
    //     instructions; when it stops being schedulable the normals are
    //     released. Measuring retired work rather than re-deriving the pick is
    //     deliberate: a test that recomputes the selection asserts its own copy
    //     of the rule, not the scheduler's. (The first version of this arm did
    //     exactly that and "failed" on a scheduler that was behaving correctly.)
    //
    //     Driven on BOTH engines — the oracle and the seeded engine select
    //     within a class by different rules and each carries its own filter, so
    //     MUT-PRIO-3 (seeded engine ignores the class) survives a
    //     round-robin-only law.
    for ([_]Scheduler{ .round_robin, .{ .seeded = 0xC0FFEE } }) |sched| {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const hi = try vm.spawn(spin, 0, null);
        const n1 = try vm.spawn(spin, 0, null);
        const n2 = try vm.spawn(spin, 0, null);
        {
            const m = &vm.procs.items[hi].machine;
            const lvl_atom = FinalTerms.atom(&m.ctx, try atoms.intern("high"));
            const prio_atom = FinalTerms.atom(&m.ctx, try atoms.intern("priority"));
            _ = try @import("bifs/procsys.zig").process_flag_2(m, &.{ prio_atom, lvl_atom });
        }
        try std.testing.expectEqual(ia.ProcPriority.high, topRunnablePriority(&vm).?);

        // ONE drive of 16 slices, not 16 drives of one: `cursor` is LOCAL to
        // `drive`, so repeated single-slice calls restart round-robin at pid 0
        // every time and the rotation never happens. Bounded — a hang is a
        // failed law, never a stuck suite.
        try sched.drive(&vm, 1, 16);
        try std.testing.expect(vm.procs.items[hi].machine.instrs > 0); // it ran
        try std.testing.expectEqual(@as(u64, 0), vm.procs.items[n1].machine.instrs); // starved
        try std.testing.expectEqual(@as(u64, 0), vm.procs.items[n2].machine.instrs); // starved

        // RELEASE — the high process stops being schedulable, so the class
        // falls back and the normals run. Without this the arm would be
        // satisfied by a scheduler that had simply stopped.
        vm.procs.items[hi].machine.status = .suspended;
        try std.testing.expectEqual(ia.ProcPriority.normal, topRunnablePriority(&vm).?);
        try sched.drive(&vm, 1, 16);
        try std.testing.expect(vm.procs.items[n1].machine.instrs > 0);
        try std.testing.expect(vm.procs.items[n2].machine.instrs > 0);
    }

    // (3) WITHIN-CLASS FAIRNESS / INERTNESS — with everyone at the default
    //     priority the class filter admits the whole schedulable set, so the
    //     pick is the pre-slice one and BOTH processes make progress. This is
    //     the property that let the slice land under the existing trace and
    //     fairness laws: on a program that never sets a priority the filter is
    //     the identity.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const a = try vm.spawn(spin, 0, null);
        const b = try vm.spawn(spin, 0, null);
        try std.testing.expectEqual(ia.ProcPriority.normal, topRunnablePriority(&vm).?);
        try (Scheduler{ .round_robin = {} }).drive(&vm, 1, 16);
        try std.testing.expect(vm.procs.items[a].machine.instrs > 0);
        try std.testing.expect(vm.procs.items[b].machine.instrs > 0);
    }

    // (4) NOTHING SCHEDULABLE is an honest null, not a fabricated class.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const p = try vm.spawn(idle, 0, null);
        vm.procs.items[p].machine.status = .suspended;
        try std.testing.expectEqual(@as(?ia.ProcPriority, null), topRunnablePriority(&vm));
    }
}

// ── gap-os-signals-delivery: `handle` → erl_signal_server ────────────────────
//
// `os:set_signal(Sig, handle)` was accepted by the grammar and did NOTHING —
// `gap-os-signals-sigaction` landed real `sigaction` for `ignore`/`default` and
// disclosed the `handle` pipeline as the remainder. This closes it.
//
// THE MESSAGE SHAPE IS MEASURED, NOT GUESSED. Probed against pinned OTP-30 by
// removing the default handler, adding one that forwards to the test process,
// and raising SIGUSR1:
//
//     {received,{sig_event,sigusr1}}
//
// The event is the BARE signal-name atom. A reading of the docs would plausibly
// have produced `{notify, Sig}` or some other tuple, which is precisely what
// MUT-SIGD-1 plants — the value probe is the only reason the shape is right.
// (The first probe attempt also failed informatively: `register(erl_signal_server,
// self())` is badarg because the real runtime already owns that name, and a
// second attempt got a CRASH DUMP because OTP's default handler treats SIGUSR1
// that way. Both are facts about OTP that a doc reading would not have given.)
//
// REACTOR DISCIPLINE: the handler does one relaxed atomic OR and nothing else —
// no allocation, no lock, no VM access, because a signal handler may call only
// async-signal-safe operations. Every real step happens on the scheduler tick.
//
// Mutants: MUT-SIGD-1 (deliver `{notify, Sig}` instead of the bare atom → the
// shape arm reds, and this is the shape a non-probed implementation would have
// chosen), MUT-SIGD-2 (the handler does not record the signal → nothing is ever
// delivered), MUT-SIGD-3 (deliver regardless of registration → a crash where
// OTP silently drops).
test "LAW gap-os-signals-delivery: a handled signal reaches erl_signal_server as the BARE signal atom (OTP-30 measured shape), and is dropped when nobody is registered" {
    const gpa = std.testing.allocator;
    const P = std.posix;
    // net-zero: restore whatever disposition this process had.
    var saved: P.Sigaction = undefined;
    P.sigaction(P.SIG.USR1, null, &saved);
    defer P.sigaction(P.SIG.USR1, &saved, null);
    _ = os_bif.drainPendingSignals(); // start from a clean pending set

    var atoms = AtomTable.init(gpa);
    defer atoms.deinit();
    const idle: ia.Program = &.{.{ .wait = .{ .to = 0 } }};

    // (1) DELIVERY — a registered erl_signal_server receives the bare atom.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const srv = try vm.spawn(idle, 0, null);
        try vm.registry.register(try atoms.intern("erl_signal_server"), srv, true);

        try os_bif.applySignalDisposition("sigusr1", "handle");
        try P.raise(P.SIG.USR1); // survived ⇒ the handler ran instead of the default
        try vm.pollPendingSignals();

        const sq = &vm.procs.items[srv].sigq;
        try std.testing.expectEqual(@as(usize, 1), sq.items.len);
        const msg = sq.items[0].sig.message;
        // THE SHAPE, byte-checked against the OTP-30 observation: a bare atom
        // named `sigusr1` — not a tuple, not `{notify, _}`.
        try std.testing.expect(FinalTerms.repIsAtom(msg));
        try std.testing.expectEqualStrings(
            "sigusr1",
            atoms.nameOf(FinalTerms.atomIdxOf(msg)),
        );
    }

    // (2) DRAINED — the pending set is consumed, so one raise is one delivery
    //     and a second poll delivers nothing.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const srv = try vm.spawn(idle, 0, null);
        try vm.registry.register(try atoms.intern("erl_signal_server"), srv, true);
        try os_bif.applySignalDisposition("sigusr1", "handle");
        try P.raise(P.SIG.USR1);
        try vm.pollPendingSignals();
        try vm.pollPendingSignals(); // nothing left
        try std.testing.expectEqual(@as(usize, 1), vm.procs.items[srv].sigq.items.len);
    }

    // (3) NOBODY REGISTERED ⇒ DROPPED, not an error. A signal can arrive before
    //     erl_signal_server exists or after it dies, and OTP does not fault the
    //     runtime for that. MUT-SIGD-3 dies here.
    {
        var vm = try Vm.init(gpa, &atoms);
        defer vm.deinit();
        const bystander = try vm.spawn(idle, 0, null);
        try os_bif.applySignalDisposition("sigusr1", "handle");
        try P.raise(P.SIG.USR1);
        try vm.pollPendingSignals(); // must not error...
        // ...and must not deliver to SOMEBODY ELSE. "It did not crash" is not
        // the property: a fallback to an arbitrary pid also does not crash, and
        // MUT-SIGD-3 SURVIVED the first version of this arm for exactly that
        // reason. The bystander's queue being empty is the real law.
        try std.testing.expectEqual(@as(usize, 0), vm.procs.items[bystander].sigq.items.len);
        _ = os_bif.drainPendingSignals();
    }

    // (4) `ignore` STILL IGNORES — the new handler must not have replaced the
    //     disposition machinery it sits beside. Raising under `ignore` records
    //     nothing, so a later poll has nothing to deliver.
    {
        try os_bif.applySignalDisposition("sigusr1", "ignore");
        _ = os_bif.drainPendingSignals();
        try P.raise(P.SIG.USR1);
        try std.testing.expectEqual(@as(u32, 0), os_bif.drainPendingSignals());
    }
}
